(function(){"use strict";var w=window.ScripturaJosephusTexts||(window.ScripturaJosephusTexts={});var a=w.antiguidades||(w.antiguidades={});a[5]={"book":5,"title":"Τάδε ἔνεστιν ἐν τῇ πέμπτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ὡς Ἰησοῦς ὁ στρατηγὸς τῶν Ἑβραίων πολεμήσας πρὸς Χαναναίους καὶ κρατήσας αὐτῶν τοὺς μὲν διέφθειρε, τὴν δὲ γῆν κατακληρουχήσας διένειμε ταῖς φυλαῖς.\n\nβ. ὡς ἀποθανόντος τοῦ στρατηγοῦ παραβαίνοντες οἱ Ἰσραηλῖται τοὺς πατρίους νόμους μεγάλων ἐπειράθησαν συμφορῶν, καὶ στασιασάντων ἡ Βενιαμὶς διεφθάρη φυλὴ χωρὶς ἀνδρῶν ἑξακοσίων.\n\nγ. πῶς μετὰ ταύτην τὴν κακοπραγίαν ἀσεβήσαντας αὐτοὺς ὁ θεὸς Ἀσσυρίοις ἐδούλωσεν.\n\nδ. ἡ διὰ Κενίζου τοῦ Ἀθνιήλου παιδὸς αὐτοῖς ἐλευθερία γενομένη ἄρξαντος ἔτη τεσσαράκοντα λεγομένου δὲ παρά τε Ἕλλησι καὶ Φοίνιξι κριτοῦ.\n\nε. ὅτι πάλιν ὁ λαὸς ἡμῶν ἐδούλευσε Μωαβίταις ὀκτωκαίδεκα ἔτη καὶ ὑπό τινος Ἰούδου τῆς δουλείας ἀπηλλάγη τὴν ἀρχὴν ἐπ' ἔτη κατασχόντος ὀγδοήκοντα.\n\nϛ. ὡς Χαναναίων αὐτοὺς καταδουλωσαμένων ἐπ' ἔτη εἴκοσιν ἠλευθερώθησαν ὑπὸ Βαράκου καὶ Δεβώρας, οἳ ἦρξαν αὐτῶν ἐπ' ἔτη τεσσαράκοντα.\n\nζ. ὅτι πολεμήσαντες Ἀμαληκῖται τοῖς Ἰσραηλίταις ἐνίκησάν τε καὶ τὴν χώραν ἐκάκωσαν ἔτη ἑπτά.\n\nη. ὡς Γεδεὼν αὐτοὺς ἠλευθέρωσεν ἀπὸ Ἀμαληκιτῶν καὶ ἦρξε τοῦ πλήθους ἐπὶ ἔτη τεσσαράκοντα.\n\nθ. ὅτι μετ' αὐτὸν πολλοὶ γενόμενοι διάδοχοι τοῖς πέριξ ἔθνεσιν ἐπολέμησαν ἱκανῷ χρόνῳ.\n\nι. περὶ τῆς Σαμψῶνος ἀνδρείας καὶ ὅσων κακῶν αἴτιος Παλαιστίνοις ἐγένετο.\n\nια. ὡς οἱ υἱοὶ Ἠλῖ τοῦ ἱερέως ἐσφάγησαν ἐν τῇ πρὸς Παλαιστίνους μάχῃ.\n\nιβ. ὡς ὁ πατὴρ αὐτῶν ἀκούσας τὴν συμφορὰν βαλὼν ἑαυτὸν ἀπὸ τοῦ θρόνου ἀπέθανεν.\n\nιγ. ὡς νικήσαντες ἐν τούτῳ τῷ πολέμῳ τοὺς Ἑβραίους οἱ Παλαιστῖνοι καὶ τὴν κιβωτὸν αὐτῶν αἰχμάλωτον ἔλαβον.\n\nιδ. ὡς οἱ ἀπὸ Κενίζου ἄρξαντες πάντες κριταὶ ἐκλήθησαν.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν τετρακοσίων ἑβδομήκοντα."},"chapters":{"1":[{"number":1,"text":"Μωυσέος δὲ τὸν προειρημένον τρόπον ἐξ ἀνθρώπων ἀπογεγονότος Ἰησοῦς ἁπάντων ἤδη τῶν ἐπʼ αὐτῷ νενομισμένων τέλος ἐχόντων καὶ τοῦ πένθους λελωφηκότος παρήγγειλεν ἐπὶ στρατείαν ἕτοιμον εἶναι τὸ πλῆθος,"},{"number":2,"text":"πέμπει τε κατασκόπους εἰς Ἱεριχοῦντα τήν τε δύναμιν αὐτῶν καὶ τίνα διάνοιαν ἔχουσιν αὐτοὶ γνωσομένους, αὐτὸς δὲ ἐξήταζε τὸν στρατὸν ὡς κατὰ καιρὸν διαβησόμενος τὸν Ἰόρδανον."},{"number":3,"text":"ἀνακαλεσάμενος δὲ τοὺς τῆς Ῥουβηλίδος φυλῆς ἄρχοντας καὶ τοὺς τῆς Γάδιδος καὶ Μανασσήτιδος προεστῶτας, ἐξ ἡμισείας γὰρ καὶ τῇδε τῇ φυλῇ τὴν Ἀμορίαν κατοικεῖν ἐπετέτραπτο τῆς Χαναναίων γῆς ἕβδομον οὖσαν μέρος, ὑπεμίμνησκεν ἃ ὑπέσχοντο Μωυσεῖ,"},{"number":4,"text":"καὶ παρεκάλει χαριζομένους τῇ τε ἐκείνου προνοίᾳ μηδʼ ὅτε ἀπέθνησκε περὶ αὐτοὺς καμούσῃ τῷ τε κοινῇ συμφέροντι παρέχειν αὑτοὺς εἰς τὰ παραγγελλόμενα προθύμους. τῶν δʼ ἑπομένων ὁπλίταις πεντακισμυρίοις ἀπὸ τῆς Ἀβέλης ἐπὶ τὸν Ἰόρδανον ἐξῄει σταδίους ἑξήκοντα."},{"number":5,"text":"Καὶ στρατοπεδεύσαντος εὐθὺς οἱ κατάσκοποι παρῆσαν μηδὲν ἀγνοήσαντες τῶν παρὰ τοῖς Χαναναίοις· ἐλθόντες γὰρ τὸ πρῶτον ἅπασαν ἐπʼ ἀδείας αὐτῶν τὴν πόλιν κατενόησαν, τῶν τε τειχῶν ὅσα καρτερὰ καὶ ὅσα μὴ τοῦτον ἔχει τὸν τρόπον αὐτοῖς ἀσφαλῶς καὶ τῶν πυλίδων αἳ πρὸς εἴσοδον τῷ στρατοπέδῳ διʼ ἀσθένειαν συνέφερον."},{"number":6,"text":"ἠμέλουν δὲ θεωμένων οἱ ἐντυγχάνοντες κατὰ ἱστορίαν ξένοις προσήκουσαν ἀκριβῶς ἕκαστα πολυπραγμονεῖν τῶν ἐν τῇ πόλει νομίζοντες, ἀλλʼ οὐχὶ διανοίᾳ πολεμίων."},{"number":7,"text":"ὡς δὲ γενομένης ὀψίας ὑποχωροῦσιν εἴς τι καταγώγιον τοῦ τείχους πλησίον, εἰς ὃ καὶ προήχθησαν δειπνοποιησάμενοι καὶ περὶ ἀπαλλαγῆς αὐτοῖς τὸ λοιπὸν ἡ φροντὶς ἦν,"},{"number":8,"text":"μηνύονται τῷ βασιλεῖ περὶ δεῖπνον ὄντι κατασκεψόμενοί τινες τὴν πόλιν ἀπὸ τοῦ τῶν Ἑβραίων στρατοπέδου παρεῖναι καὶ ὄντες ἐν τῷ τῆς Ῥαάβης καταγωγίῳ μετὰ πολλῆς τῆς τοῦ λανθάνειν προνοίας ὑπάρχειν. ὁ δʼ εὐθὺς πέμψας πρὸς αὐτοὺς ἐκέλευσεν ἀγαγεῖν συλλαβόντας, ἵνα βασανίσας μάθῃ, τί καὶ βουλόμενοι παρεῖεν."},{"number":9,"text":"ὡς δʼ ἔγνω τὴν ἔφοδον αὐτῶν ἡ Ῥαάβη, λίνου γὰρ ἀγκαλίδας ἐπὶ τοῦ τείχους ἔψυχε, τοὺς μὲν κατασκόπους εἰς ταύτας ἀποκρύπτει, τοῖς δὲ πεμφθεῖσιν ὑπὸ τοῦ βασιλέως ἔλεγεν, ὡς ξένοι τινὲς εἶεν ἀγνῶτες ὀλίγῳ πρότερον ἢ δῦναι τὸν ἥλιον παρʼ αὐτῇ δειπνήσαντες ἀπαλλαγεῖεν, οὓς εἰ φοβεροὶ τῇ πόλει δοκοῦσιν, ἢ κίνδυνον τῷ βασιλεῖ φέροντες ἧκον, ἀπόνως εἶναι λαβεῖν διωχθέντας."},{"number":10,"text":"οἱ δὲ τῆς γυναικὸς οὕτως αὐτοὺς ὑπελθούσης οὐδένα ὑπονοήσαντες δόλον ἀπῆλθον οὐδʼ ἐρευνήσαντες τὸ καταγώγιον. ἐπεὶ δʼ ὁρμήσαντες καθʼ ἃς ἐνόμιζον αὐτοὺς μάλιστα τῶν ὁδῶν ἀπέρχεσθαι καὶ κατὰ τὰς εἰς τὸν ποταμὸν φερούσας οὐδενὶ γνωρίσματι περιετύγχανον, παύονται τοῦ πονεῖν."},{"number":11,"text":"τοῦ δὲ θορύβου σταλέντος ἡ Ῥαάβη καταγαγοῦσα τοὺς ἄνδρας καὶ τὸν κίνδυνον εἰποῦσα, ὃν ὑπὲρ τῆς αὐτῶν ὑπέλθοι σωτηρίας, ἁλοῦσαν γὰρ ἀποκρύπτουσαν αὐτοὺς οὐκ ἂν διαφυγεῖν τὴν ἐκ τοῦ βασιλέως τιμωρίαν, ἀλλὰ πανοικὶ αὐτὴν ἀπολέσθαι κακῶς,"},{"number":12,"text":"παρακαλέσασα διὰ μνήμης ἔχειν, ὅταν ἐγκρατεῖς τῆς Χαναναίων γῆς καταστάντες ἀμοιβὴν ἐκτῖσαι δύνωνται τῆς ἄρτι σωτηρίας, χωρεῖν ἐκέλευεν ἐπὶ τὰ οἰκεῖα ὀμόσαντας ἦ μὴν σώσειν αὐτὴν καὶ τὰ αὐτῆς, ὅταν τὴν πόλιν ἑλόντες φθείρωσι πάντας τοὺς ἐν αὐτῇ κατὰ ψήφισμα τὸ παρʼ αὐτοῖς γενόμενον· ταῦτα γὰρ εἰδέναι σημείοις τοῖς ἐκ τοῦ θεοῦ διδαχθεῖσαν."},{"number":13,"text":"οἱ δὲ καὶ τῶν παρόντων αὐτῇ χάριν ἔχειν ὡμολόγουν καὶ περὶ τῶν αὖθις ὤμνυον ἔργῳ τὴν ἀμοιβὴν ἀποδώσειν· ἡνίκα δʼ ἂν αἴσθηται μελλούσης ἁλίσκεσθαι τῆς πόλεως, συνεβούλευον κτῆσίν τε τὴν αὐτῆς καὶ τοὺς οἰκείους ἅπαντας εἰς τὸ καταγώγιον ἀποθεμένην ἐγκαθεῖρξαι πρὸ τῶν θυρῶν ἀνατείνασαν φοινικίδας, ὅπως εἰδὼς τὴν οἰκίαν ὁ στρατηγὸς φυλάττηται κακῶς ποιεῖν·"},{"number":14,"text":"μηνύσομεν γὰρ αὐτῷ, ἔφασαν, διὰ τὸ σὸν σώζεσθαι πρόθυμον. εἰ δέ τις ἐν τῇ μάχῃ πέσοι τῶν σῶν, σύ τε οὐκ ἂν ἡμῖν ἐπενέγκοις αἰτίαν καὶ τὸν θεὸν ὃν ὀμωμόκαμεν παραιτούμεθα μηδὲν ὡς ἐπὶ παραβαίνουσι τοὺς ὅρκους δυσχερᾶναι."},{"number":15,"text":"καὶ οἱ μὲν ταῦτα συνθέμενοι ἐχώρουν διὰ τοῦ τείχους καθιμήσαντες ἑαυτούς, καὶ διασωθέντες πρὸς τοὺς οἰκείους ἐδήλωσαν ὅσα πράξαντες ἐπὶ τῆς πόλεως ἧκον· Ἰησοῦς δὲ τῷ ἀρχιερεῖ Ἐλεαζάρῳ καὶ τῇ γερουσίᾳ φράζει τὰ τοῖς σκοποῖς ὁμοθέντα πρὸς τὴν Ῥαάβην· οἱ δʼ ἐπεκύρουν τὸν ὅρκον."},{"number":16,"text":"Δεδιότος δὲ τοῦ στρατοῦ τὴν διάβασιν, μέγας γὰρ ἦν ὁ ποταμὸς τῷ ῥεύματι καὶ οὔτε γεφύραις πορευτός, οὐ γὰρ ἔζευκτο τὸ πρότερον, βουλομένους τε γεφυροῦν οὐχ ἕξειν σχολὴν παρὰ τῶν πολεμίων ὑπελάμβανον πορθμείων τε μὴ τυγχανόντων, διαβατὸν αὐτοῖς ὁ θεὸς ἐπαγγέλλεται ποιήσειν τὸν ποταμὸν μειώσας αὐτοῦ τὸ πλῆθος."},{"number":17,"text":"καὶ δύο ἐπισχὼν ἡμέρας Ἰησοῦς διεβίβαζε τὸν στρατὸν καὶ τὴν πληθὺν ἅπασαν τοιούτῳ τρόπῳ· προῄεσαν μὲν οἱ ἱερεῖς τὴν κιβωτὸν ἔχοντες, ἔπειτα οἱ Λευῖται τήν τε σκηνὴν καὶ τὰ πρὸς ὑπηρεσίαν ταῖς θυσίαις σκεύη κομίζοντες, εἵποντο δὲ τοῖς Λευίταις κατὰ φυλὰς ὁ πᾶς ὅμιλος μέσους ἔχων παῖδας καὶ γυναῖκας, δεδιὼς περὶ αὐτῶν μὴ βιασθεῖεν ὑπὸ τοῦ ῥεύματος."},{"number":18,"text":"ὡς δὲ τοῖς ἱερεῦσι πρώτοις ἐμβᾶσι πορευτὸς ἔδοξεν ὁ ποταμός, τοῦ μὲν βάθους ἐπεσχημένου, τοῦ δὲ κάχληκος τῷ μὴ πολὺν εἶναι μηδʼ ὀξὺν τὸν ῥοῦν ὥσθʼ ὑποφέρειν αὐτὸν τῇ βίᾳ ἀντʼ ἐδάφους κειμένου, πάντες ἤδη θαρσαλέως ἐπεραιοῦντο τὸν ποταμόν, οἷον αὐτὸν ὁ θεὸς προεῖπε ποιήσειν τοιοῦτον κατανοοῦντες."},{"number":19,"text":"ἔστησαν δὲ ἐν μέσῳ οἱ ἱερεῖς ἕως οὗ διαβαίη τὸ πλῆθος καὶ τἀσφαλοῦς ἁψάμενον τύχοι. πάντων δὲ διαβάντων ἐξῄεσαν οἱ ἱερεῖς ἐλεύθερον ἀφέντες ἤδη τὸ ῥεῦμα χωρεῖν κατὰ τὴν συνήθειαν. καὶ ὁ μὲν ποταμὸς εὐθὺς ἐκβάντων αὐτὸν τῶν Ἑβραίων ηὔξετο καὶ τὸ ἴδιον ἀπελάμβανε μέγεθος."},{"number":20,"text":"Οἱ δὲ πεντήκοντα προελθόντες στάδια βάλλονται στρατόπεδον ἀπὸ δέκα σταδίων τῆς Ἱεριχοῦντος, Ἰησοῦς τε τόν τε βωμὸν ἐκ τῶν λίθων ὧν ἕκαστος ἀνείλετο τῶν φυλάρχων ἐκ τοῦ βυθοῦ τοῦ προφήτου κελεύσαντος ἱδρυσάμενος τεκμήριον γενησόμενον τῆς ἀνακοπῆς τοῦ ῥεύματος ἔθυεν ἐπʼ αὐτοῦ τῷ θεῷ, καὶ τὴν φάσκα ἑώρταζον ἐν ἐκείνῳ τῷ χωρίῳ,"},{"number":21,"text":"πάντων ὧν αὐτοῖς πρότερον συνέβαινε σπανίζειν τότε ῥᾳδίως εὐποροῦντες· τόν τε γὰρ σῖτον ἀκμάζοντα ἤδη τῶν Χαναναίων ἐθέριζον καὶ τὰ λοιπὰ λείαν ἦγον· τότε γὰρ αὐτοὺς καὶ ἡ τῆς μάννας ἐπελελοίπει τροφὴ χρησαμένους ἐπὶ ἔτη τεσσαράκοντα."},{"number":22,"text":"Ὡς δὲ ταῦτα ποιούντων τῶν Ἰσραηλιτῶν οὐκ ἐπεξῄεσαν οἱ Χαναναῖοι τειχήρεις δʼ ἡσύχαζον, πολιορκεῖν αὐτοὺς Ἰησοῦς ἔγνω. καὶ τῇ πρώτῃ τῆς ἑορτῆς ἡμέρᾳ τὴν κιβωτὸν οἱ ἱερεῖς φέροντες, περὶ δʼ αὐτὴν ἐν κύκλῳ μέρος τι τῶν ὁπλιτῶν φυλάττον ἦν,"},{"number":23,"text":"οἳ καὶ προῄεσαν ἑπτὰ κέρασιν αὐτῶν σαλπίζοντες παρεκάλουν τὸν στρατὸν εἰς ἀλκὴν, περιώδευόν τε τὸ τεῖχος ἑπομένης τῆς γερουσίας, καὶ σαλπισάντων μόνον τῶν ἱερέων, τούτου γὰρ οὐδὲν ἐποίησαν περισσότερον, ἀνέζευξαν εἰς τὸ στρατόπεδον."},{"number":24,"text":"καὶ τοῦτο ἐπὶ ἡμέρας ἓξ ποιησάντων τῇ ἑβδόμῃ τὸ ὁπλιτικὸν Ἰησοῦς συναγαγὼν καὶ τὸν λαὸν ἅπαντα τὴν ἅλωσιν αὐτοῖς τῆς πόλεως εὐηγγελίζετο, ὡς κατʼ ἐκείνην τὴν ἡμέραν αὐτοῖς τοῦ θεοῦ ταύτην παρέξοντος αὐτομάτως καὶ δίχα τοῦ πόνου τοῦ σφετέρου τῶν τειχῶν κατενεχθησομένων."},{"number":25,"text":"κτείνειν μέντοι πάνθʼ ὁντινοῦν εἰ λάβοιεν παρεκελεύετο καὶ μήτε κάμνοντας ἀποστῆναι τοῦ φόνου τῶν πολεμίων, μήτʼ ἐλέῳ παραχωρήσαντας μήτε περὶ ἁρπαγὴν γινομένους περιορᾶν φεύγοντας τοὺς ἐχθρούς·"},{"number":26,"text":"ἀλλὰ τὰ μὲν ζῷα πάντα διαφθείρειν μηδὲν αὐτοὺς εἰς ἰδίαν ὠφέλειαν λαμβάνοντας, ὅσος δʼ ἂν ἄργυρος ᾖ καὶ χρυσός, ταῦτα ἐκέλευσε συγκομίζοντας ἀπαρχὴν ἐξαίρετον τῶν κατωρθωμένων τῷ θεῷ τηρεῖν ἐκ τῆς πρῶτον ἁλισκομένης πόλεως εἰληφότας· σώζειν δὲ μόνην Ῥαάβην καὶ τὴν γενεὰν αὐτῆς διὰ τοὺς γενομένους πρὸς αὐτὴν τοῖς κατασκόποις ὅρκους."},{"number":27,"text":"Ταῦτʼ εἰπὼν καὶ διατάξας τὸν στρατὸν προσήγαγεν ἐπὶ τὴν πόλιν· περιῄεσαν δὲ πάλιν τὴν πόλιν ἡγουμένης τῆς κιβωτοῦ καὶ τῶν ἱερέων τοῖς κέρασιν ἐξοτρυνόντων τὴν δύναμιν πρὸς τὸ ἔργον. καὶ περιελθόντων ἑπτάκις καὶ πρὸς ὀλίγον ἠρεμησάντων κατέπεσε τὸ τεῖχος μήτε μηχανῆς μήτε ἄλλης βίας αὐτῷ προσενεχθείσης ὑπὸ τῶν Ἑβραίων."},{"number":28,"text":"Οἱ δʼ εἰσελθόντες εἰς Ἱεριχοῦντα πάντας ἔκτεινον, τῶν ἐν αὐτῇ πρὸς τὴν παράδοξον τοῦ τείχους ἀνατροπὴν καταπεπληγότων καὶ τοῦ φρονήματος αὐτοῖς πρὸς ἄμυναν ἀχρείου γεγονότος· ἀνῃροῦντο δʼ οὖν ἐν ταῖς ὁδοῖς ἀποσφαττόμενοι καὶ ἐν ταῖς οἰκίαις ἐπικαταλαμβανόμενοι."},{"number":29,"text":"παρῃτεῖτο δʼ οὐδὲν αὐτούς, ἀλλὰ πάντες ἀπώλλυντο ἄχρι γυναικῶν καὶ παιδίων, καὶ νεκρῶν ἡ πόλις ἦν ἀνάπλεως καὶ διέφυγεν οὐδέν. τὴν δὲ πόλιν ἐνέπρησαν ἅπασαν καὶ τὴν χώραν."},{"number":30,"text":"καὶ τὴν Ῥαάβην σὺν τοῖς οἰκείοις εἰς τὸ καταγώγιον συμφυγοῦσαν ἔσωσαν οἱ κατάσκοποι, καὶ πρὸς αὐτὸν Ἰησοῦς ἀχθείσῃ χάριν ἔχειν ὡμολόγει τῆς σωτηρίας τῶν κατασκόπων καὶ μὴν τῆς εὐεργεσίας ταύτης ἔλεγεν ἐν ταῖς ἀμοιβαῖς οὐχ ἥττονα φανήσεσθαι, δωρεῖται δʼ αὐτὴν εὐθὺς ἀγροῖς καὶ διὰ τιμῆς εἶχε τῆς πάσης."},{"number":31,"text":"Τῆς δὲ πόλεως εἰ καί τι παρέλθοι τὸ πῦρ κατέσκαπτε καὶ κατὰ τῶν οἰκησόντων, εἴ τις πορθηθεῖσαν ἀνεγείρειν ἐθελήσειεν, ἀρὰς ἔθετο, ὅπως θεμελίους μὲν τειχῶν βαλόμενος στερηθῇ τοῦ πρώτου παιδός, τελειώσας δὲ τὸν νεώτατον τῶν παίδων ἀποβάλῃ. τῆς δὲ ἀρᾶς τὸ θεῖον οὐκ ἠμέλησεν, ἀλλʼ ἐν τοῖς ὑστέροις ἀπαγγελοῦμεν τὸ περὶ αὐτὴν πάθος γενόμενον."},{"number":32,"text":"Ἄπειρον δέ τι πλῆθος ἐκ τῆς ἁλώσεως συναθροίζεται ἀργύρου τε καὶ χρυσοῦ καὶ προσέτι χαλκοῦ μηδενὸς παραβάντος τὰ δεδογμένα μηδʼ εἰς ἰδίαν ὠφέλειαν αὐτὰ διαρπασαμένων, ἀλλʼ ἀποσχομένων ὡς ἤδη τῷ θεῷ καθιερωμένων. καὶ ταῦτα μὲν Ἰησοῦς τοῖς ἱερεῦσιν εἰς τοὺς θησαυροὺς παραδίδωσι καταθέσθαι. καὶ Ἱεριχοῦς μὲν τοῦτον ἀπώλετο τὸν τρόπον."},{"number":33,"text":"Ἄχαρος δέ τις Ζεβεδαίου παῖς ὢν ἐκ τῆς Ἰούδα φυλῆς εὑρὼν χλαμύδα βασίλειον ἐκ χρυσοῦ μὲν πᾶσαν ὑφασμένην, μᾶζαν δὲ χρυσοῦ σταθμὸν ἕλκουσαν σίκλων διακοσίων καὶ δεινὸν ἡγησάμενος, εἰ ὃ κινδυνεύσας ηὕρατο κέρδος, τοῦτο τῆς ἰδίας χρείας ἀφελόμενος δοῦναι φέρων τῷ θεῷ καὶ μὴ δεομένῳ, ὄρυγμα βαθὺ ποιήσας ἐν τῇ αὐτοῦ σκηνῇ κατώρυξεν εἰς τοῦτο, λήσειν νομίζων ὡς τοὺς συστρατιώτας οὕτως καὶ τὸν θεόν."},{"number":34,"text":"Ἐκλήθη δὲ ὁ τόπος ἐν ᾧ στρατόπεδον ἐβάλετο Ἰησοῦς Γάλγαλα· σημαίνει δὲ τοῦτο ἐλευθέριον ὄνομα· διαβάντες γὰρ τὸν ποταμὸν ἐλευθέρους ἑαυτοὺς ἤδη ἀπό τε τῶν Αἰγυπτίων καὶ τῆς ἐν τῇ ἐρήμῳ ταλαιπωρίας ἐγίνωσκον."},{"number":35,"text":"Μετὰ δʼ ὀλίγας ἡμέρας τῆς Ἱεριχοῦντος συμφορᾶς πέμπει τρισχιλίους ὁπλίτας Ἰησοῦς εἰς Ναϊὰν πόλιν ὑπὲρ τῆς Ἱεριχοῦντος κειμένην αἱρήσοντας, οἳ συμβαλόντων αὐτοῖς τῶν Ναϊητῶν τραπέντες ἀποβάλλουσιν ἄνδρας ἓξ καὶ τριάκοντα."},{"number":36,"text":"τοῦτʼ ἀγγελθὲν τοῖς Ἰσραηλίταις λύπην τε μεγάλην καὶ δεινὴν ἐποίησεν ἀθυμίαν οὐ κατὰ τὸ οἰκεῖον τῶν ἀπολωλότων, καίτοι γε πάντων ἀνδρῶν ἀγαθῶν καὶ σπουδῆς ἀξίων διεφθαρμένων, ἀλλὰ κατὰ ἀπόγνωσιν·"},{"number":37,"text":"πιστεύοντες γὰρ ἤδη τῆς γῆς ἐγκρατεῖς εἶναι καὶ σῶον ἕξειν ἐν ταῖς μάχαις τὸν στρατὸν οὕτως τοῦ θεοῦ προϋπεσχημένου, τεθαρρηκότας παραδόξως ἑώρων τοὺς πολεμίους· καὶ σάκκους ἐπενδύντες ταῖς στολαῖς διʼ ὅλης ἡμέρας ἐν δακρύοις ἦσαν καὶ πένθει τροφῆς οὐδεμίαν ἐπιζήτησιν ποιούμενοι, μειζόνως δὲ τὸ συμβεβηκὸς εἶχον ἀχθόμενοι."},{"number":38,"text":"Βλέπων δὲ οὕτως ὁ Ἰησοῦς τήν τε στρατιὰν καταπεπληγυῖαν καὶ περὶ τῶν ὅλων πονηρὰν ἤδη τὴν ἐλπίδα λαμβάνουσαν παρρησίαν λαμβάνει πρὸς τὸν θεόν·"},{"number":39,"text":"ἡμεῖς γὰρ εἶπεν οὐχ ὑπʼ αὐθαδείας προήχθημεν ὥστε ταύτην ὑπάγεσθαι τοῖς ὅπλοις τὴν γῆν, ἀλλὰ Μωυσέος τοῦ σοῦ δούλου πρὸς τοῦθʼ ἡμᾶς ἐξεγείραντος, ᾧ διὰ πολλῶν τεκμηρίων ἐπηγγέλλου κτήσασθαι παρέξειν ἡμῖν τήνδε τὴν γῆν καὶ τὸν στρατὸν ἡμῶν ἀεὶ τῶν πολεμίων ποιήσειν τοῖς ὅπλοις κρείττονα."},{"number":40,"text":"τινὰ μὲν οὖν κατὰ τὰς ὑποσχέσεις ἡμῖν ἀπήντησε τὰς σάς, νῦν δὲ παρὰ δόξαν ἐπταικότες καὶ τῆς δυνάμεώς τινας ἀποβαλόντες ἐπὶ τούτοις ὡς οὐ βεβαίων τῶν παρὰ σοῦ καὶ ὧν προεῖπε Μωυσῆς ἀχθόμεθα καὶ χεῖρον ἡ τῶν μελλόντων ἐλπὶς ἡμᾶς ἀνιᾷ τῇ πρώτῃ πείρᾳ τοιαύτῃ συντυχόντας."},{"number":41,"text":"ἀλλὰ σύ, δέσποτα, δύναμις γάρ σοι τούτων ἴασιν εὑρεῖν, τό τε παρὸν ἡμῶν λυπηρὸν νίκην παρασχόμενος καὶ τὸ περὶ τῶν αὖθις δύσελπι διακείμενον οὕτως τῆς διανοίας ἔξελε."},{"number":42,"text":"Ταῦτα μὲν Ἰησοῦς ἐπὶ στόμα πεσὼν ἠρώτα τὸν θεόν· χρηματίσαντος δὲ ἀνίστασθαι τοῦ θεοῦ καὶ καθαίρειν τὸν στρατὸν μιάσματος ἐν αὐτῷ γεγονότος κλοπῆς τε τῶν καθιερωμένων αὐτῷ χρημάτων τετολμημένης, διὰ γὰρ ταῦτα τὴν νῦν αὐτοῖς ἧτταν συμπεσεῖν, ἀναζητηθέντος δὲ τοῦ δράσαντος καὶ κολασθέντος νίκην αὐτοῖς ἀεὶ πορίζεσθαι τῶν πολεμίων, φράζει ταῦτα πρὸς τὸν λαὸν Ἰησοῦς,"},{"number":43,"text":"καὶ καλέσας Ἐλεάζαρον τὸν ἀρχιερέα καὶ τοὺς ἐν τέλει κατὰ φυλὴν ἐκλήρου. τούτου δὲ τὸ τετολμημένον ἐκ τῆς Ἰούδα φυλῆς δηλοῦντος κατὰ φατρίας πάλιν ταύτης προτίθησι τὸν κλῆρον. τὸ δʼ ἀληθὲς τοῦ κακουργήματος περὶ τὴν Ἀχάρου συγγένειαν ηὑρίσκετο."},{"number":44,"text":"κατʼ ἄνδρα δὲ τῆς ἐξετάσεως γινομένης λαμβάνουσι τὸν Ἄχαρον· ὁ δʼ οὐκ ἔχων ἔξαρνος εἶναι τοῦ θεοῦ δεινῶς αὐτὸν ἐκπεριελθόντος ὡμολόγει τε τὴν κλοπὴν καὶ τὰ φώρια παρῆγεν εἰς μέσον. καὶ οὗτος μὲν εὐθὺς ἀναιρεθεὶς ἐν νυκτὶ ταφῆς ἀτίμου καὶ καταδίκῳ πρεπούσης τυγχάνει."},{"number":45,"text":"Ἰησοῦς δὲ ἁγνίσας τὸν στρατὸν ἐξῆγεν ἐπὶ τὴν Ναϊὰν αὐτὸς καὶ νυκτὸς τὰ περὶ τὴν πόλιν ἐνέδραις προλοχίσας ὑπὸ τὸν ὄρθρον συμβάλλει τοῖς πολεμίοις. τῶν δὲ μετὰ θράσους αὐτοῖς διὰ τὴν προτέραν νίκην ἐπιόντων ὑποχωρεῖν προσποιησάμενος ἕλκει τῷ τρόπῳ τούτῳ μακρὰν αὐτοὺς τῆς πόλεως διώκειν οἰομένους καὶ ὡς ἐπὶ νίκῃ καταφρονοῦντας."},{"number":46,"text":"ἔπειτʼ ἀναστρέψας τὴν δύναμιν κατὰ πρόσωπον αὐτοῖς ποιεῖ, σημεῖά τε δοὺς ἃ πρὸς τοὺς ἐν ταῖς ἐνέδραις συνετέτακτο κἀκείνους ἐπὶ τὴν μάχην ἐξανίστησιν. οἱ δʼ εἰσεπήδων εἰς τὴν πόλιν τῶν ἔνδον περὶ τοῖς τείχεσιν ὄντων, ἐνίων δὲ καὶ πρὸς θέαν τῶν ἔξω τὴν γνώμην περισπωμένων."},{"number":47,"text":"καὶ οἱ μὲν τὴν πόλιν ᾕρουν καὶ πάντας τοὺς ἐντυγχάνοντας ἔκτεινον, Ἰησοῦς δὲ τοὺς προσελθόντας εἰς χεῖρας βιασάμενος φυγεῖν τρέπεται, συνελαυνόμενοι δὲ ὡς εἰς ἀκέραιον τὴν πόλιν ἐπεὶ καὶ ταύτην ἐχομένην ἑώρων καὶ καταπιμπραμένην ὁμοῦ γυναιξὶ καὶ τέκνοις κατέλαβον, διὰ τῶν ἀγρῶν σκεδασθέντες καὶ ἀμύνειν αὐτοῖς ὑπὸ μονώσεως οὐ δυνάμενοι ."},{"number":48,"text":"τοιαύτης δὲ τῆς συμφορᾶς τοὺς Ναϊτιανοὺς καταλαβούσης, παίδων τε ὄχλος ἑάλω καὶ γυναικῶν καὶ θεραπείας καὶ τῆς ἄλλης ἀποσκευῆς ἄπειρόν τι πλῆθος, ἀγέλας τε βοσκημάτων ἔλαβον οἱ Ἑβραῖοι καὶ χρήματα πολλά, καὶ γὰρ πλούσιον ἦν τὸ χωρίον, καὶ ταῦτα πάντα τοῖς στρατιώταις Ἰησοῦς διένειμεν ἐν Γαλγάλοις γενόμενος."},{"number":49,"text":"Γεβεωνῖται δὲ κατοικοῦντες ἔγγιστα τοῖς Ἱεροσολύμοις τά τε τοῖς Ἱεριχουντίοις συμβεβηκότα πάθη καὶ τὰ τοῖς Ναϊτίνοις ὁρῶντες καὶ πρὸς σφᾶς μεταβήσεσθαι τὸ δεινὸν ὑπονοοῦντες, Ἰησοῦν μὲν παρακαλεῖν οὐ διέγνωσαν· οὐδὲ γὰρ τεύξεσθαί τινος τῶν μετρίων ὑπελάμβανον ἐπʼ ὀλέθρῳ τοῦ Χαναναίων ἔθνους παντὸς πολεμοῦντος αὐτούς·"},{"number":50,"text":"Κεφηρίτας δὲ καὶ Καριαθιαριμίτας γείτονας ὄντας αὐτοῖς ἐπὶ συμμαχίαν παρεκάλουν, οὐδʼ αὐτοὺς διαφεύξεσθαι τὸν κίνδυνον λέγοντες, εἰ φθάσαιεν αὐτοὶ ληφθέντες ὑπὸ τῶν Ἰσραηλιτῶν, συνασπίσαντας δὲ αὐτοῖς διέγνωσαν διαδρᾶναι τὴν δύναμιν αὐτῶν."},{"number":51,"text":"προσδεξαμένων δὲ τοὺς λόγους αὐτῶν πέμπουσι πρέσβεις πρὸς Ἰησοῦν φιλίαν σπεισομένους οὓς μάλιστα τῶν πολιτῶν ἐδοκίμαζον ἱκανοὺς πρᾶξαι τὰ συμφέροντα τῷ πλήθει."},{"number":52,"text":"οἱ δὲ ὁμολογεῖν αὑτοὺς Χαναναίους ἐπισφαλὲς ἡγούμενοι, διαφεύξεσθαι τὸν διὰ τοῦτο κίνδυνον ὑπολαμβάνοντες, εἰ λέγοιεν αὑτοὺς μὴ προσήκειν κατὰ μηδὲν Χαναναίοις ἀλλὰ πορρωτάτω τούτων κατοικεῖν, ἥκειν τε κατὰ πύστιν τῆς ἀρετῆς αὐτοῦ πολλὴν ἀνύσαντες ὁδὸν ἔφασκον καὶ τεκμήριον τοῦ λόγου τούτου τὸ σχῆμα ὑπεδείκνυον·"},{"number":53,"text":"τὰς γὰρ ἐσθῆτας καινὰς ὅτε ἐξῄεσαν οὔσας ὑπὸ τοῦ χρόνου τῆς ὁδοιπορίας αὐτοῖς τετρῖφθαι· τρυχίνας γὰρ εἰς τὸ ταῦτα πιστοῦσθαι πρὸς αὐτῶν ἐπίτηδες ἔλαβον."},{"number":54,"text":"στάντες οὖν εἰς μέσους ἔλεγον, ὡς πεμφθεῖεν ὑπὸ τῶν Γεβεωνιτῶν καὶ τῶν περιοίκων πόλεων πλεῖστον ἀπεχουσῶν τῆσδε τῆς γῆς ποιησόμενοι πρὸς αὐτοὺς φιλίαν ἐφʼ αἷς πάτριον αὐτοῖς ἐστι συνθήκαις· μαθόντες γὰρ ἐκ θεοῦ χάριτος καὶ δωρεᾶς τὴν Χαναναίων αὐτοῖς γῆν κτήσασθαι δεδόσθαι τούτοις τʼ ἔλεγον ἥδεσθαι καὶ πολίτας ἀξιοῦν αὐτῶν γενέσθαι."},{"number":55,"text":"καὶ οἱ μὲν ταῦτα λέγοντες καὶ ἐπιδεικνύντες τὰ τεκμήρια τῆς ὁδοιπορίας παρεκάλουν ἐπὶ συνθήκας καὶ φιλίαν τοὺς Ἑβραίους· Ἰησοῦς δὲ πιστεύσας οἷς ἔλεγον, ὡς οὐκ εἰσὶ τοῦ Χαναναίων ἔθνους, ποιεῖται πρὸς αὐτοὺς φιλίαν, καὶ Ἐλεάζαρος ὁ ἀρχιερεὺς μετὰ τῆς γερουσίας ὄμνυσιν ἕξειν τε φίλους καὶ συμμάχους καὶ μηδὲν μοχλεύσεσθαι κατʼ αὐτῶν ἄδικον τοῖς ὅρκοις ἐπισυναινέσαντος τοῦ πλήθους."},{"number":56,"text":"καὶ οἱ μὲν ὧν ἤθελον τυχόντες ἐξ ἀπάτης ἀπῄεσαν πρὸς αὑτούς. Ἰησοῦς δὲ τῆς Χαναναίας στρατεύσας εἰς τὴν ὑπώρειον καὶ μαθὼν οὐ πόρρω τῶν Ἱεροσολύμων τοὺς Γεβεωνίτας κατῳκημένους καὶ τοῦ γένους ὄντας τῶν Χαναναίων, μεταπεμψάμενος αὐτῶν τοὺς ἐν τέλει τῆς ἀπάτης αὐτοῖς ἐνεκάλει."},{"number":57,"text":"τῶν δʼ οὐκ ἄλλην ἀφορμὴν σωτηρίας ἔχειν ἢ ταύτην προφασιζομένων καὶ διὰ τοῦτʼ ἐπʼ αὐτὴν ἐξ ἀνάγκης καταφυγεῖν συγκαλεῖ τὸν ἀρχιερέα Ἐλεάζαρον καὶ τὴν γερουσίαν, καὶ δημοσίους αὐτοὺς δικαιούντων ποιεῖν ἐπὶ τῷ μὴ παραβῆναι τὸν ὅρκον ἀποδείκνυσιν εἶναι τοιούτους. καὶ οἱ μὲν τῆς καταλαβούσης αὐτοὺς συμφορᾶς τοιαύτην φυλακὴν καὶ ἀσφάλειαν εὕραντο."},{"number":58,"text":"Τοῦ δὲ τῶν Ἱεροσολυμιτῶν βασιλέως χαλεπῶς φέροντος ἐπὶ τῷ μετατάξασθαι πρὸς τὸν Ἰησοῦν τοὺς Γεβεωνίτας καὶ τοὺς τῶν πλησίον ἐθνῶν παρακαλέσαντος βασιλέας συνάρασθαι τῷ κατʼ αὐτῶν πολέμῳ, ὡς τούτους τε εἶδον παρόντας σὺν αὐτῷ, τέσσαρες δὲ ἦσαν, οἱ Γεβεωνῖται καὶ στρατοπεδευσαμένους ἐπί τινι πηγῇ τῆς πόλεως οὐκ ἄπωθεν παρασκευάζεσθαι πρὸς πολιορκίαν, ἐπεκαλοῦντο σύμμαχον Ἰησοῦν·"},{"number":59,"text":"ἐν τούτοις γὰρ ἦν αὐτοῖς τὰ πράγματα, ὡς ὑπὸ μὲν τούτων ἀπολεῖσθαι προσδοκᾶν, ὑπὸ δὲ τῶν ἐπʼ ὀλέθρῳ τοῦ Χαναναίων γένους στρατευσάντων σωθήσεσθαι διὰ τὴν γενομένην φιλίαν ὑπολαμβάνειν."},{"number":60,"text":"καὶ Ἰησοῦς πανστρατιᾷ σπεύσας ἐπὶ τὴν βοήθειαν καὶ διʼ ἡμέρας καὶ νυκτὸς ἀνύσας ὄρθριος προσμίγνυσι τοῖς πολεμίοις καὶ τραπεῖσιν εἵπετο διώκων διὰ χωρίων ἐπικλινῶν, Βηθωρὰ καλεῖται. ἔνθα καὶ τὴν τοῦ θεοῦ συνεργίαν ἔμαθεν ἐπισημήναντος αὐτοῦ βρονταῖς τε καὶ κεραυνῶν ἀφέσει καὶ χαλάζης καταφορᾷ μείζονος τῆς συνήθους·"},{"number":61,"text":"ἔτι γε μὴν καὶ τὴν ἡμέραν αὐξηθῆναι πλέον, ὡς ἂν μὴ καταλαβοῦσα νὺξ ἐπίσχῃ τὸ τῶν Ἑβραίων πρόθυμον, συνέπεσεν, ὥστε καὶ λαμβάνει τοὺς βασιλέας Ἰησοῦς ἔν τινι κρυπτομένους σπηλαίῳ κατὰ Μακχίδα καὶ κολάζει πάντας. ὅτι δὲ τὸ μῆκος τῆς ἡμέρας ἐπέδωκε τότε καὶ τοῦ συνήθους ἐπλεόνασε, δηλοῦται διὰ τῶν ἀνακειμένων ἐν τῷ ἱερῷ γραμμάτων."},{"number":62,"text":"Κατεστραμμένων δʼ οὕτως τῶν περὶ τοὺς βασιλέας, οἳ τοὺς Γεβεωνίτας πολεμήσοντες ἐστράτευσαν, ἐπανῄει πάλιν τῆς Χαναναίας ἐπὶ τὴν ὀρεινὴν Ἰησοῦς καὶ πολὺν τῶν ἐν αὐτῇ φόνον ἐργασάμενος καὶ λείαν λαβὼν παρῆν εἰς τὸ ἐν Γαλγάλοις στρατόπεδον."},{"number":63,"text":"τοῦ δὲ περὶ τῆς τῶν Ἑβραίων ἀρετῆς λόγου πολλοῦ φοιτῶντος εἰς τοὺς περιοίκους κατάπληξις εἶχε τοὺς ἀκούοντας τὸ τῶν ἀπολωλότων πλῆθος καὶ στρατεύουσιν ἐπʼ αὐτοὺς οἱ περὶ Λίβανον ὄρος βασιλεῖς ὄντες Χαναναῖοι καὶ οἱ ἐν τοῖς πεδίοις τῶν Χαναναίων Παλαιστίνους προσλαβόντες στρατοπεδεύουσι πρὸς Βηρώθῃ πόλει Γαλιλαίας τῆς ἄνω Κεδέσης οὐ πόρρω· Γαλιλαίων δʼ ἐστὶ καὶ τοῦτο τὸ χωρίον."},{"number":64,"text":"τοῦ δὲ στρατοῦ παντὸς ὁπλιτῶν μὲν ἦσαν μυριάδες τριάκοντα μύριοι δʼ ἱππεῖς καὶ ἅρματα δισμύρια. καταπλήττει δὲ τὸ πλῆθος τῶν πολεμίων αὐτόν τε Ἰησοῦν καὶ τοὺς Ἰσραηλίτας καὶ πρὸς τὴν ἐλπίδα τοῦ κρείττονος εὐλαβεστέρως εἶχον διʼ ὑπερβολὴν τοῦ δέους."},{"number":65,"text":"τοῦ θεοῦ δʼ ἐξονειδίσαντος αὐτοῖς τὸν φόβον καὶ τί πλέον τῆς παρʼ αὐτοῦ βοηθείας ποθοῦσιν, ὑποσχομένου τε νικήσειν τοὺς ἐχθροὺς καὶ κελεύσαντος τούς τε ἵππους ἀχρήστους ποιῆσαι καὶ τὰ ἅρματα πυρῶσαι, θαρσαλέος πρὸς τὰς ὑποσχέσεις τοῦ θεοῦ γενόμενος ἐξώρμησεν ἐπὶ τοὺς πολεμίους,"},{"number":66,"text":"καὶ διὰ πέμπτης ἡμέρας ἐπʼ αὐτοὺς ἐλθὼν συνάπτει καὶ καρτερὰ μάχη γίνεται καὶ φόνος κρείττων πίστεως παρὰ τοῖς ἀκροωμένοις. διώκων δʼ ἐπὶ πλεῖστον ἐξῆλθε καὶ πᾶν τὸ στράτευμα τῶν ἐχθρῶν πλὴν ὀλίγων διέφθειρε,"},{"number":67,"text":"καὶ οἱ βασιλεῖς πάντες ἔπεσον, ὥστε τῶν ἀνθρώπων ἐπιλελοιπότων πρὸς τὸ κτείνεσθαι τοὺς ἵππους Ἰησοῦς αὐτῶν ἀνῄρει καὶ τὰ ἅρματα ἐνεπίμπρα, τήν τε χώραν ἐπʼ ἀδείας διεπορεύετο μηδενὸς τολμῶντος εἰς μάχην ἐπεξελθεῖν, ἀλλὰ πολιορκίᾳ τὰς πόλεις αἱρῶν καὶ πᾶν ὅ τι λάβοι φονεύων."},{"number":68,"text":"Ἔτος δὲ πέμπτον ἤδη παρεληλύθει καὶ Χαναναίων οὐκέτʼ οὐδεὶς ὑπολέλειπτο πλὴν εἰ μή τινες ὀχυρότητι τειχῶν διέφυγον. Ἰησοῦς δʼ ἐκ τῶν Γαλγάλων ἀναστρατοπεδεύσας εἰς τὴν ὄρειον ἱστᾷ τὴν ἱερὰν σκηνὴν κατὰ Σιλοῦν πόλιν, ἐπιτήδειον γὰρ ἐδόκει τὸ χωρίον διὰ κάλλος, ἕως οἰκοδομεῖν ναὸν αὐτοῖς τὰ πράγματα παράσχοι."},{"number":69,"text":"καὶ χωρήσας ἐντεῦθεν ἐπὶ Σικίμων σὺν ἅπαντι τῷ λαῷ βωμόν τε ἵστησιν ὅπου προεῖπε Μωυσῆς καὶ νείμας τὴν στρατιὰν ἐπὶ μὲν τῷ Γαριζεῖ ὄρει τὴν ἡμίσειαν ἵστησιν, ἐπὶ δὲ τῷ Ἡβήλῳ τὴν ἡμίσειαν ἐν ᾧ καὶ ὁ βωμός ἐστι καὶ τὸ Λευιτικὸν καὶ τοὺς ἱερέας."},{"number":70,"text":"θύσαντες δὲ καὶ ἀρὰς ποιησάμενοι καὶ ταύτας ἐπὶ τῷ βωμῷ γεγραμμένας καταλιπόντες εἰς τὴν Σιλοῦν ἀνέζευξαν."},{"number":71,"text":"Ἰησοῦς δʼ ἤδη γηραιὸς ὢν καὶ τὰς τῶν Χαναναίων πόλεις ὁρῶν οὐκ εὐαλώτους ὑπό τε τῶν χωρίων ἐν οἷς ἦσαν ὀχυρότητος καὶ τῆς τῶν τειχῶν ἰσχύος, ἃ τῇ φυσικῇ τῶν πόλεων πλεονεξίᾳ προσεπιβαλλόμενοι προσεδόκων τοὺς πολεμίους ἀφέξεσθαι πολιορκίας διʼ ἀπόγνωσιν τοῦ λαβεῖν,"},{"number":72,"text":"καὶ γὰρ ἐπʼ ὀλέθρῳ τῷ ἑαυτῶν οἱ Χαναναῖοι μαθόντες τοὺς Ἰσραηλίτας ποιησαμένους τὴν ἔξοδον τὴν ἀπʼ Αἰγύπτου πρὸς τῷ τὰς πόλεις καρτερὰς ποιεῖν ἐκεῖνον ἅπαντʼ ἦσαν τὸν χρόνον, συναγαγὼν τὸν λαὸν εἰς τὴν Σιλοῦν ἐκκλησίαν παρήγγειλε."},{"number":73,"text":"καὶ σπουδῇ συνδραμόντων τά τε ἤδη κατωρθωμένα καὶ τὰς γεγενημένας πράξεις, ὡς εἰσὶν ἄρισται καὶ τοῦ θείου τοῦ παρασχόντος αὐτὰς ἄξιαι καὶ τῆς ἀρετῆς τῶν νόμων οἷς κατακολουθοῦσιν ἔλεγε, βασιλεῖς τε τριάκοντα καὶ ἕνα τολμήσαντας αὐτοῖς εἰς χεῖρας ἐλθεῖν κεκρατῆσθαι δηλῶν καὶ στρατιὰν ὅση ποτὲ κατελπίσασα τῆς αὐτῶν δυνάμεως εἰς μάχην συνῆψεν ἅπασαν διαφθαρεῖσαν, ὡς μηδὲ γενεὰν αὐτοῖς ὑπολελεῖφθαι."},{"number":74,"text":"τῶν δὲ πόλεων ἐπειδήπερ αἱ μὲν ἑαλώκεσαν, πρὸς ἃς δὲ δεῖ χρόνου καὶ μεγάλης πολιορκίας διὰ τὴν τῶν τειχῶν ὀχυρότητα καὶ τὴν ἐπὶ ταύτῃ τῶν οἰκητόρων πεποίθησιν, ἠξίου τοὺς ἐκ τῆς περαίας τοῦ Ἰορδάνου συνεξορμήσαντας αὐτοῖς καὶ τῶν κινδύνων συναραμένους ὄντας συγγενεῖς ἀπολύειν ἤδη πρὸς τὰ οἰκεῖα χάριν αὐτοῖς ὧν συνέκαμον ὁμολογοῦντας,"},{"number":75,"text":"ἕνα τε κατὰ φυλὴν ἀρετῇ προύχειν μαρτυρηθέντα πέμπειν, οἳ τὴν γῆν ἐκμετρησόμενοι πιστῶς καὶ μηδὲν κακουργήσοντες δηλώσουσιν ἡμῖν ἀδόλως αὐτῆς τὸ μέγεθος."},{"number":76,"text":"Καὶ Ἰησοῦς μὲν τούτους ποιησάμενος τοὺς λόγους συγκάταινον ἔσχε τὸ πλῆθος καὶ ἄνδρας τοὺς ἐκμετρησομένους τὴν χώραν αὐτῶν ἐξέπεμψε παραδοὺς αὐτοῖς τινας γεωμετρίας ἐπιστήμονας, οὓς τἀληθὲς οὐκ ἔμελλε λήσεσθαι διὰ τὴν τέχνην, ἐντολὰς δοὺς ἀποτιμήσασθαι τῆς τε εὐδαίμονος ἰδίᾳ τὸ μέτρον γῆς καὶ τῆς ἧσσον ἀγαθῆς."},{"number":77,"text":"ἡ γὰρ φύσις τῆς Χαναναίων γῆς τοιαύτη τίς ἐστιν, ὡς ἴδοι τις ἂν πεδία μεγάλα καὶ καρποὺς φέρειν ἱκανώτατα καὶ συγκρινόμενα μὲν ἑτέρᾳ γῇ πανευδαίμονα νομισθησόμενα, τοῖς δʼ Ἱεριχουντίων χωρίοις παραβαλλόμενα καὶ τοῖς Ἱεροσολυμιτῶν τὸ μηδὲν ἀναφανησόμενα·"},{"number":78,"text":"καίτοι παντελῶς ὀλίγην αὐτῶν εἶναι τὴν γῆν συμβέβηκε ταύτης δὲ ὀρεινὴν τὴν πολλήν, ἀλλʼ ὑπερβολὴν εἰς καρπῶν ἐκτροφήν τε καὶ κάλλος οὐκ ἀπολέλοιπεν ἑτέρᾳ. καὶ διὰ τοῦτο τιμητοὺς μᾶλλον ἢ μετρητοὺς τοὺς κλήρους εἶναι δεῖν ὑπέλαβε πολλάκις ἑνὸς πλέθρου κἂν χιλίων ἀνταξίου γενομένου."},{"number":79,"text":"οἱ δὲ ἄνδρες οἱ πεμφθέντες, δέκα δὲ ἦσαν, περιοδεύσαντες καὶ τιμησάμενοι τὴν γῆν ἐν ἑβδόμῳ μηνὶ παρῆσαν πρὸς αὐτὸν εἰς Σιλοῦντα πόλιν, ἔνθα τὴν σκηνὴν ἑστάκεσαν."},{"number":80,"text":"Καὶ Ἰησοῦς Ἐλεάζαρόν τε καὶ τὴν γερουσίαν σὺν τοῖς φυλάρχοις παραλαβὼν νέμει ταῖς ἐννέα φυλαῖς καὶ τῶν Μανασσητῶν τοῖς ἡμίσεσι, κατὰ μέγεθος ἑκάστης τῶν φυλῶν τὴν μέτρησιν ποιησάμενος."},{"number":81,"text":"κληρώσαντος δὲ αὐτοῦ, ἡ μὲν Ἰούδα λαχοῦσα πᾶσαν αἱρεῖται τὴν καθύπερθεν Ἰδουμαίαν παρατείνουσαν μὲν ἄχρι τῶν Ἱεροσολύμων τὸ δʼ εὖρος ἕως τῆς Σοδομίτιδος λίμνης καθήκουσαν· ἐν δὲ τῷ κλήρῳ τούτῳ πόλεις ἦσαν Ἀσκάλων καὶ Γάζα."},{"number":82,"text":"Σεμεωνὶς δέ, δευτέρα γὰρ ἦν, ἔλαχε τῆς Ἰδουμαίας τὴν Αἰγύπτῳ τε καὶ τῇ Ἀραβίᾳ πρόσορον οὖσαν. Βενιαμῖται δὲ τὴν ἀπὸ Ἰορδάνου ποταμοῦ ἔλαχον ἄχρι θαλάσσης μὲν τὸ μῆκος, τὸ δὲ πλάτος Ἱεροσολύμοις ὁριζομένην καὶ Βηθήλοις· στενώτατος δὲ ὁ κλῆρος οὗτος ἦν διὰ τὴν τῆς γῆς ἀρετήν· Ἱεριχοῦντα γὰρ καὶ τὴν Ἱεροσολυμιτῶν πόλιν ἔλαβον."},{"number":83,"text":"ἡ δʼ Ἐφρὰν φυλὴ τὴν ἄχρι Γαζάρων ἀπὸ Ἰορδάνου ποταμοῦ μηκυνομένην ἔλαχεν, εὐρεῖαν δὲ ὅσον ἀπὸ Βεθήλων εἰς τὸ μέγα τελευτᾷ πεδίον, τῆς τε Μανασσήτιδος οἱ ἡμίσεις ἀπὸ μὲν Ἰορδάνου μέχρι Δώρων πόλεως, πλάτος δὲ ἐπὶ Βηθησάνων, ἣ νῦν Σκυθόπολις καλεῖται,"},{"number":84,"text":"καὶ μετὰ τούτους Ἰσαχαρὶς Κάρμηλόν τε τὸ ὄρος καὶ τὸν ποταμὸν τοῦ μήκους ποιησαμένη τέρμονα, τὸ δὲ Ἰταβύριον ὄρος τοῦ πλάτους. Ζαβουλωνῖται δὲ τὴν μέχρι Γενησαρίδος καθήκουσαν δὲ περὶ Κάρμηλον καὶ θάλασσαν ἔλαχον."},{"number":85,"text":"τὴν δὲ ἀπὸ τοῦ Καρμήλου κοιλάδα προσαγορευομένην διὰ τὸ καὶ τοιαύτην εἶναι Ἀσηρῖται φέρονται πᾶσαν τὴν ἐπὶ Σιδῶνος τετραμμένην· Ἄρκη δὲ πόλις ὑπῆρχεν αὐτοῖς ἐν τῇ μερίδι ἡ καὶ Ἐκδείπους."},{"number":86,"text":"τὰ δὲ πρὸς τὰς ἀνατολὰς τετραμμένα μέχρι Δαμασκοῦ πόλεως καὶ τῆς Γαλιλαίας τὰ καθύπερθεν Νεφθαλῖται παρέλαβον ἕως τοῦ Λιβάνου ὄρους καὶ τῶν τοῦ Ἰορδάνου πηγῶν, αἳ τὴν ὁρμὴν ἐκ τοῦ ὄρους ἔχουσιν, ἐκ τοῦ καθήκοντος τοῖς ὅροις κατὰ τὰ βόρεια πόλεως Ἄρκης παροικούσης."},{"number":87,"text":"Δανῖται δὲ τῆς κοίλης ὅσα πρὸς δυόμενον τέτραπται τὸν ἥλιον λαγχάνουσιν Ἀζώτῳ καὶ Δώροις ὁριζόμενοι Ἰάμνειάν τε πᾶσαν καὶ Γίτταν ἀπʼ Ἀκκαρῶνος ἕως τοῦ ὄρους, ἐξ οὗ ἡ Ἰούδα ἦρκτο φυλή."},{"number":88,"text":"Καὶ ἓξ μὲν ἔθνη τῶν υἱέων τοῦ Χαναναίου φέροντα τὴν ἐπωνυμίαν διεῖλεν οὕτως Ἰησοῦς καὶ τὴν γῆν ταῖς ἐννέα καὶ τῇ ἡμισείᾳ φυλαῖς ἔδωκε νέμεσθαι·"},{"number":89,"text":"τὴν γὰρ Ἀμορρῖτιν καὶ αὐτὴν οὕτως ἀφʼ ἑνὸς τῶν Χαναναίου παίδων καλουμένην Μωυσῆς ἤδη προειληφὼς νενεμήκει ταῖς δυσὶ φυλαῖς καὶ τῷ ἡμίσει· τοῦτο δὲ καὶ πρότερον δεδηλώκαμεν. τὰ δὲ περὶ Σιδῶνα καὶ Ἀρουκαίους καὶ Ἀμαθαίους καὶ Ἀριδαίους ἀδιακόσμητα ἦν."},{"number":90,"text":"Ἰησοῦς δὲ τοῦ γήρως ἐμποδίζοντος ἤδη πράττειν ὅσα καὶ νοήσειε τῶν τε μετʼ αὐτὸν τὴν ἡγεμονίαν παραλαβόντων ἀμελῶς προστάντων τοῦ κοινῇ συμφέροντος, παρήγγειλέ τε φυλῇ ἑκάστῃ τοῦ γένους τῶν Χαναναίων μηδὲν ὑπολιπεῖν ἐν τῇ κατακεκληρωμένῃ γῇ· τὴν γὰρ ἀσφάλειαν αὐτοῖς καὶ τὴν φυλακὴν τῶν πατρίων ἐθῶν ἐν μόνῳ τούτῳ καὶ Μωυσῆν αὐτοῖς εἶναι προειπεῖν καὶ τοῦτʼ αὐτοὺς πεπεῖσθαι."},{"number":91,"text":"καὶ τοῖς Λευίταις δὲ τὰς ὀκτὼ καὶ τριάκοντα πόλεις ἀποδιδόναι· προειλήφεισαν γὰρ ἤδη κατὰ τὴν Ἀμορραίαν τὰς δέκα. τούτων τρεῖς ἀπονέμει τοῖς φυγάσιν οἰκεῖν ἐν αὐταῖς, πολλὴ γὰρ ἦν πρόνοια τοῦ μηδὲν ὧν Μωυσῆς διέταξε παραλιπεῖν, τῆς μὲν οὖν Ἰούδα φυλῆς Ἰέβρωνα, Σίκιμα δὲ τῆς Ἐφραίμ, τῆς Νεφθαλίτιδος δὲ Κεδέσην· ἔστι τῆς καθύπερθεν Γαλιλαίας τοῦτο τὸ χωρίον."},{"number":92,"text":"νέμει δὲ καὶ τῆς λείας ὅσα ἦν ἔτι λοιπά, πλείστη δʼ ἐγεγόνει, καὶ μεγάλους πλούτους περιεβέβληντο καὶ κοινῇ πάντες καὶ κατʼ ἰδίαν ἕκαστος χρυσοῦ τε καὶ ἀργύρου καὶ ἐσθήτων καὶ τῆς ἄλλης ἐπισκευῆς ἕνεκα, τετραπόδων τε πλήθους ὅσον οὐδὲ ἀριθμῷ μαθεῖν ἦν προσγενομένου."},{"number":93,"text":"Μετὰ δὲ ταῦτα συναγαγὼν εἰς ἐκκλησίαν τὸν στρατὸν τοῖς ὑπὲρ τὸν Ἰόρδανον κατὰ τὴν Ἀμορραίαν ἱδρυμένοις, συνεστράτευον δʼ αὐτοῖς πεντακισμύριοι ὁπλῖται, ἔλεξε τάδε· ἐπεὶ ὁ θεός, πατὴρ καὶ δεσπότης τοῦ Ἑβραίων γένους, γῆν τε κτήσασθαι ταύτην ἔδωκε καὶ κτηθεῖσαν εἰς ἅπαν ἡμετέραν φυλάξειν ὑπείσχηται,"},{"number":94,"text":"συνεργίας δὲ τῆς παρʼ ὑμῶν κατʼ ἐντολὴν τὴν ἐκείνου δεομένοις ἑαυτοὺς εἰς ἅπαν προθύμους ἐδώκατε, δίκαιον ὑμᾶς μηδενὸς ἔτι δυσκόλου περιμένοντος ἀναπαύσεως ἤδη τυχεῖν φειδοῖ τῆς προθυμίας ὑμῶν, ἵνʼ εἰ καὶ πάλιν δεήσειεν ἡμῖν αὐτῆς ἄοκνον ἔχωμεν εἰς τὰ κατεπείξοντα καὶ μὴ τοῖς νῦν καμοῦσαν αὖθις βραδυτέραν."},{"number":95,"text":"χάριν τε οὖν ὑμῖν ὧν συνήρασθε κινδύνων καὶ οὐχὶ νῦν μόνον ἀλλʼ ἀεὶ πάντως ἕξομεν, ὄντες ἀγαθοὶ μεμνῆσθαι τῶν φίλων καὶ παρὰ τῇ διανοίᾳ κρατεῖν ὅσα παρʼ αὐτῶν ἡμῖν ὑπῆρξεν, ὅτι τε τὴν ἀπόλαυσιν τῶν ὑπαρχόντων ὑμῖν ἀγαθῶν διʼ ἡμᾶς ἀνεβάλεσθε καὶ πονήσαντες εἰς ἃ νῦν εὐνοίᾳ θεοῦ κατέστημεν ἔπειθʼ οὕτως ἐκρίνατε αὐτῶν μεταλαμβάνειν."},{"number":96,"text":"γέγονε δὲ πρὸς τοῖς ὑπάρχουσιν ἀγαθοῖς ἐκ τῶν σὺν ἡμῖν πόνων πλοῦτος ἄφθονος λείαν τε πολλὴν ἐπαξομένοις καὶ χρυσὸν καὶ ἄργυρον καὶ τὸ τούτων ἔτι πλεῖον, παρʼ ἡμῖν εὔνοια καὶ πρὸς ὅ τι βουληθείητε κατʼ ἀμοιβὴν πρόθυμον. οὔτε γὰρ ὧν Μωυσῆς προεῖπεν ἀπελείφθητε καταφρονήσαντες ἐξ ἀνθρώπων ἀπελθόντος οὔτʼ ἔστιν οὐδὲν ἐφʼ ᾧ μὴ χάριν ὑμῖν οἴδαμεν."},{"number":97,"text":"χαίροντας οὖν ὑμᾶς ἐπὶ τὰς κληρουχίας ἀπολύομεν καὶ παρακαλοῦμεν μηδένα τῆς πρὸς ἡμᾶς συγγενείας ὅρον ὑπολαμβάνειν, μηδʼ ὅτι μεταξὺ ποταμὸς οὗτός ἐστιν ἑτέρους ἡμᾶς νομίσητε καὶ οὐχὶ Ἑβραίους. Ἁβράμου γὰρ ἅπαντές ἐσμεν οἵ τʼ ἐνθάδε κἀκεῖ κατοικοῦντες, θεός τε εἷς, ὃς τούς τε ἡμετέρους προγόνους καὶ τοὺς ὑμῶν αὐτῶν παρήγαγεν εἰς τὸν βίον·"},{"number":98,"text":"οὗ τῆς θρησκείας ἐπιμελεῖσθε καὶ πολιτείας, ἣν αὐτὸς διὰ Μωυσέος διέταξε, φυλακὴν ἔχετε τὴν πᾶσαν, ὡς ἐμμενόντων μὲν τούτοις καὶ τοῦ θεοῦ παρέξοντος εὔνουν εἶναι καὶ σύμμαχον ἑαυτόν,"},{"number":99,"text":"ἐκτραπέντων δὲ εἰς ἑτέρων ἐθνῶν μίμησιν ἀποστραφησομένου τὸ γένος ὑμῶν. ταῦτα εἰπὼν καὶ καθʼ ἕνα τοὺς ἐν τέλει καὶ κοινῇ τὸ πλῆθος αὐτῶν ἀσπασάμενος αὐτὸς μὲν ὑπέμεινε, προύπεμπε δʼ αὐτοὺς ὁ λαὸς οὐκ ἀδακρυτὶ καὶ μόλις ἀλλήλων ἀπελύθησαν."},{"number":100,"text":"Διαβᾶσα δὲ τὸν ποταμὸν ἥ τε Ῥουβηλὶς φυλὴ καὶ Γαδὶς καὶ ὅσοι τῶν Μανασσητῶν αὐτοῖς συνείποντο βωμὸν ὑπὲρ τῆς ὄχθης ἱδρύονται τοῦ Ἰορδάνου, μνημεῖον τοῖς ἔπειτα γενησόμενον σύμβολον τῆς πρὸς τοὺς πέραν κατῳκημένους οἰκειότητος."},{"number":101,"text":"ἀκούσαντες δὲ οἱ πέραν βωμὸν ἱδρῦσθαι τοὺς ἀπολυθέντας οὐ μεθʼ ἧς ἐκεῖνοι γνώμης ἀνέστησαν αὐτόν, ἀλλʼ ἐπὶ νεωτερισμῷ καὶ ξενικῶν εἰσαγωγῇ θεῶν, οὐκ ἤθελον ἀπιστεῖν, ἀλλὰ περὶ θείαν θρησκείαν τὴν διαβολὴν πιθανὴν νομίζοντες ἐν ὅπλοις ἦσαν, ὡς ἐπʼ ἀμύνῃ τῶν τὸν βωμὸν ἱδρυσαμένων περαιωσόμενοι τὸν ποταμὸν καὶ κολάσοντες αὐτοὺς τῆς παρατροπῆς τῶν πατρίων ἐθῶν."},{"number":102,"text":"οὐ γὰρ ἐδόκει τὴν συγγένειαν αὐτοὺς λογίζεσθαι καὶ τὸ ἀξίωμα τῶν τὴν αἰτίαν εἰληφότων, ἀλλὰ τὸ τοῦ θεοῦ βουλητὸν καὶ ᾧ τρόπῳ τιμώμενος χαίρει."},{"number":103,"text":"καὶ οἱ μὲν ἐστράτευσαν ὑπʼ ὀργῆς, ἐπέσχε δʼ αὐτοὺς Ἰησοῦς καὶ ὁ ἀρχιερεὺς Ἐλεάζαρος καὶ ἡ γερουσία λόγοις συμβουλεύοντες ἀπόπειραν αὐτῶν τῆς γνώμης λαβεῖν πρῶτον, ἔπειτʼ ἂν κακοήθη μάθωσι τὴν διάνοιαν αὐτῶν τότε τοῖς. ὅπλοις χωρεῖν ἐπʼ αὐτούς."},{"number":104,"text":"πέμπουσιν οὖν πρεσβευτὰς πρὸς αὐτοὺς Φινεέσην τὸν υἱὸν Ἐλεαζάρου καὶ δέκα σὺν αὐτῷ τῶν ἐν τιμῇ παρὰ τοῖς Ἑβραίοις μαθησομένους, τί καὶ φρονήσαντες τὸν βωμὸν ἐπὶ τῆς ὄχθης τοῦ ποταμοῦ διαβάντες ἔστησαν."},{"number":105,"text":"ὡς δὲ περαιωσαμένων καὶ πρὸς αὐτοὺς ἀφικομένων ἐκκλησία συνελέγη, στὰς Φινεέσης μείζω μὲν αὐτοὺς ἁμαρτεῖν ἔλεγεν, ἢ ὥστε λόγοις ἐπιτιμηθέντας νενουθετῆσθαι πρὸς τὰ μέλλοντα πλὴν οὐ πρὸς τὸ μέγεθος τῆς παρανομίας ἀπιδόντας εὐθὺς ἐφʼ ὅπλα καὶ τὴν ἐκ χειρῶν τιμωρίαν ὁρμῆσαι, πρὸς δὲ τὸ συγγενὲς καὶ τὸ τάχα καὶ λόγοις ἂν σωφρονῆσαι σκοπήσαντας οὕτω ποιήσασθαι τὴν πρεσβείαν,"},{"number":106,"text":"ἵνα τὴν αἰτίαν μαθόντες ὑφʼ ἧς προήχθητε τὸν βωμὸν κατασκευάσαι μήτε προπετεῖς δοκῶμεν ὅπλοις μετιόντες ὑμᾶς κατὰ λογισμὸν ὅσιον ποιησαμένους τὸν βωμόν, κατι δικαίως ἀμυνώμεθα τῆς διαβολῆς ἐλεγχθείσης ἀληθοῦς."},{"number":107,"text":"οὐ γὰρ ἠξιοῦμεν ὑμᾶς πείρᾳ τῆς τοῦ θεοῦ γνώμης ἐντὸς γεγενημένους καὶ νόμων ὧν αὐτὸς ἡμῖν δέδωκεν ἀκροατὰς ὑπάρχοντας, διαζευχθέντας ἡμῶν καὶ παρόντας εἰς τὸν ἴδιον κλῆρον, ὃν κατὰ χάριν τοῦ θεοῦ καὶ τῆς ἐκείνου περὶ ἡμᾶς προνοίας ἐλάχετε, λήθην λαβεῖν αὐτοῦ καὶ τὴν σκηνὴν καὶ τὴν κιβωτὸν καταλιπόντας καὶ βωμὸν ὃς ἡμῖν πάτριος ξενικοὺς θεοὺς ἐπιφέρειν τοῖς Χαναναίων κακοῖς προσκεχωρηκότας."},{"number":108,"text":"ἀλλʼ οὐδὲν ἀδικεῖν δόξετε μετανοήσαντες καὶ μὴ περαιτέρω μανέντες νόμων δὲ πατρίων αἰδῶ καὶ μνήμην λαβόντες. ἂν δʼ ἐπιμένητε τοῖς ἡμαρτημένοις, οὐ περιστησόμεθα τὸν ὑπὲρ τῶν νόμων πόνον, ἀλλὰ περαιωσάμενοι τὸν Ἰόρδανον τούτοις βοηθήσομεν καὶ πρὸ αὐτῶν τῷ θεῷ, μηδὲν ὑμᾶς Χαναναίων διαφέρειν ὑπολαμβάνοντες ἀλλʼ ὁμοίως ἐκείνοις διαφθείροντες."},{"number":109,"text":"μὴ γὰρ νομίσητε τῷ διαβεβηκέναι τὸν ποταμὸν καὶ τῆς τοῦ θεοῦ δυνάμεως ἔξω γεγονέναι πανταχοῦ δʼ ἐν τοῖς τούτου ἐστὲ καὶ ἀποδρᾶναι τὴν ἐξουσίαν αὐτοῦ καὶ τὴν ἀπὸ ταύτης δίκην ἀδύνατον. εἰ δʼ οἴεσθε τὴν ἐνθάδε παρουσίαν ὑμῖν ἐμπόδιον εἶναι τοῦ σωφρονεῖν, οὐδὲν κωλύει πάλιν τὴν γῆν ὑμᾶς ἀναδάσασθαι καὶ ταύτην ἀνεῖναι μηλόβοτον."},{"number":110,"text":"ἀλλʼ εὖ ποιήσετε σωφρονήσαντες καὶ ἐπὶ νεαροῖς μετατιθέμενοι τοῖς ἁμαρτήμασι. καὶ παρακαλοῦμεν ὑμᾶς πρὸς παίδων καὶ γυναικῶν μὴ παρασχεῖν ἡμῖν ἀνάγκην ἀμύνασθαι. ὡς οὖν τῆς ὑμετέρας αὐτῶν σωτηρίας καὶ τῶν φιλτάτων ὑμῖν ἐν τῇδε τῇ ἐκκλησίᾳ κειμένης οὕτω βουλεύεσθε, λόγοις ἡττηθῆναι συμφέρειν ὑπολαμβάνοντες ἢ πεῖραν ἔργων καὶ πολέμου περιμένειν ."},{"number":111,"text":"Τοσαῦτα τοῦ Φινεέσου διαλεχθέντος οἱ προεστῶτες τῆς ἐκκλησίας καὶ τὸ πλῆθος αὐτὸ πᾶν ἤρξαντο περὶ τῶν ἐγκεκλημένων αὐτοῖς ἀπολογεῖσθαι, καὶ μήτε συγγενείας τῆς πρὸς αὐτοὺς ἀποστήσεσθαι μήτε κατὰ νεωτερισμὸν ἀναστῆσαι τὸν βωμὸν λέγειν,"},{"number":112,"text":"ἀλλὰ θεόν τε ἕνα γινώσκειν τὸν Ἑβραίοις ἅπασι κοινὸν καὶ τὸν πρὸ τῆς σκηνῆς βωμὸν χάλκεον, ᾧ τὰς θυσίας ποιήσειν· τὸν μέντοι γε νῦν ἀνασταθέντα, διʼ ὃν καὶ ὕποπτοι γεγόνασιν, οὐ κατὰ θρησκείαν ἱδρῦσθαι, σύμβολον δὲ ὅπως εἴη καὶ τεκμήριον εἰς τὸν αἰῶνα τῆς πρὸς ὑμᾶς οἰκειότητος καὶ ἀνάγκη τοῦ σωφρονεῖν καὶ τοῖς πατρίοις ἐμμένειν, ἀλλʼ οὐχὶ παραβάσεως ἀρχήν, ὡς ὑπονοεῖτε."},{"number":113,"text":"μάρτυς δʼ ἡμῖν τοῦ ἐπὶ τοιαύτῃ τὸν βωμὸν αἰτίᾳ κατασκευάσαι γένοιτο ὁ θεὸς ἀξιόχρεως, ὅθεν ἀμείνονα περὶ ἡμῶν ἔχοντες ὑπόληψιν μηδὲν καταγινώσκετε τούτων, ἐφʼ οἷς ἐξώλεις εἶναι δίκαιοι πάντες ὅσοι τοῦ Ἁβράμου γένους ὄντες νεωτέροις ἐπιχειροῦσιν ἔθεσι καὶ τοῦ συνήθους τρόπου παρηλλαγμένοις ."},{"number":114,"text":"Ταῦτα εἰπόντας ἐπαινέσας ὁ Φινεέσης παρῆν πρὸς Ἰησοῦν καὶ τὰ παρʼ αὐτῶν ἀνήγγειλε τῷ λαῷ. ὁ δὲ χαίρων, ὅτι μηδεμία στρατολογεῖν αὐτοὺς ἀνάγκη μέλλει μηδʼ εἰς ὅπλα καὶ πόλεμον ἐξαγαγεῖν κατὰ ἀνδρῶν συγγενῶν, χαριστηρίους ὑπὲρ τούτων τῷ θεῷ θυσίας ἐπιτελεῖ. καὶ διαλύσας μετὰ ταῦτα τὸ πλῆθος εἰς τὰς ἰδίας κληρουχίας Ἰησοῦς αὐτὸς ἐν Σικίμοις διῆγεν."},{"number":115,"text":"ἔτει δʼ ὕστερον εἰκοστῷ ὑπέργηρως ὢν μεταπεμψάμενος τοὺς ἐπʼ ἀξιώματος μάλιστα τῶν πόλεων καὶ τὰς ἀρχὰς καὶ τὴν γερουσίαν καὶ τοῦ πλήθους ὅσον ἦν ἐφικτὸν αὐτῷ συναγαγών, ἐπεὶ παρῆσαν, τάς τε εὐεργεσίας τοῦ θεοῦ ἁπάσας ἀνεμίμνησκεν αὐτούς, πολλαὶ δὲ ἦσαν τοῖς ἐκ ταπεινοῦ σχήματος εἰς τοῦτο δόξης καὶ περιουσίας προελθοῦσι,"},{"number":116,"text":"φυλάττειν τε τὴν τοῦ θεοῦ προαίρεσιν οὕτως ἔχουσαν πρὸς αὐτοὺς παρεκάλει καὶ τῇ εὐσεβείᾳ, ᾗ γε μόνῃ φίλον αὐτοῖς διαμένειν τὸ θεῖον· αὐτῷ γὰρ καλῶς ἔχειν ἀπιέναι μέλλοντι τοῦ ζῆν παραίνεσιν αὐτοῖς τοιαύτην καταλιπεῖν κἀκείνους ἠξίου διὰ μνήμης ποιήσασθαι τὴν παρακέλευσιν."},{"number":117,"text":"Καὶ ὁ μὲν τοσαῦτα πρὸς τοὺς παρόντας διαλεχθεὶς τελευτᾷ βιοὺς ἑκατὸν ἔτη καὶ δέκα, ὧν Μωυσεῖ μὲν ἐπὶ διδασκαλίᾳ τῶν χρησίμων συνδιέτριψεν τεσσαράκοντα, στρατηγὸς δὲ μετὰ τὴν ἐκείνου τελευτὴν γίνεται πέντε καὶ εἴκοσιν,"},{"number":118,"text":"ἀνὴρ δὲ μήτε συνέσεως ὢν ἐνδεὴς μήτε τοῦ τὰ νοηθέντα πρὸς τοὺς πολλοὺς σαφῶς ἐξενεγκεῖν ἄπειρος, ἀλλʼ ἐν ἀμφοτέροις ἄκρος πρός τε τὰ ἔργα καὶ τοὺς κινδύνους εὔψυχος καὶ μεγαλότολμος πρυτανεῦσαί τε τὰ κατὰ τὴν εἰρήνην δεξιώτατος καὶ πρὸς ἅπαντα καιρὸν τὴν ἀρετὴν ἡρμοσμένος."},{"number":119,"text":"θάπτεται δὲ ἐν πόλει Θαμνᾶ τῆς Ἐφραίμου φυλῆς. θνήσκει δὲ ὑπʼ αὐτὸν τὸν καιρὸν καὶ Ἐλεάζαρος ὁ ἀρχιερεὺς Φινεέσῃ τῷ παιδὶ τὴν ἱερωσύνην καταλιπών, καὶ μνημεῖον αὐτῷ καὶ τάφος ἐν Γαβαθᾶ πόλει τυγχάνει."}],"2":[{"number":120,"text":"Μετὰ δὲ τὴν τούτων τελευτὴν Φινεέσης προφητεύει κατὰ τὴν τοῦ θεοῦ βούλησιν ἐπʼ ἐξωλείᾳ τοῦ Χαναναίων γένους τῇ Ἰούδα φυλῇ παρασχεῖν τὴν ἡγεμονίαν· καὶ γὰρ τῷ λαῷ διὰ σπουδῆς ἦν μαθεῖν τί καὶ τῷ θεῷ δοκεῖ. καὶ προσλαβοῦσα τὴν Σεμεωνίδα, ἐφʼ ᾧτε ἐξαιρεθέντων τῶν ἐκείνης ὑποτελῶν καὶ τοὺς ἐν αὐτῇ τῇ κληρουχίᾳ τοῦτο ποιῶσιν"},{"number":121,"text":"Χαναναῖοι δʼ ἀκμαζόντων αὐτοῖς κατʼ ἐκεῖνον τὸν καιρὸν τῶν πραγμάτων στρατῷ μεγάλῳ κατὰ Ζεβέκην αὐτοὺς ὑπέμενον τῷ βασιλεῖ τῶν Ζεβεκηνῶν Ἀδωνιζεβέκῳ τὴν ἡγεμονίαν ἐπιτρέψαντες· τὸ δὲ ὄνομα τοῦτο σημαίνει Ζεβεκηνῶν κύριος· ἀδωνὶ γὰρ τῇ Ἑβραίων διαλέκτῳ κύριος γίνεται· ἤλπιζόν τε κρατήσειν τῶν Ἰσραηλιτῶν διὰ τὸ τεθνάναι Ἰησοῦν."},{"number":122,"text":"συμμίξαντες δὲ αὐτοῖς Ἰσραηλῖται ταῖς δυσὶ φυλαῖς αἷς προεῖπον ἐμαχέσαντο λαμπρῶς καὶ κτείνουσι μὲν αὐτῶν ὑπὲρ μυρίους, τρεψάμενοι δὲ τὸ λοιπὸν καὶ διώκοντες αἱροῦσι τὸν Ἀδωνιζέβεκον,"},{"number":123,"text":"ὃς ἀκρωτηριασθεὶς ὑπʼ αὐτῶν φησιν, ἀλλʼ οὐκ εἰς τὸ πᾶν ἄρα λήσεσθαι θεὸν ἔμελλον τάδε πεπονθώς, ἃ κατὰ δυοῖν καὶ ἑβδομήκοντα βασιλέων πρᾶξαι πρότερον οὐκ ἐνετράπην."},{"number":124,"text":"καὶ ζῶντα μὲν κομίζουσιν ἕως Ἱεροσολύμων, τελευτήσαντα δὲ γῇ θάπτουσι. καὶ διεξῄεσαν αἱροῦντες τὰς πόλεις, πλείστας τε λαβόντες ἐπολιόρκουν Ἱεροσόλυμα· καὶ τὴν μὲν κάτω λαβόντες σὺν χρόνῳ πάντας ἔκτεινον τοὺς ἐνοικοῦντας, χαλεπὴ δʼ ἦν ἡ καθύπερθεν αὐτοῖς αἱρεθῆναι τειχῶν ὀχυρότητι καὶ φύσει τοῦ χωρίου."},{"number":125,"text":"Ὅθεν μετεστρατοπέδευσαν εἰς Νεβρῶνα καὶ ταύτην ἑλόντες κτείνουσι πάντας· ὑπελείπετο δὲ τῶν γιγάντων ἔτι γένος, οἳ διὰ σωμάτων μεγέθη καὶ μορφὰς οὐδὲν τοῖς ἄλλοις ἀνθρώποις παραπλησίας παράδοξον ἦσαν θέαμα καὶ δεινὸν ἄκουσμα. δείκνυται δὲ καὶ νῦν ἔτι τούτων ὀστᾶ μηδὲν τοῖς ὑπὸ πύστιν ἐρχομένοις ἐοικότα."},{"number":126,"text":"καὶ τοῦτο μὲν τοῖς Λευίταις ἐξαίρετον γέρας ἔδοσαν μετὰ καὶ τῶν δισχιλίων πηχῶν, τὴν δὲ γῆν Χαλέβῳ δωρεὰν ἔδοσαν κατὰ Μωυσέος ἐντολάς· οὗτος δʼ ἦν τῶν κατασκόπων εἷς ὧν ἔπεμψε Μωυσῆς εἰς τὴν Χαναναίαν."},{"number":127,"text":"διδόασι δὲ καὶ τοῖς Ἰέθρου τοῦ Μαδιανίτου ἀπογόνοις, Μωυσέος γὰρ ἦν γαμβρός, γῆν ἵνα νέμοιντο· τὴν γὰρ πατρίδα καταλιπόντες ἠκολούθησαν ἐκείνοις καὶ συνῆσαν αὐτοῖς ἐπὶ τῆς ἐρήμου."},{"number":128,"text":"Ἡ δὲ Ἰούδα φυλὴ καὶ Σεμεωνὶς τὰς μὲν κατὰ τὴν ὀρεινὴν τῆς Χαναναίας πόλεις εἷλον, τῶν δʼ ἐν τῷ πεδίῳ καὶ πρὸς θαλάσσῃ Ἀσκάλωνά τε καὶ Ἄζωτον. διαφεύγει δʼ αὐτοὺς Γάζα καὶ Ἀκκάρων· πεδίων γὰρ ὄντων καὶ πολλῆς ἁρμάτων εὐπορίας κακῶς ἐποίουν τοὺς ἐπελθόντας. καὶ αἵδε μὲν αἱ φυλαὶ μεγάλως ἐκ τοῦ πολεμεῖν εὐδαιμονήσασαι ἀνεχώρησαν εἰς τὰς ἑαυτῶν πόλεις καὶ κατατίθενται τὰ ὅπλα."},{"number":129,"text":"Βενιαμῖται δέ, τούτων γὰρ ἦν Ἱεροσόλυμα, τοῖς οἰκήτορσιν αὐτῶν συνεχώρησαν φόρους τελεῖν. καὶ οὕτως παυσάμενοι πάντες οἱ μὲν τοῦ κτείνειν οἱ δὲ κινδυνεύειν, ἐργάζεσθαι τὴν γῆν εὐσχόλουν. τὸ δʼ αὐτὸ καὶ αἱ λοιπαὶ φυλαὶ τὴν Βενιαμῖτιν μιμησάμεναι ἐποίουν καὶ τοῖς τελουμένοις ἀρκούμενοι φόροις ἐπέτρεπον τοῖς Χαναναίοις ἀπολέμοις εἶναι."},{"number":130,"text":"Ἡ δʼ Ἐφρὰν πολιορκοῦσα Βήθηλα τέλος οὐδὲν ἄξιον τοῦ χρόνου καὶ τῶν πόνων ηὕρισκε τῆς πολιορκίας, οἱ δὲ καίπερ ἀχθόμενοι τῇ καθέδρᾳ προσεκαρτέρουν."},{"number":131,"text":"ἔπειτα συλλαβόντες τινὰ τῶν ἐν τῇ πόλει προελθόντα ἐπὶ κομιδῇ τῶν ἀναγκαίων τινὰς πίστεις ἔδοσαν αὐτῷ παραδιδόντι τὴν πόλιν σώσειν αὐτόν τε καὶ τοὺς συγγενεῖς αὐτοῦ. κἀκεῖνος ἐπὶ τούτοις ὤμνυε τὴν πόλιν αὐτοῖς ἐγχειριεῖν. καὶ ὁ μὲν οὕτως προδοὺς σώζεται μετὰ τῶν οἰκείων, οἱ δὲ ἀποκτείναντες ἅπαντας τοὺς ἐνοικοῦντας εἶχον τὴν πόλιν."},{"number":132,"text":"Καὶ μετὰ ταῦτα πρὸς μὲν τοὺς πολεμίους μαλακῶς εἶχον οἱ Ἰσραηλῖται, τῆς δὲ γῆς καὶ τῶν ταύτης ἔργων ἐπεμελοῦντο. τῶν δὲ κατὰ τὸν πλοῦτον αὐτοῖς ἐπιδιδόντων ὑπὸ τρυφῆς καὶ ἡδονῆς τοῦ κόσμου ὠλιγώρουν καὶ τῆς πολιτείας τῶν νόμων οὐκέτʼ ἦσαν ἀκριβεῖς ἀκροαταί."},{"number":133,"text":"παροξυνθὲν δʼ ἐπὶ τούτοις τὸ θεῖον ἀναιρεῖ, πρῶτον μὲν ὡς φείσαιντο παρὰ τὴν αὐτοῦ γνώμην τῶν Χαναναίων, ἔπειθʼ ὡς ἐκεῖνοι χρήσοιντο πολλῇ κατʼ αὐτῶν ὠμότητι καιροῦ λαβόμενοι."},{"number":134,"text":"οἱ δὲ καὶ πρὸς τὰ παρὰ τοῦ θεοῦ δυσθύμως εἶχον καὶ πρὸς τὸ πολεμεῖν ἀηδῶς πολλά τε παρὰ τῶν Χαναναίων λαβόντες καὶ πρὸς τοὺς πόνους ἤδη διὰ τὴν τρυφὴν ἐκλελυμένοι."},{"number":135,"text":"καὶ συνέβαινεν ἤδη τὴν ἀριστοκρατίαν διεφθάρθαι, καὶ τὰς γερουσίας οὐκ ἀπεδείκνυσαν οὐδʼ ἀρχὴν ἄλλην οὐδεμίαν τῶν πρότερον νενομισμένων, ἦσαν δὲ ἐν τοῖς ἀγροῖς ἡδονῇ τοῦ κερδαίνειν προσδεδεμένοι. καὶ διὰ τὴν πολλὴν ἄδειαν στάσις αὐτοὺς πάλιν καταλαμβάνει δεινὴ καὶ προήχθησαν εἰς τὸ πολεμεῖν ἀλλήλοις ἐκ τοιαύτης αἰτίας."},{"number":136,"text":"Λευίτης ἀνὴρ τῶν δημοτικωτέρων τῆς Ἐφράνου κληρουχίας ὢν καὶ ἐν ἐκείνῃ κατοικῶν ἄγεται γύναιον ἀπὸ Βηθλέμων, τῆς δὲ Ἰούδα φυλῆς τοῦτʼ ἔστι τὸ χωρίον. ἐρῶν δὲ σφόδρα τῆς γυναικὸς καὶ τοῦ κάλλους αὐτῆς ἡττημένος ἠτύχει τῶν παρʼ ἐκείνης οὐχ ὁμοίων πειρώμενος."},{"number":137,"text":"ἀλλοτρίως δʼ αὐτῆς ἐχούσης καὶ διὰ τοῦτο μᾶλλον ἐκκαιομένου τῷ πάθει μέμψεις συνεχεῖς αὐτοῖς ἐγίνοντο καὶ τέλος ἡ γυνὴ πρὸς αὐτὰς βαρυνομένη καταλιποῦσα τὸν ἄνδρα πρὸς τοὺς γονεῖς παραγίνεται μηνὶ τετάρτῳ. χαλεπῶς δὲ φέρων ὁ ἀνὴρ ἐπὶ τῷ ἔρωτι ἧκε πρὸς τοὺς πενθεροὺς καὶ διαλυσάμενος τὰς μέμψεις καταλλάττεται πρὸς αὐτήν."},{"number":138,"text":"καὶ τέτταρας μὲν ἡμέρας προσαυτόθι διαιτᾶται φιλοφρονουμένων αὐτὸν τῶν γονέων, τῇ δὲ πέμπτῃ δόξαν ἀπιέναι πρὸς αὑτὸν περὶ δείλην ἔξεισι· βράδιον γὰρ ἀπέλυον οἱ γονεῖς τὴν θυγατέρα καὶ τῆς ἡμέρας τριβὴν ἐποιοῦντο. θεράπων δʼ αὐτοῖς εἷς εἵπετο καὶ ὄνος ἦν αὐτοῖς, ἐφʼ ἧς ὠχεῖτο τὸ γύναιον."},{"number":139,"text":"γενομένων δʼ αὐτῶν κατὰ Ἱεροσόλυμα, σταδίους δʼ ἐληλύθεσαν ἤδη τριάκοντα, συνεβούλευεν ὁ θεράπων καταχθῆναί που, μὴ καί τι τῆς νυκτὸς αὐτοὺς ὁδεύοντας καταλάβῃ δύσκολον καὶ ταῦτα οὐδὲ πόρρω πολεμίων ὄντας, τοῦ καιροῦ πολλάκις ἐπισφαλῆ καὶ ὕποπτα ποιοῦντος καὶ τὰ φίλα."},{"number":140,"text":"τῷ δʼ οὐκ ἤρεσεν ἡ γνώμη παρʼ ἀλλοφύλοις ἀνδράσι ξενοῦσθαι, Χαναναίων γὰρ ἦν ἡ πόλις, ἀλλὰ προελθόντας εἴκοσι στάδια εἰς οἰκείαν ἠξίου κατάγεσθαι πόλιν, καὶ κρατήσας τῇ γνώμῃ παρῆν εἰς Γαβὰν φυλῆς τῆς Βενιαμίτιδος ἤδη ὀψίας οὔσης."},{"number":141,"text":"καὶ μηδενὸς ἐπὶ ξενίαν τῶν κατὰ τὴν ἀγορὰν αὐτὸν παρακαλοῦντος πρεσβύτης ἐξ ἀγροῦ κατιὼν τῆς μὲν Ἐφράμιος φυλῆς ὢν ἐν δὲ τῇ Γάβῃ διαιτώμενος συντυγχάνων αὐτῷ, τίς τε ὢν ἤρετο καὶ διʼ ἃς αἰτίας στελλόμενος σκότους ἤδη τὰ πρὸς τὸ δεῖπνον αὑτῷ λαμβάνοι."},{"number":142,"text":"ὁ δὲ Λευίτης μὲν ἔφησεν εἶναι, γύναιον δὲ παρὰ τῶν γονέων ἄγων πρὸς αὐτὸν ἀπιέναι, τὴν δʼ οἴκησιν ἐδήλου τυγχάνειν ἐν τῇ Ἐφράμου κληρουχίᾳ. ὁ δὲ πρεσβύτης καὶ διὰ συγγένειαν καὶ διὰ τὸ τὴν αὐτὴν φυλὴν νέμειν καὶ διὰ τὴν συντυχίαν παρʼ αὐτὸν ξενισθησόμενον ἦγε."},{"number":143,"text":"νεανίαι δέ τινες τῶν Γαβαηνῶν ἐπὶ τῆς ἀγορᾶς τὸ γύναιον θεασάμενοι καὶ τὴν εὐπρέπειαν θαυμάσαντες, ἐπεὶ παρὰ τῷ πρεσβύτῃ κατηγμένην ἔμαθον καταφρονήσαντες τῆς ἀσθενείας καὶ τῆς ὀλιγότητος ἧκον ἐπὶ τὰς θύρας. τοῦ δὲ πρεσβύτου παρακαλοῦντος ἀπαλλάττεσθαι καὶ μὴ προσφέρειν βίαν μηδὲ ὕβριν ἠξίουν αὐτὸν παρασχόντα τὴν ξένην πραγμάτων ἀπηλλάχθαι."},{"number":144,"text":"συγγενῆ δὲ λέγοντος καὶ Λευῖτιν τοῦ πρεσβύτου καὶ δράσειν αὐτοὺς δεινὰ ὑφʼ ἡδονῆς εἰς τοὺς νόμους ἐξαμαρτάνοντας ὠλιγώρουν τοῦ δικαίου καὶ κατεγέλων, ἠπείλουν δὲ ἀποκτείνειν αὐτὸν ἐμποδίζοντα ταῖς ἐπιθυμίαις αὐτῶν."},{"number":145,"text":"εἰς δʼ ἀνάγκην περιηγμένος καὶ μὴ βουλόμενος τοὺς ξένους περιιδεῖν ὑβρισθέντας τῆς ἑαυτοῦ θυγατρὸς αὐτοῖς παρεχώρει, πληρώσειν τε τὴν ἐπιθυμίαν αὐτοὺς λέγων νομιμώτερον δίχα τῆς εἰς τοὺς ξένους ὕβρεως αὐτός τε μηδὲν ἀδικήσειν οὓς ὑπεδέξατο τούτῳ τῷ τρόπῳ νομίζων."},{"number":146,"text":"ὡς δʼ οὐδὲν τῆς σπουδῆς τῆς ἐπὶ τὴν ξένην ἐνεδίδοσαν, ἀλλὰ ἐνέκειντο ταύτην παραλαβεῖν ἀξιοῦντες, ὁ μὲν ἱκέτευε μηδὲν τολμᾶν παράνομον, οἱ δʼ ἁρπασάμενοι καὶ προσθέμενοι μᾶλλον τῷ βιαίῳ τῆς ἡδονῆς ἀπήγαγον πρὸς αὑτοὺς τὴν γυναῖκα καὶ διʼ ὅλης νυκτὸς ἐμπλησθέντες τῆς ὕβρεως ἀπέλυσαν περὶ ἀρχομένην ἡμέραν."},{"number":147,"text":"ἡ δὲ τεταλαιπωρημένη τοῖς συμβεβηκόσι παρῆν ἐπὶ τὴν ξενίαν καὶ ὑπὸ λύπης ὧν ἐπεπόνθει καὶ τοῦ μὴ τολμᾶν ὑπʼ αἰσχύνης εἰς ὄψιν ἐλθεῖν τἀνδρί, τοῦτον γὰρ μάλιστα τοῖς γεγενημένοις ἔχειν ἀνιάτως ἐλογίζετο, καταπεσοῦσα τὴν ψυχὴν ἀφίησιν."},{"number":148,"text":"ὁ δὲ ἀνὴρ αὐτῆς οἰόμενος ὕπνῳ βαθεῖ κατεισχῆσθαι τὴν γυναῖκα καὶ μηδὲν σκυθρωπὸν ὑφορώμενος ἀνεγείρειν ἐπειρᾶτο παραμυθήσασθαι διεγνωκώς, ὡς οὐκ ἐξ ἑκουσίου γνώμης αὑτὴν παράσχοι τοῖς καθυβρίσασιν, ἀλλʼ ἁρπασαμένων ἐπὶ τὴν ξενίαν ἐλθόντων αὐτῶν."},{"number":149,"text":"ὡς δὲ τελευτήσασαν ἔμαθε, σωφρόνως πρὸς τὸ μέγεθος τῶν κακῶν ἐπιθέμενος τῷ κτήνει νεκρὰν τὴν γυναῖκα κομίζει πρὸς αὑτόν, καὶ διελὼν αὐτὴν κατὰ μέλος εἰς μέρη δώδεκα διέπεμψεν εἰς ἑκάστην φυλὴν ἐντειλάμενος τοῖς κομίζουσι λέγειν τοὺς αἰτίους τῆς τελευτῆς τῇ γυναικὶ καὶ τὴν παροινίαν τῆς φυλῆς."},{"number":150,"text":"Οἱ δʼ ὑπό τε τῆς ὄψεως καὶ τῆς ἀκοῆς τῶν βεβιασμένων κακῶς διατεθέντες πρότερον οὐδενὸς τοιούτου πεῖραν εἰληφότες, ὑπʼ ὀργῆς ἀκράτου καὶ δικαίας εἰς τὴν Σιλοῦν συλλεγέντες καὶ πρὸ τῆς σκηνῆς ἀθροισθέντες εἰς ὅπλα χωρεῖν εὐθὺς ὥρμηντο καὶ χρήσασθαι τοῖς Γαβαηνοῖς ὡς πολεμίοις."},{"number":151,"text":"ἐπέσχε δʼ αὐτοὺς ἡ γερουσία πείσασα μὴ δεῖν ὀξέως οὕτως πρὸς τοὺς ὁμοφύλους ἐκφέρειν πόλεμον πρὶν ἢ λόγοις διαλεχθῆναι περὶ τῶν ἐγκλημάτων, τοῦ νόμου μηδʼ ἐπὶ τοὺς ἀλλοτρίους ἐφιέντος δίχα πρεσβείας καὶ τοιαύτης πρὸς τὸ μετανοῆσαι πείρας τοὺς δόξαντας ἀδικεῖν στρατιὰν ἀγαγεῖν·"},{"number":152,"text":"καλῶς οὖν ἔχει τῷ νόμῳ πειθομένους πρὸς τοὺς Γαβαηνοὺς ἐξαιτοῦντας τοὺς αἰτίους ἐκπέμψαι καὶ παρεχομένων μὲν ἀρκεῖσθαι τῇ τούτων κολάσει, καταφρονησάντων δὲ τότε τοῖς ὅπλοις αὐτοὺς ἀμύνασθαι."},{"number":153,"text":"πέμπουσιν οὖν πρὸς τοὺς Γαβαηνοὺς κατηγοροῦντες τῶν νεανίσκων τὰ περὶ τὴν γυναῖκα καὶ πρὸς τιμωρίαν αἰτοῦντες τοὺς δράσαντας μὲν οὐ νόμιμα, γενομένους δὲ δικαίους ἀντʼ αὐτῶν ἐκείνων ἀποθανεῖν."},{"number":154,"text":"οἱ δὲ Γαβαηνοὶ οὔτε τοὺς νεανίσκους ἐξέδοσαν καὶ δεινὸν ἀλλοτρίοις ὑπακούειν προστάγμασιν ἡγοῦντο πολέμου φόβῳ μηδενὸς ἀξιοῦντες εἶναι χείρους ἐν τοῖς ὅπλοις μήτε διὰ πλῆθος μήτε διʼ εὐψυχίαν. ἦσαν δὲ ἐν παρασκευῇ μεγάλῃ καὶ τῶν ἄλλων φυλετῶν, συναπενοήθησαν γὰρ αὐτοῖς ὡς ἀμυνούμενοι βιαζομένους."},{"number":155,"text":"Ὡς δὲ τοιαῦτα τοῖς Ἰσραηλίταις τὰ παρὰ τῶν Γαβαηνῶν ἀπηγγέλθη, ὅρκους ποιοῦνται μηδένα σφῶν ἀνδρὶ Βενιαμίτῃ δώσειν πρὸς γάμον θυγατέρα στρατεύσειν τε ἐπʼ αὐτούς, μᾶλλον αὐτοῖς διʼ ὀργῆς ὄντες ἢ τοῖς Χαναναίοις τοὺς προγόνους ἡμῶν παρειλήφαμεν γενομένους."},{"number":156,"text":"παραχρῆμά τε ἐξῆγον ἐπʼ αὐτοὺς τὸ στρατόπεδον μυριάδας τεσσαράκοντα ὁπλιτῶν· καὶ Βενιαμιτῶν τὸ ὁπλιτικὸν ἦν ὑπὸ δισμυρίων καὶ πεντακισχιλίων καὶ ἑξακοσίων, ὧν ἦσαν εἰς πεντακοσίους ταῖς λαιαῖς τῶν χειρῶν σφενδονᾶν ἄριστοι,"},{"number":157,"text":"ὥστε καὶ μάχης πρὸς τῇ Γαβᾷ γενομένης τρέπουσι τοὺς Ἰσραηλίτας οἱ Βενιαμῖται ἄνδρες τε πίπτουσιν ἐξ αὐτῶν εἰς δισμυρίους καὶ δισχιλίους, ἐφθάρησαν δὲ ἴσως ἂν καὶ πλείονες, εἰ μὴ νὺξ αὐτοὺς ἐπέσχε καὶ διέλυσε μαχομένους."},{"number":158,"text":"καὶ οἱ μὲν Βενιαμῖται χαίροντες ἀνεχώρουν εἰς τὴν πόλιν, οἱ δʼ Ἰσραηλῖται καταπεπληγότες ὑπὸ τῆς ἥττης εἰς τὸ στρατόπεδον. τῇ δʼ ἐπιούσῃ πάλιν συμβαλόντων οἱ Βενιαμῖται κρατοῦσι καὶ θνήσκουσι τῶν Ἰσραηλιτῶν ὀκτακισχίλιοι καὶ μύριοι, καὶ δείσαντες τὸν φόνον ἐξέλιπον τὸ στρατόπεδον."},{"number":159,"text":"παραγενόμενοι δὲ εἰς Βέθηλα πόλιν ἔγγιστα κειμένην καὶ νηστεύσαντες κατὰ τὴν ὑστεραίαν τὸν θεὸν ἱκέτευον διὰ Φινεέσου τοῦ ἀρχιερέως παύσασθαι τῆς ὀργῆς τῆς πρὸς αὐτοὺς καὶ ταῖς δυσὶν αὐτῶν ἥτταις ἀρκεσθέντα δοῦναι νίκην καὶ κράτος κατὰ τῶν πολεμίων. ὁ δὲ θεὸς ἐπαγγέλλεται ταῦτα διὰ Φινεέσου προφητεύσαντος."},{"number":160,"text":"Ποιήσαντες οὖν τὴν στρατιὰν δύο μέρη τὴν μὲν ἡμίσειαν προλοχίζουσι νυκτὸς περὶ τὴν πόλιν, οἱ δʼ ἡμίσεις συνέβαλον τοῖς Βενιαμίταις ὑπεχώρουν τε ἐγκειμένων, καὶ ἐδίωκον οἱ Βενιαμῖται τῶν Ἑβραίων ὑποφευγόντων ἠρέμα καὶ ἐπὶ πολὺ θελόντων εἰς ἅπαν αὐτοὺς ἐξελθεῖν ἀναχωροῦσιν εἵποντο,"},{"number":161,"text":"ὡς καὶ τοὺς ἐν τῇ πόλει πρεσβύτας καὶ νέους ὑπολειφθέντας διεκδραμεῖν διʼ ἀσθένειαν αὐτοῖς πασσυδὶ βουλομένους χειρώσασθαι τοὺς πολεμίους. ὡς δὲ πολὺ τῆς πόλεως ἀπέσχον, ἐπαύσαντο μὲν φεύγοντες οἱ Ἑβραῖοι, ἐπιστραφέντες δʼ ἵστανται πρὸς μάχην καὶ τοῖς ἐν ταῖς ἐνέδραις οὖσι τὸ σημεῖον αἴρουσιν ὃ συνέκειτο."},{"number":162,"text":"οἱ δʼ ἐξαναστάντες μετὰ βοῆς ἐπῄεσαν τοῖς πολεμίοις. οἱ δὲ ἅμα τε ἠπατημένους αὑτοὺς ᾔσθοντο καὶ ἐν ἀμηχανίᾳ συνεστήκεσαν, καὶ εἴς τι κοῖλον συνελαθέντας καὶ φαραγγῶδες χωρίον περιστάντες κατηκόντισαν, ὥστε πάντας διαφθαρῆναι πλὴν ἑξακοσίων."},{"number":163,"text":"οὗτοι δὲ συστραφέντες καὶ πυκνώσαντες ἑαυτοὺς καὶ διὰ μέσων ὠσάμενοι τῶν πολεμίων ἔφυγον ἐπὶ τὰ πλησίον ὄρη, καὶ κατασχόντες ἱδρύθησαν. οἱ δʼ ἄλλοι πάντες περὶ δισμυρίους ὄντες καὶ πεντακισχιλίους ἀπέθανον."},{"number":164,"text":"οἱ δʼ Ἰσραηλῖται τήν τε Γάβαν ἐμπιπρᾶσι καὶ τὰς γυναῖκας καὶ τῶν ἀρρένων τοὺς μὴ ἐν ἀκμῇ διεχρήσαντο, τάς τε ἄλλας τῶν Βενιαμιτῶν πόλεις ταὐτὰ δρῶσιν, οὕτως τε ἦσαν παρωξυμμένοι, ὡς καὶ Ἰάβησον τῆς Γαλαδίτιδος οὖσαν, ὅτι μὴ συμμαχήσειεν αὐτοῖς κατὰ τῶν Βενιαμιτῶν, πέμψαντες μυρίους καὶ δισχιλίους ἐκ τῶν τάξεων ἐκέλευσαν ἀνελεῖν."},{"number":165,"text":"καὶ φονεύουσι τὸ μάχιμον τῆς πόλεως οἱ πεμφθέντες σὺν τέκνοις καὶ γυναιξὶ πλὴν τετρακοσίων παρθένων. ἐπὶ τοσοῦτον ὑπʼ ὀργῆς προήχθησαν τῷ κατὰ τὴν γυναῖκα πάθει προσλαβόντες καὶ τὸ κατὰ τὴν ἀναίρεσιν τῶν ὁπλιτῶν."},{"number":166,"text":"Μετάνοια δʼ αὐτοὺς λαμβάνει τῆς τῶν Βενιαμιτῶν συμφορᾶς καὶ νηστείαν ἐπʼ αὐτοῖς προέθεντο καίτοι δίκαια παθεῖν αὐτοὺς ἀξιοῦντες εἰς τοὺς νόμους ἐξαμαρτάνοντας, καὶ τοὺς διαφυγόντας αὐτῶν ἑξακοσίους διὰ πρεσβευτῶν ἐκάλουν· καθίδρυντο γὰρ ὑπὲρ πέτρας τινὸς Ῥοᾶς καλουμένης κατὰ τὴν ἔρημον."},{"number":167,"text":"οἱ δὲ πρέσβεις ὡς οὐκ ἐκείνοις τῆς συμφορᾶς μόνοις γεγενημένης ἀλλὰ καὶ αὐτοῖς τῶν συγγενῶν ἀπολωλότων ὀδυρόμενοι πρᾴως ἔπειθον φέρειν καὶ συνελθεῖν εἰς ταὐτὸ καὶ μὴ παντελῆ τῆς Βενιαμίτιδος φυλῆς ὄλεθρον τό γε ἐπʼ αὐτοῖς καταψηφίσασθαι. συγχωροῦμεν δὲ ὑμῖν, ἔλεγον, τὴν ἁπάσης τῆς φυλῆς γῆν καὶ λείαν ὅσην ἂν ἄγειν δυνηθῆτε ."},{"number":168,"text":"οἱ δὲ τῶν καθʼ ἑαυτοὺς θεοῦ ψήφῳ γεγονότων καὶ κατʼ ἀδικίαν τὴν αὐτῶν γνωσιμαχήσαντες κατῄεσαν εἰς τὴν πάτριον φυλὴν πειθόμενοι τοῖς προκαλουμένοις. οἱ δʼ Ἰσραηλῖται γυναῖκας αὐτοῖς τὰς τετρακοσίας ἔδοσαν παρθένους τὰς Ἰαβίτιδας, περὶ δὲ τῶν διακοσίων ἐσκόπουν, ὅπως κἀκεῖνοι γυναικῶν εὐπορήσαντες παιδοποιῶνται."},{"number":169,"text":"γεγενημένων δὲ αὐτοῖς ὅρκων ὥστε μηδενὶ Βενιαμίτῃ συνοικίσαι θυγατέρα πρὸ τοῦ πολέμου, οἱ μὲν ὀλιγωρεῖν συνεβούλευον τῶν ὀμωμοσμένων ὡς ὑπʼ ὀργῆς ὀμόσαντες οὐ γνώμῃ καὶ κρίσει, τῷ δὲ θεῷ μηδὲν ἐναντίον ποιήσειν εἰ φυλὴν ὅλην κινδυνεύουσαν ἀπολέσθαι σῶσαι δυνηθεῖεν, τάς τε ἐπιορκίας οὐχ ὅταν ὑπὸ ἀνάγκης γένωνται χαλεπὰς εἶναι καὶ ἐπισφαλεῖς, ἀλλʼ ὅταν ἐν κακουργίᾳ τολμηθῶσι."},{"number":170,"text":"τῆς δὲ γερουσίας πρὸς τὸ τῆς ἐπιορκίας ὄνομα σχετλιασάσης ἔφη τις τούτοις τε γυναικῶν εὐπορίαν ἔχειν εἰπεῖν καὶ τήρησιν τῶν ὅρκων. ἐρομένων δὲ τὴν ἐπίνοιαν, ἡμῖν, εἶπεν, τρὶς τοῦ ἔτους εἰς Σιλὼ συνιοῦσιν ἕπονται κατὰ πανήγυριν αἱ γυναῖκες καὶ αἱ θυγατέρες."},{"number":171,"text":"τούτων κατὰ ἁρπαγὴν ἐφείσθω γαμεῖν Βενιαμίτας ἃς ἂν δυνηθεῖεν ἡμῶν οὔτε προτρεπομένων οὔτε κωλυόντων. πρὸς δὲ τοὺς πατέρας αὐτῶν δυσχεραίνοντας καὶ τιμωρίαν λαμβάνειν ἀξιοῦντας φήσομεν αὐτοὺς αἰτίους φυλακῆς ἀμελήσαντας τῶν θυγατέρων, ὅτι δὲ δεῖ τῆς ὀργῆς ἐπὶ Βενιαμίτας ὑφεῖναι χρησαμένους αὐτῇ καὶ θᾶττον ἀμέτρως ."},{"number":172,"text":"καὶ οἱ μὲν τούτοις πεισθέντες ψηφίζονται τὸν διὰ τῆς ἁρπαγῆς γάμον τοῖς Βενιαμίταις. ἐνστάσης δὲ τῆς ἑορτῆς οἱ μὲν διακόσιοι κατὰ δύο καὶ τρεῖς πρὸ τῆς πόλεως ἐνήδρευον παρεσομένας τὰς παρθένους ἔν τε ἀμπελῶσι καὶ χωρίοις ἐν οἷς λήσειν ἔμελλον,"},{"number":173,"text":"αἱ δὲ μετὰ παιδιᾶς οὐδὲν ὑφορώμεναι τῶν μελλόντων ἀφυλάκτως ὥδευον· οἱ δὲ σκεδασθεισῶν εἴχοντο ἐξαναστάντες. καὶ οὗτοι μὲν οὕτως γαμήσαντες ἐπʼ ἔργα τῆς γῆς ἐχώρησαν καὶ πρόνοιαν ἐποιήσαντο πάλιν εἰς τὴν προτέραν εὐδαιμονίαν ἐπανελθεῖν."},{"number":174,"text":"Βενιαμιτῶν μὲν οὖν ἡ φυλὴ κινδυνεύσασα τελέως ἐκφθαρῆναι τῷ προειρημένῳ τρόπῳ κατὰ τὴν Ἰσραηλιτῶν σοφίαν σώζεται ἤνθησέ τε παραχρῆμα καὶ ταχεῖαν εἴς τε πλῆθος καὶ τὰ ἄλλα πάντα ἐποιήσατο τὴν ἐπίδοσιν. οὗτος μὲν οὖν ὁ πόλεμος οὕτως παύεται."}],"3":[{"number":175,"text":"Ὅμοια δὲ τούτοις παθεῖν καὶ τὴν Δάνην συνέβη φυλὴν ἐξ αἰτίας τοιαύτης εἰς τοῦτο προαχθεῖσαν."},{"number":176,"text":"τῶν Ἰσραηλιτῶν ἐκλελοιπότων ἤδη τὴν ἐν τοῖς πολέμοις ἄσκησιν καὶ πρὸς τοῖς ἔργοις ὄντων τῆς γῆς Χαναναῖοι καταφρονήσαντες αὐτῶν συνεποιήσαντο δύναμιν, οὐδὲν μὲν αὐτοὶ πείσεσθαι προσδοκῶντες, ὡς δὲ βεβαίαν τὴν τοῦ ποιήσειν κακῶς τοὺς Ἑβραίους ἐλπίδα λαβόντες ἐπʼ ἀδείας τὸ λοιπὸν οἰκεῖν τὰς πόλεις ἠξίουν."},{"number":177,"text":"ἅρματά τε οὖν παρεσκευάζοντο καὶ τὸ ὁπλιτικὸν συνεκρότουν αἵ τε πόλεις αὐτῶν συνεφρόνουν καὶ τῆς Ἰούδα φυλῆς τὴν Ἀσκάλωνα καὶ Ἀκαρῶνα παρεσπάσαντο ἄλλας τε πολλὰς τῶν ἐν τῷ πεδίῳ καὶ Δανίτας εἰς τὸ ὄρος ἠνάγκασαν συμφυγεῖν οὐδὲ ὀλίγον αὐτοῖς ἐπιβατὸν τοῦ πεδίου καταλιπόντες."},{"number":178,"text":"οἱ δʼ οὔτε πολεμεῖν ὄντες ἱκανοὶ γῆν τε οὐκ ἔχοντες ἀρκοῦσαν πέμπουσιν ἐξ αὐτῶν πέντε ἄνδρας εἰς τὴν μεσόγειον κατοψομένους γῆν, εἰς ἣν μετοικήσαιντο. οἱ δʼ οὐ πόρρω τοῦ Λιβάνου ὄρους καὶ ἐλάσσονος Ἰορδάνου τῶν πηγῶν κατὰ τὸ μέγα πεδίον Σιδῶνος πόλεως ὁδὸν ἡμέρας μιᾶς προελθόντες καὶ κατασκεψάμενοι γῆν ἀγαθὴν καὶ πάμφορον σημαίνουσι τοῖς αὑτῶν· οἱ δʼ ὁρμηθέντες στρατῷ κτίζουσιν αὐτόθι πόλιν Δάνα ὁμώνυμον τῷ Ἰακώβου παιδὶ φυλῆς δʼ ἐπώνυμον τῆς αὐτῶν."},{"number":179,"text":"Τοῖς δʼ Ἰσραηλίταις προύβαινεν ὑπό τε ἀπειρίας τοῦ πονεῖν τὰ κακὰ καὶ ἀπὸ τῆς περὶ τὸ θεῖον ὀλιγωρίας· μετακινηθέντες γὰρ ἅπαξ τοῦ κόσμου τῆς πολιτείας ἐφέροντο πρὸς τὸ καθʼ ἡδονὴν καὶ βούλησιν ἰδίαν βιοῦν, ὡς καὶ τῶν ἐπιχωριαζόντων παρὰ τοῖς Χαναναίοις ἀναπίμπλασθαι κακῶν."},{"number":180,"text":"ὀργίζεται τοίνυν αὐτοῖς ὁ θεὸς καὶ ἣν σὺν πόνοις μυρίοις εὐδαιμονίαν ἐκτήσαντο, ταύτην ἀπέβαλον διὰ τρυφήν. στρατεύσαντος γὰρ ἐπʼ αὐτοὺς Χουσαρσάθου τοῦ τῶν Ἀσσυρίων βασιλέως πολλούς τε τῶν παραταξαμένων ἀπώλεσαν καὶ πολιορκούμενοι κατὰ κράτος ᾑρέθησαν,"},{"number":181,"text":"εἰσὶ δʼ οἳ διὰ φόβον ἑκουσίως αὐτῷ προσεχώρησαν, φόρους τε τοῦ δυνατοῦ μείζονας ἐπιταγέντες ἐτέλουν καὶ ὕβρεις παντοίας ὑπέμενον ἕως ἐτῶν ὀκτώ, μεθʼ ἃ τῶν κακῶν οὕτως ἠλευθερώθησαν."},{"number":182,"text":"Τῆς Ἰούδα φυλῆς τις Κενίαζος ὄνομα δραστήριος ἀνὴρ καὶ τὸ φρόνημα γενναῖος, χρησθὲν αὐτῷ μὴ περιορᾶν ἐν τοιαύτῃ τοὺς Ἰσραηλίτας ἀνάγκῃ κειμένους ἀλλʼ εἰς ἐλευθερίαν αὐτοὺς ἐξαιρεῖσθαι τολμᾶν, παρακελευσάμενος συλλαμβάνεσθαι τῶν κινδύνων αὐτῷ τινάς, ὀλίγοι δʼ ἦσαν, οἷς αἰδὼς ἐπὶ τοῖς τότε παροῦσιν ἐτύγχανε καὶ προθυμία μεταβολῆς,"},{"number":183,"text":"πρῶτον μὲν τὴν παρʼ αὐτοῖς οὖσαν φρουρὰν τοῦ Χουσαρσάθου διαφθείρει, προσγενομένων δὲ πλειόνων τῶν συναγωνιζομένων ἐκ τοῦ μὴ διαμαρτεῖν περὶ τὰ πρῶτα τῆς ἐπιχειρήσεως, μάχην τοῖς Ἀσσυρίοις συνάπτουσι καὶ πρὸς τὸ παντελὲς αὐτοὺς ἀπωσάμενοι περαιοῦσθαι τὸν Εὐφράτην ἐβιάζοντο."},{"number":184,"text":"Κενίαζος δὲ ὡς ἔργῳ πεῖραν αὐτοῦ δεδωκὼς τῆς ἀνδραγαθίας γέρας ὑπὲρ αὐτῆς λαμβάνει παρὰ τοῦ πλήθους ἀρχήν, ὥστε κρίνειν τὸν λαόν. καὶ ἄρξας ἐπʼ ἔτη τεσσαράκοντα καταστρέφει τὸν βίον."}],"4":[{"number":185,"text":"Τελευτήσαντος δὲ τούτου πάλιν τὰ τῶν Ἰσραηλιτῶν ὑπὸ ἀναρχίας ἐνόσει πράγματα, καὶ τῷ μὴ διὰ τιμῆς ἄγειν τὸν θεὸν μηδὲ τοῖς νόμοις ὑπακούειν ἔτι μᾶλλον ἐκακοῦτο,"},{"number":186,"text":"ὡς καταφρονήσαντα αὐτῶν τῆς ἀκοσμίας τῆς κατὰ τὴν πολιτείαν Ἐγλῶνα τὸν Μωαβιτῶν βασιλέα πόλεμον πρὸς αὐτοὺς ἐξενεγκεῖν καὶ πολλαῖς μάχαις αὐτῶν κρατήσαντα καὶ τοὺς φρονήματι τῶν ἄλλων διαφέροντας ὑποτάξαντα πρὸς τὸ παντελὲς αὐτῶν τὴν δύναμιν ταπεινῶσαι καὶ φόρους αὐτοῖς ἐπιτάξαι τελεῖν."},{"number":187,"text":"καθιδρύσας δʼ αὐτῷ ἐν Ἱεριχοῦντι βασίλειον ταύτην ἀποδείξας οὐδὲν τῆς εἰς τὸ πλῆθος κακώσεως παρέλιπεν εἴς τε πενίαν αὐτοὺς κατέστησεν ἐπὶ ὀκτωκαίδεκα ἔτη. λαβὼν δʼ οἶκτον ὁ θεὸς τῶν Ἰσραηλιτῶν ἐφʼ οἷς ἔπασχον καὶ ταῖς ἱκετείαις αὐτῶν ἐπικλασθεὶς ἀπήλλαξε τῆς ὑπὸ τοῖς Μωαβίταις ὕβρεως. ἠλευθερώθησαν δὲ τούτῳ τῷ τρόπῳ."},{"number":188,"text":"Τῆς Βενιαμίτιδος φυλῆς νεανίας Ἰούδης μὲν τοὔνομα Γήρα τε πατρὸς τολμῆσαί τε ἀνδρειότατος καὶ τῷ σώματι πρὸς τὰ ἔργα χρῆσθαι δυνατὸς τῶν χειρῶν τὴν ἀριστερὰν ἀμείνων κἀπʼ ἐκείνης τὴν ἅπασαν ἰσχὺν ἔχων κατῴκει μὲν ἐν Ἱεριχοῦντι καὶ αὐτός,"},{"number":189,"text":"συνήθης δὲ γίνεται τῷ Ἐγλῶνι δωρεαῖς αὐτὸν θεραπεύων καὶ ὑπερχόμενος, ὡς διὰ τοῦτο καὶ τοῖς περὶ τὸν βασιλέα προσφιλῆ τυγχάνειν αὐτόν."},{"number":190,"text":"καί ποτε σὺν δυσὶν οἰκέταις δῶρα τῷ βασιλεῖ φέρων ξιφίδιον κρύφα τῷ δεξιῷ σκέλει περιδησάμενος εἰσῄει πρὸς αὐτόν. ὥρα δʼ ἦν θέρους καὶ τῆς ἡμέρας ἤδη μεσούσης ἀνεῖντο αἱ φυλακαὶ ὑπό τε τοῦ καύματος καὶ πρὸς ἄριστον τετραμμένων."},{"number":191,"text":"δοὺς οὖν τὰ δῶρα τῷ Ἐγλῶνι ὁ νεανίσκος, διέτριβε δʼ ἔν τινι δωματίῳ δεξιῶς πρὸς θέρος ἔχοντι, πρὸς ὁμιλίαν ἐτράποντο. μόνοι δʼ ἦσαν τοῦ βασιλέως καὶ τοὺς ἐπεισιόντας τῶν θεραπόντων ἀπιέναι κελεύσαντος διὰ τὸ πρὸς Ἰούδην ὁμιλεῖν."},{"number":192,"text":"καθῆστο δʼ ἐπὶ θρόνου καὶ δέος εἰσῄει τὸν Ἰούδην, μὴ διαμάρτῃ καὶ μὴ δῷ καιρίαν πληγήν. ἀνίστησιν οὖν αὐτὸν ὄναρ εἰπὼν ἔχειν ἐκ προστάγματος αὐτῷ δηλῶσαι τοῦ θεοῦ."},{"number":193,"text":"καὶ ὁ μὲν πρὸς τὴν χαρὰν τὴν τοῦ ὀνείρατος ἀνεπήδησεν ἀπὸ τοῦ θρόνου, πλήξας δʼ αὐτὸν Ἰούδης εἰς τὴν καρδίαν καὶ τὸ ξιφίδιον ἐγκαταλιπὼν ἔξεισι προσκλίνας τὴν θύραν. οἵ τε θεράποντες ἠρέμουν εἰς ὕπνον τετράφθαι νομίζοντες τὸν βασιλέα."},{"number":194,"text":"Ὁ δʼ Ἰούδης τοῖς Ἱεριχουντίοις ἀποσημαίνων κρυπτῶς παρεκάλει τῆς ἐλευθερίας ἀντιλαμβάνεσθαι. οἱ δʼ ἀσμένως ἀκούσαντες αὐτοί τε εἰς τὰ ὅπλα ᾔεσαν καὶ διέπεμπον εἰς τὴν χώραν τοὺς ἀποσημαίνοντας κέρασιν οἰῶν· τούτοις γὰρ συγκαλεῖν τὸ πλῆθος πάτριον."},{"number":195,"text":"οἱ δὲ περὶ τὸν Ἐγλῶνα πολὺν μὲν χρόνον ἠγνόουν τὸ συμβεβηκὸς αὐτῷ πάθος, ἐπεὶ δὲ πρὸς ἑσπέραν ἦν, δείσαντες μή τι νεώτερον εἴη περὶ αὐτὸν γεγονός, εἰσῆλθον εἰς τὸ δωμάτιον καὶ νεκρὸν εὑρόντες ἐν ἀμηχανίᾳ καθειστήκεσαν, καὶ πρὶν τὴν φρουρὰν συστραφῆναι τὸ τῶν Ἰσραηλιτῶν αὐτοῖς ἐπέρχεται πλῆθος."},{"number":196,"text":"καὶ οἱ μὲν παραχρῆμα ἀναιροῦνται, οἱ δʼ εἰς φυγὴν τρέπονται ὡς ἐπὶ τὴν Μωαβῖτιν σωθησόμενοι, ἦσαν δὲ ὑπὲρ μυρίους. καὶ Ἰσραηλῖται προκατειληφότες τοῦ Ἰορδάνου τὴν διάβασιν διώκοντες ἔκτεινον καὶ κατὰ τὴν διάβασιν πολλοὺς αὐτῶν ἀναιροῦσι, διέφυγέ τε οὐδεὶς τὰς χεῖρας αὐτῶν."},{"number":197,"text":"καὶ οἱ μὲν Ἑβραῖοι τούτῳ τῷ τρόπῳ τῆς ὑπὸ τοῖς Μωαβίταις δουλείας ἀπηλλάγησαν, Ἰούδης δʼ ἐκ τῆς αἰτίας ταύτης τιμηθεὶς τῇ τοῦ πλήθους παντὸς ἡγεμονίᾳ τελευτᾷ τὴν ἀρχὴν ἔτεσιν ὀγδοήκοντα κατασχών, ἀνὴρ καὶ δίχα τῆς προειρημένης πράξεως ἐπαίνου δίκαιος τυγχάνειν. καὶ μετὰ τοῦτον Σαάγαρος ὁ Ἀνάθου παῖς αἱρεθεὶς ἄρχειν ἐν τῷ πρώτῳ τῆς ἀρχῆς ἔτει κατέστρεψε τὸν βίον."}],"5":[{"number":198,"text":"Ἰσραηλῖται δὲ πάλιν, οὐδὲν γὰρ ἐπὶ διδαχῇ τοῦ κρείττονος ἐλάμβανον τῶν πρότερον ἠτυχημένων ὑπό τε τοῦ μήτε σέβειν τὸν θεὸν μήθʼ ὑπακούειν τοῖς νόμοις, πρὶν ἢ καὶ τῆς ὑπὸ Μωαβίταις ἀναπνεῦσαι δουλείας πρὸς ὀλίγον Ἀβίτω τοῦ Χαναναίων βασιλέως δουλοῦνται."},{"number":199,"text":"οὗτος γὰρ ἐξ Ἀσώρου πόλεως ὁρμώμενος, αὕτη δʼ ὑπέρκειται τῆς Σεμαχωνίτιδος λίμνης, στρατοῦ μὲν ὁπλιτῶν τριάκοντα ἔτρεφε μυριάδας μυρίους δὲ ἱππέας, τρισχιλίων δὲ ἁρμάτων ηὐπόρει. ταύτης οὖν στρατηγὸς τῆς δυνάμεως Σισάρης τιμῆς πρώτης παρὰ τῷ βασιλεῖ τυγχάνων συνελθόντας πρὸς αὐτὸν τοὺς Ἰσραηλίτας ἐκάκωσε δεινῶς, ὥστε αὐτοῖς ἐπιτάξαι τελεῖν φόρους."},{"number":200,"text":"Εἴκοσι μὲν οὖν ἔτη ταῦτα πάσχοντες ἤνυσαν μήτε αὐτοὶ φρονεῖν ὑπὸ τῆς δυστυχίας ὄντες ἀγαθοὶ καὶ τοῦ θεοῦ πλέον δαμάσαι ἔτι θέλοντος αὐτῶν τὴν ὕβριν διὰ τὴν περὶ αὐτὸν ἀγνωμοσύνην, ἵνα μεταθέμενοι τοῦ λοιποῦ σωφρονῶσιν διδαχθέντες τὰς συμφορὰς αὐτοῖς ἐκ τῆς περιφρονήσεως τῶν νόμων ὑπάρξαι, Δαβώραν δέ τινα προφῆτιν,"},{"number":201,"text":"μέλισσαν δὲ σημαίνει τοὔνομα κατὰ τὴν Ἑβραίων γλῶσσαν, ἱκέτευον δεηθῆναι τοῦ θεοῦ λαβεῖν οἶκτον αὐτῶν καὶ μὴ περιιδεῖν ἀπολλυμένους αὐτοὺς ὑπὸ Χαναναίων. ὁ δὲ θεὸς ἐπένευσε σωτηρίαν αὐτοῖς καὶ στρατηγὸν αἱρεῖται Βάρακον τῆς Νεφθαλίδος ὄντα φυλῆς· βάρακος δέ ἐστιν ἀστραπὴ κατὰ τὴν Ἑβραίων γλῶσσαν."},{"number":202,"text":"Μεταπεμψαμένη δʼ ἡ Δαβώρα τὸν Βάρακον ἐπιλέξαντα τῶν νέων μυρίους ἐκέλευε χωρεῖν ἐπὶ τοὺς πολεμίους· ἀποχρῆναι γὰρ τοσούτους τοῦ θεοῦ προειρηκότος καὶ νίκην ἀποσημήναντος."},{"number":203,"text":"Βαράκου δὲ φαμένου οὐ στρατηγήσειν μὴ κἀκείνης αὐτῷ συστρατηγούσης ἀγανακτήσασα, σὺ μέν, εἶπε, γυναικὶ παραχωρεῖς ἀξίωμα ὃ σοὶ δέδωκεν ὁ θεός, ἐγὼ δὲ οὐ παραιτοῦμαι . καὶ συναριθμήσαντες μυρίους ἐστρατοπεδεύσαντο πρὸς Ἰταβυρίῳ ὄρει."},{"number":204,"text":"ἀπήντα δʼ αὐτοῖς ὁ Σισάρης τοῦ βασιλέως κελεύσαντος καὶ στρατοπεδεύονται τῶν πολεμίων οὐκ ἄπωθεν. τοὺς δʼ Ἰσραηλίτας καὶ τὸν Βάρακον καταπλαγέντας τὸ πλῆθος τῶν πολεμίων καὶ ἀναχωρεῖν διεγνωκότας ἡ Δεβώρα κατεῖχε τὴν συμβολὴν ποιεῖσθαι κατʼ ἐκείνην κελεύουσα τὴν ἡμέραν· νικήσειν γὰρ αὐτοὺς καὶ συλλήψεσθαι τὸν θεόν."},{"number":205,"text":"Συνῄεσαν οὖν καὶ προσμιγέντων ὄμβρος ἐπιγίνεται μέγας καὶ ὕδωρ πολὺ καὶ χάλαζα, τόν τε ὑετὸν κατὰ πρόσωπον ἤλαυνε τῶν Χαναναίων ἄνεμος ταῖς ὄψεσιν αὐτῶν ἐπισκοτῶν, ὡς τὰς τοξείας ἀχρήστους αὐτοῖς εἶναι καὶ τὰς σφενδόνας· οἵ τε ὁπλῖται διὰ τὸ κρύος χρῆσθαι τοῖς ξίφεσιν οὐκ εἶχον."},{"number":206,"text":"τοὺς δʼ Ἰσραηλίτας ἧττόν τε ἔβλαπτε κατόπιν γινόμενος ὁ χειμὼν καὶ πρὸς τὴν ἔννοιαν τῆς βοηθείας τοῦ θεοῦ θάρσος ἐλάμβανον, ὥστε εἰς μέσους ὠσάμενοι τοὺς πολεμίους πολλοὺς αὐτῶν ἀπέκτειναν. καὶ οἱ μὲν ὑπὸ τῶν Ἰσραηλιτῶν, οἱ δʼ ὑπὸ τῆς οἰκείας ἵππου ταραχθέντες ἔπεσον, ὡς ὑπὸ τῶν ἁρμάτων πολλοὺς αὐτῶν ἀποθανεῖν."},{"number":207,"text":"Σισάρης δὲ καταπηδήσας τοῦ ἅρματος ὡς εἶδε τὴν τροπὴν γινομένην, φυγὼν ἀφικνεῖται παρά τινα τῶν Κενελίδων γυναῖκα Ἰάλην ὄνομα, ἣ κρύψαι τε ἀξιώσαντα δέχεται καὶ ποτὸν αἰτήσαντι δίδωσι γάλα διεφθορὸς ἤδη."},{"number":208,"text":"ὁ δὲ πιὼν τοῦ μέτρου δαψιλέστερον εἰς ὕπνον τρέπεται. ἡ δὲ Ἰάλη κοιμωμένου σιδήρεον ἧλον ἐλάσασα σφύρῃ κατὰ τοῦ στόματος καὶ τοῦ χελυνίου διέπειρε τὸ ἔδαφος καὶ τοῖς περὶ τὸν Βάρακον μικρὸν ὕστερον ἐλθοῦσιν ἐπεδείκνυε τῇ γῇ προσηλωμένον."},{"number":209,"text":"καὶ οὕτως μὲν ἡ νίκη αὕτη περιέστη κατὰ τὰ ὑπὸ Δαβώρας εἰρημένα εἰς γυναῖκα. Βάρακος δὲ στρατεύσας ἐπʼ Ἄσωρον Ἰοαβινόν τε ὑπαντιάσαντα κτείνει καὶ τοῦ στρατηγοῦ πεσόντος καθελὼν εἰς ἔδαφος τὴν πόλιν στρατηγεῖ τῶν Ἰσραηλιτῶν ἐπʼ ἔτη τεσσαράκοντα."}],"6":[{"number":210,"text":"Τελευτήσαντος δὲ Βαράκου καὶ Δαβώρας κατὰ τὸν αὐτὸν καιρὸν μετὰ ταῦτα Μαδιηνῖται παρακαλέσαντες Ἀμαληκίτας τε καὶ Ἄραβας στρατεύουσιν ἐπὶ τοὺς Ἰσραηλίτας καὶ μάχῃ τε νικῶσι τοὺς συμβαλόντας καὶ τὸν καρπὸν δῃώσαντες τὴν λείαν ἐπήγοντο."},{"number":211,"text":"τοῦτο δὲ ποιούντων ἐπʼ ἔτη ἑπτὰ εἰς τὰ ὄρη τῶν Ἰσραηλιτῶν ἀνεστάλη τὸ πλῆθος καὶ τῶν πεδίων ἐξεχώρουν ὑπονόμους τε καὶ σπήλαια ποιησάμενοι πᾶν ὅ τι τοὺς πολεμίους διέφυγεν ἐν τούτοις εἶχον φυλάττοντες."},{"number":212,"text":"οἱ γὰρ Μαδιηνῖται κατὰ ὥραν θέρους στρατεύοντες τὸν χειμῶνα γεωργεῖν τοῖς Ἰσραηλίταις ἐπέτρεπον, ὅπως ἔχωσι πεπονηκότων αὐτῶν εἰς ἃ βλάπτωσι. λιμὸς δʼ ἦν καὶ σπάνις τροφῆς καὶ τρέπονται πρὸς ἱκετείαν τοῦ θεοῦ σώζειν αὐτοὺς παρακαλοῦντες."},{"number":213,"text":"Καὶ Γεδεὼν ὁ Ἰάσου παῖς Μανασσίδος φυλῆς ἐν ὀλίγοις δράγματα σταχύων φερόμενος κρυπτῶς εἰς τὴν ληνὸν ἔκοπτε· τοὺς γὰρ πολεμίους ἐδεδίει φανερῶς τοῦτο ποιεῖν ἐπὶ τῆς ἅλωος. φαντάσματος δὲ αὐτῷ παραστάντος νεανίσκου μορφῇ καὶ φήσαντος εὐδαίμονα καὶ φίλον τῷ θεῷ, ὑποτυχών τοῦτο γοῦν, ἔφη, τεκμήριον τῆς εὐμενείας αὐτοῦ μέγιστον τῇ ληνῷ με νῦν ἀντὶ ἅλωος χρῆσθαι ."},{"number":214,"text":"θαρσεῖν δὲ παρακελευσαμένου καὶ πειρᾶσθαι τῆς ἐλευθερίας ἀνασώζειν ἀδυνάτως ἔχειν ἔλεγε· τήν τε γὰρ φυλὴν ἐξ ἧς ὑπῆρχε πλήθους ὑστερεῖν καὶ νέον αὐτὸν εἶναι καὶ τηλικούτων πραγμάτων ἀσθενέστερον. ὁ δὲ θεὸς αὐτὸς ἀναπληρώσειν τὸ λεῖπον ἐπηγγέλλετο καὶ νίκην παρέξειν Ἰσραηλίταις αὐτοῦ στρατηγοῦντος."},{"number":215,"text":"Τοῦτʼ οὖν διηγούμενος ὁ Γεδεὼν τισὶ τῶν νέων ἐπιστεύετο, καὶ παραχρῆμα πρὸς τοὺς ἀγῶνας ἕτοιμον ἦν τὸ στρατόπεδον μυρίων ἀνδρῶν. ἐπιστὰς δὲ κατὰ τοὺς ὕπνους ὁ θεὸς τῷ Γεδεῶνι τὴν ἀνθρωπίνην φύσιν αὐτῷ φίλαυτον οὖσαν ἐδήλου καὶ πρὸς τοὺς ἀρετῇ διαφέροντας ἀπεχθανομένην, ὅπως τε τὴν νίκην παρέντες τοῦ θεοῦ δοκεῖν νομίζουσιν ἰδίαν ὡς πολὺς στρατὸς ὄντες καὶ πρὸς τοὺς πολεμίους ἀξιόμαχος."},{"number":216,"text":"ἵνα μάθωσιν οὖν βοηθείας τῆς αὐτοῦ τὸ ἔργον, συνεβούλευε περὶ μεσοῦσαν τὴν ἡμέραν ἐν ἀκμῇ τοῦ καύματος ὄντος ἄγειν τὴν στρατιὰν ἐπὶ τὸν ποταμὸν καὶ τοὺς μὲν κατακλιθέντας καὶ οὕτως πίνοντας εὐψύχους ὑπολαμβάνειν, ὅσοι δʼ ἂν ἐσπευσμένως καὶ μετὰ θορύβου πίνοντες τύχοιεν τούτους δειλοὺς νομίζειν καὶ καταπεπληγότας τοὺς πολεμίους."},{"number":217,"text":"ποιήσαντος δὲ τοῦ Γεδεῶνος κατὰ τὰς ὑποθήκας τοῦ θεοῦ τριακόσιοι ἄνδρες εὑρέθησαν ταῖς χερσὶ μετὰ φόβου προσενεγκάμενοι τὸ ὕδωρ τεταραγμένως, ἔφησέ τε ὁ θεὸς τούτους ἐπαγόμενον ἐπιχειρεῖν τοῖς πολεμίοις. ἐστρατοπεδεύοντο δὲ ὑπὲρ τοῦ Ἰορδάνου μέλλοντες εἰς τὴν ἐπιοῦσαν περαιοῦσθαι."},{"number":218,"text":"Γεδεῶνος δʼ ἐν φόβῳ καθεστῶτος, καὶ γὰρ νυκτὸς ἐπιχειρεῖν αὐτῷ ὁ θεὸς προειρήκει, τοῦ δέους αὐτὸν ἀπαγαγεῖν βουλόμενος κελεύει προσλαβόντα ἕνα τῶν στρατιωτῶν πλησίον χωρεῖν ταῖς Μαδιηνιτῶν σκηναῖς· παρʼ αὐτῶν γὰρ ἐκείνων λήψεσθαι φρόνημα καὶ θάρσος."},{"number":219,"text":"πεισθεὶς δὲ ᾔει Φρουρὰν τὸν ἑαυτοῦ θεράποντα παραλαβών, καὶ πλησιάσας σκηνῇ τινι καταλαμβάνει τοὺς ἐν αὐτῇ ἐγρηγορότας καὶ τὸν ἕτερον ὄναρ διηγούμενον τῷ συσκηνοῦντι, ὥστε ἀκούειν τὸν Γεδεῶνα. τὸ δὲ τοιοῦτον ἦν· μᾶζαν ἐδόκει κριθίνην ὑπʼ εὐτελείας ἀνθρώποις ἄβρωτον διὰ τοῦ στρατοπέδου κυλιομένην τὴν τοῦ βασιλέως σκηνὴν καταβαλεῖν καὶ τὰς τῶν στρατιωτῶν πάντων."},{"number":220,"text":"ὁ δὲ σημαίνειν ὄλεθρον τοῦ στρατοῦ τὴν ὄψιν ἔκρινε λέγων, ὅθεν τοῦτʼ αὐτῷ συνιδεῖν ἐπῆλθε, πᾶν τὸ σπέρμα τὸ καλούμενον κρίθινον εὐτελέστατον ὁμολογεῖσθαι τυγχάνειν, τοῦ δʼ Ἀσιανοῦ παντὸς τὸ Ἰσραηλιτῶν ἔστιν ἰδεῖν ἀτιμότερον νῦν γεγενημένον ὅμοιον δὲ τῷ κατὰ κριθὴν γένει."},{"number":221,"text":"καὶ τὸ παρὰ τοῖς Ἰσραηλίταις νῦν μεγαλοφρονοῦν τοῦτʼ ἂν εἴη Γεδεὼν καὶ τὸ σὺν αὐτῷ στρατιωτικόν. ἐπεὶ οὖν τὴν μᾶζαν φῂς ἰδεῖν τὰς σκηνὰς ἡμῶν ἀνατρέπουσαν, δέδια μὴ θεὸς Γεδεῶνι τὴν καθʼ ἡμῶν νίκην ἐπινένευκε."},{"number":222,"text":"Γεδεῶνα δʼ ἀκούσαντα τὸ ὄναρ ἐλπὶς ἀγαθὴ καὶ θάρσος ἔλαβε καὶ προσέταξεν ἐν τοῖς ὅπλοις εἶναι τοὺς οἰκείους διηγησάμενος αὐτοῖς καὶ τὴν τῶν πολεμίων ὄψιν, οἱ δʼ ἕτοιμοι πρὸς τὰ παραγγελλόμενα φρονηματισθέντες ὑπὸ τῶν δεδηλωμένων ἦσαν."},{"number":223,"text":"καὶ κατὰ τετάρτην μάλιστα φυλακὴν προσῆγε τὴν ἑαυτοῦ στρατιὰν Γεδεὼν εἰς τρία μέρη διελὼν αὐτήν, ἑκατὸν δὲ ἦσαν ἐν ἑκάστῳ. ἐκόμιζον δὲ πάντες ἀμφορέας κενοὺς καὶ λαμπάδας ἡμμένας ἐν αὐταῖς, ὅπως μὴ κατάφωρος τοῖς πολεμίοις ἡ ἔφοδος αὐτῶν γένηται, καὶ ἐν τῇ δεξιᾷ κριοῦ κέρας· ἐχρῶντο δὲ τούτοις ἀντὶ σάλπιγγος."},{"number":224,"text":"χωρίον δὲ πολὺ κατεῖχε τὸ τῶν πολεμίων στράτευμα, πλείστην γὰρ αὐτοῖς εἶναι συνέβαινε κάμηλον, καὶ κατὰ τὰ ἔθνη νεμηθέντες ὑφʼ ἑνὶ κύκλῳ πάντες ἦσαν."},{"number":225,"text":"οἱ δʼ Ἑβραῖοι, προειρημένον αὐτοῖς ὁπόταν γένωνται πλησίον τῶν πολεμίων ἐκ συνθήματος σάλπιγξί τε ἠχήσαντας καὶ τοὺς ἀμφορέας κατεάξαντας ὁρμῆσαι μετὰ τῶν λαμπάδων ἀλαλάξαντας καὶ νικᾶν θεοῦ Γεδεῶνι βοηθήσοντος, τοῦτʼ ἐποίησαν."},{"number":226,"text":"ταραχὴ δὲ λαμβάνει τοὺς ἀνθρώπους ἔτι τε ὑπνοῦντας καὶ δείματα· νὺξ γὰρ ἦν καὶ ὁ θεὸς τοῦτο ἤθελεν. ἐκτείνοντο δὲ ὀλίγοι μὲν ὑπὸ τῶν πολεμίων, οἱ δὲ πλείους ὑπὸ τῶν συμμάχων διὰ τὸ τῇ γλώσσῃ διαφωνεῖν. ἅπαξ δὲ καταστάντες εἰς ταραχὴν πᾶν τὸ προστυχὸν ἀνῄρουν νομίζοντες εἶναι πολέμιον, φόνος τε πολὺς ἦν."},{"number":227,"text":"καὶ φήμῃ πρὸς τοὺς Ἰσραηλίτας τῆς Γεδεῶνος νίκης ἀφικομένης ἐν τοῖς ὅπλοις ἦσαν, καὶ διώξαντες λαμβάνουσι τοὺς πολεμίους ἐν κοίλῳ τινὶ χαράδραις περιειλημμένῳ οὐ δυναμέναις διαπερᾶναι χωρίῳ καὶ περιστάντες κτείνουσιν ἅπαντας καὶ δύο τῶν βασιλέων Ὤρηβόν τε καὶ Ζῆβον."},{"number":228,"text":"οἱ δὲ λοιποὶ τῶν ἡγεμόνων τοὺς περιλειφθέντας τῶν στρατιωτῶν ἐνάγοντες, ἦσαν δὲ μύριοι καὶ ὀκτακισχίλιοι, στρατοπεδεύονται πολὺ τῶν Ἰσραηλιτῶν ἄπωθεν. Γεδεὼν δὲ οὐκ ἀπηγορεύκει πονῶν, ἀλλὰ διώξας μετὰ παντὸς τοῦ στρατοῦ καὶ συμβαλὼν ἅπαντας διέφθειρε τοὺς πολεμίους καὶ τοὺς λοιποὺς ἡγεμόνας Ζεβὴν καὶ Ζαρμούνην αἰχμαλώτους λαβὼν ἀνήγαγεν."},{"number":229,"text":"ἀπέθανον δʼ ἐν αὐτῇ τῇ μάχῃ Μαδιηνιτῶν τε καὶ τῶν συστρατευσάντων αὐτοῖς Ἀράβων περὶ μυριάδας δώδεκα, λεία τε πολλὴ χρυσὸς καὶ ἄργυρος καὶ ὕφη καὶ κάμηλος καὶ ὑποζύγια λαμβάνεται τοῖς Ἑβραίοις. Γεδεὼν δὲ παραγενόμενος εἰς Ἐφρὰν τὴν ἑαυτοῦ πατρίδα κτείνει τοὺς τῶν Μαδιηνιτῶν βασιλέας."},{"number":230,"text":"Ἡ δʼ Ἐφράμιδος φυλὴ τῇ Γεδεῶνος εὐπραγίᾳ δυσχεραίνουσα στρατεύειν ἐπʼ αὐτὸν διεγνώκει, τὸ μὴ προαγγεῖλαι τὴν ἐπιχείρησιν αὐτοῖς τὴν κατὰ τῶν πολεμίων ἐγκαλοῦντες. Γεδεὼν δὲ μέτριος ὢν καὶ πᾶσαν ἀρετὴν ἄκρος οὐκ αὐτὸς ἔλεγεν αὐτοκράτορι χρησάμενος λογισμῷ τοῖς ἐχθροῖς ἐπιθέσθαι χωρὶς αὐτῶν, ἀλλὰ τοῦ θεοῦ κελεύσαντος· τὴν δὲ νίκην οὐχ ἧττον αὐτῶν ἔφασκεν ἰδίαν ἢ τῶν ἐστρατευκότων εἶναι."},{"number":231,"text":"καὶ τούτοις παρηγορήσας αὐτῶν τὴν ὀργὴν τοῖς λόγοις μᾶλλον τοὺς Ἑβραίους ὠφέλησε τῆς ἐπὶ τῶν πολεμίων εὐπραξίας φήσας αἰτίους· ἐμφυλίου γὰρ αὐτοὺς στάσεως ἄρχειν μέλλοντας ἐρρύσατο. τῆς μέντοι ὕβρεως ταύτης ἡ φυλὴ δίκην ἐξέτισεν, ἣν δηλώσομεν κατὰ καιρὸν ἴδιον."},{"number":232,"text":"Γεδεὼν δὲ τὴν ἀρχὴν ἀποθέσθαι βουλόμενος βιασθεὶς ἔσχεν αὐτὴν ἐπʼ ἔτη τεσσαράκοντα βραβεύων αὐτοῖς τὰ δίκαια καὶ περὶ τῶν διαφορῶν ἐπʼ αὐτὸν βαδιζόντων κύρια πάντα ἦν τὰ ὑπʼ αὐτοῦ λεγόμενα. καὶ ὁ μὲν γηραιὸς τελευτήσας ἐν Ἐφρὰν τῇ πατρίδι θάπτεται."}],"7":[{"number":233,"text":"Παῖδες δὲ ἦσαν αὐτῷ γνήσιοι μὲν ἑβδομήκοντα, πολλὰς γὰρ ἔγημε γυναῖκας, νόθος δʼ εἷς ἐκ παλλακῆς Δρούμας Ἀβιμέλεχος τοὔνομα, ὃς μετὰ τὴν τοῦ πατρὸς τελευτὴν ἀναχωρήσας εἰς Σίκιμα πρὸς τοὺς ἀπὸ μητρὸς συγγενεῖς, ἐντεῦθεν γὰρ ἦν, καὶ λαβὼν ἀργύριον παρʼ αὐτῶν, οἳ διὰ πλῆθος ἀδικημάτων ἦσαν ἐπίσημοι,"},{"number":234,"text":"ἀφικνεῖται σὺν αὐτοῖς εἰς τὸν πατρῷον οἶκον καὶ κτείνει πάντας τοὺς ἀδελφοὺς πλὴν Ἰωθάμου· σώζεται γὰρ οὗτος διαφυγεῖν εὐτυχήσας. Ἀβιμέλεχος δὲ εἰς τυραννίδα τὰ πράγματα μεθίστησι κύριον αὑτὸν ὅ τι βούλεται ποιεῖν ἀντὶ τῶν νομίμων ἀποδείξας καὶ δεινῶς πρὸς τοὺς τοῦ δικαίου προϊσταμένους ἐκπικραινόμενος."},{"number":235,"text":"Καί ποτε δημοτελοῦς Σικίμοις οὔσης ἑορτῆς καὶ τοῦ πλήθους παντὸς ἐκεῖ συνειλεγμένου ὁ ἀδελφὸς αὐτοῦ Ἰωθάμης, ὃν καὶ διαφυγεῖν ἔφαμεν, ἀνελθὼν ἐπὶ τὸ ὄρος τὸ Γαριζείν, ὑπέρκειται δὲ τῆς Σικιμίων πόλεως, ἐκβοήσας εἰς ἐπήκοον τοῦ πλήθους ἡσυχίαν αὐτῷ παρασχόντος ἠξίου μαθεῖν τὰ ὑπʼ αὐτοῦ λεγόμενα."},{"number":236,"text":"γενομένης δὲ σιγῆς εἶπεν, ὡς τὰ δένδρα φωνὴν ἀνθρώπειον προϊέμενα συνόδου γενομένης αὐτῶν δεηθείη συκῆς ἄρχειν αὐτῶν. ἀρνησαμένης δʼ ἐκείνης διὰ τὸ τιμῆς τῆς ἐπὶ τοῖς καρποῖς οἰκείας οὔσης ἀπολαύειν οὐχ ὑπʼ ἄλλων ἔξωθεν προσγινομένης, τὰ δένδρα τῆς ἐπὶ τῷ ἄρχεσθαι φροντίδος οὐκ ἀπελείπετο, ἐδόκει δʼ αὐτοῖς ἀμπέλῳ τὴν τιμὴν παρασχεῖν."},{"number":237,"text":"καὶ ἡ ἄμπελος χειροτονουμένη τοῖς τῆς συκῆς χρησαμένη λόγοις παρῃτεῖτο τὴν ἀρχήν. τὸ δʼ αὐτὸ καὶ τῶν ἐλαιῶν ποιησαμένων ῥάμνος, ἐδεήθη γὰρ αὐτῆς ὥστε παραλαβεῖν τὴν βασιλείαν τὰ δένδρα,"},{"number":238,"text":"πυρεῖα δὲ ἀγαθὴ παρασχεῖν τῶν ξύλων ἐστίν, ὑπισχνεῖται τὴν ἀρχὴν ἀναλήψεσθαι καὶ ἀόκνως ἔχειν. δεῖ μέντοι συνιζάνειν αὐτὰ ὑπὸ τὴν σκιάν, εἰ δʼ ὄλεθρον ἐπʼ αὐτῇ φρονοῖεν, ὑπὸ τοῦ ἐνόντος πυρὸς διαφθαρεῖεν."},{"number":239,"text":"ταῦτα δʼ οὐ γέλωτος ἕνεκα, φησί, λέγω, ὅτι δὲ πολλῶν ἀγαθῶν ἐκ Γεδεῶνος πεπειραμένοι περιορῶσιν Ἀβιμέλεχον ἐπὶ τῶν ὅλων ὄντα πραγμάτων σὺν αὐτῷ τοὺς ἀδελφοὺς ἀποκτείναντες, ὃν πυρὸς οὐδὲν διοίσειν. καὶ ὁ μὲν ταῦτα εἰπὼν ὑπεχώρησε καὶ διῃτᾶτο λανθάνων ἐν τοῖς ὄρεσι δεδιὼς ἐπʼ ἔτη τρία τὸν Ἀβιμέλεχον."},{"number":240,"text":"Μετʼ οὐ πολὺ δὲ τῆς ἑορτῆς Σικιμῖται, μετενόησαν γὰρ ἐπὶ τοῖς Γεδεῶνος υἱοῖς πεφονευμένοις, ἐξελαύνουσι τὸν Ἀβιμέλεχον τῆς πόλεως καὶ τῆς φυλῆς· ὁ δὲ κακοῦν τὴν πόλιν ἐφρόντιζε. τῆς δʼ ὥρας τῆς τοῦ τρυγᾶν γενομένης ἐδεδίεσαν συλλέγειν τὸν καρπὸν προϊόντες μή τι δράσῃ κακὸν Ἀβιμέλεχος εἰς αὐτούς."},{"number":241,"text":"ἐπιδημήσαντος δὲ πρὸς αὐτοὺς τῶν ἀρχόντων τινὸς Γυάλου σὺν ὁπλίταις καὶ συγγενέσι τοῖς αὐτοῦ φυλακὴν οἱ Σικιμῖται δέονται παρασχεῖν αὐτοῖς, ἕως ἂν τρυγήσωσι. προσδεξαμένου δʼ ἐκείνου τὴν ἀξίωσιν προῄεσαν καὶ Γυάλης σὺν αὐτοῖς τὸ οἰκεῖον ἄγων ὁπλιτικόν."},{"number":242,"text":"ὅ τε οὖν καρπὸς μετὰ ἀσφαλείας συνάγεται καὶ δειπνοῦντες κατὰ συμμορίαν φανερῶς ἀπετόλμων ἤδη βλασφημεῖν τὸν Ἀβιμέλεχον, οἵ τε ἄρχοντες ἐνέδραις καταλαμβανόμενοι τὰ περὶ τὴν πόλιν πολλοὺς τῶν Ἀβιμελέχου συλλαμβάνοντες ἀνῄρουν."},{"number":243,"text":"Ζάβουλος δέ τις τῶν Σικιμιτῶν ἄρχων ξένος ὢν Ἀβιμελέχου ὅσα παροξύνειεν Γυάλης τὸν δῆμον πέμπων ἀγγέλους ἐμήνυεν αὐτῷ καὶ παρῄνει λοχᾶν πρὸ τῆς πόλεως· πείσειν γὰρ Γυάλην ἐξελθεῖν ἐπʼ αὐτόν, καὶ τὸ λοιπὸν ἐπʼ ἐκείνῳ τυγχάνειν ὥστε ἀμύνασθαι· γενομένου γὰρ τούτου διαλλαγὰς αὐτῷ μνηστεύσεσθαι πρὸς τὸν δῆμον."},{"number":244,"text":"ὅ τε οὖν Ἀβιμέλεχος ἐκάθισεν ἐνεδρεύων καὶ ὁ Γυάλης ἀφυλακτοτέρως διέτριβεν ἐπὶ τοῦ προαστείου καὶ Ζάβουλος σὺν αὐτῷ. ἰδὼν δὲ ὁπλίτας ἐπιφερομένους Γυάλης πρὸς Ζάβουλον ἔλεγεν ἄνδρας αὐτοῖς ἐπιέναι καθωπλισμένους."},{"number":245,"text":"τοῦ δὲ σκιὰς εἶναι φαμένου τῶν πετρῶν, πλησίον ἤδη γινομένων τὸ ἀκριβὲς κατανοῶν οὐ σκιὰς ἔλεγε ταῦτʼ εἶναι, λόχον δʼ ἀνδρῶν. καὶ Ζάβουλος, οὐ σὺ μέντοι, φησίν, Ἀβιμελέχῳ κακίαν ἐπεκάλεις; τί οὖν οὐκ ἐπιδεικνύεις τὸ τῆς ἀρετῆς μέγεθος εἰς μάχην αὐτῷ συμβαλών ;"},{"number":246,"text":"Γυάλης δὲ θορυβούμενος συνάπτει τοῖς Ἀβιμελέχου καὶ πίπτουσι μέν τινες τῶν σὺν αὐτῷ, φεύγει δʼ αὐτὸς εἰς τὴν πόλιν τοὺς ἄλλους ἀγόμενος. καὶ Ζάβουλος πολιτεύεται Γυάλην ἐκβληθῆναι τῆς πόλεως κατηγορήσας, ὡς μαλακῶς πρὸς τοὺς Ἀβιμελέχου στρατιώτας ἀγωνίσαιτο."},{"number":247,"text":"Ἀβιμέλεχος δὲ πυθόμενος ἐξελευσομένους αὖθις κατὰ τρύγητον τοὺς Σικιμίους ἐνέδραις προλοχίζεται τὰ περὶ τὴν πόλιν, καὶ προελθόντων ἡ μὲν τρίτη μοῖρα τῆς στρατιᾶς καταλαμβάνει τὰς πύλας ἀφαιρησομένη τὴν εἴσοδον τοὺς πολίτας, οἱ δʼ ἄλλοι σκιδναμένους μεταθέουσι, πανταχοῦ τε φόνος ἦν."},{"number":248,"text":"καὶ κατασκάψας εἰς ἔδαφος τὴν πόλιν, οὐ γὰρ ἀντέσχε πρὸς τὴν πολιορκίαν, ἅλας κατὰ τῶν ἐρειπίων σπείρας προῆγε. καὶ Σικιμῖται πάντες οὕτως ἀπώλοντο· ὅσοι δὲ κατὰ τὴν χώραν σκεδασθέντες διέφυγον τὸν κίνδυνον, οὗτοι πέτραν ὀχυρὰν εὑρόντες ἐπʼ αὐτῆς ἱδρύονται τειχίσαι τε ταύτην παρεσκευάζοντο."},{"number":249,"text":"ἔφθη τε τὴν διάνοιαν αὐτῶν Ἀβιμέλεχος μαθὼν ἐλθεῖν ἐπʼ αὐτοὺς μετὰ τῆς δυνάμεως καὶ φακέλλους ὕλης ξηρᾶς περιβαλὼν τῷ χωρίῳ διʼ αὐτοῦ φέρων ταῦτα ποιεῖν τὴν στρατιὰν παρεκελεύσατο. καὶ ταχέως περιληφθείσης ἐν κύκλῳ τῆς πέτρας τοῖς ξύλοις πῦρ ἐμβάλλουσιν ὅσα τε μᾶλλον ἐξάπτειν φύσιν ἔχει καὶ μεγίστην αἴρουσι φλόγα."},{"number":250,"text":"καὶ διαφεύγει μὲν ἀπὸ τῆς πέτρας οὐθείς, ἀλλʼ ἅμα γυναιξὶ καὶ τέκνοις ἀπώλοντο, ἄνδρες μὲν περὶ πεντακοσίους καὶ χιλίους, τὸ δὲ ἄλλο πλῆθος ἱκανόν. καὶ Σικιμίταις μὲν τοιαύτη συμφορὰ συνέπεσε μείζων καὶ τῆς ἐπʼ αὐτῇ λύπης γενομένη πλὴν ὅτι κατὰ δίκην ἐπʼ ἀνδρὸς εὐεργέτου συνθεῖσι κακὸν τηλικοῦτον."},{"number":251,"text":"Ἀβιμέλεχος δὲ τοῖς Σικιμιτῶν κακοῖς καταπλήξας τοὺς Ἰσραηλίτας μειζόνων ἐφιέμενος δῆλος ἦν καὶ μηδαμοῦ περιγράψων τὴν βίαν, εἰ μὴ πάντας ἀπολέσειεν. ἤλαυνεν οὖν ἐπὶ Θήβας καὶ τὴν μὲν πόλιν ἐξ ἐπιδρομῆς αἱρεῖ, πύργου δʼ ὄντος ἐν αὐτῇ μεγάλου, εἰς ὃν πᾶν τὸ πλῆθος συνέφυγε, πολιορκεῖν τοῦτον παρεσκευάζετο."},{"number":252,"text":"καὶ αὐτὸν πλησίον ὁρμῶντα τῶν πυλῶν γυνὴ θραύσματι μύλης βαλοῦσα κατὰ τῆς κεφαλῆς τυγχάνει, πεσὼν δὲ Ἀβιμέλεχος τὸν ὑπασπιστὴν παρεκάλει κτείνειν αὐτόν, μὴ τῆς γυναικὸς ὁ θάνατος αὐτοῦ δόξειεν ἔργον. καὶ ὁ μὲν τὸ προσταχθὲν ἐποίει."},{"number":253,"text":"ὁ δὲ τοιαύτην ὑπὲρ τῆς εἰς τοὺς ἀδελφοὺς παρανομίας ποινὴν ἐξέτισε καὶ τῶν εἰς Σικιμίους αὐτῷ τετολμημένων· τούτοις δὲ κατὰ τὴν Ἰωθάμου μαντείαν ἡ συμφορὰ συνέπεσε. τὸ μέντοι σὺν Ἀβιμελέχῳ στράτευμα πεσόντος αὐτοῦ σκεδασθὲν ἀνεχώρησεν ἐπὶ τὰ οἰκεῖα."},{"number":254,"text":"Τῶν δὲ Ἰσραηλιτῶν τὴν ἡγεμονίαν Ἰάρης ὁ Γαλαδηνὸς ἐκ τῆς Μανασσίτιδος φυλῆς παραλαμβάνει ἀνὴρ τά τε ἄλλα εὐδαίμων καὶ παῖδας ἀγαθοὺς πεποιημένος τριάκοντα μὲν τὸν ἀριθμὸν ἱππεύειν δὲ ἀρίστους καὶ τῶν κατὰ τὴν Γαλαδηνὴν πόλεων ἀρχὰς ἐγκεχειρισμένους. οὗτος δύο καὶ εἴκοσι ἔτη τὴν ἀρχὴν κατασχὼν τελευτᾷ γηραιὸς καὶ ταφῆς ἐν Καμμὼν πόλει τῆς Γαλαδηνῆς ἀξιοῦται."},{"number":255,"text":"Πάντα δὲ τὰ τῶν Ἑβραίων εἰς ἀκοσμίαν καὶ ὕβριν τοῦ θεοῦ καὶ τῶν νόμων ὑπεφέρετο, καὶ καταφρονήσαντες αὐτῶν Ἀμμανῖται καὶ Παλαιστῖνοι στρατῷ μεγάλῳ διήρπαζον τὴν χώραν καὶ τὴν Περαίαν ἅπασαν κατασχόντες καὶ ἐπὶ τὴν τῶν λοιπῶν ἤδη κτῆσιν διαβαίνειν ἐτόλμων."},{"number":256,"text":"Ἑβραῖοι δὲ σωφρονισθέντες ὑπὸ τῶν κακῶν εἰς ἱκετείαν ἐτράποντο τοῦ θεοῦ καὶ θυσίας ἐπέφερον παρακαλοῦντες αὐτὸν μετριάσαντα καὶ πρὸς τὴν δέησιν αὐτῶν ὑπαχθέντα παύσασθαι τῆς ὀργῆς· ὁ δὲ θεὸς μεταβαλόμενος εἰς τὸ ἡμερώτερον ἔμελλεν αὐτοῖς βοηθεῖν."},{"number":257,"text":"Ἀμμανιτῶν δʼ ἐστρατευκότων ἐπὶ τὴν Γαλαδηνὴν ὑπήντων οἱ ἐπιχώριοι πρὸς τὸ ὄρος δεόμενοι τοῦ στρατηγήσοντος. ἦν δέ τις Ἰαφθᾶς ἀνὴρ διὰ τὴν πατρῴαν ἀρετὴν δυνατὸς καὶ διʼ οἰκείαν αὐτοῦ στρατιὰν ἣν ἔτρεφεν αὐτὸς μισθοφόρων."},{"number":258,"text":"πρὸς τοῦτον οὖν πέμψαντες ἠξίουν αὐτὸν συμμαχεῖν ἐπαγγελλόμενοι παρασχεῖν εἰς ἅπαντʼ αὐτῷ τὸν χρόνον τὴν ἰδίαν ἡγεμονίαν. ὁ δʼ οὐ προσίεται τὴν παράκλησιν αὐτῶν ἐγκαλῶν, ὅτι μὴ βοηθήσειαν αὐτῷ ὑπὸ τῶν ἀδελφῶν ἀδικουμένῳ περιφανῶς·"},{"number":259,"text":"οὐ γὰρ ὄντα ὁμομήτριον αὐτοῖς ἀλλὰ ξένον περὶ τὴν μητέρα διʼ ἐρωτικὴν ἐπιθυμίαν ἐπαχθεῖσαν αὐτοῖς ὑπὸ τοῦ πατρὸς ἐξέβαλον καταφρονήσαντες τῆς αὐτοῦ ἀσθενείας."},{"number":260,"text":"καὶ ὁ μὲν διέτριβεν ἐν τῇ Γαλαδίτιδι καλουμένῃ χώρᾳ πάντας τοὺς ὁποθενοῦν παραγινομένους πρὸς αὐτὸν ἐπὶ μισθῷ δεχόμενος. ἐκλιπαρησάντων δʼ αὐτῶν καὶ ὀμοσάντων εἰς ἀεὶ παρέξειν αὐτῷ τὴν ἡγεμονίαν ἐστράτευε."},{"number":261,"text":"Καὶ ποιησάμενος ὀξεῖαν τὴν τῶν πραγμάτων ἐπιμέλειαν ἐν πόλει Μασφαθῇ καθίσας τὸν στρατὸν πρεσβείαν πέμπει παρὰ τὸν Ἀμμανίτην αἰτιώμενος τῆς ἁλώσεως. ὁ δὲ ἀντιπέμψας ᾐτιᾶτο τῶν Ἰσραηλιτῶν τὴν ἔξοδον τὴν ἀπʼ Αἰγύπτου καὶ τῆς Ἀμορραίας αὐτοὺς ἠξίου παραχωρεῖν ὡς πατρῴας οὔσης ἀρχῆθεν."},{"number":262,"text":"ἀποκρινάμενος δὲ ὁ Ἰαφθᾶς, ὡς οὔτε τῆς Ἀμορραίας τοῖς προγόνοις αὐτῶν εὐλόγως ἐγκαλοῦσι χάριν τε μᾶλλον τῆς Ἀμμανίτιδος αὐτοῖς ἔχειν ὀφείλουσι παρεθείσης, δυνατὸν γὰρ Μωυσεῖ καὶ ταύτην λαβεῖν παραχωρεῖν τε ἰδίας εἰπὼν γῆς, ἣν θεοῦ κατακτησαμένου μετὰ τριακόσια ἔτη νέμονται, μάχεσθαι πρὸς αὐτοὺς ἔφησεν."},{"number":263,"text":"Καὶ τοὺς μὲν πρέσβεις ταῦτʼ εἰπὼν ἀπέλυσεν· αὐτὸς δʼ εὐξάμενος νίκην καὶ θυσιάσειν ὑποσχόμενος, ἂν σῶος εἰς τὰ οἰκεῖα ὑποστρέψῃ, καὶ πᾶν ὅ τι καὶ πρῶτον αὐτῷ συντύχοι ἱερουργήσειν, συμβαλών τε νικᾷ παρὰ πολὺ καὶ φονεύων ἐδίωκε μέχρι πόλεως Μανιάθης, καὶ διαβὰς εἰς τὴν Ἀμμανῖτιν πόλεις τε ἠφάνισε πολλὰς καὶ λείαν ἤλασε καὶ τοὺς οἰκείους δουλείας ἀπήλλαξεν ἐν ἔτεσιν ὀκτωκαίδεκα ταύτην ὑπομείναντας."},{"number":264,"text":"ἀναστρέφων δὲ συμφορᾷ περιπίπτει κατʼ οὐδὲν ὁμοίᾳ τοῖς κατωρθωμένοις αὐτῷ· ὑπήντησε γὰρ ἡ θυγάτηρ αὐτῷ, μονογενὴς δʼ ἦν, ἔτι παρθένος. ὁ δὲ ἀνοιμώξας ἐπὶ τῷ μεγέθει τοῦ πάθους κατεμέμφετο τῆς περὶ τὴν ὑπάντησιν σπουδῆς τὴν θυγατέρα· καθιερῶσαι γὰρ αὐτὴν τῷ θεῷ."},{"number":265,"text":"τῇ δὲ τὸ συμβησόμενον οὐκ ἀηδῶς προσέπεσεν ἐπὶ νίκῃ τοῦ πατρὸς καὶ ἐλευθερίᾳ τῶν πολιτῶν τεθνηξομένῃ, παρεκάλεσε δὲ δύο μῆνας αὐτῇ παρασχόντα πρὸς τὸ μετὰ τῶν πολιτῶν ἀποθρηνῆσαι τὴν νεότητα τότε ποιεῖν τὰ κατὰ τὴν εὐχήν."},{"number":266,"text":"συγχωρήσας δὲ τὰ κατὰ τὸν προειρημένον χρόνον μετὰ τοῦτον διελθόντα θύσας τὴν παῖδα ὡλοκαύτωσεν οὔτε νόμιμον οὔτε θεῷ κεχαρισμένην θυσίαν ἐπιτελῶν, μὴ διαβασανίσας τῷ λογισμῷ τὸ γενησόμενον οἷόν τε πραχθὲν δόξει τοῖς ἀκούσασι."},{"number":267,"text":"Τῆς δʼ Ἐφράνου φυλῆς ἐπʼ αὐτὸν στρατευσάσης, ὅτι μὴ κοινώσαιτο τὴν ἐπʼ Ἀμμανίτας ἔλασιν αὐτοῖς, ἀλλὰ μόνος καὶ τὴν λείαν ἔχοι καὶ τὴν ἐπὶ τοῖς πεπραγμένοις δόξαν, πρῶτον μὲν ἔλεγεν, ὡς οὔτε λάθοιεν αὐτοὺς οἱ συγγενεῖς πολεμούμενοι καλούμενοί τε πρὸς συμμαχίαν οὐ παρεγένοντο δέον καὶ πρὸ δεήσεως ἐγνωκότας ἐπειχθῆναι,"},{"number":268,"text":"ἔπειθʼ ὡς ἄδικα πράττειν ἐπιχειροῦσι τοῖς πολεμίοις οὐ τολμήσαντες εἰς χεῖρας ἐλθεῖν, ἐπὶ δὲ τοὺς συγγενεῖς ὡρμηκότες· ἠπείλει τε σὺν τῷ θεῷ λήψεσθαι δίκην παρʼ αὐτῶν, ἂν μὴ σωφρονῶσιν."},{"number":269,"text":"ὡς δʼ οὐκ ἔπειθεν, ἀλλὰ συνέβαλεν αὐτοῖς ἐλθοῦσι μετὰ στρατιᾶς, ἣ μετάπεμπτος ἐκ τῆς Γαλαδηνῆς ἐληλύθει, φόνον τε πολὺν αὐτῶν εἰργάσατο καὶ διώκων τραπέντας προλαβὼν μέρει τινὶ προαπεσταλμένῳ τοῦ Ἰορδάνου τὰς διαβάσεις κτείνει περὶ δισχιλίους καὶ τετρακισμυρίους γεγονότας."},{"number":270,"text":"Αὐτὸς δὲ ἄρξας ἓξ ἔτη τελευτᾷ καὶ θάπτεται ἐν τῇ αὐτοῦ πατρίδι Σεβέῃ· τῆς Γαλαδηνῆς δʼ ἐστὶν αὕτη."},{"number":271,"text":"Τελευτήσαντος δὲ Ἰαφθᾶ τὴν ἀρχὴν Ἀψάνης παραλαμβάνει φυλῆς ὢν Ἰουδαϊκῆς Βηθλέμων δὲ πόλεως. τούτῳ δὲ παῖδες ἦσαν ἑξήκοντα, τριάκοντα μὲν ἄρρενες αἱ λοιπαὶ δὲ θυγατέρες, οὓς καὶ πάντας ζῶντας κατέλιπε τὰς μὲν ἀνδράσιν ἐκδοὺς τοῖς δὲ γυναῖκας ἠγμένος. πράξας δʼ οὐδὲν ἐν τῷ ἑπταετεῖ γενομένῳ χρόνῳ λόγου καὶ μνήμης ἄξιον γηραιὸς ὢν ἀπέθανε καὶ ταφῆς ἐν τῇ πατρίδι τυγχάνει."},{"number":272,"text":"Ἀψανοῦς δʼ οὕτως ἀποθανόντος οὐδʼ ὁ μετʼ αὐτὸν παραλαβὼν τὴν ἡγεμονίαν Ἤλων ἐπʼ ἔτη δέκα κατασχὼν αὐτὴν φυλῆς ὢν τῆς Ζαβούλης ἔπραξέ τι σπουδῆς ἄξιον."},{"number":273,"text":"Ἀβδὼν δὲ Ἤλωνος παῖς φυλῆς μὲν τῆς Ἐφραμίτιδος πόλεως δὲ τῆς Φαραθωνιτῶν γεγονώς, αὐτοκράτωρ ἡγεμὼν ἀποδειχθεὶς μετʼ Ἤλωνα μόνης ἂν τῆς εὐπαιδίας μνημονευθείη, μηδὲν ἔργον διὰ τὴν εἰρήνην καὶ τὴν ἄδειαν τῶν πραγμάτων λαμπρὸν μηδʼ αὐτὸς εἰργασμένος."},{"number":274,"text":"υἱοὶ δὲ ἦσαν αὐτῷ τεσσαράκοντα καὶ τούτων τὴν γενεὰν καταλιπόντες τριάκοντα, ἤλαυνέ τε σὺν αὐτοῖς οὖσιν ἑβδομήκοντα πᾶσιν ἱππάζειν ἀρίστοις γεγενημένοις, καὶ πάντας ὑπὲρ γῆς ἀπολιπὼν θνήσκει γηραιὸς καὶ ταφῆς ἐν Φαραθῷ λαμπρᾶς τυγχάνει."}],"8":[{"number":275,"text":"Μετὰ δὲ τοῦτον Παλαιστῖνοι τελευτήσαντα κρατοῦσι τῶν Ἰσραηλιτῶν καὶ φόρους παρʼ αὐτῶν ἐλάμβανον ἐπʼ ἔτη τεσσαράκοντα. ταύτης δʼ ἐλευθεροῦνται τῆς ἀνάγκης τούτῳ τῷ τρόπῳ·"},{"number":276,"text":"Μανώχης τις Δανιτῶν ἐν ὀλίγοις ἄριστος καὶ τῆς πατρίδος ὁμολογούμενος πρῶτος εἶχε γύναιον ἐπʼ εὐμορφίᾳ περίβλεπτον καὶ τῶν κατʼ αὐτὸ διαφέρον. παίδων δʼ οὐ γινομένων αὐτῷ δυσφορῶν ἐπὶ τῇ ἀπαιδίᾳ θεὸν ἱκέτευεν ἐπὶ τὸ προάστειον συνεχῶς φοιτῶν μετὰ τῆς γυναικὸς δοῦναι διαδοχὴν αὐτοῖς γνησίαν· μέγα δέ ἐστι τοῦτο πεδίον."},{"number":277,"text":"ἦν δὲ καὶ μανιώδης ὑπʼ ἔρωτος ἐπὶ τῇ γυναικὶ καὶ διὰ τοῦτο ζηλότυπος ἀκρατῶς. μονωθείσῃ δὲ τῇ γυναικὶ φάντασμα ἐπιφαίνεται τοῦ θεοῦ νεανίᾳ καλῷ παραπλήσιον μεγάλῳ καὶ εὐαγγελιζόμενον αὐτῇ παιδὸς γονὴν κατὰ θεοῦ πρόνοιαν καλοῦ τε καὶ ῥώμην ἐπιφανοῦς, ὑφʼ ᾧ πονήσειν Παλαιστίνους ἀνδρουμένῳ."},{"number":278,"text":"παρῄνει τε τὰς κόμας αὐτῷ μὴ ἀποκείρειν· ἔσται δʼ αὐτῷ πρὸς ἄλλο μὲν ποτὸν ἀποστροφὴ τοῦ θεοῦ τοῦτο προστάσσοντος, πρὸς ὕδωρ δὲ μόνον οἰκειότης . καὶ ὁ μὲν ταῦτʼ εἰπὼν ᾤχετο κατὰ βούλησιν ἐλθὼν τοῦ θεοῦ."},{"number":279,"text":"Ἡ δὲ τἀνδρὶ παραγενομένῳ τὰ παρὰ τοῦ ἀγγέλου ἐκδιηγήσατο ἐκθαυμάζουσα τοῦ νεανίσκου τὸ κάλλος καὶ τὸ μέγεθος, ὡς ἐκεῖνον ἐκ τῶν ἐπαίνων εἰς ἔκπληξιν κατὰ ζηλοτυπίαν περιστῆναι καὶ ὑπόνοιαν τὴν ἐκ τοιούτου πάθους κινουμένην."},{"number":280,"text":"ἡ δὲ βουλομένη τὴν ἄλογον τἀνδρὸς λύπην σταλῆναι τὸν θεὸν ἱκέτευε πάλιν πέμψαι τὸν ἄγγελον, ὡς ἂν καὶ τῷ ἀνδρὶ αὐτῆς ὁραθείη. καὶ παραγίνεται πάλιν κατὰ χάριν τοῦ θεοῦ ὁ ἄγγελος ὄντων ἐν τῷ προαστείῳ καὶ τῇ γυναικὶ φαίνεται τοῦ ἀνδρὸς μεμονωμένῃ. ἡ δʼ ἐπιμεῖναι δεηθεῖσα ὡς ἂν ἀγάγοι τὸν ἄνδρα συγχωρήσαντος μέτεισι τὸν Μάνωχον."},{"number":281,"text":"ὁ δὲ θεασάμενος οὐδʼ οὕτως ἐπαύετο τῆς ὑπονοίας ἠξίωσέ τι καὶ αὐτῷ δηλοῦν ὅσα καὶ τῇ γυναικὶ μηνύσειεν. ἀρκέσειν δὲ φράσαντος ταύτην μόνην εἰδέναι, τίς εἴη λέγειν ἐκέλευεν, ἵνα τοῦ παιδὸς γενομένου χάριν αὐτῷ καὶ δωρεὰν παράσχωσι."},{"number":282,"text":"τοῦ δὲ μηδέ τινων αὐτῷ δεῖσθαι φήσαντος, οὐδὲ γὰρ κατὰ χρείαν ταῦτα εὐαγγελίσασθαι περὶ τῆς τοῦ παιδὸς γονῆς, τοῦ δὲ μεῖναι παρακαλοῦντος καὶ ξενίων μετασχεῖν οὐκ ἐπένευσε, πεισθεὶς δʼ ὅμως λιπαροῦντος ἐπιμεῖναι ὡς ἂν ξένιον αὐτῷ τι κομίσῃ,"},{"number":283,"text":"καὶ θύσαντος ἔριφον τοῦ Μανώχου καὶ τοῦτον ὀπτᾶν τῇ γυναικὶ κελεύσαντος, ἐπεὶ πάντʼ ἦν εὐτρεπῆ, προσέταξεν ἐπὶ τῆς πέτρας ἀποθέσθαι τούς τε ἄρτους καὶ τὰ κρέα χωρὶς τῶν ἀγγείων."},{"number":284,"text":"καὶ ποιησάντων ἅπτεται τῇ ῥάβδῳ ᾗ εἶχε τῶν κρεῶν, τὰ δὲ λάμψαντος πυρὸς ἅμα τοῖς ἄρτοις ἐκαίετο καὶ ὁ ἄγγελος διὰ τοῦ καπνοῦ ὥσπερ ὀχήματος ἀνιὼν εἰς οὐρανὸν αὐτοῖς φανερὸς ἦν. Μανώχην δὲ φοβούμενον, μή τι σφαλερὸν αὐτοῖς ἐκ τῆς ὄψεως τοῦ θεοῦ γένοιτο, θαρσεῖν ἡ γυνὴ παρεκελεύετο· ἐπὶ γὰρ συμφέροντι τῷ αὐτῶν τὸν θεὸν αὐτοῖς ὁραθῆναι."},{"number":285,"text":"Καὶ κύει τε ἐκείνη καὶ φυλακὴν εἶχε τῶν ἐντολῶν, καὶ γενόμενον τὸ παιδίον Σαμψῶνα καλοῦσιν, ἰσχυρὸν δʼ ἀποσημαίνει τὸ ὄνομα. ηὔξετο δʼ ὁ παῖς ῥᾳδίως καὶ δῆλος ἦν προφητεύσων ὑπὸ τῆς περὶ τὴν δίαιταν σωφροσύνης καὶ τῆς τῶν τριχῶν ἀνέσεως."},{"number":286,"text":"Ἀφικόμενος δὲ μετὰ τῶν γονέων εἰς Θάμνα πόλιν τῶν Παλαιστίνων πανηγύρεως ἀγομένης ἐρᾷ παρθένου τῶν ἐπιχωρίων παρακαλεῖ τε τοὺς γονεῖς ἄγεσθαι πρὸς γάμον αὐτῷ τὴν κόρην. τῶν δὲ ἀρνουμένων διὰ τὸ μὴ ὁμόφυλον εἶναι, τοῦ θεοῦ κατὰ τὸ Ἑβραίων σύμφορον ἐπινοοῦντος τὸν γάμον ἐκνικᾷ μνηστεύσασθαι τὴν παρθένον."},{"number":287,"text":"συνεχῶς δʼ ἀπερχόμενος πρὸς τοὺς γονεῖς αὐτῆς συντυγχάνει λέοντι καὶ γυμνὸς ὢν ἐκδεξάμενος αὐτὸν ἄγχει ταῖς χερσὶ καὶ εἰς τὸ χωρίον τὸ ὑλῶδες ἐνδοτέρω τῆς ὁδοῦ ῥίπτει τὸ θηρίον."},{"number":288,"text":"Πάλιν τε ἀπιὼν πρὸς τὴν κόρην ἐπιτυγχάνει σμήνει μελιττῶν ἐν τῷ στήθει τοῦ λέοντος ἐκείνου νενοσσευκότων, καὶ ἀνελόμενος τρία μέλιτος κηρία σὺν τοῖς λοιποῖς δώροις οἷς ἐκόμιζε δίδωσι τῇ παιδί."},{"number":289,"text":"τῶν δὲ Θαμνιτῶν παρὰ τὴν εὐωχίαν τὴν τῶν γάμων, εἱστία γὰρ αὐτοὺς ἅπαντας, διὰ δέος τῆς ἰσχύος τοῦ νεανίσκου τριάκοντα δόντων αὐτῷ τοὺς ἀκμαιοτάτους λόγῳ μὲν ἑταίρους ἐσομένους ἔργῳ δὲ φύλακας, μή τι παρακινεῖν ἐθελήσειεν, τοῦ πότου προβάντος καὶ παιδιᾶς οὔσης, οἷα φιλεῖ παρὰ τοὺς τοιούτους καιρούς,"},{"number":290,"text":"ὁ Σαμψὼν εἶπεν, ἀλλὰ προβάλλοντος ἐμοῦ λόγον εἰ λύσετε τοῦτον ἐφʼ ἡμέρας ἑπτὰ ποιούμενοι τὴν ζήτησιν, ὀθόνας τε καὶ στολὰς γέρας τῆς συνέσεως κατʼ ἄνδρα ἕκαστον φέρεσθε παρʼ ἐμοῦ . φιλοτιμουμένων δὲ ὁμοῦ τε συνετοὺς δόξαι καὶ κέρδος εὕρασθαι καὶ λέγειν ἀξιούντων φησίν, ὅτι τὸ πάμβορον γεγεννήκοι βορὰν ἡδεῖαν ἐξ αὐτοῦ καὶ πάνυ ἀηδοῦς ὄντος."},{"number":291,"text":"τῶν δʼ ἐπὶ τρεῖς ἡμέρας οὐ δυναμένων ἐξευρεῖν τὸ νοούμενον παρακαλούντων δὲ τὴν κόρην μαθοῦσαν παρὰ τοῦ ἀνδρὸς αὐτοῖς μηνῦσαι, καὶ γὰρ ἠπείλουν ἐμπρήσειν αὐτὴν τοῦτο μὴ παρασχοῦσαν, ὁ Σαμψὼν δεομένης τῆς κόρης εἰπεῖν αὐτῇ τὸ μὲν πρῶτον ἀντέχειν ἐπειρᾶτο,"},{"number":292,"text":"ἐγκειμένης δʼ αὐτῆς καὶ εἰς δάκρυα προπιπτούσης καὶ τεκμήριον τιθεμένης τῆς πρὸς αὐτὴν δυσνοίας τὸ μὴ λέγειν αὐτῇ, μηνύει τὰ περὶ τὴν ἀναίρεσιν αὐτῇ τοῦ λέοντος καὶ ὡς τὰ τρία βαστάσας ἐξ αὐτοῦ κηρία μέλιτος γεγονότα κομίσειεν αὐτῇ."},{"number":293,"text":"καὶ ὁ μὲν οὐδὲν ὑφορώμενος δολερὸν σημαίνει τὸ πᾶν, ἡ δʼ ἐκφέρει τὸν λόγον τοῖς δεηθεῖσι. κατὰ οὖν τὴν ἑβδόμην ἡμέραν, καθʼ ἣν ἔδει τὸν προβληθέντα λόγον αὐτῷ διασαφεῖν, πρὶν ἢ δῦναι τὸν ἥλιον συνελθόντες φασίν, οὔτε λέοντος ἀηδέστερόν τι τοῖς ἐντυγχάνουσιν οὔτε ἥδιον μέλιτος χρωμένοις ."},{"number":294,"text":"καὶ ὁ Σαμψὼν εἶπεν οὐδὲ γυναικὸς εἶναί τι δολερώτερον, ἥτις ὑμῖν ἐκφέρει τὸν ἡμέτερον λόγον . κἀκείνοις μὲν δίδωσιν ἃ ὑπέσχετο λείαν ποιησάμενος Ἀσκαλωνιτῶν τοὺς κατὰ τὴν ὁδὸν αὐτῷ συντυχόντας, Παλαιστῖνοι δʼ εἰσὶ καὶ οὗτοι, τὸν δὲ γάμον ἐκεῖνον παραιτεῖται καὶ ἡ παῖς ἐκφαυλίσασα τῆς ὀργῆς αὐτὸν συνῆν αὐτοῦ φίλῳ νυμφοστόλῳ γεγονότι."},{"number":295,"text":"Πρὸς δὲ τὴν ὕβριν ταύτην Σαμψὼν παροξυνθεὶς ἅπαντας ἔγνω σὺν αὐτῇ Παλαιστίνους μετέρχεσθαι. θέρους δʼ ὄντος καὶ πρὸς ἄμητον ἤδη τῶν καρπῶν ἀκμαζόντων συλλαβὼν τριακοσίας ἀλώπεκας καὶ τῶν οὐρῶν ἐξάψας λαμπάδας ἡμμένας ἀφίησιν εἰς τὰς ἀρούρας τῶν Παλαιστίνων."},{"number":296,"text":"καὶ φθείρεται μὲν οὕτως αὐτοῖς ὁ καρπός, Παλαιστῖνοι δὲ γνόντες Σαμψῶνος εἶναι τὸ ἔργον καὶ τὴν αἰτίαν διʼ ἣν ἔπραξε, πέμψαντες τοὺς ἄρχοντας εἰς Θαμνὰ τὴν γενομένην αὐτοῦ γυναῖκα καὶ τοὺς συγγενεῖς ζῶντας κατέπρησαν ὡς αἰτίους τῶν κακῶν γεγονότας."},{"number":297,"text":"Σαμψὼν δὲ πολλοὺς ἐν τῷ πεδίῳ τῶν Παλαιστίνων ἀποκτείνας Αἰτὰν κατῴκει, πέτρα δʼ ἐστὶν ὀχυρὰ τῆς Ἰούδα φυλῆς. Παλαιστῖνοι δʼ ἐστράτευον ἐπὶ τὴν φυλήν. τῶν δʼ οὐ δικαίως λεγόντων τιμωρίαν αὐτοὺς εἰσπράττεσθαι περὶ τῶν Σαμψῶνος ἁμαρτημάτων φόρους αὐτοὺς τελοῦντας, εἰ βούλονται μὴ ἔχειν αἰτίαν ἔφασαν αὐτοῖς ὑποχείριον Σαμψῶνα δοῦναι."},{"number":298,"text":"οἱ δὲ ἀνεπίκλητοι βουλόμενοι τυγχάνειν παρῆσαν ἐπὶ τὴν πέτραν τρισχίλιοι ὁπλῖται καὶ καταμεμψάμενοι τῶν εἰς Παλαιστίνους αὐτῷ τετολμημένων ἄνδρας ἅπαντι τῷ γένει τῶν Ἑβραίων συμφορὰν ἐπενεγκεῖν δυναμένους, ἥκειν τε λέγοντες ὅπως αὐτὸν λαβόντες ὑποχείριον δῶσιν αὐτοῖς ἠξίουν ἑκοντὶ τοῦθʼ ὑπομένειν."},{"number":299,"text":"ὁ δὲ λαβὼν ὅρκους παρʼ αὐτῶν μηδὲν τούτων ποιήσειν περισσότερον ἀλλὰ τοῖς ἐχθροῖς ἐγχειριεῖν μόνον, καταβὰς ἐκ τῆς πέτρας αὑτὸν ἐν τῇ τῶν φυλετῶν τίθησιν ἐξουσίᾳ, κἀκεῖνοι δήσαντες αὐτὸν δυσὶ καλωδίοις ἦγον παραδοῦναι τοῖς Παλαιστίνοις."},{"number":300,"text":"καὶ γενομένων κατὰ χωρίον, ὃ Σιαγὼν καλεῖται νῦν διὰ τὴν Σαμψῶνος ἀνδραγαθίαν ἐπʼ αὐτῷ γενομένην, πάλαι δʼ ἦν ἀνώνυμον, οὐκ ἄπωθεν ἐστρατοπεδευκότων τῶν Παλαιστίνων, ἀλλʼ ὑπαντώντων μετὰ χαρᾶς καὶ βοῆς ὡς ἐπὶ κατωρθωμένοις οἷς ἐβούλοντο, διαρρήξας τὰ δεσμὰ Σαμψὼν ἁρπασάμενος ὄνου σιαγόνα παρὰ ποσὶν οὖσαν εἰς τοὺς πολεμίους ὤσατο καὶ παίων αὐτοὺς τῇ σιαγόνι κτείνει εἰς χιλίους, τοὺς δὲ ἄλλους τρέπεται ταραχθέντας."},{"number":301,"text":"Σαμψὼν δὲ μεῖζον ἢ χρὴ ἐπὶ τούτῳ φρονῶν οὐ κατὰ θεοῦ συνεργίαν ἔλεγε τοῦτο συμβῆναι, τὴν δʼ ἰδίαν ἀρετὴν ἐπέγραψε τῷ γεγονότι, τῶν πολεμίων τοὺς μὲν πεσεῖν τοὺς δʼ εἰς φυγὴν τραπῆναι διὰ τοῦ παρʼ αὐτοῦ δέους αὐχῶν."},{"number":302,"text":"δίψους δʼ αὐτὸν ἰσχυροῦ κατασχόντος κατανοῶν ὡς οὐδέν ἐστιν ἀνθρώπειος ἀρετὴ τῷ θεῷ πάντα προσεμαρτύρει καὶ καθικέτευε μηδὲν τῶν εἰρημένων πρὸς ὀργὴν λαβόντα τοῖς πολεμίοις αὐτὸν ἐγχειρίσαι, παρασχεῖν δὲ βοήθειαν πρὸς τὸ δεινὸν καὶ ῥύσασθαι τοῦ κακοῦ."},{"number":303,"text":"καὶ πρὸς τὰς ἱκετείας ἐπικλασθεὶς ὁ θεὸς πηγὴν κατά τινος πέτρας ἀνίησιν ἡδεῖαν καὶ πολλήν, ὅθεν καὶ Σαμψὼν ἐκάλει τὸ χωρίον Σιαγόνα καὶ μέχρι τοῦ δεῦρο τοῦτο λέγεται."},{"number":304,"text":"Μετὰ δὲ ταύτην τὴν μάχην Σαμψὼν καταφρονῶν τῶν Παλαιστίνων εἰς Γάζαν ἀφικνεῖται καὶ ἔν τινι τῶν καταγωγίων διέτριβε. μαθόντες δὲ τῶν Γαζαίων οἱ ἄρχοντες τὴν αὐτόθι παρουσίαν αὐτοῦ τὰ πρὸ τῶν πυλῶν ἐνέδραις καταλαμβάνουσιν, ὅπως ἐξιὼν μὴ λάθῃ."},{"number":305,"text":"Σαμψὼν δέ, οὐ γὰρ λανθάνουσιν αὐτὸν ταῦτα μηχανησάμενοι, περὶ μεσοῦσαν ἤδη τὴν νύκτα ἀναστὰς ἐνράσσει ταῖς πύλαις, αὐταῖς τε φλιαῖς καὶ μοχλοῖς ὅση τε ἄλλη περὶ αὐταῖς ἦν ξύλωσις ἀράμενος κατωμαδὸν εἰς τὸ ὑπὲρ Ἑβρῶνος ὄρος φέρων κατατίθησιν."},{"number":306,"text":"Παρέβαινε δʼ ἤδη τὰ πάτρια καὶ τὴν οἰκείαν δίαιταν παρεχάρασσεν ξενικῶν μιμήσει ἐθισμῶν καὶ τοῦτʼ αὐτῷ ἀρχὴ κακοῦ γίνεται· γυναικὸς γὰρ ἑταιριζομένης παρὰ τοῖς Παλαιστίνοις ἐρασθεὶς Δαλάλης τοὔνομα συνῆν αὐτῇ."},{"number":307,"text":"καὶ τῶν Παλαιστίνων οἱ τοῦ κοινοῦ προεστῶτες ἐλθόντες πρὸς αὐτὴν πείθουσιν ἐπαγγελίαις μαθεῖν παρὰ τοῦ Σαμψῶνος τὴν αἰτίαν τῆς ἰσχύος, ὑφʼ ἧς ἄληπτός ἐστι τοῖς ἐχθροῖς. ἡ δὲ παρὰ πότον καὶ τοιαύτην συνουσίαν θαυμάζουσα τὰς πράξεις αὐτοῦ ἐτεχνίτευε μαθεῖν, τίνι τρόπῳ τοσοῦτον προύχει κατʼ ἀρετήν."},{"number":308,"text":"ὁ δὲ Σαμψών, ἔτι γὰρ φρονεῖν ἰσχυρὸς ἦν, ἀντηπάτα τὴν Δαλάλην φάμενος, εἰ κλήμασιν ἑπτὰ δεθείη ἀμπέλου ἔτι καὶ περιειλεῖσθαι δυναμένοις, ἀσθενέστερος ἂν πάντων ἔσοιτο."},{"number":309,"text":"ἡ δὲ τότε μὲν ἡσύχασεν, ἀποσημήνασα δὲ τοῖς ἄρχουσι τῶν Παλαιστίνων ἐνίδρυσε τῶν στρατιωτῶν ἔνδον τινὰς καὶ μεθύοντα κατέδει τοῖς κλήμασι κατὰ τὸ ἰσχυρότατον, ἔπειτʼ ἀνεγείρασα ἐδήλου παρεῖναί τινας ἐπʼ αὐτόν."},{"number":310,"text":"ὁ δὲ ῥήξας τὰ κλήματα βοηθεῖν ὡς ἐπερχομένων αὐτῷ τινων ἐπειρᾶτο. καὶ ἡ γυνὴ συνεχῶς ὁμιλοῦντος αὐτῇ τοῦ Σαμψῶνος δεινῶς ἔχειν ἔλεγεν, εἰ κατʼ ἀπιστίαν εὐνοίας τῆς πρὸς αὐτὸν μὴ λέγει ταῦθʼ ἅπερ δεῖται, ὡς οὐ σιγησομένης ὅσα μὴ γινώσκεσθαι συμφέρειν οἶδεν αὐτῷ."},{"number":311,"text":"τοῦ δὲ πάλιν ἀπατῶντος αὐτὴν καὶ φήσαντος ἑπτὰ κάλοις δεθέντα τὴν ἰσχὺν ἀπολέσειν, ἐπεὶ καὶ τοῦτο ποιήσασα οὐδὲν ἤνυσεν, τρίτον συνυφῆναι τὰς κόμας αὐτοῦ ἐμήνυσεν."},{"number":312,"text":"ὡς δʼ οὐδὲ τούτου γενομένου ἀληθὲς ηὑρίσκετο, δεομένης τελευταῖον ὁ Σαμψών, ἔδει γὰρ αὐτὸν συμφορᾷ περιπεσεῖν, χαρίζεσθαι βουλόμενος τῇ Δαλάλῃ, ἐμοῦ, φησίν, ὁ θεὸς κήδεται καὶ κατὰ τὴν ἐκείνου πρόνοιαν γεννηθεὶς κόμην ταύτην τρέφω παρεγγυήσαντος μὴ ἀποκείρειν τοῦ θεοῦ· τὴν γὰρ ἰσχὺν εἶναί μοι κατὰ τὴν ταύτης αὔξησιν καὶ παραμονήν ."},{"number":313,"text":"ταῦτα μαθοῦσα καὶ στερήσασα τῆς κόμης αὐτὸν παραδιδοῖ τοῖς πολεμίοις οὐκέτʼ ὄντα ἰσχυρὸν ἀμύνασθαι τὴν ἔφοδον αὐτῶν. οἱ δʼ ἐκκόψαντες αὐτοῦ τοὺς ὀφθαλμοὺς δεδεμένον ἄγειν παρέδοσαν."},{"number":314,"text":"Προϊόντος δὲ τοῦ χρόνου ηὔξετο ἡ κόμη τῷ Σαμψῶνι, καὶ ἑορτῆς οὔσης τοῖς Παλαιστίνοις δημοτελοῦς καὶ τῶν ἀρχόντων καὶ γνωριμωτάτων ἐν ταὐτῷ εὐωχουμένων, οἶκος δʼ ἦν δύο κιόνων στεγόντων αὐτοῦ τὸν ὄροφον, ἄγεται μεταπεμψαμένων ὁ Σαμψὼν εἰς τὸ συμπόσιον, ὅπως ἐνυβρίσωσιν αὐτῷ παρὰ τὸν πότον."},{"number":315,"text":"ὁ δὲ δεινότερον τῶν κακῶν ὑπολαμβάνων τὸ μὴ δύνασθαι ὑβριζόμενος ἀμύνασθαι, τὸν χειραγωγοῦντα παῖδα πείθει, προσαναπαύσασθαι χρῄζειν εἰπὼν ὑπὸ κόπου, τοῖς κίοσιν αὐτὸν ἐγγὺς ἀγαγεῖν."},{"number":316,"text":"ὡς δὲ ἧκεν, ἐνσεισθεὶς αὐτοῖς ἐπικαταβάλλει τὸν οἶκον ἀνατραπέντων τῶν κιόνων τρισχιλίοις ἀνδράσιν, οἳ πάντες ἀπέθανον, ἐν αὐτοῖς δὲ καὶ Σαμψών. καὶ τὸν μὲν τοιοῦτον κατέσχε τέλος ἄρξαντα τῶν Ἰσραηλιτῶν εἴκοσιν ἔτη."},{"number":317,"text":"θαυμάζειν δὲ ἄξιον τῆς ἀρετῆς καὶ τῆς ἰσχύος καὶ τοῦ περὶ τὴν τελευτὴν μεγαλόφρονος τὸν ἄνδρα καὶ τῆς ὀργῆς τῆς μέχρι τοῦ τελευτᾶν πρὸς τοὺς πολεμίους. καὶ τὸ μὲν ὑπὸ γυναικὸς ἁλῶναι δεῖ τῇ φύσει τῶν ἀνθρώπων προσάπτειν ἥττονι ἁμαρτημάτων οὔσῃ, μαρτυρεῖν δὲ ἐκείνῳ τὴν εἰς τὰ ἄλλα πάντα τῆς ἀρετῆς περιουσίαν. οἱ δὲ συγγενεῖς ἀράμενοι τὸ σῶμα αὐτοῦ θάπτουσιν ἐν Σαρασᾶ τῇ πατρίδι μετὰ τῶν συγγενῶν."}],"9":[{"number":318,"text":"Μετὰ δὲ τὴν Σαμψῶνος τελευτὴν προέστη τῶν Ἰσραηλιτῶν Ἠλὶς ὁ ἀρχιερεύς. ἐπὶ τούτου λιμῷ τῆς χώρας κακοπαθούσης αὐτῶν Ἀβιμέλεχος ἐκ Βηθλέμων, ἔστι δὲ ἡ πόλις αὕτη τῆς Ἰούδα φυλῆς, ἀντέχειν τῷ δεινῷ μὴ δυνάμενος τήν τε γυναῖκα Νααμεὶν καὶ τοὺς παῖδας τοὺς ἐξ αὐτῆς αὐτῷ γεγενημένους Χελλιῶνα καὶ Μαλαῶνα ἐπαγόμενος εἰς τὴν Μωαβῖτιν μετοικίζεται."},{"number":319,"text":"καὶ προχωρούντων αὐτῷ κατὰ νοῦν τῶν πραγμάτων ἄγεται τοῖς υἱοῖς γυναῖκας Μωαβίτιδας Χελλιῶνι μὲν Ὀρφᾶν Ῥούθην δὲ Μαλαῶνι. διελθόντων δὲ δέκα ἐτῶν ὅ τε Ἀβιμέλεχος καὶ μετʼ αὐτὸν οἱ παῖδες διʼ ὀλίγου τελευτῶσι,"},{"number":320,"text":"καὶ ἡ Ναάμις πικρῶς ἐπὶ τοῖς συμβεβηκόσι φέρουσα καὶ τὴν ὑπʼ ὄψιν τῶν φιλτάτων ἐρημίαν οὐχ ὑπομένουσα, διʼ ἣν καὶ τῆς πατρίδος ἐξεληλύθει, πάλιν εἰς αὐτὴν ἀπηλλάττετο·"},{"number":321,"text":"καὶ γὰρ ἤδη καλῶς τὰ κατʼ αὐτὴν ἐπυνθάνετο χωρεῖν. οὐκ ἐκαρτέρουν δὲ διαζευγνύμεναι αὐτῆς αἱ νύμφαι, οὐδὲ παραιτουμένη βουλομένας συνεξορμᾶν πείθειν ἐδύνατο, ἀλλʼ ἐγκειμένων εὐξαμένη γάμον εὐτυχέστερον αὐταῖς οὗ διημαρτήκεσαν παισὶ τοῖς αὐτῆς γαμηθεῖσαι καὶ τῶν ἄλλων ἀγαθῶν κτῆσιν, ὅτε τὰ πρὸς αὐτὴν οὕτως ἐστί,"},{"number":322,"text":"μένειν αὐτόθι παρεκάλει καὶ μὴ συμμεταλαμβάνειν αὐτῇ βούλεσθαι πραγμάτων ἀδήλων τὴν πάτριον γῆν καταλιπούσας. ἡ μὲν οὖν Ὀρφᾶ μένει, τὴν δὲ Ῥούθην μὴ πεισθεῖσαν ἀπήγαγε κοινωνὸν παντὸς τοῦ προστυχόντος γενησομένην."},{"number":323,"text":"Ἐλθοῦσαν δὲ Ῥούθην μετὰ τῆς πενθερᾶς εἰς τὴν Βηθλεέμων Βοώζης Ἀβιμελέχου συγγενὴς ὢν δέχεται ξενίᾳ. καὶ ἡ Ναάμις, προσαγορευόντων αὐτὴν ὀνομαστί, δικαιότερον εἶπε Μαρὰν καλεῖτέ με· σημαίνει δὲ καθʼ Ἑβραίων γλῶτταν ναάμις μὲν εὐτυχίαν, μαρὰ δὲ ὀδύνην."},{"number":324,"text":"ἀμήτου δὲ γενομένου ἐξῄει καλαμησομένη κατὰ συγχώρησιν τῆς πενθερᾶς ἡ Ῥούθη, ὅπως τροφῆς εὐποροῖεν, καὶ εἰς τὸ Βοώζου τυχαίως ἀφικνεῖται χωρίον. παραγενόμενος δὲ Βόαζος μετʼ ὀλίγον καὶ θεασάμενος τὴν κόρην ἀνέκρινε τὸν ἀγροκόμον περὶ τῆς παιδός. ὁ δὲ μικρὸν ἔμπροσθεν παρʼ αὐτῆς ἅπαντα προπεπυσμένος ἐδήλου τῷ δεσπότῃ."},{"number":325,"text":"ὁ δὲ τῆς περὶ τὴν πενθερὰν εὐνοίας ἅμα καὶ μνήμης τοῦ παιδὸς αὐτῆς ᾧ συνῴκησεν ἀσπασάμενος καὶ εὐξάμενος αὐτῇ πεῖραν ἀγαθῶν καλαμᾶσθαι μὲν αὐτὴν οὐκ ἠξίωσεν, θερίζειν δὲ πᾶν ὅ τι καὶ δύναιτο καὶ λαμβάνειν ἐπιτρέπει προστάξας τῷ ἀγροκόμῳ μηδὲν αὐτὴν διακωλύειν λαμβάνειν, ἄριστόν τε παρέχειν αὐτῇ καὶ ποτόν, ὁπότε σιτίζοι τοὺς θερίζοντας."},{"number":326,"text":"Ῥούθη δὲ ἄλφιτα λαβοῦσα παρʼ αὐτοῦ ἐφύλαξε τῇ ἑκυρᾷ καὶ παρῆν ὀψὲ κομίζουσα μετὰ τῶν σταχύων· ἐτετηρήκει δʼ αὐτῇ καὶ ἡ Ναάμις ἀπομοίρας βρωμάτων τινῶν, οἷς αὐτὴν ἐπολυώρουν οἱ γειτονεύοντες· διηγεῖται δὲ αὐτῇ καὶ τὰ παρὰ τοῦ Βοάζου πρὸς αὐτὴν εἰρημένα."},{"number":327,"text":"δηλωσάσης δʼ ἐκείνης ὡς συγγενής ἐστι καὶ τάχα ἂν διʼ εὐσέβειαν προνοήσειεν αὐτῶν, ἐξῄει πάλιν ταῖς ἐχομέναις ἡμέραις ἐπὶ καλάμης συλλογὴν σὺν ταῖς Βοάζου θεραπαινίσιν."},{"number":328,"text":"Ἐλθών τε μετʼ οὐ πολλὰς ἡμέρας καὶ Βόαζος ἤδη τῆς κριθῆς λελικμημένης ἐπὶ τῆς ἅλωος ἐκάθευδε. τοῦτο πυθομένη ἡ Ναάμις τεχνᾶται παρακατακλῖναι τὴν Ῥούθην αὐτῷ· καὶ γὰρ ἔσεσθαι χρηστὸν αὐταῖς ὁμιλήσαντα τῇ παιδί· καὶ πέμπει τὴν κόρην ὑπνωσομένην αὐτοῦ παρὰ τοῖς ποσίν."},{"number":329,"text":"ἡ δέ, πρὸς οὐδὲν γὰρ ἀντιλέγειν τῶν ὑπὸ τῆς ἑκυρᾶς κελευομένων ὅσιον ἡγεῖτο, παραγίνεται καὶ παραυτίκα μὲν λανθάνει τὸν Βόαζον βαθέως καθυπνωκότα, περιεγερθεὶς δὲ περὶ μέσην νύκτα καὶ αἰσθόμενος τῆς ἀνθρώπου παρακατακειμένης ἀνέκρινε τίς εἴη."},{"number":330,"text":"τῆς δʼ εἰπούσης τοὔνομα καὶ φαμένης ὡς αὐτῆς δεσπότην συγχωρεῖν, τότε μὲν ἡσυχίαν ἄγει, ὄρθριος δὲ πρὶν ἢ τοὺς οἰκέτας ἄρξασθαι κινεῖσθαι πρὸς τὸ ἔργον περιεγείρας αὐτὴν κελεύει τῶν κριθῶν λαβοῦσαν ὅ τι καὶ δύναιτο πορεύεσθαι πρὸς τὴν ἑκυρὰν πρὶν ὀφθῆναί τισιν αὐτόθι κεκοιμημένην, φυλάττεσθαι σῶφρον τὴν ἐπὶ τοιούτοις διαβολὴν καὶ μάλιστʼ ἐπὶ μὴ γεγονόσι."},{"number":331,"text":"περὶ μέντοι τοῦ παντὸς οὕτω, φησίν, ἔσται, ἐρωτᾶν τὸν ἔγγιστά μου τῷ γένει τυγχάνοντα, εἰ σοῦ χρεία γαμετῆς ἐστιν αὐτῷ, καὶ λέγοντι μὲν ἀκολουθήσεις ἐκείνῳ, παραιτουμένου δὲ νόμῳ σε συνοικήσουσαν ἄξομαι."},{"number":332,"text":"Ταῦτα τῇ ἑκυρᾷ δηλωσάσης εὐθυμία κατεῖχεν αὐτὰς ἐν ἐλπίδι τοῦ πρόνοιαν ἕξειν αὐτῶν Βόαζον γενομένας. κἀκεῖνος ἤδη μεσούσης τῆς ἡμέρας κατελθὼν εἰς τὴν πόλιν τήν τε γερουσίαν συνῆγε καὶ μεταπεμψάμενος Ῥούθην ἐκάλει καὶ τὸν συγγενῆ, καὶ παραγενομένου φησίν·"},{"number":333,"text":"Ἀβιμελέχου καὶ τῶν υἱῶν αὐτοῦ κλήρων κρατεῖς; ὁμολογήσαντος δὲ συγχωρούντων τῶν νόμων κατὰ ἀγχιστείαν, οὐκοῦν, φησὶν ὁ Βόαζος, οὐκ ἐξ ἡμισείας δεῖ μεμνῆσθαι τῶν νόμων. ἀλλὰ πάντα ποιεῖν κατʼ αὐτούς. Μαάλου γὰρ δεῦρʼ ἥκει γύναιον, ὅπερ εἰ θέλεις τῶν ἀγρῶν κρατεῖν γαμεῖν σε δεῖ κατὰ τοὺς νόμους."},{"number":334,"text":"ὁ δὲ Βοάζῳ καὶ τοῦ κλήρου καὶ τῆς γυναικὸς παρεχώρει συγγενεῖ μὲν ὄντι καὶ αὐτῷ τῶν τετελευτηκότων, εἶναι δὲ καὶ γυναῖκα λέγων αὐτῷ καὶ παῖδας ἤδη."},{"number":335,"text":"μαρτυράμενος οὖν ὁ Βόαζος τὴν γερουσίαν ἐκέλευε τῇ γυναικὶ ὑπολῦσαι αὐτὸν προσελθοῦσαν κατὰ τὸν νόμον καὶ πτύειν εἰς τὸ πρόσωπον. γενομένου δὲ τούτου Βόαζος γαμεῖ τὴν Ῥούθην καὶ γίνεται παιδίον αὐτοῖς μετʼ ἐνιαυτὸν ἄρρεν."},{"number":336,"text":"τοῦτο ἡ Ναάμις τιτθευομένη κατὰ συμβουλίαν τῶν γυναικῶν Ὠβήδην ἐκάλεσεν ἐπὶ γηροκομίᾳ τῇ αὐτῆς τραφησόμενον· ὠβήδης γὰρ κατὰ διάλεκτον τὴν Ἑβραίων ἀποσημαίνει δουλεύων. Ὠβήδου δὲ γίνεται παῖς Ἰεσσαῖος, τούτου Δαβίδης ὁ βασιλεύσας καὶ παισὶ τοῖς αὐτοῦ καταλιπὼν τὴν ἡγεμονίαν ἐπὶ μίαν καὶ εἴκοσι γενεὰς ἀνδρῶν."},{"number":337,"text":"τὰ μὲν οὖν κατὰ Ῥούθην ἀναγκαίως διηγησάμην ἐπιδεῖξαι βουλόμενος τὴν τοῦ θεοῦ δύναμιν, ὅτι τούτῳ παράγειν ἐφικτόν ἐστιν εἰς ἀξίωμα λαμπρὸν καὶ τοὺς ἐπιτυχόντας, εἰς οἷον ἀνήγαγε καὶ Δαβίδην ἐκ τοιούτων γενόμενον."}],"10":[{"number":338,"text":"Ἑβραῖοι δὲ τῶν πραγμάτων αὐτοῖς ὑπενεχθέντων πάλιν πόλεμον ἐκφέρουσι Παλαιστίνοις διὰ τοιαύτην αἰτίαν· Ἠλὶ τῷ ἀρχιερεῖ δύο παῖδες ἦσαν Ὁφνίης τε καὶ Φινεέσης."},{"number":339,"text":"οὗτοι καὶ πρὸς ἀνθρώπους ὑβρισταὶ γενόμενοι καὶ πρὸς τὸ θεῖον ἀσεβεῖς οὐδενὸς ἀπείχοντο παρανομήματος, καὶ τὰ μὲν ἐφέροντο τῶν γερῶν κατὰ τιμήν, ἃ δʼ ἐλάμβανον αὐτοῖς ἁρπαγῆς τρόπῳ, γυναῖκάς τε τὰς ἐπὶ θρησκείᾳ παραγινομένας ὕβριζον φθοραῖς ταῖς μὲν βίαν προσφέροντες τὰς δὲ δώροις ὑπαγόμενοι· τυραννίδος δʼ οὐθὲν ἀπέλειπεν ὁ βίος αὐτῶν."},{"number":340,"text":"ὅ τε οὖν πατὴρ αὐτὸς ἐπὶ τούτοις χαλεπῶς εἶχεν ὅσον οὐδέπω προσδοκῶν ἥξειν ἐκ θεοῦ τιμωρίαν αὐτοῖς ἐπὶ τοῖς πραττομένοις, τό τε πλῆθος ἐδυσφόρει, κἀπειδὴ φράζει τὴν ἐσομένην συμφορὰν ὁ θεὸς τοῖς παισὶν αὐτοῦ τῷ τε Ἠλὶ καὶ Σαμουήλῳ τῷ προφήτῃ παιδὶ τότε ὄντι, τότε φανερὸν ἐπὶ τοῖς υἱοῖς πένθος ἦγε."},{"number":341,"text":"Βούλομαι δὲ τὰ περὶ τοῦ προφήτου πρότερον διεξελθὼν ἔπειθʼ οὕτως τὰ περὶ τοὺς Ἠλὶ παῖδας εἰπεῖν καὶ τὴν δυστυχίαν τὴν τῷ παντὶ λαῷ Ἑβραίων γενομένην."},{"number":342,"text":"Ἀλκάνης Λευίτης ἀνὴρ τῶν ἐν μέσῳ πολιτῶν τῆς Ἐφράμου κληρουχίας Ῥαμαθὰν πόλιν κατοικῶν ἐγάμει δύο γυναῖκας Ἄνναν τε καὶ Φενάνναν. ἐκ δὴ ταύτης καὶ παῖδες αὐτῷ γίνονται, τὴν δʼ ἑτέραν ἄτεκνον οὖσαν ἀγαπῶν διετέλει."},{"number":343,"text":"ἀφικομένου δὲ μετὰ τῶν γυναικῶν τοῦ Ἀλκάνου εἰς Σιλὼ πόλιν θῦσαι, ἐνταῦθα γὰρ ἡ σκηνὴ τοῦ θεοῦ ἐπεπήγει καθὼς προειρήκαμεν, καὶ πάλιν κατὰ τὴν εὐωχίαν νέμοντος μοίρας κρεῶν ταῖς τε γυναιξὶ καὶ τοῖς τέκνοις, ἡ Ἄννα θεασαμένη τοὺς τῆς ἑτέρας παῖδας τῇ μητρὶ περικαθημένους, εἰς δάκρυά τε προύπεσε καὶ τῆς ἀπαιδίας αὑτὴν ὠλοφύρετο καὶ τῆς μονώσεως."},{"number":344,"text":"καὶ τῆς τἀνδρὸς παραμυθίας τῇ λύπῃ κρατήσασα εἰς τὴν σκηνὴν ᾤχετο τὸν θεὸν ἱκετεύουσα δοῦναι γονὴν αὐτῇ καὶ ποιῆσαι μητέρα, ἐπαγγελλομένη τὸ πρῶτον αὐτῇ γενησόμενον καθιερώσειν ἐπὶ διακονίᾳ τοῦ θεοῦ δίαιταν οὐχ ὁμοίαν τοῖς ἰδιώταις ποιησόμενον."},{"number":345,"text":"διατριβούσης δʼ ἐπὶ ταῖς εὐχαῖς πολὺν χρόνον Ἠλὶς ὁ ἀρχιερεύς, ἐκαθέζετο γὰρ πρὸ τῆς σκηνῆς, ὡς παροινοῦσαν ἐκέλευεν ἀπιέναι. τῆς δὲ πιεῖν ὕδωρ φαμένης, λυπουμένης δʼ ἐπὶ παίδων ἀπορίᾳ τὸν θεὸν ἱκετεύειν, θαρσεῖν παρεκελεύετο παρέξειν αὐτῇ παῖδας τὸν θεὸν καταγγέλλων."},{"number":346,"text":"Παραγενομένη δʼ εὔελπις πρὸς τὸν ἄνδρα τροφὴν χαίρουσα προσηνέγκατο, καὶ ἀναστρεψάντων εἰς τὴν πατρίδα κύειν ἤρξατο καὶ γίνεται παιδίον αὐτοῖς, ὃν Σαμουῆλον προσαγορεύουσι· θεαίτητον ἄν τις εἴποι. παρῆσαν οὖν ὑπὲρ τῆς τοῦ παιδὸς θύσοντες γενέσεως δεκάτας τʼ ἔφερον."},{"number":347,"text":"ἀναμνησθεῖσα δʼ ἡ γυνὴ τῆς εὐχῆς τῆς ἐπὶ τῷ παιδὶ γεγενημένης παρεδίδου τῷ Ἠλὶ ἀνατιθεῖσα τῷ θεῷ προφήτην γενησόμενον· κόμη τε οὖν αὐτῷ ἀνεῖτο καὶ ποτὸν ἦν ὕδωρ. καὶ Σαμουῆλος μὲν ἐν τῷ ἱερῷ διῆγε τρεφόμενος, Ἀλκάνῃ δʼ ἐκ τῆς Ἄννας υἱεῖς τε γίνονται καὶ τρεῖς θυγατέρες."},{"number":348,"text":"Σαμουῆλος δὲ πεπληρωκὼς ἔτος ἤδη δωδέκατον προεφήτευε. καί ποτε κοιμώμενον ὀνομαστὶ ἐκάλεσεν ὁ θεός· ὁ δὲ νομίσας ὑπὸ τοῦ ἀρχιερέως πεφωνῆσθαι παραγίνεται πρὸς αὐτόν. οὐ φαμένου δὲ καλέσαι τοῦ ἀρχιερέως ὁ θεὸς εἰς τρὶς τοῦτο ποιεῖ."},{"number":349,"text":"καὶ Ἠλὶς διαυγασθείς φησι πρὸς αὐτόν, ἀλλʼ ἐγὼ μὲν, Σαμουῆλε, σιγὴν ὡς καὶ τὸ πρὶν ἦγον, θεὸς δʼ ἐστὶν ὁ καλῶν, σήμαινέ τε πρὸς αὐτόν, ὅτι παρατυγχάνω. καὶ τοῦ θεοῦ φθεγξαμένου πάλιν ἀκούσας ἠξίου λαλεῖν ἐπὶ τοῖς χρωμένοις· οὐ γὰρ ὑστερήσειν αὐτὸν ἐφʼ οἷς ἂν θελήσῃ διακονίας."},{"number":350,"text":"καὶ ὁ θεός ἐπεί, φησί, παρατυγχάνεις, μάνθανε συμφορὰν Ἰσραηλίταις ἐσομένην λόγου μείζονα καὶ πίστεως τοῖς παρατυγχάνουσι, καὶ τοὺς Ἠλὶ δὲ παῖδας ἡμέρᾳ μιᾷ τεθνηξομένους καὶ τὴν ἱερωσύνην μετελευσομένην εἰς τὴν Ἐλεαζάρου οἰκίαν· Ἠλὶς γὰρ τῆς ἐμῆς θεραπείας μᾶλλον τοὺς υἱοὺς καὶ παρὰ τὸ συμφέρον αὐτοῖς ἠγάπησε."},{"number":351,"text":"ταῦτα βιασάμενος ὅρκοις εἰπεῖν αὐτῷ τὸν προφήτην Ἠλίς, οὐ γὰρ ἐβούλετο λυπεῖν αὐτὸν λέγων, ἔτι μᾶλλον βεβαιοτέραν εἶχε τὴν προσδοκίαν τῆς τῶν τέκνων ἀπωλείας. Σαμουήλου δὲ ηὔξετο ἐπὶ πλέον ἡ δόξα πάντων ὧν προεφήτευσεν ἀληθινῶν βλεπομένων."}],"11":[{"number":352,"text":"Κατὰ τοῦτον δὴ τὸν καιρὸν καὶ Παλαιστῖνοι στρατεύσαντες ἐπὶ τοὺς Ἰσραηλίτας στρατοπεδεύονται κατὰ πόλιν Ἀμφεκᾶν, δεξαμένων δʼ ἐξ ὀλίγου τῶν Ἰσραηλιτῶν συνῄεσαν εἰς τὴν ἐχομένην καὶ νικῶσιν οἱ Παλαιστῖνοι καὶ κτείνουσι μὲν τῶν Ἑβραίων εἰς τετρακισχιλίους, τὸ δὲ λοιπὸν πλῆθος συνδιώκουσιν εἰς τὸ στρατόπεδον."},{"number":353,"text":"Δείσαντες δὲ περὶ τῶν ὅλων Ἑβραῖοι πέμπουσιν ὡς τὴν γερουσίαν καὶ τὸν ἀρχιερέα τὴν κιβωτὸν τοῦ θεοῦ κελεύοντες κομίζειν, ἵνα παρούσης αὐτῆς παρατασσόμενοι κρατῶσι τῶν πολεμίων ἀγνοοῦντες, ὅτι μείζων ἐστὶν ὁ καταψηφισάμενος αὐτῶν τὴν συμφορὰν τῆς κιβωτοῦ, διʼ ὃν καὶ ταύτην συνέβαινεν εἶναι."},{"number":354,"text":"παρῆν τε οὖν ἡ κιβωτὸς καὶ οἱ τοῦ ἀρχιερέως υἱεῖς τοῦ πατρὸς αὐτοῖς ἐπιστείλαντος, εἰ ληφθείσης τῆς κιβωτοῦ ζῆν ἐθέλουσιν, εἰς ὄψιν αὐτῷ μὴ παραγίνεσθαι. Φινεέσης δὲ ἤδη καὶ ἱερᾶτο τοῦ πατρὸς αὐτῷ παρακεχωρηκότος διὰ τὸ γῆρας."},{"number":355,"text":"θάρσος οὖν ἐπιγίνεται πολὺ τοῖς Ἑβραίοις ὡς διὰ τὴν ἄφιξιν τῆς κιβωτοῦ περιεσομένοις τῶν πολεμίων, κατεπλήττοντο δὲ οἱ πολέμιοι δεδιότες τὴν παρουσίαν τῆς κιβωτοῦ τοῖς Ἰσραηλίταις. ταῖς μέντοι γε ἑκατέρων προσδοκίαις οὐχ ὅμοιον ἀπήντησε τὸ ἔργον,"},{"number":356,"text":"ἀλλὰ συμβολῆς γενομένης ἣν μὲν ἤλπιζον νίκην Ἑβραῖοι τῶν Παλαιστίνων αὕτη γίνεται, ἣν δʼ ἐφοβοῦντο ἧτταν οὗτοι ταύτην Ἑβραῖοι παθόντες ἔγνωσαν αὐτοὺς μάτην ἐπὶ τῇ κιβωτῷ τεθαρσηκότας· ἐτράπησάν τε γὰρ εὐθὺς εἰς χεῖρας ἐλθόντες τῶν πολεμίων καὶ ἀπέβαλον εἰς τρισμυρίους, ἐν οἷς ἔπεσον καὶ οἱ τοῦ ἀρχιερέως υἱεῖς, ἥ τε κιβωτὸς ἤγετο πρὸς τῶν πολεμίων."},{"number":357,"text":"Ἀπαγγελθείσης δὲ τῆς ἥττης εἰς τὴν Σιλὼ καὶ τῆς αἰχμαλωσίας τῆς κιβωτοῦ, Βενιαμίτης γάρ τις αὐτοῖς ἄγγελος ἀφικνεῖται νεανίας παρατετευχὼς τῷ γεγονότι, πένθους ἀνεπλήσθη πᾶσα ἡ πόλις."},{"number":358,"text":"καὶ Ἠλὶς ὁ ἀρχιερεύς, ἐκαθέζετο γὰρ καθʼ ἑτέρας τῶν πυλῶν ἐφʼ ὑψηλοῦ θρόνου, ἀκούσας οἰμωγῆς καὶ νομίσας νεώτερόν τι πεπρᾶχθαι περὶ τοὺς οἰκείους καὶ μεταπεμψάμενος τὸν νεανίαν, ὡς ἔγνω τὰ κατὰ τὴν μάχην, ῥᾴων ἦν ἐπὶ τὸ τοῖς παισὶ τοῖς αὐτοῦ συνενηνεγμένοις περὶ τὸ στρατόπεδον ὡς ἂν προεγνωκὼς παρὰ τοῦ θεοῦ τὸ συμβησόμενον καὶ προαπηγγελκώς· συνέχει γὰρ ἀκριβῶς τὰ κατὰ προσδοκίαν συντυχόντα τῶν δεινῶν."},{"number":359,"text":"ὡς δὲ καὶ τὴν κιβωτὸν ἤκουσεν ᾐχμαλωτίσθαι πρὸς τῶν πολεμίων, ὑπὸ τοῦ παρʼ ἐλπίδας αὐτῷ τοῦτο προσπεσεῖν περιαλγήσας ἀποκυλισθεὶς ἀπὸ τοῦ θρόνου τελευτᾷ, ὀκτὼ καὶ ἐνενήκοντα βιώσας ἔτη τὰ πάντα καὶ τούτων τεσσαράκοντα κατασχὼν τὴν ἀρχήν."},{"number":360,"text":"Θνήσκει δὲ κατʼ ἐκείνην τὴν ἡμέραν καὶ ἡ Φινεέσου τοῦ παιδὸς γυνὴ μὴ καρτερήσασα ζῆν ἐπὶ τῇ τἀνδρὸς δυστυχίᾳ. κυούσῃ μὲν αὐτῇ προσηγγέλη τὸ περὶ τὸν ἄνδρα πάθος, τίκτει δʼ ἑπταμηνιαῖον παῖδα, ὃν καὶ ζήσαντα Ἰαχώβην προσηγόρευσαν, σημαίνει δὲ ἀδοξίαν τὸ ὄνομα, διὰ τὴν προσπεσοῦσαν δύσκλειαν τότε τῷ στρατῷ."},{"number":361,"text":"Ἦρξε δὲ πρῶτος Ἠλὶς Ἰθαμάρου τῆς ἑτέρου τῶν Ἀαρῶνος υἱῶν οἰκίας· ἡ γὰρ Ἐλεαζάρου οἰκία τὸ πρῶτον ἱερᾶτο παῖς παρὰ πατρὸς ἐπιδεχόμενοι τὴν τιμήν, ἐκεῖνός τε Φινεέσῃ τῷ παιδὶ αὐτοῦ παραδίδωσι,"},{"number":362,"text":"μεθʼ ὃν Ἀβιεζέρης υἱὸς ὢν αὐτοῦ τὴν τιμὴν παραλαβὼν παιδὶ αὐτοῦ Βόκκι τοὔνομα αὐτὴν κατέλιπε, παρʼ οὗ διεδέξατο Ὄζις υἱὸς ὤν, μεθʼ ὃν Ἠλὶς ἔσχε τὴν ἱερωσύνην, περὶ οὗ νῦν ὁ λόγος, καὶ τὸ γένος τὸ ἀπʼ ἐκείνου μέχρι τῶν κατὰ τὴν τοῦ Σολομῶνος βασιλείαν καιρῶν. τότε δὲ οἱ Ἐλεαζάρου πάλιν αὐτὴν ἀπέλαβον."}]},"count":362};a[6]={"book":6,"title":"Τάδε ἔνεστιν ἐν τῇ ἕκτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Φθορὰ Παλαιστίνων καὶ τῆς γῆς αὐτῶν ἐξ ὀργῆς τοῦ θεοῦ διὰ τὴν αἰχμαλωτευθεῖσαν ὑπ' αὐτῶν κιβωτόν, καὶ τίνα τρόπον ἀπέπεμψαν αὐτὴν τοῖς Ἑβραίοις.\n\nβ. στρατεία Παλαιστίνων ἐπ' αὐτοὺς καὶ νίκη Ἑβραίων Σαμουήλου στρατηγοῦντος αὐτῶν τοῦ προφήτου.\n\nγ. ὡς Σαμουῆλος διὰ τὸ γῆρας ἀσθενὴς ὢν τὰ πράγματα διοικεῖν τοῖς παισὶν αὐτοῦ ἐνεχείρισεν.\n\nδ. ὡς οὐ καλῶς προϊσταμένων ἐκείνων τῆς ἀρχῆς τὸ πλῆθος ὑπ' ὀργῆς ᾐτήσατο βασιλεύεσθαι.\n\nε. Σαμουήλου πρὸς τοῦτο ἀγανάκτησις καὶ βασιλέως αὐτοῖς ἀνάδειξις Σαούλου τοὔνομα κελεύσαντος τοῦ θεοῦ.\n\nϛ. Σαούλου στρατεία ἐπὶ τὸ Ἀμμανιτῶν ἔθνος καὶ νίκη καὶ διαρπαγὴ τῶν πολεμίων.\n\nζ. ὡς στρατευσάμενοι πάλιν ἐπὶ τοὺς Ἑβραίους οἱ Παλαιστῖνοι ἡττήθησαν.\n\nη. Σαούλου πρὸς Ἀμαληκίτας πόλεμος καὶ νίκη.\n\nθ. ὅτι παραβαίνοντος Σαούλου τὰς ἐντολὰς τοῦ προφήτου Σαμουῆλος ἄλλον ἀπέδειξε βασιλέα κρύφα Δαβίδην ὄνομα κατ' ἐπιτροπὴν τοῦ θεοῦ.\n\nι. ὡς καὶ πάλιν ἐπεστράτευσαν τοῖς Ἑβραίοις οἱ Παλαιστῖνοι ἔτι Σαούλου βασιλεύοντος.\n\nια. μονομαχία Δαβίδου τότε πρὸς Γολίαθον τὸν ἄριστον τῶν Παλαιστίνων καὶ ἀναίρεσις τοῦ Γολιάθου καὶ ἧττα τῶν Παλαιστίνων.\n\nιβ. ὡς θαυμάσας τὸν Δαβίδην τῆς ἀνδρείας συνῴκισεν αὐτῷ τὴν θυγατέρα Σαοῦλος.\n\nιγ. ὅτι μετὰ ταῦτα ὕποπτον αὐτῷ τὸν Δαβίδην γενόμενον ὁ βασιλεὺς ἐσπούδασεν ἀποκτεῖναι.\n\nιδ. ὡς πολλάκις καὶ Δαβίδης κινδυνεύσας ἀποθανεῖν ὑπὸ τοῦ Σαούλου διέφυγε καὶ Σαοῦλον δὶς ἐπ' αὐτῷ γενόμενον ὥστε ἀνελεῖν οὐ διεχρήσατο.\n\nιε. ὡς στρατευσαμένων Παλαιστίνων πάλιν ἐπὶ τοὺς Ἑβραίους ἡττήθησαν οἱ Ἑβραῖοι τῇ μάχῃ καὶ ὁ βασιλεὺς αὐτῶν Σαοῦλος ἀπέθανε μετὰ τῶν παίδων μαχόμενος.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν λβ."},"chapters":{"1":[{"number":1,"text":"Λαβόντες δʼ οἱ Παλαιστῖνοι τὴν τῶν πολεμίων κιβωτὸν αἰχμάλωτον, ὡς προειρήκαμεν μικρὸν ἔμπροσθεν, εἰς Ἄζωτον ἐκόμισαν πόλιν καὶ παρὰ τὸν αὐτῶν θεὸν ὥσπερ τι λάφυρον, Δαγὼν δʼ οὗτος ἐκαλεῖτο, τιθέασι."},{"number":2,"text":"τῇ δʼ ἐπιούσῃ πάντες ὑπὸ τὴν τῆς ἡμέρας ἀρχὴν εἰσιόντες εἰς τὸν ναὸν προσκυνῆσαι τὸν θεὸν ἐπιτυγχάνουσιν αὐτῷ τοῦτο ποιοῦντι τὴν κιβωτὸν· ἔκειτο γὰρ ἐπʼ αὐτῆς ἀποπεπτωκὼς τῆς βάσεως, ἐφʼ ἧς ἑστὼς διετέλει· καὶ βαστάσαντες πάλιν ἐφιστᾶσιν αὐτὸν ἐπὶ ταύτης δυσφορήσαντες ἐπὶ τῷ γεγενημένῳ. πολλάκις δὲ φοιτῶντες παρὰ τὸν Δαγὼν καὶ καταλαμβάνοντες ὁμοίως ἐπὶ τοῦ προσκυνοῦντος τὴν κιβωτὸν σχήματος κείμενον ἐν ἀπορίᾳ δεινῇ καὶ συγχύσει καθίσταντο."},{"number":3,"text":"καὶ τελευταῖον ἀπέσκηψεν εἰς τὴν τῶν Ἀζωτίων πόλιν καὶ τὴν χώραν αὐτῶν φθορὰν τὸ θεῖον καὶ νόσον· ἀπέθνησκον γὰρ ὑπὸ δυσεντερίας, πάθους χαλεποῦ καὶ τὴν ἀναίρεσιν ὀξυτάτην ἐπιφέροντος πρὶν ἢ τὴν ψυχὴν αὐτοῖς εὐθανάτως ἀπολυθῆναι τοῦ σώματος, τὰ ἐντὸς ἀναφέροντες ἐξεμοῦντες διαβεβρωμένα καὶ παντοίως ὑπὸ τῆς νόσου διεφθαρμένα· τὰ δʼ ἐπὶ τῆς χώρας μυῶν πλῆθος ἀνελθὸν ἐπὶ τῆς γῆς κατέβλαψε μήτε φυτῶν μήτε καρπῶν ἀποσχόμενον."},{"number":4,"text":"ἐν δὴ τούτοις ὄντες τοῖς κακοῖς οἱ Ἀζώτιοι καὶ πρὸς τὰς συμφορὰς ἀντέχειν οὐ δυνάμενοι συνῆκαν ἐκ τῆς κιβωτοῦ ταύτας αὐτοῖς ἀνασχεῖν, καὶ τὴν νίκην καὶ τὴν ταύτης αἰχμαλωσίαν οὐκ ἐπʼ ἀγαθῷ γεγενημένην. πέμπουσιν οὖν πρὸς τοὺς Ἀσκαλωνίτας ἀξιοῦντες τὴν κιβωτὸν αὐτοὺς παρὰ σφᾶς δέχεσθαι."},{"number":5,"text":"τοῖς δὲ οὐκ ἀηδὴς ἡ τῶν Ἀζωτίων δέησις προσέπεσεν, ἀλλʼ ἐπινεύουσι μὲν αὐτοῖς τὴν χάριν, λαβόντες δὲ τὴν κιβωτὸν ἐν τοῖς ὁμοίοις δεινοῖς κατέστησαν· συνεξεκόμισε γὰρ αὑτῇ τὰ τῶν Ἀζωτίων ἡ κιβωτὸς πάθη πρὸς τοὺς ἀπʼ ἐκείνων αὐτὴν δεχομένους· καὶ πρὸς ἄλλους παρʼ αὑτῶν ἀποπέμπουσιν Ἀσκαλωνῖται."},{"number":6,"text":"μένει δʼ οὐδὲ παρʼ ἐκείνοις· ὑπὸ γὰρ τῶν αὐτῶν παθῶν ἐλαυνόμενοι πρὸς τὰς ἐχομένας ἀπολύουσι πόλεις. καὶ τοῦτον ἐκπεριέρχεται τὸν τρόπον τὰς πέντε τῶν Παλαιστίνων πόλεις ἡ κιβωτὸς ὥσπερ δασμὸν ἀπαιτοῦσα παρʼ ἑκάστης τοῦ πρὸς αὐτὰς ἐλθεῖν ἃ διʼ αὐτὴν ἔπασχον."},{"number":7,"text":"Ἀπειρηκότες δὲ τοῖς κακοῖς οἱ πεπειραμένοι καὶ τοῖς ἀκούουσιν αὐτὰ διδασκαλία γινόμενοι τοῦ μὴ προσδέξασθαι τὴν κιβωτόν ποτε πρὸς αὑτοὺς ἐπὶ τοιούτῳ μισθῷ καὶ τέλει, τὸ λοιπὸν ἐζήτουν μηχανὴν καὶ πόρον ἀπαλλαγῆς αὐτῆς."},{"number":8,"text":"καὶ συνελθόντες οἱ ἐκ τῶν πέντε πόλεων ἄρχοντες, Γίττης καὶ Ἀκάρων καὶ Ἀσκάλωνος ἔτι δὲ Γάζης καὶ Ἀζώτου, ἐσκόπουν τί δεῖ ποιεῖν. καὶ τὸ μὲν πρῶτον ἐδόκει τὴν κιβωτὸν ἀποπέμπειν τοῖς οἰκείοις, ὡς ὑπερεκδικοῦντος αὐτὴν τοῦ θεοῦ καὶ συνεπιδημησάντων αὐτῇ τῶν δεινῶν διὰ τοῦτο καὶ συνεισβαλόντων μετʼ ἐκείνης εἰς τὰς πόλεις αὐτῶν·"},{"number":9,"text":"ἦσαν δὲ οἱ λέγοντες τοῦτο μὲν μὴ ποιεῖν μηδʼ ἐξαπατᾶσθαι τὴν αἰτίαν τῶν κακῶν εἰς ἐκείνην ἀναφέροντας· οὐ γὰρ ταύτην εἶναι τὴν δύναμιν αὐτῇ καὶ τὴν ἰσχύν· οὐ γὰρ ἄν ποτʼ αὐτῆς κηδομένου τοῦ θεοῦ ὑποχείριον ἀνθρώποις γενέσθαι. ἡσυχάζειν δὲ καὶ πρᾴως ἔχειν ἐπὶ τοῖς συμβεβηκόσι παρῄνουν αἰτίαν τούτων οὐκ ἄλλην ἢ μόνην λογιζομένους τὴν φύσιν, ἣ καὶ σώμασι καὶ γῇ καὶ φυτοῖς καὶ πᾶσι τοῖς ἐξ αὐτῆς συνεστῶσι κατὰ χρόνων περιόδους τίκτει τοιαύτας μεταβολάς."},{"number":10,"text":"νικᾷ δὲ τὰς προειρημένας γνώμας ἀνδρῶν ἔν τε τοῖς ἐπάνω χρόνοις συνέσει καὶ φρονήσει διαφέρειν πεπιστευμένων συμβουλία καὶ τότε μάλιστα δοξάντων· ἁρμοζόντως λέγειν τοῖς παροῦσιν, οἳ μήτʼ ἀποπέμπειν ἔφασαν τὴν κιβωτὸν μήτε κατασχεῖν, ἀλλὰ πέντε μὲν ἀνδριάντας ὑπὲρ ἑκάστης πόλεως χρυσοῦς ἀναθεῖναι τῷ θεῷ χαριστήριον, ὅτι προενόησεν αὐτῶν τῆς σωτηρίας καὶ κατέσχεν ἐν τῷ βίῳ διωκομένους ἐξ αὐτοῦ παθήμασιν, οἷς οὐκέτι ἦν ἀντιβλέψαι, τοσούτους δὲ τὸν ἀριθμὸν μύας χρυσοῦς τοῖς κατανεμηθεῖσιν αὐτῶν καὶ διαφθείρασι τὴν χώραν ἐμφερεῖς·"},{"number":11,"text":"ἔπειτα βαλόντας εἰς γλωσσόκομον αὐτοὺς καὶ θέντας ἐπὶ τὴν κιβωτὸν ἅμαξαν αὐτῇ καινὴν κατασκευάσαι, καὶ βόας ὑποζεύξαντας ἀρτιτόκους τὰς μὲν πόρτις ἐγκλεῖσαι καὶ κατασχεῖν, μὴ ταῖς μητράσιν ἐμποδὼν ἑπόμεναι γένωνται, πόθῳ δʼ αὐτῶν ὀξυτέραν ποιῶνται τὴν πορείαν· ἐκείνας δʼ ἐξελάσαντας τὴν κιβωτὸν φερούσας ἐπὶ τριόδου καταλιπεῖν αὐταῖς ἐπιτρέψαντας ἣν βούλονται τῶν ὁδῶν ἀπελθεῖν·"},{"number":12,"text":"κἂν μὲν τὴν Ἑβραίων ἀπίωσι καὶ τὴν τούτων χώραν ἀναβαίνωσιν, ὑπολαμβάνειν τὴν κιβωτὸν αἰτίαν τῶν κακῶν, ἂν δὲ ἄλλην τράπωνται, μεταδιώξωμεν αὐτὴν, ἔφασαν, μαθόντες ὅτι μηδεμίαν ἰσχὺν τοιαύτην ἔχει."},{"number":13,"text":"Ἔκριναν δʼ αὐτὰ καλῶς εἰρῆσθαι καὶ τοῖς ἔργοις εὐθὺς τὴν γνώμην ἐκύρωσαν. καὶ ποιήσαντες μὲν τὰ προειρημένα προάγουσιν τὴν ἅμαξαν ἐπὶ τὴν τρίοδον καὶ καταλιπόντες ἀνεχώρησαν, τῶν δὲ βοῶν τὴν ὀρθὴν ὁδὸν ὥσπερ ἡγουμένου τινὸς αὐταῖς ἀπιουσῶν ἠκολούθουν οἱ τῶν Παλαιστίνων ἄρχοντες, ποῦ ποτε στήσονται καὶ πρὸς τίνας ἥξουσι βουλόμενοι μαθεῖν."},{"number":14,"text":"κώμη δέ τίς ἐστι τῆς Ἰούδα φυλῆς Βήθης ὄνομα· εἰς ταύτην ἀφικνοῦνται αἱ βόες, καὶ πεδίου μεγάλου καὶ καλοῦ τὴν πορείαν αὐτῶν ἐκδεξαμένου παύονται προσωτέρω χωρεῖν στήσασαι τὴν ἅμαξαν αὐτόθι. θέα δὲ ἦν τοῖς ἐν τῇ κώμῃ καὶ περιχαρεῖς ἐγένοντο· θέρους γὰρ ὥρᾳ πάντες ἐπὶ τὴν συγκομιδὴν τῶν καρπῶν ἐν ταῖς ἀρούραις ὑπάρχοντες ὡς εἶδον τὴν κιβωτὸν ὑφʼ ἡδονῆς ἁρπαγέντες καὶ τὸ ἔργον ἐκ τῶν χειρῶν ἀφέντες ἔδραμον εὐθὺς ἐπὶ τὴν ἅμαξαν."},{"number":15,"text":"καὶ καθελόντες τὴν κιβωτὸν καὶ τὸ ἄγγος, ὃ τοὺς ἀνδριάντας εἶχε καὶ τοὺς μύας, τιθέασιν ἐπί τινος πέτρας, ἥτις ἦν ἐν τῷ πεδίῳ, καὶ θύσαντες λαμπρῶς τῷ θεῷ καὶ κατευωχηθέντες τήν τε ἅμαξαν καὶ τοὺς βόας ὡλοκαύτωσαν. καὶ ταῦτʼ ἰδόντες οἱ τῶν Παλαιστίνων ἄρχοντες ἀνέστρεψαν ὀπίσω."},{"number":16,"text":"Ὀργὴ δὲ καὶ χόλος τοῦ θεοῦ μέτεισιν ἑβδομήκοντα τῶν ἐκ τῆς Βήθης κώμης, οὓς οὐκ ὄντας ἀξίους ἅψασθαι τῆς κιβωτοῦ, ἱερεῖς γὰρ οὐκ ἦσαν, καὶ προσελθόντας αὐτῇ βαλὼν ἀπέκτεινεν. ἔκλαυσαν δὲ ταῦτα παθόντας αὐτοὺς οἱ κωμῆται, καὶ πένθος ἐπʼ αὐτοῖς ἤγειραν οἷον εἰκὸς ἐπὶ θεοπέμπτῳ κακῷ καὶ τὸν ἴδιον ἕκαστος ἀπεθρήνει·"},{"number":17,"text":"τοῦ τε μένειν τὴν κιβωτὸν παρʼ αὐτοῖς ἀναξίους ἀποφαίνοντες αὑτοὺς καὶ πρὸς τὸ κοινὸν τῶν Ἑβραίων πέμψαντες ἐδήλουν ἀποδεδόσθαι τὴν κιβωτὸν ὑπὸ τῶν Παλαιστίνων. κἀκεῖνοι γνόντες τοῦτο ἀποκομίζουσιν αὐτὴν εἰς Καριαθιαρεὶμ γείτονα πόλιν τῆς Βήθης κώμης."},{"number":18,"text":"ἔνθα τινὸς Λευΐτου τὸ γένος Ἀμιναδάβου δόξαν ἔχοντος ἐπὶ δικαιοσύνῃ καὶ θρησκείᾳ καταβιοῦντος εἰς οἰκίαν τὴν κιβωτὸν ἤγαγον, ὥσπερ εἰς πρέποντα τῷ θεῷ τόπον ἐν ᾧ κατῴκει δίκαιος ἄνθρωπος. ἐθεράπευον δὲ τὴν κιβωτὸν οἱ τούτου παῖδες καὶ τῆς ἐπιμελείας ταύτης ἕως ἐτῶν εἴκοσι προέστησαν· τοσαῦτα γὰρ ἔμεινεν ἐν τῇ Καριαθιαρεὶμ ποιήσασα παρὰ τοῖς Παλαιστίνοις μῆνας τέσσαρας."}],"2":[{"number":19,"text":"Τοῦ δὲ λαοῦ παντὸς ἐκείνῳ τῷ χρόνῳ, καθʼ ὃν εἶχεν ἡ τῶν Καριαθιαρειμιτῶν πόλις τὴν κιβωτὸν, ἐπʼ εὐχὰς καὶ θυσίας τραπέντος τοῦ θεοῦ καὶ πολλὴν ἐμφανίζοντος τὴν περὶ αὐτὸν θρησκείαν καὶ φιλοτιμίαν, ὁ προφήτης Σαμουῆλος ἰδὼν αὐτῶν τὴν προθυμίαν, ὡς εὔκαιρον πρὸς οὕτως ἔχοντας εἰπεῖν περὶ ἐλευθερίας καὶ τῶν ἀγαθῶν τῶν ἐν αὐτῇ, χρῆται λόγοις οἷς ᾤετο μάλιστα τὴν διάνοιαν αὐτῶν προσάξεσθαι καὶ πείσειν·"},{"number":20,"text":"ἄνδρες, γὰρ εἶπεν, οἷς ἔτι νῦν βαρεῖς μὲν πολέμιοι Παλαιστῖνοι, θεὸς δʼ εὐμενὴς ἄρχεται γίνεσθαι καὶ φίλος, οὐκ ἐπιθυμεῖν ἐλευθερίας δεῖ μόνον, ἀλλὰ καὶ ποιεῖν διʼ ὧν ἂν ἔλθοι πρὸς ὑμᾶς, οὐδὲ βούλεσθαι μὲν ἀπηλλάχθαι δεσποτῶν ἐπιμένειν δὲ πράττοντας ἐξ ὧν οὗτοι διαμενοῦσιν·"},{"number":21,"text":"ἀλλὰ γίνεσθε δίκαιοι, καὶ τὴν πονηρίαν ἐκβαλόντες τῶν ψυχῶν καὶ θεραπεύσαντες αὐτὴν ὅλαις ταῖς διανοίαις προστρέπεσθε τὸ θεῖον καὶ τιμῶντες διατελεῖτε· ταῦτα γὰρ ὑμῖν ποιοῦσιν ἥξει τὰ ἀγαθά, δουλείας ἀπαλλαγὴ καὶ νίκη πολεμίων, ἃ λαβεῖν οὔθʼ ὅπλοις οὔτε σωμάτων ἀλκαῖς οὔτε πλήθει συμμάχων δυνατόν ἐστιν· οὐ γὰρ τούτοις ὁ θεὸς ὑπισχνεῖται παρέξειν αὐτά, τῷ δʼ ἀγαθοὺς εἶναι καὶ δικαίους· ἐγγυητὴς δὲ αὐτοῦ τῶν ὑποσχέσεων ἐγὼ γίνομαι."},{"number":22,"text":"ταῦτʼ εἰπόντος ἐπευφήμησε τὸ πλῆθος ἡσθὲν τῇ παραινέσει καὶ κατένευσεν αὑτὸ παρέξειν κεχαρισμένον τῷ θεῷ. συνάγει δʼ αὐτοὺς ὁ Σαμουῆλος εἴς τινα πόλιν λεγομένην Μασφάτην· κατοπτευόμενον τοῦτο σημαίνει κατὰ τὴν τῶν Ἑβραίων γλῶτταν· ἐντεῦθεν ὑδρευσάμενοί τε σπένδουσι τῷ θεῷ καὶ διανηστεύσαντες ὅλην τὴν ἡμέραν ἐπʼ εὐχὰς τρέπονται."},{"number":23,"text":"Οὐ λανθάνουσι δὲ τοὺς Παλαιστίνους ἐκεῖ συναχθέντες, ἀλλὰ μαθόντες οὗτοι τὴν ἄθροισιν αὐτῶν μεγάλῃ στρατιᾷ καὶ δυνάμει κατʼ ἐλπίδα τοῦ μὴ προσδοκῶσι μηδὲ παρεσκευασμένοις ἐπιπεσεῖσθαι τοῖς Ἑβραίοις ἐπέρχονται."},{"number":24,"text":"καταπλήττει δʼ αὐτοὺς τοῦτο καὶ εἰς ταραχὴν ἄγει καὶ δέος, καὶ δραμόντες πρὸς Σαμουῆλον, ἀναπεπτωκέναι τὰς ψυχὰς αὐτῶν ὑπὸ φόβου καὶ τῆς προτέρας ἥττης ἔφασκον καὶ διὰ τοῦτʼ ἠρεμεῖν, ἵνα μὴ κινήσωμεν τὴν τῶν πολεμίων δύναμιν, σοῦ δʼ ἀναγαγόντος ἡμᾶς ἐπʼ εὐχὰς καὶ θυσίας καὶ ὅρκους γυμνοῖς καὶ ἀνόπλοις ἐπεστράτευσαν οἱ πολέμιοι· ἐλπὶς οὖν ἡμῖν οὐκ ἄλλη σωτηρίας, ἢ μόνη ἡ παρὰ σοῦ καὶ τοῦ θεοῦ ἱκετευθέντος ὑπὸ σοῦ παρασχεῖν ἡμῖν διαφυγεῖν Παλαιστίνους."},{"number":25,"text":"ὁ δὲ θαρρεῖν τε προτρέπεται καὶ βοηθήσειν αὐτοῖς τὸν θεὸν ἐπαγγέλλεται καὶ λαβὼν ἄρνα γαλαθηνόν, ὑπὲρ τῶν ὄχλων θύει καὶ παρακαλεῖ τὸν θεὸν ὑπερσχεῖν αὐτῶν τὴν δεξιὰν ἐν τῇ πρὸς Παλαιστίνους μάχῃ καὶ μὴ περιϊδεῖν αὐτοὺς δεύτερον δυστυχήσαντας. ἐπήκοος δὲ γίνεται τῶν εὐχῶν ὁ θεὸς, καὶ προσδεξάμενος εὐμενεῖ καὶ συμμάχῳ τῇ διανοίᾳ τὴν θυσίαν ἐπινεύει νίκην αὐτοῖς καὶ κράτος."},{"number":26,"text":"ἔτι δʼ ἐπὶ τοῦ βωμοῦ τὴν θυσίαν ἔχοντος τοῦ θεοῦ καὶ μήπω πᾶσαν διὰ τῆς ἱερᾶς φλογὸς ἀπειληφότος προῆλθεν ἐκ τοῦ στρατοπέδου ἡ τῶν πολεμίων δύναμις καὶ παρατάσσεται εἰς μάχην, ἐπʼ ἐλπίδι μὲν νίκης, ὡς ἀπειλημμένων ἐν ἀπορίᾳ τῶν Ἰουδαίων μήτε ὅπλα ἐχόντων μήτε ὡς ἐπὶ μάχῃ ἐκεῖσε ἀπηντηκότων, περιπίπτουσι δὲ οἷς οὐδʼ εἰ προύλεγέ τις ῥᾳδίως ἐπείσθησαν."},{"number":27,"text":"πρῶτον μὲν γὰρ αὐτοὺς ὁ θεὸς κλονεῖ σεισμῷ καὶ τὴν γῆν αὐτοῖς ὑπότρομον καὶ σφαλερὰν κινήσας τίθησιν, ὡς σαλευομένης τε τὰς βάσεις ὑποφέρεσθαι καὶ διϊσταμένης εἰς ἔνια τῶν χασμάτων καταφέρεσθαι, ἔπειτα βρονταῖς καταψοφήσας καὶ διαπύροις ἀστραπαῖς ὡς καταφλέξων αὐτῶν τὰς ὄψεις περιλάμψας καὶ τῶν χειρῶν ἐκκροτήσας τὰ ὅπλα, γυμνοὺς εἰς φυγὴν ἀπέστρεψεν."},{"number":28,"text":"ἐπεξέρχεται δὲ Σαμουῆλος μετὰ τῆς πληθύος καὶ πολλοὺς κατασφάξας κατακολουθεῖ μέχρι Κορραίων τόπου τινὸς οὕτω λεγομένου, καὶ καταπήξας ἐκεῖ λίθον ὥσπερ ὅρον τῆς νίκης καὶ τῆς φυγῆς τῶν πολεμίων, ἰσχυρὸν αὐτὸν προσαγορεύει σύμβολον τῆς παρὰ τοῦ θεοῦ γενομένης αὐτοῖς κατὰ τῶν ἐχθρῶν ἰσχύος."},{"number":29,"text":"Οἱ δὲ μετʼ ἐκείνην τὴν πληγὴν οὐκέτʼ ἐστράτευσαν ἐπὶ τοὺς Ἰσραηλίτας, ἀλλʼ ὑπὸ δέους καὶ μνήμης τῶν συμβεβηκότων ἡσύχαζον· ὃ δʼ ἦν πάλαι θάρσος τοῖς Παλαιστίνοις ἐπὶ τοὺς Ἑβραίους, τοῦτʼ ἐκείνων μετὰ τὴν νίκην ἐγένετο."},{"number":30,"text":"καὶ Σαμουῆλος στρατεύσας ἐπʼ αὐτοὺς ἀναιρεῖ πολλοὺς καὶ τὰ φρονήματʼ αὐτῶν εἰς τὸ παντελὲς ταπεινοῖ καὶ τὴν χώραν ἀφαιρεῖται, ἣν τῶν Ἰουδαίων ἀπετέμοντο πρότερον κρατήσαντες τῇ μάχῃ· αὕτη δʼ ἦν μέχρι πόλεως Ἀκάρων ἀπὸ τῶν τῆς Γίττης ὅρων ἐκτεταμένη. ἦν δὲ κατʼ ἐκεῖνον τὸν καιρὸν φίλια τοῖς Ἰσραηλίταις τὰ ὑπολειπόμενα τῶν Χαναναίων."}],"3":[{"number":31,"text":"Ὁ δὲ προφήτης Σαμουῆλος διακοσμήσας τὸν λαὸν καὶ πόλιν αὐτοῖς ἀποδοὺς εἰς ταύτην ἐκέλευσε συνερχομένοις περὶ τῶν πρὸς ἀλλήλους κρίνεσθαι διαφορῶν, αὐτὸς δὲ διʼ ἔτους ἐπερχόμενος τὰς πόλεις ἐδίκαζεν αὐτοῖς καὶ πολλὴν ἐβράβευεν εὐνομίαν ἐπὶ χρόνον πολύν."},{"number":32,"text":"ἔπειθʼ ὑπὸ γήρως βαρυνόμενος καὶ τὰ συνήθη πράττειν ἐμποδιζόμενος τοῖς υἱοῖς τὴν ἀρχὴν καὶ τὴν προστασίαν τοῦ ἔθνους παραδίδωσιν, ὧν ὁ μὲν πρεσβύτερος Ἰοῦλος προσηγορεύετο, τῷ δὲ νεωτέρῳ Ἐβίᾳ ὄνομα ἦν. προσέταξε δὲ τὸν μὲν ἐν Βεθήλῳ πόλει καθεζόμενον κρίνειν, τὸν δʼ ἕτερον ἐν Βερσουβεὶ μερίσας τὸν ὑπακουσόμενον ἑκατέρῳ λαόν."},{"number":33,"text":"ἐγένοντο δὲ σαφὲς οὗτοι παράδειγμα καὶ τεκμήριον τοῦ μὴ τὸν τρόπον ὁμοίους τοῖς φύσασι γίνεσθαί τινας, ἀλλὰ τάχα μὲν χρηστοὺς καὶ μετρίους ἐκ πονηρῶν, τότε μέν γε φαύλους ἐξ ἀγαθῶν παρέσχον αὑτοὺς γενομένους·"},{"number":34,"text":"τῶν γὰρ τοῦ πατρὸς ἐπιτηδευμάτων ἐκτραπόμενοι καὶ τὴν ἐναντίαν ὁδὸν ἀπελθόντες δώρων καὶ λημμάτων αἰσχρῶν καθυφίεντο τὸ δίκαιον, καὶ τὰς κρίσεις οὐ πρὸς τὴν ἀλήθειαν, ἀλλὰ πρὸς τὸ κέρδος ποιούμενοι καὶ πρὸς τρυφὴν καὶ πρὸς διαίτας πολυτελεῖς ἀπονενευκότες πρῶτον μὲν ὑπεναντία ταῦτα ἔπρασσον τῷ θεῷ, δεύτερον δὲ τῷ προφήτῃ πατρὶ δʼ ἑαυτῶν, ὃς πολλὴν καὶ τοῦ τὸ πλῆθος εἶναι δίκαιον σπουδὴν εἰσεφέρετο καὶ πρόνοιαν."},{"number":35,"text":"Ὁ δὲ λαὸς ἐξυβριζόντων εἰς τὴν προτέραν κατάστασιν καὶ πολιτείαν τῶν τοῦ προφήτου παίδων χαλεπῶς τε τοῖς πραττομένοις ἔφερε καὶ πρὸς αὐτὸν συντρέχουσι, διέτριβε δʼ ἐν Ἀρμαθᾶ πόλει, καὶ τάς τε τῶν υἱῶν παρανομίας ἔλεγον καὶ ὅτι γηραιὸς ὢν αὐτὸς ἤδη καὶ παρειμένος ὑπὸ τοῦ χρόνου τῶν πραγμάτων οὐκέτι τὸν αὐτὸν προεστάναι δύναται τρόπον· ἐδέοντό τε καὶ ἱκέτευον ἀποδεῖξαί τινα αὐτῶν βασιλέα, ὃς ἄρξει τοῦ ἔθνους καὶ τιμωρήσεται Παλαιστίνους ὀφείλοντας ἔτʼ αὐτοῖς δίκας τῶν προτέρων ἀδικημάτων."},{"number":36,"text":"ἐλύπησαν δὲ σφόδρα τὸν Σαμουῆλον οἱ λόγοι διὰ τὴν σύμφυτον δικαιοσύνην καὶ τὸ πρὸς τοὺς βασιλέας μῖσος· ἥττητο γὰρ δεινῶς τῆς ἀριστοκρατίας ὡς θείας καὶ μακαρίους ποιούσης τοὺς χρωμένους αὐτῆς τῇ πολιτείᾳ."},{"number":37,"text":"ὑπὸ δὲ φροντίδος καὶ βασάνου τῆς ἐπὶ τοῖς εἰρημένοις οὔτε τροφῆς ἐμνημόνευσεν οὔτε ὕπνου, διʼ ὅλης δὲ τῆς νυκτὸς στρέφων τὰς περὶ τῶν πραγμάτων ἐννοίας διεκαρτέρει."},{"number":38,"text":"Ἔχοντι δὲ οὕτως ἐμφανίζεται τὸ θεῖον καὶ παραμυθεῖται μὴ δυσφορεῖν ἐφʼ οἷς ἠξίωσε τὸ πλῆθος, ὡς οὐκ ἐκεῖνον ὑπερηφανήσοντας ἀλλʼ ἑαυτὸν, εἰ μὴ βασιλεύσει μόνος· ταῦτα δὲ ἀφʼ ἧς ἡμέρας ἐξήγαγεν αὐτοὺς ἀπʼ Αἰγύπτου μηχανᾶσθαι τὰ ἔργα· λήψεσθαι μέντοι γε οὐκ εἰς μακρὰν μετάνοιαν αὐτοὺς ἐπίπονον, ὑφʼ ἧς οὐδὲν μὲν ἀγένητον ἔσται τῶν ἐσομένων, ἐλεγχθήσονται δὲ καταφρονήσαντες καὶ βουλὰς οὐκ εὐχαρίστους πρὸς ἐμὲ καὶ τὴν σὴν προφητείαν λαβόντες."},{"number":39,"text":"κελεύω δή σε χειροτονεῖν αὐτοῖς ὃν ἂν ἐγὼ προείπω βασιλέα προδηλώσαντα ποταπῶν τε πειραθήσονται βασιλευόμενοι κακῶν καὶ διαμαρτυράμενον ἐφʼ οἵαν σπεύδουσι μεταβολήν."},{"number":40,"text":"Ταῦτʼ ἀκούσας Σαμουῆλος ἅμα ἕῳ συγκαλέσας τοὺς Ἰουδαίους ἀποδείξειν αὐτοῖς βασιλέα ὡμολόγησεν, ἔφη δὲ δεῖν πρῶτον μὲν αὐτοῖς ἐκδιηγήσασθαι τὰ παρὰ τῶν βασιλέων ἐσόμενα καὶ ὅσοις συνενεχθήσονται κακοῖς· γινώσκετε γὰρ ὅτι πρῶτον μὲν ὑμῶν ἀποσπάσουσι τὰ τέκνα καὶ τὰ μὲν αὐτῶν ἁρματηλάτας εἶναι κελεύσουσι, τοὺς δʼ ἱππεῖς καὶ σωματοφύλακας, δρομεῖς δὲ ἄλλους καὶ χιλιάρχους καὶ ἑκατοντάρχους, ποιήσουσι δὲ καὶ τεχνίτας ὁπλοποιοὺς καὶ ἁρματοποιοὺς καὶ ὀργάνων τέκτονας γεωργούς τε καὶ τῶν ἰδίων ἀγρῶν ἐπιμελητὰς καὶ σκαπανεῖς ἀμπέλων,"},{"number":41,"text":"καὶ οὐδέν ἐστιν ὃ μὴ κελευόμενοι ποιήσουσιν ἀνδραπόδων ἀργυρωνήτων τρόπον· καὶ τὰς θυγατέρας δʼ ὑμῶν μυρεψοὺς ἀποφανοῦσι καὶ ὀψοποιοὺς καὶ σιτοποιούς, καὶ πᾶν ἔργον ὃ θεραπαινίδες ἐξ ἀνάγκης πληγὰς φοβούμεναι καὶ βασάνους ὑπηρετήσουσι. κτῆσιν δὲ τὴν ὑμετέραν ἀφαιρήσονται καὶ ταύτην εὐνούχοις καὶ σωματοφύλαξι δωρήσονται καὶ βοσκημάτων ἀγέλας τοῖς αὑτῶν προσνεμοῦσι."},{"number":42,"text":"συνελόντι δʼ εἰπεῖν, δουλεύσετε μετὰ πάντων τῶν ὑμετέρων τῷ βασιλεῖ σὺν τοῖς αὑτῶν οἰκέταις· ὃς γενόμενος μνήμην ὑμῖν τῶνδε τῶν λόγων γεννήσει καὶ τῷ πάσχειν αὐτὰ μεταγινώσκοντας ἱκετεῦσαι τὸν θεὸν ἐλεῆσαί τε ὑμᾶς καὶ δωρήσασθαι ταχεῖαν ἀπαλλαγὴν τῶν βασιλέων· ὁ δʼ οὐ προσδέξεται τὰς δεήσεις, ἀλλὰ παραπέμψας ἐάσει δίκην ὑποσχεῖν ὑμᾶς τῆς αὑτῶν κακοβουλίας."},{"number":43,"text":"Ἦν δʼ ἄρα καὶ πρὸς τὰς προρρήσεις τῶν συμβησομένων ἀνόητον τὸ πλῆθος καὶ δύσκολον ἐξελεῖν τῆς διανοίας κρίσιν ἤδη παρὰ τῷ λογισμῷ καθιδρυμένην· οὐδὲ γὰρ ἐπεστράφησαν οὐδʼ ἐμέλησεν αὐτοῖς τῶν Σαμουήλου λόγων, ἀλλʼ ἐνέκειντο λιπαρῶς καὶ χειροτονεῖν ἠξίουν ἤδη τὸν βασιλέα καὶ μὴ φροντίζειν τῶν ἐσομένων·"},{"number":44,"text":"ἐπὶ γὰρ τιμωρίᾳ τῶν ἐχθρῶν ἀνάγκη τὸν πολεμήσοντα σὺν αὑτοῖς ἔχειν, καὶ οὐδὲν ἄτοπον εἶναι τῶν πλησιοχώρων βασιλευομένων τὴν αὐτὴν ἔχειν αὐτοὺς πολιτείαν. ὁρῶν δʼ αὐτοὺς μηδʼ ὑπὸ τῶν προειρημένων ἀπεστραμμένους ὁ Σαμουῆλος, ἀλλʼ ἐπιμένοντας νῦν μὲν, εἶπεν, ἄπιτε πρὸς αὑτοὺς ἕκαστος, μεταπέμψομαι δὲ ὑμᾶς εἰς δέον, ὅταν μάθω παρὰ τοῦ θεοῦ τίνα δίδωσιν ὑμῖν βασιλέα."}],"4":[{"number":45,"text":"Ἦν δέ τις ἐκ τῆς Βενιαμίτιδος φυλῆς ἀνὴρ εὖ γεγονὼς καὶ ἀγαθὸς τὸ ἦθος, Κεὶς ὄνομα· τούτῳ παῖς ὑπῆρχεν, ἦν δὲ νεανίας τὴν μορφὴν ἄριστος καὶ τὸ σῶμα μέγας τό τε φρόνημα καὶ τὴν διάνοιαν ἀμείνων τῶν βλεπομένων· Σαοῦλον αὐτὸν ἐκάλουν."},{"number":46,"text":"οὗτος ὁ Κείς, ὄνων αὐτῷ ἐκ τῆς νομῆς καλῶν ἀποπλανηθεισῶν, ἥδετο γὰρ αὐταῖς ὡς οὐκ ἄλλῳ τινὶ τῶν κτημάτων, τὸν υἱὸν μεθʼ ἑνὸς θεράποντος ἐπὶ ζήτησιν τῶν κτηνῶν ἐξέπεμψεν· ὁ δʼ ἐπεὶ τὴν πάτριον περιῆλθε φυλὴν εἰς τὰς ἄλλας ἀφίκετο, οὐδʼ ἐν ταύταις δʼ ἐπιτυχὼν ἀπιέναι διεγνώκει, μὴ ποιήσῃ περὶ αὑτοῦ τῷ πατρὶ λοιπὸν φροντίδα."},{"number":47,"text":"τοῦ δʼ ἑπομένου θεράποντος ὡς ἐγένοντο κατὰ τὴν Ἁραμαθὰ πόλιν εἶναι προφήτην ἐν αὐτῇ φήσαντος ἀληθῆ καὶ πρὸς αὐτὸν βαδίζειν συμβουλεύσαντος, γνώσεσθαι γὰρ παρʼ αὐτοῦ τὸ περὶ τῶν ὄνων τέλος, οὐθὲν ἔχειν πορευθέντας εἶπεν ἀντὶ τῆς προφητείας ὃ παράσχωσιν αὐτῷ· κεκενῶσθαι γὰρ ἤδη τῶν ἐφοδίων."},{"number":48,"text":"τοῦ δʼ οἰκέτου τέταρτον αὐτῷ παρεῖναι σίκλου φήσαντος καὶ τοῦτο δώσειν, ὑπὸ γὰρ ἀγνοίας τοῦ μὴ λαμβάνειν τὸν προφήτην μισθὸν ἐπλανῶντο, παραγίνονται καὶ πρὸς ταῖς πύλαις παρατυγχάνοντες παρθένοις ἐφʼ ὕδωρ βαδιζούσαις ἐρωτῶσιν αὐτὰς τοῦ προφήτου τὴν οἰκίαν. αἱ δὲ σημαίνουσι καὶ σπεύδειν παρεκελεύσαντο πρὶν αὐτὸν εἰς τὸ δεῖπνον κατακλιθῆναι· πολλοὺς γὰρ ἑστιᾶν καὶ προκατακλίνεσθαι τῶν κεκλημένων."},{"number":49,"text":"ὁ δὲ Σαμουῆλος διὰ τοῦτο πολλοὺς ἐπὶ τὴν ἑστίαν τότε συνήγαγε· δεομένῳ γὰρ κατὰ πᾶσαν ἡμέραν αὐτῷ τοῦ θεοῦ προειπεῖν τίνα ποιήσει βασιλέα τῇ παρελθούσῃ τοῦτον μηνύσαντος, πέμψειν γὰρ αὐτός τινα νεανίσκον ἐκ τῆς Βενιαμίτιδος φυλῆς κατὰ τήνδε τὴν ὥραν, αὐτὸς μὲν ἐπὶ τοῦ δώματος καθεζόμενος ἐξεδέχετο τὸν καιρὸν γενέσθαι, πληρωθέντος δʼ αὐτοῦ καταβὰς ἐπὶ τὸ δεῖπνον ἐπορεύετο."},{"number":50,"text":"συναντᾷ δὲ τῷ Σαούλῳ καὶ ὁ θεὸς αὐτῷ σημαίνει τοῦτον εἶναι τὸν ἄρξειν μέλλοντα. Σαοῦλος δὲ πρόσεισι τῷ Σαμουήλῳ καὶ προσαγορεύσας ἐδεῖτο μηνύειν τὴν οἰκίαν τοῦ προφήτου· ξένος γὰρ ὢν ἀγνοεῖν ἔφασκε."},{"number":51,"text":"τοῦ δὲ Σαμουήλου αὐτὸν εἶναι φράσαντος καὶ ἄγοντος ἐπὶ τὸ δεῖπνον, ὡς τῶν ὄνων ἐφʼ ὧν τὴν ζήτησιν ἐκπεμφθείη σεσωσμένων τά τε πάντα ἀγαθὰ ἔχειν αὐτῷ κεκυρωμένα, προστυχών ἀλλʼ ἥττων, εἶπεν, ἐγὼ, δέσποτα, ταύτης τῆς ἐλπίδος καὶ φυλῆς μικροτέρας ἢ βασιλέας ποιεῖν καὶ πατριᾶς ταπεινοτέρας τῶν ἄλλων πατριῶν. σὺ δὲ παίζεις καὶ γέλωτά με τίθεσαι περὶ μειζόνων ἢ κατὰ τὴν ἐμὴν χώραν διαλεγόμενος."},{"number":52,"text":"ὁ δὲ προφήτης ἀγαγὼν αὐτὸν ἐπὶ τὴν ἑστίαν κατακλίνει καὶ τὸν ἀκόλουθον ἐπάνω τῶν κεκλημένων· οὗτοι δʼ ἦσαν ἑβδομήκοντα τὸν ἀριθμόν· προστάσσει δὲ τοῖς διακόνοις παραθεῖναι τῷ Σαούλῳ μερίδα βασιλικήν. ἐπεὶ δὲ κοίτης ὥρα προσῆγεν οἱ μὲν ἀναστάντες ἀπελύοντο πρὸς αὑτοὺς ἕκαστοι, ὁ δὲ Σαοῦλος παρὰ τῷ προφήτῃ σὺν τῷ θεράποντι κατεκοιμήθη."},{"number":53,"text":"Ἅμα δὲ ἡμέρᾳ Σαμουῆλος ἀναστήσας αὐτὸν ἐκ τῆς κοίτης προύπεμπε καὶ γενόμενος ἔξω τῆς πόλεως ἐκέλευσε τὸν μὲν θεράποντα ποιῆσαι προελθεῖν, ὑπολείπεσθαι δὲ αὐτὸν· ἔχειν γὰρ αὐτῷ τι φράσαι μηδενὸς ἄλλου παρόντος."},{"number":54,"text":"καὶ ὁ μὲν Σαοῦλος ἀποπέμπεται τὸν ἀκόλουθον, λαβὼν δʼ ὁ προφήτης τὸ ἅγιον ἔλαιον καταχεῖ τῆς τοῦ νεανίσκου κεφαλῆς καὶ κατασπασάμενος ἴσθι, φησὶ, βασιλεὺς ὑπὸ τοῦ θεοῦ κεχειροτονημένος ἐπί τε Παλαιστίνους καὶ τὴν ὑπὲρ Ἑβραίων ἄμυναν. τούτων δὲ ἔσται σοι σημεῖον ὅ σε βούλομαι προγινώσκειν·"},{"number":55,"text":"ὅταν ἀπέλθῃς ἐντεῦθεν καταλήψῃ τρεῖς ἀνθρώπους ἐν τῇ ὁδῷ προσκυνῆσαι τῷ θεῷ πορευομένους εἰς Βέθηλα, ὧν τὸν μὲν πρῶτον τρεῖς ἄρτους ὄψει κομίζοντα, τὸν δὲ δεύτερον ἔριφον, ὁ τρίτος δὲ ἀσκὸν οἴνου φέρων ἀκολουθήσει. ἀσπάσονται δέ σε οὗτοι καὶ φιλοφρονήσονται καὶ δώσουσί σοι ἄρτους δύο, σὺ δὲ λήψῃ."},{"number":56,"text":"κἀκεῖθεν ἥξεις εἰς τὸ Ῥαχήλας καλούμενον μνημεῖον, ὅπου συμβαλεῖς τῷ σεσῶσθαί σου τὰς ὄνους εὐαγγελιουμένῳ· ἔπειτʼ ἐκεῖθεν ἐλθὼν εἰς Γεβαθὰ προφήταις ἐκκλησιάζουσιν ἐπιτεύξῃ καὶ γενόμενος ἔνθεος προφητεύσεις σὺν αὐτοῖς, ὡς πάνθʼ ὅντινʼ ὁρῶντα ἐκπλήττεσθαί τε καὶ θαυμάζειν λέγοντα πόθεν εἰς τοῦτο εὐδαιμονίας ὁ Κεισαίου παῖς παρῆλθεν; ὅταν δέ σοι ταῦτα γένηται τὰ σημεῖα,"},{"number":57,"text":"τὸν θεὸν ἴσθι μετὰ σοῦ τυγχάνοντα, ἄσπασαί τε τὸν πατέρα σου καὶ τοὺς συγγενεῖς. ἥξεις δὲ μετάπεμπτος εἰς Γάλγαλα ὑπʼ ἐμοῦ, ἵνα χαριστήρια τούτων θύσωμεν τῷ θεῷ. φράσας ταῦτα καὶ προειπὼν ἀποπέμπει τὸν νεανίσκον· τῷ Σαούλῳ δὲ πάντα κατὰ τὴν Σαμουήλου προφητείαν ἀπήντησεν."},{"number":58,"text":"Ὡς δὲ ἦλθεν εἰς τὴν οἰκίαν τοῦ συγγενοῦς αὐτοῦ Ἀβηνάρου, καὶ γὰρ ἐκεῖνον τῶν ἄλλων οἰκείων μᾶλλον ἔστεργεν, ἀνερωτῶντος περὶ τῆς ἀποδημίας καὶ τῶν κατʼ αὐτὸν γεγονότων τῶν μὲν ἄλλων οὐδὲν ἀπεκρύψατο οὐδʼ ὡς ἀφίκοιτο παρὰ Σαμουῆλον τὸν προφήτην οὐδʼ ὡς ἐκεῖνος αὐτῷ σεσῶσθαι τὰς ὄνους ἔφρασε, περὶ δὲ τῆς βασιλείας καὶ τῶν κατʼ αὐτὴν,"},{"number":59,"text":"ἃ φθόνον ἀκουόμενα καὶ ἀπιστίαν ἔχειν ᾤετο, σιωπᾷ πρὸς αὐτὸν καὶ οὐδὲ πρὸς εὔνουν σφόδρα δοκοῦντα εἶναι καὶ περισσότερον τῶν ἀφʼ αἵματος ὑπʼ αὐτοῦ στεργόμενον ἀσφαλὲς ἢ σῶφρον ἔδοξε μηνύειν λογισάμενος οἶμαι τὴν ἀνθρωπίνην φύσιν οἵα ταῖς ἀληθείαις ἐστίν, ὅτι βεβαίως οὐδεὶς οὔτε φίλων οὔτε συγγενῶν οὐδʼ ἄχρι τῶν παρὰ τοῦ θεοῦ λαμπρῶν ἀποσώζει τὴν διάθεσιν, ἀλλὰ πρὸς τὰς ὑπεροχὰς κακοήθεις τυγχάνουσιν ἤδη καὶ βάσκανοι."},{"number":60,"text":"Σαμουῆλος δὲ καλεῖ τὸν λαὸν εἰς Μασφὰ πόλιν καὶ πρὸς αὐτὸν διατίθεται λόγους, οὓς κατʼ ἐντολὴν φράζειν ἔλεγε τοῦ θεοῦ, ὅτι τὴν ἐλευθερίαν αὐτοῖς ἐκείνου παρασχόντος καὶ τοὺς πολεμίους δουλώσαντος ἀμνημονήσειαν τῶν εὐεργεσιῶν, καὶ τὸν μὲν θεὸν ἀποχειροτονοῦσι τῆς βασιλείας οὐκ εἰδότες ὡς συμφορώτατον ὑπὸ τοῦ πάντων ἀρίστου προστατεῖσθαι,"},{"number":61,"text":"θεὸς δὲ πάντων ἄριστος, αἱροῦνται δʼ ἔχειν ἄνθρωπον βασιλέα, ὃς ὡς κτήματι τοῖς ὑποτεταγμένοις κατὰ βούλησιν καὶ ἐπιθυμίαν καὶ τῶν ἄλλων παθῶν ὁρμὴν χρήσεται τῆς ἐξουσίας ἀφειδῶς ἐμφορούμενος, ἀλλʼ οὐχ ὡς ἴδιον ἔργον καὶ κατασκεύασμα τὸ τῶν ἀνθρώπων γένος οὕτως διατηρῆσαι σπουδάσει, ὁ θεὸς δὲ κατὰ ταύτην τὴν αἰτίαν κήδοιτο. ἀλλʼ ἐπεὶ δέδοκται ταῦτα ὑμῖν καὶ κεκράτηκεν ἡ πρὸς τὸν θεὸν ὕβρις, τάχθητε πάντες κατὰ φυλάς τε καὶ σκῆπτρα καὶ κλήρους βάλετε."},{"number":62,"text":"Ποιησάντων δὲ τοῦτο τῶν Ἑβραίων ὁ τῆς Βενιαμίτιδος κλῆρος ἐξέπεσε, ταύτης δὲ κληρωθείσης ἔλαχεν ἡ Ματρὶς καλουμένη πατριὰ, ἧς κατʼ ἄνδρα κληρωθείσης λαγχάνει ὁ Κεισαίου βασιλεύειν παῖς Σαοῦλος."},{"number":63,"text":"γνοὺς δὲ τοῦθʼ ὁ νεανίσκος φθάσας ἐκποδὼν αὑτὸν ἐποίει μὴ βουλόμενος οἶμαι δοκεῖν τὴν ἀρχὴν ἑκὼν λαμβάνειν, ἀλλὰ τοσαύτην ἐνεδείξατο ἐγκράτειαν καὶ σωφροσύνην, ὥστε τῶν πλείστων οὐδʼ ἐπὶ μικραῖς εὐπραγίαις τὴν χαρὰν κατασχεῖν δυναμένων, ἀλλʼ εἰς τὸ πᾶσι γενέσθαι φανεροὺς προπιπτόντων, ὁ δʼ οὐ μόνον οὐδὲν ἐνέφηνε τοιοῦτον ἐπὶ βασιλείᾳ καὶ τῷ τοσούτων καὶ τηλικούτων ἐθνῶν ἀποδεδεῖχθαι δεσπότης, ἀλλὰ καὶ τῆς ὄψεως αὑτὸν τῆς τῶν βασιλευθησομένων ἐξέκλεψεν καὶ ζητεῖν αὐτὸν καὶ περὶ τοῦτο πονεῖν παρεσκεύασεν."},{"number":64,"text":"ὧν ἀμηχανούντων καὶ φροντιζόντων, ὅτι καὶ γένοιτο ἀφανὴς ὁ Σαοῦλος, ὁ προφήτης ἱκέτευε τὸν θεὸν δεῖξαι ποῦ ποτʼ εἴη καὶ παρασχεῖν εἰς ἐμφανὲς τὸν νεανίσκον."},{"number":65,"text":"μαθὼν δὲ παρὰ τοῦ θεοῦ τὸν τόπον ἔνθα κρύπτεται ὁ Σαοῦλος πέμπει τοὺς ἄξοντας αὐτὸν καὶ παραγενόμενον ἵστησι μέσον τοῦ πλήθους. ἐξεῖχε δὲ ἁπάντων, καὶ τὸ ὕψος ἦν βασιλικώτατος."},{"number":66,"text":"Λέγει δὲ ὁ προφήτης· τοῦτον ὑμῖν ὁ θεὸς ἔδωκε βασιλέα· ὁρᾶτε δὲ ὡς καὶ κρείττων ἐστὶ πάντων καὶ τῆς ἀρχῆς ἄξιος. ὡς δʼ ἐπευφήμησε τῷ βασιλεῖ σωτηρίαν ὁ λαὸς, τὰ μέλλοντα συμβήσεσθαι καταγράψας αὐτοῖς ὁ προφήτης ἀνέγνω τοῦ βασιλέως ἀκροωμένου καὶ τὸ βιβλίον τίθησιν ἐν τῇ τοῦ θεοῦ σκηνῇ ταῖς μετέπειτα γενεαῖς μαρτύριον ὧν προείρηκε."},{"number":67,"text":"ταῦτʼ ἐπιτελέσας ὁ Σαμουῆλος ἀπολύει τὴν πληθύν. καὶ αὐτὸς δὲ εἰς Ἀρμαθὰ παραγίνεται πόλιν, πατρὶς γὰρ ἦν αὐτῷ, Σαούλῳ δὲ ἀπερχομένῳ εἰς Γαβαθὴν, ἐξ ἧς ὑπῆρχε, συνήρχοντο πολλοὶ μὲν ἀγαθοὶ τὴν προσήκουσαν βασιλεῖ τιμὴν νέμοντες, πονηροὶ δὲ πλείους, οἳ καταφρονοῦντες αὐτοῦ καὶ τοὺς πολλοὺς ἐχλεύαζον καὶ οὔτε δῶρα προσέφερον οὔτʼ ἐν σπουδῇ καὶ λόγῳ τὸ ἀρέσκεσθαι τὸν Σαοῦλον ἐτίθεντο."}],"5":[{"number":68,"text":"Μηνὶ δʼ ὕστερον ἄρχει τῆς παρὰ πάντων αὐτῷ τιμῆς ὁ πρὸς Ναάσην πόλεμος τὸν τῶν Ἀμμανιτῶν βασιλέα· οὗτος γὰρ πολλὰ κακὰ τοὺς πέραν τοῦ Ἰορδάνου ποταμοῦ κατῳκημένους τῶν Ἰουδαίων διατίθησι μετὰ πολλοῦ καὶ μαχίμου στρατεύματος διαβὰς ἐπʼ αὐτούς·"},{"number":69,"text":"καὶ τὰς πόλεις αὐτῶν εἰς δουλείαν ὑπάγεται ἰσχύι μὲν καὶ βίᾳ πρὸς τὸ παρὸν αὐτοὺς χειρωσάμενος, σοφίᾳ δὲ καὶ ἐπινοίᾳ πρὸς τὸ μηδʼ αὖθις ἀποστάντας δυνηθῆναι τὴν ὑπʼ αὐτῷ δουλείαν διαφυγεῖν ἀσθενεῖς ποιῶν· τῶν γὰρ ἢ κατὰ πίστιν ὡς αὐτὸν ἀφικνουμένων ἢ λαμβανομένων πολέμου νόμῳ τοὺς δεξιοὺς ὀφθαλμοὺς ἐξέκοπτεν."},{"number":70,"text":"ἐποίει δὲ τοῦθʼ, ὅπως τῆς ἀριστερᾶς αὐτοῖς ὄψεως ὑπὸ τῶν θυρεῶν καλυπτομένης ἄχρηστοι παντελῶς εἶεν."},{"number":71,"text":"καὶ ὁ μὲν τῶν Ἀμμανιτῶν βασιλεὺς ταῦτʼ ἐργασάμενος τοὺς πέραν τοῦ Ἰορδάνου ἐπὶ τοὺς Γαλαδηνοὺς λεγομένους ἐπεστράτευσε καὶ στρατοπεδευσάμενος πρὸς τῇ μητροπόλει τῶν πολεμίων, Ἰαβὶς δʼ ἐστὶν αὕτη, πέμπει πρὸς αὐτοὺς πρέσβεις κελεύων ἤδη παραδοῦναι σφᾶς αὐτοὺς ἐπὶ τῷ τοὺς δεξιοὺς αὐτῶν ὀφθαλμοὺς ἐξορύξαι, ἢ πολιορκήσειν ἠπείλει καὶ τὰς πόλεις αὐτῶν ἀναστήσειν· τὴν δʼ αἵρεσιν ἐπʼ αὐτοῖς εἶναι, πότερόν ποτε βραχύ τι τοῦ σώματος ἀποτεμεῖν θέλουσιν ἢ παντάπασιν ἀπολωλέναι."},{"number":72,"text":"οἱ δὲ Γαλαδηνοὶ καταπλαγέντες πρὸς οὐδέτερον μὲν ἐτόλμησαν οὐδὲν εἰπεῖν οὔτʼ εἰ παραδιδόασιν αὑτοὺς οὔτʼ εἰ πολεμοῦσιν, ἀνοχὴν δʼ ἡμερῶν ἑπτὰ λαβεῖν ἠξίωσαν, ἵνα πρεσβευσάμενοι πρὸς τοὺς ὁμοφύλους παρακαλέσωσι συμμαχεῖν αὐτοῖς καὶ εἰ μὲν ἔλθοι βοήθεια πολεμῶσιν, εἰ δʼ ἄπορα εἴη τὰ παρʼ ἐκείνων παραδώσειν αὑτοὺς ἔφασκον ἐπὶ τῷ παθεῖν ὅτι ἂν αὐτῷ δοκῇ."},{"number":73,"text":"Ὁ δὲ Ναάσης καταφρονήσας τοῦ τῶν Γαλαδηνῶν πλήθους καὶ τῆς ἀποκρίσεως αὐτῶν δίδωσί τε αὐτοῖς τὴν ἀνοχὴν καὶ πέμπειν πρὸς οὓς ἂν θέλωσι συμμάχους ἐπιτρέπει. πέμπουσιν οὖν εὐθὺς κατὰ πόλιν τοῖς Ἰσραηλίταις οἳ ἤγγελλον τὰ παρὰ τοῦ Ναάσου καὶ τὴν ἀμηχανίαν ἐν ᾗ καθειστήκεσαν."},{"number":74,"text":"οἱ δʼ εἰς δάκρυα καὶ λύπην ὑπὸ τῆς ἀκοῆς τῶν περὶ τοὺς Ἰαβισηνοὺς προήχθησαν καὶ πέρα τούτων οὐδὲν αὐτοῖς ἄλλο πράττειν συνεχώρει τὸ δέος· γενομένων δὲ τῶν ἀγγέλων καὶ ἐν τῇ Σαούλου τοῦ βασιλέως πόλει καὶ τοὺς κινδύνους ἐν οἷς εἶναι συνέβαινε τοὺς Ἰαβισηνοὺς φρασάντων, ὁ μὲν λαὸς ταὐτὰ τοῖς πρώτοις ἔπασχεν· ὠδύρετο γὰρ τὴν συμφορὰν τὴν τῶν συγγενῶν·"},{"number":75,"text":"ὁ δὲ Σαοῦλος ἀπὸ τῶν περὶ τὴν γεωργίαν παραγενόμενος ἔργων εἰς τὴν πόλιν ἐπιτυγχάνει κλαίουσι τοῖς αὑτοῦ πολίταις, καὶ πυθόμενος τὴν αἰτίαν τῆς συγχύσεως καὶ κατηφείας αὐτῶν μανθάνει τὰ παρὰ τῶν ἀγγέλων."},{"number":76,"text":"καὶ ἔνθεος γενόμενος ἀποπέμπει μὲν τοὺς Ἰαβισηνοὺς ὑποσχόμενος αὐτοῖς ἥξειν βοηθὸς τῇ τρίτῃ τῶν ἡμερῶν καὶ πρὶν ἥλιον ἀνασχεῖν κρατήσειν τῶν πολεμίων, ἵνα καὶ νενικηκότας ἤδη καὶ τῶν φόβων ἀπηλλαγμένους ὁ ἥλιος ἐπιτείλας ἴδῃ· ὑπομεῖναι δʼ ἐκέλευσέ τινας αὐτῶν ἡγησομένους τῆς ὁδοῦ."},{"number":77,"text":"Βουλόμενος δὲ φόβῳ ζημίας τὸν λαὸν ἐπὶ τὸν πρὸς Ἀμμανίτας ἐπιστρέψαι πόλεμον καὶ συνελθεῖν αὐτοὺς ὀξύτερον, ὑποτεμὼν τῶν αὐτοῦ βοῶν τὰ νεῦρα ταὐτὰ διαθήσειν ἠπείλησε τοὺς ἁπάντων, εἰ μὴ πρὸς τὸν Ἰόρδανον ὡπλισμένοι κατὰ τὴν ἐπιοῦσαν ἀπαντήσουσιν ἡμέραν καὶ ἀκολουθήσουσιν αὐτῷ καὶ Σαμουήλῳ τῷ προφήτῃ, ὅπου ποτʼ ἂν αὐτοὺς ἀγάγωσι."},{"number":78,"text":"τῶν δὲ διʼ εὐλάβειαν τῆς κατεπηγγελμένης ζημίας εἰς τὸν ὡρισμένον καιρὸν συνελθόντων ἐξαριθμεῖται ἐν Βαλᾶ τῇ πόλει τὸ πλῆθος· εὑρίσκει δὲ τὸν ἀριθμὸν χωρὶς τῆς Ἰούδα φυλῆς εἰς ἑβδομήκοντα μυριάδας συνειλεγμένους, τῆς δὲ φυλῆς ἐκείνης ἦσαν μυριάδες ἑπτά."},{"number":79,"text":"διαβὰς δὲ τὸν Ἰόρδανον καὶ σχοίνων δέκα διʼ ὅλης τῆς νυκτὸς ἀνύσας ὁδὸν φθάνει μὲν ἥλιον ἀνίσχοντα, τριχῇ δὲ τὸ στράτευμα διελὼν ἐπιπίπτει πανταχόθεν αἰφνιδίως οὐ προσδοκῶσι τοῖς ἐχθροῖς, καὶ συμβαλὼν εἰς μάχην ἄλλους τε πολλοὺς ἀποκτείνει τῶν Ἀμμανιτῶν καὶ Ναάσην τὸν βασιλέα."},{"number":80,"text":"τοῦτο λαμπρὸν ἐπράχθη τῷ Σαούλῳ τὸ ἔργον καὶ πρὸς πάντας αὐτὸν διήγγειλε τοὺς Ἑβραίους ἐπαινούμενον καὶ θαυμαστῆς ἀπολαύοντα δόξης ἐπʼ ἀνδρείᾳ· καὶ γὰρ εἴ τινες ἦσαν οἳ πρότερον αὐτοῦ κατεφρόνουν, τότε μετέστησαν ἐπὶ τὸ τιμᾶν καὶ πάντων ἄριστον νομίζειν· οὐ γὰρ ἤρκεσεν αὐτῷ τοὺς Ἰαβισηνοὺς σεσωκέναι μόνον, ἀλλὰ καὶ τῇ τῶν Ἀμμανιτῶν ἐπιστρατεύσας χώρᾳ πᾶσαν αὐτὴν καταστρέφεται καὶ πολλὴν λαβὼν λείαν λαμπρὸς εἰς τὴν οἰκείαν ὑπέστρεψεν."},{"number":81,"text":"ὁ δὲ λαὸς ὑφʼ ἡδονῆς τῶν Σαούλῳ κατωρθωμένων ἔχαιρε μὲν ὅτι τοιοῦτον ἐχειροτόνησε βασιλέα, πρὸς δὲ τοὺς οὐδὲν ὄφελος αὐτὸν ἔσεσθαι τοῖς πράγμασι λέγοντας ἐβόων· ποῦ νῦν εἰσὶν οὗτοι καὶ δότωσαν δίκην καὶ πάνθʼ ὅσα φιλεῖ λέγειν ὄχλος ἐπʼ εὐπραγίαις ἠρμένος πρὸς τοὺς ἐξευτελίζοντας ἔναγχος τοὺς τούτων αἰτίους."},{"number":82,"text":"Σαοῦλος δὲ τούτων μὲν ἠσπάζετο τὴν εὔνοιαν καὶ τὴν περὶ αὐτὸν προθυμίαν, ὤμοσε δὲ μήτινα περιόψεσθαι τῶν ὁμοφύλων ἀναιρούμενον ἐπʼ ἐκείνης τῆς ἡμέρας· ἄτοπον γὰρ εἶναι τὴν ὑπὸ τοῦ θεοῦ δεδομένην νίκην αἵματι φῦραι καὶ φόνῳ τῶν πρὸς ἀλλήλους συγγενῶν ἑορτάζειν."},{"number":83,"text":"Σαμουήλου δὲ φήσαντος καὶ δευτέρᾳ δεῖν χειροτονίᾳ Σαούλῳ τὴν βασιλείαν ἐπικυρῶσαι συνίασι πάντες εἰς Γάλγαλα πόλιν· ἐκεῖ γὰρ αὐτοὺς ἐκέλευσεν ἐλθεῖν. καὶ πάλιν ὁρῶντος τοῦ πλήθους ὁ προφήτης χρίει τὸν Σαοῦλον τῷ ἁγίῳ ἐλαίῳ καὶ δεύτερον ἀναγορεύει βασιλέα. καὶ οὕτως ἡ τῶν Ἑβραίων πολιτεία εἰς βασιλείαν μετέπεσεν."},{"number":84,"text":"ἐπὶ γὰρ Μωυσέος καὶ τοῦ μαθητοῦ αὐτοῦ Ἰησοῦ, ὃς ἦν στρατηγὸς, ἀριστοκρατούμενοι διετέλουν· μετὰ δὲ τὴν ἐκείνου τελευτὴν ἔτεσι τοῖς πᾶσι δέκα καὶ πρὸς τούτοις ὀκτὼ τὸ πλῆθος αὐτῶν ἀναρχία κατέσχε."},{"number":85,"text":"μετὰ ταῦτα δʼ εἰς τὴν προτέραν ἐπανῆλθον πολιτείαν τῷ κατὰ πόλεμον ἀρίστῳ δόξαντι γεγενῆσθαι καὶ κατʼ ἀνδρείαν περὶ τῶν ὅλων δικάζειν ἐπιτρέποντες· καὶ διὰ τοῦτο τὸν χρόνον τοῦτον τῆς πολιτείας κριτῶν ἐκάλεσαν."},{"number":86,"text":"Ἐκκλησίαν δὲ Σαμουῆλος ποιήσας ὁ προφήτης τῶν Ἑβραίων ἐπόμνυμαι, φησίν, ὑμῖν τὸν μέγιστον θεὸν, ὃς τοὺς ἀδελφοὺς ἐκείνους, λέγω δὴ Μωυσῆν καὶ Ἀαρῶνα, παρήγαγεν εἰς τὸν βίον καὶ τοὺς πατέρας ἡμῶν ἐξήρπασεν Αἰγυπτίων καὶ τῆς ὑπʼ αὐτοῖς δουλείας, μηδὲν μήτʼ αἰδοῖ χαρισαμένους μήτε ὑποστειλαμένους φόβῳ μήτε ἄλλῳ τινὶ πάθει παραχωρήσαντας εἰπεῖν, εἴ τι μοι πέπρακται σκαιὸν καὶ ἄδικον ἢ κέρδους ἕνεκα ἢ πλεονεξίας ἢ χάριτος τῆς πρὸς ἄλλους·"},{"number":87,"text":"ἐλέγξαι δὲ εἰ καὶ τῶν τοιούτων τι προσηκάμην μόσχον ἢ πρόβατον, ἃ πρὸς τροφὴν ἀνεμέσητον δοκεῖ λαμβάνειν, ἢ εἴ τινος ὑποζύγιον εἰς ἐμὴν ἀποσπάσας χρείαν ἐλύπησα, τούτων ἕν τι κατειπεῖν παρόντος ὑμῶν τοῦ βασιλέως. οἱ δὲ ἀνέκραγον τούτων οὐδὲν ὑπʼ αὐτοῦ γεγονέναι, προστῆναι δὲ ὁσίως αὐτὸν καὶ δικαίως τοῦ ἔθνους."},{"number":88,"text":"Σαμουῆλος δὲ ταύτης ἐξ ἁπάντων τῆς μαρτυρίας αὐτῷ γενομένης ἐπεὶ δεδώκατέ μοι, φησί, τὸ μηδὲν ἄτοπον ἔθʼ ὑμᾶς περὶ ἐμοῦ δύνασθαι λέγειν, φέρε νῦν μετὰ παρρησίας ἀκούσατέ μου λέγοντος, ὅτι μεγάλα ἠσεβήσατε εἰς τὸν θεὸν αἰτησάμενοι βασιλέα."},{"number":89,"text":"διαμνημονεύειν δὲ ὑμᾶς προσῆκεν, ὅτι σὺν ἑβδομήκοντα μόνοις ἐκ τοῦ γένους ἡμῶν ὁ πάππος Ἰάκωβος διὰ λιμὸν εἰς Αἴγυπτον ἦλθε, κἀκεῖ πολλῶν μυριάδων ἐπιτεκνωθεισῶν, ἃς εἰς δουλείας καὶ χαλεπὰς ὕβρεις ἤγαγον οἱ Αἰγύπτιοι, ὁ θεὸς εὐξαμένων τῶν πατέρων χωρὶς βασιλέως παρέσχεν αὐτοῖς ῥύσασθαι τῆς ἀνάγκης τὸ πλῆθος Μωυσῆν αὐτοῖς καὶ Ἀαρῶνα πέμψας ἀδελφοὺς, οἳ ἤγαγον ὑμᾶς εἰς τήνδε τὴν γῆν, ἣν νῦν ἔχετε."},{"number":90,"text":"καὶ τούτων ἀπολαύσαντες ἐκ τοῦ θεοῦ προδεδώκατε τὴν θρησκείαν καὶ τὴν εὐσέβειαν. οὐ μὴν ἀλλὰ καὶ τοῖς πολεμίοις ὑποχειρίους γενομένους ἠλευθέρωσε πρῶτον μὲν Ἀσσυρίων καὶ τῆς ἐκείνων ἰσχύος ὑπερτέρους ἀπεργασάμενος, ἔπειτα Ἀμμανιτῶν κρατῆσαι παρασχὼν καὶ Μωαβιτῶν καὶ τελευταίων Παλαιστίνων. καὶ ταῦτʼ οὐ βασιλέως ἡγουμένου διεπράξασθε, ἀλλʼ Ἰφθάε καὶ Γεδεῶνος στρατηγούντων."},{"number":91,"text":"τίς οὖν ἔσχεν ὑμᾶς ἄνοια φυγεῖν μὲν τὸν θεὸν, ὑπὸ βασιλέα δὲ εἶναι θέλειν; ἀλλʼ ἐγὼ μὲν ἀπέδειξα τοῦτον ὃν αὐτὸς ἐπελέξατο, ἵνα μέντοι γε φανερὸν ποιήσω τὸν θεὸν ὀργιζόμενον καὶ δυσχεραίνοντα τῇ τῆς βασιλείας ὑμῶν αἱρέσει, δηλῶσαι τοῦθʼ ὑμῖν τὸν θεὸν παρασκευάσω διὰ σημείων ἐναργῶς· ὃ γὰρ οὐδέπω πρότερον εἶδεν ὑμῶν οὐδεὶς ἐνταῦθα γεγενημένον, θέρους ἀκμῇ χειμῶνα, αἰτησάμενος τὸν θεὸν παρέξω τοῦτο νῦν ὑμῖν ἐπιγνῶναι."},{"number":92,"text":"καὶ ταῦτα εἰπόντος πρὸς τὸ πλῆθος τοῦ Σαμουήλου βρονταῖς σημαίνει τὸ θεῖον καὶ ἀστραπαῖς καὶ χαλάζης καταφορᾷ τὴν τοῦ προφήτου περὶ πάντων ἀλήθειαν, ὡς τεθαμβηκότας αὐτοὺς καὶ περιδεεῖς γινομένους ἁμαρτεῖν τε ὁμολογεῖν καὶ κατʼ ἄγνοιαν εἰς τοῦτο προπεσεῖν, καὶ ἱκετεύειν τὸν προφήτην ὡς πατέρα χρηστὸν καὶ ἐπιεικῆ τὸν θεὸν αὐτοῖς εὐμενῆ καταστῆσαι καὶ ταύτην ἀφεῖναι τὴν ἁμαρτίαν, ἣν πρὸς οἷς ἐξύβρισαν ἄλλοις καὶ παρηνόμησαν προσεξειργάσαντο."},{"number":93,"text":"ὁ δὲ ὑπισχνεῖται καὶ παρακαλέσειν τὸν θεὸν συγγνῶναι περὶ τούτων αὐτοῖς καὶ πείσειν, συνεβούλευε μέντοι δικαίους εἶναι καὶ ἀγαθοὺς καὶ μνημονεύειν ἀεὶ τῶν διὰ τὴν παράβασιν τῆς ἀρετῆς αὐτοῖς κακῶν συμπεσόντων καὶ τῶν σημείων τοῦ θεοῦ καὶ τῆς Μωυσέος νομοθεσίας, εἰ σωτηρίας αὐτοῖς καὶ τῆς μετὰ τοῦ βασιλέως εὐδαιμονίας ἐστὶν ἐπιθυμία."},{"number":94,"text":"εἰ δὲ τούτων ἀμελήσουσιν, ἔλεγεν ἥξειν αὐτοῖς τε καὶ τῷ βασιλεῖ μεγάλην ἐκ θεοῦ πληγήν. καὶ Σαμουῆλος μὲν ταῦτα τοῖς Ἑβραίοις προφητεύσας ἀπέλυσεν αὐτοὺς ἐπὶ τὰ οἰκεῖα βεβαιώσας ἐκ δευτέρου τῷ Σαούλῳ τὴν βασιλείαν."}],"6":[{"number":95,"text":"Οὗτος δʼ ἐπιλέξας ἐκ τοῦ πλήθους ὡς τρισχιλίους τοὺς μὲν δισχιλίους ὥστε σωματοφυλακεῖν αὐτὸν λαβὼν αὐτὸς διέτριβεν ἐν πόλει Βεθήβῳ, Ἰωνάθῃ δὲ τῷ παιδὶ τοὺς λοιποὺς δοὺς ὥστε σωματοφυλακεῖν αὐτὸν εἰς Γεβὰλ ἔπεμψεν. ὁ δʼ ἐκπολιορκεῖ τι φρούριον τῶν Παλαιστίνων οὐ πόρρω Γεβάλων."},{"number":96,"text":"οἱ γὰρ Παλαιστῖνοι καταστρεφόμενοι τοὺς Ἰουδαίους τά τε ὅπλα αὐτοὺς ἀφῃροῦντο καὶ τοὺς ὀχυρωτάτους τῆς χώρας τόπους φρουραῖς κατελαμβάνοντο καὶ σιδηροφορεῖν χρῆσθαί τε καθάπαξ ἀπηγόρευον σιδήρῳ, καὶ διὰ ταύτην τὴν πρόρρησιν οἱ γεωργοὶ, εἴποτε δεήσειʼ αὐτοὺς ἐπισκευάσαι τι τῶν ἐργαλείων, ἢ ὕνιν ἢ δίκελλαν ἢ ἄλλο τι τῶν εἰς γεωργίαν χρησίμων, φοιτῶντες εἰς τοὺς Παλαιστίνους ταῦτα ἔπραττον."},{"number":97,"text":"ὡς δὲ ἠκούσθη τοῖς Παλαιστίνοις ἡ τῆς φρουρᾶς ἀναίρεσις ἀγανακτήσαντες καὶ δεινὴν ὕβριν τὴν καταφρόνησιν ἡγησάμενοι στρατεύουσιν ἐπὶ τοὺς Ἰουδαίους πεζῶν μὲν τριάκοντα μυριάσιν ἅρμασι δὲ τρισμυρίοις, ἵππον δὲ ἑξακισχιλίαν ἐπήγοντο·"},{"number":98,"text":"καὶ στρατοπεδευσαμένων πρὸς πόλει Μαχμὰ τοῦτο Σαοῦλος ὁ τῶν Ἰουδαίων βασιλεὺς μαθὼν εἰς Γάλγαλα καταβαίνει πόλιν καὶ διὰ πάσης κηρύσσει τῆς χώρας ἐπʼ ἐλευθερίᾳ καλῶν τὸν λαὸν ἐπὶ τὸν πόλεμον τὸν πρὸς Παλαιστίνους, τὴν δύναμιν ἐκφαυλίζων αὐτῶν καὶ διασύρων ὡς οὐκ ἀξιόλογον οὐδʼ ὥστε φοβεῖσθαι διακινδυνεύειν πρὸς αὐτούς."},{"number":99,"text":"κατανοήσαντες δὲ τὸ πλῆθος τῶν Παλαιστίνων οἱ τοῦ Σαούλου κατεπλάγησαν, καὶ οἱ μὲν εἰς τὰ σπήλαια καὶ τοὺς ὑπονόμους ἔκρυψαν αὑτοὺς, οἱ πλείους δὲ εἰς τὴν πέραν τοῦ Ἰορδάνου γῆν ἔφυγον· αὕτη δʼ ἦν Γάδου καὶ Ῥουβήλου."},{"number":100,"text":"Πέμψας δὲ Σαοῦλος πρὸς τὸν προφήτην ἐκάλει πρὸς αὑτὸν συνδιασκεψόμενον περὶ τοῦ πολέμου καὶ τῶν πραγμάτων. ὁ δὲ περιμένειν αὐτὸν ἐκέλευσεν αὐτόθι καὶ παρασκευάζειν θύματα· μετὰ γὰρ ἡμέρας ἑπτὰ πρὸς αὐτὸν ἥξειν, ὅπως θύσωσι τῇ ἑβδόμῃ τῶν ἡμερῶν, ἔπειθʼ οὕτως συμβάλωσι τοῖς πολεμίοις."},{"number":101,"text":"καὶ περιμένει μὲν ὡς ὁ προφήτης ἐπέστειλεν, οὐκέτι μέντοι γε διατηρεῖ τὴν ἐντολήν, ἀλλʼ ὡς ἑώρα βραδύνοντα μὲν τὸν προφήτην, αὑτὸν δὲ ὑπὸ τῶν στρατιωτῶν καταλειπόμενον, λαβὼν τὰ θύματα τὴν θυσίαν ἐπετέλει· ἐπεὶ δὲ τὸν Σαμουῆλον ἤκουσε προσιόντα ὑπαντησόμενος ἐξῆλθεν."},{"number":102,"text":"ὁ δʼ οὐκ ὀρθῶς αὐτὸν ἔφη πεποιηκέναι παρακούσαντα ὧν ἐπέστειλεν αὐτὸς καὶ φθάσαντα τὴν παρουσίαν, ἣν κατὰ βούλησιν γινομένην τοῦ θείου πρὸς τὰς εὐχὰς καὶ τὰς θυσίας τὰς ὑπὲρ τοῦ πλήθους προλάβοι κακῶς ἱερουργήσας καὶ προπετὴς γενόμενος."},{"number":103,"text":"ἀπολογουμένου δὲ τοῦ Σαούλου καὶ περιμεῖναι μὲν τὰς ἡμέρας ἃς ὥρισε λέγοντος, ὑπὸ δὲ ἀνάγκης καὶ ἀναχωρήσεως μὲν τῶν αὑτοῦ στρατιωτῶν διὰ φόβον, στρατοπεδείας δὲ τῶν ἐχθρῶν ἐν Μαχμᾶ καὶ ἀκοῆς τῆς ἐπʼ αὐτὸν εἰς Γάλγαλα καταβάσεως ἐπειχθῆναι πρὸς τὴν θυσίαν."},{"number":104,"text":"ὑπολαβὼν δὲ ὁ Σαμουῆλος ἀλλὰ σύγε, φησίν, εἰ δίκαιος ἦσθα καὶ μὴ παρήκουσας ἐμοῦ μηδʼ ὧν ὑπέθετό μοι περὶ τῶν παρόντων ὁ θεὸς ὠλιγώρησας ταχύτερος ἢ συνέφερε τοῖς πράγμασι γεγονὼς, σοί τʼ αὐτῷ πλεῖστον ἂν βασιλεῦσαι χρόνον ἐξεγένετο καὶ τοῖς σοῖς ἐγγόνοις."},{"number":105,"text":"καὶ Σαμουῆλος μὲν ἀχθόμενος ἐπὶ τοῖς γεγενημένοις ἀνεχώρησε παρʼ αὑτὸν, Σαοῦλος δὲ εἰς Γαβαὼν πόλιν ἔχων ἑξακοσίους μεθʼ ἑαυτοῦ μόνον ἧκε σὺν Ἰωνάθῃ τῷ παιδί. τούτων δὲ οἱ πλείους οὐκ εἶχον ὅπλα τῆς χώρας σπανιζούσης σιδήρου καὶ τῶν ὅπλα χαλκεύειν δυναμένων· οὐ γὰρ εἴων οἱ Παλαιστῖνοι ταῦτα εἶναι, καθὼς μικρὸν ἔμπροσθεν δεδηλώκαμεν."},{"number":106,"text":"διελόντες δʼ εἰς τρία μέρη τὴν στρατιὰν οἱ Παλαιστῖνοι καὶ κατὰ τοσαύτας ὁδοὺς ἐπερχόμενοι τὴν τῶν Ἑβραίων χώραν ἐπόρθουν, βλεπόντων τε Σαούλου τοῦ βασιλέως αὐτῶν καὶ τοῦ παιδὸς Ἰωνάθου ἀμῦναί τε τῇ γῇ, μεθʼ ἑξακοσίων γὰρ μόνων ἦσαν, οὐ δυναμένων."},{"number":107,"text":"καθεζόμενοι δʼ αὐτός τε καὶ ὁ παῖς αὐτοῦ καὶ ὁ ἀρχιερεὺς Ἐχίας ἀπόγονος ὢν Ἠλὶ τοῦ ἀρχιερέως ἐπὶ βουνοῦ ὑψηλοῦ καὶ τὴν γῆν λεηλατουμένην ὁρῶντες ἐν ἀγωνίᾳ δεινῇ καθεστήκεσαν. συντίθεται δὲ ὁ Σαούλου παῖς τῷ ὁπλοφόρῳ, κρύφα πορευθέντες αὐτοὶ εἰς τὴν τῶν πολεμίων παρεμβολὴν ἐκδραμεῖν καὶ ταραχὴν ἐμποιῆσαι καὶ θόρυβον αὐτοῖς ."},{"number":108,"text":"τοῦ δὲ ὁπλοφόρου προθύμως ἕπεσθαι φήσαντος ὅποι ποτʼ ἂν ἡγῆται, κἂν ἀποθανεῖν δέῃ, προσλαβὼν τὴν τοῦ νεανίσκου συνεργίαν καὶ καταβὰς ἀπὸ τοῦ βουνοῦ πρὸς τοὺς πολεμίους ἐπορεύετο. ἦν δὲ τὸ τῶν πολεμίων στρατόπεδον ἐπὶ κρημνοῦ, τρισὶν ἄκραις εἰς λεπτὸν ἀπηκονημέναις μῆκος πέτρας ἐν κύκλῳ περιστεφανούσης ὥσπερ προβόλοις τὰς ἐπιχειρήσεις ἀπομαχόμενον."},{"number":109,"text":"ἔνθεν συνέβαινεν ἠμελῆσθαι τὰς φυλακὰς τοῦ στρατοπέδου διὰ τὸ φύσει περιεῖναι τῷ χωρίῳ τὴν ἀσφάλειαν καὶ παντὶ νομίζειν ἀμήχανον εἶναι κατʼ ἐκείνας οὐκ ἀναβῆναι μόνον ἀλλὰ καὶ προσελθεῖν."},{"number":110,"text":"ὡς οὖν ἧκον εἰς τὴν παρεμβολὴν ὁ Ἰωνάθης παρεθάρσυνε τὸν ὁπλοφόρον καὶ προσβάλωμεν τοῖς πολεμίοις, ἔλεγε, κἂν μὲν ἀναβῆναι κελεύσωσι πρὸς αὑτοὺς ἡμᾶς ἰδόντες σημεῖον τοῦτο νίκης ὑπολάμβανε,"},{"number":111,"text":"ἐὰν δὲ φθέγξωνται μηδὲν ὡς οὐ καλοῦντες ἡμᾶς ὑποστρέψωμεν. προσιόντων δὲ αὐτῶν τῷ στρατοπέδῳ τῶν πολεμίων ὑποφαινούσης ἤδη τῆς ἡμέρας ἰδόντες οἱ Παλαιστῖνοι πρὸς ἀλλήλους ἔλεγον ἐκ τῶν ὑπονόμων καὶ σπηλαίων προϊέναι τοὺς Ἑβραίους, καὶ πρὸς Ἰωνάθην καὶ τὸν ὁπλοφόρον αὐτοῦ δεῦτε, ἔφασαν, ἀνέλθετε πρὸς ἡμᾶς, ἵνα ὑμᾶς τιμωρησώμεθα τῶν τετολμημένων ἀξίως."},{"number":112,"text":"ἀσπασάμενος δὲ τὴν φωνὴν ὁ τοῦ Σαούλου παῖς ὡς νίκην αὐτῷ σημαίνουσαν παραυτίκα μὲν ἀνεχώρησαν ἐξ οὗπερ ὤφθησαν τόπου τοῖς πολεμίοις, παραμειψάμενοι δὲ τοῦτον ἐπὶ τὴν πέτραν ἧκον ἔρημον οὖσαν τῶν φυλαττόντων διὰ τὴν ὀχυρότητα."},{"number":113,"text":"κἀκεῖθεν ἀνερπύσαντες μετὰ πολλῆς ταλαιπωρίας ἐβιάσαντο τὴν τοῦ χωρίου φύσιν ἀνελθεῖν ἐπὶ τοὺς πολεμίους, ἐπιπεσόντες δʼ αὐτοῖς κοιμωμένοις ἀποκτείνουσι μὲν ὡς εἴκοσι, ταραχῆς δὲ καὶ ἐκπλήξεως αὐτοὺς ἐγέμισαν, ὡς τινὰς μὲν φυγεῖν τὰς πανοπλίας ἀπορρίψαντας,"},{"number":114,"text":"οἱ δὲ πολλοὶ μὴ γνωρίζοντες ἑαυτοὺς διὰ τὸ ἐκ πολλῶν ἐθνῶν εἶναι πολεμίους ὑπονοοῦντες ἀλλήλους, καὶ γὰρ εἴκαζον ἀναβῆναι πρὸς αὐτοὺς τῶν Ἑβραίων οὐ δύο μόνους, εἰς μάχην ἐτράποντο. καὶ οἱ μὲν αὐτῶν ἀπέθνησκον κτεινόμενοι, τινὲς δὲ φεύγοντες κατὰ τῶν πετρῶν ὠθούμενοι κατεκρημνίζοντο."},{"number":115,"text":"Τῶν δὲ τοῦ Σαούλου κατασκόπων τεταράχθαι τὸ στρατόπεδον τῶν Παλαιστίνων φρασάντων τῷ βασιλεῖ Σαοῦλος ἠρώτα, μή τις εἴη τῶν αὑτοῦ κεχωρισμένος. ἀκούσας δὲ τὸν υἱὸν καὶ σὺν αὐτῷ τὸν ὁπλοφόρον ἀπεῖναι κελεύει τὸν ἀρχιερέα λαβόντα τὴν ἀρχιερατικὴν στολὴν προφητεύειν αὐτῷ περὶ τῶν μελλόντων. τοῦ δὲ νίκην ἔσεσθαι καὶ κράτος κατὰ τῶν πολεμίων φράσαντος ἐπεξέρχεται τοῖς Παλαιστίνοις καὶ τεταραγμένοις προσβάλλει καὶ φονεύουσιν ἀλλήλους."},{"number":116,"text":"προσρέουσι δὲ αὐτῷ καὶ οἱ πρότερον εἴς τε τοὺς ὑπονόμους καὶ εἰς τὰ σπήλαια συμφυγόντες ἀκούσαντες ὅτι νικᾷ Σαοῦλος· γενομένων δὲ ὡς μυρίων ἤδη τῶν Ἑβραίων διώκει τοὺς πολεμίους κατὰ πᾶσαν ἐσκορπισμένους τὴν χώραν. εἴτε δὲ ὑπὸ τῆς ἐπὶ τῇ νίκῃ χαρᾶς οὕτω παραλόγως γενομένῃ, συμβαίνει γὰρ μὴ κρατεῖν τοῦ λογισμοῦ τοὺς οὕτως εὐτυχήσαντας, εἴθʼ ὑπὸ ἀγνοίας εἰς δεινὸν προπίπτει καὶ πολλὴν ἔχον κατάμεμψιν ἔργον·"},{"number":117,"text":"βουλόμενος γὰρ αὑτῷ τε τιμωρῆσαι καὶ δίκην ἀπολαβεῖν παρὰ τῶν Παλαιστίνων ἐπαρᾶται τοῖς Ἑβραίοις, ἵνʼ εἴ τις ἀποσχόμενος τοῦ φονεύειν τοὺς ἐχθροὺς φάγοι καὶ μὴ μέχρι νὺξ ἐπελθοῦσα τῆς ἀναιρέσεως καὶ τῆς διώξεως αὐτοὺς παύσει τῶν πολεμίων, οὗτος ἐπάρατος ᾖ."},{"number":118,"text":"τοῦ δὲ Σαούλου τοῦτο φήσαντος, ἐπεὶ κατά τινα δρυμὸν ἐγένοντο βαθὺν καὶ μελισσῶν γέμοντα τῆς Ἐφράμου κληρουχίας, ὁ τοῦ Σαούλου παῖς οὐκ ἐπακηκοὼς τῆς τοῦ πατρὸς ἀρᾶς οὐδὲ τῆς ἐπʼ αὐτῇ τοῦ πλήθους ὁμολογίας ἀποθλίψας τι κηρίον τοῦ μέλιτος ἤσθιε."},{"number":119,"text":"μεταξὺ δὲ γνοὺς, ὅτι μετὰ δεινῆς ἀρᾶς ὁ πατὴρ ἀπεῖπε μὴ γεύσασθαί τινα πρὸ ἡλίου δυσμῶν, ἐσθίων μὲν ἐπαύσατο, ἔφη δὲ οὐκ ὀρθῶς κωλῦσαι τὸν πατέρα· μετὰ μείζονος γὰρ ἰσχύος ἂν καὶ προθυμίας διώκοντας, εἰ τροφῆς μετελάμβανον, πολλῷ πλείονας τῶν ἐχθρῶν καὶ λαβεῖν καὶ φονεῦσαι."},{"number":120,"text":"Πολλὰς γοῦν κατακόψαντες μυριάδας τῶν Παλαιστίνων δείλης ὀψίας ἐπὶ διαρπαγὴν τοῦ στρατοπέδου τῶν Παλαιστίνων τρέπονται, καὶ λείαν πολλὴν καὶ βοσκήματα λαβόντες κατασφάζουσι καὶ ταῦτʼ ἔναιμα κατήσθιον. ἀπαγγέλλεται δὲ τῷ βασιλεῖ ὑπὸ τῶν γραμματέων, ὅτι τὸ πλῆθος εἰς τὸν θεὸν ἐξαμαρτάνει θῦσαν καὶ πρὶν ἢ τὸ αἷμα καλῶς ἀποπλῦναι καὶ τὰς σάρκας ποιῆσαι καθαρὰς ἐσθίον."},{"number":121,"text":"καὶ Σαοῦλος κελεύει κυλισθῆναι λίθον μέγαν εἰς μέσον καὶ κηρύσσει θύειν ἐπʼ αὐτοῦ τὸν ὄχλον τὰ ἱερεῖα καὶ τὰ κρέα μὴ σὺν τῷ αἵματι δαίνυσθαι· τοῦτο γὰρ οὐκ εἶναι τῷ θεῷ κεχαρισμένον. τοῦτο δὲ πάντων κατὰ τὴν πρόσταξιν τοῦ βασιλέως ποιησάντων ἵστησιν ἐκεῖ βωμὸν ὁ Σαοῦλος καὶ ὡλοκαύτωσεν ἐπʼ αὐτοῦ ἐκεῖ τῷ θεῷ. τοῦτον πρῶτον βωμὸν κατεσκεύασεν."},{"number":122,"text":"Ἄγειν δʼ εὐθὺς τὴν στρατιὰν ἐπὶ τὴν παρεμβολὴν τῶν πολεμίων ἐπὶ τὴν διαρπαγὴν τῶν ἐν αὐτῇ βουλόμενος πρὶν ἡμέρας καὶ τῶν στρατιωτῶν οὐκ ὀκνούντων ἕπεσθαι, πολλὴν δʼ εἰς ἃ προστάττει προθυμίαν ἐνδεικνυμένων, καλέσας ὁ βασιλεὺς Ἀχίτωβον τὸν ἀρχιερέα κελεύει αὐτὸν γνῶναι, εἰ δίδωσιν αὐτοῖς ὁ θεὸς καὶ συγχωρεῖ βαδίσασιν ἐπὶ τὸ στρατόπεδον τῶν ἐχθρῶν διαφθεῖραι τοὺς ἐν αὐτῷ τυγχάνοντας."},{"number":123,"text":"εἰπόντος δὲ τοῦ ἱερέως μὴ ἀποκρίνεσθαι τὸν θεόν ἀλλʼ οὐ δίχα αἰτίας, εἶπεν ὁ Σαοῦλος, πυνθανομένοις ἡμῖν φωνὴν οὐ δίδωσιν ὁ θεὸς, ὃς πρότερον αὐτὸς προεμήνυσε πάντα καὶ μηδʼ ἐπερωτῶσιν ἔφθασε λέγων, ἀλλʼ ἔστι τι λανθάνον ἐξ ἡμῶν ἁμάρτημα πρὸς αὐτὸν αἴτιον τῆς σιωπῆς."},{"number":124,"text":"καὶ ὄμνυμί γε τοῦτον αὐτὸν, ἦ μὴν κἂν ὁ παῖς ὁ ἐμὸς Ἰωνάθης ᾖ τὸ ἁμάρτημα τοῦτο ἐργασάμενος ἀποκτείνειν αὐτὸν καὶ τὸν θεὸν οὕτως ἱλάσασθαι, ὡς ἂν εἰ καὶ παρʼ ἀλλοτρίου καὶ μηδὲν ἐμοὶ προσήκοντος τὴν ὑπὲρ αὐτοῦ δίκην ἀπελάμβανον."},{"number":125,"text":"τοῦ δὲ πλήθους τοῦτο ποιεῖν ἐπιβοήσαντος παραχρῆμα πάντας ἵστησιν εἰς ἕνα τόπον, ἵσταται δὲ καὶ αὐτὸς σὺν τῷ παιδὶ κατʼ ἄλλο μέρος καὶ κλήρῳ τὸν ἡμαρτηκότα μαθεῖν ἐπεζήτει· καὶ λαγχάνει δοκεῖν οὗτος εἶναι Ἰωνάθης."},{"number":126,"text":"ἐπερωτώμενος δὲ ὑπὸ τοῦ πατρὸς τί πεπλημμέληκε καὶ τί παρὰ τὸν βίον οὐκ ὀρθῶς οὐδὲ ὁσίως αὑτῷ διαπραξαμένῳ συνέγνωκε πάτερ, εἶπεν, ἄλλο μὲν οὐδὲν, ὅτι δὲ χθὲς ἀγνοῶν τὴν ἀρὰν αὐτοῦ καὶ τὸν ὅρκον μεταξὺ διώκων τοὺς πολεμίους ἐγεύσατο κηρίων. Σαοῦλος δʼ ἀποκτείνειν αὐτὸν ὄμνυσι καὶ τῆς γενέσεως καὶ τῆς φύσεως τῶν φίλτρων ἐτίμησε τὸν ὅρκον."},{"number":127,"text":"ὁ δʼ οὐ καταπλήττεται τὴν ἀπειλὴν τοῦ θανάτου, παραστησάμενος δʼ εὐγενῶς καὶ μεγαλοφρόνως οὐδʼ ἐγώ σε, φησίν, ἱκετεύσω φείσασθαί μου, πάτερ, ἥδιστος δέ μοι ὁ θάνατος ὑπέρ τε τῆς σῆς εὐσεβείας γινόμενος καὶ ἐπὶ νίκῃ λαμπρᾷ·"},{"number":128,"text":"μέγιστον γὰρ παραμύθιον τὸ καταλιπεῖν Ἑβραίους Παλαιστίνων κεκρατηκότας. ἐπὶ τούτοις ὁ λαὸς πᾶς ἤλγησε καὶ συνέπαθεν ὤμοσέ τε μὴ περιόψεσθαι τὸν αἴτιον τῆς νίκης Ἰωνάθην ἀποθανόντα. καὶ τὸν μὲν οὕτως ἐξαρπάζουσι τῆς τοῦ πατρὸς ἀρᾶς, αὐτοὶ δὲ εὐχὰς ὑπὲρ τοῦ νεανίσκου ποιοῦνται τῷ θεῷ ὥστε αὐτὸν ἀπολῦσαι τοῦ ἁμαρτήματος."},{"number":129,"text":"Καὶ ὁ Σαοῦλος εἰς τὴν ἑαυτοῦ πόλιν ὑπέστρεψε διαφθείρας ὡσεὶ μυριάδας ἓξ τῶν πολεμίων. βασιλεύει δὲ εὐτυχῶς, καὶ τὰ πλησιόχωρα τῶν ἐθνῶν πολεμήσας χειροῦται τό τε Ἀμμανιτῶν καὶ Μωαβιτῶν Παλαιστίνους Ἰδουμαίους Ἀμαληκίτας τε καὶ τὸν βασιλέα τῆς Σωβᾶς. ἦσαν δὲ παῖδες αὐτῷ τρεῖς μὲν ἄρσενες Ἰωνάθης καὶ Ἰησοῦς καὶ Μέλχισος, θυγατέρες δὲ Μερόβη καὶ Μιχαάλ."},{"number":130,"text":"στρατηγὸν δὲ εἶχε τὸν τοῦ θείου παῖδα Ἀβήναρον· Νῆρος δʼ ἐκεῖνος ἐκαλεῖτο, Νῆρος δὲ καὶ Κεὶς ὁ Σαούλου πατὴρ ἀδελφοὶ ἦσαν, υἱοὶ δʼ Ἀβελίου. ἦν δὲ καὶ πλῆθος ἁρμάτων Σαούλῳ καὶ ἱππέων, οἷς δὲ πολεμήσειε νικήσας ἀπηλλάσσετο, καὶ τοὺς Ἑβραίους εἰς εὐπραγίας καὶ μέγεθος εὐδαιμονίας προηγάγετο καὶ τῶν ἄλλων ἀπέδειξεν ἐθνῶν δυνατωτέρους, καὶ τῶν νέων τοὺς δὴ καὶ μεγέθει καὶ κάλλει διαφέροντας φύλακας τοῦ σώματος ἐποιεῖτο."}],"7":[{"number":131,"text":"Σαμουῆλος δὲ παραγενόμενος πρὸς τὸν Σαοῦλον πεμφθῆναι πρὸς αὐτὸν ἔφασκεν ὑπὸ τοῦ θεοῦ, ὅπως αὐτὸν ὑπομνήσῃ, ὅτι βασιλέα προκρίνας αὐτὸν ἁπάντων ὁ θεὸς ἀπέδειξε, καὶ διὰ τοῦτο πείθεσθαι καὶ κατήκοον αὐτῷ γενέσθαι ὡς αὐτοῦ μὲν ἔχοντος τὴν τῶν ἐθνῶν ἡγεμονίαν, τοῦ δὲ θεοῦ καὶ τὴν κατʼ ἐκείνου καὶ τῶν ὅλων πραγμάτων."},{"number":132,"text":"λέγειν τοίνυν ἔφασκε τὸν θεὸν· ἐπεὶ πολλὰ κακὰ τοὺς Ἑβραίους Ἀμαληκῖται διέθηκαν κατὰ τὴν ἔρημον, ὅτε ἐξελθόντες ἀπʼ Αἰγύπτου εἰς τὴν νῦν ὑπάρχουσαν αὐτοῖς ἐστέλλοντο χώραν, κελεύω πολέμῳ τιμωρησάμενον τοὺς Ἀμαληκίτας καὶ κρατήσαντα μηδένʼ αὐτῶν ὑπολιπεῖν,"},{"number":133,"text":"ἀλλὰ πάσης διεξελθεῖν ἡλικίας ἀρξαμένους ἀπὸ γυναικῶν κτείνειν καὶ νηπίων καὶ τοιαύτην ὑπὲρ ὧν τοὺς προγόνους ὑμῶν εἰργάσαντο τιμωρίαν ἀπολαβεῖν, φείσασθαι δὲ μήτε ὑποζυγίων μήτε τῶν ἄλλων βοσκημάτων εἰς ὠφέλειαν καὶ κτῆσιν ἰδίαν, ἅπαντα δʼ ἀναθεῖναι τῷ θεῷ καὶ τὸ Ἀμαλήκου ὄνομα ταῖς Μωυσέος κατακολουθήσαντʼ ἐντολαῖς ἐξαλεῖψαι."},{"number":134,"text":"Ὁμολογεῖ δὲ ποιήσειν Σαοῦλος τὰ προστασσόμενα, τὴν δὲ πειθαρχίαν τὴν πρὸς τὸν θεὸν οὐκ ἐν τῷ ποιήσασθαι τὴν πρὸς τοὺς Ἀμαληκίτας στρατείαν λογιζόμενος εἶναι μόνον, ἀλλὰ καὶ τὴν ἑτοιμότητα καὶ τὸ τάχος ἀναβολῆς οὐ προσούσης ἔτι μᾶλλον ἐμφανίζει, ἀθροίζει τε πᾶσαν τὴν δύναμιν καὶ ταύτην ἐξαριθμήσας ἐν Γαλγάλοις εὑρίσκει τῶν Ἰσραηλιτῶν ἔξω τῆς Ἰούδα φυλῆς περὶ τεσσαράκοντα μυριάδας· ἥδε γὰρ ἡ φυλὴ καθʼ αὑτήν ἐστι στρατιῶται τρισμύριοι."},{"number":135,"text":"Σαοῦλος δʼ ἐμβαλὼν εἰς τὴν τῶν Ἀμαληκιτῶν χώραν ἐνέδρας πολλὰς καὶ λόχους περὶ τὸν χειμάρρουν τίθησιν, ὡς μὴ μόνον ἐκ τοῦ φανεροῦ μαχομένους αὐτοὺς κακῶς ποιεῖν, ἀλλὰ καὶ μὴ προσδοκῶσι κατὰ τὰς ὁδοὺς ἐπιπίπτειν καὶ κυκλουμένους ἀναιρεῖν· καὶ δὴ συμβαλὼν αὐτοῖς εἰς μάχην τρέπεται τοὺς πολεμίους καὶ διαφθείρει πάντας φεύγουσιν ἐπακολουθῶν."},{"number":136,"text":"ὡς δʼ ἐκεῖνο τὸ ἔργον αὐτῷ κατὰ τὴν τοῦ θεοῦ προφητείαν ἐχώρησε, ταῖς πόλεσι τῶν Ἀμαληκιτῶν προσέβαλε καὶ τὰς μὲν μηχανήμασι, τὰς δὲ ὀρύγμασιν ὑπονόμοις καὶ τείχεσιν ἔξωθεν ἀντῳκοδομημένοις, τὰς δὲ λιμῷ καὶ δίψει, τὰς δὲ ἄλλοις τρόποις ἐκπολιορκήσας καὶ λαβὼν κατὰ κράτος ἐπὶ σφαγὴν γυναικῶν καὶ νηπίων ἐχώρησεν, οὐδὲν ὠμὸν οὐδʼ ἀνθρωπίνης σκληρότερον διαπράσσεσθαι φύσεως ἡγούμενος, πρῶτον μὲν πολεμίους ταῦτα δρῶν, ἔπειτα προστάγματι θεοῦ, ᾧ τὸ μὴ πείθεσθαι κίνδυνον ἔφερε."},{"number":137,"text":"λαμβάνει δὲ καὶ τὸν βασιλέα τῶν ἐχθρῶν Ἄγαγον αἰχμάλωτον, οὗ θαυμάσας τὸ κάλλος καὶ τὸ μέγεθος τοῦ σώματος σωτηρίας ἄξιον ἔκρινεν οὐκέτι τοῦτο ποιῶν κατὰ βούλησιν τοῦ θεοῦ, πάθει δὲ νικώμενος ἰδίῳ καὶ χαριζόμενος ἀκαίρως περὶ ὧν οὐκ εἶχεν ἀκίνδυνον ἐξουσίαν οἴκτῳ."},{"number":138,"text":"ὁ μὲν γὰρ θεὸς οὕτως ἐμίσησε τὸ τῶν Ἀμαληκιτῶν ἔθνος, ὡς μηδὲ νηπίων φείσασθαι κελεῦσαι πρὸς ἃ μᾶλλον ἔλεος γίνεσθαι πέφυκε, Σαοῦλος δὲ αὐτῶν τὸν βασιλέα καὶ τὸν ἡγεμόνα τῶν εἰς Ἑβραίους κακῶν ἔσωσε τῆς μνήμης ὧν ἐπέστειλεν ὁ θεὸς τὸ τοῦ πολεμίου κάλλος ἐπίπροσθεν ποιησάμενος."},{"number":139,"text":"συνεξήμαρτε δʼ αὐτῷ καὶ τὸ πλῆθος· καὶ γὰρ ἐκεῖνοι τῶν ὑποζυγίων καὶ τῶν βοσκημάτων ἐφείσαντο καὶ διήρπασαν μὴ τηρεῖν αὐτὰ τοῦ θεοῦ κελεύσαντος τά τε ἄλλα χρήματα καὶ τὸν πλοῦτον ἐξεφόρησαν, εἰ δέ τι μὴ σπουδῆς ἦν ἄξιον ὥστε κεκτῆσθαι διέφθειραν."},{"number":140,"text":"Νικήσας δὲ Σαοῦλος ἅπαντας τοὺς ἀπὸ Πηλουσίου τῆς Αἰγύπτου καθήκοντας ἕως τῆς Ἐρυθρᾶς θαλάσσης διέφθειρε πολεμίους παραλιπὼν τὸ τῶν Σικιμιτῶν ἔθνος· οὗτοι γὰρ ἐν τῇ Μαδιηνῇ χώρᾳ μέσοι κατῴκηνται. πρὸ δὲ τῆς μάχης πέμψας παρήγγειλεν αὐτοῖς ἀναχωρεῖν, μὴ τοῖς Ἀμαληκίταις κοινωνήσωσι συμφορᾶς· συγγενεῖς γὰρ αὐτοὺς ὄντας Ῥαγουήλου τοῦ Μωυσέος πενθεροῦ σώζειν αἰτίαν ἔχειν."},{"number":141,"text":"Καὶ Σαοῦλος μὲν ὡς μηδενὸς παρακούσας ὧν ὁ προφήτης ἐπέστειλε μέλλοντι τὸν πρὸς Ἀμαληκίτας ἐκφέρειν πόλεμον, ἀλλʼ ὡς ἐπὶ πᾶσιν ἐκείνοις ἀκριβῶς πεφυλαγμένοις νενικηκὼς τοὺς πολεμίους οἴκαδε πρὸς αὑτὸν ὑπέστρεψε χαίρων ἐπὶ τοῖς κατωρθωμένοις."},{"number":142,"text":"ὁ δὲ θεὸς ἄχθεται τῇ τε τοῦ βασιλέως τῶν Ἀμαληκιτῶν σωτηρίᾳ καὶ τῇ τῶν βοσκημάτων διαρπαγῇ τοῦ πλήθους, ὅτι μὴ συγχωρήσαντος αὐτοῦ ταῦτʼ ἐπράχθη· δεινὸν γὰρ ἡγεῖτο νικᾶν μὲν καὶ περιγίνεσθαι τῶν ἐχθρῶν ἐκείνου τὴν ἰσχὺν διδόντος αὐτοῖς, καταφρονεῖσθαι δὲ καὶ παρακούεσθαι μηδὲ ὡς ἄνθρωπον βασιλέα."},{"number":143,"text":"μετανοεῖν οὖν ἔλεγε πρὸς τὸν προφήτην Σαμουῆλον ἐπὶ τῷ χειροτονῆσαι βασιλέα τὸν Σαοῦλον μηδὲν ὧν αὐτὸς κελεύει πράττοντα, τῇ δʼ οἰκείᾳ βουλήσει χρώμενον. σφόδρα ταῦτʼ ἀκούσας ὁ Σαμουῆλος συνεχύθη καὶ διʼ ὅλης τῆς νυκτὸς παρακαλεῖν ἤρξατο τὸν θεὸν καταλλάττεσθαι τῷ Σαούλῳ καὶ μὴ χαλεπαίνειν."},{"number":144,"text":"ὁ δὲ τὴν συγγνώμην οὐκ ἐπένευσεν εἰς τὸν Σαοῦλον αἰτουμένῳ τῷ προφήτῃ λογισάμενος οὐκ εἶναι δίκαιον ἁμαρτήματα χαρίζεσθαι παραιτήσει· οὐ γὰρ ἐξ ἄλλου τινὸς φύεσθαι μᾶλλον ἢ τοῦ μαλακίζεσθαι τοὺς ἀδικουμένους· θηρωμένους γὰρ δόξαν ἐπιεικείας καὶ χρηστότητος λανθάνειν αὐτοὺς ταῦτα γεννῶντας."},{"number":145,"text":"ὡς οὖν ἀπεῖπεν ὁ θεὸς τῇ τοῦ προφήτου δεήσει καὶ δῆλος ἦν μεταμελόμενος, ἅμʼ ἡμέρᾳ Σαμουῆλος εἰς Γάλγαλα παραγίνεται πρὸς Σαοῦλον· θεασάμενος δʼ αὐτὸν ὁ βασιλεὺς προστρέχει καὶ κατασπασάμενος τῷ θεῷ, φησίν, εὐχαριστῶ δόντι μοι τὴν νίκην, ἅπαντα μέντοι γε τὰ κελευσθέντα ὑπʼ αὐτοῦ πέπρακται."},{"number":146,"text":"Σαμουῆλος δὲ πρὸς τοῦθʼ ὑπολαβὼν πόθεν οὖν ἀκούω θρεμμάτων, εἶπε, καὶ ὑποζυγίων βοῆς ἐν τῷ στρατοπέδῳ; ὁ δὲ τὸν λαὸν ταῦτʼ εἰς θυσίας ἀπεκρίνατο τετηρηκέναι· τὸ μέντοι γε τῶν Ἀμαληκιτῶν γένος πᾶν ἐξηφανίσθαι κατὰ τὴν ἐντολὴν καὶ περιλείπεσθαι ἄλλον μηδένα, πρὸς δʼ αὐτὸν ἀγαγεῖν μόνον τηρήσαντα αὐτῶν τὸν βασιλέα, περὶ οὗ τί δεῖ ποιεῖν βουλεύσεσθαι πρὸς ἀλλήλους ἔφασκεν."},{"number":147,"text":"ὁ δὲ προφήτης οὐχὶ θυσίαις ἔλεγεν ἥδεσθαι τὸ θεῖον, ἀλλὰ τοῖς ἀγαθοῖς καὶ δικαίοις. οὗτοι δέ εἰσιν οἱ τῇ βουλήσει καὶ ταῖς ἐντολαῖς αὐτοῦ κατακολουθοῦντες καὶ μηδὲν ἄλλο πραχθήσεσθαι καλῶς ὑφʼ ἑαυτῶν νομίζοντες ἢ ὅτι ἂν ποιήσωσι τοῦ θεοῦ κεκελευκότος· καταφρονεῖσθαι γὰρ οὐχ ὅταν αὐτῷ μὴ θύῃ τις, ἀλλʼ ὅταν ἀπειθεῖν δοκῇ."},{"number":148,"text":"παρὰ δὲ τῶν οὐχ ὑποτασσομένων οὐδʼ ἀληθῆ καὶ μόνην τῷ θεῷ κεχαρισμένην θρησκευόντων θρησκείαν, οὔτʼ ἂν πολλὰ καὶ πιμελῆ καταθύσωσιν ἱερεῖα, οὔτʼ ἂν κόσμον ἀναθημάτων ἐξ ἀργύρου καὶ χρυσοῦ πεποιημένων προσφέρωσι, δέχεται ταῦτʼ εὐμενῶς, ἀλλʼ ἀποστρέφεται καὶ δείγματα τῆς πονηρίας οὐκ εὐσέβειαν ἡγεῖται."},{"number":149,"text":"τοῖς δʼ ἓν καὶ μόνον τοῦθʼ ὅτι περ ἂν φθέγξηται καὶ κελεύσῃ ὁ θεὸς διὰ μνήμης ἔχουσι καὶ τεθνάναι μᾶλλον ἢ παραβῆναί τι τούτων αἱρουμένοις ἐπιτέρπεται, καὶ οὔτε θυσίαν ἐπιζητεῖ παρʼ αὐτῶν καὶ παρὰ θυόντων δὲ, κἂν ᾖ λιτά, τῆς πενίας ἥδιον τὴν τιμὴν ἢ παρὰ τῶν πλουσιωτάτων δεξιοῦται."},{"number":150,"text":"σὺ τοίνυν ἴσθι σαυτὸν διʼ ὀργῆς ὄντα τῷ θεῷ· κατεφρόνησας γὰρ καὶ κατημέλησας ὧν ἐπέστειλε. πῶς οὖν οἴει τὴν θυσίαν ἂν αὐτὸν προσβλέπειν ἐξ ὧν κατέκρινεν ἀπολέσθαι γινομένην; πλὴν εἰ μὴ νομίζεις ὅμοιον ὄλεθρον τὸ θύεσθαι ταῦτα τῷ θεῷ. προσδόκα τοίνυν τὴν βασιλείαν ἀφαιρεθησόμενος καὶ τὴν ἐξουσίαν, ἀφʼ ἧς ὁρμώμενος τοῦ παρασχόντος σοι θεοῦ ταύτην ἠμέλησας."},{"number":151,"text":"Σαοῦλος δὲ ἀδικεῖν ὡμολόγει καὶ τὴν ἁμαρτίαν οὐκ ἠρνεῖτο· παραβῆναι γὰρ τὰς ἐντολὰς τοῦ προφήτου· κατὰ μέντοι γε δέος καὶ τὸν ἀπὸ τῶν στρατιωτῶν φόβον μὴ κωλῦσαι διαρπάζοντας αὐτοὺς τὴν λείαν μηδʼ ἐπισχεῖν. ἀλλὰ συγγίνωσκε καὶ πρᾷος ἴσθι· φυλάξεσθαι γὰρ εἰς τοὐπιὸν ἁμαρτεῖν, παρεκάλει δὲ τὸν προφήτην ὑποστρέψαντα θυσίας χαριστηρίους ἐπιτελέσαι τῷ θεῷ· ὁ δὲ, οὐ γὰρ ἑώρα τὸν θεὸν διαλλαττόμενον, ἀπῄει πρὸς ἑαυτόν."},{"number":152,"text":"Σαοῦλος δὲ κατασχεῖν βουλόμενος τὸν Σαμουῆλον ἐλλαμβάνεται τῆς διπλοΐδος καὶ βιαίας τῆς ὁλκῆς διὰ τὸ μεθʼ ὁρμῆς ἀπιέναι τὸν Σαμουῆλον γενομένης διασχίζει τὸ ἱμάτιον."},{"number":153,"text":"τοῦ δὲ προφήτου τὴν βασιλείαν οὕτως αὐτοῦ διασχισθῆναι φήσαντος καὶ λήψεσθαι ταύτην ἀγαθὸν καὶ δίκαιον, ἐμμένειν γὰρ τὸν θεὸν τοῖς περὶ αὐτοῦ κεκριμένοις ὡς τοῦ μεταβάλλεσθαι καὶ στρέφειν τὴν γνώμην ἀνθρωπίνου πάθους ὄντος οὐχὶ θείας ἰσχύος,"},{"number":154,"text":"ὁ Σαοῦλος ἀσεβῆσαι μὲν ἔλεγεν, ἀγένητα δὲ ποιῆσαι τὰ πεπραγμένα μὴ δύνασθαι· τιμῆσαί γε μὴν αὐτὸν παρεκάλει τοῦ πλήθους ὁρῶντος σὺν αὐτῷ παραγενόμενον τὸν θεὸν προσκυνῆσαι. δίδωσι δὲ τοῦτο Σαμουῆλος αὐτῷ καὶ συνελθὼν προσκυνεῖ τῷ θεῷ."},{"number":155,"text":"ἄγεται δὲ καὶ ὁ τῶν Ἀμαληκιτῶν βασιλεὺς Ἄγαγος πρὸς αὐτόν· καὶ πυνθανομένου, πῶς εἴη πικρὸς ὁ θάνατος, εἶπεν ὡς σὺ πολλὰς μητέρας Ἑβραίων ἐπὶ τέκνοις ὀδύρεσθαι καὶ πένθος ἄγειν ἐποίησας, οὕτως ὀδυνήσεις ἐπὶ σαυτῷ διαφθαρέντι τὴν μητέρα. καὶ κελεύει παραχρῆμα αὐτὸν ἐν Γαλγάλοις ἀποθανεῖν. καὶ αὐτὸς δὲ εἰς Ἅρμαθον πόλιν ἀπαλλάσσεται."}],"8":[{"number":156,"text":"Σαοῦλος δὲ ὁ βασιλεὺς αἰσθόμενος ὧν πειραθείη κακῶν ἐχθρὸν αὑτῷ τὸν θεὸν κατασκευάσας, εἰς τὸ βασίλειον ἀναβαίνει Γαβᾶ, σημαίνει βουνὸν ἑρμηνευόμενον τὸ ὄνομα, καὶ μετʼ ἐκείνην οὐκέτι τὴν ἡμέραν εἰς ὄψιν ἔρχεται τῷ προφήτῃ."},{"number":157,"text":"Σαμουήλῳ δὲ λυπουμένῳ περὶ αὐτοῦ παύσασθαι μὲν τῆς φροντίδος ἐκέλευσεν ὁ θεός, λαβόντι δὲ τὸ ἅγιον ἔλαιον εἰς Βηθλέμην ἀπελθεῖν πόλιν πρὸς Ἰεσσαῖον παῖδα Ὠβήδου καὶ χρῖσαι τῶν υἱῶν αὐτοῦ ὃν ἂν αὐτὸς ἐπιδείξῃ βασιλέα γενησόμενον. ὁ δὲ εὐλαβεῖσθαι φήσας, μὴ τοῦτο μαθὼν Σαοῦλος ἀνέλῃ λοχήσας αὐτὸν ἢ καὶ φανερῶς, ὑποθεμένου τοῦ θεοῦ καὶ δόντος ἀσφαλείας ὁδὸν ἧκεν εἰς τὴν προειρημένην πόλιν."},{"number":158,"text":"καὶ πάντες αὐτὸν ἠσπάζοντό τε καὶ τὴν αἰτίαν τῆς ἀφίξεως ἀνηρώτων, ἔλεγε δὲ ἥκειν ἵνα θύσῃ τῷ θεῷ. ποιήσας οὖν τὴν θυσίαν καλεῖ τὸν Ἰεσσαῖον μετὰ τῶν τέκνων ἐπὶ τὰ ἱερὰ καὶ θεασάμενος αὐτοῦ τὸν πρεσβύτατον υἱὸν εὐμεγέθη καὶ καλὸν εἴκασεν ἐκ τῆς εὐμορφίας τοῦτον εἶναι τὸν μέλλοντα βασιλεύειν."},{"number":159,"text":"διαμαρτάνει δὲ τῆς τοῦ θεοῦ προνοίας· ἐπερωτήσαντι γὰρ αὐτὸν, εἰ χρίσει τῷ ἐλαίῳ τὸν νεανίσκον, ὃν αὐτός τε θαυμάζει καὶ τῆς βασιλείας ἄξιον ἔκρινεν, οὐ τὰ αὐτὰ βλέπειν ἀνθρώπους εἶπε καὶ θεόν·"},{"number":160,"text":"ἀλλὰ σὺ μὲν εἰς τὸ κάλλος ἀπιδὼν τοῦ νεανίσκου καὶ δὴ τοῦτον ἡγῇ ἄξιον τοῦ βασιλεύειν εἶναι, ἐγὼ δʼ οὐ σωμάτων εὐμορφίας ἔπαθλον ποιοῦμαι τὴν βασιλείαν ἀλλὰ ψυχῶν ἀρετῆς καὶ ζητῶ ὅστις ταύτης ἐστὶ τελέως εὐπρεπὴς, εὐσεβείᾳ καὶ δικαιοσύνῃ καὶ ἀνδρείᾳ καὶ πειθοῖ ἐξ ὧν τὸ τῆς ψυχῆς συνίσταται κάλλος κατακεκοσμημένος."},{"number":161,"text":"ταῦτα φράσαντος τοῦ θεοῦ πάντας ἐκέλευσεν αὐτῷ τὸν Ἰεσσαῖον τοὺς υἱοὺς ἐπιδεῖξαι Σαμουῆλος· ὁ δὲ πέντε ἄλλους ἐποίησεν ἐλθεῖν, ὧν ὁ μὲν πρεσβύτερος Ταλίαβος, ὁ δεύτερος Ἀμινάδαβος, Σάμαλος ὁ τρίτος, ὁ τέταρτος Ναθαναῆλος, καὶ Ῥάηλος ὁ πέμπτος ἐκαλεῖτο, ὁ δὲ ἕκτος Ἄσαμος."},{"number":162,"text":"ἰδὼν δὲ καὶ τούτους ὁ προφήτης μηδὲν χείρους τοῦ πρεσβυτέρου ταῖς μορφαῖς ἐπηρώτησε τὸν θεὸν, τίνα τούτων αἱρεῖται βασιλέα. εἰπόντος δʼ οὐδένα πυνθάνεται τοῦ Ἰεσσαίου, μὴ πρὸς τούτοις αὐτῷ καὶ ἄλλοι παῖδές εἰσι."},{"number":163,"text":"φήσαντος δὲ εἶναι Δαβίδην τοὔνομα, ποιμαίνειν δὲ καὶ τῆς τῶν βοσκημάτων φυλακῆς ἐπιμελεῖσθαι κελεύει καλεῖν αὐτὸν ἐν τάχει· κατακλιθῆναι γὰρ εἰς εὐωχίαν οὐκ εἶναι δυνατὸν αὐτοῖς ἐκείνου μὴ παρόντος."},{"number":164,"text":"ὡς δʼ ἧκεν ὁ Δαβίδης μεταπεμφθεὶς ὑπὸ τοῦ πατρὸς, παῖς ξανθὸς μὲν τὴν χρόαν γοργὸς δὲ τὰς ὄψεις καὶ καλὸς ἄλλως οὗτός ἐστιν, εἰπὼν ἡσυχῇ πρὸς αὑτὸν Σαμουῆλος, ὁ βασιλεύειν ἀρέσας τῷ θεῷ κατακλίνεται μὲν αὐτός, κατακλίνει δʼ ὑφʼ αὑτὸν τὸν νεανίσκον καὶ τὸν Ἰεσσαῖον μετὰ καὶ τῶν παίδων."},{"number":165,"text":"ἔπειτα λαβὼν ὁρῶντος τοῦ Δαβίδου τὸ ἔλαιον ἀλείφει τʼ αὐτὸν καὶ πρὸς τὸ οὖς ἠρέμα λαλεῖ καὶ σημαίνει τοῦθʼ, ὅτι βασιλεύειν αὐτὸν ὁ θεὸς ᾕρηται, παρῄνει δʼ εἶναι δίκαιον καὶ κατήκοον αὐτοῦ τῶν προσταγμάτων· οὕτως γὰρ αὐτῷ παραμενεῖν τὴν βασιλείαν εἰς πολὺν χρόνον καὶ τὸν οἶκον λαμπρὸν καὶ περιβόητον γενήσεσθαι, καταστρέψεσθαι δὲ καὶ Παλαιστίνους, καὶ οἷς ἂν ἔθνεσι πολεμῇ νικῶντα καὶ περιόντα τῇ μάχῃ κλέος ἀοίδιμον ζῶντά τε ἕξειν καὶ τοῖς μετʼ αὐτὸν ἀπολείψειν."},{"number":166,"text":"Καὶ Σαμουῆλος μὲν ἀπαλλάσσεται ταῦτα παραινέσας, πρὸς δὲ τὸν Δαβίδην μεταβαίνει τὸ θεῖον καταλιπὸν Σαοῦλον. καὶ ὁ μὲν προφητεύειν ἤρξατο τοῦ θείου πνεύματος εἰς αὐτὸν μετοικισαμένου, τὸν Σαοῦλον δὲ περιήρχετο πάθη τινὰ καὶ δαιμόνια πνιγμοὺς αὐτῷ καὶ στραγγάλας ἐπιφέροντα, ὡς τοὺς ἰατροὺς ἄλλην μὲν αὐτῷ θεραπείαν μὴ ἐπινοεῖν, εἰ δέ τίς ἐστιν ἐξᾴδειν δυνάμενος καὶ ψάλλειν ἐπὶ κινύρᾳ τοῦτον ἐκέλευσαν ζητήσαντας, ὁπόταν αὐτῷ προσίῃ τὰ δαιμόνια καὶ ταράττῃ, ποιεῖν ὑπὲρ κεφαλῆς στάντα ψάλλειν τε καὶ τοὺς ὕμνους ἐπιλέγειν."},{"number":167,"text":"ὁ δὲ οὐκ ἠμέλησεν, ἀλλὰ ζητεῖσθαι προσέταξε τοιοῦτον ἄνθρωπον· φήσαντος δέ τινος αὐτῷ τῶν παρόντων ἐν Βηθλεέμῃ πόλει τεθεᾶσθαι Ἰεσσαίου μὲν υἱὸν, ἔτι δὲ παῖδα τὴν ἡλικίαν, εὐπρεπῆ δὲ καὶ καλὸν τά τε ἄλλα σπουδῆς ἄξιον καὶ δὴ καὶ ψάλλειν εἰδότα καὶ ᾄδειν ὕμνους καὶ πολεμιστὴν ἄκρον, πέμψας πρὸς τὸν Ἰεσσαῖον ἐκέλευσεν ἀποστέλλειν αὐτῷ τὸν Δαβίδην τῶν ποιμνίων ἀποσπάσαντα· βούλεσθαι γὰρ αὐτὸν ἰδεῖν περὶ τῆς εὐμορφίας καὶ τῆς ἀνδρείας ἀκούσας τοῦ νεανίσκου."},{"number":168,"text":"ὁ δὲ Ἰεσσαῖος πέμπει τὸν υἱὸν καὶ ξένια δοὺς κομίσαι τῷ Σαούλῳ. ἐλθόντι δὲ ἥσθη καὶ ποιήσας ὁπλοφόρον διὰ πάσης ἦγε τιμῆς· ἐξῄδετο γὰρ ὑπʼ αὐτοῦ καὶ πρὸς τὴν ἀπὸ τῶν δαιμονίων ταραχήν, ὁπότε αὐτῷ ταῦτα προσέλθοι, μόνος ἰατρὸς ἦν λέγων τε τοὺς ὕμνους καὶ ψάλλων ἐν τῇ κινύρᾳ καὶ ποιῶν ἑαυτοῦ γίνεσθαι τὸν Σαοῦλον."},{"number":169,"text":"πέμπει τοίνυν πρὸς τὸν πατέρα τοῦ παιδὸς Ἰεσσαῖον ἐᾶσαι παρʼ αὐτῷ τὸν Δαβίδην κελεύων· ἥδεσθαι γὰρ αὐτῷ βλεπομένῳ καὶ παρόντι· τὸν δʼ οὐκ ἀντειπεῖν τῷ Σαούλῳ, συγχωρῆσαι δὲ κατέχειν."}],"9":[{"number":170,"text":"Χρόνοις δʼ ὕστερον οὐ πολλοῖς οἱ Παλαιστῖνοι πάλιν συνελθόντες καὶ δύναμιν ἀθροίσαντες μεγάλην ἐπίασι τοῖς Ἰσραηλίταις καὶ μεταξὺ Σωκοῦς καὶ Ἀζηκοῦς καταλαμβανόμενοι στρατοπεδεύονται. ἀντεπεξάγει δʼ αὐτοῖς τὴν στρατιὰν καὶ Σαοῦλος καὶ ἐπί τινος ὄρους στρατοπεδευσάμενος ἀναγκάζει τοὺς Παλαιστίνους τὸ μὲν πρῶτον στρατόπεδον καταλιπεῖν, ὁμοίως δʼ ἐπί τινος ὄρους ἀντικρὺ τοῦ καταληφθέντος ὑπὸ τοῦ Σαούλου στρατοπεδεύσασθαι."},{"number":171,"text":"διίστη δʼ ἀπʼ ἀλλήλων τὰ στρατόπεδα μέσος αὐλὼν τῶν ὀρῶν ἐφʼ ὧν ἦν. καταβὰς οὖν τις τῶν ἐκ τοῦ Παλαιστίνων στρατοπέδου Γολιάθης ὄνομα· πόλεως δὲ Γίττης ἀνὴρ παμμεγεθέστατος· ἦν γὰρ πηχῶν τεσσάρων καὶ σπιθαμῆς ὅπλα τῇ φύσει τοῦ σώματος ἀναλογοῦντα περικείμενος· θώρακα μὲν γὰρ ἐνεδέδυτο σταθμὸν ἄγοντα πέντε χιλιάδας σίκλων, κόρυθα δὲ καὶ κνημῖδας χαλκέας ὁποίας εἰκὸς ἦν ἀνδρὸς οὕτω παραδόξου τὸ μέγεθος σκεπάσαι μέρη, δόρυ δὲ ἦν οὐ κοῦφον βάσταγμα δεξιᾶς, ἀλλʼ ἐπὶ τῶν ὤμων αὐτὸ αἴρων ἔφερεν, εἶχε δὲ καὶ λόγχην ἑξακοσίων σίκλων, εἵποντο δὲ πολλοὶ βαστάζοντες τὰ ὅπλα·"},{"number":172,"text":"στὰς τοίνυν ὁ Γολίαθος οὗτος μεταξὺ τῶν παρατάξεων βοήν τε ἀφίησι μεγάλην καὶ πρὸς τὸν Σαοῦλον καὶ τοὺς Ἑβραίους λέγει· μάχης μὲν ὑμᾶς καὶ κινδύνων ἀπαλλάττω· τίς γὰρ ἀνάγκη τὴν στρατιὰν ἡμῶν συμπεσοῦσαν κακοπαθεῖν;"},{"number":173,"text":"δότε δʼ ὅστις ἐμοὶ μαχεῖται τῶν ὑμετέρων, καὶ βραβευθήσεται τὰ τοῦ πολέμου ἑνὶ τῷ νενικηκότι· δουλεύσουσι γὰρ ἐκεῖνοι τοῖς ἑτέροις, ὧν ἂν ὁ νικήσας γένηται· πολὺ δὲ κρεῖττον εἶναι καὶ σωφρονέστατον ἑνὸς κινδύνῳ λαβεῖν ὃ βούλεσθε ἢ τῷ ἁπάντων."},{"number":174,"text":"ταῦτʼ εἰπὼν ἀνεχώρησεν εἰς τὸ τῶν οἰκείων στρατόπεδον. τῇ δʼ ἐχομένῃ πάλιν ἐλθὼν τοὺς αὐτοὺς ἐποιήσατο λόγους, καὶ μέχρι τεσσαράκοντα ἡμερῶν οὐ διέλειπε προκαλούμενος ἐπὶ τοῖς προειρημένοις τοὺς πολεμίους, ὡς καταπλαγῆναι αὐτόν τε τὸν Σαοῦλον καὶ τὴν στρατιάν. καὶ παρετάσσοντο μὲν ὡς εἰς μάχην, οὐκ ἤρχοντο δὲ εἰς χεῖρας."},{"number":175,"text":"Τοῦ δὲ πολέμου συνεστηκότος τοῖς Ἑβραίοις καὶ τοῖς Παλαιστίνοις Σαοῦλος ἀπέλυσε τὸν Δαβίδην πρὸς τὸν πατέρα Ἰεσσαῖον ἀρκούμενος αὐτοῦ τοῖς τρισὶν υἱοῖς, οὓς ἐπὶ συμμαχίαν καὶ τοὺς κινδύνους ἔπεμψεν."},{"number":176,"text":"ὁ δὲ τὸ μὲν πρῶτον ἐπὶ τὰ ποίμνια πάλιν καὶ τὰς νομὰς τῶν βοσκημάτων παραγίνεται, μετʼ οὐ πολὺ δὲ ἔρχεται εἰς τὸ στρατόπεδον τῶν Ἑβραίων πεμφθεὶς ὑπὸ τοῦ πατρὸς κομίσαι τε τοῖς ἀδελφοῖς ἐφόδια καὶ γνῶναι τί πράττουσι."},{"number":177,"text":"τοῦ δὲ Γολιάθου πάλιν ἐλθόντος καὶ προκαλουμένου καὶ ὀνειδίζοντος, ὅτι μηδείς ἐστιν ἀνδρεῖος ἐν αὐτοῖς, ὃς εἰς μάχην αὐτῷ τολμᾷ καταβῆναι, μεταξὺ τοῖς ἀδελφοῖς ὁμιλῶν Δαβίδης περὶ ὧν ἐπέστειλεν ὁ πατὴρ ἀκούσας βλασφημοῦντος τὴν στρατιὰν καὶ κακίζοντος τοῦ Παλαιστίνου ἠγανάκτησε καὶ πρὸς τοὺς ἀδελφοὺς αὐτοῦ εἶπεν ἑτοίμως ἔχειν μονομαχῆσαι τῷ πολεμίῳ."},{"number":178,"text":"πρὸς τοῦθʼ ὁ πρεσβύτατος τῶν ἀδελφῶν Ἰάναβος ἐπέπληξεν αὐτῷ τολμηρότερον παρʼ ἡλικίαν καὶ ἀμαθῆ τοῦ προσήκοντος εἰπών, ἐκέλευσέ τε πρὸς τὰ ποίμνια καὶ τὸν πατέρα βαδίζειν. καταιδεσθεὶς δὲ τὸν ἀδελφὸν ὑπεχώρησε καὶ πρός τινας τῶν στρατιωτῶν ἀπελάλησεν, ὅτι θέλοι μάχεσθαι τῷ προκαλουμένῳ."},{"number":179,"text":"δηλωσάντων δʼ εὐθὺς τῷ Σαούλῳ τὴν τοῦ νεανίσκου προαίρεσιν μεταπέμπεται αὐτὸν ὁ βασιλεύς, καὶ πυθομένου τί βούλεται λέγειν μὴ ταπεινὸν ἔστω τὸ φρόνημα μηδʼ εὐλαβὲς, ὦ βασιλεῦ· καθαιρήσω γὰρ ἐγὼ τὴν ἀλαζονείαν τοῦ πολεμίου χωρήσας αὐτῷ διὰ μάχης καὶ τὸν ὑψηλὸν καὶ μέγαν ὑπʼ ἐμαυτῷ βαλών."},{"number":180,"text":"γένοιτο μὲν ἂν αὐτὸς οὕτως καταγέλαστος, ἔνδοξον δὲ τὸ σὸν στράτευμα, εἰ μηδʼ ὑπʼ ἀνδρὸς πολεμεῖν ἤδη δυναμένου καὶ πιστευομένου παράταξιν καὶ μάχας, ἀλλʼ ὑπὸ παιδὸς ἔτι δοκοῦντος καὶ ταύτην ἔχοντος τὴν ἡλικίαν ἀποθάνοι."},{"number":181,"text":"Τοῦ δὲ Σαούλου τὸ μὲν τολμηρὸν αὐτοῦ καὶ τὴν εὐψυχίαν θαυμάζοντος, οὐ θαρροῦντος δὲ ἐπʼ αὐτῷ διὰ τὴν ἡλικίαν, ἀλλʼ ἀσθενέστερον εἶναι διὰ ταύτην πρὸς εἰδότα πολεμεῖν μάχεσθαι λέγοντος, ταῦτʼ, εἶπε Δαβίδης, ἐπαγγέλλομαι τῷ θεῷ θαρρῶν ὄντι μετʼ ἐμοῦ· πεπείραμαι γὰρ αὐτοῦ τῆς βοηθείας."},{"number":182,"text":"λέοντα γὰρ ἐπελθόντα μού ποτε τοῖς ποιμνίοις καὶ ἁρπάσαντα ἄρνα διώξας καταλαμβάνω καὶ τὸν μὲν ἄρνα τοῦ στόματος ἐξαρπάζω τοῦ θηρὸς, αὐτὸν δʼ ὁρμήσαντα ἐπʼ ἐμὲ τῆς οὐρᾶς βαστάσας καὶ προσρήξας τῇ γῇ διαφθείρω."},{"number":183,"text":"ταὐτὸ δὲ καὶ ἄρκον ἀμυνόμενος διατίθεμαι. νομιζέσθω δὴ καὶ ὁ πολέμιος ἐκείνων εἶναι τῶν θηρίων ὀνειδίζων ἐκ πολλοῦ τὴν στρατιὰν καὶ βλασφημῶν ἡμῶν τὸν θεὸν, ὃς αὐτὸν ὑποχείριον ἐμοὶ θήσει."},{"number":184,"text":"Τῇ προθυμίᾳ τοιγαροῦν καὶ τῇ τόλμῃ τοῦ παιδὸς ὅμοιον γενέσθαι τέλος παρὰ τοῦ θεοῦ Σαοῦλος εὐξάμενος ἄπιθι, φησί πρὸς τὴν μάχην. καὶ περιθεὶς αὐτῷ τὸν αὑτοῦ θώρακα καὶ περιζώσας τὸ ξίφος καὶ περικεφαλαίαν ἁρμόσας ἐξέπεμψεν."},{"number":185,"text":"ὁ δὲ Δαβίδης βαρυνόμενος ὑπὸ τῶν ὅπλων, οὐκ ἐγεγύμναστο γὰρ οὐδʼ ἐμεμαθήκει φέρειν ὅπλα, ταῦτα μέν, εἶπεν, ὦ βασιλεῦ, σὸς ἔστω κόσμος τοῦ βαστάζειν δυναμένου, συγχώρησον δὲ ὡς δούλῳ σου καὶ ὡς ἐγὼ βούλομαι μαχεσθῆναι. τίθησιν οὖν τὰ ὅπλα καὶ τὴν βακτηρίαν ἀράμενος καὶ πέντε λίθους ἐκ τοῦ χειμάρρου βαλὼν εἰς τὴν πήραν τὴν ποιμενικὴν καὶ σφενδόνην ἐν τῇ δεξιᾷ χειρὶ φέρων ἐπὶ τὸν Γολίαθον ἐπορεύετο."},{"number":186,"text":"καταφρονεῖ δὲ οὕτως ἰδὼν αὐτὸν ὁ πολέμιος ἐρχόμενον καὶ προσέσκωψεν, ὡς οὐχ οἷα πρὸς ἄνθρωπον ὅπλα νενόμισται ταῦτʼ ἔχων μέλλοι μάχεσθαι, οἷς δὲ κύνας ἀπελαύνομεν καὶ φυλασσόμεθα. μὴ αὐτὸν ἀντὶ ἀνθρώπου κύνα εἶναι δοκεῖ; ὁ δʼ οὐχὶ τοιοῦτον ἀλλὰ καὶ χείρω κυνὸς αὐτὸν νομίζειν ἀπεκρίνατο. κινεῖ δὲ πρὸς ὀργὴν τὸν Γολίαθον, καὶ ἀρὰς αὐτῷ τίθεται ἐκ τῆς προσηγορίας τοῦ θεοῦ καὶ δώσειν ἠπείλησε τὰς σάρκας αὐτοῦ τοῖς ἐπιγείοις καὶ τοῖς μεταρσίοις διασπάσασθαι·"},{"number":187,"text":"ἀμείβεται δʼ αὐτὸν ὁ Δαβίδης· σὺ μὲν ἐπέρχῃ μοι ἐν ῥομφαίᾳ καὶ δόρατι καὶ θώρακι, ἐγὼ δὲ χωρῶν ἐπὶ σὲ τὸν θεὸν ὥπλισμαι, ὃς σέ τε καὶ πᾶσαν ὑμῶν στρατιὰν χερσὶ ταῖς ἡμετέραις διολέσει. καρατομήσω μὲν γάρ σε σήμερον καὶ τὸ ἄλλο σῶμα τοῖς ὁμοφύλοις κυσὶ παραβαλῶ, μαθήσονται δὲ πάντες, ὅτι προέστηκεν Ἑβραίων τὸ θεῖον καὶ ὅπλα ἡμῖν καὶ ἰσχὺς τοῦτʼ ἔστι κηδόμενον, ἡ δʼ ἄλλη παρασκευὴ καὶ δύναμις ἀνωφελὴς θεοῦ μὴ παρόντος."},{"number":188,"text":"ὁ δὲ Παλαιστῖνος ὑπὸ βάρους τῶν ὅπλων εἰς ὠκύτητα καὶ δρόμον ἐμποδιζόμενος βάδην ἐπὶ τὸν Δαβίδην παραγίνεται καταφρονῶν καὶ πεποιθὼς γυμνὸν ὁμοῦ καὶ παῖδα ἔτι τὴν ἡλικίαν ἀπόνως ἀναιρήσειν."},{"number":189,"text":"Ἀπαντᾷ δὲ ὁ νεανίσκος μετὰ συμμάχου μὴ βλεπομένου τῷ πολεμίῳ· θεὸς δʼ ἦν οὗτος. καὶ ἀνελόμενος ἐκ τῆς πήρας ὧν εἰς αὐτὴν κατέθηκεν ἐκ τοῦ χειμάρρου λίθων ἕνα καὶ ἁρμόσας τῇ σφενδόνῃ βάλλει ἐπὶ τὸν Γολίαθον εἰς τὸ μέτωπον· καὶ διῆλθεν ἕως τοῦ ἐγκεφάλου τὸ βληθέν, ὡς εὐθὺς καρωθέντα πεσεῖν τὸν Γολίαθον ἐπὶ τὴν ὄψιν."},{"number":190,"text":"δραμὼν δʼ ἐφίσταται τῷ πολεμίῳ κειμένῳ καὶ τῇ ῥομφαίᾳ τῇ ἐκείνου μάχαιραν οὐκ ἔχων αὐτὸς ἀποτέμνει τὴν κεφαλὴν αὐτοῦ."},{"number":191,"text":"πεσὼν δʼ ὁ Γολίαθος ἧττα καὶ φυγὴ γίνεται Παλαιστίνοις· τὸν γὰρ δοκιμώτατον ἰδόντες ἐρριμμένον καὶ περὶ τῶν ὅλων δείσαντες οὐκέτι μένειν διέγνωσαν, ἀλλʼ αἰσχρᾷ καὶ ἀκόσμῳ φυγῇ παραδόντες ἑαυτοὺς ἐξαρπάζειν τῶν κινδύνων ἐπειρῶντο. Σαοῦλος δὲ καὶ πᾶς ὁ τῶν Ἑβραίων στρατὸς ἀλαλάξαντες ἐκπηδῶσιν εἰς αὐτοὺς καὶ πολλοὺς ἀποσφάττοντες διώκουσιν ἄχρι τῶν Γίττης ὁρίων καὶ τῶν πυλῶν τῶν Ἀσκάλωνος."},{"number":192,"text":"καὶ θνήσκουσι μὲν τῶν Παλαιστίνων εἰς τρισμυρίους, δὶς δὲ τοσοῦτοι τραυματίαι γίνονται. Σαοῦλος δὲ ὑποστρέψας εἰς τὸ στρατόπεδον αὐτῶν διαρπάζει τὸ χαράκωμα καὶ ἐνέπρησε· τὴν κεφαλὴν δὲ Γολιάθου Δαβίδης εἰς τὴν ἰδίαν σκηνὴν ἐκόμισε καὶ τὴν ῥομφαίαν ἀνέθηκε τῷ θεῷ."}],"10":[{"number":193,"text":"Φθόνον δὲ καὶ μῖσος τοῦ Σαούλου πρὸς αὐτὸν αἱ γυναῖκες ἐρεθίζουσιν· ὑπαντῶσαι γὰρ τῇ στρατιᾷ νικηφόρῳ μετὰ κυμβάλων καὶ τυμπάνων καὶ παντοίας χαρᾶς ᾖδον αἱ μὲν γυναῖκες, ὡς πολλὰς Σαοῦλος ἀπώλεσε Παλαιστίνων χιλιάδας, αἱ παρθένοι δὲ, ὡς μυριάδας Δαυίδης ἀφανίσειε."},{"number":194,"text":"τούτων δὲ ἀκούων ὁ βασιλεύς, ὡς τὸ μὲν ἔλαττον τῆς μαρτυρίας αὐτὸς λάβοι, τὸ δὲ τῶν μυριάδων πλῆθος ἀνατεθείη τῷ νεανίσκῳ, καὶ λογισάμενος μηδὲν οὕτω μετὰ λαμπρὰν εὐφημίαν ἢ τὴν βασιλείαν ὑστερεῖν αὐτῷ φοβεῖσθαι καὶ ὑποπτεύειν ἤρξατο τὸν Δαυίδην."},{"number":195,"text":"καὶ τῆς μὲν πρώτης τάξεως, ἐπεὶ τῷ δέει πλησίον αὐτοῦ καὶ λίαν ἐγγὺς ἐδόκει, ἐποίησε γὰρ αὐτὸν ὁπλοφόρον, μεταστήσας ἀποδείκνυσι χιλίαρχον δοὺς αὐτῷ χώραν ἀμείνονα μὲν ἀσφαλεστέραν δὲ ὡς ἐνόμιζεν αὑτῷ· ἐβούλετο γὰρ εἰς τοὺς πολεμίους αὐτὸν ἐκπέμπειν καὶ τὰς μάχας ὡς ἐν τοῖς κινδύνοις τεθνηξόμενον."},{"number":196,"text":"Δαυίδης δὲ πανταχοῦ τὸν θεὸν ἐπαγόμενος ὅποι ποτʼ ἀφίκοιτο κατώρθου καὶ διευπραγῶν ἐδείκνυτο, ὡς διʼ ὑπερβολὴν τῆς ἀνδρείας τόν τε λαὸν αὐτοῦ καὶ τὴν Σαούλου θυγατέρα παρθένον ἔτι οὖσαν λαβεῖν ἔρωτα καὶ τοῦ πάθους ὑπερκρατοῦντος γενέσθαι φανερὰν καὶ διαβληθῆναι πρὸς τὸν πατέρα."},{"number":197,"text":"ὁ δʼ ὡς ἀφορμῇ χρησάμενος τῆς ἐπὶ Δαυίδην ἐπιβουλῆς ἡδέως ἤκουσε καὶ δώσειν προθύμως αὐτῷ τὴν παρθένον πρὸς τοὺς τὸν ἔρωτα μηνύσαντας αὐτῆς ἔφη γενησόμενον ἀπωλείας καὶ κινδύνων αἴτιον αὐτῷ ληψομένῳ· κατεγγυῶ γὰρ, εἶπεν, αὐτῷ τὸν τῆς θυγατρός μου γάμον, ἂν ἑξακοσίας μοι κομίσῃ κεφαλὰς τῶν πολεμίων."},{"number":198,"text":"ὁ δὲ καὶ γέρως οὕτω λαμπροῦ προτεθέντος καὶ βουλόμενος ἐπʼ ἔργῳ παραβόλῳ καὶ ἀπίστῳ λαβεῖν κλέος ὁρμήσει μὲν ἐπὶ τὴν πρᾶξιν, διαφθαρήσεται δὲ ὑπὸ τῶν Παλαιστίνων καὶ χωρήσει μοι τὰ κατʼ αὐτὸν εὐπρεπῶς· ἀπαλλαγήσομαι γὰρ αὐτοῦ διʼ ἄλλων αὐτὸν ἀλλʼ οὐχὶ διʼ ἐμαυτοῦ κτείνας."},{"number":199,"text":"διάπειραν δὴ τῆς τοῦ Δαυίδου διανοίας κελεύει τοὺς οἰκέτας λαμβάνειν, πῶς ἔχει πρὸς τὸ γῆμαι τὴν κόρην. οἱ δʼ ἤρξαντο διαλέγεσθαι πρὸς αὐτόν, ὅτι στέργει μὲν αὐτὸν ὁ βασιλεὺς Σαοῦλος καὶ ὁ λαὸς ἅπας, βούλεται δʼ αὐτῷ κηδεῦσαι τὴν θυγατέρα."},{"number":200,"text":"ὁ δὲ μικρὸν ἄρʼ ὑμῖν, εἶπε, δοκεῖ γαμβρὸν γενέσθαι βασιλέως· ἐμοὶ δʼ οὐχὶ τοιοῦτον φαίνεται καὶ μάλιστα ὄντι ταπεινῷ καὶ δόξης καὶ τιμῆς ἀμοίρῳ. Σαοῦλος δὲ ἀγγειλάντων αὐτῷ τῶν οἰκετῶν τὰς τοῦ Δαυίδου ἀποκρίσεις οὐ χρημάτων, ἔφη, δεῖσθαί με φράζετε αὐτῷ οὐδὲ ἔδνων, ἀπεμπολᾶν γὰρ ἔστιν οὕτως τὴν θυγατέρα μᾶλλον ἢ συνοικίζειν, γαμβροῦ δὲ ἀνδρείαν ἔχοντος καὶ τὴν ἄλλην ἀρετὴν ἅπασαν, ἣν ὁρᾶν ὑπάρχουσαν αὐτῷ."},{"number":201,"text":"βούλεσθαι δή με παρʼ αὐτοῦ λαβεῖν ἀντὶ τοῦ γάμου τῆς θυγατρὸς οὐ χρυσὸν οὐδʼ ἄργυρον οὐδʼ ὅπως ταῦτα ἐκ τῶν τοῦ πατρὸς οἰκιῶν κομίσῃ, Παλαιστίνων δὲ τιμωρίαν καὶ κεφαλὰς αὐτῶν ἑξακοσίας."},{"number":202,"text":"αὐτῷ τε γὰρ ἐμοὶ τούτων οὐδὲν ἂν οὔτε ποθεινότερον οὔτε λαμπρότερον οὔτε προτιμότερον δῶρον γένοιτο, τῇ τε παιδί μου πολὺ τῶν νενομισμένων ἔδνων ζηλωτότερον τὸ συνοικεῖν ἀνδρὶ τοιούτῳ καὶ μαρτυρουμένῳ τὴν τῶν πολεμίων ἧτταν."},{"number":203,"text":"Κομισθέντων δὲ τούτων πρὸς τὸν Δαυίδην τῶν λόγων ἡσθεὶς τὸν Σαοῦλον ἐσπουδακέναι νομίζων αὐτοῦ περὶ τὴν συγγένειαν, οὐδὲ βουλεύσασθαι περιμείνας οὐδʼ εἰ δυνατὸν ἢ δύσκολόν ἐστι τὸ προκείμενον ἔργον τῷ λογισμῷ περινοήσας ὥρμησεν εὐθὺς μετὰ τῆς ἑταιρίας ἐπὶ τοὺς πολεμίους καὶ τὴν ὑπὲρ τοῦ γάμου κατηγγελμένην πρᾶξιν καί, θεὸς γὰρ ἦν ὁ πάντα ποιῶν εὐμαρῆ καὶ δυνατὰ τῷ Δαυΐδῃ, κτείνας πολλοὺς καὶ κεφαλὰς ἑξακοσίων ἀποτεμὼν ἧκε πρὸς τὸν βασιλέα διὰ τῆς τούτων ἐπιδείξεως τὸν ἀντὶ τούτων γάμον ἀπαιτῶν."},{"number":204,"text":"Σαοῦλος δὲ οὐκ ἔχων ἀναφυγεῖν ἐκ τῶν ὑπεσχημένων, αἰσχρὸν γὰρ ὑπελάμβανεν ἢ ψεύσασθαι δοκεῖν ἢ διʼ ἐπιβουλὴν ἵνʼ ὡς ἀδυνάτοις ἐπιχειρῶν ὁ Δαυίδης ἀποθάνῃ τὸν γάμον ἐπηγγέλθαι, δίδωσιν αὐτῷ τὴν θυγατέρα Μελχὰν ὀνόματι."}],"11":[{"number":205,"text":"Ἔμελλε δὲ οὐκ ἐπὶ πολὺ τοῖς γεγενημένοις ἐμμένειν Σαοῦλος ἄρα· ὁρῶν γὰρ τὸν Δαυίδην παρὰ τῷ θεῷ καὶ παρὰ τοῖς ὄχλοις εὐδοκιμοῦντα κατέδεισε, καὶ τὸν φόβον οὐκ ἔχων ἀποκρύψασθαι περὶ μεγάλων ὄντα βασιλείας τε καὶ ζωῆς, ὧν καὶ θατέρου στερηθῆναι συμφορὰ δεινή, κτείνειν τὸν Δαυίδην διεγνώκει καὶ προστάσσει τὴν ἀναίρεσιν αὐτοῦ Ἰωνάθῃ τῷ παιδὶ καὶ τοῖς πιστοτάτοις τῶν οἰκετῶν."},{"number":206,"text":"ὁ δὲ τὸν πατέρα τῆς ἐπὶ τῷ Δαυίδῃ μεταβολῆς θαυμάσας οὐκ ἐπὶ μετρίοις ἀπὸ τῆς πολλῆς εὐνοίας ἀλλʼ ἐπὶ θανάτῳ γενομένης, καὶ τὸν νεανίσκον ἀγαπῶν καὶ τὴν ἀρετὴν αὐτοῦ καταιδούμενος λέγει πρὸς αὐτὸν τὸ τοῦ πατρὸς ἀπόρρητον καὶ τὴν προαίρεσιν."},{"number":207,"text":"συμβουλεύει μέντοι φυλάσσεσθαι γενόμενον ἐκποδὼν τὴν ἐπιοῦσαν ἡμέραν· αὐτὸς γὰρ ἀσπάσεσθαι τὸν πατέρα καὶ καιροῦ παραφανέντος αὐτῷ διαλεχθήσεσθαι περὶ αὐτοῦ καὶ τὴν αἰτίαν μαθήσεσθαι καὶ ταύτην ἐκφαυλίσειν,"},{"number":208,"text":"ὡς οὐ δεῖν ἐπʼ αὐτῇ κτείνειν τοσαῦτα μὲν ἀγαθὰ τὸ πλῆθος ἐργασάμενον εὐεργέτην δʼ αὐτοῦ γεγενημένον, διʼ ἃ καὶ συγγνώμην ἂν ἐπὶ τοῖς μεγίστοις ἁμαρτήμασιν εἰκότως εὕρατο. δηλώσω δέ σοι τὴν τοῦ πατρὸς γνώμην. Δαυίδης δὲ πεισθεὶς συμβουλίᾳ χρηστῇ ὑπεξίσταται τῆς τοῦ βασιλέως ὄψεως."},{"number":209,"text":"Τῇ δʼ ἐπιούσῃ πρὸς τὸν Σαοῦλον Ἰωνάθης ἐλθὼν ὡς ἱλαρόν τε καὶ χαίροντα κατέλαβεν ἤρξατο λόγους αὐτῷ περὶ τοῦ Δαυίδου προσφέρειν· τί καταγνοὺς αὐτοῦ μικρὸν ἢ μεῖζον ἀδίκημα, πάτερ, προσέταξας ἀνελεῖν ἄνδρα μέγα μὲν αὐτῷ πρὸς σωτηρίαν ὄφελος γεγενημένον, μεῖζον δὲ πρὸς τὴν Παλαιστίνων τιμωρίαν,"},{"number":210,"text":"ὕβρεως δὲ καὶ χλεύης ἀπαλλάξαντα τὸν Ἑβραίων λαὸν ἣν ἐπὶ τεσσαράκοντα ἡμέρας ὑπέμεινε μόνος τολμῶν ὑποστῆναι τὴν τοῦ πολεμίου πρόκλησιν, καὶ μετὰ ταῦτα κομίσαντα μὲν ὅσας ἐπετάχθη κεφαλὰς τῶν ἐχθρῶν, λαβόντα δʼ ἐπὶ τούτῳ γέρας τὴν ἐμὴν ἀδελφὴν πρὸς γάμον, ὡς ἂν ἀλγεινὸς αὐτοῦ γένοιθʼ ἡμῖν ὁ θάνατος οὐ διὰ τὴν ἀρετὴν μόνον, ἀλλὰ καὶ διὰ τὴν συγγένειαν· συναδικεῖται γὰρ αὐτοῦ τῷ θανάτῳ καὶ ἡ σὴ θυγάτηρ χηρείαν πρὶν ἢ τῆς συμβιώσεως εἰς ὄνησιν ἐλθεῖν μέλλουσα πειράζειν."},{"number":211,"text":"ταῦτα λογισάμενος μεταβαλοῦ πρὸς τὸ ἡμερώτερον καὶ μηδὲν ποιήσῃς κακὸν ἄνδρα πρῶτον μὲν εὐεργεσίαν εὐεργετήσαντα μεγάλην τὴν σὴν σωτηρίαν, ὅτε σοι τοῦ πονηροῦ πνεύματος καὶ τῶν δαιμονίων ἐγκαθεζομένων τὰ μὲν ἐξέβαλεν, εἰρήνην δὲ ἀπʼ αὐτῶν τῇ ψυχῇ σου παρέσχεν, δεύτερον δὲ τὴν ἀπὸ τῶν πολεμίων ἐκδικίαν· αἰσχρὸν γὰρ τούτων ἐπιλελῆσθαι."},{"number":212,"text":"τούτοις παρηγορεῖται τοῖς λόγοις Σαοῦλος καὶ μηδὲν ἀδικήσειν τὸν Δαυίδην ὄμνυσι τῷ παιδί· κρείττων γὰρ ὀργῆς καὶ φόβου δίκαιος λόγος. Ἰωνάθης δὲ μεταπεμψάμενος τὸν Δαυίδην σημαίνει τε αὐτῷ χρηστὰ καὶ σωτήρια τὰ παρὰ τοῦ πατρὸς ἄγει τε πρὸς αὐτόν, καὶ παρέμεινε τῷ βασιλεῖ Δαυίδης ὥσπερ ἔμπροσθεν."},{"number":213,"text":"Κατὰ δὲ τοῦτον τὸν καιρὸν τῶν Παλαιστίνων στρατευσαμένων πάλιν ἐπὶ τοὺς Ἑβραίους πέμπει μετὰ στρατιᾶς τὸν Δαυίδην πολεμήσοντα τοῖς Παλαιστίνοις, καὶ συμβαλὼν πολλοὺς αὐτῶν ἀπέκτεινε καὶ νικήσας ἐπάνεισι πρὸς τὸν βασιλέα. προσδέχεται δʼ αὐτὸν ὁ Σαοῦλος οὐχ ὡς ἤλπισεν ἀπὸ τοῦ κατορθώματος, ἀλλʼ ὑπὸ τῆς εὐπραγίας αὐτοῦ λυπηθεὶς ὡς ἐπισφαλέστερος αὐτὸς ἐκ τῶν ἐκείνου πράξεων γενόμενος."},{"number":214,"text":"ἐπεὶ δὲ πάλιν αὐτὸν προσελθὸν τὸ δαιμόνιον ἐθορύβει πνεῦμα καὶ συνετάραττε, καλέσας εἰς τὸ δωμάτιον ἐν ᾧ κατέκειτο κατέχων τὸ δόρυ προσέταξε τῷ ψαλμῷ καὶ τοῖς ὕμνοις ἐξᾴδειν αὐτόν. ἐκείνου δὲ τὰ κελευσθέντα ποιοῦντος διατεινάμενος ἀκοντίζει τὸ δόρυ· καὶ τὸ μὲν προϊδόμενος ὁ Δαυίδης ἐξέκλινε, φεύγει δὲ εἰς τὸν οἶκον τὸν αὑτοῦ καὶ διʼ ὅλης ἔμεινεν ἡμέρας αὐτόθι."},{"number":215,"text":"Νυκτὸς δὲ πέμψας ὁ βασιλεὺς ἐκέλευσεν αὐτὸν ἄχρι τῆς ἕω φυλάττεσθαι μὴ καὶ λάθῃ παντελῶς ἀφανὴς γενόμενος, ἵνα παραγενόμενος εἰς τὸ δικαστήριον καὶ κρίσει παραδοὺς ἀποκτείνῃ. Μελχὰ δὲ ἡ γυνὴ Δαυίδου θυγάτηρ δὲ τοῦ βασιλέως τὴν τοῦ πατρὸς μαθοῦσα διάνοιαν τῷ ἀνδρὶ παρίσταται δειλὰς ἔχουσα τὰς περὶ αὐτοῦ ἐλπίδας καὶ περὶ τῆς ἰδίας ψυχῆς ἀγωνιῶσα· οὐδὲ γὰρ αὑτὴν ζῆν ὑπομενεῖν ἐκείνου στερηθεῖσαν."},{"number":216,"text":"καί μή σε, φησίν, ὁ ἥλιος ἐνταυθοῖ καταλάβῃ· οὐ γὰρ ἔτʼ ὄψεταί σε. φεῦγε δʼ ἕως τοῦτό σοι δύναται παρασχεῖν ἡ παροῦσα νύξ· καὶ ποιήσει δέ σοι ταύτην ὁ θεὸς μακροτέραν· ἴσθι γὰρ σαυτὸν ἂν εὑρεθῇς ὑπὸ τοῦ πατρὸς ἀπολούμενον. καὶ καθιμήσασα διὰ θυρίδος αὐτὸν ἐξέσωσεν·"},{"number":217,"text":"ἔπειτα σκευάσασα τὴν κλίνην ὡς ἐπὶ νοσοῦντι καὶ ὑποθεῖσα τοῖς ἐπιβολαίοις ἧπαρ αἰγός, ἅμʼ ἡμέρᾳ τοῦ πατρὸς ὡς αὐτὴν πέμψαντος ἐπὶ τὸν Δαυίδην ὠχλῆσθαι διὰ τῆς νυκτὸς εἶπε τοῖς παροῦσιν ἐπιδείξασα τὴν κλίνην κατακεκαλυμμένην καὶ τῷ πηδήματι τοῦ ἥπατος σαλεύοντι τὴν ἐπιβολὴν πιστωσαμένη τὸ κατακείμενον τὸν Δαυίδην ἀσθμαίνειν."},{"number":218,"text":"ἀπαγγειλάντων δὲ τῶν πεμφθέντων, ὅτι γένοιτο διὰ τῆς νυκτὸς ἀσθενέστερος, ἐκέλευσεν οὕτως ἔχοντα κομισθῆναι· βούλεσθαι γὰρ αὐτὸν ἀνελεῖν. ἐλθόντες δὲ καὶ ἀνακαλύψαντες τὴν κλίνην καὶ τὸ σόφισμα τῆς γυναικὸς εὑρόντες ἀπήγγειλαν τῷ βασιλεῖ."},{"number":219,"text":"μεμφομένου δὲ τοῦ πατρὸς αὐτήν, ὅτι σώσειε μὲν τὸν ἐχθρὸν αὐτοῦ κατασοφίσαιτο δʼ αὐτόν, ἀπολογίαν σκήπτεται πιθανήν· ἀπειλήσαντα γὰρ αὐτὴν ἀποκτείνειν ἔφησε τυχεῖν ἐκ τοῦ δέους τῆς πρὸς τὸ σωθῆναι συνεργίας· ὑπὲρ ἧς συγγνῶναι καλῶς ἔχειν αὐτῇ κατʼ ἀνάγκην ἀλλὰ μὴ κατὰ προαίρεσιν γενομένης· οὐ γὰρ οὕτως, ἔλεγεν, οἶμαι τὸν ἐχθρὸν ἐζήτεις ἀποθανεῖν, ὡς ἐμὲ σώζεσθαι. καὶ συγγινώσκει δὲ τῇ κόρῃ Σαοῦλος."},{"number":220,"text":"ὁ δὲ Δαυίδης ἐκφυγὼν τὸν κίνδυνον ἧκε πρὸς τὸν προφήτην Σαμουῆλον εἰς Ἀραμαθὰ καὶ τὴν ἐπιβουλὴν αὐτῷ τὴν τοῦ βασιλέως ἐδήλωσε καὶ ὡς παρὰ μικρὸν ὑπʼ αὐτοῦ τῷ δόρατι βληθεὶς ἀποθάνοι, μήτʼ ἐν τοῖς πρὸς αὐτὸν κακὸς γενόμενος μήτʼ ἐν τοῖς πρὸς τοὺς πολεμίους ἀγῶσιν ἄνανδρος, ἀλλʼ ἐν ἅπασι μετὰ τοῦ θυμοῦ καὶ ἐπιτυχής. τοῦτο δʼ ἦν αἴτιον Σαούλῳ τῆς πρὸς Δαυίδην ἀπεχθείας."},{"number":221,"text":"Μαθὼν δʼ ὁ προφήτης τὴν τοῦ βασιλέως ἀδικίαν καταλείπει μὲν τὴν πόλιν Ἀραμαθάν, ἀγαγὼν δὲ τὸν Δαυίδην ἐπί τινα τόπον Γαλβουὰθ ὄνομα ἐκεῖ διέτριβε σὺν αὐτῷ. ὡς δʼ ἀπηγγέλη τῷ Σαούλῳ παρὰ τῷ προφήτῃ τυγχάνων ὁ Δαυίδης πέμψας ὁπλίτας πρὸς αὑτὸν ἄγειν προσέταξε συλλαμβάνοντας."},{"number":222,"text":"οἱ δʼ ἐλθόντες πρὸς τὸν Σαμουῆλον καὶ καταλαβόντες προφητῶν ἐκκλησίαν τοῦ θείου μεταλαμβάνουσι πνεύματος καὶ προφητεύειν ἤρξαντο· Σαοῦλος δʼ ἀκούσας ἄλλους ἔπεμψεν ἐπὶ τὸν Δαυίδην· κἀκείνων ταὐτὸ τοῖς πρώτοις παθόντων πάλιν ἀπέστειλεν ἑτέρους· προφητευόντων δὲ καὶ τῶν τρίτων τελευταῖον ὀργισθεὶς αὐτὸς ἐξώρμησεν."},{"number":223,"text":"ἐπεὶ δʼ ἐγγὺς ἦν ἤδη, Σαμουῆλος πρὶν ἰδεῖν αὐτὸν προφητεύειν ἐποίησεν. ἐλθὼν δὲ πρὸς αὐτὸν Σαοῦλος ὑπὸ τοῦ πολλοῦ πνεύματος ἐλαυνόμενος ἔκφρων γίνεται καὶ τὴν ἐσθῆτα περιδύσας ἑαυτὸν καταπεσὼν ἔκειτο διʼ ὅλης ἡμέρας τε καὶ νυκτὸς Σαμουήλου τε καὶ Δαυίδου βλεπόντων."},{"number":224,"text":"Ἰωνάθης δὲ ὁ Σαούλου παῖς ἀφικομένου πρὸς αὐτὸν ἐκεῖθεν Δαυίδου καὶ περὶ τῆς τοῦ πατρὸς ἀποδυρομένου ἐπιβουλῆς καὶ λέγοντος, ὡς οὐδὲν ἀδικήσας οὔτʼ ἐξαμαρτὼν σπουδάζοιτο ὑπὸ τοῦ πατρὸς αὐτοῦ φονευθῆναι, μήθʼ ἑαυτῷ τοῦθʼ ὑπονοοῦντι πιστεύειν παρεκάλει μήτε τοῖς διαβάλλουσιν, εἴ τινες ἄρα εἰσὶν οἱ τοῦτο πράττοντες, ἀλλʼ αὐτῷ προσέχειν καὶ θαρρεῖν· μηδὲν γὰρ τοιοῦτον ἐπʼ αὐτῷ φρονεῖν τὸν πατέρα· φράσαι γὰρ ἂν αὐτῷ περὶ τούτου καὶ σύμβουλον παραλαβεῖν τῇ κοινῇ γνώμῃ καὶ τἆλλα πράττοντα."},{"number":225,"text":"ὁ δὲ Δαυίδης ὤμνυεν ἦ μὴν οὕτως ἔχειν, καὶ πιστεύοντʼ ἠξίου προνοεῖν αὐτοῦ μᾶλλον ἢ καταφρονοῦντʼ ἐπʼ ἀληθέσι τοῖς λόγοις τότε ἀληθὲς ὑπολαβεῖν, ὅταν ἢ θεάσηται πεφονευμένον αὐτὸν ἢ πύθηται· μηδὲν λέγειν δʼ αὐτῷ τὸν πατέρα περὶ τούτων ἔφασκεν εἰδότα τὴν πρὸς αὐτὸν φιλίαν καὶ διάθεσιν."},{"number":226,"text":"Λυπηθεὶς δʼ ἐφʼ ὅτῳ πιστωσάμενος τὴν τοῦ Σαούλου προαίρεσιν Ἰωνάθης οὐκ ἔπεισεν ἐπηρώτα, τίνος ἐξ αὐτοῦ βούλεται τυχεῖν. ὁ δέ οἶδα γάρ, ἔφη, πάντα σε χαρίζεσθαί μοι καὶ παρέχειν ἐθέλοντα· νουμηνία μὲν εἰς τὴν ἐπιοῦσάν ἐστιν, ἔθος δʼ ἔχω δειπνεῖν σὺν τῷ βασιλεῖ καθήμενος·"},{"number":227,"text":"εἰ δή σοι δοκεῖ πορευθεὶς ἔξω τῆς πόλεως ἐν τῷ πεδίῳ λανθάνων διαμενῶ, σὺ δʼ ἐπιζητήσαντος αὐτοῦ λέγε πορευθῆναί με εἰς τὴν πατρίδα Βηθλέεμʼ ἑορτήν μου τῆς φυλῆς ἀγούσης προστιθεὶς ὅτι σύ μοι συγκεχώρηκας. κἂν μὲν οἷον εἰκὸς καὶ σύνηθές ἐστι λέγειν ἐπὶ φίλοις ἀποδημοῦσιν ἐπʼ ἀγαθῷ βεβάδικεν εἴπῃ, ἴσθι μηδὲν ὕπουλον παρʼ αὐτοῦ εἶναι μηδʼ ἐχθρόν· ἂν δʼ ὡς ἄλλως ἀποκρίνηται τοῦτʼ ἔσται τεκμήριον τῶν κατʼ ἐμοῦ βεβουλευμένων."},{"number":228,"text":"μηνύσεις δέ μοι τὴν διάνοιαν τὴν τοῦ πατρὸς οἴκτῳ τε νέμων τοῦτο καὶ φιλίᾳ, διʼ ἣν πίστεις τε παρʼ ἐμοῦ λαβεῖν ἠξίωκας αὐτός τε ἐμοὶ δοῦναι δεσπότης ὤν. εἰ δʼ εὑρίσκεις τι ἐν ἐμοὶ πονηρόν, αὐτὸς ἄνελε καὶ φθάσον τὸν πατέρα."},{"number":229,"text":"Πρὸς δὲ τὸ τελευταῖον δυσχεράνας τῶν λόγων Ἰωνάθης ποιήσειν ταῦτʼ ἐπηγγείλατο κἄν τι σκυθρωπὸν ὁ πατὴρ αὐτοῦ καὶ τὴν ἀπέχθειαν ἐμφανίζον ἀποκρίνηται μηνύσειν. ἵνα δʼ αὐτῷ θαρρῇ μᾶλλον, ἐξαγαγὼν αὐτὸν εἰς ὕπαιθρον καὶ καθαρὸν ἀέρα οὐδὲν παρήσειν ὑπὲρ τῆς Δαυίδου σωτηρίας ὤμνυε·"},{"number":230,"text":"τὸν γὰρ θεόν, εἶπε, τοῦτον ὃν πολὺν ὁρᾷς καὶ πανταχοῦ κεχυμένον, καὶ πρὶν ἑρμηνεῦσαί με τοῖς λόγοις τὴν διάνοιαν ἤδη μου ταύτην εἰδότα, μάρτυρα ποιοῦμαι τῶν πρὸς σὲ συνθηκῶν, ὡς οὐκ ἀνήσω τὸν πατέρα πολλάκις αὐτοῦ τῆς προαιρέσεως διάπειραν λαμβάνων, πρὶν ἢ καταμαθεῖν ἥτις ἐστὶ καὶ παρὰ τοῖς ἀπορρήτοις αὐτοῦ τῆς ψυχῆς γενέσθαι."},{"number":231,"text":"καταμαθὼν δʼ οὐκ ἀποκρύψομαι, καταμηνύσω δὲ πρὸς σὲ καὶ πρᾷον ὄντα καὶ δυσμενῶς διακείμενον. οἶδε δὲ οὗτος ὁ θεός, πῶς αὐτὸν εἶναι μετὰ σοῦ διὰ παντὸς εὔχομαι· ἔστι μὲν γὰρ νῦν καὶ οὐκ ἀπολείψει σε, ποιήσει δέ σε τῶν ἐχθρῶν ἄντε ὁ πατὴρ ὁ ἐμὸς ᾖ ἄντʼ ἐγὼ κρείττονα."},{"number":232,"text":"σὺ μόνον μνημόνευε τούτων, κἂν ἀποθανεῖν μοι γένηται τὰ τέκνα μου σῶζε, καὶ τὴν ὑπὲρ τῶν παρόντων μοι ἀμοιβὴν εἰς ἐκεῖνα κατάθου. ταῦτʼ ἐπομόσας ἀπολύει τὸν Δαυίδην εἴς τινα τόπον ἀπελθεῖν τοῦ πεδίου φράσας, ἐν ᾧ γυμναζόμενος διατελεῖ· γνοὺς γὰρ τὰ παρὰ τοῦ πατρὸς ἥξειν πρὸς αὐτὸν ἔφησεν ἐκεῖ μόνον ἐπαγόμενος παῖδα."},{"number":233,"text":"καὶ τρία ἀκόντια δὲ βαλὼν ἐπὶ τὸν σκοπὸν κομίσαι τῷ παιδὶ προστάσσω τὰ ἀκόντια· κεῖσθαι γὰρ ἔμπροσθεν αὐτοῦ. καὶ ἂν ταῦτα, φησίν, ἀκούσῃς γίνωσκε μηδὲν εἶναι φαῦλον παρὰ τοῦ πατρός· ἂν δὲ τὰ ἐναντία τούτων ἀκούσῃς μου λέγοντος, καὶ τὰ ἐναντία παρὰ τοῦ βασιλέως προσδόκα."},{"number":234,"text":"τῆς μέντοι γε ἀσφαλείας τεύξῃ παρʼ ἐμοῦ καὶ οὐδὲν μὴ πάθῃς ἄτοπον· ὅπως δὲ μνησθῇς τούτων παρὰ τὸν τῆς εὐπραγίας καιρὸν σκόπει καὶ τοῖς υἱοῖς μου γενοῦ χρήσιμος. Δαυίδης μὲν οὖν ταύτας λαβὼν παρὰ Ἰωνάθου τὰς πίστεις εἰς τὸ συγκείμενον ἀπηλλάγη χωρίον."},{"number":235,"text":"Τῇ δʼ ἐχομένῃ, νεομηνία δʼ ἦν, ἁγνεύσας ὡς ἔθος εἶχεν ὁ βασιλεὺς ἧκεν ἐπὶ τὸ δεῖπνον, καὶ παρακαθεσθέντων αὐτῷ τοῦ μὲν παιδὸς Ἰωνάθου ἐκ δεξιῶν Ἀβενήρου δὲ τοῦ ἀρχιστρατήγου ἐκ τῶν ἑτέρων, ἰδὼν τὴν τοῦ Δαβίδου καθέδραν κενὴν ἡσύχασεν ὑπονοήσας οὐ καθαρεύσαντα αὐτὸν ἀπὸ συνουσίας ὑστερεῖν."},{"number":236,"text":"ὡς δὲ καὶ τῇ δευτέρᾳ τῆς νουμηνίας οὐ παρῆν ἐπυνθάνετο παρὰ τοῦ παιδὸς Ἰωνάθου, ὅτι καὶ τῇ παρελθούσῃ καὶ ταύτῃ τοῦ δείπνου καὶ τῆς ἑστιάσεως ὁ τοῦ Ἰεσσαίου παῖς ἀπολέλειπται. ὁ δὲ πεπορεῦσθαι κατὰ τὰς συνθήκας ἔφησεν αὐτὸν εἰς τὴν ἑαυτοῦ πατρίδα τῆς φυλῆς ἑορτὴν ἀγούσης ἐπιτρέψαντος αὐτοῦ· παρακαλέσαι μέντοι καὶ αὐτὸν ἐλθεῖν ἐπὶ τὴν θυσίαν καὶ εἰ συγχωρηθείη φησὶν ἀπέρχεσθαι· τὴν γὰρ εὔνοιάν μου τὴν πρὸς αὐτὸν ἐπίστασαι."},{"number":237,"text":"τότε τὴν πρὸς Δαυίδην τοῦ πατρὸς Ἰωνάθης ἐπέγνω δυσμένειαν καὶ τρανῶς τὴν ὅλην αὐτοῦ βούλησιν εἶδεν· οὐ γὰρ κατέσχε Σαοῦλος τῆς ὀργῆς, ἀλλὰ βλασφημῶν ἐξ αὐτομόλων γεγενημένον καὶ πολέμιον ἀπεκάλει καὶ κοινωνὸν τοῦ Δαυίδου καὶ συνεργὸν ἔλεγεν καὶ μήτʼ αὐτὸν αἰδεῖσθαι μήτε τὴν μητέρα αὐτοῦ ταῦτα φρονοῦντα καὶ μηδὲ βουλόμενον πεισθῆναι τοῦθʼ, ὅτι μέχρις οὗ περίεστι Δαυίδης ἐπισφαλῶς αὐτοῖς τὰ τῆς βασιλείας ἔχει. μετάπεμψαι τοιγαροῦν αὐτόν, ἔφησεν, ἵνα δῷ δίκην."},{"number":238,"text":"ὑποτυχόντος δʼ Ἰωνάθου, τί δʼ ἀδικοῦντα κολάσαι θέλεις; οὐκέτʼ εἰς λόγους καὶ βλασφημίας τὴν ὀργὴν ὁ Σαοῦλος ἐξήνεγκεν, ἀλλὰ ἁρπάσας τὸ δόρυ ἀνεπήδησεν ἐπʼ αὐτὸν ἀποκτεῖναι θέλων. καὶ τὸ μὲν ἔργον οὐκ ἔδρασε διακωλυθεὶς ὑπὸ τῶν φίλων, φανερὸς δʼ ἐγένετο τῷ παιδὶ μισῶν τὸν Δαυίδην καὶ διαχρήσασθαι ποθῶν, ὡς παρὰ μικρὸν διʼ ἐκεῖνον αὐτόχειρ καὶ τοῦ παιδὸς γεγονέναι."},{"number":239,"text":"Καὶ τότε μὲν ὁ τοῦ βασιλέως παῖς ἐκπηδήσας ἀπὸ τοῦ δείπνου καὶ μηδὲν ὑπὸ λύπης προσενέγκασθαι δυνηθείς, κλαίων αὑτὸν μὲν τοῦ παρὰ μικρὸν ἀπολέσθαι τοῦ κατακεκρίσθαι δʼ ἀποθανεῖν Δαυίδην διενυκτέρευσεν. ἅμα δὲ ἡμέρᾳ πρὸ τῆς πόλεως εἰς τὸ πεδίον ὡς γυμνασόμενος μὲν δηλώσων δὲ τῷ φίλῳ τὴν τοῦ πατρὸς διάθεσιν, ὡς συνέθετο, πρόεισι."},{"number":240,"text":"ποιήσας δὲ ὁ Ἰωνάθης τὰ συγκείμενα τὸν μὲν ἑπόμενον ἀπολύει εἰς τὴν πόλιν παῖδα, ἦν δʼ ἠρεμία τῷ Δαυίδῃ παρελθεῖν εἰς ὄψιν αὐτῷ καὶ λόγους. ἀναφανεὶς δʼ οὗτος πίπτει πρὸ τῶν Ἰωνάθου ποδῶν καὶ προσκυνῶν σωτῆρα αὐτοῦ τῆς ψυχῆς ἀπεκάλει."},{"number":241,"text":"ἀνίστησι δʼ ἀπὸ τῆς γῆς αὐτόν, καὶ περιπλακέντες ἀλλήλους μακρά τε ἠσπάζοντο καὶ δεδακρυμένα τήν τε ἡλικίαν ἀποθρηνοῦντες αὑτῶν καὶ τὴν ἐφθονημένην ἑταιρίαν καὶ τὸν μέλλοντα διαχωρισμόν, ὃς οὐδὲν αὐτοῖς ἐδόκει θανάτου διαφέρειν. μόλις δʼ ἐκ τῶν θρήνων ἀνανήψαντες καὶ μεμνῆσθαι τῶν ὅρκων ἀλλήλοις παρακελευσάμενοι διελύθησαν."}],"12":[{"number":242,"text":"Δαυίδης δὲ φεύγων τὸν βασιλέα καὶ τὸν ἐξ αὐτοῦ θάνατον εἰς Ναβὰν παραγίνεται πόλιν πρὸς Ἀβιμέλεχον τὸν ἀρχιερέα, ὃς ἐπὶ τῷ μόνον ἥκοντα ἰδεῖν καὶ μήτε φίλον σὺν αὐτῷ μήτʼ οἰκέτην παρόντα ἐθαύμασε καὶ τὴν αἰτίαν τοῦ μηδένα εἶναι σὺν αὐτῷ μαθεῖν ἤθελεν."},{"number":243,"text":"ὁ δὲ πρᾶξιν ἀπόρρητον ἐπιταγῆναι παρὰ τοῦ βασιλέως ἔφησεν, εἰς ἣν συνοδίας αὐτῷ βουλομένῳ λαθεῖν οὐκ ἔδει· τοὺς μέντοι θεράποντας εἰς τόνδε μοι τὸν τόπον ἀπαντᾶν προσέταξα. ἠξίου δὲ λαβεῖν ἐφόδια· φίλου γὰρ αὐτὸν ποιήσειν ἔργον παρασχόντα καὶ πρὸς τὸ προκείμενον συλλαμβανομένου."},{"number":244,"text":"τυχὼν δὲ τούτων ᾔτει καὶ ὅπλον τι μετὰ χεῖρας ῥομφαίαν ἢ δοράτιον· παρῆν δὲ καὶ Σαούλου δοῦλος γένει μὲν Σύρος Δώηγος δὲ ὄνομα τὰς τοῦ βασιλέως ἡμιόνους νέμων· ὁ δʼ ἀρχιερεὺς ἔχειν μὲν αὐτὸς οὐδέν τι εἶπε τοιοῦτον, εἶναι δὲ τὴν Γολιάθου ῥομφαίαν, ἣν ἀποκτείνας τὸν Παλαιστῖνον αὐτὸς ἀναθείη τῷ θεῷ."},{"number":245,"text":"λαβὼν δὲ ταύτην ὁ Δαβίδης ἔξω τῆς τῶν Ἑβραίων χώρας εἰς Γίτταν διέφυγε τὴν Παλαιστίνων, ἧς Ἄγχους ἐβασίλευεν. ἐπιγνωσθεὶς δὲ ὑπὸ τῶν τοῦ βασιλέως οἰκετῶν καὶ φανερὸς αὐτῷ γενόμενος μηνυόντων ἐκείνων, ὅτι Δαυίδης ὁ πολλὰς ἀποκτείνας Παλαιστίνων μυριάδας εἴη, δείσας μὴ πρὸς αὐτοῦ θάνῃ καὶ τὸν κίνδυνον ὃν ἐξέφυγε παρὰ Σαούλου παρʼ ἐκείνου πειράσῃ προσποιεῖται μανίαν καὶ λύσσαν, ὡς ἀφρὸν κατὰ τοῦ στόματος αὐτοῦ φερόμενον καὶ τὰ ἄλλα ὅσα συνίστησι μανίαν πίστιν παρὰ τῷ Γίττης βασιλεῖ γενέσθαι τῆς νόσου."},{"number":246,"text":"καὶ τοῖς οἰκέταις ὁ βασιλεὺς προσδυσχεράνας ὡς ἔκφρονα πρὸς αὐτὸν ἀγάγοιεν ἄνθρωπον ἐκέλευσε τὸν Δαυίδην ὡς τάχος ἐκβάλλειν."},{"number":247,"text":"Διασωθεὶς δὲ οὗτος ἐκ τῆς Γίττης εἰς τὴν Ἰούδα παραγίνεται φυλὴν καὶ ἐν τῷ πρὸς Ἀδολλάμῃ πόλει σπηλαίῳ διατρίβων πέμπει πρὸς τοὺς ἀδελφοὺς δηλῶν αὐτοῖς ἔνθα εἴη. οἱ δὲ μετὰ πάσης συγγενείας ἧκον πρὸς αὐτόν· καὶ τῶν ἄλλων δὲ ὅσοις ἢ χρεία ἦν ἢ φόβος ἐκ Σαούλου τοῦ βασιλέως συνερρύησαν πρὸς αὐτὸν καὶ ποιεῖν τὰ ἐκείνῳ δοκοῦντα ἑτοίμως ἔχειν ἔλεγον. ἐγένοντο δὲ οἱ πάντες ὡσεὶ τετρακόσιοι."},{"number":248,"text":"θαρρήσας δὲ ὡς καὶ χειρὸς αὐτῷ καὶ συνεργίας ἤδη γεγενημένης ἀπάρας ἐκεῖθεν ἀφικνεῖται πρὸς τὸν τῶν Μωαβιτῶν βασιλέα, καὶ τοὺς γονεῖς αὐτοῦ εἰς τὴν ἑαυτοῦ χώραν προσδεξάμενον ἕως οὗ ἐπὶ τὸ καθʼ αὑτὸν τέλος ἔχειν παρεκάλει· κατανεύσαντος δʼ αὐτοῦ τὴν χάριν καὶ πάσης τοὺς γονεῖς τοῦ Δαυίδου τιμὴς παρʼ ὃν ἐτύγχανον παρʼ αὐτῷ χρόνον"},{"number":249,"text":"ἀξιώσαντος αὐτὸς τοῦ προφήτου κελεύσαντος αὐτὸν τὴν μὲν ἐρημίαν ἐκλιπεῖν, πορευθέντα δʼ εἰς τὴν κληρουχίαν τῆς Ἰούδα φυλῆς ἐν αὐτῇ διάγειν πείθεται καὶ παραγενόμενος εἰς Σάριν πόλιν ἐν αὐτῇ κατέμενε."},{"number":250,"text":"Σαοῦλος δʼ ἀκούσας ὅτι μετὰ πλήθους ὀφθείη ὁ Δαυίδης οὐκ εἰς τυχόντα θόρυβον καὶ ταραχὴν ἐνέπεσεν, ἀλλʼ εἰδὼς τὸ φρόνημα τοῦ ἀνδρὸς καὶ τὴν εὐτολμίαν οὐδὲν ἐξ αὐτοῦ μικρὸν ἀνακύψειν ἔργον ἐφʼ οὗ κλαύσεσθαι πάντως καὶ πονήσειν ὑπενόησε."},{"number":251,"text":"καὶ συγκαλέσας τοὺς φίλους καὶ τοὺς ἡγεμόνας καὶ τὴν φυλὴν ἐξ ἧς αὐτὸς ἦν πρὸς αὑτὸν ἐπὶ τὸν βουνὸν οὗ τὸ βασίλειον εἶχε, καὶ καθίσας ἐπʼ Ἀρούρης, τόπος ἦν τις τιμῆς, πολιτικῆς περὶ αὐτὸν οὔσης τάξεως σωματοφυλάκων λέγει πρὸς αὐτούς· ἄνδρες ὁμόφυλοι, μέμνησθε μὲν οἶδʼ ὅτι τῶν ἐμῶν εὐεργεσιῶν, ὅτι καὶ ἀγρῶν τινας ἐποίησα δεσπότας καὶ τιμῶν τῶν ἐν τῷ πλήθει καὶ τάξεων ἠξίωσα."},{"number":252,"text":"πυνθάνομαι τοιγαροῦν, εἰ μείζονας τούτων δωρεὰς καὶ πλείονας παρὰ τοῦ Ἰεσσαίου παιδὸς προσδοκᾶτε· οἶδα γὰρ ὅτι πάντες ἐκείνῳ προστέθεισθε τοὐμοῦ παιδὸς Ἰωνάθου αὐτοῦ τε οὕτως φρονήσαντος καὶ ὑμᾶς ταῦτα πείσαντος·"},{"number":253,"text":"οὐ γὰρ ἀγνοῶ τοὺς ὅρκους καὶ τὰς συνθήκας τὰς πρὸς Δαυίδην αὐτῷ γεγενημένας, οὐδʼ ὅτι σύμβουλος μὲν καὶ συνεργὸς Ἰωνάθης ἐστὶ τῶν κατʼ ἐμοῦ συντεταγμένων, μέλει δὲ ὑμῶν οὐδενὶ περὶ τούτων,"},{"number":254,"text":"ἀλλὰ τὸ ἀποβησόμενον ἡσυχάζοντες σκοπεῖτε. σιωπήσαντος δὲ τοῦ βασιλέως ἄλλος μὲν οὐδεὶς ἀπεκρίνατο τῶν παρόντων, Δώηγος δʼ ὁ Σύρος ὁ τὰς ἡμιόνους αὐτοῦ βόσκων εἶπεν, ὡς ἴδοι τὸν Δαυίδην εἰς Ναβὰν πόλιν πρὸς Ἀβιμέλεχον ἐλθόντα τὸν ἀρχιερέα τά τε μέλλοντα παρʼ αὐτοῦ προφητεύσαντος μαθεῖν καὶ λαβόντα ἐφόδια καὶ τὴν ῥομφαίαν τοῦ Γολιάθου πρὸς οὓς ἐβούλετο μετὰ ἀσφαλείας προπεμφθῆναι."},{"number":255,"text":"Μεταπεμψάμενος οὖν τὸν ἀρχιερέα καὶ πᾶσαν αὐτοῦ τὴν γενεὰν Σαοῦλος τί παθὼν ἐξ ἐμοῦ, εἶπε, δεινὸν καὶ ἄχαρι τὸν Ἰεσσαίου παῖδα προσεδέξω καὶ σιτίων μὲν αὐτῷ μετέδωκας καὶ ὅπλων ὄντι τῆς ἐμῆς βασιλείας ἐπιβούλῳ, τί δὲ δὴ περὶ τῶν μελλόντων ἐχρημάτιζες; οὐ γὰρ δή σε φεύγων ἐμὲ καὶ μισῶν τὸν ἐμὸν οἶκον ἐλάνθανεν."},{"number":256,"text":"ὁ δʼ ἀρχιερεὺς οὐκ ἐπʼ ἄρνησιν ἐτράπη τῶν γεγονότων, ἀλλὰ μετὰ παρρησίας ταῦτα παρασχεῖν ὡμολόγει οὐχὶ Δαυίδῃ χαριζόμενος, ἀλλʼ αὐτῷ· πολέμιον γὰρ σὸν οὐκ εἰδέναι ἔφασκε, πιστὸν δὲ ἐν τοῖς μάλιστα δοῦλον καὶ χιλίαρχον καὶ τὸ τούτων μεῖζον γαμβρόν τε ἤδη καὶ συγγενῆ."},{"number":257,"text":"ταῦτα δʼ οὐκ ἐχθροῖς παρέχειν τοὺς ἀνθρώπους, ἀλλὰ τοῖς εὐνοίᾳ καὶ τιμῇ τῇ πρὸς αὐτοὺς ἀρίστοις. προφητεῦσαι δὲ οὐ νῦν πρῶτον αὐτῷ, πολλάκις δὲ καὶ ἄλλοτε τοῦτο πεποιηκέναι· φήσαντι δὲ ὑπὸ σοῦ πεμφθῆναι κατὰ πολλὴν σπουδὴν ἐπὶ πρᾶξιν τῷ μηδὲν παρασχεῖν ὧν ἐπεζήτει σοὶ μᾶλλον ἀντιλέγειν ἢ ἐκείνῳ περὶ αὐτῶν ἐλογιζόμην."},{"number":258,"text":"διὸ μηδὲν πονηρὸν κατʼ ἐμοῦ φρονήσῃς μηδὲ πρὸς ἃ νῦν ἀκούεις Δαυίδην ἐγχειρεῖν πρὸς ταῦτα τὴν τότε μου δοκοῦσαν φιλανθρωπίαν ὑποπτεύσῃς· φίλῳ γὰρ καὶ γαμβρῷ σῷ καὶ χιλιάρχῳ παρέσχον, οὐ πολεμίῳ."},{"number":259,"text":"Ταῦτα λέγων ὁ ἀρχιερεὺς οὐκ ἔπεισε τὸν Σαοῦλον· δεινὸς γὰρ ὁ φόβος μηδʼ ἀληθεῖ πιστεύειν ἀπολογίᾳ· κελεύει δὲ τοῖς ὁπλίταις περιστᾶσιν αὐτὸν ἀποκτεῖναι. μὴ θαρρούντων δʼ ἐκείνων ἅψασθαι τοῦ ἀρχιερέως, ἀλλὰ τὸ θεῖον εὐλαβουμένων μᾶλλον ἢ τὸ παρακοῦσαι τοῦ βασιλέως, τῷ Σύρῳ Δωήγῳ προστάσσει τὸν φόνον."},{"number":260,"text":"καὶ παραλαβὼν ὁμοίους αὑτῷ πονηροὺς ἐκεῖνος ἀποκτείνει τὸν Ἀβιμέλεχον καὶ τὴν γενεὰν αὐτοῦ· ἦσαν δὲ πάντες ὡσεὶ πέντε καὶ τριακόσιοι. πέμψας δὲ Σαοῦλος καὶ εἰς τὴν πόλιν τῶν ἱερέων Ναβὰν πάντας τε αὐτοὺς ἀπέκτεινεν οὐ γυναικῶν οὐ νηπίων οὐδʼ ἄλλης ἡλικίας φεισάμενος, αὐτὴν δὲ ἐνέπρησε."},{"number":261,"text":"διασώζεται δὲ παῖς εἷς Ἀβιμελέχου Ἀβιάθαρος ὄνομα. ταῦτα μέντοι συνέβη, καθὼς προεφήτευσεν ὁ θεὸς τῷ ἀρχιερεῖ Ἠλὶ διὰ τὰς τῶν υἱῶν αὐτοῦ δύο παρανομίας εἰπὼν διαφθαρήσεσθαι τοὺς ἐγγόνους."},{"number":262,"text":"Σαοῦλος δὲ ὁ βασιλεὺς ὠμὸν οὕτως ἔργον διαπραξάμενος καὶ γενεὰν ὅλην ἀρχιερατικῆς ἀποσφάξας τιμῆς καὶ μήτʼ ἐπὶ νηπίοις λαβὼν οἶκτον μήτʼ ἐπὶ γέρουσιν αἰδῶ, καταβαλὼν δὲ καὶ τὴν πόλιν, ἣν πατρίδα καὶ τροφὸν τῶν ἱερέων καὶ προφητῶν αὐτόθι τὸ θεῖον ἐπελέξατο καὶ μόνην εἰς τὸ τοιούτους φέρειν ἄνδρας ἀπέδειξε, μαθεῖν ἅπασι παρέσχε καὶ κατανοῆσαι τὸν ἀνθρώπινον τρόπον,"},{"number":263,"text":"ὅτι μέχρις οὗ μέν εἰσιν ἰδιῶταί τινες καὶ ταπεινοὶ τῷ μὴ δύνασθαι χρῆσθαι τῇ φύσει μηδὲ τολμᾶν ὅσα θέλουσιν ἐπιεικεῖς εἰσι καὶ μέτριοι καὶ μόνον διώκουσι τὸ δίκαιον, καὶ πρὸς αὐτῷ τὴν πᾶσαν εὔνοιάν τε καὶ σπουδὴν ἔχουσι τότε, καὶ περὶ τοῦ θείου πεπιστεύκασιν, ὅτι πᾶσι τοῖς γινομένοις ἐν τῷ βίῳ πάρεστι καὶ οὐ τὰ ἔργα μόνον ὁρᾷ τὰ πραττόμενα, ἀλλὰ καὶ τὰς διανοίας ἤδη σαφῶς οἶδεν, ἀφʼ ὧν μέλλει ταῦτα ἔσεσθαι·"},{"number":264,"text":"ὅταν δὲ εἰς ἐξουσίαν παρέλθωσι καὶ δυναστείαν, τότε πάντʼ ἐκεῖνα μετεκδυσάμενοι καὶ ὥσπερ ἐπὶ σκηνῆς προσωπεῖα τὰ ἤθη καὶ τοὺς τρόπους ἀποθέμενοι μεταλαμβάνουσι τόλμαν ἀπόνοιαν καταφρόνησιν ἀνθρωπίνων τε καὶ θείων,"},{"number":265,"text":"καὶ ὅτε μάλιστα δεῖ τῆς εὐσεβείας αὐτοῖς καὶ τῆς δικαιοσύνης ἔγγιστα τοῦ φθονεῖσθαι γεγενημένοις καὶ πᾶσι φανεροῖς ἐφʼ οἷς ἂν νοήσωσιν ἢ πράξωσι καθεστῶσι, τόθʼ ὡς οὐκέτι βλέποντος αὐτοὺς τοῦ θεοῦ ἢ διὰ τὴν ἐξουσίαν δεδιότος οὕτως ἐμπαροινοῦσι τοῖς πράγμασιν."},{"number":266,"text":"ἃ δʼ ἂν ἢ φοβηθῶσιν ἀκούσαντες ἢ μισῶσι θελήσαντες ἢ στέρξωσιν ἀλόγως, ταῦτα κύρια καὶ βέβαια καὶ ἀληθῆ καὶ ἀνθρώποις ἀρεστὰ καὶ τῷ θεῷ δοκοῦσι, τῶν δὲ μελλόντων λόγος αὐτοῖς οὐδὲ εἷς·"},{"number":267,"text":"ἀλλὰ τιμῶσι μὲν τοὺς πολλὰ ταλαιπωρήσαντας, τιμήσαντες δὲ φθονοῦσι, καὶ παραγαγόντες εἰς ἐπιφάνειαν οὐ ταύτης ἀφαιροῦνται μόνον τοὺς τετυχηκότας, ἀλλὰ διὰ ταύτην καὶ τοῦ ζῆν ἐπὶ πονηραῖς αἰτίαις καὶ διʼ ὑπερβολὴν αὐτῶν ἀπιθάνοις· κολάζουσι δʼ οὐκ ἐπʼ ἔργοις δίκης ἀξίοις, ἀλλʼ ἐπὶ διαβολαῖς καὶ κατηγορίαις ἀβασανίστοις, οὐδʼ ὅσους ἔδει τοῦτο παθεῖν, ἀλλʼ ὅσους ἀποκτεῖναι δύνανται."},{"number":268,"text":"τοῦτο Σαοῦλος ἡμῖν ὁ Κείσου παῖς, ὁ πρῶτος μετὰ τὴν ἀριστοκρατίαν καὶ τὴν ἐπὶ τοῖς κριταῖς πολιτείαν Ἑβραίων βασιλεύσας, φανερὸν πεποίηκε τριακοσίους ἀποκτείνας ἱερέας καὶ προφήτας ἐκ τῆς πρὸς Ἀβιμέλεχον ὑποψίας, ἐπικαταβαλὼν δὲ αὐτοῖς καὶ τὴν πόλιν καὶ τὸν ἐν τρόπῳ τινὶ ναὸν σπουδάσας ἱερέων καὶ προφητῶν ἔρημον καταστῆσαι τοσούτους μὲν ἀνελών, μεῖναι δʼ ἐάσας οὐδὲ τὴν πατρίδα αὐτῶν πρὸς τὸ καὶ μετʼ ἐκείνους ἄλλους γενέσθαι."},{"number":269,"text":"Ὁ δʼ Ἀβιάθαρος ὁ τοῦ Ἀβιμελέχου παῖς ὁ μόνος δυνηθεὶς ἐκ τοῦ γένους τῶν ὑπὸ τοῦ Σαούλου φονευθέντων ἱερέων φυγὼν πρὸς Δαυίδην τὴν τῶν οἰκείων αὐτοῦ συμφορὰν ἐδήλωσε καὶ τὴν τοῦ πατρὸς ἀναίρεσιν."},{"number":270,"text":"ὁ δʼ οὐκ ἀγνοεῖν ἔφη ταῦτα περὶ αὐτοὺς ἐσόμενα ἰδὼν τὸν Δώηγον· ὑπονοῆσαι γὰρ διαβληθήσεσθαι πρὸς αὐτοῦ τὸν ἀρχιερέα τῷ βασιλεῖ, καὶ τῆς ἀτυχίας ταύτης αὐτοῖς αὑτὸν ᾐτιᾶτο. μένειν δʼ αὐτόθι καὶ σὺν αὐτῷ διατρίβειν ὡς οὐκ ἐν ἄλλῳ τόπῳ λησόμενον οὕτως ἠξίου."}],"13":[{"number":271,"text":"Κατὰ δὲ τοῦτον τὸν καιρὸν ἀκούσας ὁ Δαυίδης τοὺς Παλαιστίνους ἐμβεβληκότας εἰς τὴν Κιλλανῶν χώραν καὶ ταύτην διαρπάζοντας δίδωσιν ἑαυτὸν στρατεύειν ἐπʼ αὐτοὺς τοῦ θεοῦ διὰ τοῦ προφήτου πυθόμενος εἰ ἐπιτρέπει νίκην. τοῦ δὲ σημαίνειν φήσαντος ἐξώρμησεν ἐπὶ τοὺς Παλαιστίνους μετὰ τῶν ἑταίρων καὶ φόνον τε αὐτῶν πολὺν ἐξέχεε καὶ λείαν ἤλασεν."},{"number":272,"text":"καὶ παραμείνας τοῖς Κιλλανοῖς ἕως οὗ τὰς ἅλως καὶ τὸν καρπὸν συνεῖλον ἀδεῶς Σαούλῳ τῷ βασιλεῖ μηνύεται παρʼ αὐτοῖς ὤν· τὸ γὰρ ἔργον καὶ τὸ κατόρθωμα οὐκ ἔμεινε παρʼ οἷς ἐγένετο, φήμῃ δʼ ἐπίπαν εἴς τε τὰς τῶν ἄλλων ἀκοὰς καὶ πρὸς τὰς τοῦ βασιλέως διεκομίσθη αὑτό τε συνιστάνον καὶ τὸν πεποιηκότα."},{"number":273,"text":"χαίρει δὲ Σαοῦλος ἀκούσας ἐν Κίλλα τὸν Δαυίδην, καί θεὸς ἤδη χερσὶ ταῖς ἐμαῖς ὑπέθετο αὐτόν, εἰπών, ἐπεὶ καὶ συνηνάγκασεν ἐλθεῖν εἰς πόλιν τείχη καὶ πύλας καὶ μοχλοὺς ἔχουσαν , τῷ λαῷ παντὶ προσέταξεν ἐπὶ τὴν Κίλλαν ἐξορμῆσαι καὶ πολιορκήσαντι καὶ ἑλόντι τὸν Δαυίδην ἀποκτεῖναι."},{"number":274,"text":"ταῦτα δὲ αἰσθόμενος ὁ Δαυίδης καὶ μαθὼν παρὰ τοῦ θεοῦ, ὅτι μείναντα παρʼ αὐτοῖς οἱ Κιλλῖται ἐκδώσουσι τῷ Σαούλῳ, παραλαβὼν τοὺς τετρακοσίους ἀπῆρεν ἀπὸ τῆς πόλεως εἰς τὴν ἔρημον ἐπάνω τῆς Ἐνγεδὼν λεγομένης. καὶ ὁ μὲν βασιλεὺς ἀκούσας αὐτὸν πεφευγότα παρὰ τῶν Κιλλιτῶν ἐπαύσατο τῆς ἐπʼ αὐτὸν στρατείας."},{"number":275,"text":"Δαυίδης δὲ ἐκεῖθεν ἄρας εἴς τινα τόπον Καινὴν καλουμένην τῆς Ζιφήνης παραγίνεται, εἰς ὃν Ἰωνάθης ὁ τοῦ Σαούλου παῖς συμβαλὼν αὐτῷ καὶ κατασπασάμενος θαρρεῖν τε καὶ χρηστὰς περὶ τῶν μελλόντων ἔχειν ἐλπίδας παρεκάλει καὶ μὴ κάμνειν τοῖς παροῦσι· βασιλεύσειν γὰρ αὐτὸν καὶ πᾶσαν τὴν Ἑβραίων δύναμιν ἕξειν ὑφʼ ἑαυτῷ, φιλεῖν δὲ τὰ τοιαῦτα σὺν μεγάλοις ἀπαντᾶν πόνοις."},{"number":276,"text":"πάλιν δʼ ὅρκους ποιησάμενος τῆς εἰς ἅπαντα τὸν βίον πρὸς ἀλλήλους εὐνοίας καὶ πίστεως καὶ τὸν θεὸν μάρτυρα καλέσας, ὧν ἐπηράσατο αὑτῷ παραβάντι τὰ συγκείμενα καὶ μεταβαλλομένῳ πρὸς τἀναντία, τὸν μὲν αὐτόθι καταλείπει μικρὰ τῶν φροντίδων καὶ τοῦ δέους ἐπικουφίσας, αὐτὸς δὲ πρὸς αὑτὸν ἐπανέρχεται."},{"number":277,"text":"οἱ δὲ Ζιφηνοὶ χαριζόμενοι τῷ Σαούλῳ μηνύουσιν αὐτῷ παρʼ αὐτοῖς διατρίβειν τὸν Δαυίδην καὶ παραδώσειν ἔφασαν ἐπʼ αὐτὸν ἐλθόντι· καταληφθέντων γὰρ τῶν τῆς Ζιφηνῆς στενῶν οὐκ εἶναι φυγεῖν αὐτὸν πρὸς ἄλλους."},{"number":278,"text":"ὁ δὲ βασιλεὺς ἐπῄνεσεν αὐτοὺς χάριν ἔχειν ὁμολογήσας τὸν ἐχθρὸν αὐτῷ μεμηνυκόσι, καὶ οὐκ εἰς μακρὰν ἀμείψεσθαι τῆς εὐνοίας ὑποσχόμενος αὐτοὺς ἔπεμψε τοὺς ζητήσοντας τὸν Δαυίδην καὶ τὴν ἐρημίαν ἐξερευνήσοντας, αὐτὸς δʼ ἀκολουθήσειν ἀπεκρίνατο."},{"number":279,"text":"καὶ οἱ μὲν ἐπὶ τὴν θήραν καὶ τὴν σύλληψιν τοῦ Δαυίδου προῆγον τὸν βασιλέα σπουδάζοντες μὴ μόνον αὐτῷ μηνῦσαι τὸν ἐχθρὸν αὐτῷ τὴν εὔνοιαν, ἀλλὰ καὶ τῷ παρασχεῖν αὐτὸν εἰς ἐξουσίαν φανερωτέραν καταστῆσαι· διήμαρτον δὲ τῆς ἀδίκου καὶ πονηρᾶς ἐπιθυμίας, οἳ μηδὲν κινδυνεύειν ἔμελλον ἐκ τοῦ μὴ ταῦτʼ ἐμφανίσαι τῷ Σαούλῳ,"},{"number":280,"text":"διὰ δὲ κολακείαν καὶ κέρδους προσδοκίαν παρὰ τοῦ βασιλέως ἄνδρα θεοφιλῆ καὶ παρὰ δίκην ζητούμενον ἐπὶ θανάτῳ καὶ λανθάνειν δυνάμενον διέβαλλον καὶ παραδώσειν ὑπέσχοντο· γνοὺς γὰρ ὁ Δαυίδης τὴν τῶν Ζιφηνῶν κακοήθειαν καὶ τὴν τοῦ βασιλέως ἔφοδον ἐκλείπει μὲν τὰ στενὰ τῆς ἐκείνων χώρας, φεύγει δὲ ἐπὶ τὴν μεγάλην πέτραν τὴν οὖσαν ἐν τῇ Σίμωνος ἐρήμῳ."},{"number":281,"text":"Ὥρμησεν δὲ ἐπʼ ἐκείνην διώκειν Σαοῦλος· κατὰ γὰρ τὴν ὁδὸν ἀναχωρήσαντα ἐκ τῶν στενῶν μαθὼν τὸν Δαυίδην ἐπὶ τὸ ἕτερον μέρος τῆς πέτρας ἀπῆρεν. ἀντιπεριέσπασαν δὲ τὸν Σαοῦλον ἀπὸ τῆς διώξεως τοῦ Δαυίδου μέλλοντος ἤδη συλλαμβάνεσθαι Παλαιστῖνοι πάλιν ἐπὶ τὴν Ἑβραίων ἐστρατευκέναι χάραν ἀκουσθέντες· ἐπὶ γὰρ τούτους ἀνέστρεψε φύσει πολεμίους ὄντας αὐτοὺς ἀμύνασθαι κρίνας ἀναγκαιότερον, ἢ τὸν ἴδιον σπουδάζοντα λαβεῖν ἐχθρὸν ὑπεριδεῖν τὴν γῆν κακωθεῖσαν."},{"number":282,"text":"Καὶ Δαυίδης μὲν οὕτως ἐκ παραλόγου τὸν κίνδυνον διαφυγὼν εἰς τὰ στενὰ τῆς Ἐνγεδηνῆς ἀφικνεῖται· Σαούλῳ δὲ ἐκβαλόντι τοὺς Παλαιστίνους ἧκον ἀπαγγέλλοντές τινες τὸν Δαυίδην ἐν τοῖς Ἐγγεδηνῆς διατρίβειν ὅροις."},{"number":283,"text":"λαβὼν δὲ τρισχιλίους ἐπιλέκτους ὁπλίτας ἐπʼ αὐτὸν ἠπείγετο, καὶ γενόμενος οὐ πόρρω τῶν τόπων ὁρᾷ παρὰ τὴν ὁδὸν σπήλαιον βαθὺ καὶ κοῖλον εἰς πολὺ καὶ μῆκος ἀνεῳγὸς καὶ πλάτος, ἔνθα συνέβαινε τὸν Δαυίδην μετὰ τῶν τετρακοσίων κεκρύφθαι· ἐπειγόμενος οὖν ὑπὸ τῶν κατὰ φύσιν εἴσεισιν εἰς αὐτὸ μόνος θεαθεὶς ὑπό τινος τῶν μετὰ Δαυίδου·"},{"number":284,"text":"καὶ φράσαντος τοῦ θεασαμένου πρὸς τὸν ἐχθρὸν αὐτοῦ παρὰ τοῦ θεοῦ καιρὸν ἔχειν ἀμύνης καὶ συμβουλεύοντος τοῦ Σαούλου ἀποτεμεῖν τὴν κεφαλὴν καὶ τῆς πολλῆς ἄλης αὑτὸν ἀπαλλάξαι καὶ ταλαιπωρίας, ἀναστὰς ἀναίρει μὲν τὴν κροκύδα τοῦ ἱματίου μόνον οὗ Σαοῦλος ἀμπείχετο, μετανοήσας δʼ εὐθύς οὐ δίκαιον, εἶπε, φονεύειν τὸν αὑτοῦ δεσπότην, οὐδὲ τὸν ὑπὸ τοῦ θεοῦ βασιλείας ἀξιωθέντα· καὶ γὰρ εἰ πονηρὸς οὗτος εἰς ἡμᾶς, ἀλλʼ οὐκ ἐμὲ δεῖ τοιοῦτον εἶναι πρὸς αὐτόν."},{"number":285,"text":"τοῦ δὲ Σαούλου τὸ σπήλαιον ἐκλιπόντος προελθὼν ὁ Δαυίδης ἔκραγεν ἀκοῦσαι τὸν Σαοῦλον ἀξιῶν. ἐπιστραφέντος δὲ τοῦ βασιλέως προσκυνεῖ τε αὐτὸν πεσὼν ἐπὶ πρόσωπον, ὡς ἔθος, καί φησιν· οὐ πονηροῖς, ὦ βασιλεῦ, καὶ ψευδεῖς πλάττουσι διαβολὰς παρέχοντα δεῖ τὰς ἀκοὰς χαρίζεσθαι μὲν ἐκείνοις τὸ πιστεύειν αὐτοῖς, εἰς δὲ τοὺς φιλτάτους ὑπονοίας ἔχειν, ἀλλὰ τοῖς ἔργοις σκοπεῖν τὴν ἁπάντων διάθεσιν."},{"number":286,"text":"διαβολὴ μὲν γὰρ ἀπατᾷ, σαφὴς δʼ ἀπόδειξις εὐνοίας τὰ πραττόμενα· καὶ λόγος μὲν ἐπʼ ἀμφότερα πέφυκεν ἀληθής τε καὶ ψευδής, τὰ δὲ ἔργα γυμνὴν ὑπʼ ὄψει τὴν διάνοιαν τίθησιν."},{"number":287,"text":"ἴσθι τοίνυν ἐκ τούτων καλῶς ἔχειν με πρὸς σὲ καὶ τὸν σὸν οἶκον ἐμοὶ πιστεῦσαι δεῖ, καὶ μὴ τοῖς κατηγοροῦσιν ἃ μήτε εἰς νοῦν ἐβαλόμην μήτε δύναται γενέσθαι προσθέμενον μεταδιώκειν τὴν ἐμὴν ψυχὴν καὶ μηδὲν μήθʼ ἡμέρας μήτε νυκτὸς ἔχειν διὰ φροντίδος ἢ τὴν ἐμὴν ἀναίρεσιν, ἣν ἀδίκως μεταπορεύῃ·"},{"number":288,"text":"πῶς γὰρ οὐχὶ ψευδῆ περὶ ἐμοῦ δόξαν εἴληφας ὡς ἀποκτεῖναί σε θέλοντος; ἢ πῶς οὐκ ἀσεβεῖς εἰς τὸν θεὸν ἄνθρωπον τήμερον αὑτῷ τιμωρῆσαι δυνάμενον καὶ παρὰ σοῦ λαβεῖν δίκην καὶ μὴ θελήσαντα μηδὲ τῷ καιρῷ χρησάμενον, ὃν εἰ σοὶ κατʼ ἐμοῦ περιέπεσεν οὐκ ἂν αὐτὸς παρῆκας, διαχρήσασθαι ποθῶν καὶ νομίζων πολέμιον;"},{"number":289,"text":"ὅτε γάρ σου τὴν πτέρυγα τοῦ ἱματίου ἀπέτεμον, τότε σου καὶ τὴν κεφαλὴν ἠδυνάμην. ἐπιδείξας δὲ τὸ ῥάκος ἰδεῖν πιστεύειν παρεῖχεν. ἀλλʼ ἐγὼ μὲν ἀπεσχόμην δικαίας ἀμύνης, φησί, σὺ δὲ μῖσος ἄδικον οὐκ αἰδῇ κατʼ ἐμοῦ τρέφων. ὁ θεὸς ταῦτα δικάσειε καὶ τὸν ἑκατέρου τρόπον ἡμῶν ἐλέγξειε."},{"number":290,"text":"Σαοῦλος δὲ ἐπὶ τῷ παραδόξῳ τῆς σωτηρίας θαυμάσας καὶ τὴν τοῦ νεανίσκου μετριότητα καὶ φύσιν ἐκπλαγεὶς ἀνῴμωξε· τὸ δʼ αὐτὸ κἀκείνου ποιήσαντος αὐτὸν εἶναι δίκαιον στένειν ἀπεκρίνατο· σὺ μὲν γάρ, φησίν, ἀγαθῶν αἴτιος ἐμοὶ γέγονας, ἐγὼ δὲ σοὶ συμφορῶν. ἐπεδείξω δὲ σήμερον τὴν ἀρχαίων ἔχοντα σαυτὸν δικαιοσύνην, οἳ τοὺς ἐχθροὺς ἐν ἐρημίᾳ λαβόντες σώζειν παρήγγελλον."},{"number":291,"text":"πέπεισμαι δὴ νῦν, ὅτι σοὶ τὴν βασιλείαν ὁ θεὸς φυλάττει καὶ περιμένει σε τὸ πάντων τῶν Ἑβραίων κράτος. δὸς δέ μοι πίστεις ἐνόρκους μή μου τὸ γένος ἐξαφανίσαι μηδʼ ἐμοὶ μνησικακοῦντα τοὺς ἐμοὺς ἐγγόνους ἀπολέσαι, τηρῆσαι δέ μοι καὶ σῶσαι τὸν οἶκον. ὀμόσας δὲ καθὼς ἠξίωκε Δαυίδης Σαοῦλον μὲν εἰς τὴν ἰδίαν ἀπέλυσε βασιλείαν, αὐτὸς δὲ μετὰ τῶν σὺν αὐτῷ εἰς τὴν Μασθηρῶν ἀνέβη στενήν."},{"number":292,"text":"Ἀποθνήσκει δὲ κατὰ τοῦτον τὸν καιρὸν καὶ Σαμουῆλος ὁ προφήτης, ἀνὴρ οὐ τῆς τυχούσης ἀπολαύων παρὰ τοῖς Ἑβραίοις τιμῆς· ἐνεφάνισε γὰρ τὴν ἀρετὴν αὐτοῦ καὶ τὴν τοῦ πλήθους πρὸς αὐτὸν εὔνοιαν τὸ πένθος, ὃ ἐπὶ πολὺν χρόνον ὁ λαὸς ἤγετο, καὶ ἡ περὶ τὴν ταφὴν αὐτοῦ καὶ τὴν τῶν νομιζομένων ἀναπλήρωσιν φιλοτιμία τε καὶ σπουδή."},{"number":293,"text":"θάπτουσι γὰρ αὐτὸν ἐν τῇ πατρίδι Ἀρμεθᾶ καὶ ἐπὶ πολλὰς πάνυ ἡμέρας ἔκλαυσαν, οὐ κοινὸν τοῦτο πάσχοντες ὡς ἐπʼ ἀλλοτρίου τελευτῇ, ὡς οἰκεῖον δʼ ἕκαστος ἴδιον ποθῶν."},{"number":294,"text":"ἐγένετο δʼ ἀνὴρ δίκαιος καὶ χρηστὸς τὴν φύσιν καὶ διὰ τοῦτο μάλιστα φίλος τῷ θεῷ. ἦρξε δὲ καὶ προέστη τοῦ λαοῦ μετὰ τὴν Ἠλεὶ τοῦ ἀρχιερέως τελευτὴν μόνος μὲν ἔτη δώδεκα, μετὰ δὲ Σαούλου τοῦ βασιλέως δέκα πρὸς τοῖς ὀκτώ. καὶ τὰ μὲν περὶ Σαμουῆλον οὕτω πέρας ἔσχεν."},{"number":295,"text":"Ἦν δέ τις τῶν Ζιφηνῶν ἐκ πόλεως Ἐμμᾶν πλούσιος καὶ πολυθρέμματος· τρισχιλίων μὲν γὰρ αὐτῷ ποίμνη προβάτων ἐνέμετο, χιλίων δʼ αἰγῶν. ταῦτα Δαυίδης ἀσινῆ τηρεῖν τε καὶ ἀβλαβῆ παρήγγελλε τοῖς σὺν αὐτῷ καὶ μήτε ὑπὸ ἐπιθυμίας μήτε ὑπὸ ἐνδείας μήτε ὑπὸ τῆς ἐρημίας καὶ τοῦ δύνασθαι λανθάνειν καταβλάπτειν, τούτων δʼ ἁπάντων ἐπάνω τίθεσθαι τὸ μηδένʼ ἀδικεῖν καὶ τὸ τῶν ἀλλοτρίων ἅπτεσθαι δεινὸν ἡγεῖσθαι καὶ πρόσαντες τῷ θεῷ."},{"number":296,"text":"ταῦτα δʼ ἐδίδασκεν αὐτοὺς οἰόμενος ἀνθρώπῳ χαρίζεσθαι ἀγαθῷ καὶ ταύτης τυγχάνειν ἀξίῳ τῆς προνοίας. ἦν δὲ Νάβαλος, τοῦτο γὰρ εἶχεν ὄνομα, σκληρὸς καὶ πονηρὸς τοῖς ἐπιτηδεύμασιν ἐκ κυνικῆς ἀσκήσεως πεποιημένος τὸν βίον, γυναικὸς δʼ ἀγαθῆς καὶ σώφρονος καὶ τὸ εἶδος ὡραίας λελαχώς."},{"number":297,"text":"πρὸς οὖν τὸν Νάβαλον τοῦτον καθʼ ὃν ἔκειρε τὰ πρόβατα καιρὸν πέμψας ὁ Δαυίδης ἄνδρας δέκα τῶν σὺν αὐτῷ διὰ τούτων αὐτὸν ἀσπάζεται καὶ συνεύχεται τοῦτο ποιεῖν ἐπʼ ἔτη πολλά· παρασχεῖν δὲ ἐξ ὧν δυνατός ἐστιν αὐτῷ παρεκάλει μαθόντα παρὰ τῶν ποιμένων, ὅτι μηδὲν αὐτοὺς ἠδίκησαν, ἀλλὰ φύλακες αὐτῶν τε καὶ τῶν ποιμνίων γεγόνασι πολὺν ἐν τῇ ἐρήμῳ διατρίβοντες ἤδη χρόνον· μετανοήσει δʼ οὐδὲν Δαυίδῃ παρασχόμενος."},{"number":298,"text":"ταῦτα δὲ τῶν πεμφθέντων διακονησάντων πρὸς τὸν Νάβαλον ἀπανθρώπως σφόδρα καὶ σκληρῶς ἀπήντησεν· ἐρωτήσας γὰρ αὐτούς, τίς ἐστι Δαυίδης, ὡς τὸν υἱὸν ἤκουσεν Ἰεσσαίου,"},{"number":299,"text":"νῦν ἄρα, εἶπε, μέγα φρονοῦσιν ἐφʼ αὑτοῖς οἱ δραπέται καὶ σεμνύνονται τοὺς δεσπότας καταλιπόντες. ὀργίζεται δʼ αὐτῶν φρασάντων ὁ Δαυίδης καὶ τετρακοσίους μὲν ὡπλισμένους αὐτῷ κελεύσας ἕπεσθαι, διακοσίους δὲ φύλακας τῶν σκευῶν καταλιπών, ἤδη γὰρ εἶχεν ἑξακοσίους, ἐπὶ τὸν Νάβαλον ἐβάδιζεν ὀμόσας ἐκείνῃ τῇ νυκτὶ τὸν οἶκον αὐτοῦ καὶ τὴν κτῆσιν ὅλην ἀφανίσειν· οὐ γὰρ ἄχθεσθαι μόνον ὅτι γέγονεν ἀχάριστος ἐπʼ αὐτοὺς μηδὲν ἐπιδοὺς πολλῇ φιλανθρωπίᾳ πρὸς αὐτὸν χρησαμένοις, ἀλλʼ ὅτι καὶ προσεβλασφήμησε καὶ κακῶς εἶπε μηδὲν ὑπʼ αὐτῶν λελυπημένος."},{"number":300,"text":"Δούλου δέ τινος τῶν τὰ ποίμνια φυλασσόντων τὰ τοῦ Ναβάλου πρὸς τὴν δέσποιναν μὲν ἑαυτοῦ γυναῖκα δʼ ἐκείνου κατειπόντος, ὅτι πέμψας ὁ Δαυίδης αὐτῆς πρὸς τὸν ἄνδρα μηδενὸς τύχοι τῶν μετρίων, ἀλλὰ καὶ προσυβρισθείη βλασφημίαις δειναῖς πάσῃ περὶ αὐτοὺς προνοίᾳ καὶ φυλακῇ τῶν ποιμνίων χρησάμενος,"},{"number":301,"text":"γέγονε δὲ τοῦτο ἐπὶ κακῷ τῷ τοῦ δεσπότου καὶ ταῦτʼ ἐκείνου φήσαντος Ἀβιγαία, προσηγορεύετο γὰρ οὕτως, ἐπισάξασα τοὺς ὄνους καὶ πληρώσασα παντοίων ξενίων καὶ μηδὲν εἰποῦσα τἀνδρί, ὑπὸ γὰρ μέθης ἀναίσθητος ἦν, ἐπορεύετο πρὸς Δαυίδην· καταβαινούσῃ δὲ τὰ στενὰ τοῦ ὄρους ἀπήντησε Δαυίδης μετὰ τῶν τετρακοσίων ἐπὶ Νάβαλον ἐρχόμενος."},{"number":302,"text":"θεασαμένη δʼ αὐτὸν ἡ γυνὴ κατεπήδησε καὶ πεσοῦσα ἐπὶ πρόσωπον προσεκύνησε καὶ τῶν μὲν Ναβάλου λόγων ἐδεῖτο μὴ μνημονεύειν οὐ γὰρ ἀγνοεῖν αὐτὸν ὅμοιον ὄντα τῷ ὀνόματι, Νάβαλος γὰρ κατὰ τὴν Ἑβραίων γλῶτταν ἀφροσύνην δηλοῖ, αὐτὴ δʼ ἀπελογεῖτο μὴ θεάσασθαι τοὺς πεμφθέντας ὑπʼ αὐτοῦ·"},{"number":303,"text":"διὸ συγγίνωσκέ μοι, φησί, καὶ τῷ θεῷ χάριν ἔχε κωλύοντί σε μιανθῆναι ἀνθρωπίνῳ αἵματι· μένοντα γάρ σε καθαρὸν ἐκεῖνος αὐτὸς ἐκδικήσει παρὰ τῶν πονηρῶν· ἃ γὰρ ἐκδέχεται κακὰ Νάβαλον ταῦτα καὶ ταῖς τῶν ἐχθρῶν σου κεφαλαῖς ἐμπέσοι."},{"number":304,"text":"γενοῦ δὲ εὐμενής μοι κρίνας ἀξίαν τοῦ παρʼ ἐμοῦ ταῦτα δέξασθαι, καὶ τὸν θυμὸν καὶ τὴν ὀργὴν τὴν ἐπὶ τὸν ἄνδρα μου καὶ τὸν οἶκον αὐτοῦ εἰς τὴν ἐμὴν τιμὴν ἄφες· πρέπει γὰρ ἡμέρῳ σοι καὶ φιλανθρώπῳ τυγχάνειν, καὶ ταῦτα μέλλοντι βασιλεύειν."},{"number":305,"text":"ὁ δὲ τὰ δῶρα δεξάμενος ἀλλά σε, φησίν, ὦ γύναι, θεὸς εὐμενὴς ἤγαγε πρὸς ἡμᾶς τήμερον· οὐ γὰρ ἂν τὴν ἐπερχομένην ἡμέραν εἶδες, ἐμοῦ τὸν οἶκον τὸν Ναβάλου διὰ τῆσδε τῆς νυκτὸς ὀμόσαντος ἀπολέσαι καὶ μηδένα ὑμῶν ἀπολείψειν ἀπὸ ἀνδρὸς ἕως τετραπόδου πονηροῦ καὶ ἀχαρίστου πρὸς ἐμὲ καὶ τοὺς ἐμοὺς ἑταίρους γενομένου. νῦν δὲ φθάσασα προέλαβες καταμειλίξασθαί μου τὸν θυμὸν κηδομένου σου θεοῦ. ἀλλὰ Νάβαλος μὲν κἂν ἀφεθῇ διὰ σὲ νῦν τῆς τιμωρίας οὐ φεύξεται τὴν δίκην, ἀλλʼ ὁ τρόπος αὐτὸν ἀπολεῖ λαβὼν αἰτίαν ἄλλην."},{"number":306,"text":"Ταῦτʼ εἰπὼν ἀπολύει τὴν γυναῖκα· ἡ δʼ εἰς τὸν οἶκον ἐλθοῦσα καὶ καταλαβοῦσα τὸν ἄνδρα μετὰ πολλῶν εὐωχούμενον καὶ κεκαρωμένον ἤδη τότε μὲν οὐδὲν τῶν γεγενημένων διεσάφει, τῇ δὲ ἐπιούσῃ νήφοντι ἅπαντα δηλώσασα παρεθῆναι καὶ πᾶν αὐτῷ νεκρωθῆναι τὸ σῶμα ὑπὸ τῶν λόγων καὶ τῆς ἐπʼ αὐτοῖς λύπης ἐποίησε· καὶ δέκα οὐ πλείους ἐπιζήσας ἡμέρας τὸν βίον κατέστρεψεν ὁ Νάβαλος."},{"number":307,"text":"ἀκούσας δʼ αὐτοῦ τὴν τελευτὴν ὁ Δαυίδης ἐκδικηθῆναι μὲν αὑτὸν ὑπὸ τοῦ θεοῦ καλῶς ἔλεγεν· ἀποθανεῖν γὰρ Νάβαλον ὑπὸ τῆς ἰδίας πονηρίας καὶ δοῦναι δίκην αὐτῷ καθαρὰν ἔχοντι τὴν δεξιάν· ἔγνω δὲ καὶ τότε τοὺς πονηροὺς ἐλαυνομένους ὑπὸ τοῦ θεοῦ μηδενὸς τῶν ἐν ἀνθρώποις ὑπερορῶντος, διδόντος δὲ τοῖς μὲν ἀγαθοῖς τὰ ὅμοια, τοῖς δὲ πονηροῖς ὀξεῖαν ἐπιφέροντος τὴν ποινήν."},{"number":308,"text":"πέμψας δʼ αὐτοῦ πρὸς τὴν γυναῖκα συνοικήσουσαν καὶ γαμηθησομένην ἐκάλει πρὸς αὑτόν· ἡ δὲ ἀναξία μὲν εἶναι καὶ ποδῶν ἅψασθαι τῶν ἐκείνου πρὸς τοὺς παρόντας ἔλεγεν, ὅμως δὲ μετὰ πάσης τῆς θεραπείας ἧκε. καὶ συνῴκησε μὲν αὐτῷ ταύτην λαβοῦσα τὴν τιμὴν καὶ διὰ τὸ τὸν τρόπον σώφρονα εἶναι καὶ δίκαιον, τυχοῦσα δʼ αὐτῆς καὶ διὰ τὸ κάλλος."},{"number":309,"text":"εἶχε δὲ Δαυίδης γυναῖκα πρότερον, ἣν ἐξ Ἀβισάρου πόλεως ἔγημε· Μελχὰν δὲ τὴν Σαούλου τοῦ βασιλέως θυγατέρα τὴν γενομένην τοῦ Δαυίδου γυναῖκα ὁ πατὴρ τῷ Φελτίῳ υἱῷ Λίσου συνέζευξεν ἐκ πόλεως ὄντι Γεθλᾶς."},{"number":310,"text":"Μετὰ ταῦτά τινες ἐλθόντες τῶν Ζιφηνῶν ἀπήγγειλαν τῷ Σαούλῳ, ὡς εἴη πάλιν ὁ Δαυίδης ἐν τῇ χώρᾳ αὐτῶν καὶ δύνανται συλλαβεῖν αὐτὸν βουλομένῳ συνεργῆσαι. ὁ δὲ μετὰ τρισχιλίων ὁπλιτῶν ἐβάδιζεν ἐπʼ αὐτὸν καὶ νυκτὸς ἐπελθούσης ἐστρατοπέδευσεν ἐπί τινι τόπῳ Σίκελλα λεγομένῳ."},{"number":311,"text":"Δαυίδης δὲ ἀκούσας τὸν Σαοῦλον ἐπʼ αὐτὸν ἥκοντα πέμψας κατασκόπους ἐκέλευσε δηλοῦν αὐτῷ, ποῦ τῆς χώρας Σαοῦλος ἤδη προεληλύθοι. τῶν δʼ ἐν Σίκελλα φρασάντων διανυκτερεύειν διαλαθὼν τοὺς ἰδίους εἰς τὸ τοῦ Σαούλου στρατόπεδον παραγίνεται ἐπαγόμενος τὸν ἐκ τῆς ἀδελφῆς αὐτοῦ Σαρουίας Ἀβισαῖον καὶ Ἀβιμέλεχον τὸν Χετταῖον."},{"number":312,"text":"τοῦ δὲ Σαούλου κοιμωμένου καὶ περὶ αὐτὸν ἐν κύκλῳ τῶν ὁπλιτῶν καὶ τοῦ στρατηγοῦ Ἀβενήρου κειμένων, ὁ Δαυίδης εἰσελθὼν εἰς τὸ στρατόπεδον τὸ τοῦ βασιλέως οὔτʼ αὐτὸς ἀναιρεῖ τὸν Σαοῦλον ἐπιγνοὺς αὐτοῦ τὴν κοίτην ἐκ τοῦ δόρατος, τοῦτο γὰρ αὐτῷ παρεπεπήγει, οὔτε τὸν Ἀβισαῖον βουλόμενον φονεῦσαι καὶ πρὸς τοῦτο ὡρμηκότα εἴασεν, ἀλλὰ τὸν ὑπὸ τοῦ θεοῦ κεχειροτονημένον βασιλέα φήσας εἶναι δεινὸν ἀποκτεῖναι κἂν ᾖ πονηρός, ἥξειν γὰρ αὐτῷ παρὰ τοῦ δόντος τὴν ἀρχὴν σὺν χρόνῳ τὴν δίκην, ἐπέσχε τῆς ὁρμῆς."},{"number":313,"text":"σύμβολον δὲ τοῦ κτεῖναι δυνηθεὶς ἀποσχέσθαι λαβὼν αὐτοῦ τὸ δόρυ καὶ τὸν φακὸν τοῦ ὕδατος, ὃς ἦν παρʼ αὐτῷ κείμενος τῷ Σαούλῳ, μηδενὸς αἰσθομένου τῶν ἐν τῷ στρατοπέδῳ πάντων δὲ κατακοιμωμένων ἐξῆλθεν, ἀδεῶς πάντʼ ἐργασάμενος, ὅσα καὶ τοῦ καιροῦ δόντος αὐτῷ καὶ τῆς τόλμης διέθηκε τοὺς τοῦ βασιλέως."},{"number":314,"text":"διαβὰς δὲ τὸν χείμαρρον καὶ ἐπὶ τὴν κορυφὴν ἀνελθὼν τοῦ ὄρους, ὅθεν ἔμελλεν ἐξάκουστος εἶναι, ἐμβοήσας τοῖς στρατιώταις τοῦ Σαούλου καὶ τῷ στρατηγῷ Ἀβενήρῳ διανίστησιν αὐτὸν ἀπὸ τοῦ ὕπνου τοῦτόν τε ἐφώνει καὶ τὸν λαόν. ἐπακούσαντος δὲ τοῦ στρατηγοῦ καὶ τίς ὁ καλέσας αὐτόν ἐστιν ἐρομένου Δαυίδης εἶπεν·"},{"number":315,"text":"ἐγώ, παῖς μὲν Ἰεσσαίου, φυγὰς δὲ ὑμέτερος. ἀλλὰ τί δήποτε μέγας τε ὢν καὶ τὴν πρώτην ἔχων παρὰ τῷ βασιλεῖ τιμὴν οὕτως ἀμελῶς τὸ τοῦ δεσπότου φυλάσσεις σῶμα, καὶ ὕπνος ἡδίων ἐστί σοι τῆς τούτου σωτηρίας καὶ προνοίας; θανάτου γὰρ ἄξια ταῦτα καὶ τιμωρίας, οἵ γε μικρὸν ἔμπροσθεν εἰσελθόντας τινὰς ὑμῶν εἰς τὸ στρατόπεδον οὐκ ἐνοήσατε. ζήτησον οὖν τὸ δόρυ τοῦ βασιλέως καὶ τὸν φακὸν τοῦ ὕδατος καὶ μαθήσῃ, πηλίκον ὑμᾶς ἔλαθε κακὸν ἐντὸς γενόμενον. Σαοῦλος δὲ γνωρίσας τὴν τοῦ Δαυίδου φωνὴν καὶ μαθών,"},{"number":316,"text":"ὅτι λαβὼν αὐτὸν ἔκδοτον ὑπὸ τοῦ ὕπνου καὶ τῆς τῶν φυλασσόντων ἀμελείας οὐκ ἀπέκτεινεν, ἀλλʼ ἐφείσατο δικαίως ἂν αὐτὸν ἀνελών, χάριν ἔχειν αὐτῷ τῆς σωτηρίας ἔλεγε καὶ παρεκάλει θαρροῦντα καὶ μηδὲν ἔτι πείσεσθαι δεινὸν ἐξ αὐτοῦ φοβούμενον ἀναχωρεῖν ἐπὶ τὰ οἰκεῖα·"},{"number":317,"text":"πεπεῖσθαι γάρ, ὅτι μηδʼ αὐτὸν οὕτως ἀγαπήσειεν, ὡς ὑπʼ ἐκείνου στέργεται· ὃς τὸν μὲν φυλάττειν αὐτὸν δυνάμενον καὶ πολλὰ δείγματα τῆς εὐνοίας παρεσχημένον ἐλαύνοι καὶ τοσοῦτον ἐν φυγῇ χρόνον καὶ ταῖς περὶ τὴν ψυχὴν ἀγωνίαις ἠνάγκασε ζῆσαι φίλων καὶ συγγενῶν ἔρημον· αὐτὸς δʼ οὐ παύεται ὑπʼ αὐτοῦ σωζόμενος, οὐδὲ τὴν ψυχὴν φανερῶς ἀπολλυμένην λαμβάνων."},{"number":318,"text":"ὁ δὲ Δαυίδης πέμψαντα ἀπολαβεῖν ἐκέλευσε τὸ δόρυ καὶ τὸν φακὸν τοῦ ὕδατος ἐπειπών, ὡς ὁ θεὸς ἑκατέρῳ τῆς ἰδίας φύσεως καὶ τῶν κατʼ αὐτὴν πεπραγμένων ἔσται δικαστής, ὃς ὅτι καὶ κατὰ τὴν παροῦσαν ἡμέραν ἀποκτεῖναί σε δυνηθεὶς ἀπεσχόμην οἶδε."},{"number":319,"text":"Καὶ Σαοῦλος μὲν δεύτερον διαφυγὼν τὰς Δαυίδου χεῖρας εἰς τὰ βασίλεια καὶ τὴν οἰκείαν ἀπηλλάσσετο, φοβηθεὶς δὲ Δαυίδης, μὴ μένων αὐτόθι συλληφθῇ ὑπὸ τοῦ Σαούλου, συμφέρειν ἔκρινεν εἰς τὴν Παλαιστίνην ἀναβὰς διατρίβειν ἐν αὐτῇ, καὶ μετὰ τῶν ἑξακοσίων, οἳ περὶ αὐτὸν ἦσαν παραγίνεται πρὸς Ἀγχοῦν τὸν Γίττης βασιλέα· μία δʼ ἦν αὕτη τῶν πέντε πόλεων."},{"number":320,"text":"δεξαμένου δʼ αὐτὸν τοῦ βασιλέως σὺν τοῖς ἀνδράσι καὶ δόντος οἰκητήριον ἔχων ἅμα καὶ τὰς δύο γυναῖκας Ἀχιμὰν καὶ Ἀβιγαίαν διῆγεν ἐν τῇ Γίττῃ. Σαούλῳ δὲ ταῦτʼ ἀκούσαντι λόγος οὐκέτʼ ἦν πέμπειν ἐπʼ αὐτὸν ἢ βαδίζειν· δὶς γὰρ ἤδη κινδυνεῦσαι παρὰ μικρὸν ἐπʼ ἐκείνῳ γενόμενον συλλαβεῖν αὐτὸν σπουδάσαντα."},{"number":321,"text":"Δαυίδῃ δʼ οὐκ ἔδοξεν ἐν τῇ πόλει τῶν Γιττῶν μένειν, ἀλλʼ ἐδεήθη τοῦ βασιλέως αὐτῶν, ἵνʼ ἐπειδὴ φιλανθρώπως αὐτὸν ὑπεδέξατο καὶ τοῦτο χαρίσηται, τόπον τινὰ τῆς χώρας δοὺς αὐτῷ πρὸς κατοίκησιν· αἰδεῖσθαι γὰρ διατρίβων ἐν τῷ πόλει βαρὺς αὐτῷ καὶ φορτικὸς εἶναι."},{"number":322,"text":"δίδωσι δὲ Ἀγχοῦς αὐτῷ κώμην τινὰ Σέκελλαν καλουμένην, ἣν βασιλεύσας ὁ Δαυίδης ἀγαπῶν ἴδιον κτῆμα ἐτίμησεν εἶναι καὶ οἱ παῖδες αὐτοῦ. ἀλλὰ περὶ μὲν τούτων ἐν ἄλλοις δηλώσομεν· ὁ δὲ χρόνος, ὃν κατῴκησε Δαυίδης ἐν Σεκέλλα τῆς Παλαιστίνης, ἐγένετο μῆνες τέσσαρες πρὸς ταῖς εἴκοσιν ἡμέραις."},{"number":323,"text":"ἐπερχόμενος δὲ λάθρα τοῖς πλησιοχώροις τῶν Παλαιστίνων Σερρίταις καὶ Ἀμαληκίταις διήρπαζεν αὐτῶν τὴν χώραν καὶ λείαν πολλὴν κτηνῶν καὶ καμήλων λαμβάνων ὑπέστρεφεν· ἀνθρώπων γὰρ ἀπείχετο δεδιὼς μὴ καταμηνύσωσιν αὐτὸν πρὸς Ἀγχοῦν τὸν βασιλέα, τὸ μέντοι γε τῆς λείας μέρος αὐτῷ δωρεὰν ἔπεμπε."},{"number":324,"text":"τοῦ δὲ βασιλέως πυθομένου, τίσιν ἐπιθέμενος τὴν λείαν ἀπήλασε; τοῖς πρὸς τὸν νότον τῶν Ἰουδαίων τετραμμένοις καὶ ἐν τῇ πεδιάδι κατοικοῦσιν εἰπὼν πείθει τὸν Ἀγχοῦν φρονῆσαι οὕτως· ἤλπισε γὰρ οὗτος, ὅτι Δαυίδης ἐμίσησε τὸ ἴδιον ἔθνος, καὶ δοῦλον ἕξειν παρʼ ὃν ζῇ χρόνον ἐν τοῖς αὐτοῦ καταμένοντα."}],"14":[{"number":325,"text":"Κατὰ δὲ τὸν αὐτὸν καιρὸν τῶν Παλαιστίνων ἐπὶ τοὺς Ἰσραηλίτας στρατεύειν διεγνωκότων καὶ περιπεμψάντων πρὸς τοὺς συμμάχους ἅπαντας, ἵνα παρῶσιν αὐτοῖς εἰς τὸν πόλεμον εἰς Ῥεγάν, ἔνθεν ἔμελλον ἀθροισθέντες ἐξορμᾶν ἐπὶ τοὺς Ἑβραίους, ὁ τῶν Γιττῶν βασιλεὺς Ἀγχοῦς συμμαχῆσαι τὸν Δαυίδην αὐτῷ μετὰ τῶν ἰδίων ὁπλιτῶν ἐκέλευσε."},{"number":326,"text":"τοῦ δὲ προθύμως ὑποσχομένου καὶ φήσαντος παραστῆναι καιρόν, ἐν ᾧ τὴν ἀμοιβὴν αὐτῷ τῆς εὐεργεσίας καὶ τῆς ξενίας ἀποδώσει, ποιήσειν αὐτὸν καὶ φύλακα τοῦ σώματος μετὰ τὴν νίκην καὶ τοὺς ἀγῶνας τοὺς πρὸς τοὺς πολεμίους κατὰ νοῦν χωρήσαντας αὐτοῖς ἐπηγγείλατο, τῆς τιμῆς καὶ πίστεως ὑποσχέσει τὸ πρόθυμον αὐτοῦ μᾶλλον αὔξων."},{"number":327,"text":"Ἔτυχε δὲ Σαοῦλος ὁ τῶν Ἑβραίων βασιλεὺς τοὺς μάντεις καὶ τοὺς ἐγγαστριμύθους καὶ πᾶσαν τὴν τοιαύτην τέχνην ἐκ τῆς χώρας ἐκβεβληκὼς ἔξω τῶν προφητῶν. ἀκούσας δὲ τοὺς Παλαιστίνους ἤδη παρόντας καὶ ἔγγιστα Σούνης πόλεως ἐν τῷ πεδίῳ ἐστρατοπεδευκότας ἐξώρμησεν ἐπʼ αὐτοὺς μετὰ τῆς δυνάμεως."},{"number":328,"text":"καὶ παραγενόμενος πρὸς ὄρει τινὶ Γελβουὲ καλουμένῳ βάλλεται στρατόπεδον ἀντικρὺ τῶν πολεμίων. ταράττει δʼ αὐτὸν οὐχ ὡς ἔτυχεν ἡ τῶν ἐχθρῶν δύναμις πολλή τε οὖσα καὶ τῆς οἰκείας κρείττων ὑπονοουμένη, καὶ τὸν θεὸν διὰ τῶν προφητῶν ἐρωτᾷ περὶ τῆς μάχης καὶ τοῦ περὶ ταύτην ἐσομένου τέλους προειπεῖν."},{"number":329,"text":"οὐκ ἀποκρινομένου δὲ τοῦ θεοῦ ἔτι μᾶλλον ὁ Σαοῦλος κατέδεισε καὶ τὴν ψυχὴν ἀνέπεσε, τὸ κακὸν οἷον εἰκὸς οὐ παρόντος αὐτῷ κατὰ χεῖρα τοῦ θείου προορώμενος. ζητηθῆναι δʼ αὑτῷ κελεύει γύναιόν τι τῶν ἐγγαστριμύθων καὶ τῶν τεθνηκότων ψυχὰς ἐκκαλουμένων ὡς οὕτως γνωσομένῳ, ποῖ χωρεῖν αὐτῷ μέλλει τὰ πράγματα·"},{"number":330,"text":"τὸ γὰρ τῶν ἐγγαστριμύθων γένος ἀνάγον τὰς τῶν νεκρῶν ψυχὰς διʼ αὐτῶν προλέγει τοῖς δεομένοις τὰ ἀποβησόμενα. μηνυθέντος δʼ αὐτῷ παρά τινος τῶν οἰκετῶν εἶναί τι γύναιον τοιοῦτον ἐν πόλει Δώρῳ, λαθὼν πάντας τοὺς ἐν τῷ στρατοπέδῳ καὶ μετεκδὺς τὴν βασιλικὴν ἐσθῆτα δύο παραλαβὼν οἰκέτας, οὓς ᾔδει πιστοτάτους ἄνδρας, ἧκεν εἰς τὴν Δῶρον πρὸς τὴν γυναῖκα καὶ παρεκάλει μαντεύεσθαι καὶ ἀνάγειν αὐτῷ ψυχὴν οὗπερ ἂν αὐτὸς εἴπῃ."},{"number":331,"text":"τῆς δὲ γυναικὸς ἀπομαχομένης καὶ λεγούσης οὐ καταφρονήσειν τοῦ βασιλέως, ὃς τοῦτο τὸ γένος τῶν μάντεων ἐξήλασεν, οὐδʼ αὐτὸν δὲ ποιεῖν καλῶς ἀδικηθέντα μηδὲν ὑπʼ αὐτῆς, ἐνεδρεύοντα δὲ εἰς τὰ κεκωλυμένα λαβεῖν αὐτὴν ἵνα δῷ δίκην, ὤμοσε μηδένα γνώσεσθαι μηδὲ παρʼ ἄλλον ἄγειν αὐτῆς τὴν μαντείαν, ἔσεσθαι δʼ ἀκίνδυνον."},{"number":332,"text":"ὡς δὲ τοῖς ὅρκοις αὐτὴν ἔπεισε μὴ δεδιέναι, κελεύει τὴν Σαμουήλου ψυχὴν ἀναγαγεῖν αὐτῷ. ἡ δʼ ἀγνοοῦσα τὸν Σαμουῆλον ὅστις ἦν καλεῖ τοῦτον ἐξ ᾅδου· φανέντος δʼ αὐτοῦ θεασάμενον τὸ γύναιον ἄνδρα σεμνὸν καὶ θεοπρεπῆ ταράττεται, καὶ πρὸς τὴν ὄψιν ἐκπλαγέν, οὐ σύ, φησίν, ὁ βασιλεὺς εἶ Σαοῦλος; ἐδήλωσε γὰρ αὐτὸν Σαμουῆλος."},{"number":333,"text":"ἐπινεύσαντος δʼ ἐκείνου καὶ τὴν ταραχὴν αὐτῆς ἐρομένου πόθεν γένοιτο, βλέπειν εἶπεν ἀνελθόντα τῷ θεῷ τινα τὴν μορφὴν ὅμοιον. τοῦ δὲ τὴν εἰκόνα φράζειν εἰπόντος καὶ τὸ σχῆμα τοῦ θεαθέντος καὶ τὴν ἡλικίαν κελεύσαντος γέροντα μὲν ἤδη καὶ ἔνδοξον ἐσήμαινεν, ἱερατικὴν δὲ περικείμενον διπλοΐδα."},{"number":334,"text":"ἐγνώρισεν ἐκ τούτων ὁ βασιλεὺς τὸν Σαμουῆλον ὄντα καὶ πεσὼν ἐπὶ τὴν γῆν ἠσπάζετο καὶ προσεκύνησε· τῆς δὲ Σαμουήλου ψυχῆς πυθομένης, διὰ τί κινήσειεν αὐτὴν καὶ ἀναχθῆναι ποιήσειεν ἀνάγκην, ἀπωδύρετο τοὺς πολεμίους ἐπικεῖσθαι βαρεῖς αὐτῷ, αὐτὸν δὲ ἀμηχανεῖν τοῖς παροῦσιν ἐγκαταλελειμμένον ὑπὸ τοῦ θεοῦ καὶ μηδὲ προρρήσεως τυγχάνοντα μήτε διὰ προφητῶν μήτε διʼ ὀνειράτων καὶ διὰ τοῦτο ἐπὶ σὲ τὸν ἐμοῦ προνοησόμενον κατέφυγον."},{"number":335,"text":"Σαμουῆλος δὲ τέλος αὐτὸν ἔχοντα ἤδη τῆς μεταβολῆς ὁρῶν περισσὸν μέν, εἶπεν, ἔτι καὶ παρʼ ἐμοῦ βούλεσθαι μαθεῖν τοῦ θεοῦ καταλελοιπότος αὐτόν· ἄκουέ γε μήν, ὅτι βασιλεῦσαι δεῖ Δαυίδην καὶ κατορθῶσαι τὸν πόλεμον, σὲ δὲ καὶ τὴν ἀρχὴν καὶ τὴν ζωὴν"},{"number":336,"text":"ἀπολέσαι τοῦ θεοῦ παρακούσαντα ἐν τῷ πρὸς Ἀμαληκίτας πολέμῳ καὶ τὰς ἐντολὰς αὐτοῦ μὴ φυλάξαντα, καθὼς προεφήτευσά σοι καὶ ζῶν. ἴσθι τοίνυν καὶ τὸν λαὸν ὑποχείριον τοῖς ἐχθροῖς γενησόμενον καὶ σαυτὸν μετὰ τῶν τέκνων αὔριον πεσόντα ἐπὶ τῆς μάχης μετʼ ἐμοῦ γενησόμενον."},{"number":337,"text":"Ταῦτʼ ἀκούσας Σαοῦλος ἄφωνος ὑπὸ λύπης ἐγένετο καὶ κατενεχθεὶς εἰς τοὔδαφος, εἴτε διὰ τὴν προσπεσοῦσαν ἐκ τῶν δεδηλωμένων ὀδύνην, εἴτε διὰ τὴν ἔνδειαν, οὐ γὰρ προσενήνεκτο τροφὴν τῇ παρελθούσῃ ἡμέρᾳ τε καὶ νυκτί, ῥᾳδίως ἔκειτο νέκυς ὥς τις."},{"number":338,"text":"μόλις δὲ ἑαυτοῦ γενόμενον συνηνάγκασεν ἡ γυνὴ γεύσασθαι ταύτην αἰτουμένη παρʼ αὐτοῦ τὴν χάριν ἀντὶ τῆς παραβόλου μαντείας, ἣν οὐκ ἐξὸν αὐτῇ ποιήσασθαι διὰ τὸν ἐξ αὐτοῦ φόβον ἀγνοουμένου τίς ἦν, ὅμως ὑπέστη καὶ παρέσχεν. ἀνθʼ ὧν παρεκάλει τράπεζάν τε αὐτῷ παραθεῖναι καὶ τροφήν, ὡς ἂν τὴν ἰσχὺν συλλεξάμενος εἰς τὸ τῶν οἰκείων ἀποσωθῇ στρατόπεδον· ἀντέχοντα δὲ καὶ τελέως ἀπεστραμμένον ὑπὸ ἀθυμίας ἐβιάσατο καὶ συνέπεισεν."},{"number":339,"text":"ἔχουσα δὲ μόσχον ἕνα συνήθη καὶ τῆς κατʼ οἶκον ἐπιμελείας καὶ τροφῆς ἀξιούμενον ὑπʼ αὐτῆς, ὡς γυνὴ χερνῆτις καὶ τούτῳ μόνῳ προσαναπαυομένη τῷ κτήματι, κατασφάξασα τοῦτον καὶ τὰ κρέα παρασκευάσασα τοῖς οἰκέταις αὐτοῦ καὶ αὐτῷ παρατίθησι. καὶ Σαοῦλος μὲν διὰ τῆς νυκτὸς ἦλθεν εἰς τὸ στρατόπεδον."},{"number":340,"text":"Δίκαιον δὲ ἀποδέξασθαι τῆς φιλοτιμίας τὴν γυναῖκα, ὅτι καίπερ τῇ τέχνῃ κεκωλυμένη χρήσασθαι ὑπὸ τοῦ βασιλέως, παρʼ ἧς ἂν αὐτῇ τὰ κατὰ τὸν οἶκον ἦν ἀμείνω καὶ διαρκέστερα, καὶ μηδέποτε αὐτὸν πρότερον τεθεαμένη οὐκ ἐμνησικάκησε τῆς ἐπιστήμης ὑπʼ αὐτοῦ καταγνωσθείσης, οὐκ ἀπεστράφη δὲ ὡς ξένον καὶ μηδέποτε ἐν συνηθείᾳ γεγενημένον,"},{"number":341,"text":"ἀλλὰ συνεπάθησέ τε καὶ παρεμυθήσατο καὶ πρὸς ἃ διέκειτο λίαν ἀηδῶς προετρέψατο, καὶ τὸ μόνον αὐτῇ παρὸν ὡς ἐν πενίᾳ τοῦτο παρέσχεν ἐκτενῶς καὶ φιλοφρόνως, οὔθʼ ὑπὲρ εὐεργεσίας ἀμειβομένη τινὸς γεγενημένης οὔτε χάριν μέλλουσαν θηρωμένη, τελευτήσοντα γὰρ αὐτὸν ἠπίστατο, φύσει τῶν ἀνθρώπων ἢ πρὸς τοὺς ἀγαθόν τι παρεσχημένους φιλοτιμουμένων, ἢ παρʼ ὧν ἂν δύνωνται λαβεῖν ὄφελος τούτους προθεραπευόντων."},{"number":342,"text":"καλὸν οὖν ἐστι μιμεῖσθαι τὴν γυναῖκα καὶ ποιεῖν εὖ πάντας τοὺς ἐν χρείᾳ γενομένους καὶ μηδὲν ὑπολαμβάνειν ἄμεινον μηδὲ μᾶλλόν τι προσήκειν τῷ τῶν ἀνθρώπων γένει τούτου μηδʼ ἐφʼ ᾧ τὸν θεὸν εὐμενῆ καὶ χορηγὸν τῶν ἀγαθῶν ἕξομεν. καὶ τὰ μὲν περὶ τῆς γυναικὸς ἐν τοσούτοις ἀρκεῖ δεδηλῶσθαι·"},{"number":343,"text":"τὸν δὲ πόλεσι καὶ δήμοις καὶ ἔθνεσι συμφέροντα λόγον καὶ προσήκοντα τοῖς ἀγαθοῖς, ὑφʼ οὗ προαχθήσονται πάντες ἀρετὴν διώξειν καὶ ζηλοῦν δόξαν καὶ μνήμην αἰώνιον παρασχεῖν δυνησόμενον, ποιήσομαι, πολλὴν καὶ βασιλεῦσιν ἐθνῶν καὶ ἄρχουσι πόλεων ἐπιθυμίαν καὶ σπουδὴν τῶν καλῶν ἐνθήσοντα, καὶ πρός τε κινδύνους καὶ τὸν ὑπὲρ τῶν πατρίδων θάνατον προτρεψόμενον, καὶ πάντων καταφρονεῖν διδάξοντα τῶν δεινῶν."},{"number":344,"text":"ἔχω δʼ αἰτίαν τοῦ λόγου τούτου Σαοῦλον τὸν τῶν Ἑβραίων βασιλέα· οὗτος γὰρ καίπερ εἰδὼς τὰ συμβησόμενα καὶ τὸν ἐπικείμενον θάνατον τοῦ προφήτου προειρηκότος οὐκ ἔγνω φυγεῖν αὐτὸν οὐδὲ φιλοψυχήσας προδοῦναι μὲν τοὺς οἰκείους τοῖς πολεμίοις καθυβρίσαι δὲ τὸ τῆς βασιλείας ἀξίωμα,"},{"number":345,"text":"ἀλλὰ παραδοὺς αὑτὸν πανοικὶ μετὰ τῶν τέκνων τοῖς κινδύνοις καλὸν ἡγήσατο εἶναι πεσεῖν μετὰ τούτων ὑπὲρ τῶν βασιλευομένων μαχόμενος, καὶ τοὺς παῖδας ἀποθανεῖν μᾶλλον ἀγαθοὺς ὄντας, ἢ καταλιπεῖν ἐπʼ ἀδήλῳ τῷ ποδαποὶ γενήσονται τὸν τρόπον· διάδοχον γὰρ καὶ γένος τὸν ἔπαινον καὶ τὴν ἀγήρω μνήμην ἕξειν."},{"number":346,"text":"οὗτος οὖν δίκαιος καὶ ἀνδρεῖος καὶ σώφρων ἔμοι γε δοκεῖ μόνος καὶ εἴ τις γέγονε τοιοῦτος ἢ γενήσεται τὴν μαρτυρίαν ἐπʼ ἀρετῇ καρποῦσθαι παρὰ πάντων ἄξιος· τοὺς γὰρ μετʼ ἐλπίδων ἐπὶ πόλεμον ἐξελθόντας ὡς καὶ κρατήσοντας καὶ σῶς ἐπιστρέψοντας, ἐπειδάν τι διαπράξωνται λαμπρόν, οὔ μοι δοκοῦσι καλῶς ποιεῖν ἀνδρείους ἀποκαλοῦντες, ὅσοι περὶ τῶν τοιούτων ἐν ταῖς ἱστορίαις καὶ τοῖς ἄλλοις συγγράμμασιν εἰρήκασιν·"},{"number":347,"text":"ἀλλὰ δίκαιοι μέν εἰσι κἀκεῖνοι τυγχάνειν ἀποδοχῆς, εὔψυχοι δὲ καὶ μεγαλότολμοι καὶ τῶν δεινῶν καταφρονηταὶ μόνοι δικαίως ἂν λέγοιντο πάντες οἱ Σαοῦλον μιμησάμενοι. τὸ μὲν γὰρ οὐκ εἰδότας τί μέλλει συμβήσεσθαι κατὰ τὸν πόλεμον αὐτοῖς μὴ μαλακισθῆναι περὶ αὐτόν, ἀλλʼ ἀδήλῳ τῷ μέλλοντι παραδόντας αὑτοὺς ἐπʼ αὐτοῦ σαλεύειν οὔπω γενναῖον, κἂν ἔργα πολλὰ διαπραξάμενοι τύχωσι·"},{"number":348,"text":"τὸ δὲ μηδὲν ἐν τῇ διανοίᾳ χρηστὸν προσδοκῶντας, ἀλλὰ προειδότας ὡς δεῖ θανεῖν καὶ τοῦτο παθεῖν μαχομένους εἶτα μὴ φοβηθῆναι μηδὲ καταπλαγῆναι τὸ δεινόν, ἀλλʼ ἐπʼ αὐτὸ χωρῆσαι προγινωσκόμενον, τοῦτʼ ἀνδρείου ἀληθῶς τεκμήριον ἐγὼ κρίνω."},{"number":349,"text":"Σαοῦλος τοίνυν τοῦτο ἐποίησεν ἐπιδείξας ὅτι πάντας μὲν προσήκει τῆς μετὰ τὸν θάνατον εὐφημίας γλιχομένους ταῦτα ποιεῖν, ἐξ ὧν ἂν αὑτοῖς ταύτην καταλείποιεν, μάλιστα δὲ τοὺς βασιλέας, ὡς οὐκ ἐξὸν αὐτοῖς διὰ τὸ μέγεθος τῆς ἀρχῆς οὐ μόνον οὐ κακοῖς εἶναι περὶ τοὺς ἀρχομένους, ἀλλʼ οὐδὲ μετρίως χρηστοῖς."},{"number":350,"text":"ἔτι τούτων πλείω περὶ Σαούλου καὶ τῆς εὐψυχίας λέγειν ἠδυνάμην ὕλην ἡμῖν χορηγησάσης τῆς ὑποθέσεως, ἀλλʼ ἵνα μὴ φανῶμεν ἀπειροκάλως αὐτοῦ χρῆσθαι τοῖς ἐπαίνοις, ἐπάνειμι πάλιν ἀφʼ ὧν εἰς τούτους ἐξέβην."},{"number":351,"text":"Κατεστρατοπεδευκότων γὰρ τῶν Παλαιστίνων, ὡς προεῖπον, καὶ κατὰ ἔθνη καὶ βασιλείας καὶ σατραπείας ἐξαριθμούντων τὴν δύναμιν, τελευταῖος βασιλεὺς παρῆλθεν Ἀγχοῦς μετὰ τῆς ἰδίας στρατιᾶς καὶ Δαυίδης μετὰ τῶν ἑξακοσίων ὁπλιτῶν εἵπετο."},{"number":352,"text":"θεασάμενοι δὲ αὐτὸν οἱ στρατηγοὶ τῶν Παλαιστίνων, πόθεν εἴησαν ἥκοντες οἱ Ἑβραῖοι καὶ τίνων καλεσάντων ἠρώτων τὸν βασιλέα. ὁ δὲ Δαυίδην ἔλεγεν εἶναι τὸν φυγόντα Σαοῦλον τὸν ἑαυτοῦ δεσπότην καὶ πρὸς αὐτὸν ἐλθόντα δέξασθαι, καὶ νῦν τῆς χάριτος ἀμοιβὴν ἐκτεῖσαι βουλόμενον καὶ τιμωρήσασθαι τὸν Σαοῦλον συμμαχεῖν αὐτοῖς."},{"number":353,"text":"ἐμέμφθη δὲ ὑπὸ τῶν στρατηγῶν ἄνδρα παρειληφὼς ἐπὶ συμμαχίᾳ πολέμιον καὶ ἀποπέμπειν συνεβούλευον, μὴ καὶ λάθῃ μέγα διʼ αὐτὸν κακὸν τοὺς φίλους ἐργασάμενος· καὶ γὰρ οὕτω παρέξειν καταλλαγῆναι πρὸς τὸν δεσπότην κακώσαντα τὴν ἡμετέραν δύναμιν."},{"number":354,"text":"ὃ δὴ καὶ προορώμενον εἰς τὸν τόπον ὃν ἔδωκεν αὐτῷ κατοικεῖν ἐκέλευον ἀποπέμπειν σὺν τοῖς ἑξακοσίοις ὁπλίταις· τοῦτον γὰρ εἶναι τὸν Δαυίδην, ὃν ᾄδουσιν αἱ παρθένοι πολλὰς μυριάδας Παλαιστίνων ἀπολέσαντα. ταῦτʼ ἀκούσας ὁ τῶν Γιττῶν βασιλεὺς καὶ καλῶς εἰρῆσθαι λογισάμενος καλέσας τὸν Δαυίδην ἐγὼ μέν,"},{"number":355,"text":"εἶπε, μαρτυρῶ σοι πολλὴν περὶ ἐμὲ σπουδὴν καὶ εὔνοιαν καὶ διὰ τοῦτό σε σύμμαχον ἐπηγόμην· οὐ δοκεῖ δὲ ταὐτὸ τοῖς στρατηγοῖς. ἀλλʼ ἄπιθι μεθʼ ἡμέραν εἰς ὃν ἔδωκά σοι τόπον μηδὲν ὑπονοῶν ἄτοπον, κἀκεῖ φύλασσέ μοι τὴν χώραν, μή τινες εἰς αὐτὴν τῶν πολεμίων ἐμβάλωσιν. ἔστι δὲ καὶ τοῦτο συμμαχίας μέρος."},{"number":356,"text":"καὶ Δαυίδης μέν, ὡς ἐκέλευσεν ὁ τῶν Γιττῶν βασιλεύς, ἧκεν εἰς Σίκελλαν. καθʼ ὃν δὲ καιρὸν ἐξ αὐτῆς συμμαχήσων τοῖς Παλαιστίνοις ἀπῆλθε τὸ τῶν Ἀμαληκιτῶν ἔθνος ἐπελθὸν αἱρεῖ τὴν Σίκελλαν κατὰ κράτος, καὶ ἐμπρήσαντες καὶ πολλὴν λείαν ἄλλην ἔκ τʼ αὐτῆς ἐκείνης καὶ τῆς ἄλλης τῶν Παλαιστίνων χώρας λαβόντες ἀνεχώρησαν."},{"number":357,"text":"Ἐκπεπορθημένην δὲ τὴν Σίκελλαν καταλαβὼν ὁ Δαυίδης καὶ διηρπαγμένα πάντα καὶ τὰς γυναῖκας τὰς ἑαυτοῦ, δύο γὰρ ἦσαν, καὶ τὰς γυναῖκας τῶν ἑταίρων σὺν τοῖς τέκνοις ᾐχμαλωτισμένας, περιρρήγνυται εὐθὺς τὴν ἐσθῆτα."},{"number":358,"text":"κλαίων δὲ καὶ ὀδυρόμενος μετὰ τῶν φίλων ἐπὶ τοσοῦτον παρείθη τοῖς κακοῖς, ὥστε αὐτὸν ἐπιλιπεῖν ἤδη καὶ τὰ δάκρυα, κινδυνεῦσαι δὲ καὶ βληθεὶς ὑπὸ τῶν ἑταίρων ἀλγούντων ἐπὶ ταῖς αἰχμαλωσίαις τῶν γυναικῶν καὶ τῶν τέκνων ἀποθανεῖν· αὐτὸν γὰρ τῶν γεγονότων ᾐτιῶντο."},{"number":359,"text":"ἀνασχὼν δʼ ἐκ τῆς λύπης καὶ τὴν διάνοιαν πρὸς τὸν θεὸν ἀναστήσας παρεκάλεσε τὸν ἀρχιερέα Ἀβιάθαρον ἐνδύσασθαι τὴν ἱερατικὴν στολὴν καὶ ἐπερωτῆσαι τὸν θεὸν καὶ προφητεῦσαι, εἰ διώξαντι τοὺς Ἀμαληκίτας δίδωσι καταλαβεῖν καὶ σῶσαι μὲν τὰς γυναῖκας καὶ τὰ τέκνα, τιμωρήσασθαι δὲ τοὺς ἐχθρούς."},{"number":360,"text":"τοῦ δʼ ἀρχιερέως διώκειν κελεύσαντος ἐκπηδήσας μετὰ τῶν ἑξακοσίων ὁπλιτῶν εἵπετο τοῖς πολεμίοις· παραγενόμενος δʼ ἐπί τινα χειμάρρουν Βάσελον λεγόμενον καὶ πλανωμένῳ τινὶ περιπεσὼν Αἰγυπτίῳ μὲν τὸ γένος ὑπʼ ἐνδείας δὲ καὶ λιμοῦ παρειμένῳ, τρισὶ γὰρ ἡμέραις ἐν τῇ ἐρημίᾳ πλανώμενος ἄσιτος διεκαρτέρησε, πρῶτον αὐτὸν ποτῷ καὶ τροφῇ παραστησάμενος καὶ ἀναλαβὼν ἐπύθετο, τίς τε εἴη καὶ πόθεν."},{"number":361,"text":"ὁ δὲ γένος μὲν ἐσήμαινεν Αἰγύπτιος ὤν, καταλειφθῆναι δὲ ὑπὸ τοῦ δεσπότου κατʼ ἀρρωστίαν ἕπεσθαι μὴ δυνάμενον· ἐδήλου δʼ αὑτὸν τῶν καταπρησάντων καὶ διηρπακότων ἄλλα τε τῆς Ἰουδαίας καὶ τὴν Σίκελλαν εἶναι."},{"number":362,"text":"χρησάμενος οὖν ὁ Δαυίδης τούτῳ ἐπὶ τοὺς Ἀμαληκίτας ὁδηγῷ καὶ καταλαβὼν αὐτοὺς ἐπὶ γῆς ἐρριμμένους, καὶ τοὺς μὲν ἀριστῶντας, τοὺς δὲ καὶ μεθύοντας ἤδη καὶ λελυμένους ὑπὸ τοῦ οἴνου καὶ τῶν λαφύρων καὶ τῆς λείας ἀπολαύοντας, ἐπιπεσὼν αἰφνιδίως πολὺν αὐτῶν φόνον εἰργάσατο· γυμνοὶ γὰρ ὄντες καὶ μηδὲν προσδοκῶντες τοιοῦτον, ἀλλὰ πρὸς τὸ πιεῖν καὶ εὐωχεῖσθαι τετραμμένοι πάντες ἦσαν εὐκατέργαστοι."},{"number":363,"text":"καὶ οἱ μὲν αὐτῶν ἔτι τῶν τραπεζῶν παρακειμένων ἐπικαταλαμβανόμενοι παρʼ αὐταῖς ἀνῃροῦντο καὶ παρέσυρεν αὐτοῖς τὰ σιτία καὶ τὴν τροφὴν τὸ αἷμα, τοὺς δὲ δεξιουμένους ἀλλήλους ταῖς προπόσεσι διέφθειρεν, ἐνίους δὲ καὶ πρὸς ὕπνον ὑπὸ τοῦ ἀκράτου κατενηνεγμένους. ὁπόσοι δʼ ἔφθασαν περιθέμενοι τὰς πανοπλίας ἐξ ἐναντίας τʼ αὐτῷ στῆναι, τούτους οὐδὲν ἧττον εὐχερῶς τῶν γυμνῶν κατακειμένων ἀπέσφαττον."},{"number":364,"text":"διέμειναν δὲ οἱ σὺν τῷ Δαυίδῃ καὶ αὐτοὶ ἀναιροῦντες ἀπὸ πρώτης ὥρας ἕως ἑσπέρας, ὡς μὴ περιλειφθῆναι τῶν Ἀμαληκιτῶν πλείονας ἢ τετρακοσίους· καὶ οὗτοι δὲ δρομάσι καμήλοις ἐπιβάντες διέφυγον. ἀνέσωσε δὲ τἆλλα πάντα ἃ διήρπασαν αὐτῶν οἱ πολέμιοι καὶ τάς τε αὐτοῦ γυναῖκας καὶ τὰς τῶν ἑταίρων."},{"number":365,"text":"ὡς δὲ ἀναστρέφοντες ἧκον ἐπὶ τὸν τόπον, ἔνθα διακοσίους μὴ δυναμένους αὐτοῖς ἕπεσθαι καταλελοίπεσαν ἐπὶ τῶν σκευῶν, οἱ μὲν τετρακόσιοι τῆς μὲν ἄλλης ὠφελείας τε καὶ λείας οὐκ ἠξίουν αὐτοῖς ἀπομερίζειν· οὐ συνακολουθήσαντας γὰρ ἀλλὰ μαλακισθέντας περὶ τὴν δίωξιν ἀγαπήσειν ἀνασεσωσμένας τὰς γυναῖκας ἀπολαμβάνοντας ἔλεγον·"},{"number":366,"text":"Δαυίδης δὲ πονηρὰν καὶ ἄδικον αὐτῶν ταύτην ἀπέφηνε τὴν γνώμην· εἶναι γὰρ ἀξίους, τοῦ θεοῦ παρασχόντος αὐτοῖς ἀμύνασθαι μὲν τοὺς πολεμίους, κομίσασθαι δὲ πάντα τὰ αὑτῶν, πᾶσιν ἐξ ἴσου τοῖς συστρατευσαμένοις μερίζεσθαι τὴν ὠφέλειαν, καὶ ταῦτʼ ἐπὶ φυλακῇ τῶν σκευῶν μεμενηκότων."},{"number":367,"text":"καὶ ἐξ ἐκείνου νόμος οὗτος ἐκράτησε παρʼ αὐτοῖς, ἵνα ταὐτὰ τοῖς μαχομένοις λαμβάνωσιν οἱ τὰ σκεύη φυλάσσοντες. γενόμενος δʼ ἐν Σικέλλα Δαυίδης διέπεμψε πᾶσι τοῖς ἐν τῇ Ἰούδα φυλῇ συνήθεσι καὶ φίλοις ἀπομοίρας τῶν λαφύρων. καὶ τὰ μὲν περὶ τὴν Σικέλλων πόρθησιν καὶ Ἀμαληκιτῶν ἀναίρεσιν οὕτως ἐγένετο."},{"number":368,"text":"Τῶν δὲ Παλαιστίνων συμβαλόντων καὶ καρτερᾶς μάχης γενομένης νικῶσιν οἱ Παλαιστῖνοι καὶ πολλοὺς ἀναιροῦσι τῶν ἐναντίων, Σαοῦλος δὲ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς καὶ οἱ παῖδες αὐτοῦ γενναίως ἀγωνιζόμενοι καὶ πάσῃ προθυμίᾳ χρώμενοι, ὡς ἐν μόνῳ τῷ καλῶς ἀποθανεῖν καὶ παραβόλως διακινδυνεῦσαι τοῖς πολεμίοις τῆς ὅλης αὐτοῖς δόξης ἀποκειμένης, οὐδὲν γὰρ τούτου περισσότερον εἶχον,"},{"number":369,"text":"ἐπιστρέφουσι πᾶσαν εἰς αὑτοὺς τὴν τῶν ἐχθρῶν φάλαγγα καὶ περικυκλωθέντες ἀποθνήσκουσι πολλοὺς τῶν Παλαιστίνων καταβαλόντες. ἦσαν δὲ οἱ παῖδες Ἰωνάθης καὶ Ἀμινάδαβος καὶ Μέλχισος. τούτων πεσόντων τρέπεται τὸ τῶν Ἑβραίων πλῆθος καὶ ἀκοσμία καὶ σύγχυσις γίνεται καὶ φόνος ἐπικειμένων τῶν πολεμίων."},{"number":370,"text":"Σαοῦλος δὲ φεύγει τὸ καρτερὸν ἔχων περὶ αὑτόν, καὶ τῶν Παλαιστίνων ἐπιπεμψάντων ἀκοντιστὰς καὶ τοξότας πάντας μὲν ἀποβάλλει πλὴν ὀλίγων, αὐτὸς δὲ λαμπρῶς ἀγωνισάμενος καὶ πολλὰ τραύματα λαβών, ὡς μηκέτι διακαρτερεῖν μηδʼ ἀντέχειν ταῖς πληγαῖς, ἀποκτεῖναι μὲν αὑτὸν ἠσθένει, κελεύει δὲ τὸν ὁπλοφόρον σπασάμενον τὴν ῥομφαίαν ταύτην αὐτοῦ διελάσαι, πρὶν ζῶντα συλλαβεῖν αὐτὸν τοὺς πολεμίους."},{"number":371,"text":"μὴ τολμῶντος δὲ τοῦ ὁπλοφόρου κτεῖναι τὸν δεσπότην, αὐτὸς τὴν ἰδίαν σπασάμενος καὶ στήσας ἐπὶ τὴν ἀκμὴν ῥίπτει κατʼ αὐτῆς ἑαυτόν· ἀδυνατῶν δὲ μήθʼ ἵστασθαι μήτʼ ἐπερείσας διαβαλεῖν αὑτοῦ τὸν σίδηρον ἐπιστρέφεται, καὶ νεανίσκου τινὸς ἑστῶτος πυθόμενος τίς εἴη καὶ μαθὼν ὡς Ἀμαληκίτης ἐστὶ παρεκάλεσεν ἐπερείσαντα τὴν ῥομφαίαν διὰ τὸ μὴ ταῖς χερσὶν αὐτὸν δύνασθαι παρασχεῖν αὐτῷ τελευτὴν ὁποίαν αὐτὸς βούλεται."},{"number":372,"text":"ποιήσας δὲ τοῦτο καὶ περιελόμενος τὸν περὶ τὸν βραχίονα αὐτοῦ χρυσὸν καὶ τὸν βασιλικὸν στέφανον ἐκποδὼν ἐγένετο. θεασάμενος δʼ ὁ ὁπλοφόρος Σαοῦλον ἀνῃρημένον ἀπέκτεινεν ἑαυτόν· διεσώθη δʼ οὐδεὶς τῶν σωματοφυλάκων τοῦ βασιλέως, ἀλλὰ πάντες ἔπεσον περὶ τὸ καλούμενον Γελβουὲ ὄρος."},{"number":373,"text":"ἀκούσαντες δὲ τῶν Ἑβραίων οἱ τὴν κοιλάδα πέραν τοῦ Ἰορδάνου κατοικοῦντες καὶ οἱ ἐν τῷ πεδίῳ τὰς πόλεις ἔχοντες, ὅτι Σαοῦλος πέπτωκε καὶ οἱ παῖδες αὐτοῦ, καὶ τὸ σὺν αὐτῷ πλῆθος ἀπόλωλε, καταλιπόντες τὰς ἑαυτῶν πόλεις εἰς ὀχυρωτάτας ἔφυγον. οἱ δὲ Παλαιστῖνοι τὰς καταλελειμμένας ἐρήμους εὑρόντες κατῴκησαν."},{"number":374,"text":"Τῇ δʼ ἐπιούσῃ σκυλεύοντες οἱ Παλαιστῖνοι τοὺς τῶν πολεμίων νεκροὺς ἐπιτυγχάνουσι τοῖς Σαούλου καὶ τῶν παίδων αὐτοῦ σώμασι καὶ σκυλεύσαντες ἀποτέμνουσιν αὐτῶν τὰς κεφαλάς, καὶ κατὰ πᾶσαν περιήγγειλαν τὴν χώραν πέμψαντες, ὅτι πεπτώκασιν οἱ πολέμιοι· καὶ τὰς μὲν πανοπλίας αὐτῶν ἀνέθηκαν εἰς τὸ Ἀστάρτειον ἱερόν, τὰ δὲ σώματα ἀνεσταύρωσαν πρὸς τὰ τείχη τῆς Βηθσὰν πόλεως, ἣ νῦν Σκυθόπολις καλεῖται."},{"number":375,"text":"ἐπεὶ δὲ ἤκουσαν οἱ ἐν Ἰάβει πόλει τῆς Γαλααδίτιδος κατοικοῦντες, ὅτι λελώβηνται τὸν Σαούλου νεκρὸν καὶ τοὺς τῶν παίδων αὐτοῦ, δεινὸν ἡγησάμενοι περιϊδεῖν ἀκηδεύτους ἐξελθόντες οἱ ἀνδρειότατοι καὶ τόλμῃ διαφέροντες, ἡ δὲ πόλις αὕτη καὶ σώμασιν ἀλκίμους καὶ ψυχαῖς φέρει, καὶ διʼ ὅλης τῆς νυκτὸς ὁδεύσαντες ἦλθον εἰς Βηθσάν,"},{"number":376,"text":"καὶ προσελθόντες τῷ τείχει τῶν πολεμίων καὶ καθελόντες τὸ σῶμα Σαούλου καὶ τὰ τῶν παίδων αὐτοῦ κομίζουσιν εἰς Ἰάβησαν μηδὲ τῶν πολεμίων αὐτοὺς κωλῦσαι τολμησάντων διὰ τὴν ἀνδρείαν."},{"number":377,"text":"οἱ δὲ Ἰαβησηνοὶ πανδημεὶ κλαύσαντες θάπτουσι τὰ σώματα ἐν τῷ καλλίστῳ τῆς χώρας τόπῳ Ἀρούρης λεγομένῳ, καὶ πένθος ἐφʼ ἡμέρας ἑπτὰ σὺν γυναιξὶ καὶ τέκνοις ἐπʼ αὐτοῖς ἦγον κοπτόμενοι καὶ θρηνοῦντες τὸν βασιλέα καὶ τοὺς παῖδας αὐτοῦ μήτε τροφῆς μήτε ποτοῦ γευσάμενοι."},{"number":378,"text":"Τοῦτο Σαοῦλος τὸ τέλος ἔσχε προφητεύσαντος Σαμουήλου διὰ τὸ παρακοῦσαι τοῦ θεοῦ τῶν ἐπʼ Ἀμαληκίταις ἐντολῶν, καὶ ὅτι τὴν Ἀβιμελέχου τοῦ ἀρχιερέως γενεὰν καὶ Ἀβιμέλεχον αὐτὸν καὶ τὴν τῶν ἀρχιερέων πόλιν ἀνεῖλεν. ἐβασίλευσε δὲ Σαμουήλου ζῶντος ἔτη ὀκτὼ πρὸς τοῖς δέκα, τελευτήσαντος δὲ δύο καὶ εἴκοσι. καὶ Σαοῦλος μὲν οὕτω κατέστρεψε τὸν βίον."}]},"count":378};a[7]={"book":7,"title":"Τάδε ἔνεστιν ἐν τῇ ἑβδόμῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ὡς Δαυίδης μὲν τῆς μιᾶς φυλῆς ἐβασίλευσεν ἐν Γιβρῶνι τῇ πόλει, τοῦ δ' ἄλλου πλήθους ὁ Σαούλου παῖς.\n\nβ. ὅτι τούτου φονευθέντος ἐξ ἐπιβουλῆς φίλων ἅπασιν τὴν βασιλείαν Δαυίδης παρέλαβεν.\n\nγ. ὡς πολιορκήσας Ἱεροσόλυμα Δαυίδης καὶ λαβὼν τὴν πόλιν ἐξέβαλε μὲν ἐξ αὐτῆς τοὺς Χαναναίους, ἐνῴκισε δὲ εἰς αὐτὴν Ἰουδαίους.\n\nδ. ὅτι στρατεύσαντας ἐπ' αὐτὸν δὶς Παλαιστίνους ἐν Ἱεροσολύμοις ἐνίκησεν.\n\nε. ἡ γενομένη πρὸς Εἴρωμον τὸν Τυρίων βασιλέα καὶ Δαυίδου φιλία.\n\nϛ. ὡς τοῖς πέριξ ἔθνεσι στρατεύσας Δαυίδης καὶ χειρωσάμενος φόρον ἐπέταξεν αὑτῷ τελεῖν.\n\nζ. ἡ γενομένη πρὸς Δαμασκηνοὺς Δαυίδῃ μάχη καὶ νίκη.\n\nη. πῶς ἐπὶ τοὺς Μεσοποταμίους στρατεύσας ἐκράτησεν αὐτῶν.\n\nθ. ὅτι τῶν περὶ τὴν οἰκίαν αὐτῷ στασιασάντων ὑπὸ τοῦ παιδὸς ἐξεβλήθη τῆς ἀρχῆς εἰς τὴν πέραν τοῦ Ἰορδάνου.\n\nι. ὡς στρατεύσας Ἀψάλωμος ἐπὶ τὸν πατέρα Δαυίδην ἀπώλετο σὺν τῷ στρατῷ.\n\nια. πῶς εἰς τὴν βασιλείαν πάλιν κατῆλθε καὶ ζήσας εὐδαιμόνως ἔτι περιὼν Σολόμωνα τὸν υἱὸν ἀπέδειξε βασιλέα.\n\nιβ. τελευτὴ Δαυίδου καταλιπόντος τῷ παιδὶ πολλὴν ὕλην ἀργύρου τε καὶ χρυσοῦ καὶ λιθίας εἰς τὴν οἰκοδομὴν τοῦ ναοῦ.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν τεσσαράκοντα."},"chapters":{"1":[{"number":1,"text":"Συνέβη δὲ ταύτην γενέσθαι τὴν μάχην καθʼ ἣν ἡμέραν καὶ Δαυίδης τοὺς Ἀμαληκίτας νικήσας εἰς Σίκελλαν ὑπέστρεψεν. ἤδη δὲ αὐτοῦ δύο ἡμέρας ἔχοντος ἐν τῇ Σικέλλα τῇ τρίτῃ παραγίνεται διασωθεὶς ἐκ τῆς μάχης τῆς πρὸς Παλαιστίνους ὁ τὸν Σαοῦλον ἀνελὼν τήν τε ἐσθῆτα περιερρηγμένος καὶ τὴν κεφαλὴν τέφρᾳ περιχεάμενος."},{"number":2,"text":"καὶ προσκυνήσας αὐτὸν πυνθανομένῳ, πόθεν ἥκοι τοιοῦτος, ἀπὸ τῆς τῶν Ἰσραηλιτῶν μάχης ἔλεγε· γενέσθαι δʼ ἀτυχὲς αὐτῆς τὸ τέλος ἐδήλου πολλῶν μὲν ἀναιρεθεισῶν τοῖς Ἑβραίοις μυριάδων, πεσόντος δὲ καὶ τοῦ βασιλέως αὐτῶν Σαούλου μετὰ τῶν τέκνων·"},{"number":3,"text":"ταῦτα δὲ σημαίνειν ἔφασκεν αὐτὸς παρατυχὼν τῇ τροπῇ τῶν Ἑβραίων καὶ τῷ βασιλεῖ πεφευγότι παρών, ὃν καὶ κτεῖναι μέλλοντα ὑπὸ τῶν πολεμίων λαμβάνεσθαι παρακληθεὶς αὐτὸς ὡμολόγει· τῇ ῥομφαίᾳ γὰρ αὐτὸν ἐπιπεσόντα διὰ τὴν τῶν τραυμάτων ὑπερβολὴν αὑτὸν ἀσθενῆσαι κατεργάσασθαι."},{"number":4,"text":"καὶ σύμβολα τῆς ἀναιρέσεως ἐπεδείκνυεν τόν τε περὶ τοῖς βραχίοσι χρυσὸν τοῦ βασιλέως καὶ τὸν στέφανον, ἃ περιδύσας τὸν Σαούλου νεκρὸν κομίσειεν αὐτῷ. Δαυίδης δὲ μηκέτʼ ἀπιστεῖν ἔχων ἀλλʼ ἐναργῆ τεκμήρια τοῦ Σαούλου θανάτου βλέπων καταρρηγνύει μὲν τὴν ἐσθῆτα, κλαίων δὲ καὶ ὀδυρόμενος μετὰ τῶν ἑταίρων ὅλην διεκαρτέρησε τὴν ἡμέραν."},{"number":5,"text":"ποιεῖ δʼ αὐτῷ τὴν λύπην χαλεπωτέραν ὁ Σαούλου παῖς Ἰωνάθης πιστότατός τε ὢν φίλος αὐτῷ καὶ σωτηρίας αἴτιος γεγενημένος. τοσαύτην δʼ ἐπεδείξατο τὴν ἀρετὴν καὶ τὴν πρὸς τὸν Σαοῦλον εὔνοιαν, ὡς μὴ μόνον ἐπὶ τεθνηκότι χαλεπῶς ἐνεγκεῖν πολλάκις ὑπʼ αὐτοῦ κινδυνεύσας ἀφαιρεθῆναι τὸν βίον, ἀλλὰ καὶ τὸν ἀποκτείναντα κολάσαι."},{"number":6,"text":"φήσας γὰρ πρὸς αὐτὸν, ὡς αὐτὸς γένοιτο κατήγορος ἀνελὼν τὸν βασιλέα, καὶ μαθών, ὡς εἴη πατρὸς Ἀμαληκίτου γένος, ἐκέλευσεν αὐτὸν ἀπολέσθαι. ἔγραψε δὲ καὶ θρήνους καὶ ἐπιταφίους ἐπαίνους Σαούλου καὶ Ἰωνάθου, οἳ καὶ μέχρις ἐμοῦ διαμένουσιν."},{"number":7,"text":"Ἐπεὶ δὲ τούτοις ἐξετίμησε τὸν βασιλέα παυσάμενος τοῦ πένθους ἤρετο τὸν θεὸν διὰ τοῦ προφήτου, τίνα δίδωσιν αὐτῷ κατοικῆσαι πόλιν τῆς Ἰούδα καλουμένης φυλῆς. φήσαντος δʼ αὐτοῦ διδόναι Γιβρῶνα καταλιπὼν τὴν Σίκελλαν εἰς ἐκείνην παραγίνεται τάς τε γυναῖκας ἐπαγόμενος τὰς αὑτοῦ, δύο δὲ ἦσαν, καὶ τοὺς ὁπλίτας τοὺς σὺν αὐτῷ."},{"number":8,"text":"συνελθὼν δὲ πρὸς αὐτὸν πᾶς ὁ τῆς φυλῆς τῆς προειρημένης λαὸς ἀποδείκνυσιν αὐτὸν βασιλέα. ἀκούσας δʼ ὅτι τὸν Σαοῦλον καὶ τοὺς υἱοὺς αὐτοῦ θάψειαν οἱ ἐν Ἰαβησῷ τῆς Γαλααδίτιδος κατοικοῦντες, ἔπεμψε πρὸς αὐτοὺς ἐπαινῶν καὶ ἀποδεχόμενος αὐτῶν τὸ ἔργον, καὶ χάριτας ἀποδώσειν ἀντὶ τῆς πρὸς τοὺς τεθνηκότας σπουδῆς ὑπισχνούμενος, ἅμα δὲ καὶ δηλῶν ὡς ἡ Ἰούδα φυλὴ κεχειροτόνηκεν αὐτὸν βασιλέα."},{"number":9,"text":"Ὁ δὲ τοῦ Σαούλου μὲν ἀρχιστράτηγος Ἀβεννῆρος Νήρου δὲ παῖς ἀνὴρ δραστήριος καὶ ἀγαθὸς τὴν φύσιν, ὡς ἔγνω πεσόντα τὸν βασιλέα καὶ τὸν Ἰωνάθην καὶ τοὺς δύο τοὺς ἄλλους αὐτοῦ παῖδας, ἐπειχθεὶς εἰς τὴν παρεμβολὴν καὶ τὸν περιλειπόμενον ἐξαρπάσας υἱὸν αὐτοῦ, Ἰέβοσθος δʼ ἐκαλεῖτο, διαβιβάζει πρὸς τοὺς πέραν τοῦ Ἰορδάνου καὶ παντὸς ἀποδείκνυσι τοῦ πλήθους βασιλέα πάρεξ τῆς Ἰούδα φυλῆς."},{"number":10,"text":"βασίλειον δʼ ἐποίησεν αὐτῷ τὴν κατὰ μὲν τὴν ἐπιχώριον γλῶτταν Μάναλιν, κατὰ δὲ τὴν Ἑλλήνων Παρεμβολὰς λεγομένην· ὥρμησε δʼ ἐκεῖθεν Ἀβεννῆρος μετὰ στρατιᾶς ἐπιλέκτου συμβαλεῖν τοῖς ἐκ τῆς Ἰούδα φυλῆς προαιρούμενος· ὤργιστο γὰρ αὐτοῖς βασιλέα τὸν Δαυίδην κεχειροτονηκόσιν."},{"number":11,"text":"ἀπήντησε δʼ αὐτῷ πεμφθεὶς ὑπὸ Δαυίδου Σαρουίας μὲν παῖς, πατρὸς δὲ Σουρί, ἐκ δὲ τῆς ἀδελφῆς τῆς ἐκείνου γεγονὼς αὐτῷ Ἰώαβος ἀρχιστράτηγος ὢν αὐτοῦ, μετὰ καὶ τῶν ἀδελφῶν Ἀβεσσαίου καὶ Ἀσαήλου καὶ πάντων τῶν Δαυίδου ὁπλιτῶν. καὶ περιτυχὼν ἐπί τινος κρηνίδος ἐν Γαβαῶ πόλει παρατάσσεται πρὸς μάχην."},{"number":12,"text":"τοῦ δʼ Ἀβεννήρου φήσαντος πρὸς αὐτὸν βούλεσθαι μαθεῖν, πότερος αὐτῶν ἀνδρειοτέρους στρατιώτας ἔχει, συντίθεται παρʼ ἀμφοτέρων δυοκαίδεκα μαχησομένους συμβαλεῖν. προελθόντες τοίνυν εἰς τὸ μεταξὺ τῶν παρατάξεων οἱ πρὸς τὴν μάχην ὑφʼ ἑκατέρων τῶν στρατηγῶν ἐξειλεγμένοι καὶ τὰς αἰχμὰς ἐπʼ ἀλλήλους ἀφέντες σπῶνται τὰς μαχαίρας καὶ τῶν κεφαλῶν ἐλλαμβανόμενοι κατέχοντες αὑτοὺς ἔπαιον εἰς τὰς πλευρὰς καὶ τὰς λαγόνας ἀλλήλους ταῖς ῥομφαίαις, ἕως οὗ πάντες ὥσπερ ἐκ συνθήματος ἀπώλοντο."},{"number":13,"text":"πεσόντων δὲ τούτων συνέρρηξε καὶ ἡ λοιπὴ στρατιά, καὶ καρτερᾶς τῆς μάχης γενομένης ἡττήθησαν οἱ τοῦ Ἀβεννήρου· καὶ τραπέντας οὐκ ἀνίει διώκων Ἰώαβος, ἀλλʼ αὐτός τε ἐπέκειτο παρακελευόμενος τοὺς ὁπλίτας ἐκ ποδὸς ἕπεσθαι καὶ μὴ κάμνειν ἀναιροῦντας,"},{"number":14,"text":"οἵ τε ἀδελφοὶ προθύμως ἠγωνίσαντο, καὶ διαφανέστερος τῶν ἄλλων μάλιστα ὁ νεώτερος Ἀσάηλος, ὃς ἐπὶ ποδῶν ὠκύτητι κλέος εἶχεν· οὐ γὰρ ἀνθρώπους ἐνίκα μόνον, ἀλλὰ καὶ ἵππῳ καταστάντα εἰς ἅμιλλαν λέγουσι παραδραμεῖν, καὶ τὸν Ἀβεννῆρον ἐδίωκεν ὑπὸ ῥύμης καὶ τῆς ἐπʼ ὀρθὸν φορᾶς εἰς οὐδέτερον ἐγκλιθεὶς τῶν μερῶν."},{"number":15,"text":"ἐπιστραφέντος δὲ τοῦ Ἀβεννήρου καὶ κατασοφίζεσθαι τὴν ὁρμὴν αὐτοῦ πειρωμένου καὶ ποτὲ μὲν εἰπόντος ἑνὸς τῶν αὐτοῦ στρατιωτῶν ἀφέμενος τῆς διώξεως ἀφελέσθαι τὴν πανοπλίαν, πάλιν δʼ ὡς οὐκ ἔπειθε τοῦτο ποιεῖν κατασχεῖν αὑτὸν καὶ μὴ διώκειν παραινοῦντος, μὴ κτείνας αὐτὸν ἀπολέσῃ τὴν πρὸς τὸν ἀδελφὸν αὐτοῦ παρρησίαν, οὐ προσιέμενον δὲ τοὺς λόγους, ἀλλʼ ἐπιμείναντα τὴν δίωξιν φεύγων ὡς εἶχε τὸ δόρυ πλήξας εἰς τοὐπίσω καιρίως παραχρῆμʼ ἀπέκτεινεν."},{"number":16,"text":"οἱ δὲ μετʼ αὐτοῦ διώκοντες τὸν Ἀβεννῆρον ὡς ἦλθον ἐπὶ τὸν τόπον, οὗ κεῖσθαι συνέβαινε τὸν Ἀσάηλον, περιστάντες τὸν νεκρὸν οὐκέτι τοὺς πολεμίους ἐδίωκον· ὁ δὲ Ἰώαβος αὐτὸς καὶ ὁ ἀδελφὸς αὐτοῦ Ἀβεσσαῖος παραδραμόντες τὸ πτῶμα καὶ τῆς πλείονος ἐπὶ τὸν Ἀβεννῆρον σπουδῆς αἰτίαν τὴν ὑπὲρ τοῦ τετελευτηκότος ὀργὴν λαβόντες, ἀπίστῳ τάχει καὶ προθυμίᾳ χρώμενοι μέχρι τόπου τινός, Ὄμματον καλοῦσιν, ἐδίωξαν τὸν Ἀβεννῆρον ἤδη περὶ δυσμὰς ὄντος ἡλίου."},{"number":17,"text":"ἀναβὰς δʼ ἐπί τινα βουνόν, ὅς ἐστιν ἐν ἐκείνῳ τῷ τόπῳ μετὰ τῆς Βενιαμίτιδος φυλῆς, αὐτούς τε κατεσκέπτετο καὶ τὸν Ἀβεννῆρον. τούτου δὲ ἀνακεκραγότος καὶ φήσαντος, μὴ δεῖν ἄνδρας ὁμοφύλους εἰς ἔριδα καὶ μάχην παροξύνειν, ἁμαρτεῖν δὲ καὶ τὸν ἀδελφὸν αὐτοῦ Ἀσάηλον, ὃς παραινοῦντος μὴ διώκειν οὐκ ἐπείσθη καὶ διὰ τοῦτο βληθεὶς ἀπέθανε, συμφρονήσας καὶ παράκλησιν ἡγησάμενος τούτους τοὺς λόγους ὁ Ἰώαβος ἀνακαλεῖ τῇ σάλπιγγι σημάνας τοὺς στρατιώτας καὶ τῆς ἐπὶ πολὺ διώξεως ἐπισχών."},{"number":18,"text":"καὶ οὗτος μὲν ἐπʼ ἐκείνου καταστρατοπεδεύεται τοῦ τόπου τὴν νύκτα ταύτην, Ἀβεννῆρος δὲ διʼ ὅλης αὐτῆς ὁδεύσας καὶ περαιωσάμενος τὸν Ἰόρδανον ποταμὸν ἀφικνεῖται πρὸς τὸν τοῦ Σαούλου παῖδα εἰς τὰς Παρεμβολὰς Ἰέβωσθον. τῇ δʼ ἐχομένῃ τοὺς νεκροὺς ὁ Ἰώαβος ἐξαριθμήσας ἅπαντας ἐκήδευσεν."},{"number":19,"text":"ἔπεσον δὲ τῶν μὲν Ἀβεννήρου στρατιωτῶν ὡς τριακόσιοι καὶ ἑξήκοντα, τῶν δὲ Δαυίδου δέκα πρὸς τοῖς ἐννέα καὶ Ἀσάηλος, οὗ τὸ σῶμα κομίσαντες ἐκεῖθεν Ἰώαβος καὶ Ἀβεσσαῖος εἰς Βηθλεέμην καὶ θάψαντες ἐν τῷ πατρῴῳ μνήματι πρὸς Δαυίδην εἰς Γιβρῶνα παρεγένοντο."},{"number":20,"text":"ἤρξατο μὲν οὖν ἐξ ἐκείνου τοῦ χρόνου τοῖς Ἑβραίοις ἐμφύλιος πόλεμος καὶ διέμεινεν ἄχρι πολλοῦ, τῶν μὲν μετὰ Δαυίδου κρειττόνων ἀεὶ γινομένων καὶ πλεῖον ἐν τοῖς κινδύνοις φερομένων, τοῦ δὲ Σαούλου παιδὸς καὶ τῶν ὑπηκόων αὐτοῦ κατὰ πᾶσαν σχεδὸν ἡμέραν ἐλαττουμένων."},{"number":21,"text":"Ἐγένοντο δὲ κατὰ τοῦτον τὸν καιρὸν καὶ παῖδες Δαυίδῃ τὸν ἀριθμὸν ἓξ ἐκ γυναικῶν τοσούτων, ὧν ὁ μὲν πρεσβύτατος ἐκ μητρὸς Ἀχίνας γενόμενος Ἀμνὼν ἐκλήθη, ὁ δὲ δεύτερος ἐκ γυναικὸς Ἀβιγαίας Δανίηλος, τῷ τρίτῳ δʼ ἐκ τῆς Θολομαίου θυγατρὸς Μαχάμης φύντι τοῦ Γεσσιρῶν βασιλέως Ἀψάλωμος ὄνομα, τὸν δὲ τέταρτον Ἀδωνίαν ἐκ γυναικὸς Ἀήθης προσηγόρευσε, τὸν πέμπτον δὲ Σαφατίαν τῆς Ἀβιτάλης καὶ τὸν ἕκτον Γεθερσὰν τῆς Γαλαὰδ ἐπωνόμασε."},{"number":22,"text":"τοῦ δʼ ἐμφυλίου πολέμου συνεστῶτος καὶ συμπιπτόντων εἰς ἔργα καὶ μάχην πυκνῶς μεθʼ ἑκατέρου τῶν βασιλέων, Ἀβεννῆρος ὁ τοῦ Σαούλου παιδὸς ἀρχιστράτηγος συνετὸς ὢν καὶ σφόδρα εὔνουν ἔχων τὸ πλῆθος πάντας συμμεῖναι τῷ Ἰεβόσθῳ παρεσκεύασε· καὶ διέμειναν ἱκανὸν χρόνον τὰ ἐκείνου φρονοῦντες."},{"number":23,"text":"ὕστερον δʼ ἐν ἐγκλήματι γενόμενος Ἀβεννῆρος καὶ λαβὼν αἰτίαν ὡς συνέλθοι τῇ Σαούλου παλλακῇ Ῥαισφᾶ μὲν τοὔνομα Σιβάτου δὲ θυγατρί, καὶ καταμεμφθεὶς ὑπὸ Ἰεβώσθου περιαλγήσας καὶ θυμωθείς, ὡς οὐ δικαίων τῶν παρʼ αὐτοῦ τυγχάνοι πάσῃ προνοίᾳ περὶ αὐτὸν χρώμενος, ἠπείλησε μὲν τὴν βασιλείαν εἰς Δαυίδην περιστήσειν, ἐπιδείξειν δὲ ὡς οὐχὶ διὰ τὴν ἰδίαν ῥώμην καὶ σύνεσιν ἄρχοι τῶν πέραν Ἰορδάνου, διὰ δὲ τὴν αὐτοῦ στρατηγίαν τε καὶ πίστιν."},{"number":24,"text":"καὶ πέμψας εἰς Γιβρῶνα παρὰ Δαυίδην λαβεῖν ὅρκους τε καὶ πίστεις ἠξίου, ἦ μὴν ἕξειν αὐτὸν ἑταῖρον καὶ φίλον ἀναπείσαντα τὸν λαὸν τοῦ Σαούλου μὲν ἀποστῆναι παιδός, αὐτὸν δὲ ἀποδείξαντα πάσης τῆς χώρας βασιλέα."},{"number":25,"text":"τοῦ δὲ Δαυίδου ποιησαμένου τὰς ὁμολογίας, ἥσθη γὰρ ἐφʼ οἷς Ἀβεννῆρος διεπρεσβεύσατο πρὸς αὐτόν, καὶ πρῶτον τεκμήριον παρασχεῖν τῶν συνθηκῶν ἀξιώσαντος ἀνασώσαντα πρὸς αὐτὸν Μελχάλην τὴν γυναῖκα μεγάλοις ὠνηθεῖσαν ὑπʼ αὐτοῦ κινδύνοις καὶ Παλαιστίνων κεφαλαῖς ἑξακοσίαις, ἃς ὑπὲρ αὐτῆς ἐκόμισε τῷ πατρὶ Σαούλῳ,"},{"number":26,"text":"πέμπει μὲν αὐτῷ τὴν Μελχάλην ἀποσπάσας Ὀφελτίου τοῦ τότε συνοικοῦντος αὐτῇ, πρὸς τοῦτο καὶ Ἰεβώσθου συμπράξαντος· ἐγεγράφει γὰρ αὐτῷ Δαυίδης τὴν γυναῖκα δικαίως ἀπολαβεῖν· συγκαλέσας δὲ τοὺς γεγηρακότας τοῦ πλήθους καὶ ταξιάρχους καὶ χιλιάρχους λόγους ἐποιήσατο πρὸς αὐτούς,"},{"number":27,"text":"ὡς ἔχοντας ἑτοίμως ἀποστῆναι μὲν Ἰεβώσθου Δαυίδῃ δὲ προσθέσθαι ταύτης ἀποστρέψειε τῆς ὁρμῆς, νῦν μέντοι γε ἐπιτρέποι χωρεῖν ᾗ βούλονται· καὶ γὰρ εἰδέναι τὸν θεὸν διὰ Σαμουήλου τοῦ προφήτου Δαυίδην χειροτονήσαντα πάντων Ἑβραίων βασιλέα, προειπεῖν δʼ ὅτι Παλαιστίνους ἐκεῖνος αὐτὸς τιμωρήσεται καὶ ποιήσει κρατήσας ὑποχειρίους."},{"number":28,"text":"ταῦτʼ ἀκούσαντες οἱ πρεσβύτεροι καὶ ἡγεμόνες, ὡς τὴν Ἀβεννήρου γνώμην ᾗ πρότερον εἶχον αὐτοὶ περὶ τῶν πραγμάτων σύμφωνον προσέλαβον, τὰ Δαυίδου φρονεῖν μετεβάλοντο."},{"number":29,"text":"πεισθέντων δὲ τούτων Ἀβεννῆρος συγκαλεῖ τὴν Βενιαμιτῶν φυλήν, οἱ γὰρ ἐκ ταύτης ἅπαντες Ἰεβώσθου σωματοφύλακες ἦσαν, καὶ ταὐτὰ πρὸς αὐτοὺς διαλεχθείς, ἐπειδὴ μὴ ἀντικρούοντας ἑώρα, προστιθεμένους δʼ οἷς ἐβούλετο, παραλαβὼν ὡς εἴκοσι τῶν ἑταίρων ἧκε πρὸς Δαυίδην τοὺς ὅρκους παρʼ αὐτοῦ ληψόμενος αὐτός, πιστότερα γὰρ τῶν διʼ ἄλλου πραττομένων ὅσα διʼ αὑτῶν ἕκαστοι ποιοῦμεν εἶναι δοκεῖ, καὶ προσέτι τοὺς γενομένους αὐτῷ λόγους πρός τε τοὺς ἡγεμόνας καὶ πρὸς τὴν φυλὴν ἅπασαν σημανῶν."},{"number":30,"text":"ὑποδεξαμένου δʼ αὐτὸν φιλοφρόνως καὶ λαμπρᾷ καὶ πολυτελεῖ τραπέζῃ ξενίσαντος ἐπὶ πολλὰς ἡμέρας, ἠξίωσεν ἀφεθεὶς ἀγαγεῖν τὸ πλῆθος, ἵνα παρόντι καὶ βλεπομένῳ παραδῶσι τὴν ἀρχήν."},{"number":31,"text":"Ἐκπέμψαντος δὲ τοῦ Δαυίδου τὸν Ἀβεννῆρον οὐδὲ ὀλίγον διαλιπὼν εἰς Γιβρῶνα ἧκεν Ἰώαβος ὁ ἀρχιστράτηγος αὐτοῦ, καὶ μαθών, ὡς εἴη παρὼν πρὸς αὐτὸν Ἀβεννῆρος καὶ μικρὸν ἔμπροσθεν ἀπηλλαγμένος ἐπὶ συνθήκαις καὶ ὁμολογίαις τῆς ἡγεμονίας, δείσας μὴ τὸν μὲν ἐν τιμῇ καὶ τῇ πρώτῃ ποιήσεται τάξει συνεργόν τε τῆς βασιλείας ἐσόμενον καὶ τἆλλα δεινὸν ὄντα συνιδεῖν πράγματα καὶ τοὺς καιροὺς ὑποδραμεῖν, αὐτὸς δʼ ἐλαττωθείη καὶ τῆς στρατηγίας ἀφεθείη, κακοῦργον καὶ πονηρὰν ὁδὸν ἄπεισι."},{"number":32,"text":"καὶ πρῶτον μὲν ἐπιχειρεῖ διαβαλεῖν αὐτὸν πρὸς τὸν βασιλέα φυλάττεσθαι παραινῶν καὶ μὴ προσέχειν οἷς Ἀβεννῆρος συντίθεται· πάντα γὰρ ποιεῖν αὐτὸν ἐπὶ τῷ βεβαιώσασθαι τῷ Σαούλου παιδὶ τὴν ἡγεμονίαν· ἐπὶ δὲ ἀπάτῃ καὶ δόλῳ πρὸς αὐτὸν ἐλθόντα μεθʼ ἧς ἐβούλετο νῦν ἐλπίδος καὶ οἰκονομίας τῶν κατασκευαζομένων ἀπελθεῖν."},{"number":33,"text":"ὡς δʼ οὐκ ἔπειθε τὸν Δαυίδην τούτοις οὐδὲ παροξυνόμενον ἑώρα, τρέπεται ταύτης τολμηροτέραν ὁδὸν καὶ κρίνας Ἀβεννῆρον ἀποκτεῖναι πέμπει τοὺς ἐπιδιώξοντας, οἷς καταλαβοῦσι προσέταξεν αὐτὸν καλεῖν ἐκ τοῦ Δαυίδου ὀνόματος, ὡς ἔχοντος αὐτοῦ τινα περὶ τῶν πραγμάτων πρὸς αὐτὸν ἃ μὴ διεμνημόνευσε παρόντος εἰπεῖν."},{"number":34,"text":"Ἀβεννῆρος δʼ ὡς ἤκουσε τὰ παρὰ τῶν ἀγγέλων, κατέλαβον αὐτὸν ἐν τόπῳ τινὶ Βησηρᾶ καλουμένῳ ἀπέχοντι τῆς Γιβρῶνος σταδίους εἴκοσι, μηδὲν ὑπιδόμενος τῶν συμβησομένων ὑπέστρεψεν. ἀπαντήσας δʼ αὐτῷ πρὸς τῇ πύλῃ Ἰώαβος καὶ δεξιωσάμενος ὡς μάλιστʼ εὔνους καὶ φίλος, ὑποκρίνονται γὰρ ἱκανῶς πολλάκις εἰς τὸ ἀνύποπτον τῆς ἐπιβουλῆς τὰ τῶν ἀληθῶς ἀγαθῶν οἱ πράγμασιν ἐγχειροῦντες ἀτόποις,"},{"number":35,"text":"ἀποσπᾷ μὲν τῶν οἰκείων αὐτὸν ὡς ἐν ἀπορρήτῳ διαλεξόμενος, παραγαγὼν δὲ εἰς τὸ ἐρημότερον τῆς πύλης μόνος αὐτὸς ὢν σὺν Ἀβεσσαίῳ τῷ ἀδελφῷ σπασάμενος τὴν μάχαιραν ὑπὸ τὴν λαγόνα παίει."},{"number":36,"text":"καὶ τελευτᾷ μὲν Ἀβεννῆρος τοῦτον ἐνεδρευθεὶς τὸν τρόπον ὑπὸ Ἰωάβου, ὡς μὲν αὐτὸς ἔλεγε τιμωρήσαντος Ἀσαήλῳ τῷ ἀδελφῷ, ὃν διώκοντα λαβὼν Ἀβεννῆρος ἀπέκτεινεν ἐν τῇ πρὸς Γιβρῶνι μάχῃ, ὡς δὲ τἀληθὲς εἶχε δείσαντος περὶ τῆς στρατηγίας καὶ τῆς παρὰ τῷ βασιλεῖ τιμῆς, μὴ τούτων μὲν αὐτὸς ἀφαιρεθείη, λάβοι δὲ παρὰ Δαυίδου τὴν πρώτην τάξιν Ἀβεννῆρος."},{"number":37,"text":"ἐκ τούτων ἄν τις κατανοήσειεν, ὅσα καὶ πηλίκα τολμῶσιν ἄνθρωποι πλεονεξίας ἕνεκα καὶ ἀρχῆς καὶ τοῦ μηδενὶ τούτων παραχωρῆσαι· κτήσασθαι γὰρ αὐτὰ ποθοῦντες διὰ μυρίων κακῶν λαμβάνουσι, καὶ δείσαντες ἀποβαλεῖν πολλῷ χείροσι τὸ βέβαιον αὑτοῖς τῆς παραμονῆς περιποιοῦσιν,"},{"number":38,"text":"ὡς οὐχ ὁμοίου δεινοῦ τυγχάνοντος πορίσασθαι τηλικοῦτον μέγεθος ἐξουσίας, καὶ συνήθη τοῖς ἀπʼ αὐτῆς ἀγαθοῖς γενόμενον ἔπειτʼ αὐτὴν ἀπολέσαι, τούτου δὲ ὑπερβολὴν ἔχοντος συμφορᾶς. καὶ διὰ τοῦτο χαλεπώτερα μηχανῶνται καὶ τολμῶσιν ἐν φόβῳ ἔργα πάντες τοῦτʼ ἀποβαλεῖν γενόμενοι. ἀλλὰ περὶ μὲν τούτων ἐν βραχέσιν ἀρκεῖ δεδηλῶσθαι."},{"number":39,"text":"Δαυίδης δʼ ἀκούσας ἀνῃρημένον τὸν Ἀβεννῆρον ἤλγησε μὲν τὴν ψυχήν, ἐμαρτύρατο δὲ πάντας ἀνατείνων εἰς τὸν θεὸν τὴν δεξιὰν καὶ βοῶν, ὡς οὔτε κοινωνὸς εἴη τῆς Ἀβεννήρου σφαγῆς, οὔτε κατʼ ἐντολὴν καὶ βούλησιν ἰδίαν ἀποθάνοι. ἀρὰς δὲ κατὰ τοῦ πεφονευκότος αὐτὸν δεινὰς ἐτίθετο καὶ τὸν οἶκον ὅλον αὐτοῦ καὶ τοὺς συμπράξαντας ὑπευθύνους ἐποιεῖτο ταῖς ὑπὲρ τοῦ τετελευτηκότος ποιναῖς·"},{"number":40,"text":"ἔμελε γὰρ αὐτῷ μὴ δόξαι παρὰ τὰς πίστεις καὶ τοὺς ὅρκους οὓς ἔδωκεν Ἀβεννήρῳ τοῦτο εἰργάσθαι. προσέταξε μέντοι γε παντὶ τῷ λαῷ κλαίειν καὶ πενθεῖν τὸν ἄνδρα καὶ τοῖς νομιζομένοις τιμᾶν αὐτοῦ τὸ σῶμα περιρρηξαμένῳ μὲν τὰς ἐσθῆτας ἐνδύντι δὲ σάκκους, ταῦτα δὲ ποιεῖν προάγοντας τὴν κλίνην."},{"number":41,"text":"αὐτὸς δʼ ἐφείπετο μετὰ τῶν γεγηρακότων καὶ τῶν ἐν ἡγεμονίαις ὄντων κοπτόμενός τε καὶ τοῖς δακρύοις ἐνδεικνύμενος τό τε εὔνουν τὸ πρὸς τὸν ζῶντα καὶ τὴν ἐπὶ τεθνηκότι λύπην, καὶ ὅτι μὴ κατὰ τὴν αὐτοῦ γνώμην ἀνῄρηται."},{"number":42,"text":"θάψας δʼ αὐτὸν ἐν Γιβρῶνι μεγαλοπρεπῶς καὶ ἐπιταφίους τε συγγραψάμενος θρήνους αὐτὸς ἐπὶ τοῦ τάφου στὰς πρῶτος ἀνεκλαύσατο καὶ παρέδωκε τοῖς ἄλλοις. οὕτως δʼ αὐτὸν ὁ Ἀβεννήρου συνέσχε θάνατος, ὡς μηδὲ τροφὴν ἀναγκαζόντων αὐτὸν τῶν ἑταίρων λαβεῖν, ἀλλʼ ὤμοσε γεύσεσθαι μηδενὸς ἄχρι ἡλίου δυσμῶν."},{"number":43,"text":"ταῦτʼ εὔνοιαν αὐτῷ παρὰ τοῦ πλήθους ἐγέννησεν· οἵ τε γὰρ πρὸς τὸν Ἀβεννῆρον φιλοστόργως διακείμενοι σφόδρʼ αὐτοῦ τὴν πρὸς αὐτὸν τιμὴν ἀποθανόντα καὶ φυλακὴν τῆς πίστεως ἠγάπησαν, ὅτι πάντων αὐτὸν ἀξιώσειεν τῶν νομιζομένων ὡς συγγενῆ καὶ φίλον, ἀλλʼ οὐχ ὡς ἐχθρὸν γενόμενον ὑβρίσειεν ἀκόσμῳ ταφῇ καὶ ἠμελημένῃ· τό τε ἄλλο πᾶν ὡς ἐπὶ χρηστῷ καὶ ἡμέρῳ τὴν φύσιν ἔχαιρε, τὴν αὐτὴν ἑκάστου λογιζομένου πρόνοιαν εἰς αὑτὸν τοῦ βασιλέως ἐν τοῖς ὁμοίοις τυγχάνοντα τὸν Ἀβεννήρου νεκρὸν ἑώρα."},{"number":44,"text":"πρὸς τούτοις οὖν μάλιστα Δαυίδην γλίχεσθαι δόξης ἀγαθῆς ποιούμενον πρόνοιαν ὡς εἰκὸς ἣν οὐθεὶς ὑπενόησεν ὑπʼ αὐτοῦ φονευθῆναι τὸν Ἀβεννῆρον· ἔλεξε δὲ καὶ πρὸς τὸ πλῆθος, ὡς αὐτῷ μὲν οὐχ ἡ τυχοῦσα λύπη γένοιτʼ ἀνδρὸς ἀγαθοῦ τετελευτηκότος, οὐ μικρὰ δὲ τοῖς Ἑβραίων πράγμασι βλάβη στερηθέντων αὐτοῦ καὶ συνέχειν αὐτὰ καὶ σώζειν βουλαῖς τε ἀρίσταις καὶ ῥώμῃ χειρῶν ἐν τοῖς πολεμικοῖς ἔργοις δυναμένου."},{"number":45,"text":"ἀλλὰ θεὸς μέν, εἶπεν, ᾧ μέλει πάντων, οὐκ ἐάσει τοῦτον ἡμῖν ἀνεκδίκητον· ἐγὼ δʼ ἐπίστασθε, ὡς οὐδὲν Ἰώαβον καὶ Ἀβεσσαῖον τοὺς Σαρουίας παῖδας ποιεῖν ἱκανός εἰμι πλέον ἐμοῦ δυναμένους, ἀλλʼ ἀποδώσει τὴν ὑπὲρ τῶν τετολμημένων αὐτοῖς ἀμοιβὴν τὸ θεῖον. καὶ Ἀβεννῆρος μὲν εἰς τοιοῦτο κατέστρεψε τέλος τὸν βίον."}],"2":[{"number":46,"text":"Ἀκούσας δὲ τὴν τελευτὴν αὐτοῦ ὁ Σαούλου παῖς Ἰέβωσθος οὐ πρᾴως ἤνεγκεν ἀνδρὸς ἐστερημένος συγγενοῦς καὶ τὴν βασιλείαν αὐτῷ παρασχόντος, ἀλλʼ ὑπερεπάθησε καὶ λίαν αὐτὸν ὠδύνησεν ὁ Ἀβεννήρου θάνατος. ἐπεβίω δʼ οὐδʼ αὐτὸς πολὺν χρόνον, ἀλλʼ ὑπὸ τῶν Ἐρέμμωνος υἱῶν Βανά, ἑτέρῳ δὲ Θαηνὸς ὄνομα ἦν, ἐπιβουλευθεὶς ἀπέθανεν."},{"number":47,"text":"οὗτοι γὰρ ὄντες τὸ μὲν γένος Βενιαμῖται τοῦ δὲ πρώτου τάγματος, λογισάμενοι δʼ ὡς ἂν ἀποκτείνωσι τὸν Ἰέβωσθον μεγάλων παρὰ Δαυίδου τεύξονται δωρεῶν καὶ στρατηγίας ἤ τινος ἄλλης πίστεως τὸ ἔργον αὐτοῖς ἔσται παρʼ αὐτῷ αἴτιον,"},{"number":48,"text":"μόνον εὑρόντες μεσημβρίζοντα καὶ κοιμώμενον τὸν Ἰέβωσθον καὶ μήτε τοὺς φύλακας παρόντας μήτε τὴν θυρωρὸν ἐγρηγορυῖαν, ἀλλὰ καὶ αὐτὴν ὑπό τε τοῦ κόπου καὶ τῆς ἐργασίας ἣν μετεχειρίζετο καὶ τοῦ καύματος εἰς ὕπνον καταπεσοῦσαν, παρελθόντες εἰς τὸ δωμάτιον, ἐν ᾧ συνέβαινε κατακεκοιμῆσθαι τὸν Σαούλου παῖδα, κτείνουσιν αὐτόν."},{"number":49,"text":"καὶ τὴν κεφαλὴν ἀποτεμόντες καὶ διʼ ὅλης νυκτὸς καὶ ἡμέρας ποιησάμενοι τὴν πορείαν, ὡς ἂν φεύγοντες ἐκ τῶν ἠδικημένων πρὸς τὸν ληψόμενόν τε τὴν χάριν καὶ παρέξοντα τὴν ἀσφάλειαν, εἰς Γιβρῶνα παρεγένοντο· καὶ τὴν κεφαλὴν ἐπιδείξαντες τῷ Δαυίδῃ τὴν Ἰεβώσθου συνίστων αὑτοὺς ὡς εὔνους καὶ τὸν ἐχθρὸν αὐτοῦ καὶ τῆς βασιλείας ἀνταγωνιστὴν ἀνῃρηκότας."},{"number":50,"text":"ὁ δʼ οὐχ ὡς ἤλπιζον οὕτως αὐτῶν προσεδέξατο τὸ ἔργον, ἀλλʼ εἰπών, ὦ κάκιστοι καὶ παραχρῆμα δίκην ὑφέξοντες, οὐκ ἔγνωτε πῶς ἐγὼ τὸν Σαούλου φονέα καὶ τὸν κομίσαντά μοι τὸν χρυσοῦν αὐτοῦ στέφανον ἠμυνάμην, καὶ ταῦτα ἐκείνῳ χαριζόμενον τὴν ἀναίρεσιν, ἵνα μὴ συλλάβωσιν αὐτὸν οἱ πολέμιοι;"},{"number":51,"text":"ἦ μεταβεβλῆσθαί με καὶ μηκέτʼ εἶναι τὸν αὐτὸν ὑπωπτεύσατε, ὡς χαίρειν κακούργοις ἀνδράσι καὶ χάριτας ἡγήσασθαι τὰς κυριοκτόνους ὑμῶν πράξεις, ἀνῃρηκότων ἐπὶ τῆς αὑτοῦ κοίτης ἄνδρα δίκαιον καὶ μηδένα μηδὲν κακὸν εἰργασμένον, ὑμᾶς δὲ καὶ διὰ πολλῆς εὐνοίας καὶ τιμῆς ἐσχηκότα;"},{"number":52,"text":"διὸ δώσετε ποινὴν μὲν αὐτῷ κολασθέντες, δίκην δʼ ἐμοὶ τοῦ νομίσαντας ἡδέως ἕξειν με τὴν Ἰεβώσθου τελευτὴν τοῦτον ἀνελεῖν· οὐ γὰρ ἐδύνασθε μᾶλλον ἀδικῆσαι τὴν ἐμὴν δόξαν ἢ τοῦθʼ ὑπολαβόντες. ταῦτʼ εἰπὼν πᾶσαν αἰκίαν αὐτοὺς αἰκισάμενος διεχρήσατο καὶ τὴν Ἰεβώσθου κεφαλὴν ἐν τῷ Ἀβεννήρου τάφῳ πάντων ἀξιώσας ἐκήδευσε."},{"number":53,"text":"Τούτων δὲ τοιοῦτον λαβόντων τέλος ἧκον ἅπαντες οἱ τοῦ λαοῦ τῶν Ἑβραίων πρῶτοι πρὸς Δαυίδην εἰς Γιβρῶνα οἵ τε χιλίαρχοι καὶ ἡγεμόνες αὐτῶν, καὶ παρεδίδοσαν αὑτοὺς τήν τε εὔνοιαν, ἣν ἔτι καὶ Σαούλου ζῶντος εἶχον πρὸς αὐτόν, ὑπομιμνήσκοντες καὶ τὴν τιμήν, ἣν γενόμενον τότε χιλίαρχον τιμῶντες οὐ διέλιπον, ὅτι τε βασιλεὺς ὑπὸ τοῦ θεοῦ διὰ Σαμουήλου τοῦ προφήτου χειροτονηθείη καὶ παῖδες αὐτοῦ καὶ ὡς τὴν Ἑβραίων χώραν αὐτῷ σῶσαι καταγωνισαμένῳ Παλαιστίνους δέδωκεν ὁ θεὸς ἐμφανίζοντες."},{"number":54,"text":"ὁ δὲ ταύτης τε ἀποδέχεται τῆς προθυμίας αὐτοὺς καὶ παρακαλέσας διαμένειν, οὐ γὰρ ἔσεσθαι μετάνοιαν αὐτοῖς ἐκ τοῦ τοιούτου, καὶ κατευωχήσας καὶ φιλοφρονησάμενος ἔπεμψε τὸν λαὸν παρʼ αὐτὸν ἄξοντας ἅπαντα."},{"number":55,"text":"καὶ συνῆλθον ἐκ μὲν τῆς Ἰούδα φυλῆς ὁπλιτῶν ὡς ὀκτακόσιοι καὶ ἑξακισχίλιοι φοροῦντες ὅπλα θυρεὸν καὶ σιρομάστην· οὗτοι δὲ τῷ Σαούλου παιδὶ παρέμενον· τούτων γὰρ χωρὶς ἡ Ἰούδα φυλὴ τὸν Δαυίδην ἀπέδειξε βασιλέα."},{"number":56,"text":"ἐκ δὲ τῆς Συμεωνίδος φυλῆς ἑπτακισχίλιοι καὶ ἑκατόν. ἐκ δὲ τῆς Ληουίτιδος τετρακισχίλιοι καὶ ἑπτακόσιοι ἔχοντες ἄρχοντα Ἰώδαμον· μετὰ τούτοις ἦν ὁ ἀρχιερεὺς Σάδωκος σὺν εἴκοσι δύο συγγενέσιν ἡγεμόσιν. ἐκ δὲ τῆς Βενιαμίτιδος φυλῆς ὁπλῖται τετρακισχίλιοι· ἡ γὰρ φυλὴ περιέμενεν ἔτι τῶν τοῦ γένους Σαούλου τινὰ βασιλεύσειν προσδοκῶσα."},{"number":57,"text":"ἐκ δὲ τῆς Ἐφραίμου φυλῆς δισμύριοι καὶ ὀκτακόσιοι τῶν δυνατωτάτων καὶ κατʼ ἰσχὺν διαφερόντων. ἐκ δὲ τῆς Μανασσήτιδος φυλῆς τοῦ ἡμίσους μύριοι ὀκτακισχίλιοι τῶν δυνατωτάτων. ἐκ δὲ τῆς Ἰσαχάρου φυλῆς διακόσιοι μὲν οἱ προγινώσκοντες τὰ μέλλοντα, ὁπλῖται δὲ δισμύριοι."},{"number":58,"text":"ἐκ δὲ τῆς Ζαβουλωνίτιδος φυλῆς ὁπλιτῶν ἐπιλέκτων πέντε μυριάδες· αὕτη γὰρ ἡ φυλὴ μόνη πᾶσα πρὸς Δαυίδην συνῆλθεν· οὗτοι πάντες τὸν αὐτὸν ὁπλισμὸν εἶχον τοῖς τῆς Γάδου φυλῆς. ἐκ δὲ τῆς Νεφθαλίδος φυλῆς ἐπίσημοι καὶ ἡγεμόνες χίλιοι ὅπλοις χρώμενοι θυρεῷ καὶ δόρατι, ἠκολούθει δὲ φυλὴ ἀναρίθμητος οὖσα."},{"number":59,"text":"ἐκ δὲ τῆς Δανίτιδος φυλῆς ἐκλεκτοὶ δισμύριοι ἑπτακισχίλιοι ἑξακόσιοι. ἐκ δὲ τῆς Ἀσήρου φυλῆς μυριάδες τέσσαρες. ἐκ δὲ τῶν δύο φυλῶν τῶν πέραν τοῦ Ἰορδάνου καὶ τοῦ λοιποῦ τῆς Μανασσήτιδος φυλῆς ὡπλισμένων θυρεὸν καὶ δόρυ καὶ περικεφαλαίαν καὶ ῥομφαίαν μυριάδες δώδεκα· καὶ αἱ λοιπαὶ φυλαὶ ῥομφαίαις ἐχρῶντο."},{"number":60,"text":"τοῦτο δὴ πᾶν τὸ πλῆθος εἰς Γιβρῶνα πρὸς Δαυίδην συνῆλθε μετὰ πολλῆς παρασκευῆς σιτίων καὶ οἴνου καὶ τῶν πρὸς τροφὴν πάντων καὶ μιᾷ γνώμῃ βασιλεύειν τὸν Δαυίδην ἐκύρωσαν. ἐπὶ δὲ τρεῖς ἡμέρας ἑορτάσαντος τοῦ λαοῦ καὶ κατευωχηθέντος ἐν Γιβρῶνι, ὁ Δαυίδης μετὰ πάντων ἐκεῖθεν ἄρας ἧκεν εἰς Ἱεροσόλυμα."}],"3":[{"number":61,"text":"Τῶν δὲ κατοικούντων τὴν πόλιν Ἰεβουσαίων, γένος δʼ εἰσὶν οὗτοι Χαναναίων, ἀποκλεισάντων αὐτῷ τὰς πύλας καὶ τοὺς πεπηρωμένους τὰς ὄψεις καὶ τὰς βάσεις καὶ πᾶν τὸ λελωβημένον στησάντων ἐπὶ χλεύῃ τοῦ βασιλέως ἐπὶ τοῦ τείχους καὶ λεγόντων κωλύσειν αὐτὸν εἰσελθεῖν τοὺς ἀναπήρους, ταῦτα δʼ ἔπραττον καταφρονοῦντες τῇ τῶν τειχῶν ὀχυρότητι, ὀργισθεὶς πολιορκεῖν ἤρξατο τὰ Ἱεροσόλυμα."},{"number":62,"text":"καὶ πολλῇ σπουδῇ καὶ προθυμίᾳ χρησάμενος ὡς διὰ τοῦ ταύτην ἑλεῖν εὐθὺς ἐμφανίζων τὴν ἰσχὺν καὶ καταπληξόμενος εἴ τινες ἄρα καὶ ἄλλοι τὸν αὐτὸν ἐκείνοις τρόπον διέκειντο πρὸς αὐτόν, λαμβάνει κατὰ κράτος τὴν κάτω πόλιν."},{"number":63,"text":"ἔτι δὲ τῆς ἄκρας λειπομένης ἔγνω τιμῆς ὑποσχέσει καὶ γερῶν ὁ βασιλεὺς προθυμοτέρους ἐπὶ τὰ ἔργα τοὺς στρατιώτας παρασκευάσαι, καὶ τῷ διὰ τῶν ὑποκειμένων φαράγγων ἐπὶ τὴν ἄκραν ἀναβάντι καὶ ταύτην ἑλόντι στρατηγίαν ἅπαντος τοῦ λαοῦ δώσειν ἐπηγγείλατο."},{"number":64,"text":"πάντων δὲ φιλοτιμουμένων ἀναβῆναι καὶ μηδένα πόνον ὀκνούντων ὑφίστασθαι διʼ ἐπιθυμίαν τῆς στρατηγίας, ὁ Σαρουίας παῖς Ἰώαβος ἔφθη τοὺς ἄλλους, καὶ ἀναβὰς ἐβόησε πρὸς τὸν βασιλέα τὴν στρατηγίαν ἀπαιτῶν."},{"number":65,"text":"Ἐκβαλὼν δὲ τοὺς Ἰεβουσαίους ἐκ τῆς ἄκρας καὶ αὐτὸς ἀνοικοδομήσας τὰ Ἱεροσόλυμα πόλιν αὐτὴν Δαυίδου προσηγόρευσε, καὶ τὸν ἅπαντα χρόνον ἐν αὐτῇ διέτριβε βασιλεύων. ὁ δὲ χρόνος ὃν τῆς Ἰούδα φυλῆς ἦρξε μόνης ἐν Γιβρῶνι ἐγένετο ἔτη ἑπτὰ καὶ μῆνες ἕξ. ἀποδείξας δὲ βασίλειον τὰ Ἱεροσόλυμα λαμπροτέροις αἰεὶ καὶ μᾶλλον ἐχρῆτο τοῖς πράγμασι τοῦ θεοῦ προνοουμένου κρείττω ποιεῖν αὐτὰ καὶ λαμβάνειν ἐπίδοσιν."},{"number":66,"text":"πέμψας δὲ πρὸς αὐτὸν καὶ Ἱέρωμος ὁ Τυρίων βασιλεὺς φιλίαν καὶ συμμαχίαν συνέθετο· ἔπεμψε δʼ αὐτῷ καὶ δωρεὰς ξύλα κέδρινα καὶ τεχνίτας ἄνδρας τέκτονας καὶ οἰκοδόμους, οἳ κατεσκεύασαν βασίλειον ἐν Ἱεροσολύμοις. Δαυίδης δὲ τήν τε ἄνω πόλιν παραλαβὼν καὶ τὴν ἄκραν συνάψας αὐτῇ ἐποίησεν ἓν σῶμα, καὶ περιτειχίσας ἐπιμελητὴν τῶν τειχῶν κατέστησεν Ἰώαβον."},{"number":67,"text":"πρῶτος οὖν Δαυίδης τοὺς Ἰεβουσαίους ἐξ Ἱεροσολύμων ἐκβαλὼν ἀφʼ ἑαυτοῦ προσηγόρευσε τὴν πόλιν· ἐπὶ γὰρ Ἁβράμου τοῦ προγόνου ἡμῶν Σόλυμα ἐκαλεῖτο, μετὰ ταῦτα δὲ αὐτήν φασί τινες, ὅτι καὶ Ὅμηρος ταῦτʼ ὠνόμασεν Ἱεροσόλυμα· τὸ γὰρ ἱεροῦ κατὰ τὴν Ἑβραίων γλῶτταν ὠνόμασε τὰ Σόλυμα ὅ ἐστιν ἀσφάλεια."},{"number":68,"text":"ἦν δὲ πᾶς ὁ χρόνος ἀπὸ τῆς Ἰησοῦ τοῦ στρατηγοῦ ἐπὶ Χαναναίους στρατείας καὶ τοῦ πολέμου, καθʼ ὃν κρατήσας αὐτῶν κατένειμε ταύτην τοῖς Ἑβραίοις καὶ οὐκέτι τοὺς Χαναναίους ἐκβαλεῖν ἐξ Ἱεροσολύμων ἐδυνήθησαν οἱ Ἰσραηλῖται, μέχρις ὁ Δαυίδης αὐτοὺς ἐξεπολιόρκησεν, ἔτη πεντακόσια καὶ δέκα καὶ πέντε."},{"number":69,"text":"Ποιήσομαι δὲ καὶ μνήμην Ὀρόνα πλουσίου μὲν ἀνδρὸς τῶν Ἰεβουσαίων, οὐκ ἀναιρεθέντος δὲ ἐν τῇ Ἱεροσολύμων πολιορκίᾳ ὑπὸ Δαυίδου διὰ τὴν πρὸς τοὺς Ἑβραίους εὔνοιαν αὐτοῦ καί τινα καὶ χάριν καὶ σπουδὴν πρὸς αὐτὸν γενομένην τὸν βασιλέα, ἣν μικρὸν ὕστερον εὐκαιρότερον σημανῶ."},{"number":70,"text":"ἔγημε δὲ καὶ ἄλλας γυναῖκας πρὸς ταῖς οὔσαις αὐτῷ Δαυίδης καὶ παλλακὰς ἔσχεν. ἐποιήσατο δὲ καὶ παῖδας ἐννέα τὸν ἀριθμόν, οὓς προσηγόρευσεν Ἀμασέ, Ἀμνου, Σεβάν, Νάθαν, Σολομῶνα, Ἰεβαρῆ, Ἐλιήν, Φαλναγέην, Ναφήν, Ἰεναέ, Ἐλιφαλέ, ἔτι δὲ καὶ θυγατέρα Θαμάραν. τούτων οἱ μὲν ἐννέα ἐξ εὐγενίδων ἦσαν γεγονότες, οὓς δὲ τελευταίους εἰρήκαμεν δύο ἐκ τῶν παλλακίδων. Θαμάρα δὲ ὁμομήτριος Ἀψαλώμῳ ἦν."}],"4":[{"number":71,"text":"Γνόντες δʼ οἱ Παλαιστῖνοι τὸν Δαυίδην βασιλέα ὑπὸ τῶν Ἑβραίων ἀποδεδειγμένον στρατεύουσιν ἐπʼ αὐτὸν εἰς Ἱεροσόλυμα· καὶ καταλαβόμενοι τὴν κοιλάδα τῶν Γιγάντων καλουμένην, τόπος δέ ἐστιν οὐ πόρρω τῆς πόλεως, ἐν αὐτῇ στρατοπεδεύονται."},{"number":72,"text":"ὁ δὲ τῶν Ἰουδαίων βασιλεύς, οὐδὲν γὰρ ἄνευ προφητείας καὶ τοῦ κελεῦσαι τὸν θεὸν καὶ περὶ τῶν ἐσομένων λαβεῖν ἐγγυητὴν ἐκεῖνον ἑαυτῷ ποιεῖν ἐπέτρεπεν, ἐκέλευσε τὸν ἀρχιερέα τί δοκεῖ τῷ θεῷ καὶ ποδαπὸν ἔσται τὸ τέλος τῆς μάχης προλέγειν αὐτῷ."},{"number":73,"text":"προφητεύσαντος δὲ νίκην καὶ κράτος ἐξάγει τὴν δύναμιν ἐπὶ τοὺς Παλαιστίνους· καὶ γενομένης συμβολῆς αὐτὸς κατόπιν αἰφνιδίως ἐπιπεσὼν τοῖς πολεμίοις τοὺς μὲν αὐτῶν ἀπέκτεινε, τοὺς δὲ εἰς φυγὴν ἐτρέψατο."},{"number":74,"text":"ὑπολάβῃ δὲ μηδεὶς ὀλίγην τὴν τῶν Παλαιστίνων στρατιὰν ἐλθεῖν ἐπὶ τοὺς Ἑβραίους τῷ τάχει τῆς ἥττης καὶ τῷ μηδὲν ἔργον ἐπιδείξασθαι γενναῖον μηδὲ μαρτυρίας ἄξιον στοχαζόμενος αὐτῶν τὴν βραδυτῆτα καὶ τὴν ἀγέννειαν, ἀλλὰ γινωσκέτω Συρίαν τε ἅπασαν καὶ Φοινίκην καὶ πρὸς τούτοις ἄλλα ἔθνη πολλὰ καὶ μάχιμα συστρατεῦσαι αὐτοῖς καὶ τοῦ πολέμου κοινωνῆσαι,"},{"number":75,"text":"ὃ καὶ μόνον ἦν αἴτιον τοσαυτάκις αὐτοῖς νικωμένοις καὶ πολλὰς ἀποβαλοῦσι μυριάδας μετὰ μείζονος ἐπιέναι τοῖς Ἑβραίοις δυνάμεως. ἀμέλει καὶ ταύταις πταίσαντες ταῖς μάχαις τριπλάσιος στρατὸς ἐπῆλθε τῷ Δαυίδῃ καὶ εἰς ταὐτὸ χωρίον ἐστρατοπεδεύσατο."},{"number":76,"text":"πάλιν δὲ τοῦ βασιλέως τῶν Ἰσραηλιτῶν ἐρομένου τὸν θεὸν περὶ τῆς περὶ τὴν μάχην ἐξόδου, προφητεύει ὁ ἀρχιερεὺς ἐν τοῖς ἄλσεσι τοῖς καλουμένοις Κλαυθμῶσι κατέχειν τὴν στρατιὰν οὐκ ἄπωθεν τοῦ τῶν πολεμίων στρατοπέδου, κινεῖν δʼ αὐτὸν μὴ πρότερον μηδʼ ἄρχεσθαι τῆς μάχης."},{"number":77,"text":"πρὶν ἢ τὰ ἄλση σαλεύεσθαι μὴ πνέοντος ἀνέμου. ὡς δʼ ἐσαλεύθη τὰ ἄλση καὶ ὃν αὐτῷ καιρὸν προεῖπεν ὁ θεὸς παρῆν, οὐδὲν ἐπισχὼν ἐφʼ ἑτοίμην ἤδη καὶ φανερὰν ἐξῆλθε τὴν νίκην· οὐ γὰρ ὑπέμειναν αὐτὸν αἱ τῶν πολεμίων φάλαγγες, ἀλλʼ εὐθὺς ἀπὸ τῆς πρώτης συμβολῆς τραπέντας ἐνέκειτο κτείνων· καὶ διώκει μὲν αὐτοὺς ἄχρι πόλεως Γαζάρων, ἡ δʼ ἐστὶν ὅρος αὐτῶν τῆς χώρας, διαρπάζει δʼ αὐτῶν τὴν παρεμβολὴν καὶ πολὺν εὑρὼν ἐν αὐτῇ πλοῦτον καὶ τοὺς θεοὺς αὐτῶν διέφθειρε."},{"number":78,"text":"Τοιαύτης δʼ ἀποβάσης καὶ ταύτης τῆς μάχης ἔδοξε Δαυίδῃ συμβουλευσαμένῳ μετὰ τῶν γερόντων καὶ ἡγεμόνων καὶ χιλιάρχων μεταπέμψασθαι τῶν ὁμοφύλων ἐξ ἁπάσης τῆς χώρας πρὸς αὑτὸν τοὺς ἐν ἀκμῇ τῆς ἡλικίας, ἔπειτα τοὺς ἱερεῖς καὶ Ληουίτας καὶ πορευθέντας εἰς Καριαθιάριμα μετακομίσαι τὴν τοῦ θεοῦ κιβωτὸν ἐξ αὐτῆς εἰς Ἱεροσόλυμα καὶ θρησκεύειν ἐν αὐτῇ λοιπὸν ἔχοντας αὐτὴν θυσίαις καὶ ταῖς ἄλλαις τιμαῖς, αἷς χαίρει τὸ θεῖον·"},{"number":79,"text":"εἰ γὰρ ἔτι Σαούλου βασιλεύοντος τοῦτʼ ἔπραξαν, οὐκ ἂν δεινὸν οὐδὲν ἔπαθον. συνελθόντος οὖν τοῦ λαοῦ παντός, καθὼς ἐβουλεύσαντο, παραγίνεται ὁ βασιλεὺς ἐπὶ τὴν κιβωτόν, ἣν βαστάξαντες ἐκ τῆς Ἀμιναδάβου οἰκίας οἱ ἱερεῖς καὶ ἐπιθέντες ἐφʼ ἅμαξαν καινὴν ἕλκειν ἀδελφοῖς τε καὶ παισὶν ἐπέτρεψαν μετὰ τῶν βοῶν."},{"number":80,"text":"προῆγε δʼ ὁ βασιλεὺς καὶ πᾶν σὺν αὐτῷ τὸ πλῆθος ὑμνοῦντες τὸν θεὸν καὶ ᾄδοντες πᾶν εἶδος μέλους ἐπιχώριον σύν τε ἤχῳ ποικίλῳ κρουσμάτων τε καὶ ὀρχήσεων καὶ ψαλμῶν ἔτι δὲ σάλπιγγος καὶ κυμβάλων κατάγοντες τὴν κιβωτὸν εἰς Ἱεροσόλυμα."},{"number":81,"text":"ὡς δʼ ἄχρι τῆς Χειδῶνος ἅλωνος τόπου τινὸς οὕτω καλουμένου προῆλθον, τελευτᾷ Ὀζᾶς κατʼ ὀργὴν τοῦ θεοῦ· τῶν βοῶν γὰρ ἐπινευσάντων τὴν κιβωτὸν ἐκτείναντα τὴν χεῖρα καὶ κατασχεῖν ἐθελήσαντα, ὅτι μὴ ὢν ἱερεὺς ἥψατο ταύτης, ἀποθανεῖν ἐποίησε."},{"number":82,"text":"καὶ ὁ μὲν βασιλεὺς καὶ ὁ λαὸς ἐδυσφόρησαν ἐπὶ τῷ θανάτῳ τοῦ Ὀζᾶ, ὁ δὲ τόπος ἐν ᾧ ἐτελεύτησεν Ὀζᾶ διακοπὴ καλεῖται. δείσας δʼ ὁ Δαυίδης καὶ λογισάμενος, μὴ ταὐτὸ πάθῃ τῷ Ὀζᾶ δεξάμενος τὴν κιβωτὸν παρʼ αὑτὸν ἐν τῇ πόλει, ἐκείνου διότι μόνον ἐξέτεινε τὴν χεῖρα πρὸς αὐτὴν οὕτως ἀποθανόντος,"},{"number":83,"text":"οὐκ εἰσδέχεται μὲν αὐτὴν πρὸς αὑτὸν εἰς τὴν πόλιν, ἀλλʼ ἐκνεύσας εἴς τι χωρίον ἀνδρὸς δικαίου, Ὠβαδάρου ἄνομα Ληουίτου τὸ γένος, παρʼ αὐτῷ τὴν κιβωτὸν τίθησιν· ἔμεινε δʼ ἐπὶ τρεῖς ὅλους μῆνας αὐτόθι καὶ τὸν οἶκον τὸν Ὠβαδάρου ηὔξησέ τε καὶ πολλῶν αὐτῷ μετέδωκεν ἀγαθῶν."},{"number":84,"text":"ἀκούσας δὲ ὁ βασιλεὺς ὅτι ταῦτα συμβέβηκεν Ὠβαδάρῳ καὶ ἐκ πενίας καὶ ταπεινότητος ἀθρόως εὐδαίμων καὶ ζηλωτὸς γέγονε παρὰ πᾶσι τοῖς ὁρῶσι καὶ πυνθανομένοις τὴν οἰκίαν αὐτοῦ, θαρσήσας ὡς οὐδενὸς κακοῦ πειρασόμενος τὴν κιβωτὸν πρὸς αὑτὸν μετακομίζει,"},{"number":85,"text":"τῶν μὲν ἱερέων βασταζόντων αὐτήν, ἑπτὰ δὲ χορῶν οὓς διεκόσμησεν ὁ βασιλεὺς προαγόντων, αὐτοῦ δʼ ἐν κινύρᾳ παίζοντος καὶ κροτοῦντος, ὥστε καὶ τὴν γυναῖκα Μιχάλην Σαούλου δὲ θυγατέρα τοῦ πρώτου βασιλέως ἰδοῦσαν αὐτὸν τοῦτο ποιοῦντα χλευάσαι."},{"number":86,"text":"εἰσκομίσαντες δὲ τὴν κιβωτὸν τιθέασιν ὑπὸ τὴν σκηνήν, ἣν Δαυίδης ἔπηξεν αὐτῇ, καὶ θυσίας τελείας καὶ εἰρηνικὰς ἀνήνεγκε, καὶ τὸν ὄχλον εἱστίασε πάντα καὶ γυναιξὶ καὶ ἀνδράσι καὶ νηπίοις διαδοὺς κολλυρίδα ἄρτου καὶ ἐσχαρίτην καὶ λάγανον τηγανιστὸν καὶ μερίδα θύματος. καὶ τὸν μὲν λαὸν οὕτως κατευωχήσας ἀπέπεμψεν, αὐτὸς δʼ εἰς τὸν οἶκον τὸν αὑτοῦ παραγίνεται."},{"number":87,"text":"Παραστᾶσα δὲ αὐτῷ Μιχάλη ἡ γυνὴ Σαούλου δὲ θυγάτηρ τά τε ἄλλα αὐτῷ κατηύχετο καὶ παρὰ τοῦ θεοῦ γενέσθαι ᾔτει πάνθʼ ὅσα παρασχεῖν αὐτῷ δυνατὸν εὐμενεῖ τυγχάνοντι, καὶ δὴ κατεμέμψατο, ὡς ἀκοσμήσειεν ὀρχούμενος ὁ τηλικοῦτος βασιλεὺς καὶ γυμνούμενος ὑπὸ τῆς ὀρχήσεως καὶ ἐν δούλοις καὶ ἐν θεραπαινίσιν."},{"number":88,"text":"ὁ δʼ οὐκ αἰδεῖσθαι ταῦτα ποιήσας εἰς τὸ τῷ θεῷ κεχαρισμένον ἔφασκεν, ὃς αὐτὸν καὶ τοῦ πατρὸς αὐτῆς καὶ τῶν ἄλλων ἁπάντων προετίμησε, παίζειν τε καὶ πολλάκις χορεῦσαι μηδένα τοῦ δόξαι ταῖς θεραπαινίσιν αἰσχρὸν καὶ αὐτῇ τὸ γινόμενον ποιησάμενος λόγον."},{"number":89,"text":"ἡ Μιχάλη αὕτη Δαυίδῃ μὲν συνοικοῦσα παῖδας οὐκ ἐποιήσατο, γαμηθεῖσα δὲ ὕστερον ᾧ παρέδωκεν αὐτὴν ὁ πατὴρ Σαοῦλος, τότε δὲ ἀποσπάσας αὐτὸς εἶχε, πέντε παῖδας ἔτεκε. καὶ περὶ μὲν τούτων κατὰ χώραν δηλώσομεν."},{"number":90,"text":"Ὁρῶν δʼ ὁ βασιλεὺς κατὰ πᾶσαν αὐτῷ τὰ πράγματα σχεδὸν ἡμέραν ἀμείνω γινόμενα ἐκ τῆς τοῦ θεοῦ βουλήσεως ἐνόμιζεν ἐξαμαρτάνειν αὑτὸν, εἰ μένων αὐτὸς ἐν οἴκοις ἐκ κέδρου πεποιημένοις ὑψηλοῖς τε καὶ καλλίστην τὴν ἄλλην κατασκευὴν ἔχουσι περιορᾷ τὴν κιβωτὸν ἐν σκηνῇ κειμένην·"},{"number":91,"text":"ἐβούλετο δὲ τῷ θεῷ κατασκευάσαι ναόν, ὡς Μωυσῆς εἶπε, καὶ περὶ τούτων Νάθᾳ τῷ προφήτῃ διαλεχθείς, ἐπεὶ ποιεῖν ὅτιπερ ὥρμηται προσέταξεν αὐτὸν ὡς τοῦ θεοῦ πρὸς ἅπαντʼ αὐτῷ συνεργοῦ παρόντος, εἶχεν ἤδη περὶ τὴν τοῦ ναοῦ κατασκευὴν προθυμότερον."},{"number":92,"text":"τοῦ θεοῦ δὲ κατʼ ἐκείνην τὴν νύκτα τῷ Νάθᾳ φανέντος καὶ φράσαι κελεύσαντος τῷ Δαυίδῃ, ὡς τὴν μὲν προαίρεσιν αὐτοῦ καὶ τὴν ἐπιθυμίαν ἀποδέχεται, μηδενὸς μὲν πρότερον εἰς νοῦν βαλομένου ναὸν αὐτῷ κατασκευάσαι. τούτου δὲ ταύτην τὴν διάνοιαν λαβόντος· οὐκ ἐπιτρέπειν δὲ πολλοὺς πολέμους ἠγωνισμένῳ καὶ φόνῳ τῶν ἐχθρῶν μεμιασμένῳ ποιῆσαι ναὸν αὐτῷ."},{"number":93,"text":"μετὰ μέντοι γε τὸν θάνατον αὐτοῦ γηράσαντος καὶ μακρὸν ἀνύσαντος βίον γενήσεσθαι τὸν ναὸν ὑπὸ τοῦ παιδὸς τοῦ μετʼ αὐτὸν τὴν βασιλείαν παραληψομένου κληθησομένου δὲ Σολομῶνος, οὗ προστήσεσθαι καὶ προνοήσειν ὡς πατὴρ υἱοῦ κατεπηγγέλλετο, τὴν μὲν βασιλείαν τέκνων ἐγγόνοις φυλάξων καὶ παραδώσων, αὐτὸν δὲ τιμωρήσων, ἂν ἁμαρτὼν τύχῃ, νόσῳ καὶ γῆς ἀφορίᾳ."},{"number":94,"text":"μαθὼν ταῦτα παρὰ τοῦ προφήτου Δαυίδης καὶ περιχαρὴς γενόμενος ἐπὶ τῷ τοῖς ἐγγόνοις αὐτοῦ τὴν ἀρχὴν διαμένουσαν ἐγνωκέναι βεβαίως καὶ τὸν οἶκον αὐτοῦ λαμπρὸν ἐσόμενον καὶ περιβόητον πρὸς τὴν κιβωτὸν παραγίνεται,"},{"number":95,"text":"καὶ πεσὼν ἐπὶ πρόσωπον ἤρξατο προσκυνεῖν καὶ περὶ πάντων εὐχαριστεῖν τῷ θεῷ, ὧν τε αὐτῷ παρέσχηκεν ἤδη ἐκ ταπεινοῦ καὶ ποιμένος εἰς τηλικοῦτο μέγεθος ἡγεμονίας τε καὶ δόξης ἀναγαγών, ὧν τε τοῖς ἐγγόνοις αὐτοῦ καθυπέσχετο, τῆς προνοίας, ἣν Ἑβραίων καὶ τῆς τούτων ἐλευθερίας ἐποιήσατο. ταῦτʼ εἰπὼν καὶ τὸν θεὸν ὑμνήσας ἀπαλλάσσεται."}],"5":[{"number":96,"text":"Διαλιπὼν δὲ ὀλίγον χρόνον ἔγνω δεῖν ἐπὶ τοὺς Παλαιστίνους ἐκστρατεύειν, καὶ μηδὲν ἀργὸν μηδὲ ῥᾴθυμον ἐν τοῖς πράγμασιν ὁρᾶν γινόμενον, ἵνʼ ὡς τὸ θεῖον αὐτῷ προεῖπε καταστρεψάμενος τοὺς πολεμίους ἐν εἰρήνῃ τὸ λοιπὸν τοὺς ἐκγόνους αὐτοῦ βασιλεύοντας καταλείποι."},{"number":97,"text":"καὶ συγκαλέσας πάλιν τὴν στρατιὰν καὶ παραγγείλας αὐτῇ πρὸς πόλεμον ἑτοίμῃ καὶ παρεσκευασμένῃ τυγχάνειν, ὅτʼ ἔδοξεν αὐτῷ καλῶς ἔχειν τὰ παρʼ αὐτῆς ἄρας ἐκ τῶν Ἱεροσολύμων ἐπὶ τοὺς Παλαιστίνους ἧκε."},{"number":98,"text":"κρατήσας δʼ αὐτῶν τῇ μάχῃ καὶ πολλὴν τῆς χώρας ἀποτεμόμενος καὶ προσορίσας τῇ τῶν Ἑβραίων ἐπὶ τοὺς Μωαβίτας τὸν πόλεμον μετήγαγε, καὶ τὰ μὲν δύο μέρη τῆς στρατιᾶς αὐτῶν τῇ μάχῃ νικήσας διέφθειρε, τὸ δὲ λειπόμενον αἰχμάλωτον ἔλαβε."},{"number":99,"text":"φόρους δὲ αὐτοῖς ἐπιτάξας κατʼ ἔτος τελεῖν ἐπὶ Ἀρτάζαρον τὸν Ἀραοῦ μὲν υἱὸν βασιλέα δὲ τῆς Σωφηνῆς ἐστράτευσε, καὶ συμβαλὼν αὐτῷ παρὰ τὸν Εὐφράτην ποταμὸν τῶν μὲν πεζῶν αὐτοῦ διέφθειρεν ὡσεὶ δισμυρίους, τῶν δʼ ἱπποτῶν ὡς πεντακισχιλίους. ἔλαβε δὲ καὶ αὐτοῦ ἅρματα χίλια, καὶ τὰ πλείω μὲν αὐτῶν ἠφάνισεν, ἑκατὸν δὲ μόνα προσέταξεν αὑτῷ φυλαχθῆναι."},{"number":100,"text":"Ἀκούσας δὲ ὁ Δαμασκοῦ καὶ Σύρων βασιλεὺς Ἄδαδος, ὅτι πολεμεῖ Δαυίδης τὸν Ἀρτάζαρον, φίλος ὢν αὐτῷ μετὰ δυνάμεως ἧκεν ἰσχυρᾶς συμμαχήσων· ἀπήλλαξε δʼ ὡς προσεδόκα συμβαλὼν πρὸς τῷ Εὐφράτῃ ποταμῷ, πταίσας δὲ τῇ μάχῃ πολλοὺς ἀπέβαλε τῶν στρατιωτῶν· ἔπεσον γὰρ ὑπὸ τῶν Ἑβραίων ἀναιρούμενοι τῆς Ἀδάδου δυνάμεως δισμύριοι, οἱ δὲ λοιποὶ πάντες ἔφυγον."},{"number":101,"text":"μέμνηται δὲ τούτου τοῦ βασιλέως καὶ Νικόλαος ἐν τῇ τετάρτῃ τῶν ἱστοριῶν αὐτοῦ λέγων οὕτως· μετὰ δὲ ταῦτα πολλῷ χρόνῳ ὕστερον τῶν ἐγχωρίων τις Ἄδαδος ὄνομα πλεῖον ἰσχύσας Δαμασκοῦ τε καὶ τῆς ἄλλης Συρίας ἔξω Φοινίκης ἐβασίλευσε. πόλεμον δʼ ἐξενέγκας πρὸς Δαυίδην τὸν βασιλέα τῆς Ἰουδαίας καὶ πολλαῖς μάχαις κριθείς, ὑστάτῃ δὲ παρὰ τὸν Εὐφράτην, ἐν ᾗ ἡττᾶτο, ἄριστος ἔδοξεν εἶναι βασιλέων ῥώμῃ καὶ ἀνδρείᾳ."},{"number":102,"text":"πρὸς τούτοις δὲ καὶ περὶ τῶν ἀπογόνων αὐτοῦ φησιν, ὡς μετὰ τὴν ἐκείνου τελευτὴν ἐξεδέχοντο παρʼ ἀλλήλων καὶ τὴν βασιλείαν καὶ τὸ ὄνομα, λέγων οὕτως· τελευτήσαντος δὲ ἐκείνου ἀπόγονοι ἐπὶ δέκα γενεὰς ἐβασίλευον ἑκάστου παρὰ τοῦ πατρὸς ἅμα καὶ τὴν ἀρχὴν καὶ τοὔνομα τούτου ἐκδεχομένου, ὥσπερ οἱ Πτολεμαῖοι ἐν Αἰγύπτῳ."},{"number":103,"text":"μέγιστον δὲ ἁπάντων δυνηθεὶς ὁ τρίτος ἀναμαχέσασθαι βουλόμενος τὴν τοῦ προπάτορος ἧτταν στρατεύσας ἐπὶ τοὺς Ἰουδαίους ἐπόρθησε τὴν νῦν Σαμαρεῖτιν καλουμένην γῆν. οὐ διήμαρτε δὲ τῆς ἀληθείας· οὗτος γάρ ἐστιν Ἄδαδος ὁ στρατευσάμενος ἐπὶ Σαμάρειαν Ἀχάβου βασιλεύοντος τῶν Ἰσραηλιτῶν, περὶ οὗ κατὰ χώραν ἐροῦμεν."},{"number":104,"text":"Δαυίδης δὲ στρατευσάμενος ἐπὶ Δαμασκὸν καὶ τὴν ἄλλην Συρίαν πᾶσαν αὐτὴν ὑπήκοον ἐποιήσατο, καὶ φρουρὰς ἐν τῇ χώρᾳ καταστήσας καὶ φόρους αὐτοῖς τελεῖν ὁρίσας ὑπέστρεψε· καὶ τάς τε χρυσᾶς φαρέτρας καὶ τὰς πανοπλίας, ἃς οἱ τοῦ Ἀδάδου σωματοφύλακες ἐφόρουν,"},{"number":105,"text":"ἀνέθηκε τῷ θεῷ εἰς Ἱεροσόλυμα, ἃς ὕστερον ὁ τῶν Αἰγυπτίων βασιλεὺς Σούσακος στρατεύσας ἐπὶ τὸν υἱωνὸν αὐτοῦ Ῥοβόαμον ἔλαβε καὶ πολὺν ἄλλον ἐκ τῶν Ἱεροσολύμων ἐξεφόρησε πλοῦτον· ταῦτα μὲν ὅταν ἔλθωμεν ἐπὶ τὸν οἰκεῖον αὐτῶν τόπον δηλώσομεν. ὁ δὲ τῶν Ἑβραίων βασιλεὺς τοῦ θεοῦ συμπνέοντος αὐτῷ καὶ τοὺς πολέμους συγκατορθοῦντος καὶ ταῖς καλλίσταις τῶν Ἀνδραζάρου πόλεων ἐπεστράτευσε Βατταίᾳ καὶ Μάχωνι, καὶ λαβὼν αὐτὰς κατὰ κράτος διήρπασε."},{"number":106,"text":"χρυσὸς δʼ ἐν αὐταῖς εὑρέθη πάμπολυς καὶ ἄργυρος ἔτι δὲ καὶ χαλκός, ὃν τοῦ χρυσοῦ κρείττονʼ ἔλεγον, ἐξ οὗ καὶ Σολόμων τὸ μέγα σκεῦος θάλασσαν δὲ καλούμενον ἐποίησε καὶ τοὺς καλλίστους ἐκείνους λουτῆρας, ὅτε τῷ θεῷ τὸν ναὸν κατεσκεύασεν."},{"number":107,"text":"Ὡς δὲ ὁ τῆς Ἀμάθης βασιλεὺς τὰ περὶ τὸν Ἀνδράζαρον ἐπύθετο καὶ τὴν δύναμιν αὐτοῦ διεφθαρμένην ἤκουσε, δείσας περὶ αὑτῷ καὶ τὸν Δαυίδην πρὶν ἐπʼ αὐτὸν ἔλθοι φιλίᾳ καὶ πίστει γνοὺς ἐνδήσασθαι, πέμπει πρὸς αὐτὸν Ἀδώραμον υἱὸν αὐτοῦ καὶ περὶ τοῦ τὸν Ἀνδράζαρον ἐχθρὸν ὄντʼ αὐτῷ πολεμῆσαι χάριν ἔχειν ὁμολογῶν, καὶ συμμαχίαν πρὸς αὐτὸν καὶ φιλίαν ποιούμενος."},{"number":108,"text":"ἔπεμψε δʼ αὐτῷ καὶ δῶρα σκεύη τῆς ἀρχαίας κατασκευῆς χρύσεα καὶ ἀργύρεα καὶ χάλκεα. Δαυίδης δὲ ποιησάμενος τὴν συμμαχίαν πρὸς τὸν Θαῖνον, τοῦτο γὰρ ἦν ὄνομα τῷ βασιλεῖ τῆς Ἀμάθης, καὶ τὰ δῶρα δεξάμενος ἀπέλυσεν αὐτοῦ τὸν υἱὸν μετὰ τιμῆς τῆς πρεπούσης ἑκατέροις. τὰ δὲ πεμφθέντα ὑπʼ αὐτοῦ καὶ τὸν ἄλλον χρυσὸν καὶ ἄργυρον, ὃν ἐκ τῶν πόλεων εἰλήφει καὶ τῶν κεχειρωμένων ἐθνῶν, φέρων ἀνατίθησι τῷ θεῷ."},{"number":109,"text":"οὐκ αὐτῷ δὲ πολεμοῦντι μόνον καὶ τῆς στρατιᾶς ἡγουμένῳ τὸ νικᾶν καὶ κατορθοῦν παρεῖχεν ὁ θεός, ἀλλὰ καὶ πέμψαντος αὐτοῦ μετὰ δυνάμεως εἰς τὴν Ἰδουμαίαν Ἀβεσσαῖον τὸν Ἰωάβου τοῦ ἀρχιστρατήγου ἀδελφὸν διʼ ἐκείνου τὴν τῶν Ἰδουμαίων νίκην ἔδωκε· μυρίους γὰρ αὐτῶν καὶ ὀκτακισχιλίους Ἀβεσσαῖος διέφθειρε τῇ μάχῃ. καὶ τὴν Ἰδουμαίαν ἅπασαν φρουραῖς διαλαβὼν ὁ βασιλεὺς φόρους ὑπέρ τε τῆς χώρας καὶ τῆς ἑκάστου κεφαλῆς παρʼ αὐτῶν ἐδέχετο."},{"number":110,"text":"ἦν δὲ καὶ δίκαιος τὴν φύσιν καὶ τὰς κρίσεις πρὸς τὴν ἀλήθειαν ἀφορῶν ἐποιεῖτο. στρατηγὸν δὲ ἁπάσης εἶχε τῆς στρατιᾶς τὸν Ἰώαβον· ἐπὶ δὲ τῶν ὑπομνημάτων Ἰωσάφατον υἱὸν Ἀχίλου κατέστησεν· ἀπέδειξε δʼ ἐκ τῆς Φινεέσου οἰκίας τὸν Σάδωκον ἀρχιερέα μετʼ Ἀβιαθάρου, φίλος γὰρ ἦν αὐτῷ· γραμματέα δὲ Σισὰν ἐποίησε· Βαναίᾳ δὲ τῷ Ἰωάδου τὴν τῶν σωματοφυλάκων ἀρχὴν παραδίδωσιν· οἱ δὲ πρεσβύτεροι παῖδες αὐτοῦ περὶ τὸ σῶμα καὶ τὴν τούτου φυλακὴν ἦσαν."},{"number":111,"text":"Ἐμνήσθη δὲ καὶ τῶν πρὸς Ἰωνάθην τὸν Σαούλου παῖδα συνθηκῶν καὶ ὅρκων καὶ τῆς ἐκείνου πρὸς αὐτὸν φιλίας τε καὶ σπουδῆς· πρὸς γὰρ τοῖς ἄλλοις ἅπασιν ἀγαθοῖς οἷς εἶχεν ἔτι καὶ μνημονικώτατος τῶν εὖ ποιησάντων παρὰ τὸν ἄλλον χρόνον ὑπῆρχε."},{"number":112,"text":"προσέταξεν οὖν ἀναζητεῖν εἴ τις ἐκ τοῦ γένους αὐτοῦ σώζεται, ᾧ τὰς ἀμοιβὰς ἃς ὤφειλεν Ἰωνάθῃ τῆς ἑταιρίας ἀποδώσει· ἀχθέντος οὖν τινος ἠλευθερωμένου μὲν ὑπὸ Σαούλου δυναμένου δὲ γινώσκειν τοὺς ἐκ τοῦ γένους αὐτοῦ περιόντας, ἀνέκρινεν εἴ τινα ἔχοι λέγειν τῶν Ἰωνάθῃ προσηκόντων ζῶντα καὶ κομίσασθαι τὰς τῶν εὐεργεσιῶν χάριτας δυνάμενον, ὧν καὶ αὐτὸς ἔτυχε παρὰ Ἰωνάθου."},{"number":113,"text":"φήσαντος δʼ υἱὸν αὐτοῦ περιλείπεσθαι Μεμφίβοσθον ὄνομα πεπηρωμένον τὰς βάσεις, τῆς γὰρ τροφοῦ μετὰ τὸ προσαγγελθῆναι τὸν πατέρα τοῦ παιδίου καὶ τὸν πάππον ἐν τῇ μάχῃ πεσόντας ἁρπασαμένης καὶ φευγούσης, ἀπὸ τῶν ὤμων αὐτὸ κατενεχθῆναι καὶ βλαβῆναι τὰς βάσεις, μαθὼν ὅπου καὶ παρὰ τίνι τρέφεται πέμψας πρὸς τὸν Μάχειρον εἰς Λάβαθα πόλιν, παρὰ τούτῳ γὰρ ὁ Ἰωνάθου παῖς ἐτρέφετο, μεταπέμπεται πρὸς αὑτόν."},{"number":114,"text":"ἐλθὼν δʼ ὁ Μεμφίβοσθος πρὸς τὸν βασιλέα πεσὼν ἐπὶ πρόσωπον προσεκύνησεν αὐτόν. ὁ δὲ Δαυίδης θαρρεῖν τε προυτρέπετο καὶ τὰ βελτίω προσδοκᾶν· δίδωσι δʼ αὐτῷ καὶ τὸν πατρῷον οἶκον καὶ πᾶσαν τὴν οὐσίαν, ἣν ὁ πάππος αὐτοῦ Σαοῦλος ἐκτήσατο, σύσσιτόν τε καὶ ὁμοτράπεζον ἐκέλευσεν εἶναι καὶ μηδεμίαν ἡμέραν ἀπολείπεσθαι τῆς σὺν αὐτῷ διαίτης."},{"number":115,"text":"τοῦ δὲ παιδὸς προσκυνήσαντος ἐπί τε τοῖς λόγοις καὶ ταῖς δωρεαῖς, καλέσας τὸν Σιβὰν τὸν πατρῷον οἶκον ἔλεγε δεδωρῆσθαι τῷ παιδὶ καὶ πᾶσαν τὴν Σαούλου κτῆσιν, αὐτόν τε ἐκέλευσεν ἐργαζόμενον αὐτοῦ τὴν γῆν καὶ προνοούμενον ἁπάντων τὴν πρόσοδον εἰς Ἱεροσόλυμα κομίζειν, ἄγειν τε αὐτὸν καθʼ ἑκάστην ἡμέραν ἐπὶ τὴν αὐτοῦ τράπεζαν αὐτὸν Σιβὰν καὶ τοὺς υἱοὺς αὐτοῦ, ἦσαν δʼ οὗτοι πεντεκαίδεκα, καὶ τοὺς οἰκέτας αὐτοῦ τὸν ἀριθμὸν ὄντας εἴκοσι τῷ παιδὶ χαρίζεται Μεμφιβόσθῳ."},{"number":116,"text":"ταῦτα διαταξαμένου τοῦ βασιλέως ὁ μὲν Σιβὰς προσκυνήσας καὶ πάντα ποιήσειν εἰπὼν ἀνεχώρησεν, ὁ δὲ Ἰωνάθου παῖς ἐν Ἱεροσολύμοις κατῴκει συνεστιώμενος τῷ βασιλεῖ καὶ πάσης ὡς υἱὸς αὐτοῦ θεραπείας τυγχάνων· ἐγένετο δʼ αὐτῷ καὶ παῖς, ὃν Μίχανον προσηγόρευσε."}],"6":[{"number":117,"text":"Καὶ οἱ μὲν περιλειφθέντες ἐκ τοῦ Σαούλου γένους καὶ Ἰωνάθου τούτων ἔτυχον παρὰ Δαυίδου τῶν τιμῶν. τελευτήσαντος δὲ κατʼ ἐκεῖνον τὸν χρόνον τοῦ τῶν Ἀμμανιτῶν βασιλέως Ναάσου, φίλος δʼ ἦν οὗτος αὐτῷ, καὶ διαδεξαμένου τὴν βασιλείαν Ἀννὼν τοῦ παιδός, πέμψας Δαυίδης πρὸς αὐτὸν παρεμυθήσατο πρᾴως τε φέρειν ἐπὶ τῷ θανάτῳ τοῦ πατρὸς παραινῶν καὶ τὴν αὐτὴν φιλίαν διαμενεῖν, ἣ πρὸς ἐκεῖνον ἦν, τούτῳ προσδοκᾶν."},{"number":118,"text":"οἱ δὲ τῶν Ἀμμανιτῶν ἄρχοντες κακοήθως ἀλλʼ οὐ κατὰ τὸν Δαυίδου τρόπον ταῦτʼ ἐδέξαντο, καὶ παρώτρυναν τὸν βασιλέα λέγοντες κατασκόπους πεπομφέναι τῆς χώρας Δαυίδην καὶ τῆς αὑτῶν δυνάμεως ἐπὶ προφάσει φιλανθρωπίας, φυλάττεσθαί τε συνεβούλευον καὶ μὴ προσέχειν τοῖς λόγοις αὐτοῦ, μὴ καὶ σφαλεὶς ἀπαρηγορήτῳ συμφορᾷ περιπέσῃ."},{"number":119,"text":"ταῦτʼ οὖν δόξας πιθανώτερα λέγειν τοὺς ἄρχοντας ἢ τἀληθὲς εἶχεν ὁ τῶν Ἀμμανιτῶν βασιλεὺς Ἀννὼν τοὺς παρὰ τοῦ Δαυίδου πεμφθέντας πρέσβεις χαλεπῶς περιύβρισε· ξυρήσας γὰρ αὐτῶν τὰ ἡμίση τῶν γενείων καὶ τὰ ἡμίση τῶν ἱματίων περιτεμὼν ἔργοις ἀπέλυσε κομίζοντας οὐ λόγοις τὰς ἀποκρίσεις."},{"number":120,"text":"ἰδὼν δὲ ταῦθʼ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς ἠγανάκτησε καὶ δῆλος ἦν οὐ περιοψόμενος τὴν ὕβριν καὶ τὸν προπηλακισμόν, ἀλλὰ πολεμήσων τοῖς Ἀμμανίταις καὶ τιμωρίαν αὐτῶν τῆς παρανομίας τῆς πρὸς τοὺς πρεσβευτὰς εἰσπραξόμενος τὸν βασιλέα."},{"number":121,"text":"συνέντες δὲ οἵ τε ἀναγκαῖοι καὶ οἱ ἡγεμόνες, ὅτι παρεσπονδήκασι καὶ δίκην ὑπὲρ τούτων ὀφείλουσι, προπαρασκευάζονται εἰς τὸν πόλεμον· καὶ πέμψαντες πρὸς Σύρον τὸν τῶν Μεσοποταμιτῶν βασιλέα χίλια τάλαντα σύμμαχον αὐτὸν ἐπὶ τούτῳ γενέσθαι τῷ μισθῷ παρεκάλεσαν καὶ Σουβάν· ἦσαν δὲ τοῖς βασιλεῦσι τούτοις πεζοῦ δύο μυριάδες. προσεμισθώσαντο δὲ καὶ τὸν ἐκ τῆς Μιχᾶς καλουμένης χώρας βασιλέα καὶ τέταρτον Ἴστοβον ὄνομα, καὶ τούτους ἔχοντας μυρίους καὶ δισχιλίους ὁπλίτας."},{"number":122,"text":"Οὐ κατεπλάγη δὲ τὴν συμμαχίαν καὶ τὴν τῶν Ἀμμανιτῶν δύναμιν ὁ Δαυίδης, τῷ δὲ θεῷ πεποιθὼς καὶ τῷ δικαίως αὐτοῖς ἀνθʼ ὧν ὑβρίσθη πολεμεῖν μέλλειν, Ἰώαβον τὸν ἀρχιστράτηγον δοὺς αὐτῷ τῆς στρατιᾶς τὸ ἀκμαιότατον ἐξ αὐτῆς ἔπεμψεν ἐπʼ αὐτούς."},{"number":123,"text":"ὁ δὲ πρὸς τῇ μητροπόλει τῶν Ἀμμανιτῶν Ἀραβαθᾶ κατεστρατοπεδεύσατο. τῶν δὲ πολεμίων ἐξελθόντων καὶ παραταξαμένων οὐχ ὁμοῦ διχῇ δέ, τὸ μὲν γὰρ ἐπικουρικὸν ἐν τῷ πεδίῳ καθʼ αὑτὸ ἐτάχθη, τὸ δὲ τῶν Ἀμμανιτῶν στράτευμα πρὸς ταῖς πύλαις ἀντικρὺ τῶν Ἑβραίων, ἰδὼν τοῦτο Ἰώαβος ἀντιμηχανᾶται·"},{"number":124,"text":"καὶ τοὺς μὲν ἀνδρειοτάτους ἐπιλεξάμενος ἀντιπαρατάσσεται τῷ Σύρῳ καὶ τοῖς μετʼ αὐτοῦ βασιλεῦσι, τὸ δʼ ἄλλο παραδοὺς Ἀβεσσαίῳ τῷ ἀδελφῷ τοῖς Ἀμμανίταις ἐκέλευσεν ἀντιπαρατάξασθαι, εἰπὼν ἂν τοὺς Σύρους ἴδῃ βιαζομένους αὐτὸν καὶ πλέον δυναμένους μεταγαγόντα τὴν φάλαγγα βοηθεῖν αὐτῷ, τὸ δʼ αὐτὸ τοῦτο ποιήσειν καὶ αὐτός, ἂν ὑπὸ τῶν Ἀμμανιτῶν αὐτὸν καταπονούμενον θεάσηται."},{"number":125,"text":"προτρεψάμενος οὖν τὸν ἀδελφὸν καὶ παρακαλέσας εὐψύχως καὶ μετὰ προθυμίας ἀνδράσιν αἰσχύνην φοβουμένοις πρεπούσης ἀγωνίσασθαι τὸν μὲν ἀπέλυσε τοῖς Ἀμμανίταις μαχησόμενον, αὐτὸς δὲ τοῖς Σύροις συνέβαλε."},{"number":126,"text":"καὶ πρὸς ὀλίγον ἀντισχόντων αὐτῶν καρτερῶς πολλοὺς μὲν αὐτῶν ἀπέκτεινεν Ἰώαβος, ἅπαντας δʼ ἠνάγκασεν εἰς φυγὴν τραπῆναι. τοῦτο ἰδόντες οἱ Ἀμμανῖται καὶ δείσαντες τὸν Ἀβεσσαῖον καὶ τὴν μετʼ αὐτοῦ στρατιὰν οὐκ ἔμειναν, ἀλλὰ μιμησάμενοι τοὺς συμμάχους εἰς τὴν πόλιν ἔφυγον. κρατήσας οὖν τῶν πολεμίων Ἰώαβος εἰς Ἱεροσόλυμα πρὸς τὸν βασιλέα λαμπρῶς ὑπέστρεψε."},{"number":127,"text":"Τοῦτο τὸ πταῖσμα τοὺς Ἀμμανίτας οὐκ ἔπεισεν ἠρεμεῖν οὐδὲ μαθόντας τοὺς κρείττονας ἡσυχίαν ἄγειν, ἀλλὰ πέμψαντες πρὸς Χαλαμὰν τὸν τῶν πέραν Εὐφράτου Σύρων βασιλέα μισθοῦνται τοῦτον ἐπὶ συμμαχίᾳ, ἔχοντα μὲν ἀρχιστράτηγον Σέβεκον, πεζῶν δὲ μυριάδας ὀκτὼ καὶ ἱππέων μυρίους."},{"number":128,"text":"γνοὺς δʼ ὁ τῶν Ἑβραίων βασιλεὺς πάλιν ἐπʼ αὐτὸν τοὺς Ἀμμανίτας τοσαύτην δύναμιν συνηθροικότας οὐκέτι διὰ στρατηγῶν αὐτοῖς πολεμεῖν ἔκρινεν, ἀλλʼ αὐτὸς σὺν ἁπάσῃ τῇ δυνάμει διαβὰς τὸν Ἰόρδανον ποταμὸν καὶ ὑπαντήσας αὐτοῖς συνάψας εἰς μάχην ἐνίκησε· καὶ ἀναιρεῖ μὲν αὐτῶν πεζῶν μὲν εἰς τέσσαρας μυριάδας ἱππέων δὲ εἰς ἑπτακισχιλίους, ἔτρωσε δὲ καὶ τὸν στρατηγὸν τοῦ Χαλαμᾶ Σέβεκον, ὃς ἐκ τῆς πληγῆς ἀπέθανεν."},{"number":129,"text":"οἱ δὲ Μεσοποταμῖται τοιούτου γενομένου τοῦ τέλους τῆς μάχης αὑτοὺς Δαυίδῃ παρέδοσαν καὶ δῶρα ἔπεμψαν αὐτῷ. καὶ ὁ μὲν ὥρᾳ χειμῶνος ἀνέστρεψεν εἰς Ἱεροσόλυμα, ἀρχομένου δὲ τοῦ ἔαρος ἔπεμψε τὸν ἀρχιστράτηγον Ἰώαβον πολεμήσοντα τοῖς Ἀμμανίταις. ὁ δὲ τήν τε γῆν αὐτῶν ἅπασαν ἐπερχόμενος διέφθειρε καὶ αὐτοὺς εἰς τὴν μητρόπολιν συγκλείσας Ἀραβαθὰ ἐπολιόρκει."}],"7":[{"number":130,"text":"Συνέπεσε δὲ καὶ Δαυίδῃ πταῖσμα δεινὸν ὄντι φύσει δικαίῳ καὶ θεοσεβεῖ καὶ τοὺς πατρίους νόμους ἰσχυρῶς φυλάσσοντι· θεασάμενος γὰρ δείλης ὀψίας ἀπὸ τοῦ στέγους τῶν βασιλείων, ἐν ᾧ περιπατεῖν κατʼ ἐκεῖνο τῆς ὥρας ἦν ἔθος, γυναῖκα λουομένην ἐν τῇ αὑτῆς οἰκίᾳ ψυχρῷ ὕδατι καλλίστην τὸ εἶδος καὶ πασῶν διαφέρουσαν, ὄνομα αὐτῇ ἦν Βεεθσαβή, ἡττᾶται τοῦ κάλλους τῆς γυναικός· καὶ τῆς ἐπιθυμίας κατασχεῖν οὐ δυνάμενος αὐτῇ συνέρχεται."},{"number":131,"text":"γενομένης δʼ ἐγκύου τῆς γυναικὸς καὶ πεμψάσης πρὸς τὸν βασιλέα, ὅπως τῷ ἁμαρτήματι σκέψηταί τινα τοῦ λαθεῖν ὁδόν, ἀποθανεῖν γὰρ αὐτὴν κατὰ τοὺς πατρίους καθήκει νόμους μεμοιχευμένην, μετακαλεῖται τὸν Ἰωάβου μὲν ὁπλοφόρον ἐκ τῆς πολιορκίας ἄνδρα δὲ τῆς γυναικὸς Οὐρίαν ὄνομα, καὶ παραγενόμενον περί τε τῆς στρατιᾶς καὶ τῆς πολιορκίας ἀνέκρινε."},{"number":132,"text":"λέγοντος δὲ πάντα κατὰ νοῦν αὐτοῖς κεχωρηκέναι τὰ πράγματα βαστάσας ἐκ τοῦ δείπνου μέρη προσδίδωσιν αὐτῷ, καὶ κελεύει πρὸς τὴν γυναῖκα ἀπελθόντα ἀναπαύσασθαι σὺν αὐτῇ. ὁ δὲ Οὐρίας τοῦτο μὲν οὐκ ἐποίησε, παρεκοιμήθη δὲ τῷ βασιλεῖ σὺν τοῖς ἄλλοις ὁπλοφόροις."},{"number":133,"text":"ὡς δὲ γνοὺς τοῦθʼ ὁ βασιλεὺς ἀνέκρινεν αὐτόν, ὅτι μὴ πρὸς αὑτὸν εἰς τὴν οἰκίαν ἔλθοι μηδὲ πρὸς τὴν γυναῖκα διὰ τοσούτου χρόνου πάντων ἀνθρώπων ταύτην ἐχόντων τὴν φύσιν ὅταν ἔλθωσιν ἐξ ἀποδημίας, οὐκ εἶναι δίκαιον ἔφη τῶν συστρατιωτῶν αὐτοῦ καὶ τοῦ στρατηγοῦ χαμαὶ κοιμωμένων ἐν παρεμβολῇ καὶ τῇ τῶν πολεμίων χώρᾳ μετὰ γυναικὸς αὐτὸν ἀναπαύεσθαι καὶ τρυφᾶν."},{"number":134,"text":"ταῦτʼ εἰπόντα μεῖναι τὴν ἡμέραν ἐκείνην ἐκέλευσεν αὐτόθι ὡς εἰς τὴν ἐπιοῦσαν ἀπολύσων αὐτὸν πρὸς τὸν ἀρχιστράτηγον. κληθεὶς δʼ ἐπὶ δεῖπνον ὑπὸ τοῦ βασιλέως Οὐρίας καὶ μέχρι μέθης προελθὼν ἐν τῷ πότῳ δεξιουμένου τοῦ βασιλέως αὐτὸν ἐπίτηδες ταῖς προπόσεσιν, οὐδὲν ἧττον πάλιν πρὸ τῶν τοῦ βασιλέως θυρῶν ἐκοιμήθη μηδεμίαν λαβὼν τῆς γυναικὸς ἐπιθυμίαν."},{"number":135,"text":"ἐπὶ τούτοις δὲ δυσανασχετήσας ὁ βασιλεὺς ἔγραψε τῷ Ἰωάβῳ κολάσαι προστάττων τὸν Οὐρίαν, ἁμαρτεῖν γὰρ αὐτὸν ἐδήλου, καὶ τὸν τρόπον τῆς τιμωρίας ἵνα μὴ γένηται φανερὸς αὐτὸς τοῦτο βουληθεὶς ὑπέθετο·"},{"number":136,"text":"κατὰ γὰρ τὸ δυσμαχώτατον αὐτὸν ἐκέλευσε μέρος τῶν πολεμίων τάξαι καὶ καθʼ ὃ κινδυνεύσει μαχόμενος ἀπολειφθεὶς μόνος· τοὺς γὰρ συμπαραστάτας ἀναχωρῆσαι ἐκ τῆς μάχης γινομένης ἐκέλευσε. ταῦτα γράψας καὶ σημηνάμενος τῇ αὑτοῦ σφραγῖδι τὴν ἐπιστολὴν ἔδωκεν Οὐρίᾳ κομίσαι πρὸς Ἰώαβον."},{"number":137,"text":"δεξάμενος δὲ Ἰώαβος τὰ γράμματα καὶ τὴν τοῦ βασιλέως προαίρεσιν ἀναγνούς, καθʼ ὃν ᾔδει τόπον τοὺς πολεμίους χαλεποὺς αὐτῷ γενομένους, κατὰ τοῦτον ἔστησε τὸν Οὐρίαν δοὺς αὐτῷ τινας τῶν ἀρίστων τῆς στρατιᾶς· αὐτὸς δʼ ἁπάσῃ τῇ δυνάμει προσεπιβοηθήσειν ἔφησεν, εἰ δυνηθεῖεν ἀνατρέψαντές τι τοῦ τείχους εἰσελθεῖν εἰς τὴν πόλιν."},{"number":138,"text":"ὄντα δʼ αὐτὸν γενναῖον στρατιώτην καὶ δόξαν ἔχοντα παρά τε τῷ βασιλεῖ καὶ πᾶσι τοῖς ὁμοφύλοις ἐπʼ ἀνδρείᾳ χαίρειν τοῖς μεγάλοις πόνοις ἀλλὰ μὴ προσαγανακτεῖν ἠξίου. τοῦ δʼ Οὐρία προθύμως ὑποστάντος τὸ ἔργον, τοῖς μετʼ αὐτοῦ παρατασσομένοις ἰδίᾳ καταλιπεῖν ὅταν ἐξορμήσαντας ἴδωσι τοὺς πολεμίους ἐδήλωσε."},{"number":139,"text":"προσβαλόντων οὖν τῇ πόλει τῶν Ἑβραίων δείσαντες οἱ Ἀμμανῖται, μὴ κατʼ ἐκεῖνον τὸν τόπον, καθʼ ὃν Οὐρίαν συνέβαινε τετάχθαι, φθάσαντες ἀναβῶσιν οἱ πολέμιοι, προστησάμενοι τοὺς ἀνδρειοτάτους αὐτῶν καὶ τὴν πύλην ἀνοίξαντες αἰφνιδίως καὶ μετὰ ῥύμης καὶ δρόμου πολλοῦ τοῖς ἐχθροῖς ἐπεξῆλθον."},{"number":140,"text":"ἰδόντες δὲ αὐτοὺς οἱ σὺν τῷ Οὐρίᾳ πάντες ἀνεχώρησαν ὀπίσω, καθὼς Ἰώαβος αὐτοῖς προεῖπεν· αἰσχυνθεὶς δʼ Οὐρίας φυγεῖν καὶ τὴν τάξιν καταλιπεῖν ὑπέμεινε τοὺς πολεμίους· καὶ τὴν ὁρμὴν αὐτῶν ἐκδεξάμενος ἀναιρεῖ μὲν οὐκ ὀλίγους, κυκλωθεὶς δὲ καὶ ληφθεὶς ἐν μέσῳ ἅμα δʼ αὐτῷ τινες καὶ ἄλλοι τελευτᾷ συγκαταπεσόντων ἑτέρων."},{"number":141,"text":"Τούτων οὕτως γενομένων ἔπεμψεν ἀγγέλους Ἰώαβος πρὸς τὸν βασιλέα λέγειν ἐντειλάμενος αὐτοῖς, ὡς σπουδάσειε μὲν ταχέως ἑλεῖν τὴν πόλιν, προσβαλὼν δὲ τῷ τείχει καὶ πολλοὺς ἀπολέσας ἀναχωρῆσαι βιασθείη· προστιθέναι δὲ τούτοις ἂν ὀργιζόμενον ἐπʼ αὐτοῖς βλέπωσι καὶ τὸν Οὐρία θάνατον."},{"number":142,"text":"τοῦ δὲ βασιλέως ἀκούσαντος παρὰ τῶν ἀγγέλων ταῦτα καὶ δυσφοροῦντος φάσκοντος ἁμαρτεῖν αὐτοὺς τῷ τείχει προσβαλόντας, δέον ὑπονόμοις καὶ μηχανήμασιν ἑλεῖν πειρᾶσθαι τὴν πόλιν, καὶ ταῦτʼ ἔχοντας παράδειγμα τὸν Γεδεῶνος υἱὸν Ἀβιμέλεχον, ὃς ἐπεὶ τὸν ἐν Θήβαις πύργον ἑλεῖν ἐβούλετο βίᾳ, βληθεὶς ὑπὸ πρεσβύτιδος πέτρῳ κατέπεσε καὶ ἀνδρειότατος ὢν διὰ τὸ δυσχερὲς τῆς ἐπιβολῆς αἰσχρῶς ἀπέθανεν·"},{"number":143,"text":"οὗ μνημονεύοντας ἔδει μὴ προσιέναι τῷ τείχει τῶν πολεμίων· ἄριστον γὰρ ἁπάντων τῶν ἐν πολέμῳ πραχθέντων καὶ καλῶς καὶ ὡς ἑτέρως ἐνίοις αὐτοῖς κινδύνοις μνήμην ἔχειν, ὡς τὰ μὲν μιμεῖσθαι τὰ δὲ φυλάττεσθαι."},{"number":144,"text":"ἐπεὶ δὲ οὕτως ἔχοντι καὶ τὸν Οὐρία θάνατον ἐδήλωσεν ὁ ἄγγελος, παύεται μὲν τῆς ὀργῆς, Ἰωάβῳ δʼ ἐκέλευσεν ἀπελθόντα λέγειν ἀνθρώπινον εἶναι τὸ συμβεβηκὸς καὶ τὰ τοῦ πολέμου φύσιν ἔχειν τοιαύτην, ὥστε ποτὲ μὲν τοῖς ἐναντίοις εὖ πράττειν συμβαίνειν κατʼ αὐτόν, ποτὲ δὲ τοῖς ἑτέροις·"},{"number":145,"text":"τοῦ λοιποῦ μέντοι γε προνοεῖν τῆς πολιορκίας, ὅπως μηδὲν ἔτι πταίσωσι κατʼ αὐτήν, ἀλλὰ χώμασι καὶ μηχαναῖς ἐκπολιορκήσαντας καὶ παραστησαμένους τὴν μὲν πόλιν κατασκάψαι, ἅπαντας δʼ ἀπολέσαι τοὺς ἐν αὐτῇ. καὶ ὁ μὲν ἄγγελος τὰ ὑπὸ τοῦ βασιλέως ἐντεταλμένα κομίζων πρὸς Ἰώαβον ἠπείγετο."},{"number":146,"text":"ἡ δὲ τοῦ Οὐρία γυνὴ Βεεθσαβὴ τὸν θάνατον τἀνδρὸς πυθομένη ἐπὶ συχνὰς αὐτὸν ἡμέρας ἐπένθησεν, παυσαμένην δὲ τῆς λύπης καὶ τῶν ἐπʼ Οὐρίᾳ δακρύων ὁ βασιλεὺς εὐθὺς ἄγεται γυναῖκα, καὶ παῖς ἄρρην ἐξ αὐτῆς γίνεται αὐτῷ."},{"number":147,"text":"Τοῦτον οὐχ ἡδέως ἐπεῖδεν ὁ θεὸς τὸν γάμον, ἀλλὰ διʼ ὀργῆς ἔχων τὸν Δαυίδην τῷ προφήτῃ Νάθᾳ φανεὶς κατὰ τοὺς ὕπνους ἐμέμφετο τὸν βασιλέα. ὁ δὲ Νάθας ἀστεῖος καὶ συνετὸς ὢν ἀνήρ, λογισάμενος ὡς οἱ βασιλεῖς ὅταν εἰς ὀργὴν ἐμπέσωσι ταύτῃ πλέον ἢ τῷ δικαίῳ νέμουσι, τὰς μὲν παρὰ τοῦ θεοῦ γεγενημένας ἀπειλὰς ἡσυχάζειν ἔκρινεν, ἄλλους δὲ λόγους χρηστοὺς πρὸς αὐτὸν διεξῆλθε,"},{"number":148,"text":"καὶ δὴ τοιοῦτόν τινα τρόπον περὶ οὗ καὶ τί φρονεῖ ποιῆσαι σαφὲς αὐτῷ παρεκάλει· δύο γάρ, ἔφησεν, ἄνδρες τὴν αὐτὴν κατῴκουν πόλιν, ὧν ὁ μὲν πλούσιος ἦν καὶ πολλὰς εἶχεν ἀγέλας ὑποζυγίων τε καὶ θρεμμάτων καὶ βοῶν, τῷ πένητι δʼ ἀμνὰς ὑπῆρχε μία."},{"number":149,"text":"ταύτην μετὰ τῶν τέκνων αὐτοῦ ἀνέτρεφε συνδιαιρούμενος αὐτῇ τὰ σιτία καὶ φιλοστοργίᾳ πρὸς αὐτὴν χρώμενος ᾗ τις ἂν χρήσαιτο καὶ πρὸς θυγατέρα. ξένου δʼ ἐπελθόντος τῷ πλουσίῳ τῶν μὲν ἰδίων οὐδὲν ἠξίωσεν ἐκεῖνος βοσκημάτων καταθύσας εὐωχῆσαι τὸν φίλον, πέμψας δὲ τὴν ἀμνάδα τοῦ πένητος ἀπέσπασε, καὶ ταύτην παρασκευάσας εἱστίασε τὸν ξένον."},{"number":150,"text":"σφόδρα ἐλύπησεν ὁ λόγος οὗτος τὸν βασιλέα καὶ πονηρὸν πρὸς τὸν Νάθαν τὸν ἄνθρωπον ἐκεῖνον, ὃς δὴ τοῦτο τὸ ἔργον ἐτόλμησεν, ἀπεφήνατο καὶ τετραπλὴν ἀποτῖσαι τὴν ἀμνάδα δίκαιον εἶναι καὶ πρὸς τούτῳ θανάτῳ κολασθῆναι. Νάθας δʼ ὑποτυχὼν αὐτὸν ἔλεγεν ἐκεῖνον εἶναι τὸν ἄξιον ταῦτα παθεῖν ὑφʼ ἑαυτοῦ κεκριμένον τολμήσαντα μέγα καὶ δεινὸν ἔργον."},{"number":151,"text":"ἀνεκάλυπτε δʼ αὐτῷ καὶ παρεγύμνου τὴν ὀργὴν τοῦ θεοῦ ποιήσαντος μὲν αὐτὸν βασιλέα πάσης τῆς Ἑβραίων δυνάμεως καὶ τῶν ἐν κύκλῳ πάντων ἐθνῶν πολλῶν καὶ μεγάλων κύριον, ῥυσαμένου δʼ ἔτι πρὸ τούτων ἐκ τῶν Σαούλου χειρῶν, δόντος δʼ αὐτῷ καὶ γυναῖκας ἃς δικαίως καὶ νομίμως ἠγάγετο, καταφρονηθέντος δʼ ὑπʼ αὐτοῦ καὶ ἀσεβηθέντος, ὃς ἀλλοτρίαν τε γήμας ἔχει γυναῖκα καὶ τὸν ἄνδρα αὐτῆς ἀποκτείνειεν ἐκδοὺς τοῖς πολεμίοις·"},{"number":152,"text":"δώσειν οὖν αὐτὸν ἀντὶ τούτων δίκας τῷ θεῷ καὶ βιασθήσεσθαι μὲν αὐτοῦ τὰς γυναῖκας ὑφʼ ἑνὸς τῶν παίδων, ἐπιβουλευθήσεσθαι δὲ καὶ αὐτὸν ὑπʼ ἐκείνου, καὶ τὸ ἁμάρτημα τοῦτο κρύφα δράσαντα φανερὰν τὴν ἐπʼ αὐτῷ δίκην ὑφέξειν· τεθνήξεσθαι δὲ καὶ τὸν παῖδά σοι παραχρῆμα τὸν ἐξ αὐτῆς γεγενημένον."},{"number":153,"text":"ταραχθέντος δʼ ἐπὶ τούτοις τοῦ βασιλέως καὶ συσχεθέντος ἱκανῶς καὶ μετὰ δακρύων καὶ λύπης ἀσεβῆσαι λέγοντος, ἦν γὰρ ὁμολογουμένως θεοσεβὴς καὶ μηδὲν ἁμαρτὼν ὅλως περὶ τὸν βίον ἢ τὰ περὶ τὴν Οὐρία γυναῖκα, ᾤκτειρεν ὁ θεὸς καὶ διαλλάττεται φυλάξειν αὐτῷ καὶ τὴν ζωὴν καὶ τὴν βασιλείαν ἐπαγγειλάμενος· μετανοοῦντι γὰρ περὶ τῶν γεγενημένων οὐκέτι χαλεπῶς ἔχειν ἔφασκε. καὶ Νάθας μὲν ταῦτα τῷ βασιλεῖ προφητεύσας οἴκαδε ἐπανῆλθε."},{"number":154,"text":"Τῷ δʼ ἐκ τῆς Οὐρία γυναικὸς γενομένῳ παιδὶ Δαυίδῃ νόσον ἐνσκήπτει χαλεπὴν τὸ θεῖον, ἐφʼ ᾗ δυσφορῶν ὁ βασιλεὺς τροφὴν μὲν ἐφʼ ἡμέρας ἑπτὰ καίτοι γε ἀναγκαζόντων τῶν οἰκείων οὐ προσηνέγκατο, μέλαιναν δὲ περιθέμενος ἐσθῆτα πεσὼν ἐπὶ σάκκου κατὰ γῆς ἔκειτο τὸν θεὸν ἱκετεύων ὑπὲρ τῆς τοῦ παιδὸς σωτηρίας· σφόδρα γὰρ ἔστεργεν αὐτοῦ τὴν μητέρα."},{"number":155,"text":"τῇ δʼ ἑβδόμῃ τῶν ἡμερῶν τελευτήσαντος τοῦ παιδὸς οὐκ ἐτόλμων τῷ βασιλεῖ τοῦτο μηνύειν οἱ θεράποντες λογιζόμενοι, μὴ γνοὺς ἔτι μᾶλλον ἀπόσχηται καὶ τροφῆς καὶ τῆς ἄλλης ἐπιμελείας ὡς ἂν ἐπὶ ποθεινοῦ τέκνου τετελευτηκότος, ὅτε καὶ νοσοῦντος οὕτως ὑπὸ τῆς λύπης ἑαυτὸν ἐκάκου."},{"number":156,"text":"ταραττομένων δʼ αἰσθόμενος τῶν οἰκετῶν ὁ βασιλεὺς καὶ ταῦτα πασχόντων, ἃ μάλιστα συγκρύψαι τι θέλουσι συμβαίνει, συνεὶς ὅτι τέθνηκεν ὁ παῖς προσφωνήσας ἕνα τῶν οἰκετῶν καὶ μαθὼν τἀληθὲς ἀνίσταται καὶ λουσάμενος καὶ λαβὼν ἐσθῆτα λευκὴν εἰς τὴν σκηνὴν τοῦ θεοῦ παραγίνεται,"},{"number":157,"text":"καὶ κελεύσας δεῖπνον αὑτῷ παραθεῖναι πολλὴν ἐπὶ τῷ παραλόγῳ τοῖς τε συγγενέσι καὶ τοῖς οἰκέταις ἔκπληξιν παρεῖχεν, ὅτι μηδὲν τούτων ἐπὶ νοσοῦντι τῷ παιδὶ ποιήσας πάνθʼ ὁμοῦ τετελευτηκότος ἔπραττε. τήν τε αἰτίαν, δεηθέντες ἐπιτρέψαι πρῶτον αὐτοῖς πυθέσθαι, παρεκάλουν εἰπεῖν τῶν γεγενημένων."},{"number":158,"text":"ὁ δὲ ἀμαθεῖς εἰπὼν αὐτοὺς ἐδίδασκεν, ὡς ἔτι μὲν ζῶντος τοῦ παιδὸς ἔχων ἐλπίδα σωτηρίας αὐτοῦ δεόντως πάντʼ ἐποίει τὸν θεὸν ἡγούμενος τούτοις εὐμενῆ καταστήσειν, ἀποθανόντος δʼ οὐκέτι χρείαν εἶναι λύπης ματαίας. ταῦτʼ εἰπόντος ἐπῄνεσαν τὴν σοφίαν καὶ τὴν διάνοιαν τοῦ βασιλέως. συνελθὼν δὲ τῇ γυναικὶ Βεεθσαβῇ ἔγκυον αὐτὴν ἐποίησε, καὶ γεννησαμένης ἄρρεν παιδίον Σολόμωνα τοῦτον προσηγόρευσεν, οὕτως Νάθα τοῦ προφήτου κελεύσαντος."},{"number":159,"text":"Ἰώαβος δὲ τῇ πολιορκίᾳ τοὺς Ἀμμανίτας ἰσχυρῶς ἐκάκου τῶν τε ὑδάτων αὐτοὺς ἀποτεμνόμενος καὶ τῆς τῶν ἄλλων εὐπορίας, ὡς πάνυ ταλαιπωρεῖν ἐνδείᾳ ποτοῦ καὶ τροφῆς. ἐξ ὀλίγου γὰρ φρέατος ἤρτηντο καὶ ταμείας ὡς μὴ τελέως αὐτοὺς ἐπιλιπεῖν τὴν πηγὴν δαψιλέστερον χρωμένους."},{"number":160,"text":"γράφει δὴ τῷ βασιλεῖ ταῦτα δηλῶν καὶ παρακαλῶν αὐτὸν ἐπὶ τὴν αἵρεσιν τῆς πόλεως ἐλθεῖν, ἵνα τὴν νίκην αὐτὸς ἐπιγραφῇ. ταῦτα Ἰωάβου γράψαντος ἀποδεξάμενος αὐτὸν τῆς εὐνοίας καὶ τῆς πίστεως ὁ βασιλεὺς παραλαβὼν τὴν σὺν αὐτῷ δύναμιν ἧκεν ἐπὶ τὴν τῆς Ῥαβαθᾶς πόρθησιν, καὶ κατὰ κράτος ἑλὼν διαρπάσαι τοῖς στρατιώταις ἐφῆκεν."},{"number":161,"text":"αὐτὸς δὲ τὸν τοῦ βασιλέως τῶν Ἀμμανιτῶν λαμβάνει στέφανον ἕλκοντα χρυσοῦ τάλαντον καὶ πολυτελῆ λίθον ἔχοντα ἐν μέσῳ σαρδόνυχος· ἐφόρει δʼ αὐτὸν ἐπὶ τῆς κεφαλῆς διαπαντὸς Δαυίδης. πολλὰ δὲ καὶ ἄλλα σκῦλα λαμπρὰ καὶ πολύτιμα εὗρεν ἐν τῇ πόλει· τοὺς δʼ ἄνδρας αἰκισάμενος διέφθειρε. ταὐτὰ δὲ καὶ τὰς ἄλλας τῶν Ἀμμανιτῶν πόλεις διέθηκεν ἑλὼν αὐτὰς κατὰ κράτος."}],"8":[{"number":162,"text":"Ἀναστρέψαντος δὲ εἰς Ἱεροσόλυμα τοῦ βασιλέως πταῖσμα αὐτοῦ τὴν οἰκίαν ἐξ αἰτίας τοιαύτης καταλαμβάνει· θυγάτηρ γὰρ ἦν αὐτῷ παρθένος μὲν ἔτι τὸ δὲ κάλλος εὐπρεπής, ὡς ἁπάσας ὑπερβάλλειν τὰς εὐμορφοτάτας γυναῖκας, Θήμαρ ὄνομα, τῆς δʼ αὐτῆς Ἀψαλώμῳ μητρὸς κεκοινωνηκυῖα."},{"number":163,"text":"ταύτης ὁ πρεσβύτατος τῶν Δαυίδου παίδων Ἀμνὼν ἐρασθείς, ὡς οὔτε διὰ τὴν παρθενίαν αὐτῆς οὔτε διὰ τὴν φυλακὴν τυχεῖν τῆς ἐπιθυμίας ἐδύνατο χαλεπῶς διέκειτο, καὶ τό τε σῶμα τῆς ὀδύνης αὐτὸν κατεσθιούσης κατισχναίνετο καὶ τὴν χρόαν μετέβαλλε."},{"number":164,"text":"δῆλος δὲ γίνεται ταῦτα πάσχων Ἰωνάθῃ τινὶ συγγενεῖ καὶ φίλῳ· συνετὸς δʼ ἦν οὗτος ἐν τοῖς μάλιστα καὶ τὴν διάνοιαν ὀξύς. ὁρῶν οὖν καθʼ ἑκάστην πρωίαν τὸν Ἀμνῶνα μὴ κατὰ φύσιν ἔχοντα τῷ σώματι προσελθὼν ἠρώτα φράσαι τὴν αἰτίαν αὐτῷ, εἰκάζειν μέντοι γε οὕτως ἔλεγεν ἐξ ἐρωτικῆς αὐτὸν ἔχειν ἐπιθυμίας."},{"number":165,"text":"τοῦ δὲ Ἀμνῶνος ὁμολογήσαντος τὸ πάθος ὅτι τῆς ἀδελφῆς ἐρᾷ τυγχανούσης ὁμοπατρίας, ὁδὸν αὐτῷ καὶ μηχανὴν εἰς τὸ περιγενέσθαι τῶν εὐκταίων ὑπέθετο· νόσον γὰρ ὑποκρίνασθαι παρῄνεσεν, ἐλθόντα δὲ πρὸς αὐτὸν τὸν πατέρα πέμψαι τὴν ἀδελφὴν αὐτῷ διακονησομένην ἐκέλευσε παρακαλέσαι· ῥᾴω γὰρ ἔσεσθαι καὶ ταχέως ἀπαλλαγήσεσθαι τῆς νόσου τούτου γενομένου."},{"number":166,"text":"πεσὼν οὖν ὁ Ἀμνὼν ἐπὶ τὴν κλίνην νοσεῖν προσεποιήσατο κατὰ τὰς Ἰωνάθου ὑποθήκας. παραγενομένου δὲ τοῦ πατρὸς καὶ σκεπτομένου πῶς ἔχοι, τὴν ἀδελφὴν ἐδεῖτο πέμψαι πρὸς αὐτόν· ὁ δʼ εὐθὺς ἐκέλευσεν ἀχθῆναι. ἡκούσῃ δὲ προσέταξεν ἄρτους αὐτῷ ποιῆσαι τηγανιστοὺς αὐτουργῷ γενομένῃ· προσοίσεσθαι γὰρ ἥδιον ἐκ τῶν ἐκείνης χειρῶν."},{"number":167,"text":"ἡ δʼ ἐμβλέποντος τἀδελφοῦ φυράσασα τὸ ἄλευρον καὶ πλάσασα κολλυρίδας καὶ τηγανίσασα προσήνεγκεν αὐτῷ· ὁ δὲ τότε μὲν οὐκ ἐγεύσατο, προσέταξε δὲ τοῖς οἰκέταις παραιτήσασθαι πάντας πρὸ τοῦ δωματίου· βούλεσθαι γὰρ ἀναπαύσασθαι θορύβου καὶ ταραχῆς ἀπηλλαγμένος."},{"number":168,"text":"ὡς δὲ τὸ κελευσθὲν ἐγένετο, τὴν ἀδελφὴν ἠξίωσεν εἰς τὸν ἐνδοτέρω τὸ δεῖπνον οἶκον αὐτῷ παρενεγκεῖν· ποιησάσης δὲ τοῦτο τῆς κόρης λαβόμενος αὐτῆς συνελθεῖν αὐτῷ πείθειν ἐπειρᾶτο. ἀνακραγοῦσα δʼ ἡ παῖς ἀλλὰ μὴ σύ γε τοῦτο βιάσῃ με μηδὲ ἀσεβήσῃς, εἶπεν, ἀδελφέ, τοὺς νόμους παραβὰς καὶ δεινῇ περιβαλὼν σαυτὸν αἰσχύνῃ· παῦσαι δʼ οὕτως ἀδίκου καὶ μιαρᾶς ἐπιθυμίας, ἐξ ἧς ὀνείδη καὶ κακοδοξίαν ὁ οἶκος ἡμῶν κερδανεῖ."},{"number":169,"text":"συνεβούλευέ τε περὶ τούτου διαλεχθῆναι τῷ πατρί· συγχωρήσειν γὰρ ἐκεῖνον. ταῦτα δʼ ἔλεγε βουλομένη τὴν ὁρμὴν αὐτοῦ τῆς ὀρέξεως πρὸς τὸ παρὸν διαφυγεῖν. ὁ δʼ οὐ πείθεται, τῷ δὲ ἔρωτι καιόμενος καὶ τοῖς τοῦ πάθους κέντροις μυωπιζόμενος βιάζεται τὴν ἀδελφήν."},{"number":170,"text":"μῖσος δʼ εὐθέως μετὰ τὴν κορείαν εἰσέρχεται τὸν Ἀμνῶνα καὶ προσλοιδορησάμενος ἐκέλευσεν ἀναστᾶσαν ἀπιέναι. τῆς δὲ χείρω τὴν ὕβριν καὶ διὰ τοῦτο ἀποκαλούσης, εἰ βιασάμενος αὐτὸς μηδʼ ἄχρι νυκτὸς ἐπιτρέπει μεῖναι παραχρῆμα δʼ ἀπαλλάττεσθαι κελεύει ἐν ἡμέρᾳ καὶ φωτί, ἵνα καὶ μάρτυσι τῆς αἰσχύνης περιπέσοι, προσέταξεν αὐτὴν ἐκβαλεῖν τῷ οἰκέτῃ."},{"number":171,"text":"ἡ δὲ περιαλγὴς ἐπὶ τῇ ὕβρει καὶ τῇ βίᾳ γενομένη περιρρήξασα τὸν χιτωνίσκον, ἐφόρουν γὰρ αἱ τῶν ἀρχαίων παρθένοι χειριδωτοὺς ἄχρι τῶν σφυρῶν πρὸς τὸ μὴ βλέπεσθαι χιτῶνας, καὶ σποδὸν καταχεαμένη τῆς κεφαλῆς ἀπῄει διὰ τῆς πόλεως μέσης βοῶσα καὶ ὀδυρομένη τὴν βίαν."},{"number":172,"text":"περιτυχὼν δʼ αὐτῇ ὁ ἀδελφὸς Ἀψάλωμος ἀνέκρινε, τίνος αὐτῇ δεινοῦ συμβάντος οὕτως ἔχει, κατειπούσης δʼ αὐτῆς πρὸς αὐτὸν τὴν ὕβριν ἡσυχάζειν καὶ μετρίως φέρειν παρηγόρει καὶ μὴ νομίζειν ὑβρίσθαι φθαρεῖσαν ὑπʼ ἀδελφοῦ. πεισθεῖσα οὖν παύεται τῆς βοῆς καὶ τοῦ πρὸς πολλοὺς τὴν βίαν ἐκφέρειν, καὶ πολὺν χρόνον χηρεύουσα παρὰ Ἀψαλώμῳ τῷ ἀδελφῷ διεκαρτέρησε."},{"number":173,"text":"Γνοὺς δὲ τοῦθʼ ὁ πατὴρ Δαυίδης τοῖς μὲν πεπραγμένοις ἤχθετο, φιλῶν δὲ τὸν Ἀμνῶνα σφόδρα, πρεσβύτατος γὰρ ἦν αὐτῷ υἱός, μὴ λυπεῖν αὐτὸν ἠναγκάζετο. ὁ δὲ Ἀψάλωμος ἐμίσει χαλεπῶς αὐτὸν καὶ λανθάνων καιρὸν εἰς ἄμυναν αὐτοῦ τῆς ἁμαρτίας ἐπιτήδειον παρεφύλαττεν."},{"number":174,"text":"ἔτος δʼ ἤδη τοῖς περὶ τὴν ἀδελφὴν αὐτοῦ πταίσμασιν διεληλύθει δεύτερον, καὶ μέλλων ἐπὶ τὴν τῶν ἰδίων κουρὰν ἐξιέναι θρεμμάτων εἰς Βελσεφών, πόλις δʼ ἐστὶν αὕτη τῆς Ἐφράμου κληρουχίας, παρακαλεῖ τὸν πατέρα σὺν καὶ τοῖς ἀδελφοῖς ἐλθεῖν πρὸς αὐτὸν ἐφʼ ἑστίασιν."},{"number":175,"text":"παραιτησαμένου δʼ ὡς μὴ βαρὺς αὐτῷ γένοιτο, τοὺς ἀδελφοὺς ἀποστεῖλαι παρεκάλεσε. πέμψαντος δὲ τοῖς ἰδίοις ἐκέλευσεν ὁπηνίκʼ ἂν ἴδωσι τὸν Ἀμνῶνα μέθῃ παρειμένον καὶ κάρῳ, νεύσαντος αὐτοῦ φονεύσωσι μηδένα φοβηθέντες."},{"number":176,"text":"Ὡς δʼ ἐποίησαν τὸ προσταχθὲν ἔκπληξις καὶ ταραχὴ τοὺς ἀδελφοὺς λαμβάνει, καὶ δείσαντες τοῖς αὑτῶν ἐμπηδήσαντες ἵπποις ἐφέροντο πρὸς τὸν πατέρα. φθάσας δέ τις αὐτοὺς ἅπαντας ὑπὸ Ἀψαλώμου πεφονεῦσθαι τῷ πατρὶ προσήγγειλεν."},{"number":177,"text":"ὁ δʼ ὡς ἐπὶ παισὶν ὁμοῦ τοσούτοις ἀπολωλόσι καὶ τοῦθʼ ὑπʼ ἀδελφοῦ τῆς λύπης κἀπὶ τῷ κτεῖναι δυναμένης δοκοῦντι γινομένης πικρότερον, συναρπαγεὶς ὑπὸ τοῦ πάθους οὔτε τὴν αἰτίαν ἀνέκρινεν οὔτʼ ἄλλο τι μαθεῖν οἷον εἰκὸς τηλικούτου προσηγγελμένου κακοῦ καὶ διʼ ὑπερβολὴν ἀπιστίαν ἔχοντος περιέμεινεν, ἀλλὰ καταρρηξάμενος τὴν ἐσθῆτα καὶ ῥίψας ἑαυτὸν ἐπὶ τὴν γῆν ἔκειτο πενθῶν τοὺς υἱοὺς ἅπαντας καὶ τοὺς ἀποθανεῖν δεδηλωμένους καὶ τὸν ἀνῃρηκότα."},{"number":178,"text":"ὁ δὲ Σαμᾶ τοῦ ἀδελφοῦ αὐτοῦ παῖς Ἰωνάθης ἀνεῖναί τι τῆς λύπης παρεκάλει καὶ περὶ μὲν τῶν ἄλλων μὴ πιστεύειν ὡς τεθνᾶσιν, οὐδὲ γὰρ αἰτίαν εὑρίσκειν ὑπολαμβάνειν, περὶ δʼ Ἀμνῶνος ἐξετάζειν ἔφη δεῖν· εἰκὸς γὰρ διὰ τὴν Θημάρης ὕβριν ἀποτολμῆσαι τὸν Ἀψάλωμον τὴν ἀναίρεσιν τὴν ἐκείνου."},{"number":179,"text":"μεταξὺ δὲ κτύπος ἵππων καὶ θόρυβος προσιόντων τινῶν αὐτοὺς ἐπέστρεψεν· ἦσαν δʼ οἱ τοῦ βασιλέως παῖδες οἱ διαδράντες ἀπὸ τῆς ἑστιάσεως. ὑπαντᾷ δʼ αὐτοῖς ὁ πατὴρ θρηνοῦσι λυπούμενος καὶ παρʼ ἐλπίδας ὁρῶν οὓς ἀκηκόει μικρὸν ἔμπροσθεν ἀπολωλότας."},{"number":180,"text":"ἦν δὲ παρὰ πάντων δάκρυα καὶ στόνος, τῶν μὲν ὡς ἐπʼ ἀδελφῷ τετελευτηκότι, τοῦ δὲ βασιλέως ὡς ἐπὶ παιδὶ κατεσφαγμένῳ. φεύγει δʼ Ἀψάλωμος εἰς Γεσσούραν πρὸς τὸν πάππον τὸν πρὸς μητρὸς δυναστεύοντα τῆς ἐκεῖ χώρας, καὶ τρισὶν ὅλοις ἔτεσι παρʼ αὐτῷ καταμένει."},{"number":181,"text":"Τοῦ δὲ Δαυίδου προαίρεσιν ἔχοντος ἐπὶ τὸν υἱὸν Ἀψάλωμον πέμπειν, οὐκ ἐπὶ τιμωρίᾳ κατελευσόμενον, ἀλλʼ ὅπως εἴη σὺν αὐτῷ, καὶ γὰρ τὰ τῆς ὀργῆς ὑπὸ τοῦ χρόνου λελωφήκει, πρὸς τοῦτο μᾶλλον αὐτὸν Ἰώαβος ὁ ἀρχιστράτηγος παρώρμησε·"},{"number":182,"text":"γύναιον γάρ τι τὴν ἡλικίαν ἤδη προβεβηκὸς ἐποίησεν αὐτῷ προσελθεῖν ἐν σχήματι πενθίμῳ, ὡς παίδων ἐπὶ τῆς ἀγροικίας αὐτῇ διενεχθέντων καὶ πρὸς φιλονεικίαν τραπέντων οὐδενὸς τοῦ καταπαῦσαι δυναμένου παραφανέντος ἔλεγεν ὑπὸ θατέρου τὸν ἕτερον πληγέντα ἀποθανεῖν·"},{"number":183,"text":"ἠξίου τε τῶν συγγενῶν ἐπὶ τὸν ἀνῃρηκότα ὡρμηκότων καὶ ζητούντων αὐτὸν ἀνελεῖν, χαρίσασθαι τὴν σωτηρίαν αὐτῇ τοῦ παιδὸς καὶ μὴ τὰς ἐπιλοίπους τῆς γηρωκομίας ἐλπίδας προσαφαιρεθῆναι· τοῦτο δʼ αὐτῇ κωλύσαντα τοὺς βουλομένους ἀποκτεῖναι τὸν υἱὸν αὐτῆς παρέξειν· οὐ γὰρ ἐφέξειν ἐκείνους ἄλλῳ τινὶ τῆς σπουδῆς ἢ τῷ παρʼ αὐτοῦ φόβῳ."},{"number":184,"text":"τοῦ δὲ συγκαταινέσαντος οἷς τὸ γύναιον ἱκέτευσεν, ὑπολαβὸν πάλιν πρὸς τὸν βασιλέα χάρις μέν, εἶπεν, ἤδη σου τῇ χρηστότητι κατοικτείραντός μου τὸ γῆρας καὶ τὴν παρὰ μικρὸν ἀπαιδίαν, ἀλλʼ ἵνα βέβαια τὰ παρὰ τῆς σῆς μοι ᾖ φιλανθρωπίας, τῷ σαυτοῦ παιδὶ πρῶτον καταλλάγηθι καὶ τὴν πρὸς αὐτὸν ὀργὴν ἄφες·"},{"number":185,"text":"πῶς γὰρ ἂν πεισθείην ἐμοί σε ταύτην ἀληθῶς δεδωκέναι τὴν χάριν αὐτοῦ σοῦ μέχρι νῦν ἐφʼ ὁμοίοις ἀπεχθανομένου τῷ παιδί;"},{"number":186,"text":"τελέως δʼ ἀνόητον εἶναι προσθεῖναι τῷ παρὰ γνώμην ἀποθανόντι υἱῷ ἄλλον ἑκουσίως. συνίησι δὲ ὁ βασιλεὺς ὑπόβλητον οὖσαν τὴν σκῆψιν ἐξ Ἰωάβου καὶ τῆς τούτου σπουδῆς· καὶ ἐπειδὴ παρὰ τῆς πρεσβύτιδος πυθόμενος οὕτως ἔχον τἀληθὲς ἔμαθε, προσκαλεσάμενος τὸν Ἰώαβον ἐπιτυχεῖν τε τοῦ προκειμένου κατὰ νοῦν ἔφασκε καὶ τὸν Ἀψάλωμον ἄγειν ἐκέλευεν· οὐ γὰρ ἔτι χαλεπῶς ἔχειν πρὸς αὐτόν, ἀλλʼ ἤδη τὴν ὀργὴν καὶ τὸν θυμὸν ἀφεικέναι."},{"number":187,"text":"ὁ δὲ προσκυνήσας τὸν βασιλέα καὶ τοὺς λόγους ἀσπασάμενος ἐξώρμησεν εἰς τὴν Γεσσούραν παραυτίκα καὶ τὸν Ἀψάλωμον παραλαβὼν ἧκεν εἰς Ἱεροσόλυμα."},{"number":188,"text":"Προέπεμψε δὲ ὁ βασιλεὺς πρόσθεν πρὸς τὸν υἱόν, ἤκουσε γὰρ παραγενόμενον, καὶ πρὸς ἑαυτὸν ἐκέλευσε χωρεῖν· οὔπω γὰρ οὕτως ἔχειν ὥστʼ εὐθὺς ἰδεῖν κατελθόντα. καὶ ὁ μὲν τοῦτο τοῦ πατρὸς κελεύσαντος ἐξέκλινε τὴν ὄψιν αὐτοῦ καὶ διετέλει τῆς παρὰ τῶν οἰκείων θεραπείας τυγχάνων."},{"number":189,"text":"οὐκ ἐπιβέβλαπτο δʼ εἰς τὸ κάλλος ὑπό τε τῆς λύπης καὶ τοῦ μὴ τυγχάνειν τῆς προσηκούσης ἐπιμελείας υἱῷ βασιλέως, ἀλλʼ ἔτι γὰρ ἐξεῖχε καὶ διέπρεπε πᾶν τῷ τε εἴδει καὶ τῷ μεγέθει τοῦ σώματος καὶ τοὺς ἐν πολλῇ τρυφῇ διαιτωμένους ὑπερέβαλλε. τοσοῦτον μέντοι γε ἦν τὸ βάθος τῆς κόμης, ὡς μόλις αὐτὴν ἡμέραις ἀποκείρειν ὀκτὼ σταθμὸν ἕλκουσαν σίκλους διακοσίους· οὗτοι δʼ εἰσὶ πέντε μναῖ."},{"number":190,"text":"διέτριψε μέντοι γε ἐν Ἱεροσολύμοις ἔτη δύο τριῶν μὲν ἀρρένων πατὴρ γενόμενος μιᾶς δὲ θυγατρὸς τὴν μορφὴν ἀρίστης, ἣν ὁ Σολόμωνος υἱὸς Ῥοβόαμος ὕστερον λαμβάνει, καὶ γίνεται παιδίον ἐξ αὐτῆς Ἀβίας ὄνομα."},{"number":191,"text":"πέμψας δʼ αὐτὸς Ἀψάλωμος πρὸς Ἰώαβον ἐδεῖτʼ αὐτοῦ τελέως καταπραῧναι τὸν πατέρα καὶ δεηθῆναι, ὅπως αὐτῷ συγχωρήσῃ πρὸς αὐτὸν ἐλθόντι θεάσασθαί τε καὶ προσειπεῖν. καταμελήσαντος δὲ Ἰωάβου τῶν ἰδίων τινὰς ἀποστείλας τὴν ὁμοροῦσαν αὐτῷ χώραν ἐπυρπόλησεν. ὁ δὲ τὸ πραχθὲν μαθὼν ἧκε πρὸς τὸν Ἀψάλωμον ἐγκαλῶν τε αὐτῷ καὶ τὴν αἰτίαν πυνθανόμενος."},{"number":192,"text":"ὁ δέ στρατήγημα τοῦτʼ, εἶπεν, εὗρον ἀγαγεῖν σε πρὸς ἡμᾶς δυνάμενον ἀμελοῦντα τῶν ἐντολῶν, ἃς ἵνα μοι τὸν πατέρα διαλλάξῃς ἐποιούμην. καὶ δὴ δέομαί σου παρόντος ἡμερῶσαί μοι τὸν γεγεννηκότα· ὡς ἔγωγε δεινοτέραν τῆς φυγῆς κρίνω τὴν κάθοδον ἔτι τοῦ πατρὸς ἐν ὀργῇ μένοντος."},{"number":193,"text":"πεισθεὶς δʼ ὁ Ἰώαβος καὶ τὴν ἀνάγκην αὐτοῦ κατοικτείρας ἐμεσίτευσε πρὸς τὸν βασιλέα καὶ διαλεχθεὶς περὶ τοῦ παιδὸς οὕτως αὐτὸν ἡδέως διατίθησιν, ὡς εὐθέως καλέσαι πρὸς αὑτόν. τοῦ δὲ ῥίψαντος αὑτὸν ἐπὶ τοὔδαφος καὶ συγγνώμην αἰτουμένου τῶν ἡμαρτημένων ἀνίστησί τε καὶ τῶν γεγονότων ἀμνηστίαν ἐπαγγέλλεται."}],"9":[{"number":194,"text":"Ὁ δὲ Ἀψάλωμος τοιούτων αὐτῷ τῶν παρὰ τοῦ πατρὸς ἀποβάντων πολλοὺς μὲν ἵππους ἐν ὀλίγῳ πάνυ χρόνῳ πολλὰ δʼ ἅρματα ἐκέκτητο, καὶ ὁπλοφόροι περὶ αὐτὸν ἦσαν πεντήκοντα·"},{"number":195,"text":"καθʼ ἑκάστην δʼ ἡμέραν ὄρθριος πρὸς τὰ βασίλεια παρεγίνετο καὶ τοῖς ἐπὶ τὰς κρίσεις ἥκουσι καὶ ἐλαττουμένοις πρὸς ἡδονὴν ὁμιλῶν, ὡς παρὰ τὸ μὴ συμβούλους ἀγαθοὺς εἶναι τῷ πατρὶ τάχʼ αὐτῷ καὶ ἀδίκως ἐπταικότων τῶν περὶ τὴν κρίσιν, εὔνοιαν αὑτῷ παρὰ πάντων κατεσκεύαζε λέγων, ὡς αὐτὸς ἂν εἰ ταύτην εἶχε τὴν ἐξουσίαν πολλὴν αὐτοῖς ἐβράβευσεν εὐνομίαν."},{"number":196,"text":"τούτοις δημαγωγῶν τὸ πλῆθος ὡς βεβαίαν ἤδη τὴν παρὰ τῶν ὄχλων εὔνοιαν ἐνόμιζε, μετὰ δὲ τὴν τοῦ πατρὸς αὐτοῦ καταλλαγὴν τεσσάρων ἐτῶν ἤδη διεληλυθότων, ἐδεῖτο προσελθὼν εἰς Γιβρῶνα συγχωρῆσαι πορευθέντι θυσίαν ἀποδοῦναι τῷ θεῷ· φεύγοντα γὰρ αὐτὸν εὔξασθαι. τοῦ δὲ Δαυίδου τὴν ἀξίωσιν ἐφέντος πορεύεται, καὶ πολὺς ἐπισυνέρρευσεν ὄχλος ἐπὶ πολλοὺς αὐτοῦ διαπέμψαντος."},{"number":197,"text":"Παρῆν δὲ καὶ ὁ Δαυίδου σύμβουλος ὁ Γελμωναῖος Ἀχιτόφελος καὶ διακόσιοί τινες ἐξ αὐτῶν Ἱεροσολύμων οὐκ εἰδότες μὲν τὴν ἐπιχείρησιν, ὡς δʼ ἐπὶ θυσίαν μετεσταλμένοι· καὶ βασιλεὺς ὑπὸ πάντων ἀποδείκνυται τοῦτο γενέσθαι στρατηγήσας."},{"number":198,"text":"ὡς δʼ ἀπηγγέλη ταῦτα Δαυίδῃ καὶ παρʼ ἐλπίδας αὐτῷ τὰ παρὰ τοῦ παιδὸς ἠκούσθη, δείσας ἅμα καὶ τῆς ἀσεβείας καὶ τῆς τόλμης αὐτὸν θαυμάσας, ὅτι μηδὲ τῆς ἐπὶ τοῖς ἡμαρτημένοις συγγνώμης ἐμνημόνευσεν, ἀλλʼ ἐκείνων πολὺ χείροσι καὶ παρανομωτέροις ἐπεβάλετο βασιλείᾳ πρῶτον μὲν ὑπὸ θεοῦ οὐ δεδομένῃ, δεύτερον δὲ ἐπʼ ἀφαιρέσει τοῦ γεγεννηκότος, ἔγνω φεύγειν εἰς τὰ πέραν τοῦ Ἰορδάνου."},{"number":199,"text":"καὶ συγκαλέσας τῶν φίλων τοὺς ἐπιτηδειοτάτους καὶ περὶ τῆς τοῦ παιδὸς ἀπονοίας κοινολογησάμενος αὐτοῖς καὶ περὶ πάντων ἐπιτρέψας κριτῇ τῷ θεῷ, καταλιπὼν τὰ βασίλεια φυλάσσειν δέκα παλλακίσιν ἀπῆρεν ἐκ τῶν Ἱεροσολύμων, τοῦ τε ἄλλου πλήθους αὐτῷ συνεξορμήσαντος καὶ τῶν ἑξακοσίων ὁπλιτῶν, οἳ καὶ τῆς πρώτης φυγῆς ἐκοινώνουν, ὅτʼ ἔζη Σαοῦλος."},{"number":200,"text":"τὸν δὲ Ἀβιάθαρον καὶ Σάδωκον τοὺς ἀρχιερεῖς συναπαίρειν διεγνωκότας καὶ Λευίτας ἅπαντας μετὰ τῆς κιβωτοῦ μένειν ἔπεισεν, ὡς τοῦ θεοῦ καὶ μὴ μετακομιζομένης αὐτῆς ῥυσομένου."},{"number":201,"text":"ἐνετείλατο δʼ ἕκαστα τῶν γινομένων λάθρα διαγγέλλειν αὐτῷ· πιστοὺς δʼ ἔσχε πρὸς πάντα διακόνους παῖδας Ἀχίμανον μὲν Σαδώκου Ἰωνάθην δὲ Ἀβιαθάρου. Ἔθις δʼ ὁ Γιτταῖος συνεξώρμησεν αὐτῷ βιασάμενος τὴν Δαυίδου βούλησιν, μένειν γὰρ αὐτὸν ἀνέπειθε, καὶ διὰ τοῦτο μᾶλλον εὔνους αὐτῷ κατεφάνη."},{"number":202,"text":"ἀναβαίνοντος δʼ αὐτοῦ διὰ τοῦ Ἐλαιῶνος ὄρους γυμνοῖς τοῖς ποσὶ καὶ πάντων σὺν αὐτῷ δακρυόντων, ἀγγέλλεται καὶ ὁ Ἀχιτόφελος συνὼν τῷ Ἀψαλώμῳ καὶ τὰ τούτου φρονῶν. ἐπέτεινε δʼ αὐτῷ τὸ λυπηρὸν τοῦτʼ ἀκουσθέν, καὶ τὸν θεὸν ἐπεκαλεῖτο δεόμενος ἀπαλλοτριῶσαι τὴν Ἀψαλώμου διάνοιαν πρὸς τὸν Ἀχιτόφελον. ἐδεδίει γάρ, μὴ τἀναντία συμβουλεύων πείσειεν αὐτὸν ἀνὴρ ὢν φρενήρης καὶ συνιδεῖν τὸ λυσιτελὲς ὀξύτατος."},{"number":203,"text":"γενόμενος δʼ ἐπὶ τῆς κορυφῆς τοῦ ὄρους ἀπεσκόπει τὴν πόλιν καὶ μετὰ πολλῶν δακρύων ὡς ἂν βασιλείας ἐκπεσὼν ηὔχετο τῷ θεῷ· συνήντησε δʼ αὐτῷ φίλος ἀνὴρ καὶ βέβαιος Χουσὶς ὄνομα."},{"number":204,"text":"τοῦτον ὁρῶν τὴν ἐσθῆτα κατερρηγμένον καὶ τὴν κεφαλὴν σποδοῦ πλήρη καὶ θρηνοῦντα τὴν μεταβολὴν παρηγορεῖ καὶ παύσασθαι τῆς λύπης παρακαλεῖ καὶ τέλος ἱκέτευσεν ἀπελθόντα πρὸς Ἀψάλωμον ὡς τὰ ἐκείνου φρονοῦντα τά τε ἀπόρρητα τῆς διανοίας αὐτοῦ κατανοεῖν καὶ ταῖς Ἀχιτοφέλου συμβουλίαις ἀντιπράσσειν· οὐ γὰρ τοσοῦτον ὠφελήσειν αὐτῷ συνερχόμενον, ὅσον παρʼ ἐκείνῳ γενόμενον. καὶ ὁ μὲν πεισθεὶς τῷ Δαυίδῃ, καταλιπὼν αὐτὸν ἧκεν εἰς Ἱεροσόλυμα· ἀφικνεῖται δʼ εἰς αὐτὰ μετʼ οὐ πολὺ καὶ Ἀψάλωμος."},{"number":205,"text":"Ὀλίγον δὲ τῷ Δαυίδῃ προελθόντι Σιβᾶς ὁ τοῦ Μεμφιβόσθου δοῦλος συνήντησεν, ὃν προνοησόμενον ἀπεστάλκει τῶν κτήσεων ἃς δεδώρητο τῷ Ἰωνάθου τοῦ Σαούλου παιδὸς υἱῷ, μετὰ ζεύγους ὄνων καταπεφορτισμένων τοῖς ἐπιτηδείοις, ἐξ ὧν ἐκέλευσε λαμβάνειν ὧν αὐτός τε καὶ οἱ σὺν αὐτῷ δέοιντο."},{"number":206,"text":"πυνθανομένου δέ, ποῦ καταλέλοιπε τὸν Μεμφίβοσθον, ἐν Ἱεροσολύμοις ἔλεγε προσδοκῶντα χειροτονηθήσεσθαι βασιλέα διὰ τὴν ὑπάρχουσαν ταραχὴν εἰς μνήμην ὧν εὐηργέτησεν αὐτοὺς Σαοῦλος. ἀγανακτήσας δʼ ἐπὶ τούτῳ πάνθʼ ὅσα τῷ Μεμφιβόσθῳ παρεχώρησε Σιβᾷ χαρίζεται πολὺ γὰρ δικαιότερον αὐτὸν ἐκείνου ταῦτʼ ἔχειν ἐπέγνωκε· καὶ ὁ μὲν Σιβᾶς περιχαρὴς ἦν."},{"number":207,"text":"Δαυίδῃ δὲ γενομένῳ κατὰ Χώρανον τόπον οὕτως καλούμενον ἐπέρχεται τοῦ Σαούλου συγγενὴς Σαμούις μὲν ὄνομα υἱὸς δὲ Γηρᾶ, καὶ λίθοις τε ἔβαλλεν αὐτὸν καὶ ἐκακηγόρει. περιστάντων δὲ τῶν φίλων καὶ σκεπόντων ἔτι μᾶλλον ὁ Σαμούις βλασφημῶν διετέλει, μιαιφόνον καὶ πολλῶν ἀρχηγὸν κακῶν ἀποκαλῶν."},{"number":208,"text":"ἐκέλευε δὲ καὶ τῆς γῆς ὡς ἐναγῆ καὶ ἐπάρατον ἐξιέναι, καὶ τῷ θεῷ χάριν ὡμολόγει τῆς βασιλείας αὐτὸν ἀφελομένῳ καὶ διὰ παιδὸς ἰδίου τὴν ὑπὲρ ὧν ἥμαρτεν εἰς τὸν αὑτοῦ δεσπότην δίκην αὐτὸν εἰσπραξαμένῳ. πάντων δʼ ἐπʼ αὐτὸν ἠρεθισμένων ὑπʼ ὀργῆς καὶ μάλιστα Ἀβεσσαίου διαχρήσασθαι βουλομένου τὸν Σαμούιν Δαυίδης αὐτὸν τῆς ὀργῆς ἐπέσχε,"},{"number":209,"text":"μὴ τοῖς παροῦσι κακοῖς ἑτέραν προσεξεργασώμεθα, φησί, καινοτέραν ἀφορμήν· οὐ γὰρ δὴ τοῦ προσλυσσῶντός μοι τούτου κυνὸς αἰδώς τις ἢ φροντὶς ὑπέρχεται, τῷ θεῷ δὲ εἴκω, διʼ ὃν οὗτος ἐφʼ ἡμᾶς ἀπενοήθη. θαυμαστὸν δʼ οὐδὲν ὑπὸ τούτου με ταῦτα πάσχειν, ὅπου γε καὶ παιδὸς ἀσεβοῦς πεπείραμαι. ἀλλʼ ἔσται τις οἶκτος ἡμῖν ἐκ θεοῦ καὶ κρατήσομεν τῶν ἐχθρῶν τούτου θελήσαντος."},{"number":210,"text":"ἤνυεν οὖν τὴν ὁδὸν οὐ φροντίζων τοῦ Σαμούι παρὰ τὸ ἕτερον μέρος τοῦ ὄρους διατρέχοντος καὶ πολλὰ κακηγοροῦντος· παραγενόμενος δʼ ἐπὶ τὸν Ἰόρδανον ἀνελάμβανε τοὺς ἰδίους ἐνταῦθα κεκοπωμένους."},{"number":211,"text":"Ἀψαλώμου δὲ καὶ Ἀχιτοφέλου τοῦ συμβούλου παραγενομένων εἰς Ἱεροσόλυμα σὺν ἅπαντι τῷ λαῷ, καὶ ὁ Δαυίδου φίλος ἧκε πρὸς αὐτοὺς καὶ προσκυνήσας αὐτὸν συνηύχετο τὴν βασιλείαν εἰς αἰῶνα καὶ τὸν πάντα παραμεῖναι χρόνον. φήσαντος δʼ ἐκείνου πρὸς αὐτόν, τί δήποτε φίλος ἐν τοῖς μάλιστα τοῦ πατρὸς αὐτοῦ γεγενημένος καὶ πρὸς ἅπαντα πιστὸς εἶναι δόξας οὐ σὺν αὐτῷ νῦν ἐστιν, ἀλλὰ καταλιπὼν ἐκεῖνον μεταβαίη πρὸς αὐτόν, δεξιῶς ἀποκρίνεται καὶ σωφρόνως·"},{"number":212,"text":"εἶπε γὰρ ἕπεσθαι δεῖν αὐτὸν τῷ θεῷ καὶ τῷ παντὶ πλήθει. τούτων οὖν μετὰ σοῦ, ὦ δέσποτα, γεγενημένων εἰκότως ἕπομαι κἀγώ· τὴν γὰρ βασιλείαν ἔλαβες παρὰ τοῦ θεοῦ. τὴν αὐτὴν μέντοι γε πίστιν καὶ εὔνοιαν ἐνδείξομαι πιστευόμενος εἶναι φίλος, ἣν οἶσθά με τῷ πατρί σου παρεσχημένον. ἀγανακτεῖν δʼ οὐδὲν προσῆκε τοῖς παροῦσιν· οὐ γὰρ εἰς ἄλλην οἰκίαν ἡ βασιλεία μεταβέβηκε, μεμένηκε δʼ ἐπὶ τῆς αὐτῆς υἱοῦ παραλαβόντος."},{"number":213,"text":"ταῦτα λέγων ἔπειθεν· ὕποπτον γὰρ αὐτὸν εἶχε. καὶ καλέσας τὸν Ἀχιτόφελον συνεβουλεύετο αὐτῷ τί δεῖ ποιεῖν· ὁ δὲ παρῄνεσε ταῖς τοῦ πατρὸς αὐτὸν παλλακαῖς συνελθεῖν· ἐκ τούτου γὰρ εἴσεσθαι τὸν λαὸν ἔλεγε πιστεύσαντα, ὡς ἀδιάλλακτά σοι τὰ πρὸς αὐτόν ἐστι, καὶ μετὰ πολλῆς συστρατεύσεσθαι προθυμίας ἐπὶ τὸν πατέρα· μέχρι δεῦρο γὰρ φανερὰν ἔχθραν ἀναλαμβάνειν δεδιέναι προσδοκῶντας ὑμᾶς ὁμονοήσειν."},{"number":214,"text":"πεισθεὶς δὲ τῇ συμβουλίᾳ κελεύει σκηνὴν αὑτῷ πῆξαι τοὺς οἰκέτας ἐπὶ τοῦ βασιλείου τοῦ πλήθους ὁρῶντος, καὶ παρελθὼν συνέρχεται ταῖς τοῦ πατρὸς παλλακαῖς. ταῦτα δʼ ἐγένετο κατὰ τὴν Νάθα προφητείαν, ἣν τῷ Δαυίδῃ σημαίνων τὴν ἐκ τοῦ παιδὸς ἐσομένην ἐπίθεσιν προεφήτευσε."},{"number":215,"text":"Ποιήσας δʼ Ἀψάλωμος τὰ παραινεθέντα αὐτῷ ὑπὸ τοῦ Ἀχιτοφέλου δεύτερον αὐτὸν ἠξίου συμβουλεύειν περὶ τοῦ πολέμου τοῦ πρὸς τὸν πατέρα. μυρίους δʼ αὐτὸν ἐπιλέκτους αἰτήσαντος ἐκείνου καὶ τόν τε πατέρα κτενεῖν αὐτοῦ καὶ τοὺς σὺν αὐτῷ ζωοὺς ἀνάξειν ὑποσχομένου καὶ βεβαίαν τότε τὴν βασιλείαν ἔσεσθαι φήσαντος Δαυίδου μηκέτι ζῶντος,"},{"number":216,"text":"ἀρεσθεὶς τῇ γνώμῃ μετακαλεῖται καὶ τὸν Χουσὶν τὸν Δαυίδου ἀρχίφιλον· οὕτως γὰρ αὐτὸν ἐκεῖνος ἐκάλει· καὶ τὴν Ἀχιτοφέλου γνώμην αὐτῷ δηλώσας, τί καὶ αὐτῷ δοκεῖ περὶ αὐτῆς ἐπυνθάνετο. συνιδὼν δʼ, ὅτι γενομένων ὧν Ἀχιτόφελος συνεβούλευσε κινδυνεύσει Δαυίδης συλληφθεὶς ἀποθανεῖν, γνώμην εἰσφέρειν ἐναντίαν ἐπειρᾶτο·"},{"number":217,"text":"οὐ γὰρ ἀγνοεῖς εἶπεν, ὦ βασιλεῦ, τὴν τοῦ πατρὸς καὶ τὴν τῶν συνόντων αὐτῷ ἀνδρείαν, ὅτι καὶ πολλοὺς πολέμους πεπολέμηκε καὶ πάντοτε κρατῶν τῶν ἐχθρῶν ἀπήλλακται. νῦν δὲ εἰκὸς αὐτὸν ἐπὶ στρατοπέδου μένειν· στρατηγῆσαι γὰρ ἱκανώτατος καὶ προϊδεῖν ἀπάτην ἐπερχομένων πολεμίων·"},{"number":218,"text":"ἀλλὰ κατὰ τὴν ἑσπέραν ἀπολιπὼν τοὺς ἰδίους ἢ εἴς τινα τῶν αὐλώνων ἑαυτὸν ἀποκρύψει ἢ πρὸς πέτρᾳ τινὶ λοχήσει· συμβαλόντων δὲ τῶν ἡμετέρων οἱ μὲν ἐκείνου πρὸς μικρὸν ὑποχωρήσουσιν, αὐτοὶ δὲ θαρσήσαντες ὡς τοῦ βασιλέως αὐτοῖς ἐγγὺς ὄντος ἀντιστήσονται, καὶ μεταξὺ τούτων μαχομένων ὁ πατὴρ ἐπιφανεὶς ἐξαίφνης τοῖς μὲν εὐψυχίαν πρὸς τοὺς κινδύνους παρασκευάσει τοὺς δὲ σοὺς καταπλήξεται."},{"number":219,"text":"παράθου δὴ τοίνυν καὶ τὴν ἐμὴν συμβουλίαν τῷ λογισμῷ καὶ ταῦτʼ ἐπιγνοὺς ἄριστα τὴν μὲν Ἀχιτοφέλου γνώμην παραίτησαι, πέμψας δʼ εἰς πᾶσαν τὴν χώραν τῶν Ἑβραίων παράγγειλον αὐτοῖς τὴν ἐπὶ τὸν πατέρα σου στρατείαν, καὶ παραλαβὼν αὐτὸς τὴν δύναμιν τοῦ πολέμου γίνου στρατηγὸς καὶ μὴ πιστεύσῃς τοῦτον ἑτέρῳ."},{"number":220,"text":"νικήσειν γὰρ προσδόκα ῥᾳδίως αὐτόν, ἂν ἐν φανερῷ καταλάβῃς ὄντα μετʼ ὀλίγων αὐτὸς πολλὰς ἔχων μυριάδας βουλομένων τὴν περὶ σὲ σπουδὴν ἐπιδείξασθαι καὶ προθυμίαν. ἂν δʼ ὁ πατὴρ αὑτὸν εἰς πολιορκίαν περικλείσῃ, μηχανήμασι καὶ ὀρύγμασιν ὑπονόμοις καθαιρήσομεν ἐκείνην τὴν πόλιν."},{"number":221,"text":"ταῦτʼ εἰπὼν εὐδοκίμησε μᾶλλον Ἀχιτοφέλου· τῆς γὰρ ἐκείνου γνώμης ἡ τούτου προεκρίθη παρʼ Ἀψαλώμου. θεὸς μέντοι γε ἦν ὁ τούτου τῇ διανοίᾳ τὴν τοῦ Χουσὶ συμβουλίαν συστήσας ἀμείνω εἶναι δοκεῖν."},{"number":222,"text":"Σπεύσας δὲ πρὸς τοὺς ἀρχιερέας Σάδωκον καὶ Ἀβιάθαρον καὶ τήν τε Ἀχιτοφέλου γνώμην ἐξειπὼν αὐτοῖς καὶ τὴν ἑαυτοῦ καὶ ὅτι δέδοκται τὰ ὑπʼ αὐτοῦ παραινεθέντα πράττειν, ἐκέλευσε μηνύειν πέμψαντας Δαυίδῃ καὶ φανερὰ ποιεῖν τὰ συμβεβουλευμένα καὶ προσπαρακελεύσασθαι ταχέως διαβῆναι τὸν Ἰόρδανον, μὴ μεταγνοὺς ὁ παῖς αὐτοῦ διώκειν ὁρμήσῃ καὶ πρὶν ἐν ἀσφαλείᾳ γένηται φθάσας καταλάβῃ."},{"number":223,"text":"οἱ δὲ ἀρχιερεῖς ἐξεπίτηδες τοὺς υἱοὺς ἔξω τῆς πόλεως κεκρυμμένους εἶχον, ὅπως διακομίσωσι πρὸς τὸν Δαυίδην τὰ πραττόμενα· πέμψαντες οὖν πιστὴν θεραπαινίδα πρὸς αὐτοὺς φέρουσαν τὰ βεβουλευμένα ὑπὸ τοῦ Ἀψαλώμου προσέταξαν μετὰ σπουδῆς ταῦτα Δαυίδῃ σημαίνειν."},{"number":224,"text":"οἱ δʼ οὐδὲν εἰς ἀναβολὰς καὶ μέλλησιν ὑπερέθεντο, λαβόντες δὲ τὰς τῶν πατέρων ἐντολὰς εὐσεβεῖς ἅμα καὶ πιστοὶ γίνονται διάκονοι· καὶ τῆς ὑπηρεσίας τὸ τάχος καὶ τὴν ὀξύτητα κρίναντες ἄριστα εἶναι ἠπείγοντο συμβαλεῖν Δαυίδῃ."},{"number":225,"text":"γενομένους δʼ αὐτοὺς ἀπὸ σταδίων τῆς πόλεως δύο θεῶνταί τινες ἱππεῖς καὶ διαβάλλουσι πρὸς τὸν Ἀψάλωμον· ὁ δʼ εὐθὺς ἔπεμψε τοὺς συλληψομένους. νοήσαντες δὲ τοῦτο οἱ τῶν ἀρχιερέων παῖδες ἐκτραπέντες τῆς ὁδοῦ παραχρῆμα εἰς κώμην τινὰ τῶν Ἱεροσολύμων οὐκ ἄπωθεν αὑτοὺς ἔδωκαν, Βοκχόρης ἦν ὄνομα τῇ πόλει, καὶ γυναικὸς ἐδεήθησάν τινος κρύψαι καὶ παρασχεῖν αὐτοῖς τὴν ἀσφάλειαν."},{"number":226,"text":"ἡ δὲ καθιμήσασα τοὺς νεανίσκους εἰς φρέαρ καὶ πλάκας ἄνωθεν ἐρίων ἐρίων ἐπιβαλοῦσα, ὡς ἧκον οἱ διώκοντες αὐτοὺς καὶ περὶ αὐτῶν ἀνέκριναν εἰ θεάσαιτο, ἰδεῖν οὐκ ἠρνήσατο, πιόντας γὰρ παρʼ αὐτῇ πάλιν ἀπελθεῖν, εἰ μέντοι γε συντόνως διώξουσι καταλήψεσθαι προύλεγεν. ὡς δʼ ἐπὶ πολὺ διώξαντες οὐ κατέλαβον, ἀνέστρεψαν εἰς τοὐπίσω."},{"number":227,"text":"θεασαμένη δʼ αὐτοὺς ἀναζεύξαντας ἡ γυνὴ καὶ μηδένα φόβον τοῖς νεανίσκοις ἀπʼ αὐτῶν ἔτι συλλήψεως εἶναι, ἀνιμήσασα τὴν προκειμένην ὁδὸν ἀνύειν παρεκελεύσατο· καὶ πολλῇ σπουδῇ καὶ τάχει χρησάμενοι περὶ τὴν ὁδοιπορίαν ἧκον πρὸς Δαυίδην καὶ πάντʼ ἀκριβῶς ἐδήλωσαν τὰ παρʼ Ἀψαλώμου βεβουλευμένα. ὁ δὲ διαβῆναι τὸν Ἰόρδανον τοὺς μεθʼ ἑαυτοῦ προσέταξεν ἤδη νυκτὸς οὔσης καὶ μηδὲν ὀκνεῖν διʼ αὐτήν."},{"number":228,"text":"Ἀχιτόφελος δὲ τῆς γνώμης αὐτοῦ παρευδοκιμηθείσης ἐπιβὰς τοῦ κτήνους ἐξώρμησεν εἰς Γελμὼν τὴν πατρίδα· καὶ συγκαλέσας τοὺς οἰκείους ἅπαντας ἃ συνεβούλευσεν Ἀψαλώμῳ ταῦτʼ αὐτοῖς διεξῆλθε, καὶ ὡς οὐ πεισθεὶς φανερός ἐστιν οὐκ εἰς μακρὰν ἀπολούμενος· Δαυίδην δὲ κρατήσειν ἔλεγεν καὶ ἐπανήξειν ἐπὶ τὴν βασιλείαν."},{"number":229,"text":"ἄμεινον οὖν ἔφησεν εἶναι τοῦ ζῆν αὑτὸν ἐξαγαγεῖν ἐλευθέρως καὶ μεγαλοφρόνως ἢ παρασχεῖν αὑτὸν εἰς κόλασιν Δαυίδῃ, καθʼ οὗ πάντα συνέπραττεν Ἀψαλώμῳ. ταῦτα διαλεχθεὶς καὶ παρελθὼν εἰς τὸ μυχαίτατον τῆς οἰκίας ἀνήρτησεν ἑαυτόν. καὶ τὸν μὲν Ἀχιτόφελον τοιούτου θανάτου δικαστὴν αὑτῷ γενόμενον καθελόντες ἐκ τῆς ἀγχόνης ἐκήδευσαν οἱ προσήκοντες."},{"number":230,"text":"ὁ δὲ Δαυίδης διαβὰς τὸν Ἰόρδανον, καθὼς προειρήκαμεν, εἰς Παρεμβολὰς καλλίστην καὶ ὀχυρωτάτην πόλιν παραγίνεται· δέχονται δὲ αὐτὸν ἀσμενέστατα πάντες οἱ πρῶτοι τῆς χώρας κατά τε αἰδῶ τῆς τότε φυγῆς καὶ κατὰ τιμὴν τῆς προτέρας εὐπραγίας. ἦσαν δὲ οὗτοι Βερζελαῖος ὁ Γαλαδίτης καὶ Σειφὰρ ὁ τῆς Ἀμμανίτιδος δυνάστῃς καὶ Μάχειρος ὁ τῆς Γαλαδίτιδος χώρας πρῶτος."},{"number":231,"text":"οὗτοι πᾶσαν αὐτῷ καὶ τοῖς ἐκείνου τῶν ἐπιτηδείων ἐκτένειαν παρέσχον, ὡς μήτε κλίνας ἐπιλιπεῖν ἐστρωμένας μήτε ἄρτους καὶ οἶνον, ἀλλὰ καὶ θυμάτων ἀφθονίαν χορηγῆσαι καὶ τῶν εἰς ἀνάπαυσιν ἤδη κεκοπωμένοις καὶ τροφὴν χρησίμων εὐπορίαν διαρκῆ παρασχεῖν."}],"10":[{"number":232,"text":"Καὶ οἱ μὲν ἐν τούτοις ἦσαν· Ἀψάλωμος δʼ ἀθροίσας μεγάλην στρατιὰν τῶν Ἑβραίων ἐπὶ τὸν πατέρα καὶ διαβὰς τὸν Ἰόρδανον ποταμὸν οὐ πόρρω κατέζευξε τῶν Παρεμβολῶν ἐν τῇ Γαλαδιτῶν χώρᾳ, καταστήσας στρατηγὸν πάσης τῆς δυνάμεως Ἀμασᾶν εἰς τὴν Ἰωάβου τάξιν τοῦ συγγενοῦς αὐτοῦ· πατρὸς μὲν γὰρ ἦν Ἰεθράου μητρὸς δὲ Ἀβιγαίας, αὕτη δὲ καὶ Σουρία ἡ Ἰωάβου μήτηρ ἀδελφαὶ ἦσαν Δαυίδου."},{"number":233,"text":"ὡς δʼ ἐξαριθμήσας τοὺς σὺν αὐτῷ Δαυίδης περὶ τετρακισχιλίους εὗρεν ὄντας, οὐκ ἔγνω μένειν, πότʼ ἐπʼ αὐτὸν Ἀψάλωμος ἔλθῃ, προσθεὶς δὲ τοῖς οὖσι χιλιάρχους καὶ ἑκατοντάρχους καὶ διελὼν εἰς τρία μέρη τὸ μὲν τῷ στρατηγῷ παρέδωκεν Ἰωάβῳ, τὸ δὲ τῷ ἀδελφῷ αὐτοῦ Ἀβεσσαίῳ, τὴν δὲ τρίτην μοῖραν ἐνεχείρισεν Ἐσθαίῳ συνήθει μὲν ὄντι καὶ φίλῳ ἐκ δὲ τῆς Γιττῶν πόλεως ὑπάρχοντι."},{"number":234,"text":"βουλόμενον δὲ συνεκστρατεύειν αὐτὸν οὐκ εἴασαν οἱ φίλοι γνώμῃ κατασχόντες σοφωτάτῃ· νικηθέντες μὲν γὰρ σὺν αὐτῷ πᾶσαν ἀποβαλεῖν ἐλπίδα χρηστὴν ἔφασκον, ἂν δὲ ἡττηθέντες ἑνὶ μέρει τῆς δυνάμεως τῷ λοιπῷ πρὸς αὐτὸν φύγωσιν ἀμείνονα παρασκευάσειν αὐτὸν ἰσχύν· ὑπονοήσειν δὲ καὶ τοὺς πολεμίους εἰκός ἐστιν ἄλλο μετʼ αὐτοῦ στράτευμα εἶναι."},{"number":235,"text":"πεισθεὶς δὲ τῇ συμβουλίᾳ ταύτῃ μένειν μὲν αὐτὸς ἐν ταῖς Παρεμβολαῖς ἔκρινεν, ἐκπέμπων δὲ τοὺς φίλους καὶ τοὺς στρατηγοὺς ἐπὶ τὸν πόλεμον παρεκάλει προθυμίαν ἐναποδείξασθαι καὶ πίστιν καὶ μνήμην, εἴ τινος τῶν μετρίως ἐχόντων παρʼ αὐτοῦ ἔτυχον· φείσασθαι δὲ καὶ τοῦ παιδὸς Ἀψαλώμου κρατήσαντας ἠντιβόλει, μὴ κακὸν αὑτὸν ἐργάσηταί τι τελευτήσαντος αὐτοῦ. καὶ ὁ μὲν νίκην αὐτοῖς ἐπευξάμενος ἐκπέμπει τὴν στρατιάν."},{"number":236,"text":"Ἰωάβου δὲ παρατάξαντος τὴν δύναμιν ἀντικρὺ τῶν πολεμίων ἐν πεδίῳ μεγάλῳ ἐξόπισθεν περιβεβλημένῳ δρυμὸν ἀντεξάγει τὴν στρατιὰν καὶ Ἀψάλωμος. καὶ συμβολῆς γενομένης ἔργα μεγάλα χειρῶν τε καὶ τόλμης παρʼ ἀμφοτέρων ἐπεδείκνυτο, τῶν μὲν ὑπὲρ τοῦ τὴν βασιλείαν ἀπολαβεῖν Δαυίδην παρακινδυνευόντων καὶ πάσῃ προθυμίᾳ χρωμένων, τῶν δʼ ἵνα μὴ ταύτην Ἀψάλωμος ἀφαιρεθῇ καὶ δῷ τῷ πατρὶ δίκας κολασθεὶς ἀνθʼ ὧν ἐτόλμησεν οὐδὲν ὀκνούντων οὔτε ποιεῖν οὔτε πάσχειν,"},{"number":237,"text":"ἔτι δὲ τῶν μὲν πλειόνων ἵνα μὴ κρατηθῶσιν ὑπὸ τῶν σὺν Ἰωάβῳ καὶ τοῖς σὺν αὐτῷ στρατηγοῖς ὄντων ὀλίγων, αἰσχύνην γὰρ αὐτοῖς τοῦτο εἶναι μεγίστην, τῶν δὲ Δαυίδου στρατιωτῶν ἵνα τοσούτων μυριάδων κρατήσωσι φιλοτιμουμένων, ἔρις ἐγένετο καρτερά, καὶ νικῶσιν οἱ Δαυίδου ῥώμῃ τε προύχοντες καὶ τῇ τῶν πολεμικῶν ἐπιστήμῃ."},{"number":238,"text":"φεύγοντας δὲ διὰ δρυμῶν καὶ φαράγγων ἑπόμενοι τοὺς μὲν ἐλάμβανον πολλοὺς δὲ ἀνῄρουν, ὡς φεύγοντας πεσεῖν πλείονας ἢ μαχομένους· ἔπεσον γὰρ ὡς δισμύριοι ἐπʼ ἐκείνης τῆς ἡμέρας. οἱ δὲ τοῦ Δαυίδου πάντες ὥρμησαν ἐπὶ τὸν Ἀψάλωμον· φανερὸς γὰρ αὐτοῖς ὑπό τε τοῦ κάλλους καὶ τοῦ μεγέθους ἐγένετο."},{"number":239,"text":"δείσας δέ, μὴ καταλάβωσιν αὐτὸν οἱ πολέμιοι, ἐπιβὰς τῆς ἡμιόνου τῆς βασιλικῆς ἔφευγε· φερόμενος δὲ μετὰ ῥύμης καὶ ὑπὸ τοῦ σάλου καὶ τῆς κινήσεως κοῦφος ὤν, ἐμπλακείσης αὐτῷ τῆς κόμης τραχεῖ δένδρῳ μεγάλοις ἐπὶ πολὺ κλάδοις ἐκτεταμένῳ παραδόξως ἀνακρεμνᾶται. καὶ τὸ μὲν κτῆνος ὑπʼ ὀξύτητος ὡς ἐπικείμενον τὸν δεσπότην ἔτι φέρον ἐχώρει προσωτέρω, ὁ δʼ ἐκ τῶν κλάδων αἰωρούμενος ἐκρατεῖτο τοῖς πολεμίοις."},{"number":240,"text":"τοῦτό τις ἰδὼν τῶν Δαυίδου στρατιωτῶν ἐδήλωσεν Ἰωάβῳ, καὶ πεντήκοντα σίκλους ἂν αὐτῷ δεδωκέναι τοῦ στρατηγοῦ φήσαντος, εἰ βαλὼν ἀπέκτεινε τὸν Ἀψάλωμον, οὐδʼ εἰ χιλίους, εἶπεν, ἔμελλές μοι παρέξειν, τοῦτʼ ἂν διέθηκά μου τὸν τοῦ δεσπότου παῖδα, καὶ ταῦτʼ ἐκείνου πάντων ἡμῶν ἀκουόντων φείσασθαι τοῦ νεανίσκου δεηθέντος."},{"number":241,"text":"ὁ δὲ κελεύσας αὐτῷ δεῖξαι ποῦ κρεμάμενον ἴδοι τὸν Ἀψάλωμον τοξεύσας κατὰ τῆς καρδίας ἀπέκτεινεν· οἱ δὲ τὰ τοῦ Ἰωάβου κομίζοντες ὅπλα περιστάντες ἐν κύκλῳ τὸ δένδρον κατασπῶσι τὸν νεκρόν·"},{"number":242,"text":"καὶ τὸν μὲν εἰς χάσμα βαθὺ καὶ ἀχανὲς ῥίψαντες ἐπιβάλλουσιν αὐτῷ λίθους, ὥστε ἀναπληρωθῆναι καὶ τὸ σχῆμα τάφου καὶ μέγεθος λαβεῖν, σημήνας δὲ ἀνακλητικὸν ὁ Ἰώαβος ἐπέσχε τοῦ διώκειν τοὺς οἰκείους στρατιώτας τὴν τῶν πολεμίων δύναμιν φειδόμενος τῶν ὁμοφύλων."},{"number":243,"text":"Ἔστησε δʼ Ἀψάλωμος ἐν τῇ κοιλάδι τῇ βασιλικῇ στήλην λίθου μαρμαρίνου δύο σταδίους ἀπέχουσαν Ἱεροσολύμων, ἣν προσηγόρευσεν ἰδίαν χεῖρα λέγων, ὡς καὶ τῶν τέκνων αὐτοῦ διαφθαρέντων ἐν τῇ στήλῃ μενεῖ τὸ ὄνομα· τέκνα γὰρ ἦν αὐτῷ τρία μὲν ἄρρενα, θυγάτηρ δὲ μία Θωμάρα τοὔνομα, ὡς προειρήκαμεν."},{"number":244,"text":"συνοικησάσης δʼ αὐτῆς τῷ Σολόμωνος υἱῷ Ῥοβοάμῳ γίνεται παῖς ὁ διαδεξάμενος τὴν βασιλείαν Ἀβίας. καὶ περὶ μὲν τούτων ἐν ὑστέροις οἰκειότερον τῇ ἱστορίᾳ δηλώσομεν. μετὰ δὲ τὴν Ἀψαλώμου τελευτὴν ὁ μὲν λαὸς εἰς τὰ οἰκεῖα διεσπάρη."},{"number":245,"text":"Ἀχιμᾶς δὲ ὁ Σαδώκου τοῦ ἀρχιερέως υἱὸς Ἰωάβῳ προσελθὼν ἐδεῖτο αὐτοῦ τὴν νίκην ἐπιτρέψαι πορευθέντι Δαυίδῃ μηνῦσαι, καὶ ὅτι τῆς παρὰ τοῦ θεοῦ βοηθείας ἔτυχε καὶ προνοίας εὐαγγελίσασθαι."},{"number":246,"text":"καὶ τὸν μέν, οὐ προσήκειν εἰπὼν αὐτῷ καλῶν ἄγγελον ἀεὶ γεγενημένον νῦν ἀπιέναι δηλώσοντα θάνατον τῷ βασιλεῖ τοῦ παιδὸς αὐτοῦ, μένειν ἠξίου, καλέσας δὲ τὸν Χουσὶν ἐκείνῳ προσέταξε τὸ ἔργον, ἵνʼ ὅπερ αὐτὸς εἶδε τοῦτο μηνύσειε τῷ βασιλεῖ."},{"number":247,"text":"τοῦ δʼ Ἀχιμᾶ πάλιν δεηθέντος αὐτῷ τὴν ἀγγελίαν ἐφεῖναι, περὶ μόνης γὰρ αὐτὴν ποιήσεσθαι τῆς νίκης ἡσυχάσειν δὲ περὶ τῆς Ἀψαλώμου τελευτῆς, ἐπέτρεψεν αὐτῷ τὴν πρὸς τὸν Δαυίδην ἄφιξιν. καὶ τὴν ἐπιτομωτέραν ἐκβαλὼν τῶν ὁδῶν, καὶ γὰρ μόνος αὐτὴν ἐγίνωσκε, τὸν Χουσὶν φθάνει."},{"number":248,"text":"καθεζομένῳ δὲ Δαυίδῃ μεταξὺ τῶν πυλῶν καὶ περιμένοντι, πότʼ αὐτῷ τις ἐλθὼν ἀπὸ τῆς μάχης ἀγγείλῃ τὰ κατʼ αὐτήν, τῶν σκοπῶν τις ἰδὼν τὸν Ἀχιμᾶν τρέχοντα καὶ μήπω τίς ἐστι γνωρίσαι δυνάμενος εἶπε πρὸς τὸν Δαυίδην βλέπειν τινὰ παραγινόμενον πρὸς αὐτόν."},{"number":249,"text":"τοῦ δʼ ἄγγελον εἶναι φήσαντος ἀγαθῶν, μετʼ ὀλίγον ἕπεσθαί τινα καὶ ἕτερον ἐδήλωσεν αὐτῷ. κἀκεῖνον δὲ ἄγγελον εἰπόντος, ἰδὼν τὸν Ἀχιμᾶν ὁ σκοπὸς ἤδη ἐγγὺς γεγενημένον τὸν Σαδώκου παῖδα τοῦ ἀρχιερέως προστρέχειν ἐσήμαινεν. ὁ δὲ Δαυίδης περιχαρὴς γενόμενος ἀγαθῶν ἄγγελον τοῦτον ἔφησεν εἶναι καί τι τῶν εὐκταίων αὐτῷ φέρειν ἀπὸ τῆς μάχης."},{"number":250,"text":"Καὶ μεταξὺ ταῦτα λέγοντος τοῦ βασιλέως φανεὶς ὁ Ἀχιμᾶς προσκυνεῖ τὸν βασιλέα, καὶ πυθομένῳ περὶ τῆς μάχης νίκην εὐαγγελίζεται καὶ κράτος. ἐρομένῳ δʼ εἴ τι καὶ περὶ τοῦ παιδὸς ἔχοι λέγειν αὐτὸς μὲν ἔφασκεν εὐθὺς ὁρμῆσαι πρὸς αὐτὸν τῆς τροπῆς τῶν πολεμίων γενομένης, ἀκοῦσαι δὲ μεγάλης φωνῆς διωκόντων τὸν Ἀψάλωμον καὶ πλεῖον τούτου μηδὲν δεδυνῆσθαι μαθεῖν διὰ τὸ πεμφθέντα ὑπὸ Ἰωάβου δηλῶσαι τὴν νίκην ἐπείγεσθαι."},{"number":251,"text":"παραγενομένου δὲ τοῦ Χουσὶ καὶ προσκυνήσαντος καὶ τὴν νίκην σημήναντος, περὶ τοῦ παιδὸς αὐτὸν ἀνέκρινεν. ὁ δʼ ἐχθροῖς, εἶπε, τοῖς σοῖς οἷα συμβέβηκεν Ἀψαλώμῳ γένοιτο."},{"number":252,"text":"οὗτος ὁ λόγος οὐδὲ τὴν ἐπὶ τῇ νίκῃ χαρὰν εἴασεν οὔτʼ αὐτῷ μεῖναι μεγίστην οὖσαν οὔτε τοῖς στρατιώταις· αὐτὸς μὲν γὰρ ἀναβὰς ἐπὶ τὸ ὑψηλότατον τῆς πόλεως ἀπεκλαίετο τὸν υἱὸν τυπτόμενος τὰ στέρνα καὶ τὴν κεφαλὴν σπαραττόμενος καὶ παντοίως αὑτὸν αἰκιζόμενος καὶ τέκνον, ἐκβοῶν, εἴθε μοι τὸν θάνατον ἐπελθεῖν ἐγένετο καὶ ἅμα σοι τελευτῆσαι · φύσει γὰρ ὢν φιλόστοργος πρὸς ἐκεῖνον μᾶλλον συμπαθῶς εἶχεν."},{"number":253,"text":"ἡ στρατιὰ δὲ καὶ Ἰώαβος ἀκούσαντες, ὅτι πενθεῖ τὸν υἱὸν οὕτως ὁ βασιλεύς, ᾐσχύνθησαν μετὰ τοῦ τῶν νενικηκότων σχήματος εἰσελθεῖν εἰς τὴν πόλιν, κατηφεῖς δὲ καὶ δεδακρυμένοι πάντες ὡς ἀφʼ ἥττης παρῆλθον."},{"number":254,"text":"κατακαλυψαμένου δὲ τοῦ βασιλέως καὶ στένοντος τὸν υἱὸν εἴσεισι πρὸς αὐτὸν Ἰώαβος καὶ παρηγορῶν ὦ δέσποτα, φησί, λανθάνεις διαβάλλων σαυτὸν οἷς ποιεῖς, ὅτι τοὺς μὲν ἀγαπῶντάς σε καὶ περὶ σοῦ κινδυνεύοντας καὶ σαυτὸν καὶ τὴν σὴν γενεὰν δοκεῖς μισεῖν, στέργειν δὲ τοὺς ἐχθροτάτους καὶ ποθεῖν οὐκέτʼ ὄντας, οἳ δίκῃ τεθνήκασιν·"},{"number":255,"text":"εἰ γὰρ Ἀψάλωμος ἐκράτησε καὶ τὴν βασιλείαν βεβαίως κατέσχεν, οὐδενὸς ἂν ἡμῶν ὑπελείφθη λείψανον, ἀλλὰ πάντες ἂν ἀπὸ σοῦ καὶ τῶν σῶν ἀρξάμενοι τέκνων ἀπωλώλειμεν οἰκτρῶς, οὐ κλαιόντων ἡμᾶς τῶν πολεμίων ἀλλὰ καὶ χαιρόντων καὶ τοὺς ἐλεοῦντας ἐπὶ τοῖς κακοῖς κολαζόντων. σὺ δʼ οὐκ αἰσχύνῃ ταῦτα ποιῶν ἐπὶ μᾶλλον ἐχθρῷ, ὅτι σὸς υἱὸς ὢν ἀσεβὴς οὕτως ἐγένετο."},{"number":256,"text":"παυσάμενος οὖν τῆς ἀδίκου λύπης προελθὼν ὄφθητι τοῖς σαυτοῦ στρατιώταις καὶ τῆς νίκης αὐτοῖς καὶ τῆς περὶ τοὺς ἀγῶνας προθυμίας εὐχαρίστησον. ὡς ἐγὼ τήμερον, ἂν ἐπιμένῃς τοῖς ἄρτι πραττομένοις, ἀναπείσας ἀποστῆναί σου τὸν λαὸν καὶ τὴν βασιλείαν ἑτέρῳ παραδοῦναι, τότε σοι πικρότερον καὶ ἀληθὲς ποιήσω τὸ πένθος."},{"number":257,"text":"ταῦτʼ εἰπὼν Ἰώαβος ἀπέστρεψεν ἀπὸ τῆς λύπης καὶ ἤγαγεν εἰς τὸν περὶ τῶν πραγμάτων λογισμὸν τὸν βασιλέα· μετασχηματίσας γὰρ ἑαυτὸν Δαυίδης καὶ ποιήσας ἐπιτήδειον εἰς τὴν τοῦ πλήθους θέαν πρὸς ταῖς πύλαις ἐκάθισεν, ὡς ἅπαντα τὸν λαὸν ἀκούσαντα συνδραμεῖν πρὸς αὐτὸν καὶ κατασπάσασθαι. καὶ ταῦτα μὲν τοῦτον ἔσχε τὸν τρόπον."}],"11":[{"number":258,"text":"Οἱ δʼ ἐκ τῆς μάχης ἀναχωρήσαντες τῶν Ἑβραίων τῶν μετʼ Ἀψαλώμου γενόμενοι παρʼ αὑτοῖς ἕκαστοι διεπέμποντο κατὰ πόλεις ὑπομιμνήσκοντες αὑτοὺς ὧν εὐηργέτησε Δαυίδης καὶ τῆς ἐλευθερίας, ἣν ἐκ πολλῶν καὶ μεγάλων ῥυσάμενος αὐτοὺς πολέμων παρέσχε,"},{"number":259,"text":"μεμφόμενοι δʼ ὅτι τῆς βασιλείας αὐτὸν ἐκβαλόντες ἄλλῳ ταύτην ἐνεχείρισαν καὶ νῦν τεθνηκότος τοῦ κατασταθέντος ὑπʼ αὐτῶν ἡγεμόνος οὐ παρακαλοῦσι Δαυίδην παύσασθαι μὲν τῆς ὀργῆς, εὐνοϊκῶς δὲ πρὸς αὐτοὺς ἔχειν, τῶν δὲ πραγμάτων καθὼς ἤδη καὶ πρότερον ποιεῖσθαι πρόνοιαν τὴν βασιλείαν ἀπολαβόντα."},{"number":260,"text":"ταῦτα μὲν οὖν συνεχέστερον ἀπηγγέλλετο Δαυίδῃ· κἀκεῖνος οὐδὲν ἧττον ἔπεμψε πρὸς Σάδωκον καὶ Ἀβιάθαρον τοὺς ἀρχιερέας, ἵνα τοῖς ἄρχουσι τῆς Ἰούδα φυλῆς διαλεχθῶσιν, ὡς αἰσχρὸν αὐτοῖς ἄλλας φυλὰς πρὸ ἐκείνης Δαυίδην χειροτονῆσαι βασιλέα, καὶ ταῦθʼ ὑμῶν συγγενῶν ὄντων καὶ κοινὸν αἷμα πρὸς αὐτὸν κεκληρωμένων."},{"number":261,"text":"τὰ δʼ αὐτὰ καὶ Ἀμασᾷ τῷ στρατηγῷ προσέταξεν αὐτοὺς λέγειν, ὅτι τῆς ἀδελφῆς υἱὸς ὢν αὐτοῦ μὴ πείθει τὸ πλῆθος Δαυίδῃ τὴν βασιλείαν ἀποδοῦναι· προσδοκᾶν δὲ παρʼ αὐτοῦ μὴ διαλλαγὴν μόνον, τοῦτο γὰρ ἤδη γέγονεν, ἀλλὰ καὶ τὴν παντὸς τοῦ λαοῦ στρατηγίαν, ἣν αὐτῷ καὶ Ἀψάλωμος παρέσχε."},{"number":262,"text":"καὶ οἱ μὲν ἀρχιερεῖς ἃ μὲν τοῖς τῆς φυλῆς ἄρχουσι διειλέχθησαν ἃ δὲ τὸν Ἀμασὰν ἔπεισαν τὰ παρὰ τοῦ βασιλέως πρὸς αὐτὸν εἰπόντες ἐγχειρεῖν ταῖς ὑπὲρ αὐτοῦ φροντίσι. καὶ πείθει γε τὴν φυλὴν παραχρῆμα πέμψαι πρὸς Δαυίδην πρέσβεις παρακαλοῦντας εἰς τὴν ἰδίαν αὐτὸν ἐπανελθεῖν βασιλείαν. τὸ δʼ αὐτὸ καὶ πάντες ἐποίουν οἱ Ἰσραηλῖται προτρεψαμένου τοῦ Ἀμασᾶ."},{"number":263,"text":"Τῶν δὲ πρέσβεων ἀφικομένων πρὸς αὐτὸν εἰς Ἱεροσόλυμα παρεγένετο. πάντας δὲ τοὺς ἄλλους ἔφθασεν ἡ Ἰούδα φυλὴ πρὸς τὸν Ἰόρδανον ποταμὸν ἀπαντῆσαι τῷ βασιλεῖ καὶ ὁ Γήρα παῖς Σαμούις μετὰ χιλίων ἀνδρῶν, οὓς ἐκ τῆς Βενιαμίδος φυλῆς ἐπήγετο, καὶ Σιβᾶς δὲ ὁ ἀπελεύθερος Σαούλου καὶ οἱ παῖδες αὐτοῦ πεντεκαίδεκα τὸν ἀριθμὸν ὄντες μετὰ οἰκετῶν εἴκοσιν."},{"number":264,"text":"οὗτοι σὺν τῇ Ἰούδα φυλῇ τὸν ποταμὸν ἐγεφύρωσαν, ἵνα ῥᾷστα διαβῇ μετὰ τῶν ἰδίων ὁ βασιλεύς. ὡς δὲ ἧκεν ἐπὶ τὸν Ἰόρδανον ἠσπάσατο μὲν αὐτὸν ἡ Ἰούδα φυλή, προσπεσὼν δʼ ἀναβάντι ἐπὶ τὴν γέφυραν Σαμούις καὶ κατασχὼν αὐτοῦ τοὺς πόδας ἐδεῖτο συγγνῶναι περὶ τῶν εἰς αὐτὸν ἡμαρτημένων καὶ μὴ γενέσθαι πικρὸν αὐτῷ μηδὲ τοῦτο πρῶτον ἡγήσασθαι τὴν τιμωρίαν ἐν ἐξουσίᾳ γενόμενον, λογίσασθαι δʼ ὅτι καὶ μετανοήσας ἐφʼ οἷς ἐσφάλη πρῶτος ἐλθεῖν πρὸς αὐτὸν ἔσπευσε."},{"number":265,"text":"ταῦτα δʼ ἀντιβολοῦντος αὐτοῦ καὶ οἰκτιζομένου Ἀβεσσαῖος ὁ Ἰωάβου ἀδελφός, διὰ τοῦτο οὖν, εἶπεν, οὐ τεθνήξῃ βλασφημήσας τὸν ὑπὸ τοῦ θεοῦ κατασταθέντα βασιλεύειν; Δαυίδης δʼ ἐπιστραφεὶς πρὸς αὐτόν, οὐ παύσεσθʼ, εἶπεν, ὦ Σαρουίας παῖδες; μὴ κινήσητε πάλιν ἡμῖν καινὰς ἐπὶ ταῖς πρώταις ταραχὰς καὶ στάσεις·"},{"number":266,"text":"οὐ γὰρ ἀγνοεῖν ὑμᾶς προσῆκεν, ὅτι σήμερον ἄρχομαι τῆς βασιλείας. διὸ πᾶσιν ἀφιέναι τὰς κολάσεις τοῖς ἀσεβήσασιν ὄμνυμι καὶ μηδενὶ τῶν ἁμαρτόντων ἐπεξελθεῖν. σύ τε, εἶπεν, ὦ Σαμούι, θάρρει καὶ δείσῃς μηδὲν ὡς τεθνηξόμενος. ὁ δὲ προσκυνήσας αὐτὸν προῆγεν."},{"number":267,"text":"Ἀπήντησε δʼ αὐτῷ καὶ ὁ Σαούλου υἱωνὸς Μεμφίβοσθος ῥυπαράν τε τὴν ἐσθῆτα περικείμενος καὶ τὴν κόμην βαθεῖαν καὶ κατημελημένην ἔχων· μετὰ γὰρ τὴν Δαυίδου φυγὴν οὔτε ἀπεκείρατο λυπούμενος οὔτʼ ἐκάθηρε τὴν ἐσθῆτα κατακρίνας αὑτοῦ συμφορὰν ταύτην ἐπὶ τῇ τοῦ βασιλέως μεταβολῇ· διεβέβλητο δὲ καὶ ὑπὸ τοῦ ἐπιτρόπου Σιβᾶ πρὸς αὐτὸν ἀδίκως."},{"number":268,"text":"ἀσπασαμένου δὲ αὐτοῦ καὶ προσκυνήσαντος ἤρξατο πυνθάνεσθαι, τί δήποτʼ οὐ συνεξῆλθεν αὐτῷ καὶ κοινωνὸς ἦν τῆς φυγῆς; ὁ δʼ ἀδίκημα τοῦτʼ ἔλεγεν εἶναι Σιβᾶ· κελευσθεὶς γὰρ παρασκευάσαι τὰ πρὸς τὴν ἔξοδον οὐκ ἐφρόντισεν, ἀλλʼ ὥσπερ ἀνδραπόδου τινὸς οὕτως παρήκουσεν."},{"number":269,"text":"εἰ μέντοι γε τὰς βάσεις εἶχον ἐρρωμένας, οὐκ ἂν ἀπελείφθην σου χρῆσθαι πρὸς τὴν φυγὴν ταύταις δυνάμενος. οὐ τοῦτο δὲ μόνον ἠδίκησέ μου τὴν πρὸς σέ, δέσποτα, εὐσέβειαν, ἀλλὰ καὶ προσδιέβαλε καὶ κατεψεύσατο κακουργῶν. ἀλλʼ οἶδα γάρ, ὅτι τούτων οὐδὲν ἡ σὴ διάνοια προσίεται δικαία τε οὖσα καὶ τὴν ἀλήθειαν ἐνισχύειν βουλομένη καὶ τὸ θεῖον ἀγαπῶσα·"},{"number":270,"text":"μείζονα γὰρ κινδυνεύσας παθεῖν ὑπὸ τοῦ πάππου τοὐμοῦ καὶ τῆς ὅλης ἡμῶν γενεᾶς ὀφειλούσης εἰς ἐκεῖνα ἀπολωλέναι, σύ τε μέτριος καὶ χρηστὸς ἐγένου τότε μάλιστα πάντων ἐκείνων λήθην ποιησάμενος, ὅτʼ ἐξουσίαν τῆς ὑπὲρ αὐτῶν τιμωρίας εἶχεν ἡ μνήμη. φίλον δὲ σὸν ἔκρινας ἐμὲ καὶ ἐπὶ τῆς τραπέζης εἶχες ὁσημέραι, καὶ οὐδὲν ἀπέλειπον τῶν συγγενῶν τοῦ μάλιστα τιμωμένου."},{"number":271,"text":"ταῦτʼ εἰπόντος οὔτε τὸν Μεμφίβοσθον ἔγνω κολάζειν οὔθʼ ὡς καταψευσαμένου τοῦ Σιβᾶ πρὸς αὐτὸν καταδικάζειν, ἀλλʼ ὑπὲρ μὲν τοῦ μὴ μετὰ Σιβᾶ ἐλθεῖν ἐκείνῳ πάντα χαρίσασθαι φήσας αὐτῷ συγγινώσκειν ὑπέσχετο τὰ ἡμίση τῆς οὐσίας αὐτῷ κελεύσας ἀποδοθῆναι. ὁ δὲ Μεμφίβοσθος πάντʼ ἐχέτω μέν, εἶπε, Σιβάς, ἐμοὶ δʼ ἀπόχρη τὸ σὲ τὴν βασιλείαν ἀπολαβεῖν."},{"number":272,"text":"Βεέρζελον δὲ τὸν Γαλαδίτην ἄνδρα μέγαν καὶ καλὸν καὶ πολλὰ παρεσχημένον ἐν ταῖς Παρεμβολαῖς αὐτῷ Δαυίδης προπέμψαντα μέχρι τοῦ Ἰορδάνου παρεκάλει συνελθεῖν ἕως τῶν Ἱεροσολύμων· γηρωκομήσειν γὰρ αὐτὸν ἐν πάσῃ τιμῇ καὶ ὡς πατρὸς ἐπιμεληθήσεσθαι καὶ προνοήσειν ἐπηγγέλλετο."},{"number":273,"text":"ὁ δὲ πόθῳ τῶν οἴκοι παρῃτεῖτο τὴν μετʼ αὐτοῦ διατριβήν· καὶ τὸ γῆρας λέγων τοιοῦτον αὐτῷ τυγχάνειν, ὥστε μὴ ἀπολαύειν τῶν ἡδέων εἰς ὀγδοήκοντα ἔτη προβεβηκότος, ἀλλʼ ὥστε καταλύσεως ἤδη καὶ ταφῆς προνοεῖν, ἐπὶ ταύτην ἠξίου βουλόμενον αὐτῷ χαρίζεσθαι τὰ κατʼ ἐπιθυμίαν αὐτὸν ἀπολῦσαι·"},{"number":274,"text":"οὔτε γὰρ τροφῆς οὔτε ποτοῦ συνιέναι διὰ τὸν χρόνον, ἀποκεκλεῖσθαι δʼ αὐτῷ καὶ τὰς ἀκοὰς ἤδη πρὸς αὐλῶν ἤχους καὶ μέλη τῶν ἄλλων ὀργάνων, ὅσα παρὰ βασιλεῦσι τέρπει τοὺς συνδιαιτωμένους. οὕτως δὲ λιπαρῶς δεομένου, σὲ μέν, εἶπεν, ἀπολύω,"},{"number":275,"text":"τὸν δʼ υἱὸν Ἀχίμανον ἄφες μοι· πάντων γὰρ αὐτῷ μεταδώσω τῶν ἀγαθῶν. καὶ Βεέρζελος μὲν καταλιπὼν τὸν υἱὸν καὶ προσκυνήσας τὸν βασιλέα καὶ πάντων ἐπευξάμενος αὐτῷ τέλος ὧν ἔχει κατὰ ψυχὴν οἴκαδʼ ὑπέστρεψε. παραγίνεται δʼ εἰς Γάλγαλα Δαυίδης τοῦ λαοῦ παντὸς ἤδη τὸ ἥμισυ περὶ αὑτὸν ἔχων καὶ τὴν Ἰούδα φυλήν."},{"number":276,"text":"Ἀφικνοῦνται δʼ εἰς Γάλγαλα πρὸς αὐτὸν οἱ πάσης φυλῆς πρῶτοι μετὰ πολλοῦ πλήθους καὶ τὴν Ἰούδα φυλὴν κατεμέμφοντο λάθρα πρὸς αὐτὸν ἐλθοῦσαν, ὡς δεῖν ὁμοῦ πάντας μιᾷ γνώμῃ ποιεῖσθαι τὴν ἀπάντησιν. οἱ δʼ ἄρχοντες τῆς Ἰούδα φυλῆς μὴ δυσχεραίνειν αὐτοὺς ἠξίουν προληφθέντας· καὶ γὰρ συγγενεῖς ὄντες αὐτοῦ καὶ διὰ τοῦτο μᾶλλον προνοούμενοι καὶ στέργοντες φθάσαι, οὐ μέντοι γε διὰ τὸ προελθεῖν δῶρα λαβεῖν αὐτούς, ἵνʼ ἔχωσιν ἐπὶ τούτῳ δυσφορεῖν ὕστεροι πρὸς αὐτὸν ἐλθόντες."},{"number":277,"text":"ταῦτα τῶν τῆς Ἰούδα φυλῆς ἡγεμόνων εἰπόντων οἱ τῶν ἄλλων ἄρχοντες οὐχ ἡσύχασαν, ἀλλʼ ἡμεῖς μέν, ἔφασαν, ὦ ἀδελφοί, θαυμάζομεν ὑμᾶς αὑτῶν ἀποκαλοῦντας μόνων συγγενῆ τὸν βασιλέα· ὁ γὰρ τὴν ἁπάντων ἐξουσίαν παρὰ τοῦ θεοῦ λαβὼν πάντων ἡμῶν εἶναι συγγενὴς κρίνεται. καὶ διὰ τοῦθʼ ὁ μὲν λαὸς ἕνδεκα μοίρας ἔχει, μίαν δʼ ὑμεῖς, καὶ πρεσβύτεροι ἐσμέν, καὶ οὐκ ἐποιήσατε δίκαια λεληθότως ἐλθόντες πρὸς τὸν βασιλέα."},{"number":278,"text":"Τοιαῦτα τῶν ἡγεμόνων πρὸς ἀλλήλους διαλεχθέντων ἀνήρ τις πονηρὸς καὶ στάσει χαίρων, ὄνομα Σαβαῖος υἱὸς δὲ Βοχορίου τῆς Βενιαμίτιδος φυλῆς, στὰς ἐν μέσῳ πρὸς τὸ πλῆθος μέγα βοήσας εἶπεν· οὔτʼ ἔχει τις ἡμῶν παρὰ Δαυίδου μοίρας οὔτε κλῆρον παρὰ τῷ Ἰεσσαίου παιδί."},{"number":279,"text":"καὶ μετὰ τοὺς λόγους σαλπίσας κέρατι σημαίνει πόλεμον πρὸς τὸν βασιλέα, καὶ πάντες ἠκολούθησαν ἐκείνῳ Δαυίδην καταλιπόντες· μόνη δʼ αὐτῷ παρέμεινεν ἡ Ἰούδα φυλὴ καὶ κατέστησεν αὐτὸν εἰς τὸ ἐν Ἱεροσολύμοις βασίλειον. καὶ τὰς μὲν παλλακάς, αἷς ὁ υἱὸς αὐτοῦ συνῆλθεν Ἀψάλωμος, εἰς ἄλλην μετήγαγεν οἰκίαν πάντα προστάξας αὐταῖς χορηγεῖν τὰ ἐπιτήδεια τοὺς ἐπιμελομένους, αὐτὸς δʼ οὐκέτʼ ἐπλησίαζεν αὐταῖς."},{"number":280,"text":"ἀποδείκνυσι δὲ καὶ τὸν Ἀμασὰν στρατηγὸν καὶ τὴν τάξιν αὐτῷ ἐφʼ ἧς Ἰώαβος ἦν δίδωσιν ἐκέλευσέ τε στρατιὰν ὅσην δύναται συναγαγόντʼ ἐκ τῆς Ἰούδα φυλῆς μεθʼ ἡμέρας τρεῖς ὡς αὐτὸν ἐλθεῖν, ἵνα παραδοὺς αὐτῷ πᾶσαν τὴν δύναμιν ἐκπέμψῃ πολεμήσοντα τὸν υἱὸν τοῦ Βοχορίου."},{"number":281,"text":"ἐξελθόντος δὲ τοῦ Ἀμασᾶ καὶ περὶ τὴν ἄθροισιν τῆς στρατιᾶς βραδύνοντος, ὡς οὐκ ἐπανῄει τῇ τρίτῃ τῶν ἡμερῶν ὁ βασιλεὺς πρὸς τὸν Ἰώαβον ἔλεγεν οὐκ εἶναι σύμφορον ἀνοχὴν τῷ Σαβαίῳ διδόναι, μὴ γενόμενος ἐν πλείονι παρασκευῇ μειζόνων κακῶν καὶ πραγμάτων αἴτιος, ἢ Ἀψάλωμος αὐτοῖς κατέστη, γένηται."},{"number":282,"text":"μὴ περίμενε τοίνυν μηδένα, ἀλλὰ τὴν οὖσαν παραλαβὼν δύναμιν καὶ τοὺς ἑξακοσίους μετὰ Ἀβεσσαίου τοῦ Ἀδελφοῦ σου δίωκε τὸν πολέμιον. καὶ ὅπου ποτʼ ἂν αὐτὸν καταλάβῃς ὄντα πειράθητι συμβαλεῖν· σπούδασον δʼ αὐτὸν φθάσαι, μὴ πόλεις ὀχυρὰς καταλαβόμενος ἀγῶνας ἡμῖν καὶ πολλοὺς ἱδρῶτας παρασκευάσῃ."},{"number":283,"text":"Ἰώαβος δʼ οὐκέτι μέλλειν ἔκρινεν, ἀλλὰ τόν τε ἀδελφὸν καὶ τοὺς ἑξακοσίους παραλαβὼν καὶ ὅση λοιπὴ δύναμις ἦν ἐν τοῖς Ἱεροσολύμοις ἕπεσθαι κελεύσας ἐξώρμησεν ἐπὶ τὸν Σαβαῖον. ἤδη δʼ ἐν Γαβαών, κώμη δʼ ἐστὶν αὕτη σταδίους ἀπέχουσα τεσσαράκοντα τῶν Ἱεροσολύμων, γεγενημένος πολλὴν Ἀμασᾶ δύναμιν ἀγαγόντος ἀπήντησεν αὐτῷ διεζωσμένος μάχαιραν καὶ θώρακα ἐνδεδυμένος ὁ Ἰώαβος·"},{"number":284,"text":"προσιόντος δὲ ἀσπάσασθαι τοῦ Ἀμασᾶ φιλοτεχνεῖ τὴν μάχαιραν αὐτομάτως ἐκ τῆς θήκης ἐκπεσεῖν, βαστάσας δʼ αὐτὴν ἀπὸ τῆς γῆς καὶ τῇ ἑτέρᾳ τὸν Ἀμασᾶν ἐγγὺς γενόμενον ὡς καταφιλήσων τοῦ γενείου λαβόμενος οὐ προϊδόμενον εἰς τὴν γαστέρα πλήξας ἀπέκτεινεν, ἀσεβὲς ἔργον διαπραξάμενος καὶ παντελῶς ἀνόσιον, ἀγαθὸν νεανίαν καὶ συγγενῆ καὶ μηδὲν ἀδικήσαντα ζηλοτυπήσας τῆς στρατηγίας καὶ τῆς παρὰ τῷ βασιλεῖ πρὸς αὐτὸν ἰσοτιμίας."},{"number":285,"text":"διὰ ταύτην γὰρ τὴν αἰτίαν καὶ τὸν Ἀβενῆρον ἐφόνευσεν. ἀλλʼ ἐκεῖνο μὲν αὐτοῦ τὸ παρανόμημα πρόφασις εὐπρεπὴς συγγνωστὸν ἐδόκει ποιεῖν, ὁ ἀδελφὸς Ἀσάηλος ἐκδεδικῆσθαι νομιζόμενος, τοῦ δʼ Ἀμασᾶ φόνου οὐδὲν τοιοῦτον ἔσχε παρακάλυμμα."},{"number":286,"text":"ἀποκτείνας δὲ τὸν συστράτηγον ἐδίωκε τὸν Σαβαῖον καταλιπὼν ἕνα πρὸς τῷ νεκρῷ βοᾶν ἐντειλάμενος πρὸς τὴν στρατιάν, ὅτι τέθνηκεν Ἀμασᾶς δικαίως καὶ μετʼ αἰτίας κολαζούσης· εἰ δὲ φρονεῖτε τὰ τοῦ βασιλέως, ἕπεσθε τῷ στρατηγῷ αὐτοῦ Ἰωάβῳ καὶ Ἀβεσσαίῳ τῷ τούτου ἀδελφῷ."},{"number":287,"text":"κειμένου δὲ τοῦ σώματος ἐπὶ τῆς ὁδοῦ καὶ παντὸς τοῦ πλήθους ἐπʼ αὐτῷ συρρέοντος καὶ οἷον ὄχλος φιλεῖ ἐθαύμαζον ἠλέουν προϊστάμενοι· βαστάσας δʼ ἐκεῖθεν ὁ φύλαξ καὶ κομίσας εἴς τι χωρίον ἀπωτάτω τῆς ὁδοῦ τίθησιν αὐτόθι καὶ καλύπτει ἱματίῳ. τούτου γενομένου πᾶς ὁ λαὸς ἠκολούθησε τῷ Ἰωάβῳ."},{"number":288,"text":"διώξαντι δʼ αὐτῷ διὰ πάσης τῆς Ἰσραηλιτῶν χώρας τὸν Σαβαῖον δηλοῖ τις ἐν ὀχυρᾷ πόλει τυγχάνειν Ἀβελωχέᾳ λεγομένῃ. παραγενόμενος δʼ ἐκεῖ καὶ τῇ στρατιᾷ περικαθίσας τὴν πόλιν καὶ χαράκωμα περὶ αὐτὴν πηξάμενος ὑπορύσσειν ἐκέλευσε τοῖς στρατιώταις τὰ τείχη καὶ καταβάλλειν αὐτά· μὴ δεξαμένων γὰρ αὐτὸν τῶν ἐν τῇ πόλει χαλεπῶς πρὸς αὐτοὺς διετέθη."},{"number":289,"text":"Γύναιον δέ τι σῶφρον καὶ συνετὸν ἐν ἐσχάτοις ἤδη τὴν πατρίδα κειμένην θεασάμενον ἀναβὰν ἐπὶ τὸ τεῖχος προσκαλεῖται διὰ τῶν ὁπλιτῶν τὸν Ἰώαβον. προσελθόντος δʼ ἤρξατο λέγειν, ὡς ὁ θεὸς τοὺς βασιλεῖς καὶ τοὺς στρατηγοὺς ἀποδείξειεν, ἵνα τοὺς πολεμίους τοὺς Ἑβραίων ἐξαιρῶσι καὶ παρέχωσιν αὐτοῖς εἰρήνην ἀπʼ αὐτῶν· σὺ δὲ σπουδάζεις μητρόπολιν Ἰσραηλιτῶν καταβαλεῖν καὶ πορθῆσαι μηδὲν ἐξαμαρτοῦσαν."},{"number":290,"text":"ὁ δὲ ἵλεων μὲν εὔχεται τὸν θεὸν αὐτῷ διαμένειν, αὐτὸς δʼ οὕτως ἔχειν εἶπεν, ὡς μηδένα τοῦ λαοῦ φονεῦσαι, οὐχ ὅτι πόλιν ἐξελεῖν βούλεσθαι τηλικαύτην· λαβὼν μέντοι παρʼ αὐτῶν τὸν ἀντάραντα τῷ βασιλεῖ πρὸς τιμωρίαν Σαβαῖον υἱὸν δὲ Βοχορίου παύσεσθαι τῆς πολιορκίας καὶ τὴν στρατιὰν ἀπάξειν."},{"number":291,"text":"ὡς δʼ ἤκουσεν ἡ γυνὴ τὰ παρὰ τοῦ Ἰωάβου μικρὸν ἐπισχεῖν δεηθεῖσα, τὴν γὰρ κεφαλὴν εὐθέως αὐτῷ ῥιφήσεσθαι τὴν τοῦ πολεμίου, καταβαίνει πρὸς τοὺς πολίτας καὶ βούλεσθʼ, εἰποῦσα, κακοὶ κακῶς ἀπολέσθαι μετὰ τέκνων καὶ γυναικῶν ὑπὲρ ἀνθρώπου πονηροῦ καὶ μηδὲ τίς ἐστι γνωριζομένου καὶ τοῦτον ἔχειν ἀντὶ Δαυίδου τοῦ τοσαῦτʼ εὐεργετήσαντος ὑμᾶς βασιλέα καὶ πρὸς δύναμιν τοσαύτην καὶ τηλικαύτην ἀνταίρειν μίαν πόλιν;"},{"number":292,"text":"πείθει τὴν κεφαλὴν ἀποτεμόντας τοῦ Σαβαίου ῥῖψαι ταύτην εἰς τὸ τοῦ Ἰωάβου στράτευμα. τούτου γενομένου σημήνας ἀνακλητικὸν ὁ τοῦ βασιλέως στρατηγὸς ἔλυσε τὴν πολιορκίαν καὶ παραγενόμενος εἰς Ἱεροσόλυμα παντὸς ἀποδείκνυται πάλιν τοῦ λαοῦ στρατηγός."},{"number":293,"text":"καθίστησι δὲ καὶ Βαναῖον ὁ βασιλεὺς ἐπὶ τῶν σωματοφυλάκων καὶ τῶν ἑξακοσίων, Ἀδώραμον δʼ ἐποίησεν ἐπὶ τῶν φόρων καὶ Ἰωσάφατον υἱὸν Ἀχίλου ἐπὶ τῶν ὑπομνημάτων, Σουσὰν δὲ γραμματέα, Σάδωκον δὲ καὶ Ἀβιάθαρον ἀπέφηνεν ἱερεῖς."}],"12":[{"number":294,"text":"Μετὰ δὲ ταῦτα τῆς χώρας λιμῷ φθειρομένης ἱκέτευε Δαυίδης τὸν θεὸν ἐλεῆσαι τὸν λαὸν καὶ τὴν αἰτίαν αὐτῷ καὶ τὴν ἴασιν φανερὰν ποιῆσαι τῆς νόσου. τῶν δὲ προφητῶν εἰπόντων βούλεσθαι τὸν θεὸν ἐκδικίας τυχεῖν τοὺς Γαβαωνίτας, οὓς Σαοῦλος ὁ βασιλεὺς ἀποκτείνας ἠσέβησεν ἐξαπατήσας καὶ τοὺς ὅρκους αὐτοῖς, οὓς ὁ στρατηγὸς Ἰησοῦς ὤμοσε καὶ ἡ γερουσία, μὴ φυλάξας·"},{"number":295,"text":"ἐὰν τοίνυν δίκην ἣν αὐτοὶ θέλουσιν οἱ Γαβαωνῖται λαβεῖν ὑπὲρ τῶν ἀνῃρημένων ταύτην αὐτοῖς παράσχῃ, διαλλαγήσεσθαι καὶ τὸν ὄχλον ἀπαλλάξειν τῶν κακῶν ἐπηγγέλλετο."},{"number":296,"text":"ὡς οὖν ταῦτα παρὰ τῶν προφητῶν ἔμαθεν ἐπιζητεῖν τὸν θεόν, μεταπέμπεται τοὺς Γαβαωνίτας καὶ τίνος βούλονται τυχεῖν ἐπηρώτα. τῶν δʼ ἐκ τοῦ γένους τοῦ Σαούλου παραλαβεῖν ἑπτὰ παῖδας ἀξιωσάντων πρὸς τιμωρίαν, ὁ βασιλεὺς ἀναζητήσας παρέδωκεν αὐτοῖς Ἰεβόσθου φεισάμενος τοῦ Ἰωνάθου παιδός."},{"number":297,"text":"παραλαβόντες δʼ οἱ Γαβαωνῖται τοὺς ἄνδρας ὡς ἐβούλοντο ἐκόλασαν. ἤρξατο δʼ ὕειν παραχρῆμα ὁ θεὸς καὶ τὴν γῆν πρὸς γονὴν καρπῶν ἀνακαλεῖν ἀπολύσας τοῦ πρότερον αὐχμοῦ· καὶ πάλιν εὐθήνησεν ἡ τῶν Ἑβραίων χώρα."},{"number":298,"text":"Στρατεύεται δὲ μετʼ οὐ πολὺν χρόνον ὁ βασιλεὺς ἐπὶ Παλαιστίνους, καὶ συνάψας μάχην αὐτοῖς καὶ τρεψάμενος ἐμονώθη διώκων καὶ γενόμενος ἔκλυτος ὤφθη ὑπό τινος τῶν πολεμίων Ἄκμονος μὲν τοὔνομα Ἀράφου δὲ παιδός·"},{"number":299,"text":"οὗτος ἦν μὲν καὶ ἀπόγονος τῶν Γιγάντων, ἔχων δὲ καὶ ξυστόν, οὗ τὴν λαβὴν συνέλκειν σταθμὸν σίκλους τριακοσίους, καὶ θώρακα ἁλυσιδωτὸν καὶ ῥομφαίαν ὥρμησεν ἐπιστραφεὶς ὡς ἀποκτενῶν τὸν τῶν πολεμίων βασιλέα· παρεῖτο γὰρ ὑπὸ τοῦ κόπου. ἐπιφανεὶς δʼ ἐξαίφνης Ἀβεσσαῖος ὁ Ἰωάβου ἀδελφὸς τὸν βασιλέα μὲν ὑπερήσπισε περιβὰς κείμενον, ἀπέκτεινε δὲ τὸν πολέμιον."},{"number":300,"text":"ἤνεγκε δʼ ἐπὶ τῷ παρʼ ὀλίγον κινδυνεῦσαι τὸν βασιλέα χαλεπῶς τὸ πλῆθος· καὶ οἱ ἡγεμόνες ὥρκωσαν αὐτὸν μηκέτι εἰς μάχην ἀπαντῆσαι σὺν αὐτοῖς, μὴ διʼ ἀνδρείαν καὶ προθυμίαν παθών τι τῶν δεινῶν στερήσῃ τὸν λαὸν τῶν διʼ αὐτὸν ἀγαθῶν, ὅσα τε ἤδη παρέσχηκε καὶ ὅσων ἔτι μεθέξουσι πολὺν βιώσαντος χρόνον."},{"number":301,"text":"Συνελθόντων δὲ τῶν Παλαιστίνων εἰς Γάζαρα πόλιν ἀκούσας ὁ βασιλεὺς ἔπεμψεν ἐπʼ αὐτοὺς στρατιάν. ἠρίστευσε δὲ τότε καὶ σφόδρʼ ηὐδοκίμησε Σαβρήχης ὁ Χετταῖος εἷς τῶν περὶ Δαυίδην ἀνδρειοτάτων· ἀπέκτεινε γὰρ πολλοὺς τῶν αὐχούντων προγόνους τοὺς Γίγαντας καὶ μέγα ἐπʼ ἀνδρείᾳ φρονούντων, αἴτιός τε τῆς νίκης τοῖς Ἑβραίοις ἐγένετο."},{"number":302,"text":"καὶ μετʼ ἐκείνην τὴν ἧτταν πάλιν ἐπολέμησαν οἱ Παλαιστῖνοι· καὶ στρατιὰν ἐπʼ αὐτοὺς Δαυίδου πέμψαντος ἠρίστευσεν Ἐφὰν ὁ συγγενὴς αὐτοῦ· μονομαχήσας γὰρ τῷ πάντων ἀνδρειοτάτῳ Παλαιστίνων ἀπέκτεινεν αὐτὸν καὶ τοὺς ἄλλους εἰς φυγὴν ἔτρεψε, πολλοί τε αὐτῶν ἀπέθανον μαχόμενοι."},{"number":303,"text":"διαλιπόντες δʼ ὀλίγον χρόνον ἐστρατοπεδεύσαντο πρὸς τῇ πόλει τῶν ὅρων τῆς Ἑβραίων χώρας οὐκ ἄπωθεν. ἦν δʼ αὐτοῖς ἀνὴρ τὸ μὲν ὕψος ἓξ πηχῶν, δακτύλους δʼ ἐν ἑκατέρῳ τῶν βάσεων καὶ τῶν χειρῶν ἑνὶ περισσοτέρους εἶχε τῶν κατὰ φύσιν."},{"number":304,"text":"ἐκ τῆς οὖν πεμφθείσης ἐπʼ αὐτοὺς ὑπὸ Δαυίδου στρατιᾶς τούτῳ μονομαχήσας Ἰωνάθης ὁ Σουμᾶ υἱὸς ἀνεῖλέ τε αὐτὸν καὶ τῆς ὅλης νίκης ῥοπὴ γενόμενος δόξαν ἀριστείας ἀπηνέγκατο· καὶ γὰρ οὗτος ὁ Παλαιστῖνος ηὔχει τῶν Γιγάντων ἀπόγονος εἶναι. μετὰ δὲ ταύτην τὴν μάχην οὐκέτι τοῖς Ἰσραηλίταις ἐπολέμησαν."},{"number":305,"text":"Ἀπηλλαγμένος δʼ ἤδη πολέμων ὁ Δαυίδης καὶ κινδύνων καὶ βαθείας ἀπολαύων τὸ λοιπὸν εἰρήνης ᾠδὰς εἰς τὸν θεὸν καὶ ὕμνους συνετάξατο μέτρου ποικίλου· τοὺς μὲν γὰρ τριμέτρους, τοὺς δὲ πενταμέτρους ἐποίησεν. ὄργανά τε κατασκευάσας ἐδίδαξε πρὸς αὐτὰ τοὺς Ληουίτας ὑμνεῖν τὸν θεὸν κατά τε τὴν τῶν καλουμένων σαββάτων ἡμέραν καὶ κατὰ τὰς ἄλλας ἑορτάς."},{"number":306,"text":"ἡ δὲ τῶν ὀργάνων ἐστὶν ἰδέα τοιαύτη τις τὸν τρόπον· ἡ μὲν κινύρα δέκα χορδαῖς ἐξημμένη τύπτεται πλήκτρῳ, ἡ δὲ νάβλα δώδεκα φθόγγους ἔχουσα τοῖς δακτύλοις κρούεται, κύμβαλά τε ἦν πλατέα καὶ μεγάλα χάλκεα. καὶ περὶ μὲν τούτων ἐπὶ τοσοῦτον ἡμῖν, ὥστε μὴ τελέως ἀγνοεῖν τὴν τῶν προειρημένων ὀργάνων φύσιν, ἀρκείσθω λελέχθαι."},{"number":307,"text":"Τῷ δὲ βασιλεῖ πάντες ἦσαν οἱ περὶ αὐτὸν ἀνδρεῖοι· τούτων δʼ οἱ διασημότατοι καὶ λαμπροὶ τὰς πράξεις ὀκτὼ καὶ τριάκοντα, ὧν πέντε μόνων διηγήσομαι τὰ ἔργα· φανερὰς γὰρ καὶ τὰς τῶν ἄλλων ἀρετὰς ἀρκέσουσιν οὗτοι ποιῆσαι· δυνατοὶ γὰρ ἦσαν οὗτοι καὶ χώραν ὑπάγεσθαι καὶ μεγάλων ἐθνῶν κρατῆσαι."},{"number":308,"text":"πρῶτος μὲν οὖν Ἴσεβος υἱὸς Ἀχεμαίου, ὃς πολλάκις εἰς τὴν παράταξιν ἐμπηδῶν τῶν πολεμίων οὐ πρὶν ἀνεπαύετο μαχόμενος πρὶν ἐνακοσίους αὐτῶν καταβαλεῖν. μετʼ αὐτὸν ἦν Ἐλεάζαρος υἱὸς Δωδείου, ὃς ἦν μετὰ τοῦ βασιλέως ἐν Ἐρασαμῷ·"},{"number":309,"text":"οὗτός ποτε τῶν Ἰσραηλιτῶν καταπλαγέντων τὸ πλῆθος τῶν Παλαιστίνων καὶ φευγόντων μόνος ἔμεινε καὶ συμπεσὼν τοῖς πολεμίοις ἀπέκτεινεν αὐτῶν πολλούς, ὡς ὑπὸ τοῦ αἵματος προσκολληθῆναι τὴν ῥομφαίαν αὐτοῦ τῇ δεξιᾷ καὶ τοὺς Ἰσραηλίτας ἰδόντας τετραμμένους ὑπʼ αὐτοῦ τοὺς Παλαιστίνους καταβάντας διώκειν καὶ θαυμαστὴν καὶ διαβόητον τότε νίκην ἄρασθαι, τοῦ μὲν Ἐλεαζάρου κτείνοντος ἑπομένου δὲ τοῦ πλήθους καὶ σκυλεύοντος τοὺς ἀνῃρημένους."},{"number":310,"text":"τρίτος δὲ ἦν Ἠλοῦ μὲν υἱὸς Σαβαίας δὲ ὄνομα. καὶ οὗτος ἐν τοῖς πρὸς Παλαιστίνους ἀγῶσιν εἰς τόπον Σιαγόνα λεγόμενον αὐτῶν παραταξαμένων, ὡς οἱ Ἑβραῖοι πάλιν τὴν δύναμιν φοβηθέντες οὐχ ὑπέμειναν, ὑπέστη μόνος ὡς στράτευμα καὶ τάξις, καὶ τοὺς μὲν αὐτῶν κατέβαλε τοὺς δʼ οὐ καρτερήσαντας αὐτοῦ τὴν ἰσχὺν καὶ τὴν βίαν ἀλλʼ εἰς φυγὴν ἀποστραφέντας ἐδίωκε."},{"number":311,"text":"ταῦτα μὲν ἔργα χειρῶν καὶ μάχης οἱ τρεῖς ἐπεδείξαντο. καθʼ ὃν δὲ καιρὸν ἐν Ἱεροσολύμοις ὄντος τοῦ βασιλέως ἐπῆλθεν ἡ τῶν Παλαιστίνων δύναμις πολεμῆσαι, Δαυίδης μὲν ἐπὶ τὴν ἀκρόπολιν ἀνῆλθεν, ὡς προειρήκαμεν, πευσόμενος τοῦ θεοῦ περὶ τοῦ πολέμου,"},{"number":312,"text":"τῆς δὲ τῶν ἐχθρῶν παρεμβολῆς ἐν τῇ κοιλάδι κειμένης, ἣ μέχρι Βηθλεέμης πόλεως διατείνει σταδίους Ἱεροσολύμων ἀπεχούσης εἴκοσιν, ὁ Δαυίδης τοῖς ἑταίροις καλὸν ὕδωρ , εἶπεν, ἔχομεν ἐν τῇ πατρίδι μου· καὶ μάλιστα τὸ ἐν τῷ λάκκῳ τῷ πρὸς τῇ πύλῃ θαυμάζων, εἴ τις ἐξ αὐτοῦ πιεῖν αὐτῷ κομίσειε μᾶλλον ἐθελήσειν ἢ εἰ πολλὰ χρήματα διδοῖ."},{"number":313,"text":"ταῦτʼ ἀκούσαντες οἱ τρεῖς ἄνδρες οὗτοι παραχρῆμα ἐκδραμόντες καὶ διὰ μέσου τοῦ τῶν πολεμίων ὁρμήσαντες στρατοπέδου ἧκον εἰς Βηθλεέμην, καὶ τοῦ ὕδατος ἀρυσάμενοι πάλιν διὰ τῆς παρεμβολῆς ὑπέστρεψαν πρὸς τὸν βασιλέα, ὡς τοὺς Παλαιστίνους καταπλαγέντας αὐτῶν τὸ θράσος καὶ τὴν εὐψυχίαν ἠρεμῆσαι καὶ μηδὲν ἐπʼ αὐτοὺς τολμῆσαι καταφρονήσαντας τῆς ὀλιγότητος."},{"number":314,"text":"κομισθέντος δὲ τοῦ ὕδατος οὐκ ἔπιεν ὁ βασιλεὺς κινδύνῳ καὶ αἵματι φήσας ἀνθρώπων αὐτὸ κεκομίσθαι καὶ διὰ τοῦτο μὴ προσήκειν αὐτῷ πιεῖν, ἔσπεισε δὲ ἀπʼ αὐτοῦ τῷ θεῷ καὶ περὶ τῆς σωτηρίας τῶν ἀνδρῶν εὐχαρίστησεν αὐτῷ. μετὰ τούτους ἦν ὁ Ἰωάβου ἀδελφὸς Ἀβεσσαῖος·"},{"number":315,"text":"καὶ γὰρ οὗτος μιᾷ ἡμέρᾳ τῶν πολεμίων ἑξακοσίους ἀπέκτεινε. πέμπτος Ναβαῖος ὁ ἱερεὺς τῷ γένει· προκληθεὶς γὰρ ὑπʼ ἀδελφῶν διασήμων ἐν τῇ Μωαβίτιδι χώρᾳ κατʼ ἀρετὴν ἐκράτησεν αὐτῶν. καὶ πάλιν αὐτὸν ἀνδρὸς Αἰγυπτίου τὸ γένος θαυμαστοῦ τὸ μέγεθος προκαλεσαμένου, γυμνὸς ὡπλισμένον τῷ δόρατι τῷ ἐκείνου βαλὼν ἀπέκτεινε· περιελόμενος γὰρ αὐτοῦ τὸν ἄκοντα καὶ ζῶντα ἔτι καὶ μαχόμενον σκυλεύσας τοῖς ἰδίοις αὐτὸν ὅπλοις διεχρήσατο."},{"number":316,"text":"προσαριθμήσειε δὲ ἄν τις αὐτοῦ καὶ τοῦτο ταῖς προειρημέναις πράξεσιν ἢ ὡς πρῶτον αὐτῶν κατʼ εὐψυχίαν ἢ ὡς ὅμοιον· νίφοντος γὰρ τοῦ θεοῦ λέων εἴς τινα λάκκον ὀλισθὼν ἐνέπεσε· στενοῦ δʼ ὄντος τοῦ στομίου δῆλον ἦν ἀφανὲς ἐσόμενον ἐμφραγέντος αὐτοῦ τῇ χιόνι· πόρον οὖν οὐδένα βλέπων ἐξόδου καὶ σωτηρίας ἐβρυχᾶτο."},{"number":317,"text":"τοῦ δὲ θηρὸς ἀκούσας ὁ Ναβαῖος, ὥδευε γὰρ τότε, καὶ πρὸς τὴν βοὴν ἐλθών, καταβὰς εἰς τὸ στόμιον πλήξας αὐτὸν μαχόμενον τῷ μετὰ χεῖρας ξύλῳ παραχρῆμα ἀπέκτεινε. καὶ οἱ λοιποὶ δὲ τοιοῦτοι τὰς ἀρετὰς ὑπῆρχον."}],"13":[{"number":318,"text":"Ὁ δὲ βασιλεὺς Δαυίδης βουλόμενος γνῶναι πόσαι μυριάδες εἰσὶ τοῦ λαοῦ, τῶν Μωυσέος ἐντολῶν ἐκλαθόμενος, ὃς προεῖπεν ἐὰν ἐξαριθμηθῇ τὸ πλῆθος ὑπὲρ ἑκάστης κεφαλῆς αὐτοῦ τῷ θεῷ τελεῖν ἡμίσικλον, προσέταξεν Ἰωάβῳ τῷ στρατηγῷ πορευθέντι πάντα τὸν ὄχλον ἐξαριθμῆσαι."},{"number":319,"text":"τοῦ δʼ οὐκ ἀναγκαῖον εἶναι φήσαντος τοῦτο ποιεῖν οὐκ ἐπείσθη, προσέταξε δὲ μηδὲν μελλήσαντα βαδίζειν ἐπὶ τὴν ἐξαρίθμησιν τῶν Ἑβραίων. Ἰώαβος δὲ τοὺς ἄρχοντας τῶν φυλῶν παραλαβὼν καὶ γραμματεῖς, ἐπιὼν τὴν τῶν Ἰσραηλιτῶν χώραν καὶ τὸ πλῆθος ὅσον ἐστὶ κατανοήσας ὑπέστρεψεν εἰς Ἱεροσόλυμα πρὸς τὸν βασιλέα μετὰ μῆνας ἐννέα καὶ ἡμέρας εἴκοσι καὶ τὸν ἀριθμὸν ἀπέδωκε τῷ βασιλεῖ τοῦ λαοῦ χωρὶς τῆς Βενιαμίτιδος φυλῆς·"},{"number":320,"text":"ἐξαριθμῆσαι γὰρ αὐτὴν οὐκ ἔφθασεν ἀλλʼ οὐδὲ τὴν Λευιτῶν φυλήν· μετενόησε γὰρ ὁ βασιλεὺς ὧν εἰς τὸν θεὸν ἥμαρτεν. ἦν δὲ τῶν ἄλλων Ἰσραηλιτῶν ἀριθμὸς ἐνενήκοντα μυριάδες ὅπλα βαστάζειν καὶ στρατεύεσθαι δυναμένων, ἡ δὲ Ἰούδα φυλὴ καθʼ ἑαυτὴν τεσσαράκοντα μυριάδες ἦσαν."},{"number":321,"text":"Τῶν δὲ προφητῶν δηλωσάντων τῷ Δαυίδῃ, ὅτι διʼ ὀργῆς ἐστιν ὁ θεὸς αὐτῷ, ἱκετεύειν ἤρξατο καὶ παρακαλεῖν εὐμενῆ γενέσθαι καὶ συγγινώσκειν ἡμαρτηκότι. Γάδον δὲ τὸν προφήτην ἔπεμψεν ὁ θεὸς πρὸς αὐτὸν τρεῖς αἱρέσεις κομίζοντα, ὅπως ἐκλέξηται τούτων ἣν ἂν δοκιμάσῃ· πότερον θέλει λιμὸν γενέσθαι κατὰ τὴν χώραν ἐπὶ ἔτη ἑπτά, ἢ τρεῖς μῆνας πολεμήσας ὑπὸ τῶν ἐχθρῶν ἡττηθῆναι, ἢ λοιμὸν ἐνσκῆψαι καὶ νόσον ἐπὶ τρεῖς ἡμέρας τοῖς Ἑβραίοις."},{"number":322,"text":"ὁ δʼ εἰς ἀμήχανον ἐκλογὴν μεγάλων κακῶν ἐμπεσὼν ἐλυπεῖτο καὶ σφόδρʼ ἦν συγκεχυμένος. τοῦ δὲ προφήτου τοῦτο δεῖν ἐξ ἀνάγκης γενέσθαι φήσαντος καὶ κελεύοντος ἀποκρίνασθαι ταχέως, ἵνα ἀναγγείλῃ τὴν αἵρεσιν αὐτοῦ τῷ θεῷ, λογισάμενος ὁ βασιλεύς, ὡς εἰ λιμὸν αἰτήσει, δόξει τοῦτο πεποιηκέναι τοῖς ἄλλοις αὐτῷ μὲν ἀφόβως, ὅτι πολὺν αὐτὸς ἐγκεκλεισμένον ἔχοι σῖτον, ἐκείνοις δὲ βλαβερῶς·"},{"number":323,"text":"κἂν γένηται τοὺς τρεῖς μῆνας νικωμένους αὐτούς, ὅτι τοὺς ἀνδρειοτάτους ἔχων περὶ αὑτὸν καὶ φρούρια καὶ διὰ τοῦτο μηδὲν φοβούμενος εἵλετο τὸν πόλεμον, ᾐτήσατο πάθος κοινὸν καὶ βασιλεῦσι καὶ τοῖς ἀρχομένοις, ἐν ᾧ τὸ δέος ἶσον ἁπάντων γίνεται, προσειπὼν ὅτι πολὺ κρεῖττον εἰς τὰς τοῦ θεοῦ χεῖρας ἐμπεσεῖν ἢ τὰς τῶν πολεμίων."},{"number":324,"text":"Ταῦτʼ ἀκούσας ὁ προφήτης ἀπήγγειλε τῷ θεῷ· ὁ δὲ τὸν λοιμὸν καὶ τὴν φθορὰν ἔπεμψε τοῖς Ἑβραίοις. ἀπέθνησκον δʼ οὐ μονοτρόπως οὐδʼ ὥστε ῥᾴδιον κατανοῆσαι γενέσθαι τὴν νόσον, ἀλλὰ τὸ μὲν κακὸν ἓν ἦν, μυρίαις δʼ αὐτοὺς αἰτίαις καὶ προφάσεσιν οὐδʼ ἐπινοῆσαι δυναμένους ἀνήρπαζεν."},{"number":325,"text":"ἄλλος γὰρ ἐπʼ ἄλλῳ διεφθείρετο, καὶ λανθάνον ἐπερχόμενον τὸ δεινὸν ὀξεῖαν τὴν τελευτὴν ἐπέφερεν, τῶν μὲν αἰφνιδίως μετʼ ἀλγημάτων σφοδρῶν καὶ πικρᾶς ὀδύνης τὴν ψυχὴν ἀφιέντων, ἐνίων δὲ καὶ μαραινομένων τοῖς παθήμασι καὶ μηδʼ εἰς κηδείαν ὑπολειπομένων, ἀλλʼ ἐν αὐτῷ τῷ κάμνειν εἰς τὸ παντελὲς δαπανωμένων·"},{"number":326,"text":"οἱ δʼ αἰφνίδιον σκότους αὐτοῖς τὰς ὄψεις ὑποδραμόντος περιπνιγεῖς ἀπῴμωζον, ἔνιοι δὲ τῶν οἰκείων τινὰ κηδεύοντες ἐναπέθνησκον ἀτελέσι ταῖς ταφαῖς. ἀπώλοντο δʼ ἀρξαμένης ἕωθεν τῆς λοιμικῆς νόσου φθείρειν αὐτοὺς ἕως ὥρας ἀρίστου μυριάδες ἑπτά."},{"number":327,"text":"ἐξέτεινε δὲ ὁ ἄγγελος τὴν χεῖρα καὶ ἐπὶ τὰ Ἱεροσόλυμα τὸ δεινὸν κἀκεῖσε πέμπων. ὁ δὲ βασιλεὺς σάκκον ἐνδεδυμένος ἔκειτο κατὰ τῆς γῆς ἱκετεύων τὸν θεὸν καὶ δεόμενος ἤδη λωφῆσαι καὶ τοῖς ἀπολωλόσιν ἀρκεσθέντα παύσασθαι· ἀναβλέψας δʼ εἰς τὸν ἀέρα ὁ βασιλεὺς καὶ θεασάμενος τὸν ἄγγελον διʼ αὐτοῦ φερόμενον ἐπὶ τὰ Ἱεροσόλυμα καὶ μάχαιραν ἐσπασμένον εἶπε πρὸς τὸν θεόν,"},{"number":328,"text":"ὡς αὐτὸς εἴη κολασθῆναι δίκαιος ὁ ποιμήν, τὰ δὲ ποίμνια σώζεσθαι μηδὲν ἁμαρτόντα, καὶ ἠντιβόλει τὴν ὀργὴν εἰς αὐτὸν καὶ τὴν γενεὰν αὐτοῦ πᾶσαν ἀποσκήπτειν, φείδεσθαι δὲ τοῦ λαοῦ."},{"number":329,"text":"Κατακούσας δὲ ὁ θεὸς τῆς ἱκεσίας ἔπαυσε τὸν λοιμόν, καὶ πέμψας Γάδον τὸν προφήτην ἐκέλευσεν αὐτὸν ἀναβῆναι παραχρῆμα εἰς τὴν ἅλω τοῦ Ἰεβουσαίου Ὀροννᾶ καὶ οἰκοδομήσαντα βωμὸν ἐκεῖ τῷ θεῷ θυσίαν ἐπιτελέσαι. Δαυίδης δʼ ἀκούσας οὐκ ἠμέλησεν, ἀλλʼ εὐθὺς ἔσπευσεν ἐπὶ τὸν παρηγγελμένον αὐτῷ τόπον."},{"number":330,"text":"Ὀροννᾶς δὲ τὸν σῖτον ἀλοῶν ἐπεὶ τὸν βασιλέα προσιόντα καὶ τοὺς παῖδας αὐτοῦ πάντας ἐθεάσατο, προσέδραμεν αὐτῷ καὶ προσεκύνησεν. ἦν δὲ τὸ μὲν γένος Ἰεβουσαῖος, φίλος δʼ ἐν τοῖς μάλιστα Δαυίδου· καὶ διὰ τοῦτʼ αὐτὸν οὐδὲν εἰργάσατο δεινόν, ὅτε τὴν πόλιν κατεστρέψατο, ὡς μικρὸν ἔμπροσθεν ἐδηλώσαμεν."},{"number":331,"text":"τοῦ δὲ Ὀροννᾶ πυθομένου τί παρείη πρὸς τὸν δοῦλον ὁ δεσπότης, εἶπεν ὠνήσασθαι παρʼ αὐτοῦ τὴν ἅλω, ὅπως βωμὸν ἐν αὐτῇ κατασκευάσῃ τῷ θεῷ καὶ ποιήσῃ θυσίαν. ὁ δὲ καὶ τὴν ἅλω εἶπε καὶ τὰ ἄροτρα καὶ τοὺς βόας εἰς ὁλοκαύτωσιν χαρίζεσθαι καὶ τὸν θεὸν ἡδέως εὔχεσθαι τὴν θυσίαν προσέσθαι."},{"number":332,"text":"ὁ δὲ βασιλεὺς ἀγαπᾶν μὲν αὐτὸν τῆς ἁπλότητος καὶ τῆς μεγαλοψυχίας ἔλεγε καὶ δέχεσθαι τὴν χάριν, τιμὴν δʼ αὐτὸν ἠξίου λαμβάνειν πάντων· οὐ γὰρ εἶναι δίκαιον προῖκα θυσίαν ἐπιτελεῖν. τοῦ δὲ Ὀροννᾶ φήσαντος ποιεῖν ὅ τι βούλεται πεντήκοντα σίκλων ὠνεῖται παρʼ αὐτοῦ τὴν ἅλω."},{"number":333,"text":"καὶ οἰκοδομήσας τὸν βωμὸν ἱερούργησε καὶ ὡλοκαύτωσε καὶ θυσίας ἐπήνεγκεν εἰρηνικάς. καταπραΰνεται δὲ τούτοις τὸ θεῖον καὶ πάλιν εὐμενὲς γίνεται. συνέβη δʼ εἰς ἐκεῖνον ἀγαγεῖν τὸν τόπον Ἅβραμον τὸν υἱὸν αὐτοῦ Ἴσακον ὥστε ὁλοκαυτῶσαι, καὶ μέλλοντος ἀποσφάττεσθαι τοῦ παιδὸς κριὸν ἐξαίφνης ἀναφανῆναι παρεστῶτα τῷ βωμῷ, ὃν καὶ κατέθυσεν Ἅβραμος ἀντὶ τοῦ παιδός, ὡς προειρήκαμεν."},{"number":334,"text":"ὁρῶν δʼ ὁ βασιλεὺς Δαυίδης τῆς εὐχῆς αὐτοῦ τὸν θεὸν ἐπήκοον γεγενημένον καὶ τὴν θυσίαν ἡδέως προσδεξάμενον ἔκρινε τὸν τόπον ἐκεῖνον ὅλον βωμὸν προσαγορεῦσαι τοῦ λαοῦ παντὸς καὶ οἰκοδομῆσαι ναὸν τῷ θεῷ. καὶ ταύτην εὐστόχως ἀφῆκεν εἰς τὸ γενησόμενον τὴν φωνήν· ὁ γὰρ θεὸς τὸν προφήτην ἀποστείλας πρὸς αὐτὸν ἐκεῖ ναὸν ἔλεγεν οἰκοδομήσειν αὐτοῦ τὸν υἱὸν τὸν μέλλοντα μετʼ αὐτὸν τὴν βασιλείαν διαδέχεσθαι."}],"14":[{"number":335,"text":"Μετὰ δὴ ταύτην τὴν προφητείαν ἐκέλευσεν ὁ βασιλεὺς τοὺς παροίκους ἐξαριθμηθῆναι καὶ εὑρέθησαν εἰς ὀκτὼ μυριάδας καὶ δέκα. ἐκ τούτων ἀπέδειξε λατόμους μὲν τοὺς ὀκτακισμυρίους, τὸ δʼ ἄλλο πλῆθος παραφέρειν τοὺς λίθους, τρισχιλίους δὲ καὶ πεντακοσίους τοῖς ἐργαζομένοις ἐξ αὐτῶν ἐπέστησεν. ἡτοίμασε δὲ καὶ πολὺν σίδηρον καὶ χαλκὸν εἰς τὰ ἔργα καὶ ξύλα κέδρινα πολλὰ καὶ παμμεγεθέστατα, Τυρίων αὐτῷ ταῦτα πεμπόντων καὶ Σιδωνίων· ἐπεστάλκει γὰρ αὐτοῖς τὴν τῶν ξύλων χορηγίαν."},{"number":336,"text":"πρός τε τοὺς φίλους ἔλεγε ταῦτα παρασκευάζεσθαι νῦν, ἵνα τῷ μέλλοντι παιδὶ βασιλεύειν μετʼ αὐτὸν ἑτοίμην τὴν ὕλην τῆς οἰκοδομίας καταλείπῃ καὶ μὴ τότε συμπορίζῃ νέος ὢν καὶ τῶν τοιούτων ἄπειρος διὰ τὴν ἡλικίαν, ἀλλʼ ἔχων παρακειμένην ἐπιτελῇ τὸ ἔργον."},{"number":337,"text":"Καλέσας δὲ τὸν παῖδα Σολόμωνα κατασκευάσαι τῷ θεῷ ναὸν αὐτὸν ἐκέλευε διαδεξάμενον τὴν βασιλείαν λέγων, ὡς αὐτὸν βουλόμενον κωλύσειεν ὁ θεὸς αἵματι καὶ πολέμοις πεφυραμένον, προείποι δʼ ὅτι Σολόμων οἰκοδομήσει αὐτῷ παῖς νεώτατος καὶ τοῦτο κληθησόμενος τοὔνομα, οὗ προνοήσειν μὲν αὐτὸς ὡς πατὴρ ἐπηγγέλλετο, τὴν δʼ Ἑβραίων χώραν εὐδαίμονα καταστήσειν ἐπʼ αὐτοῦ τοῖς τε ἄλλοις ἀγαθοῖς καὶ δὴ καὶ τῷ μεγίστῳ πάντων εἰρήνῃ καὶ πολέμων ἀπαλλαγῇ καὶ στάσεων ἐμφυλίων."},{"number":338,"text":"σὺ τοίνυν ἐπεὶ καὶ πρὸ τῆς γενέσεως ἀπεδείχθης βασιλεὺς ὑπὸ τοῦ θεοῦ πειρῶ τά τε ἄλλα γίνεσθαι τῆς τούτου προνοίας ἄξιος εὐσεβὴς ὢν καὶ δίκαιος καὶ ἀνδρεῖος, καὶ τὰς ἐντολὰς αὐτοῦ καὶ τοὺς νόμους οὓς διὰ Μωυσέος ἔδωκεν ἡμῖν φύλαττε καὶ τοῖς ἄλλοις μὴ παραβαίνειν ἐπίτρεπε."},{"number":339,"text":"τὸν δὲ ναόν, ὃν ὑπὸ σοῦ βασιλεύοντος εἵλετο αὑτῷ γενέσθαι, σπούδασον ἀποδοῦναι τῷ θεῷ μὴ καταπλαγεὶς τὸ μέγεθος τοῦ ἔργου μηδʼ ἀποδειλιάσας πρὸς αὐτό· πάντα γάρ σοι πρὸ τῆς ἐμαυτοῦ τελευτῆς ἕτοιμα ποιήσω."},{"number":340,"text":"γίνωσκε χρυσοῦ μὲν ἤδη τάλαντα συνειλεγμένα μύρια, δέκα δʼ ἀργύρου μυριάδας ταλάντων, χαλκόν τε καὶ σίδηρον ἀριθμοῦ πλείονα συντέθεικα καὶ ξύλων δὲ καὶ λίθων ὕλην ἄφθονον, ἔχεις δὲ καὶ λατόμων πολλὰς μυριάδας καὶ τεκτόνων· ἂν δέ τι τούτοις προσδέῃ, σὺ προσθήσεις. γίνου τοίνυν ἄριστος τὸν θεὸν ἔχων προστάτην."},{"number":341,"text":"προσπαρεκελεύσατο δὲ καὶ τοὺς ἄρχοντας τοῦ λαοῦ τῆς οἰκοδομίας συλλαβέσθαι τῷ παιδὶ καὶ πάντων ἀδεεῖς ὄντας τῶν κακῶν περὶ τὴν τοῦ θεοῦ θρησκείαν ἀσχολεῖν· καρπώσεσθαι γὰρ αὐτοὺς ἀντὶ τούτων εἰρήνην καὶ εὐνομίαν, οἷς ἀμείβεται τοὺς εὐσεβεῖς καὶ δικαίους ὁ θεὸς ἀνθρώπους."},{"number":342,"text":"οἰκοδομηθέντος δὲ τοῦ ναοῦ τὴν κιβωτὸν αὐτὸν ἀποθέσθαι προσέταξε καὶ τὰ ἅγια σκεύη πρὸ πολλοῦ ναὸν ὀφείλοντα ἔχειν, εἰ τῶν ἐντολῶν τοῦ θεοῦ μὴ παρήκουσαν ἡμῶν οἱ πατέρες ἐντειλαμένου μετὰ τὸ τὴν γῆν ταύτην κατασχεῖν οἰκοδομῆσαι ναὸν αὐτῷ. ταῦτα μὲν πρὸς τοὺς ἡγεμόνας ὁ Δαυίδης καὶ τὸν υἱὸν αὐτοῦ διελέχθη."},{"number":343,"text":"Πρεσβύτερος δὲ ὢν ἤδη καὶ τοῦ σώματος αὐτῷ ψυχομένου διὰ τὸν χρόνον δύσριγος ὑπῆρχεν, ὡς μηδʼ ὑπὸ τῆς ἐπιβολῆς ἐκ πολλῶν ἱματίων γινομένης ἀναθερμαίνεσθαι. συνελθόντων δὲ τῶν ἰατρῶν καὶ συμβουλευσάντων, ὅπως ἐξ ἁπάσης τῆς χώρας εὐειδὴς ἐπιλεχθεῖσα παρθένος συγκαθεύδῃ τῷ βασιλεῖ, τοῦτο γὰρ αὐτῷ πρὸς τὸ ῥῖγος ἔσεσθαι βοήθημα θαλπούσης αὐτὸν τῆς κόρης,"},{"number":344,"text":"εὑρίσκετʼ ἐν πόλει γυνὴ μία πασῶν τὸ εἶδος ἀρίστη γυναικῶν Ἀβισάκη τοὔνομα, ἣ συγκοιμωμένη μόνον τῷ βασιλεῖ συνεθέρμαινεν αὐτόν· ὑπὸ γὰρ γήρως ἦν πρὸς τἀφροδίσια καὶ γυναικὸς ὁμιλίαν ἀσθενής. καὶ περὶ μὲν ταύτης τῆς παρθένου μετʼ ὀλίγον δηλώσομεν."},{"number":345,"text":"Ὁ δὲ τέταρτος υἱὸς Δαυίδου νεανίας εὐειδὴς καὶ μέγας, ἐκ γυναικὸς αὐτῷ Αἰγίσθης γεγονὼς Ἀδωνίας δὲ προσαγορευόμενος, ἐμφερὴς ὢν Ἀψαλώμῳ τήν τε διάνοιαν αὐτὸς ὡς βασιλεύσων ἐπῆρτο καὶ πρὸς τοὺς φίλους ἔλεγεν, ὡς τὴν ἀρχὴν αὐτὸν δεῖ παραλαβεῖν· κατεσκεύασε δὲ ἅρματα πολλὰ καὶ ἵππους καὶ πεντήκοντα ἄνδρας τοὺς προδρόμους."},{"number":346,"text":"ταῦθʼ ὁρῶν ὁ πατὴρ οὐκ ἐπέπληττεν οὐδʼ ἐπεῖχεν αὐτὸν τῆς προαιρέσεως οὐδὲ μέχρι τοῦ πυθέσθαι διὰ τί ταῦτα πράττει προήχθη. συνεργοὺς δʼ εἶχεν Ἀδωνίας τὸν στρατηγὸν Ἰώαβον καὶ τὸν ἀρχιερέα Ἀβιάθαρον, μόνοι δʼ ἀντέπραττον ὁ ἀρχιερεὺς Σάδωκος καὶ ὁ προφήτης Νάθας καὶ Βαναίας ὁ ἐπὶ τῶν σωματοφυλάκων καὶ Σιμούεις ὁ Δαυίδου φίλος καὶ πάντες οἱ ἀνδρειότατοι."},{"number":347,"text":"τοῦ δὲ Ἀδωνία παρασκευασαμένου δεῖπνον ἔξω τῆς πόλεως παρὰ τὴν πηγὴν τὴν ἐν τῷ βασιλικῷ παραδείσῳ καὶ πάντας καλέσαντος τοὺς ἀδελφοὺς χωρὶς Σολόμωνος, παραλαβόντος δὲ καὶ τὸν στρατηγὸν Ἰώαβον καὶ Ἀβιάθαρον καὶ τοὺς ἄρχοντας τῆς Ἰούδα φυλῆς, οὔτε δὲ Σάδωκον τὸν ἀρχιερέα καὶ Νάθαν τὸν προφήτην καὶ τὸν ἐπὶ τῶν σωματοφυλάκων Βαναίαν καὶ πάντας τοὺς ἐκ τῆς ἐναντίας αἱρέσεως καλέσαντος ἐπὶ τὴν ἑστίασιν,"},{"number":348,"text":"τοῦτο πρὸς τὴν Σολόμωνος κατεμήνυσε μητέρα Βερσάβην Νάθας ὁ προφήτης, ὡς Ἀδωνίας βασιλεῦσαι βούλεται, συνεβούλευέ τε σώζειν αὑτὴν καὶ τὸν παῖδα Σολόμωνα, εἴπερ Ἀδωνίας τὴν ἀρχὴν ἤδη παραλάβοι, καὶ περὶ τούτου πυθέσθαι τοῦ βασιλέως."},{"number":349,"text":"ταῦτα δὲ τῷ βασιλεῖ διαλεγομένης ὁ προφήτης εἰσελεύσεσθαι καὶ αὐτὸς ἔφησε καὶ τοῖς λόγοις αὐτῆς ἐπιμαρτυρήσειν. ἡ δὲ Βερσάβη πεισθεῖσα τῷ Νάθᾳ πάρεισι πρὸς τὸν βασιλέα,"},{"number":350,"text":"καὶ προσκυνήσασα καὶ λόγον αἰτησαμένη πάντʼ αὐτῷ καθὼς ὁ προφήτης ὑπέθετο διεξέρχεται τό τε δεῖπνον τὸ Ἀδωνία καὶ τοὺς ὑπʼ αὐτοῦ κεκλημένους Ἀβιάθαρον τὸν ἀρχιερέα καὶ Ἰώαβον τὸν ἄρχοντα καὶ τοὺς υἱοὺς αὐτοῦ χωρὶς Σολόμωνος καὶ τῶν ἀναγκαίων αὐτοῦ φίλων μηνύσασα· ἔλεγέ τε πάντα τὸν λαὸν ἀφορᾶν, τίνα χειροτονήσει βασιλέα, παρεκάλει τε κατὰ νοῦν ἔχειν, ὡς μετὰ τὴν ἀπαλλαγὴν αὐτοῦ βασιλεύσας αὐτήν τε καὶ Σολόμωνα τὸν υἱὸν αὐτῆς ἀναιρήσει."},{"number":351,"text":"Διαλεγομένης δὲ ἔτι τῆς γυναικὸς ἤγγειλαν οἱ τοῦ δωματίου προεστῶτες, ὅτι βούλεται Νάθας ἰδεῖν αὐτόν. τοῦ δὲ βασιλέως ἐκδέξασθαι κελεύσαντος εἰσελθών, εἰ τήμερον ἀποδείξειε τὸν Ἀδωνίαν βασιλέα καὶ παραδοίη τὴν ἀρχὴν ἐπυνθάνετο·"},{"number":352,"text":"λαμπρὸν γὰρ αὐτὸν ποιήσαντα δεῖπνον κεκληκέναι τοὺς υἱοὺς αὐτοῦ πάντας χωρὶς Σολόμωνος καὶ τὸν στρατηγὸν Ἰώαβον, οἳ μετὰ κρότου καὶ παιδιᾶς εὐωχούμενοι πολλῆς αἰώνιον αὐτῷ συνεύχονται τὴν ἡγεμονίαν· ἐκάλεσε δὲ οὔτε ἐμὲ οὔτε τὸν ἀρχιερέα Σάδωκον οὔτε Βαναίαν τὸν ἐπὶ τῶν σωματοφυλάκων· δίκαιον δʼ εἶναι ταῦτα γινώσκειν ἅπαντας, εἰ κατὰ τὴν σὴν γνώμην ἐγένετο."},{"number":353,"text":"ταῦτα τοῦ Νάθα φήσαντος ὁ βασιλεὺς ἐκέλευσε καλέσαι τὴν Βερσάβην πρὸς αὑτόν· ἐκπεπηδήκει γὰρ ἐκ τοῦ δωματίου τοῦ προφήτου παραγενομένου. τῆς δὲ γυναικὸς ἐλθούσης, ὄμνυμί σοι, φησί, τὸν μέγιστον θεόν, ἦ μὴν τὸν υἱόν σου Σολόμωνα βασιλεύσειν, ὡς καὶ πρότερον ὤμοσα, καὶ τοῦτον ἐπὶ τοὐμοῦ καθιεῖσθαι θρόνου· καὶ τοῦτο ἔσται τήμερον."},{"number":354,"text":"προσκυνησάσης δʼ αὐτὸν τῆς γυναικὸς καὶ μακρὸν εὐξαμένης αὐτῷ βίον Σάδωκον μεταπέμπεται τὸν ἀρχιερέα καὶ Βαναίαν τὸν ἐπὶ τῶν σωματοφυλάκων,"},{"number":355,"text":"καὶ παραγενομένοις κελεύει παραλαβεῖν Νάθαν τὸν προφήτην καὶ τοὺς περὶ τὴν αὐλὴν ὁπλίτας καὶ ἀναβιβάσαντας τὸν υἱὸν αὐτοῦ Σολόμωνα ἐπὶ τὴν βασιλικὴν ἡμίονον ἔξω τῆς πόλεως ἀγαγεῖν ἐπὶ πηγὴν τὴν λεγομένην Γειὼν καὶ περιχρίσαντας τὸ ἅγιον ἔλαιον ἀποδεῖξαι βασιλέα· τοῦτο δὲ ποιῆσαι προσέταξε Σάδωκον τὸν ἀρχιερέα καὶ Νάθαν τὸν προφήτην."},{"number":356,"text":"ἀκολουθοῦντάς τε προσέταξε διὰ μέσης τῆς πόλεως τοῖς κέρασιν ἐπισαλπίζοντας βοᾶν εἰς αἰῶνα Σολόμωνα τὸν βασιλέα καθίσαι ἐπὶ τοῦ βασιλικοῦ θρόνου, ἵνα γνῷ πᾶς ὁ λαὸς ἀποδεδειγμένον αὐτὸν ὑπὸ τοῦ πατρὸς βασιλέα, Σολόμωνι δʼ ἐντετάλθαι περὶ τῆς ἀρχῆς, ἵνα εὐσεβῶς καὶ δικαίως προστῇ τοῦ τε Ἑβραίων ἔθνους παντὸς καὶ τῆς Ἰούδα φυλῆς."},{"number":357,"text":"Βαναία δὲ εὐξαμένου τὸν θεὸν Σολόμωνι εὐμενῆ γενέσθαι μηδὲ μικρὸν διαλιπόντες ἀναβιβάζουσιν ἐπὶ τὴν ἡμίονον τὸν Σολόμωνα, καὶ προαγαγόντες ἔξω τῆς πόλεως ἐπὶ τὴν πηγὴν καὶ τῷ ἐλαίῳ χρίσαντες εἰσήγαγον εἰς τὴν πόλιν ἐπευφημοῦντες καὶ τὴν βασιλείαν αὐτῷ γενέσθαι πολυχρόνιον εὐχόμενοι,"},{"number":358,"text":"καὶ παραγαγόντες εἰς τὸν οἶκον τὸν βασιλικὸν καθίζουσιν αὐτὸν ἐπὶ τοῦ θρόνου, καὶ πᾶς ὁ λαὸς ἐπʼ εὐωχίαν εὐθὺς ἐτράπη καὶ ἑορτὴν χορεύων καὶ αὐλοῖς τερπόμενος, ὡς ὑπὸ τοῦ πλήθους τῶν ὀργάνων ἅπασαν περιηχεῖσθαι τὴν γῆν καὶ τὸν ἀέρα."},{"number":359,"text":"Ὡς δʼ ᾔσθοντο τῆς βοῆς Ἀδωνίας τε καὶ οἱ παρόντες ἐπὶ τὸ δεῖπνον ἐταράχθησαν, ὅ τε στρατηγὸς Ἰώαβος ἔλεγεν οὐκ ἀρέσκεσθαι τοῖς ἤχοις οὐδὲ τῇ σάλπιγγι. παρακειμένου δὲ τοῦ δείπνου καὶ μηδενὸς γευομένου πάντων δʼ ἐπʼ ἐννοίας ὑπαρχόντων, εἰστρέχει πρὸς αὐτοὺς ὁ τοῦ ἀρχιερέως Ἀβιαθάρου παῖς Ἰωνάθης."},{"number":360,"text":"τοῦ δʼ Ἀδωνία θεασαμένου τὸν νεανίαν ἡδέως καὶ προσειπόντος ἀγαθῶν ἄγγελον, ἐδήλου πάντʼ αὐτοῖς τὰ περὶ τὸν Σολόμωνα καὶ τὴν Δαυίδου τοῦ βασιλέως γνώμην· ἀναπηδήσαντες δʼ ἐκ τοῦ συμποσίου ὅ τε Ἀδωνίας καὶ οἱ κεκλημένοι πάντες ἔφυγον πρὸς ἑαυτοὺς ἕκαστοι."},{"number":361,"text":"φοβηθεὶς δʼ Ἀδωνίας τὸν βασιλέα περὶ τῶν γεγονότων ἱκέτης γίνεται τοῦ θεοῦ καὶ τῶν τοῦ θυσιαστηρίου κεράτων ἃ δὴ προεῖχεν ἐλλαβόμενος δηλοῦται τοῦτο Σολόμωνι πεποιηκὼς καὶ πίστεις ἀξιῶν παρʼ αὐτοῦ λαβεῖν, ὥστε μὴ μνησικακῆσαι μηδʼ ἐργάσασθαι δεινὸν αὐτὸν μηδέν."},{"number":362,"text":"ὁ δὲ ἡμέρως πάνυ καὶ σωφρόνως τῆς μὲν τότε ἁμαρτίας αὐτὸν ἀφῆκεν ἀθῷον, εἰπὼν δέ, εἰ ληφθείη τι πάλιν καινοποιῶν, ἑαυτῷ αἴτιον τῆς τιμωρίας ἔσεσθαι, πέμψας ἀνίστησιν αὐτὸν ἀπὸ τῆς ἱκεσίας· ἐλθόντα δὲ καὶ προσκυνήσαντα εἰς τὴν ἰδίαν οἰκίαν ἀπελθεῖν ἐκέλευσε μηδὲν ὑφορώμενον καὶ τοῦ λοιποῦ παρέχειν αὑτὸν ἀγαθὸν ὡς αὐτῷ τοῦτο συμφέρον ἠξίου."},{"number":363,"text":"Βουλόμενος δὲ Δαυίδης ἐπὶ παντὸς τοῦ λαοῦ ἀποδεῖξαι τὸν υἱὸν βασιλέα συγκαλεῖ τοὺς ἄρχοντας εἰς Ἱεροσόλυμα καὶ τοὺς ἱερεῖς καὶ τοὺς Ληουίτας. ἐξαριθμήσας δὲ τούτους πρῶτον εὑρίσκει τῶν ἀπὸ τριάκοντα ἐτῶν ἕως πεντήκοντα τρισμυρίους ὀκτακισχιλίους."},{"number":364,"text":"ἐξ ὧν ἀπέδειξεν ἐπιμελητὰς μὲν τῆς οἰκοδομίας τοῦ ναοῦ δισμυρίους τετρακισχιλίους, κριτὰς δὲ τοῦ λαοῦ καὶ γραμματεῖς τούτων ἑξακισχιλίους, πυλωροὺς δὲ τετρακισχιλίους καὶ τοσούτους ὑμνῳδοὺς τοῦ θεοῦ ᾄδοντας τοῖς ὀργάνοις οἷς Δαυίδης κατεσκεύασε, καθὼς προειρήκαμεν."},{"number":365,"text":"διεμέρισε δʼ αὐτοὺς καὶ κατὰ πατριὰς καὶ χωρίσας ἐκ τῆς φυλῆς τοὺς ἱερεῖς εὗρε τούτων εἴκοσι τέσσαρας πατριάς, ἐκ μὲν τῆς Ἐλεαζάρου οἰκίας ἑκκαίδεκα, ἐκ δὲ τῆς Ἰθαμάρου ὀκτώ, διέταξέ τε μίαν πατριὰν διακονεῖσθαι τῷ θεῷ ἐπὶ ἡμέρας ὀκτὼ ἀπὸ σαββάτου ἐπὶ σάββατον."},{"number":366,"text":"καὶ οὕτως αἱ πατριαὶ πᾶσαι διεκληρώσαντο Δαυίδου παρόντος καὶ Σαδώκου καὶ Ἀβιαθάρου τῶν ἀρχιερέων καὶ πάντων τῶν ἀρχόντων· καὶ ἡ πρώτη μὲν ἀναβᾶσα πατριὰ ἐγράφη πρώτη, ἡ δὲ δευτέρα ἀκολούθως ἄχρι τῶν εἴκοσι τεσσάρων· καὶ διέμεινεν οὗτος ὁ μερισμὸς ἄχρι τῆς σήμερον ἡμέρας."},{"number":367,"text":"ἐποίησε δὲ καὶ τῆς Ληουίτιδος φυλῆς εἴκοσι μέρη καὶ τέσσαρα καὶ κληρωσαμένων κατὰ τὸν αὐτὸν ἀνέβησαν τρόπον ταῖς τῶν ἱερέων ἐφημερίσιν ἐπὶ ἡμέρας ὀκτώ. τοὺς δʼ ἀπογόνους τοὺς Μωυσέος ἐτίμησεν· ἐποίησε γὰρ αὐτοὺς φύλακας τῶν θησαυρῶν τοῦ θεοῦ καὶ τῶν ἀναθημάτων, ἃ συνέβη τοὺς βασιλεῖς ἀναθεῖναι· διέταξε δὲ πᾶσι τοῖς ἐκ τῆς Ληουίτιδος φυλῆς καὶ τοῖς ἱερεῦσι δουλεύειν κατὰ νύκτα καὶ ἡμέραν τῷ θεῷ, καθὼς αὐτοῖς ἐπέστειλε Μωυσῆς."},{"number":368,"text":"Μετὰ ταῦτα διεμέρισε τὴν στρατιὰν εἰς δώδεκα μοίρας σὺν ἡγεμόσι καὶ ἑκατοντάρχοις καὶ ταξιάρχαις. εἶχεν δʼ ἑκάστη τῶν μοιρῶν δισμυρίους καὶ τετρακισχιλίους, ὧν ἐκέλευσε προσεδρεύειν κατὰ τριάκονθʼ ἡμέρας ἀπὸ τῆς πρώτης ἕως τῆς ὑστάτης Σολόμωνι τῷ βασιλεῖ σὺν τοῖς χιλιάρχοις καὶ ἑκατοντάρχοις."},{"number":369,"text":"κατέστησε δὲ καὶ ἄρχοντα ἑκάστης μοίρας ὃν ἀγαθὸν ᾔδει καὶ δίκαιον, ἐπιτρόπους τε τῶν θησαυρῶν καὶ κωμῶν καὶ ἀγρῶν ἄλλους καὶ κτηνῶν, ὧν οὐκ ἀναγκαῖον ἡγησάμην μνησθῆναι τῶν ὀνομάτων."},{"number":370,"text":"Ὡς δʼ ἕκαστα τούτων κατὰ τὸν προειρημένον διέταξε τρόπον, εἰς ἐκκλησίαν συγκαλέσας τοὺς ἄρχοντας τῶν Ἑβραίων καὶ τοὺς φυλάρχους καὶ τοὺς ἡγεμόνας τῶν διαιρέσεων καὶ τοὺς ἐπὶ πάσης πράξεως ἢ κτήσεως τοῦ βασιλέως τεταγμένους, στὰς ἐφʼ ὑψηλοτάτου βήματος ὁ βασιλεὺς ἔλεξε πρὸς τὸ πλῆθος·"},{"number":371,"text":"ἀδελφοὶ καὶ ὁμοεθνεῖς, γινώσκειν ὑμᾶς βούλομαι, ὅτι ναὸν οἰκοδομῆσαι τῷ θεῷ διανοηθεὶς χρυσόν τε πολὺν παρεσκευασάμην καὶ ἀργύρου ταλάντων μυριάδας δέκα, ὁ δὲ θεὸς ἐκώλυσέ με διὰ τοῦ προφήτου Νάθα διά τε τοὺς ὑπὲρ ὑμῶν πολέμους καὶ τῷ φόνῳ τῶν ἐχθρῶν μεμιάνθαι τὴν δεξιάν, τὸν δὲ υἱὸν ἐκέλευσε τὸν διαδεξόμενον τὴν βασιλείαν κατασκευάσαι τὸν ναὸν αὐτῷ."},{"number":372,"text":"νῦν οὖν ἐπεὶ καὶ τῷ προγόνῳ ἡμῶν Ἰακώβῳ δυοκαίδεκα παίδων γενομένων ἴστε τὸν Ἰούδαν ἀποδειχθέντα βασιλέα, καὶ ἐμὲ τῶν ἀδελφῶν ἓξ ὄντων προκριθέντα καὶ τὴν ἡγεμονίαν λαβόντα παρὰ τοῦ θεοῦ καὶ μηδένα τούτων δυσχεράναντα, οὕτως ἀξιῶ κἀγὼ τοὺς ἐμαυτοῦ παῖδας μὴ στασιάζειν πρὸς ἀλλήλους Σολόμωνος τὴν βασιλείαν παρειληφότος, ἀλλʼ ἐπισταμένους ὡς ὁ θεὸς αὐτὸν ἐξελέξατο φέρειν ἡδέως αὐτὸν δεσπότην."},{"number":373,"text":"οὐ δεινὸν γὰρ θεοῦ θέλοντος οὐδʼ ἀλλοτρίῳ κρατοῦντι δουλεύειν, χαίρειν δʼ ἐπʼ ἀδελφῷ ταύτης τυχόντι τῆς τιμῆς προσῆκεν ὡς κοινωνοῦντας αὐτῆς. εὔχομαι δὴ τὰς ὑποσχέσεις τοῦ θεοῦ παρελθεῖν εἰς τέλος καὶ τὴν εὐδαιμονίαν ταύτην ἀνὰ πᾶσαν τὴν χώραν σπαρῆναι καὶ τὸν ἅπαντα ταύτῃ παραμεῖναι χρόνον, ἣν αὐτὸς ἐπηγγείλατο παρέξειν ἐπὶ Σολόμωνος βασιλέως."},{"number":374,"text":"ἔσται δὲ ταῦτα βέβαια καὶ καλὸν ἕξει πέρας, ἂν εὐσεβῆ καὶ δίκαιον αὑτὸν καὶ φύλακα τῶν πατρίων παρέχῃς νόμων, ὦ τέκνον· εἰ δὲ μή, τὰ χείρω προσδοκάτω ταῦτα παραβαίνων."},{"number":375,"text":"Ὁ μὲν οὖν βασιλεὺς τούτους ποιησάμενος τοὺς λόγους ἐπαύσατο, τήν τε διαγραφὴν καὶ διάταξιν τῆς οἰκοδομίας τοῦ ναοῦ πάντων ὁρώντων ἔδωκε Σολόμωνι θεμελίων καὶ οἴκων καὶ ὑπερῴων, ὅσοι τε τὸ πλῆθος καὶ πηλίκοι τὸ ὕψος καὶ εὖρος γένοιντο, ὅσα τε σκεύη χρυσᾶ καὶ ἀργυρᾶ τούτων τὸν σταθμὸν ὥρισε."},{"number":376,"text":"προσπαρώρμησε δὲ καὶ λόγοις αὐτόν τε πάσῃ χρήσασθαι προθυμίᾳ περὶ τὸ ἔργον καὶ τοὺς ἄρχοντας καὶ τὴν Ληουιτῶν φυλὴν συναγωνίσασθαι διά τε τὴν ἡλικίαν καὶ διὰ τὸ τὸν θεὸν ἐκεῖνον ἑλέσθαι καὶ τῆς οἰκοδομίας τοῦ ναοῦ καὶ τῆς βασιλείας προστάτην."},{"number":377,"text":"εὐμαρῆ δʼ αὐτοῖς καὶ οὐ σφόδρα ἐπίπονον τὴν οἰκοδομίαν ἀπέφαινεν αὐτοῦ μὲν πολλὰ τάλαντα χρυσοῦ πλείω δʼ ἀργύρου καὶ ξύλα καὶ τεκτόνων πλῆθος καὶ λατόμων ἤδη παρεσκευασμένου σμαράγδου τε καὶ πάσης ἰδέας λίθου πολυτελοῦς·"},{"number":378,"text":"καὶ νῦν δʼ ἔτι τῆς ἰδίας ἀπαρχὴν διακονίας ἄλλα τρισχίλια τάλαντα χρυσοῦ καθαροῦ παρέξειν ἔλεγεν εἰς τὸ ἄδυτον καὶ εἰς τὸ ἅρμα τοῦ θεοῦ τοὺς Χερουβεῖς, οὓς ἐφεστάναι δεήσει τὴν κιβωτὸν καλύπτοντας. σιωπήσαντος δὲ τοῦ Δαυίδου πολλὴ καὶ τῶν ἀρχόντων καὶ τῶν ἱερέων καὶ τῆς Ληουίτιδος φυλῆς προθυμία συμβαλλομένων καὶ ποιουμένων ἐπαγγελίας λαμπρὰς καὶ μεγαλοπρεπεῖς ἐγένετο·"},{"number":379,"text":"χρυσοῦ μὲν γὰρ ὑπέστησαν εἰσοίσειν τάλαντα πεντακισχίλια καὶ στατῆρας μυρίους, ἀργυρίου δὲ μύρια τάλαντα, καὶ σιδήρου μυριάδας ταλάντων πολλάς· καὶ εἴ τινι λίθος ἦν πολυτελὴς ἐκόμισε καὶ παρέδωκεν εἰς τοὺς θησαυρούς, ὧν ἐπετρόπευεν ὁ Μωυσέος ἔκγονος Ἴαλος."},{"number":380,"text":"Ἐπὶ τούτοις ἥσθη τε ὁ λαὸς ἅπας καὶ Δαυίδης τὴν σπουδὴν καὶ τὴν φιλοτιμίαν τῶν ἀρχόντων καὶ ἱερέων καὶ τῶν ἄλλων ἁπάντων ὁρῶν τὸν θεὸν εὐλογεῖν ἤρξατο μεγάλῃ βοῇ πατέρα τε καὶ γένεσιν τῶν ὅλων ἀποκαλῶν καὶ δημιουργὸν ἀνθρωπίνων καὶ θείων, οἷς αὑτὸν ἐκόσμησε, προστάτην τε καὶ κηδεμόνα γένους τῶν Ἑβραίων καὶ τῆς τούτων εὐδαιμονίας ἧς τε αὐτῷ βασιλείας ἔδωκεν."},{"number":381,"text":"ἐπὶ τούτοις εὐξάμενος τῷ τε παντὶ λαῷ τὰ ἀγαθὰ καὶ τῷ παιδὶ Σολόμωνι διάνοιαν ὑγιῆ καὶ δικαίαν καὶ πᾶσι τοῖς τῆς ἀρετῆς μέρεσιν ἐρρωμένην ἐκέλευσε καὶ τὸ πλῆθος εὐλογεῖν τὸν θεόν. καὶ οἱ μὲν πεσόντες ἐπὶ τὴν γῆν προσεκύνησαν, εὐχαρίστησαν δὲ καὶ Δαυίδῃ περὶ πάντων ὧν αὐτοῦ τὴν βασιλείαν παραλαβόντος ἀπέλαυσαν."},{"number":382,"text":"τῇ δʼ ἐπιούσῃ θυσίας τῷ θεῷ παρέστησαν μόσχους χιλίους καὶ κριοὺς τοσούτους καὶ χιλίους ἀμνούς, οὓς ὡλοκαύτωσαν· ἔθυσαν δὲ καὶ τὰς εἰρηνικὰς θυσίας πολλὰς μυριάδας ἱερείων κατασφάξαντες. καὶ διʼ ὅλης τῆς ἡμέρας ἑώρτασεν ὁ βασιλεὺς σὺν παντὶ τῷ λαῷ, καὶ Σολόμωνα δεύτερον ἔχρισαν τῷ ἐλαίῳ καὶ ἀπέδειξαν αὐτὸν βασιλέα καὶ Σάδωκον ἀρχιερέα τῆς πληθύος ἁπάσης. εἴς τε τὸ βασίλειον ἀγαγόντες Σολόμωνα καὶ καθίσαντες αὐτὸν ἐπὶ θρόνου τοῦ πατρῴου ἀπʼ ἐκείνης τῆς ἡμέρας ὑπήκουον αὐτῷ."}],"15":[{"number":383,"text":"Μετʼ ὀλίγον δὲ χρόνον ὁ Δαυίδης καταπεσὼν εἰς νόσον ὑπὸ γήρως καὶ συνειδὼς ὅτι μέλλει τελευτᾶν καλέσας τὸν υἱὸν Σολόμωνα διελέχθη πρὸς αὐτὸν τοιάδε· ἐγὼ μέν, ὦ τέκνον, εἰς τὸ χρεὼν ἤδη καὶ πατέρας τοὺς ἐμοὺς ἀπαλλάσσομαι κοινὴν ὁδὸν ἁπάντων τῶν τε νῦν ὄντων καὶ τῶν ἐσομένων πορευόμενος, ἐξ ἧς οὐκέτι οἷόν τε ἐπανελθόντα γνῶναι, τί κατὰ τὸν βίον πράττεται."},{"number":384,"text":"διὸ ζῶν ἔτι καὶ πρὸς αὐτῷ γεγονὼς τῷ τελευτᾶν παραινῶ σοι ταῦθʼ ἃ καὶ πρότερον ἔφθην συμβουλεύσας, δικαίῳ μὲν εἶναι πρὸς τοὺς ἀρχομένους, εὐσεβεῖ δὲ πρὸς τὸν τὴν βασιλείαν δεδωκότα θεόν, φυλάττειν δʼ αὐτοῦ τὰς ἐντολὰς καὶ τοὺς νόμους, οὓς αὐτὸς διὰ Μωυσέος κατέπεμψεν ἡμῖν, καὶ μήτε χάριτι μήτε θωπείᾳ μήτʼ ἐπιθυμίᾳ μήτε ἄλλῳ πάθει προστιθέμενον τούτων ἀμελῆσαι·"},{"number":385,"text":"τὴν γὰρ τοῦ θείου πρὸς σαυτὸν εὔνοιαν ἀπολεῖς παραβάς τι τῶν νομίμων καὶ πρὸς ἅπαντʼ αὐτοῦ τὴν ἀγαθὴν ἀποστρέψεις πρόνοιαν· τοιοῦτον δὲ σεαυτὸν παρέχων, ὁποῖον εἶναί τε δεῖ κἀγὼ δὲ παρακαλῶ, καθέξεις ἡμῶν τὴν βασιλείαν τῷ γένει καὶ οἶκος ἄλλος Ἑβραίων οὐκ ἂν δεσπόσειεν, ἀλλʼ ἡμεῖς αὐτοὶ διὰ τοῦ παντὸς αἰῶνος."},{"number":386,"text":"μέμνησο δὲ καὶ τῆς Ἰωάβου τοῦ στρατηγοῦ παρανομίας ἀποκτείναντος διὰ ζηλοτυπίαν δύο στρατηγοὺς δικαίους καὶ ἀγαθούς, Ἀβεννῆρόν τε τὸν Νήρου παῖδα καὶ τὸν Ἀμασὰν υἱὸν Ἰέθρα· ὧν ὅπως ἄν σοι δόξῃ τὸν θάνατον ἐκδίκησον, ἐπεὶ καὶ κρείττων ἐμοῦ καὶ δυνατώτερος ὁ Ἰώαβος ὢν μέχρι νῦν τὴν δίκην διέφυγε."},{"number":387,"text":"παρατίθεμαι δέ σοι καὶ τοὺς Βερζέλου τοῦ Γαλαδίτου παῖδας, οὓς ἐν τιμῇ πάσῃ καὶ προνοίᾳ τοῦτʼ ἐμοὶ χαριζόμενος ἕξεις· οὐ προκατάρχομεν γὰρ εὐποιίας, ἀλλʼ ἀμοιβὴν ὧν ὁ πατὴρ αὐτῶν παρὰ τὴν φυγὴν ὑπῆρξέ μοι χρεολυτοῦμεν."},{"number":388,"text":"καὶ τὸν Γήρα δὲ υἱὸν Σουμούιν τὸν ἐκ τῆς Βενιαμίτιδος φυλῆς, ὃς πολλὰ βλασφημήσας με παρὰ τὴν φυγήν, ὅτʼ εἰς Παρεμβολὰς ἐπορευόμην, ἀπήντησεν ἐπὶ τὸν Ἰόρδανον καὶ πίστεις ἔλαβεν ὡς μηδὲν αὐτὸν παθεῖν τότε, νῦν ἐπιζητήσας αἰτίαν εὔλογον ἄμυνε."},{"number":389,"text":"Ταῦτα παραινέσας τῷ παιδὶ περί τε τῶν ὅλων πραγμάτων καὶ περὶ τῶν φίλων καὶ οὓς ᾔδει τιμωρίας ἀξίους γεγενημένους ἀπέθανεν, ἔτη μὲν βιώσας ἑβδομήκοντα, βασιλεύσας δὲ ἑπτὰ μὲν ἐν Χεβρῶνι τῆς Ἰούδα φυλῆς καὶ μῆνας ἕξ, ἐν Ἱεροσολύμοις δὲ ἁπάσης τῆς χώρας τρία καὶ τριάκοντα."},{"number":390,"text":"οὕτως ἀρίστῳ ἀνδρὶ γεγενημένῳ καὶ πᾶσαν ἀρετὴν ἔχοντι καὶ τοσούτων ἐθνῶν σωτηρίαν ἐγκεχειρισμένῳ βασιλεῖ ἔδει προσεπαινέσαι καὶ τό τε τῆς δυνάμεως αὐτοῦ εὐσθενὲς καὶ τὸ τῆς σωφροσύνης συνετόν· ἀνδρεῖος γὰρ ἦν, ὡς οὐκ ἄλλος τις, ἐν δὲ τοῖς ὑπὲρ τῶν ὑπηκόων ἀγῶσι πρῶτος ἐπὶ τοὺς κινδύνους ὥρμα, τῷ πονεῖν καὶ μάχεσθαι παρακελευόμενος τοὺς στρατιώτας ἐπὶ τὰς παρατάξεις ἀλλʼ οὐχὶ τῷ προστάττειν ὡς δεσπότης,"},{"number":391,"text":"νοῆσαί τε καὶ συνιδεῖν καὶ περὶ τῶν μελλόντων καὶ τῆς τῶν ἐνεστηκότων οἰκονομίας ἱκανώτατος, σώφρων ἐπιεικὴς χρηστὸς πρὸς τοὺς ἐν συμφοραῖς ὑπάρχοντας δίκαιος φιλάνθρωπος, ἃ μόνοις δικαιότατα βασιλεῦσιν εἶναι προσῆκε, μηδὲν ὅλως παρὰ τοσοῦτο μέγεθος ἐξουσίας ἁμαρτὼν ἢ τὸ περὶ τὴν Οὐρία γυναῖκα. κατέλιπε δὲ καὶ πλοῦτον ὅσον οὐκ ἄλλος βασιλεὺς οὔθʼ Ἑβραίων οὔτʼ ἄλλων ἐθνῶν."},{"number":392,"text":"Ἔθαψε δὲ αὐτὸν ὁ παῖς Σολόμων ἐν Ἱεροσολύμοις διαπρεπῶς τοῖς τε ἄλλοις οἷς περὶ κηδείαν νομίζεται βασιλικὴν ἅπασι καὶ δὴ καὶ πλοῦτον αὐτῷ πολὺν καὶ ἄφθονον συνεκήδευσεν, ὧν τὴν ὑπερβολὴν τεκμήραιτʼ ἄν τις ῥᾳδίως ἐκ τοῦ λεχθησομένου·"},{"number":393,"text":"μετὰ γὰρ χρόνον ἐτῶν χιλίων καὶ τριακοσίων Ὑρκανὸς ὁ ἀρχιερεὺς πολιορκούμενος ὑπʼ Ἀντιόχου τοῦ Εὐσεβοῦς ἐπικληθέντος υἱοῦ δὲ Δημητρίου, βουλόμενος χρήματʼ αὐτῷ δοῦναι ὑπὲρ τοῦ λῦσαι τὴν πολιορκίαν καὶ τὴν στρατιὰν ἀπαγαγεῖν καὶ ἀλλαχόθεν οὐκ εὐπορῶν, ἀνοίξας ἕνα οἶκον τῶν ἐν τῷ Δαυίδου μνήματι καὶ βαστάσας τρισχίλια τάλαντα μέρος ἔδωκεν Ἀντιόχῳ καὶ διέλυσεν οὕτως τὴν πολιορκίαν, καθὼς καὶ ἐν ἄλλοις δεδηλώκαμεν."},{"number":394,"text":"μετὰ δὲ τοῦτο ἐτῶν πολλῶν διαγενομένων πάλιν ὁ βασιλεὺς Ἡρώδης ἕτερον ἀνοίξας οἶκον ἀνείλετο χρήματα πολλά. ταῖς μέντοι γε θήκαις τῶν βασιλέων οὐδεὶς αὐτῶν ἐπέτυχεν· ἦσαν γὰρ ὑπὸ τὴν γῆν μηχανικῶς κεκηδευμέναι πρὸς τὸ μὴ φανεραὶ εἶναι τοῖς εἰς τὸ μνῆμα εἰσιοῦσιν. ἀλλὰ περὶ μὲν τούτων ἡμῖν τοσοῦτον ἀπόχρη δεδηλῶσθαι."}]},"count":394};a[8]={"book":8,"title":"Τάδε ἔνεστιν ἐν τῇ ὀγδόῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ὡς Σολόμων τὴν βασιλείαν παραλαβὼν τοὺς ἐχθροὺς ἀνεῖλε.\n\nβ. περὶ τῆς σοφίας αὐτοῦ καὶ συνέσεως καὶ τοῦ πλούτου.\n\nγ. ὅτι πρῶτος τὸν ἐν Ἱεροσολύμοις ναὸν ᾠκοδόμησεν.\n\nδ. ὡς τελευτήσαντος Σολόμωνος ὁ λαὸς ἀποστὰς τοῦ παιδὸς αὐτοῦ Ῥοβοάμου τῶν δέκα φυλῶν τῶν ὑπηκόων τινὰ Ἱεροβόαμον ἀπέδειξε βασιλέα, τῶν δὲ δύο φυλῶν ὁ υἱὸς αὐτοῦ ἐβασίλευσεν.\n\nε. ὡς Ἴσακος Αἰγυπτίων βασιλεὺς στρατευσάμενος ἐπὶ τὰ Ἱεροσόλυμα καὶ κατασχὼν τὴν πόλιν τὸν πλοῦτον αὐτῆς εἰς Αἴγυπτον μετήνεγκε.\n\nϛ. στρατεία Ἱεροβοάμου τοῦ τῶν Ἰσραηλιτῶν βασιλέως ἐπὶ τὸν υἱὸν τὸν Ῥοβοάμου καὶ ἧττα.\n\nζ. ὅτι τὴν Ἱεροβοάμου γενεὰν Βασίνης τις ὄνομα διαφθείρας αὐτὸς τὴν βασιλείαν ἔσχεν.\n\nη. Αἰθιόπων ἐπιστρατεία τοῖς Ἱεροσολύμοις βασιλεύοντος αὐτῶν Ἀσάνου τοῦ Ἀβία παιδός, καὶ διαφθορὰ τοῦ στρατοῦ.\n\nθ. ὡς τῆς Ἀβεσσάρου γενεᾶς διαφθαρείσης ἐβασίλευσε τῶν Ἰσραηλιτῶν Ἄμαρις καὶ ὁ υἱὸς αὐτοῦ Ἄχαβος.\n\nι. ὡς Ἄδαδος Δαμασκοῦ καὶ Συρίας βασιλεὺς δὶς ἐπ' Ἄχαβον στρατευσάμενος ἡττήθη.\n\nια. Ἀμμανιτῶν καὶ Μωαβιτῶν στρατευσαμένων ἐπ' Ἰωσαφάτην τὸν Ἱεροσολύμων βασιλέα ἧττα.\n\nιβ. ὡς Ἄχαβος ἐπὶ Σύρους στρατευσάμενος ἡττήθη τῇ μάχῃ καὶ αὐτὸς ἀπώλετο.\n\nπεριέχει ἡ βίβλος αὕτη ἔτη ἑκατὸν ἑξήκοντα καὶ τρία."},"chapters":{"1":[{"number":1,"text":"Περὶ μὲν οὖν Δαυίδου καὶ τῆς ἀρετῆς αὐτοῦ καὶ ὅσων ἀγαθῶν αἴτιος γενόμενος τοῖς ὁμοφύλοις πολέμους τε καὶ μάχας ὅσας κατορθώσας γηραιὸς ἐτελεύτησεν, ἐν τῇ πρὸ ταύτης βίβλῳ δεδηλώκαμεν."},{"number":2,"text":"Σολόμωνος δὲ τοῦ παιδὸς αὐτοῦ νέου τὴν ἡλικίαν ἔτι ὄντος τὴν βασιλείαν παραλαβόντος, ὃν ἔτι ζῶν ἀπέφηνε τοῦ λαοῦ δεσπότην κατὰ τὴν τοῦ θεοῦ βούλησιν, καθίσαντος ἐπὶ τὸν θρόνον ὁ μὲν πᾶς ὄχλος ἐπευφήμησεν, οἷον εἰκὸς ἐπʼ ἀρχομένῳ βασιλεῖ, τελευτῆσαι καλῶς αὐτῷ τὰ πράγματα καὶ πρὸς γῆρας ἀφικέσθαι λιπαρὸν καὶ πανεύδαιμον τὴν ἡγεμονίαν."},{"number":3,"text":"Ἀδωνίας δέ, ὃς καὶ τοῦ πατρὸς ἔτι ζῶντος ἐπεχείρησε τὴν ἀρχὴν κατασχεῖν, παρελθὼν πρὸς τὴν τοῦ βασιλέως μητέρα Βερσάβην καὶ φιλοφρόνως αὐτὴν ἀσπασάμενος, πυθομένης εἰ καὶ διὰ χρείαν τινὰ πρὸς αὐτὴν ἀφῖκται καὶ δηλοῦν κελευούσης ὡς ἡδέως παρεξομένης ἤρξατο λέγειν,"},{"number":4,"text":"ὅτι γινώσκει μὲν τὴν βασιλείαν καὶ αὐτὴ καὶ διὰ τὴν ἡλικίαν καὶ διὰ τὴν τοῦ πλήθους προαίρεσιν οὖσαν αὐτοῦ, μεταβάσης δὲ πρὸς Σολόμωνα τὸν υἱὸν αὐτῆς κατὰ τὴν τοῦ θεοῦ γνώμην στέργει καὶ ἀγαπᾷ τὴν ὑπʼ αὐτῷ δουλείαν καὶ τοῖς παροῦσιν ἥδεται πράγμασιν."},{"number":5,"text":"ἐδεῖτο δʼ οὖν διακονῆσαι πρὸς τὸν ἀδελφὸν αὐτῷ καὶ πεῖσαι δοῦναι τὴν τῷ πατρὶ συγκοιμωμένην πρὸς γάμον αὐτῷ Ἀβισάκην· οὐ γὰρ πλησιάσαι τὸν πατέρα διὰ τὸ γῆρας αὐτῇ, μένειν δʼ ἔτι παρθένον."},{"number":6,"text":"ἡ δὲ Βερσάβη καὶ διακονήσειν σπουδαίως ὑπέσχετο καὶ καταπράξεσθαι τὸν γάμον διʼ ἀμφότερα, τοῦ τε βασιλέως αὐτῷ χαρίσασθαί τι βουλησομένου καὶ δεησομένης αὐτῆς λιπαρῶς. καὶ ὁ μὲν εὔελπις ἀπαλλάττεται περὶ τοῦ γάμου, ἡ δὲ τοῦ Σολόμωνος μήτηρ εὐθὺς ὥρμησεν ἐπὶ τὸν υἱὸν διαλεξομένη περὶ ὧν Ἀδωνίᾳ δεηθέντι κατεπηγγείλατο."},{"number":7,"text":"καὶ προϋπαντήσαντος αὐτῇ τοῦ παιδὸς καὶ περιπλακέντος, ἐπεὶ παρήγαγεν εἰς τὸν οἶκον, οὗ συνέβαινεν αὐτῷ κεῖσθαι τὸν βασιλικὸν θρόνον, καθίσας ἐκέλευσεν ἕτερον ἐκ δεξιῶν τεθῆναι τῇ μητρί. καθεσθεῖσα δʼ ἡ Βερσάβη μίαν, εἶπεν, ὦ παῖ, χάριν αἰτουμένῃ κατάνευσον καὶ μηδὲν ἐξ ἀρνήσεως δύσκολον μηδὲ σκυθρωπὸν ἀπεργάσῃ. τοῦ δὲ Σολόμωνος προστάττειν κελεύοντος,"},{"number":8,"text":"πάντα γὰρ ὅσιον εἶναι μητρὶ παρέχειν, καί τι προσμεμψαμένου τὴν ἀρχήν, ὅτι μὴ μετʼ ἐλπίδος ἤδη βεβαίας τοῦ τυχεῖν ὧν ἀξιοῖ ποιεῖται τοὺς λόγους ἀλλʼ ἄρνησιν ὑφορωμένη, δοῦναι τὴν παρθένον αὐτὸν Ἀβισάκην Ἀδωνίᾳ τἀδελφῷ πρὸς γάμον παρεκάλει."},{"number":9,"text":"Λαβὼν δὲ πρὸς ὀργὴν ὁ βασιλεὺς τὸν λόγον ἀποπέμπεται μὲν τὴν μητέρα μειζόνων ὀρέγεσθαι πραγμάτων εἰπὼν Ἀδωνίαν καὶ θαυμάζειν, πῶς οὐ παραχωρῆσαι καὶ τῆς βασιλείας ὡς πρεσβυτέρῳ παρακαλεῖ τὸν γάμον αὐτῷ τὸν Ἀβισάκης αἰτουμένη φίλους ἔχοντι δυνατοὺς Ἰώαβον τὸν στρατηγὸν καὶ Ἀβιάθαρον τὸν ἱερέα, μεταπεμψάμενος δὲ Βαναίαν τὸν ἐπὶ τῶν σωματοφυλάκων ἀποκτεῖναι προσέταξεν αὐτῷ τὸν ἀδελφὸν Ἀδωνίαν."},{"number":10,"text":"καλέσας δὲ τὸν Ἀβιάθαρον τὸν ἱερέα θανάτου μέν, εἶπε, ῥύεταί σε τά τε ἄλλα ὅσα τῷ πατρὶ συνέκαμες καὶ ἡ κιβωτός, ἣν σὺν αὐτῷ μετήνεγκας. ταύτην δέ σοι τὴν τιμωρίαν ἐπιτίθημι ταξαμένῳ μετὰ Ἀδωνία καὶ τὰ ἐκείνου φρονήσαντι· μήτε ἐνθάδε ἴσθι μήτε εἰς ὄψιν ἀπάντα τὴν ἐμήν, ἀλλʼ εἰς τὴν πατρίδα πορευθεὶς ἐν τοῖς ἀγροῖς ζῆθι καὶ τοῦτον ἄχρι τελευτῆς ἔχε τὸν βίον ἁμαρτὼν τοῦ μηκέτʼ εἶναι δικαίως ἐν ἀξίᾳ."},{"number":11,"text":"καταλύεται μὲν οὖν ἀπὸ τῆς ἱερατικῆς τιμῆς ὁ Ἰθαμάρου οἶκος διὰ τὴν προειρημένην αἰτίαν, καθὼς καὶ τῷ Ἀβιαθάρου πάππῳ προεῖπεν ὁ θεὸς Ἠλεί, μετέβη δʼ εἰς τὸ Φιναάσου γένος πρὸς Σάδωκον."},{"number":12,"text":"οἱ δὲ ἰδιωτεύσαντες ἐκ τοῦ Φιναάσου γένους καθʼ ὃν καιρὸν εἰς τὸν Ἰθαμάρου οἶκον ἡ ἀρχιερωσύνη μετῆλθεν Ἠλεὶ πρώτου ταύτην παραλαβόντος ἦσαν οὗτοι· ὁ τοῦ ἀρχιερέως Ἰησοῦ υἱὸς Βοκίας, τούτου δὲ Ἰώθαμος, Ἰωθάμου δὲ Μαραίωθος, Μαραιώθου δὲ Ἀροφαῖος, Ἀροφαίου δὲ Ἀχίτωβος, Ἀχιτώβου δὲ Σάδωκος, ὃς πρῶτος ἐπὶ Δαυίδου τοῦ βασιλέως ἀρχιερεὺς ἐγένετο."},{"number":13,"text":"Ἰώαβος δὲ ὁ στρατηγὸς τὴν ἀναίρεσιν ἀκούσας Ἀδωνία περιδεὴς ἐγένετο, φίλος γὰρ ἦν αὐτῷ μᾶλλον ἢ τῷ βασιλεῖ Σολόμωνι, καὶ κίνδυνον ἐκ τούτου διὰ τὴν πρὸς ἐκεῖνον εὔνοιαν οὐκ ἀλόγως ὑποπτεύων καταφεύγει μὲν ἐπὶ τὸ θυσιαστήριον, ἀσφάλειαν δὲ ἐνόμιζεν αὑτῷ ποριεῖν ἐκ τῆς πρὸς τὸν θεὸν εὐσεβείας τοῦ βασιλέως."},{"number":14,"text":"ὁ δὲ ἀπαγγειλάντων αὐτῷ τινων τὴν Ἰωάβου γνώμην πέμψας Βαναίαν ἐκέλευσεν ἀναστήσαντα ἄγειν ἐπὶ τὸ δικαστήριον ὡς ἀπολογησόμενον. Ἰώαβος δὲ οὐκ ἔφη καταλείψειν τὸ ἱερόν, ἀλλʼ αὐτοῦ τεθνήξεσθαι μᾶλλον ἢ ἐν ἑτέρῳ χωρίῳ."},{"number":15,"text":"Βαναίου δὲ τὴν ἀπόκρισιν αὐτοῦ τῷ βασιλεῖ δηλώσαντος προσέταξεν ὁ Σολόμων ἐκεῖ τὴν κεφαλὴν αὐτοῦ ἀποτεμεῖν, καθὼς βούλεται, καὶ ταύτην λαβεῖν τὴν δίκην ὑπὲρ τῶν δύο στρατηγῶν, οὓς ὁ Ἰώαβος ἀνοσίως ἀπέκτεινε, θάψαι δʼ αὐτοῦ τὸ σῶμα, ὅπως τὰ μὲν ἁμαρτήματα μηδέποτε καταλείπῃ τὸ γένος τὸ ἐκείνου, τῆς δὲ Ἰωάβου τελευτῆς αὐτός τε καὶ ὁ πατὴρ ἀθῷοι τυγχάνωσι."},{"number":16,"text":"καὶ Βαναίας μὲν τὰ κελευσθέντα ποιήσας αὐτὸς ἀποδείκνυται στρατηγὸς πάσης τῆς δυνάμεως, Σάδωκον δὲ ποιεῖ μόνον ἀρχιερέα ὁ βασιλεὺς εἰς τὸν Ἀβιαθάρου τόπον, ὃν μετεστήσατο."},{"number":17,"text":"Σουμουίσῳ δὲ προσέταξεν οἰκίαν οἰκοδομήσαντι μένειν ἐν Ἱεροσολύμοις αὐτῷ προσεδρεύοντι καὶ μὴ διαβαίνειν τὸν χειμάρρουν Κεδρῶνα ἔχειν ἐξουσίαν, παρακούσαντι δὲ τούτων θάνατον ἔσεσθαι τὸ πρόστιμον. τῷ δὲ μεγέθει τῆς ἀπειλῆς καὶ ὅρκους αὐτῷ προσηνάγκασε ποιήσασθαι."},{"number":18,"text":"Σουμούισος δὲ χαίρειν οἷς προσέταξεν αὐτῷ Σολόμων φήσας καὶ ταῦτα ποιήσειν προσομόσας καταλιπὼν τὴν πατρίδα τὴν διατριβὴν ἐν τοῖς Ἱεροσολύμοις ἐποιεῖτο. διελθόντων δὲ τριῶν ἐτῶν ἀκούσας δύο δούλους ἀποδράντας αὐτὸν ἐν Γίττῃ τυγχάνοντας ὥρμησεν ἐπὶ τοὺς οἰκέτας."},{"number":19,"text":"ἐπανελθόντος δὲ μετʼ αὐτῶν ὁ βασιλεὺς αἰσθόμενος, ὡς καὶ τῶν ἐντολῶν αὐτοῦ καταφρονήσαντος καὶ τὸ μεῖζον τῶν ὅρκων τοῦ θεοῦ μηδεμίαν ποιησαμένου φροντίδα, χαλεπῶς εἶχε καὶ καλέσας αὐτόν οὐ σύ, φησίν, ὤμοσας μὴ καταλείψειν ἐμὲ μηδʼ ἐξελεύσεσθαί ποτʼ ἐκ ταύτης τῆς πόλεως εἰς ἄλλην;"},{"number":20,"text":"οὔκουν ἀποδράσῃ τὴν τῆς ἐπιορκίας δίκην, ἀλλὰ καὶ ταύτης καὶ ὧν τὸν πατέρα μου παρὰ τὴν φυγὴν ὕβρισας τιμωρήσομαί σε πονηρὸν γενόμενον, ἵνα γνῷς ὅτι κερδαίνουσι μὲν οὐδὲν οἱ κακοὶ μὴ παρʼ αὐτὰ τἀδικήματα κολασθέντες, ἀλλὰ παντὶ τῷ χρόνῳ ᾧ νομίζουσιν ἀδεεῖς εἶναι μηδὲν πεπονθότες αὔξεται καὶ γίνεται μείζων ἡ κόλασις αὐτοῖς ἧς ἂν παραυτίκα πλημμελήσαντες ἔδοσαν. καὶ Σουμούισον μὲν κελευσθεὶς Βαναίας ἀπέκτεινεν."}],"2":[{"number":21,"text":"Ἤδη δὲ τὴν βασιλείαν βεβαίως ἔχων Σολόμων καὶ τῶν ἐχθρῶν κεκολασμένων ἄγεται τὴν Φαραώθου τοῦ τῶν Αἰγυπτίων βασιλέως θυγατέρα· καὶ κατασκευάσας τὰ τείχη τῶν Ἱεροσολύμων πολλῷ μείζω καὶ ὀχυρώτερα τῶν πρόσθεν ὄντων διεῖπε τὰ πράγματα λοιπὸν ἐπὶ πολλῆς εἰρήνης μηδʼ ὑπὸ τῆς νεότητος πρός τε δικαιοσύνην καὶ φυλακὴν τῶν νόμων καὶ μνήμην ὧν ὁ πατὴρ τελευτῶν ἐπέστειλε βλαπτόμενος, ἀλλὰ πάνθʼ ὅσα οἱ τοῖς χρόνοις προβεβηκότες καὶ πρὸς τὸ φρονεῖν ἀκμάζοντες μετὰ πολλῆς ἀκριβείας ἐπιτελῶν."},{"number":22,"text":"ἔγνω δʼ εἰς Γιβρῶνα παραγενόμενος ἐπὶ τοῦ χαλκέου θυσιαστηρίου τοῦ κατασκευασθέντος ὑπὸ Μουσείου θῦσαι τῷ θεῷ καὶ χίλια τὸν ἀριθμὸν ὡλοκαύτωσεν ἱερεῖα. τοῦτο δὲ ποιήσας μεγάλως ἔδοξε τὸν θεὸν τετιμηκέναι· φανεὶς γὰρ αὐτῷ κατὰ τοὺς ὕπνους ἐκείνης τῆς νυκτὸς ἐκέλευσεν αἱρεῖσθαι, τίνας ἀντὶ τῆς εὐσεβείας παράσχῃ δωρεὰς αὐτῷ."},{"number":23,"text":"Σολόμων δὲ τὰ κάλλιστα καὶ μέγιστα καὶ θεῷ παρασχεῖν ἥδιστα καὶ λαβεῖν ἀνθρώπῳ συμφορώτατα τὸν θεὸν ᾔτησεν· οὐ γὰρ χρυσὸν οὐδʼ ἄργυρον οὐδὲ τὸν ἄλλον πλοῦτον ὡς ἄνθρωπος καὶ νέος ἠξίωσεν αὑτῷ προσγενέσθαι, ταῦτα γὰρ σχεδὸν νενόμισται παρὰ τοῖς πλείστοις μόνα σπουδῆς ἄξια καὶ θεοῦ δῶρα εἶναι, ἀλλὰ δός μοι φησί, δέσποτα, νοῦν ὑγιῆ καὶ φρόνησιν ἀγαθήν, οἷς ἂν τὸν λαὸν τἀληθῆ καὶ τὰ δίκαια λαβὼν κρίνοιμι."},{"number":24,"text":"τούτοις ἥσθη τοῖς αἰτήμασιν ὁ θεὸς καὶ τά τε ἄλλα πάνθʼ ὧν οὐκ ἐμνήσθη παρὰ τὴν ἐκλογὴν δώσειν ἐπηγγείλατο πλοῦτον δόξαν νίκην πολεμίων, καὶ πρὸ πάντων σύνεσιν καὶ σοφίαν οἵαν οὐκ ἄλλος τις ἀνθρώπων ἔσχεν οὔτε βασιλέων οὔτʼ ἰδιωτῶν, φυλάξειν τε καὶ τοῖς ἐκγόνοις αὐτοῦ τὴν βασιλείαν ἐπὶ πλεῖστον ὑπισχνεῖτο χρόνον, ἂν δίκαιός τε ὢν διαμένῃ καὶ πειθόμενος αὐτῷ καὶ τὸν πατέρα μιμούμενος ἐν οἷς ἦν ἄριστος."},{"number":25,"text":"ταῦτα τοῦ θεοῦ Σολόμων ἀκούσας ἀνεπήδησεν εὐθὺς ἐκ τῆς κοίτης καὶ προσκυνήσας αὐτὸν ὑπέστρεψεν εἰς Ἱεροσόλυμα, καὶ πρὸ τῆς σκηνῆς μεγάλας ἐπιτελέσας θυσίας κατευωχεῖ τοὺς Ἰουδαίους ἅπαντας."},{"number":26,"text":"Ταύταις δὲ ταῖς ἡμέραις κρίσις ἐπʼ αὐτὸν ἤχθη δυσχερής, ἧς τὸ τέλος εὑρεῖν ἦν ἐπίπονον· τὸ δὲ πρᾶγμα περὶ οὗ συνέβαινεν εἶναι τὴν δίκην ἀναγκαῖον ἡγησάμην δηλῶσαι, ἵνα τοῖς ἐντυγχάνουσι τό τε δύσκολον τῆς κρίσεως γνώριμον ὑπάρξῃ, καὶ τοιούτων μεταξὺ πραγμάτων γενόμενοι λάβωσιν ὥσπερ ἐξ εἰκόνος τῆς τοῦ βασιλέως ἀγχινοίας τὸ ῥᾳδίως ἀποφαίνεσθαι περὶ τῶν ζητουμένων δυνηθῆναι."},{"number":27,"text":"δύο γυναῖκες ἑταῖραι τὸν βίον ἧκον ἐπʼ αὐτόν, ὧν ἡ ἀδικεῖσθαι δοκοῦσα πρώτη λέγειν ἤρξατο· οἰκῶ μέν, εἶπεν, ὦ βασιλεῦ, μετὰ ταύτης ἐν ἑνὶ δωματίῳ, συνέβη δʼ ἀμφοτέραις ἡμῖν ἐπὶ μιᾶς ἡμέρας ἀποτεκεῖν κατὰ τὴν αὐτὴν ὥραν ἄρρενα παιδία."},{"number":28,"text":"τρίτης δὲ ἡμέρας διελθούσης ἐπικοιμηθεῖσα τῷ αὑτῆς παιδίῳ αὕτη τοῦτο μὲν ἀποκτείνει, βαστάσασα δὲ τοὐμὸν ἐκ τῶν γονάτων πρὸς αὑτὴν μεταφέρει καὶ τὸ νεκρὸν ἐμοῦ κοιμωμένης εἰς τὰς ἀγκάλας μου τίθησι."},{"number":29,"text":"πρωῒ δὲ θηλὴν ὀρέξαι βουλομένη τῷ παιδίῳ τὸ μὲν ἐμὸν οὐχ εὗρον, τὸ δὲ ταύτης νεκρὸν ὁρῶ μοι παρακείμενον· ἀκριβῶς γὰρ κατανοήσασα τοῦτο ἐπέγνων· ὅθεν ἀπαιτῶ τὸν ἐμὸν υἱὸν καὶ οὐκ ἀπολαμβάνουσα καταπέφευγα, δέσποτα, ἐπὶ τὴν παρὰ σοῦ βοήθειαν· τῷ γὰρ εἶναι μόνας καὶ μηδένα τὸν ἐλέγξαι δυνάμενον φοβεῖσθαι καταφρονοῦσα ἰσχυρῶς ἀρνουμένη παραμένει."},{"number":30,"text":"ταῦτʼ εἰπούσης ὁ βασιλεὺς ἀνέκρινε τὴν ἑτέραν, τί τοῖς εἰρημένοις ἀντιλέγειν ἔχει. τῆς δὲ ἀρνουμένης τοῦτο πεποιηκέναι, τὸ δὲ παιδίον ζῆν τὸ αὑτῆς λεγούσης, τὸ δὲ τῆς ἀντιδίκου τεθνηκέναι, μηδενὸς ἐπινοοῦντος τὴν κρίσιν ἀλλʼ ὥσπερ ἐπʼ αἰνίγματι περὶ τὴν εὕρεσιν αὐτοῦ πάντων τῇ διανοίᾳ τετυφλωμένων μόνος ὁ βασιλεὺς ἐπενόησέ τι τοιοῦτον·"},{"number":31,"text":"κελεύσας κομισθῆναι καὶ τὸ νεκρὸν καὶ τὸ ζῶν παιδίον μεταπέμπεταί τινα τῶν σωματοφυλάκων καὶ σπασάμενον ἐκέλευσε τὴν μάχαιραν ἀμφότερα διχοτομῆσαι τὰ παιδία, ὅπως ἑκάτεραι λάβωσιν ἀνὰ ἥμισυ τοῦ τε ζῶντος καὶ τοῦ τετελευτηκότος."},{"number":32,"text":"ἐπὶ τούτῳ πᾶς μὲν ὁ λαὸς λανθάνων ἐχλεύαζεν ὡς μειράκιον τὸν βασιλέα, μεταξὺ δὲ τῆς μὲν ἀπαιτούσης καὶ ἀληθοῦς μητρὸς ἀνακραγούσης τοῦτο μὴ ποιεῖν ἀλλὰ παραδιδόναι τῇ ἑτέρᾳ τὸ παιδίον ὡς ἐκείνης, ἀρκεῖσθαι γὰρ τῷ ζῆν αὐτὸ καὶ βλέπειν μόνον κἂν ἀλλότριον δοκῇ, τῆς δʼ ἑτέρας ἑτοίμως ἐχούσης διαιρούμενον ἰδεῖν τὸ παιδίον καὶ προσέτι βασανισθῆναι καὶ αὐτὴν ἀξιούσης,"},{"number":33,"text":"ὁ βασιλεὺς ἐπιγνοὺς τὰς ἑκατέρων φωνὰς ἀπὸ τῆς ἀληθείας γεγενημένας τῇ μὲν ἀνακραγούσῃ τὸ παιδίον προσέκρινε, μητέρα γὰρ αὐτὴν ἀληθῶς εἶναι, τῆς δὲ ἄλλης κατέγνω πονηρίαν τό τε ἴδιον ἀποκτεινάσης καὶ τὸ τῆς φίλης σπουδαζούσης ἀπολλύμενον θεάσασθαι."},{"number":34,"text":"τοῦτο μέγα δεῖγμα καὶ τεκμήριον τῆς τοῦ βασιλέως φρονήσεως καὶ σοφίας ἐνόμιζε τὸ πλῆθος, κἀξ ἐκείνης τὸ λοιπὸν τῆς ἡμέρας ὡς θείαν ἔχοντι διάνοιαν αὐτῷ προσεῖχον."},{"number":35,"text":"Στρατηγοὶ δʼ αὐτῷ καὶ ἡγεμόνες ἦσαν τῆς χώρας ἁπάσης οἵδε· τῆς μὲν Ἐφραίμου κληρουχίας Οὔρης· ἐπὶ δὲ τῆς Βιθιέμες τοπαρχίας ἦν Διόκληρος· τὴν δὲ τῶν Δώρων καὶ τὴν παραλίαν Ἀβινάδαβος εἶχεν ὑπʼ αὐτῷ γεγαμηκὼς τὴν Σολόμωνος θυγατέρα·"},{"number":36,"text":"τὸ δὲ μέγα πεδίον ἦν ὑπὸ Βαναίᾳ τῷ Ἀχίλου παιδί, προσεπῆρχε δὲ καὶ τῆς ἄχρι Ἰορδάνου πάσης· τὴν δὲ Γαλαδῖτιν καὶ Γαυλανῖτιν ἕως τοῦ Λιβάνου ὄρους καὶ πόλεις ἑξήκοντα μεγάλας καὶ ὀχυρωτάτας ἔχων ὑφʼ αὑτὸν Γαβάρης διεῖπεν· Ἀχινάδαβος δὲ τῆς Γαλιλαίας ὅλης ἄχρι Σιδῶνος ἐπετρόπευε συνοικῶν καὶ αὐτὸς θυγατρὶ Σολόμωνος Βασίμα τοὔνομα·"},{"number":37,"text":"τὴν δὲ περὶ Ἀκὴν παραλίαν εἶχε Βανακάτης· Σαφάτης δὲ τὸ Ἰταβύριον ὄρος καὶ Καρμήλιον καὶ τὴν κάτω Γαλιλαίαν ἄχρι τοῦ ποταμοῦ Ἰορδάνου χώραν ἐπὶ τούτῳ πᾶσαν ἐπετέτραπτο· Σουμούις δὲ τὴν τῆς Βενιαμίδος κληρουχίαν ἐγκεχείριστο· Γαβάρης δὲ εἶχε τὴν πέραν τοῦ Ἰορδάνου χώραν· ἐπὶ δὲ τούτων εἷς πάλιν ἄρχων ἀποδέδεικτο."},{"number":38,"text":"θαυμαστὴν δʼ ἐπίδοσιν ἔλαβεν ὅ τε τῶν Ἑβραίων λαὸς καὶ ἡ Ἰούδα φυλὴ πρὸς γεωργίαν τραπέντων καὶ τὴν τῆς γῆς ἐπιμέλειαν· εἰρήνης γὰρ ἀπολαύοντες καὶ πολέμοις καὶ ταραχαῖς μὴ περισπώμενοι καὶ προσέτι τῆς ποθεινοτάτης ἐλευθερίας ἀκρατῶς ἐμφορούμενοι πρὸς τῷ συναύξειν ἕκαστος τὰ οἰκεῖα καὶ ποιεῖν ἄξια πλείονος ὑπῆρχεν."},{"number":39,"text":"Ἦσαν δὲ καὶ ἕτεροι τῷ βασιλεῖ ἡγεμόνες, οἳ τῆς τε Σύρων γῆς καὶ τῶν ἀλλοφύλων ἥτις ἦν ἀπʼ Εὐφράτου ποταμοῦ διήκουσα μέχρι τῆς Αἰγυπτίων ἐπῆρχον ἐκλέγοντες αὐτῷ φόρους παρὰ τῶν ἐθνῶν."},{"number":40,"text":"συνετέλουν δὲ καὶ τῇ τραπέζῃ καθʼ ἡμέραν καὶ τῷ δείπνῳ τοῦ βασιλέως σεμιδάλεως μὲν κόρους τριάκοντα, ἀλεύρου δὲ ξ, σιτιστοὺς δὲ βόας δέκα καὶ νομάδας βόας εἴκοσι, σιτιστοὺς δὲ ἄρνας ἑκατόν. ταῦτα πάντα πάρεξ τῶν ἀπʼ ἄγρας ἐλάφων λέγω καὶ βουβάλων καὶ τῶν πετεινῶν καὶ ἰχθύων ἐκομίζετο καθʼ ἡμέραν βασιλεῖ παρὰ τῶν ἀλλοφύλων."},{"number":41,"text":"τοσοῦτον δὲ πλῆθος ἦν ἁρμάτων Σολόμωνι, ὡς τέσσαρας εἶναι μυριάδας φατνῶν τῶν ὑποζευγνυμένων ἵππων· χωρὶς δὲ τούτων ἦσαν ἱππεῖς δισχίλιοι καὶ μύριοι, ὧν οἱ μὲν ἡμίσεις τῷ βασιλεῖ προσήδρευον ἐν Ἱεροσολύμοις, οἱ δὲ λοιποὶ κατὰ τὰς βασιλικὰς διεσπαρμένοι κώμας ἐν αὐταῖς κατέμενον. ὁ δʼ αὐτὸς ἡγεμὼν ὁ τὴν τοῦ βασιλέως δαπάνην πεπιστευμένος καὶ τοῖς ἵπποις ἐχορήγει τὰ ἐπιτήδεια συγκομίζων εἰς ὃν ὁ βασιλεὺς διέτριβε τόπον."},{"number":42,"text":"Τοσαύτη δʼ ἦν ἣν ὁ θεὸς παρέσχε Σολόμωνι φρόνησιν καὶ σοφίαν, ὡς τούς τε ἀρχαίους ὑπερβάλλειν ἀνθρώπους καὶ μηδὲ τοὺς Αἰγυπτίους, οἳ πάντων συνέσει διενεγκεῖν λέγονται, συγκρινομένους λείπεσθαι παρʼ ὀλίγον, ἀλλὰ πλεῖστον ἀφεστηκότας τῆς τοῦ βασιλέως φρονήσεως ἐλέγχεσθαι."},{"number":43,"text":"ὑπερῆρε δὲ καὶ διήνεγκε σοφίᾳ καὶ τῶν κατὰ τὸν αὐτὸν καιρὸν δόξαν ἐχόντων παρὰ τοῖς Ἑβραίοις ἐπὶ δεινότητι, ὧν οὐ παρελεύσομαι τὰ ὀνόματα· ἦσαν δὲ Ἄθανος καὶ Αἱμανὸς καὶ Χάλκεος καὶ Δάρδανος υἱοὶ Ἡμάωνος."},{"number":44,"text":"συνετάξατο δὲ καὶ βιβλία περὶ ᾠδῶν καὶ μελῶν πέντε πρὸς τοῖς χιλίοις καὶ παραβολῶν καὶ εἰκόνων βίβλους τρισχιλίας· καθʼ ἕκαστον γὰρ εἶδος δένδρου παραβολὴν εἶπεν ἀπὸ ὑσσώπου ἕως κέδρου, τὸν αὐτὸν δὲ τρόπον καὶ περὶ κτηνῶν καὶ τῶν ἐπιγείων ἁπάντων ζῴων καὶ τῶν νηκτῶν καὶ τῶν ἀερίων· οὐδεμίαν γὰρ φύσιν ἠγνόησεν οὐδὲ παρῆλθεν ἀνεξέταστον, ἀλλʼ ἐν πάσαις ἐφιλοσόφησε καὶ τὴν ἐπιστήμην τῶν ἐν αὐταῖς ἰδιωμάτων ἄκραν ἐπεδείξατο."},{"number":45,"text":"παρέσχε δʼ αὐτῷ μαθεῖν ὁ θεὸς καὶ τὴν κατὰ τῶν δαιμόνων τέχνην εἰς ὠφέλειαν καὶ θεραπείαν τοῖς ἀνθρώποις· ἐπῳδάς τε συνταξάμενος αἷς παρηγορεῖται τὰ νοσήματα καὶ τρόπους ἐξορκώσεων κατέλιπεν, οἷς οἱ ἐνδούμενοι τὰ δαιμόνια ὡς μηκέτʼ ἐπανελθεῖν ἐκδιώξουσι."},{"number":46,"text":"καὶ αὕτη μέχρι νῦν παρʼ ἡμῖν ἡ θεραπεία πλεῖστον ἰσχύει· ἱστόρησα γάρ τινα Ἐλεάζαρον τῶν ὁμοφύλων Οὐεσπασιανοῦ παρόντος καὶ τῶν υἱῶν αὐτοῦ καὶ χιλιάρχων καὶ ἄλλου στρατιωτικοῦ πλήθους ὑπὸ τῶν δαιμονίων λαμβανομένους ἀπολύοντα τούτων. ὁ δὲ τρόπος τῆς θεραπείας τοιοῦτος ἦν·"},{"number":47,"text":"προσφέρων ταῖς ῥισὶ τοῦ δαιμονιζομένου τὸν δακτύλιον ἔχοντα ὑπὸ τῇ σφραγῖδι ῥίζαν ἐξ ὧν ὑπέδειξε Σολόμων ἔπειτα ἐξεῖλκεν ὀσφρομένῳ διὰ τῶν μυκτήρων τὸ δαιμόνιον, καὶ πεσόντος εὐθὺς τἀνθρώπου μηκέτʼ εἰς αὐτὸν ἐπανήξειν ὥρκου, Σολόμωνός τε μεμνημένος καὶ τὰς ἐπῳδὰς ἃς συνέθηκεν ἐκεῖνος ἐπιλέγων."},{"number":48,"text":"βουλόμενος δὲ πεῖσαι καὶ παραστῆσαι τοῖς παρατυγχάνουσιν ὁ Ἐλεάζαρος, ὅτι ταύτην ἔχει τὴν ἰσχύν, ἐτίθει μικρὸν ἔμπροσθεν ἤτοι ποτήριον πλῆρες ὕδατος ἢ ποδόνιπτρον καὶ τῷ δαιμονίῳ προσέταττεν ἐξιὸν τἀνθρώπου ταῦτα ἀνατρέψαι καὶ παρασχεῖν ἐπιγνῶναι τοῖς ὁρῶσιν, ὅτι καταλέλοιπε τὸν ἄνθρωπον."},{"number":49,"text":"γινομένου δὲ τούτου σαφὴς ἡ Σολόμωνος καθίστατο σύνεσις καὶ σοφία διʼ ἣν, ἵνα γνῶσιν ἅπαντες αὐτοῦ τὸ μεγαλεῖον τῆς φύσεως καὶ τὸ θεοφιλὲς καὶ λάθῃ μηδένα τῶν ὑπὸ τὸν ἥλιον ἡ τοῦ βασιλέως περὶ πᾶν εἶδος ἀρετῆς ὑπερβολή, περὶ τούτων εἰπεῖν προήχθημεν."},{"number":50,"text":"Ὁ δὲ τῶν Τυρίων βασιλεὺς Εἴρωμος ἀκούσας ὅτι Σολόμων τὴν τοῦ πατρὸς διεδέξατο βασιλείαν ὑπερήσθη, φίλος γὰρ ἐτύγχανε τῷ Δαυίδῃ, καὶ πέμψας πρὸς αὐτὸν ἠσπάζετό τε καὶ συνέχαιρεν ἐπὶ τοῖς παροῦσιν ἀγαθοῖς. ἀποστέλλει δὲ πρὸς αὐτὸν Σολόμων γράμματα δηλοῦντα τάδε·"},{"number":51,"text":"βασιλεὺς Σολόμων Εἱρώμῳ βασιλεῖ. ἴσθι μου τὸν πατέρα βουληθέντα κατασκευάσαι τῷ θεῷ ναὸν ὑπὸ τῶν πολέμων καὶ τῶν συνεχῶν στρατειῶν κεκωλυμένον· οὐ γὰρ ἐπαύσατο πρότερον τοὺς ἐχθροὺς καταστρεφόμενος πρὶν ἢ πάντας αὐτοὺς φόρων ὑποτελεῖς πεποιηκέναι."},{"number":52,"text":"ἐγὼ δὲ χάριν οἶδα τῷ θεῷ τῆς παρούσης εἰρήνης καὶ διὰ ταύτην εὐσχολῶν οἰκοδομῆσαι τῷ θεῷ βούλομαι τὸν οἶκον· καὶ γὰρ ὑπʼ ἐμοῦ τοῦτον ἔσεσθαι τῷ πατρί μου προεῖπεν ὁ θεός. διὸ παρακαλῶ σε συμπέμψαι τινὰς τοῖς ἐμοῖς εἰς Λίβανον τὸ ὄρος κόψοντας ξύλα· πρὸς γὰρ τομὴν ὕλης ἐπιστημονέστερον ἔχουσι τῶν ἡμετέρων οἱ Σιδώνιοι. μισθὸν δʼ ὃν ἂν ὁρίσῃς ἐγὼ τοῖς ὑλουργοῖς παρέξω."},{"number":53,"text":"Ἀναγνοὺς δὲ τὴν ἐπιστολὴν Εἵρωμος καὶ τοῖς ἐπεσταλμένοις ἡσθεὶς ἀντιγράφει τῷ Σολόμωνι· βασιλεὺς Εἵρωμος βασιλεῖ Σολόμωνι. τὸν μὲν θεὸν εὐλογεῖν ἄξιον, ὅτι σοι τὴν πατρῴαν παρέδωκεν ἡγεμονίαν ἀνδρὶ σοφῷ καὶ πᾶσαν ἀρετὴν ἔχοντι, ἐγὼ δὲ τούτοις ἡδόμενος ἅπαντα ὑπουργήσω τὰ ἐπεσταλμένα·"},{"number":54,"text":"τεμὼν γὰρ ξύλα πολλὰ καὶ μεγάλα κέδρου τε καὶ κυπαρίσσου διὰ τῶν ἐμῶν καταπέμψω ἐπὶ θάλασσαν καὶ κελεύσω τοὺς ἐμοὺς σχεδίαν πηξαμένους εἰς ὃν ἂν βουληθῇς τόπον τῆς σαυτοῦ χώρας πλεύσαντας ἀποθέσθαι· ἔπειθʼ οἱ σοὶ διακομίσουσιν εἰς Ἱεροσόλυμα. ὅπως δὲ καὶ σὺ παράσχῃς ἡμῖν ἀντὶ τούτων σῖτον, οὗ διὰ τὸ νῆσον οἰκεῖν δεόμεθα, φρόντισον."},{"number":55,"text":"Διαμένει δὲ ἄχρι τῆς τήμερον τὰ τῶν ἐπιστολῶν τούτων ἀντίγραφα οὐκ ἐν τοῖς ἡμετέροις μόνον σωζόμενα βιβλίοις ἀλλὰ καὶ παρὰ Τυρίοις, ὥστε εἴ τις ἐθελήσειε τὸ ἀκριβὲς μαθεῖν, δεηθεὶς τῶν ἐπὶ τοῦ Τυρίων γραμματοφυλακείου δημοσίων εὕροι συμφωνοῦντα τοῖς εἰρημένοις ὑφʼ ἡμῶν τὰ παρʼ ἐκείνοις."},{"number":56,"text":"ταῦτα μὲν οὖν διεξῆλθον βουλόμενος γνῶναι τοὺς ἐντευξομένους, ὅτι μηδὲν μᾶλλον ἔξω τῆς ἀληθείας λέγομεν, μηδὲ πιθανοῖς τισι καὶ πρὸς ἀπάτην καὶ τέρψιν ἐπαγωγοῖς τὴν ἱστορίαν διαλαμβάνοντες τὴν μὲν ἐξέτασιν φεύγειν πειρώμεθα, πιστεύεσθαι δʼ εὐθὺς ἀξιοῦμεν, οὐδὲ συγκεχωρημένον ἡμῖν κατεξανισταμένοις τοῦ πρέποντος τῇ πραγματείᾳ ἀθῴοις ὑπάρχειν, ἀλλὰ μηδεμιᾶς ἀποδοχῆς τυγχάνειν παρακαλοῦντες, ἂν μὴ μετὰ ἀποδείξεως καὶ τεκμηρίων ἰσχυρῶν ἐμφανίζειν δυνώμεθα τὴν ἀλήθειαν."},{"number":57,"text":"Ὁ δὲ βασιλεὺς Σολόμων ὡς ἐκομίσθη τὰ παρὰ Τυρίων βασιλέως γράμματα τήν τε προθυμίαν αὐτοῦ καὶ τὴν εὔνοιαν ἐπῄνεσε καὶ οἷς ἠξίωσε τούτοις αὐτὸν ἠμείψατο, σίτου μὲν αὐτῷ κατʼ ἔτος πέμψας δισμυρίους κόρους καὶ τοσούτους ἐλαίου βάτους, ὁ δὲ βάτος δύναται ξέστας ἑβδομήκοντα δύο· τὸ δʼ αὐτὸ μέτρον καὶ οἴνου παρεῖχεν."},{"number":58,"text":"ἡ μὲν οὖν Εἱρώμου φιλία καὶ Σολόμωνος ἀπὸ τούτων ἔτι μᾶλλον ηὔξησε καὶ διαμένειν ὤμοσαν εἰς ἅπαν. ὁ δὲ βασιλεὺς ἐπέταξε παντὶ τῷ λαῷ φόρον ἐργάτας τρισμυρίους, οἷς ἄπονον τὴν ἐργασίαν κατέστησε μερίσας αὐτὴν συνετῶς· μυρίους γὰρ ἐποίησε κόπτοντας ἐπὶ μῆνα ἕνα ἐν Λιβάνῳ ὄρει δύο μῆνας ἀναπαύεσθαι παραγινομένους ἐπὶ τὰ οἰκεῖα, μέχρις οὗ πάλιν οἱ δισμύριοι τὴν"},{"number":59,"text":"ἐργασίαν ἀναπληρώσωσι κατὰ τὸν ὡρισμένον χρόνον ἔπειθʼ οὕτως συνέβαινε τοῖς πρώτοις μυρίοις διὰ τετάρτου μηνὸς ἀπαντᾶν ἐπὶ τὸ ἔργον. ἐγεγόνει δʼ ἐπίτροπος τοῦ φόρου τούτου Ἀδώραμος. ἦσαν δʼ ἐκ τῶν παροίκων οὓς Δαυίδης καταλελοίπει τῶν μὲν παρακομιζόντων τὴν λιθίαν καὶ τὴν ἄλλην ὕλην ἑπτὰ μυριάδες, τῶν δὲ λατομούντων ὀκτάκις μύριοι, τούτων δʼ ἐπιστάται τρισχίλιοι καὶ τριακόσιοι."},{"number":60,"text":"προστετάχει δὲ λίθους μὲν αὐτοῖς τέμνειν μεγάλους εἰς τοὺς τοῦ ναοῦ θεμελίους, ἁρμόσαντας δὲ πρῶτον καὶ συνδήσαντας ἐν τῷ ὄρει κατακομίζειν οὕτως εἰς τὴν πόλιν. ἐγίνετο δὲ ταῦτʼ οὐ παρὰ τῶν οἰκοδόμων τῶν ἐγχωρίων μόνον, ἀλλὰ καὶ ὧν ὁ Εἵρωμος ἔπεμψε τεχνιτῶν."}],"3":[{"number":61,"text":"Τῆς δʼ οἰκοδομίας τοῦ ναοῦ Σολόμων ἤρξατο τέταρτον ἔτος ἤδη τῆς βασιλείας ἔχων μηνὶ δευτέρῳ, ὃν Μακεδόνες μὲν Ἀρτεμίσιον καλοῦσιν Ἑβραῖοι δὲ Ἰάρ, μετὰ ἔτη πεντακόσια καὶ ἐνενήκοντα καὶ δύο τῆς ἀπʼ Αἰγύπτου τῶν Ἰσραηλιτῶν ἐξόδου, μετὰ δὲ χίλια καὶ εἴκοσι ἔτη τῆς Ἁβράμου εἰς τὴν Χαναναίαν ἐκ τῆς Μεσοποταμίας ἀφίξεως, ἀπὸ δὲ τῆς ἐπομβρίας μετὰ χίλια καὶ τετρακόσια καὶ τεσσαράκοντα·"},{"number":62,"text":"ἀπὸ δὲ τοῦ πρώτου γεννηθέντος Ἀδάμου ἕως οὗ τὸν ναὸν ᾠκοδόμησε Σολόμων διεληλύθει τὰ πάντα ἔτη τρισχίλια καὶ ἑκατὸν δύο. καθʼ ὃν δὲ ὁ ναὸς ἤρξατο οἰκοδομεῖσθαι χρόνον, κατʼ ἐκεῖνον ἔτος ἤδη τῆς ἐν Τύρῳ βασιλείας ἑνδέκατον ἐνειστήκει Εἱρώμῳ, τῆς δὲ οἰκήσεως εἰς τὴν οἰκοδομίαν τοῦ ναοῦ διεγεγόνει χρόνος ἐτῶν τεσσαράκοντα καὶ διακοσίων."},{"number":63,"text":"Βάλλεται μὲν οὖν τῷ ναῷ θεμελίους ὁ βασιλεὺς ἐπὶ μήκιστον τῆς γῆς βάθος ὕλης λίθων ἰσχυρᾶς καὶ πρὸς χρόνον ἀντέχειν δυναμένης, οἳ τῇ τε γῇ συμφυέντες ἔμελλον ἔδαφος καὶ ἔρεισμα τῆς ἐποικοδομησομένης κατασκευῆς ἔσεσθαι καὶ διὰ τὴν κάτωθεν ἰσχὺν οἴσειν ἀπόνως μέγεθός τε τῶν ἐπικεισομένων καὶ κάλλους πολυτέλειαν, ᾗ βάρος ἔμελλεν οὐχ ἧττον εἶναι τῶν ἄλλων ὅσα πρὸς ὕψος καὶ πρὸς ὄγκον κόσμου τε χάριν καὶ μεγαλουργίας ἐπενοεῖτο."},{"number":64,"text":"ἀνήγαγε δὲ αὐτὸν ἄχρι τῆς ὀροφῆς ἐκ λευκοῦ λίθου πεποιημένον. τὸ μὲν οὖν ὕψος ἦν ἑξήκοντα πηχῶν, τῶν δʼ αὐτῶν καὶ τὸ μῆκος, εὖρος δʼ εἴκοσι. κατὰ τούτου δὲ ἄλλος ἦν ἐγηγερμένος ἴσος τοῖς μέτροις, ὥστε εἶναι τὸ πᾶν ὕψος τῷ ναῷ πηχῶν ἑκατὸν καὶ εἴκοσι·"},{"number":65,"text":"τέτραπτο δὲ πρὸς τὴν ἀνατολήν. τὸ δὲ προνάιον αὐτοῦ προύστησαν ἐπὶ πήχεις μὲν εἴκοσι τὸ μῆκος πρὸς τὸ εὖρος τοῦ οἴκου τεταμένον, ἔχον δὲ πλάτος πήχεις δέκα καὶ εἰς ὕψος δὲ ἀνεγηγερμένον πηχῶν ἑκατὸν καὶ εἴκοσι. περιῳκοδόμησε δὲ τὸν ναὸν ἐν κύκλῳ τριάκοντα βραχέσιν οἴκοις, οἳ συνοχή τε τοῦ παντὸς ἔμελλον ἔσεσθαι διὰ πυκνότητα καὶ πλῆθος ἔξωθεν περικείμενοι, καὶ δὴ καὶ τὰς εἰσόδους αὐτοῖς διʼ ἀλλήλων κατεσκεύασεν."},{"number":66,"text":"ἕκαστος δὲ τῶν οἴκων τούτων εὖρος μὲν εἶχε πέντε πήχεις, μῆκος δὲ τοὺς αὐτούς, ὕψος δὲ εἴκοσιν. ἐπῳκοδόμηντο δὲ τούτοις ἄνωθεν ἕτεροι οἶκοι καὶ πάλιν ἄλλοι κατʼ αὐτῶν ἴσοι καὶ τοῖς μέτροις καὶ τῷ ἀριθμῷ, ὡς τὸ πᾶν ὕψος αὐτοὺς λαβεῖν τῷ κάτωθεν οἴκῳ παραπλήσιον· ὁ γὰρ ὑπερῷος οὐκ ἦν περιῳκοδομημένος."},{"number":67,"text":"ὄροφος δὲ αὐτοῖς ἐπεβέβλητο κέδρου καὶ τοῖς μὲν οἴκοις ἴδιος ἦν οὗτος ἑκάστῳ πρὸς τοὺς πλησίον οὐ συνάπτων, τοῖς δʼ ἄλλοις ὑπῆρχεν ἡ στέγη κοινὴ διʼ ἀλλήλων δεδομημένη μηκίσταις δοκοῖς καὶ διηκούσαις ἁπάντων, ὡς τοὺς μέσους τοίχους ὑπὸ τῶν αὐτῶν συγκρατουμένους ξύλων ἐρρωμενεστέρους διὰ τοῦτο γίνεσθαι."},{"number":68,"text":"τὴν δὲ ὑπὸ τὰς δοκοὺς στέγην τῆς αὐτῆς ὕλης ἐβάλετο πᾶσαν ἐξεσμένην εἰς φατνώματα καὶ προσκόλλησιν χρυσοῦ. τοὺς δὲ τοίχους κεδρίναις διαλαβὼν σανίσι χρυσὸν αὐταῖς ἐνετόρευσεν, ὥστε στίλβειν ἅπαντα τὸν ναὸν καὶ περιλάμπεσθαι τὰς ὄψεις τῶν εἰσιόντων ὑπὸ τῆς αὐγῆς τοῦ χρυσοῦ πανταχόθεν φερομένης."},{"number":69,"text":"ἡ δʼ ὅλη τοῦ ναοῦ οἰκοδομία κατὰ πολλὴν τέχνην ἐκ λίθων ἀκροτόμων ἐγένετο συντεθέντων ἁρμονίως πάνυ καὶ λείως, ὡς μήτε σφύρας μήτε ἄλλου τινὸς ἐργαλείου τεκτονικοῦ τοῖς κατανοοῦσιν ἐργασίαν δηλοῦσθαι, ἀλλὰ δίχα τῆς τούτων χρήσεως πᾶσαν ἡρμόσθαι τὴν ὕλην προσφυῶς, ὡς ἑκούσιον τὴν ἁρμονίαν αὐτῆς δοκεῖν μᾶλλον ἢ τῆς τῶν ἐργαλείων ἀνάγκης."},{"number":70,"text":"ἐφιλοτέχνησε δὲ ὁ βασιλεὺς ἄνοδον εἰς τὸν ὑπερῷον οἶκον διὰ τοῦ εὔρους τοῦ τοίχου· οὐ γὰρ εἶχε θύραν μεγάλην κατὰ τῆς ἀνατολῆς ὡς εἶχεν ὁ κάτωθεν οἶκος, ἀλλʼ ἐκ τῶν πλευρῶν ἦσαν εἴσοδοι διὰ μικρῶν πάνυ θυρῶν. διέλαβε δὲ τὸν ναὸν καὶ ἔνδοθεν καὶ ἔξωθεν ξύλοις κεδρίνοις ἁλύσεσι παχείαις συνδεδεμένοις, ὥστε ἀντʼ ὀχυρωμάτων καὶ ῥώμης τοῦτο εἶναι."},{"number":71,"text":"Διελὼν δὲ τὸν ναὸν εἰς δύο τὸν μὲν ἔνδοθεν οἶκον εἴκοσι πηχῶν ἐποίησεν ἄδυτον, τὸν δὲ τεσσαράκοντα πηχῶν ἅγιον ναὸν ἀπέδειξεν. ἐκτεμὼν δὲ τὸν μέσον τοῖχον θύρας ἐπέστησε κεδρίνας χρυσὸν πολὺν αὐταῖς ἐνεργασάμενος καὶ τορείαν ποικίλην."},{"number":72,"text":"κατεπέτασε δὲ ταύτας ὕφεσιν εὐανθεστάτοις ἐξ ὑακίνθου καὶ πορφύρας καὶ κόκκου πεποιημένοις, οὐ μὴν ἀλλὰ καὶ βύσσου λαμπροτάτης καὶ μαλακωτάτης. ἀνέθηκε δὲ εἰς τὸ ἄδυτον εἴκοσι πηχῶν τὸ εὖρος τῶν δʼ αὐτῶν καὶ τὸ μῆκος δύο Χερουβεῖς ὁλοχρύσους πηχῶν ἑκατέραν τὸ ὕψος πέντε, δύο δʼ ἦσαν ἑκατέρᾳ πτέρυγες ἐπὶ πέντε πήχεις ἐκτεταμέναι."},{"number":73,"text":"διὸ καὶ οὐ μακρὰν ἀλλήλων αὐτὰς ἀνέστησεν, ἵνα τῶν πτερύγων τῇ μὲν ἅπτωνται τοῦ κατὰ νότον κειμένου τοίχου τοῦ ἀδύτου, τῇ δὲ κατὰ βορέαν, αἱ δʼ ἄλλαι πτέρυγες αὑταῖς συνάπτουσαι τεθείσῃ μεταξὺ αὐτῶν τῇ κιβωτῷ σκέπη τυγχάνωσι. τὰς δὲ Χερουβεῖς οὐδεὶς ὁποῖαί τινές εἰσιν εἰπεῖν οὐδʼ εἰκάσαι δύναται."},{"number":74,"text":"κατέστρωσε δὲ καὶ τοῦ ναοῦ τὸ ἔδαφος ἐλάσμασι χρυσοῦ, ἐπέθηκε δὲ καὶ τῷ πυλῶνι τοῦ ναοῦ θύρας πρὸς τὸ ὕψος τοῦ τοίχου συμμεμετρημένας εὖρος ἐχούσας πηχῶν εἴκοσι, καὶ ταύτας κατεκόλλησε χρυσῷ."},{"number":75,"text":"συνελόντι δʼ εἰπεῖν οὐδὲν εἴασε τοῦ ναοῦ μέρος οὔτε ἔξωθεν οὔτε ἔνδοθεν, ὃ μὴ χρυσὸς ἦν. κατεπέτασε δὲ καὶ ταύτας τὰς θύρας ὁμοίως ταῖς ἐνδοτέρω καταπετάσμασιν. ἡ δὲ τοῦ προναΐου πύλη τούτων οὐδὲν εἶχε."},{"number":76,"text":"Μεταπέμπεται δʼ ἐκ Τύρου Σολόμων παρὰ Εἱρώμου τεχνίτην Χείρωμον ὄνομα μητρὸς μὲν ὄντα Νεφθαλίτιδος τὸ γένος, ἐκ γὰρ ταύτης ὑπῆρχε τῆς φυλῆς, πατρὸς δὲ Οὐρίου γένος Ἰσραηλίτου. οὗτος ἅπαντος μὲν ἐπιστημόνως εἶχεν ἔργου, μάλιστα δὲ τεχνίτης ἦν χρυσὸν ἐργάζεσθαι καὶ ἄργυρον καὶ χαλκόν, ὑφʼ οὗ δὴ καὶ πάντα κατὰ τὴν τοῦ βασιλέως βούλησιν τὰ περὶ τὸν ναὸν ἐμηχανήθη."},{"number":77,"text":"κατεσκεύασε δὲ ὁ Χείρωμος οὗτος καὶ στύλους δύο χαλκοῦς ἔσωθεν τὸ πάχος τεσσάρων δακτύλων. ἦν δὲ τὸ μὲν ὕψος τοῖς κίοσιν ὀκτωκαίδεκα πήχεων, ἡ δὲ περίμετρος δέκα καὶ δύο πηχῶν· χωνευτὸν δʼ ἐφʼ ἑκατέρᾳ κεφαλῇ κρίνον ἐφειστήκει τὸ ὕψος ἐπὶ πέντε πήχεις ἐγηγερμένον, ᾧ περιέκειτο δίκτυον ἐλάτῃ χαλκέᾳ περιπεπλεγμένον καλύπτον τὰ κρίνα."},{"number":78,"text":"τούτου δὲ ἀπήρτηντο κατὰ διστιχίαν καὶ ῥοιαὶ διακόσιαι. τούτων τῶν κιόνων τὸν μὲν ἕτερον κατὰ τὴν δεξιὰν ἔστησε τοῦ προπυλαίου παραστάδα καλέσας αὐτὸν Ἰαχείν, τὸν δʼ ἕτερον κατὰ τὸ ἀριστερὸν ὀνομάσας αὐτὸν Ἀβαίζ."},{"number":79,"text":"Ἐχώνευσε δὲ καὶ θάλασσαν χαλκῆν εἰς ἡμισφαίριον ἐσχηματισμένην· ἐκλήθη δὲ τὸ χαλκούργημα θάλασσα διὸ τὸ μέγεθος· ἦν γὰρ ὁ λουτὴρ τὴν διάμετρον πηχῶν δέκα καὶ ἐπὶ παλαιστιαῖον πάχος κεχωνευμένος. ὑπερήρειστο δὲ κατὰ τὸ μεσαίτατον τοῦ κύτους σπείρᾳ περιαγομένῃ εἰς ἕλικας δέκα·"},{"number":80,"text":"ἦν δὲ τὴν διάμετρον πήχεως, περιειστήκεσαν δὲ περὶ αὐτὴν μόσχοι δώδεκα πρὸς τὰ κλίματα τῶν τεσσάρων ἀνέμων ἀποβλέποντες καθʼ ἕκαστον αὐτῶν τρεῖς, εἰς τὰ ὀπίσθια νενευκότες, ὥστʼ αὐτοῖς ἐπικαθέζεσθαι τὸ ἡμισφαίριον κατὰ περιαγωγὴν ἔνδον ἀπονεῦον. ἐδέχετο δὲ ἡ θάλασσα βάτους τρισχιλίους."},{"number":81,"text":"Ἐποίησε δὲ καὶ λουτήρων δέκα βάσεις χαλκᾶς τετραγώνους. τούτων ἑκάστη μῆκος γεγόνει πηχῶν πέντε πλάτος τεσσάρων ὕψος ἕξ. συνεκέκλειτο δὲ τὸ ἔργον κατὰ μέρος τετορευμένον οὕτως· τέσσαρες ἦσαν κιονίσκοι κατὰ γωνίαν ἑστῶτες τετράγωνοι τὰ πλευρὰ τῆς βάσεως ἐξ ἑκατέρου μέρους ἐν αὑτοῖς ἔχοντες ἐξηρμοσμένα."},{"number":82,"text":"ἦν δὲ ταῦτα τριχῇ διῃρημένα· ἑκάστην δὲ χώραν ὅρος ἐπεῖχεν εἰς ὑπόβασιν κατεσκευασμένος, ἐφʼ οἷς ἐτετόρευτο πῇ μὲν λέων πῇ δὲ ταῦρος καὶ ἀετός, ἐπὶ δὲ τῶν κιονίσκων ὁμοίως ἐξείργαστο τοῖς κατὰ τὰ πλευρὰ τετορευμένοις."},{"number":83,"text":"τὸ δὲ πᾶν ἔργον ἐπὶ τεσσάρων αἰωρούμενον τροχῶν εἱστήκει. χωνευτοὶ δʼ ἦσαν οὗτοι πλήμνας καὶ ἄντυγας πήχεως καὶ ἡμίσους ἔχοντες τὴν διάμετρον. ἐθαύμασεν ἄν τις τὰς ἀψῖδας τῶν τροχῶν θεασάμενος, ὅπως συντετορευμέναι καὶ τοῖς πλευροῖς τῶν βάσεων προσηνωμέναι ἁρμονίως ταῖς ἄντυξιν ἐνέκειντο· ἦσαν δʼ ὅμως οὕτως ἔχουσαι."},{"number":84,"text":"τὰς δὲ γωνίας ἄνωθεν συνέκλειον ὦμοι χειρῶν ἀνατεταμένων, οἷς ἐπεκάθητο σπεῖρα κατὰ κοῖλον ἐπικειμένη τὸν λουτῆρα ταῖς χερσὶν ἐπαναπαυόμενον ἀετοῦ καὶ λέοντος αὐτοῖς ἐφηρμοσμένων, ὡς σύμφυτα ταῦτʼ εἶναι δοκεῖν τοῖς ὁρῶσι. μεταξὺ δὲ τούτων φοίνικες ἦσαν τετορευμένοι. τοιαύτη μὲν ἡ κατασκευὴ τῶν δέκα βάσεων ὑπῆρχε."},{"number":85,"text":"προσεξείργαστο δὲ καὶ χυτρογαύλους δέκα λουτῆρας στρογγύλους χαλκοῦς, ὧν ἕκαστος ἐχώρει τεσσαράκοντα χόας· τὸ γὰρ ὕψος εἶχε τεσσάρων πηχῶν καὶ τοσούτοις ἀλλήλων αὐτοῖς διειστήκει τὰ χείλη. τίθησι δὲ τοὺς λουτῆρας τούτους ἐπὶ τῶν δέκα βάσεων τῶν κληθεισῶν Μεχενώθ."},{"number":86,"text":"πέντε δὲ λουτῆρας ἵστησιν ἐξ ἀριστεροῦ μέρους τοῦ ναοῦ, τέτραπτο δὲ τοῦτο κατὰ βορέαν ἄνεμον, καὶ τοσούτους ἐκ τοῦ δεξιοῦ πρὸς νότον ἀφορῶντας εἰς τὴν ἀνατολήν· κατὰ δʼ αὐτὸ καὶ τὴν θάλασσαν ἔθηκε."},{"number":87,"text":"πληρώσας δὲ ὕδατος τὴν μὲν θάλασσαν ἀπέδειξεν εἰς τὸ νίπτειν τοὺς εἰς τὸν ναὸν εἰσιόντας ἱερεῖς ἐν αὐτῇ τὰς χεῖρας καὶ τοὺς πόδας μέλλοντας ἀναβαίνειν ἐπὶ τὸν βωμόν, τοὺς δὲ λουτῆρας εἰς τὸ καθαίρειν τὰ ἐντὸς τῶν ὁλοκαυτουμένων ζῴων καὶ τοὺς πόδας αὐτῶν."},{"number":88,"text":"Κατεσκεύασε δὲ καὶ θυσιαστήριον χάλκεον εἴκοσι πηχῶν τὸ μῆκος καὶ τοσούτων τὸ εὖρος τὸ δὲ ὕψος δέκα πρὸς τὰς ὁλοκαυτώσεις. ἐποίησε δὲ αὐτοῦ καὶ τὰ σκεύη πάντα χάλκεα ποδιστῆρας καὶ ἀναλημπτῆρας· οὐ μὴν ἀλλὰ πρὸς τούτοις Χείρωμος καὶ λέβητας καὶ ἅρπαγας καὶ πᾶν σκεῦος ἐδημιούργησεν ἐκ χαλκοῦ τὴν αὐγὴν ὁμοίου χρυσῷ καὶ τὸ κάλλος·"},{"number":89,"text":"τραπεζῶν τε πλῆθος ἀνέθηκεν ὁ βασιλεύς, καὶ μίαν μὲν μεγάλην χρυσέαν, ἐφʼ ἧς ἐτίθεσαν τοὺς ἄρτους τοῦ θεοῦ, καὶ ταύτῃ παραπλησίας μυρίας πρὸς αὐταῖς ἑτέρῳ τρόπῳ γεγενημένας, ἐφʼ ὧν ἐπέκειτο τὰ σκεύη φιάλαι τε καὶ σπονδεῖα χρύσεα μὲν δισμύρια ἀργύρεα δὲ τετρακισμύρια."},{"number":90,"text":"καὶ λυχνίας δὲ μυρίας ἐποίησε κατὰ τὴν Μωυσέος προσταγήν, ἐξ ὧν μίαν ἀνέθηκεν εἰς τὸν ναόν, ἵνα καίηται καθʼ ἡμέραν ἀκολούθως τῷ νόμῳ, καὶ τράπεζαν μίαν ἐπικειμένην ἄρτους πρὸς τὸ βόρειον τοῦ ναοῦ μέρος ἀντικρὺ τῆς λυχνίας· ταύτην γὰρ κατὰ νότον ἔστησεν, ὁ δὲ χρύσεος βωμὸς μέσος αὐτῶν ἔκειτο. ταῦτα πάντα εἶχεν ὁ τῶν τεσσαράκοντα πηχῶν οἶκος πρὸ τοῦ καταπετάσματος τοῦ ἀδύτου· ἐν τούτῳ δὲ ἡ κιβωτὸς ἔμελλε κεῖσθαι."},{"number":91,"text":"Οἰνοχόας δʼ ὁ βασιλεὺς μυριάδας ὀκτὼ κατεσκεύασε καὶ φιαλῶν χρυσέων δέκα ἀργυρέας δὲ διπλασίονας. πινάκων δὲ χρυσέων εἰς τὸ προσφέρειν ἐν αὐτοῖς πεφυραμένην σεμίδαλιν τῷ βωμῷ μυριάδας ὀκτώ, τούτων δʼ ἀργυροῦς διπλασίονας. κρατῆρας δʼ οἷς ἐνεφύρων τὴν σεμίδαλιν μετʼ ἐλαίου χρυσέους μὲν ἑξακισμυρίους, ἀργυρέους δὲ δὶς τοσούτους."},{"number":92,"text":"τὰ μέτρα δὲ τοῖς Μωυσήου λεγομένοις δὲ ειν καὶ ἐσσάρωνες παραπλήσια, χρυσᾶ μὲν δισμύρια ἀργύρεα δὲ διπλασίονα. θυμιατήρια δὲ χρυσᾶ ἐν οἷς ἐκομίζετο τὸ θυμίαμα εἰς τὸν ναὸν δισμύρια· ὁμοίως ἄλλα θυμιατήρια οἷς ἐκόμιζον ἀπὸ τοῦ μεγάλου βωμοῦ πῦρ ἐπὶ τὸν μικρὸν βωμὸν τὸν ἐν τῷ ναῷ πεντακισμύρια."},{"number":93,"text":"στολὰς δὲ ἱερατικὰς τοῖς ἀρχιερεῦσι σὺν ποδήρεσιν ἐπωμίσι καὶ λογίῳ καὶ λίθοις χιλίας· ἡ δὲ στεφάνη, εἰς ἣν τὸν θεὸν Μωυσῆς ἔγραψε, μία ἦν καὶ διέμεινεν ἄχρι τῆσδε τῆς ἡμέρας· τὰς δὲ ἱερατικὰς στολὰς ἐκ βύσσου κατεσκεύασε καὶ ζώνας πορφυρᾶς εἰς ἕκαστον μυρίας."},{"number":94,"text":"καὶ σαλπίγγων κατὰ Μωυσέος ἐντολὴν μυριάδας εἴκοσι, καὶ στολῶν τοῖς ὑμνῳδοῖς Ληουιτῶν ἐκ βύσσου μυριάδας εἴκοσι· καὶ τὰ ὄργανα τὰ μουσικὰ καὶ πρὸς τὴν ὑμνῳδίαν ἐξηυρημένα, ἃ καλεῖται νάβλας καὶ κινύρας, ἐξ ἠλέκτρου κατεσκεύασε τετρακισμύρια."},{"number":95,"text":"Ταῦτα πάντα ὁ Σολόμων εἰς τὴν τοῦ θεοῦ τιμὴν πολυτελῶς καὶ μεγαλοπρεπῶς κατεσκεύασε μηδενὸς φεισάμενος ἀλλὰ πάσῃ φιλοτιμίᾳ περὶ τὸν τοῦ ναοῦ κόσμον χρησάμενος, ἃ καὶ κατέθηκεν ἐν τοῖς θησαυροῖς τοῦ θεοῦ. περιέβαλε δὲ τοῦ ναοῦ κύκλῳ γείσιον μὲν κατὰ τὴν ἐπιχώριον γλῶτταν τριγχὸν δὲ παρʼ Ἕλλησι λεγόμενον εἰς τρεῖς πήχεις ἀναγαγὼν τὸ ὕψος, εἴρξοντα μὲν τοὺς πολλοὺς τῆς εἰς τὸ ἱερὸν εἰσόδου, μόνοις δὲ ἀνειμένην αὐτὴν τοῖς ἱερεῦσι σημανοῦντα."},{"number":96,"text":"τούτου δʼ ἔξωθεν ἱερὸν ᾠκοδόμησεν· ἐν τετραγώνου σχήματι στοὰς ἐγείρας μεγάλας καὶ πλατείας καὶ πύλαις ὑψηλαῖς ἀνεῳγμένας, ὧν ἑκάστη πρὸς ἕκαστον τῶν ἀνέμων τέτραπτο χρυσέαις κλειομένη θύραις. εἰς τοῦτο τοῦ λαοῦ πάντες οἱ διαφέροντες ἁγνείᾳ καὶ παρατηρήσει τῶν νομίμων εἰσῄεσαν."},{"number":97,"text":"θαυμαστὸν δὲ καὶ λόγου παντὸς ἀπέφηνε μεῖζον, ὡς δὲ εἰπεῖν καὶ τῆς ὄψεως, τὸ τούτων ἔξωθεν ἱερόν· μεγάλας γὰρ ἐγχώσας φάραγγας, ἃς διὰ βάθος ἄπειρον οὐδὲ ἀπόνως ἐννεύσαντας ἦν ἰδεῖν, καὶ ἀναβιβάσας εἰς τετρακοσίους πήχεις τὸ ὕψος ἰσοπέδους τῇ κορυφῇ τοῦ ὄρους ἐφʼ ἧς ὁ ναὸς ᾠκοδόμητο κατεσκεύασε· καὶ διὰ τοῦτο ὕπαιθρον ὂν τὸ ἔξωθεν ἱερὸν ἴσον ὑπῆρχε τῷ ναῷ."},{"number":98,"text":"περιλαμβάνει δʼ αὐτὸ καὶ στοαῖς διπλαῖς μὲν τὴν κατασκευήν, λίθου δʼ αὐτοφυοῦς τὸ ὕψος κίοσιν ἐπερηρεισμέναις· ὀροφαὶ δʼ αὐταῖς ἦσαν ἐκ κέδρου φατνώμασιν ἀνεξεσμέναι. τὰς δὲ θύρας τῷ ἱερῷ τούτῳ πάσας ἐπέστησεν ἐξ ἀργύρου."}],"4":[{"number":99,"text":"Τὰ μὲν οὖν ἔργα ταῦτα καὶ τὰ μεγέθη καὶ κάλλη τῶν τε οἰκοδομημάτων καὶ τῶν εἰς τὸν ναὸν ἀναθημάτων Σολόμων ὁ βασιλεὺς ἐν ἔτεσιν ἑπτὰ συντελέσας καὶ πλούτου καὶ προθυμίας ἐπίδειξιν ποιησάμενος, ὡς ἄν τις ἰδὼν ἐνόμισεν ὡς ἐν τῷ παντὶ κατασκευασθῆναι χρόνῳ ταῦτα ἐν οὕτως ὀλίγῳ πρὸς τὸ μέγεθος συγκρινόμενα τοῦ ναοῦ συμπερασθῆναι, γράψας τοῖς ἡγεμόσι καὶ τοῖς πρεσβυτέροις τῶν Ἑβραίων ἐκέλευσεν ἅπαντα τὸν λαὸν συναγαγεῖν εἰς Ἱεροσόλυμα ὀψόμενόν τε τὸν ναὸν καὶ μετακομιοῦντα τὴν τοῦ θεοῦ κιβωτὸν εἰς αὐτόν."},{"number":100,"text":"καὶ περιαγγελθείσης τῆς εἰς τὰ Ἱεροσόλυμα πᾶσιν ἀφίξεως ἑβδόμῳ μηνὶ μόλις συνίασιν, ὑπὸ μὲν τῶν ἐπιχωρίων Ἀθύρει, ὑπὸ δὲ τῶν Μακεδόνων Ὑπερβερεταίῳ λεγομένῳ. συνέδραμε δʼ εἰς τὸν αὐτὸν χρόνον καὶ ὁ τῆς σκηνοπηγίας καιρὸς ἑορτῆς σφόδρα παρὰ τοῖς Ἑβραίοις ἁγιωτάτης καὶ μεγίστης."},{"number":101,"text":"βαστάσαντες οὖν τὴν κιβωτὸν καὶ τὴν σκηνήν, ἣν Μωυσῆς ἐπήξατο, καὶ πάντα τὰ πρὸς τὴν διακονίαν τῶν θυσιῶν τοῦ θεοῦ σκεύη μετεκόμιζον εἰς τὸν ναόν. προῆγον δὲ μετὰ θυσιῶν αὐτός τε ὁ βασιλεὺς καὶ ὁ λαὸς ἅπας καὶ οἱ Λευῖται σπονδαῖς τε καὶ πολλῶν ἱερείων αἵματι τὴν ὁδὸν καταντλοῦντες καὶ θυμιῶντες ἀπειρόν τι θυμιαμάτων πλῆθος,"},{"number":102,"text":"ὡς ἅπαντα τὸν πέριξ ἀέρα πεπληρωμένον καὶ τοῖς πορρωτάτω τυγχάνουσιν ἡδὺν ἀπαντᾶν καὶ γνωρίζειν ἐπιδημίαν θεοῦ καὶ κατοικισμὸν κατʼ ἀνθρωπίνην δόξαν εἰς νεοδόμητον αὐτῷ καὶ καθιερωμένον χωρίον· καὶ γὰρ οὐδʼ ὑμνοῦντες οὐδὲ χορεύοντες ἕως οὗ πρὸς τὸν ναὸν ἦλθον ἔκαμον."},{"number":103,"text":"τούτῳ μὲν οὖν τῷ τρόπῳ τὴν κιβωτὸν μετήνεγκαν. ὡς δʼ εἰς τὸ ἄδυτον αὐτὴν εἰσενεγκεῖν ἔδει, τὸ μὲν ἄλλο πλῆθος μετέστη, μόνοι δὲ κομίσαντες οἱ ἱερεῖς μεταξὺ τῶν δύο Χερουβὶμ κατέθεσαν· αἱ δὲ τοὺς ταρσοὺς συμπλέξασαι, καὶ γὰρ οὕτως ἦσαν ὑπὸ τοῦ τεχνίτου κατεσκευασμέναι, τὴν κιβωτὸν ὡς ὑπὸ σκηνῇ τινι καὶ θόλῳ κατεσκέπασαν."},{"number":104,"text":"εἶχε δὲ ἡ κιβωτὸς οὐδὲν ἕτερον ἢ δύο λιθίνας πλάκας, αἳ τοὺς δέκα λόγους τοὺς ὑπὸ τοῦ θεοῦ Μωυσεῖ λαληθέντας ἐν Σιναίῳ ὄρει ἐγγεγραμμένους αὐταῖς ἔσωζον. τὴν δὲ λυχνίαν καὶ τὴν τράπεζαν καὶ τὸν βωμὸν τὸν χρύσεον ἔστησαν ἐν τῷ ναῷ πρὸ τοῦ ἀδύτου κατὰ τοὺς αὐτοὺς τόπους, οὓς καὶ τότε ἐν τῇ σκηνῇ κείμενοι κατεῖχον, καὶ τὰς καθημερινὰς θυσίας ἀνέφερον."},{"number":105,"text":"τὸ δὲ θυσιαστήριον τὸ χάλκεον ἵστησι πρὸ τοῦ ναοῦ ἀντικρὺ τῆς θύρας, ὡς ἀνοιχθείσης αὐτὸ κατὰ πρόσωπον εἶναι καὶ βλέπεσθαι τὰς ἱερουργίας καὶ τὴν τῶν θυσιῶν πολυτέλειαν. τὰ δὲ λοιπὰ σκεύη πάντα συναλίσας ἔνδον εἰς τὸν ναὸν κατέθετο."},{"number":106,"text":"Ἐπεὶ δὲ πάντα διακοσμήσαντες οἱ ἱερεῖς τὰ περὶ τὴν κιβωτὸν ἐξῆλθον, ἄφνω πίλημα νεφέλης οὐ σκληρὸν οὐδʼ οἷον ὥρᾳ χειμῶνος ὑετοῦ γέμον ἵσταται κεχυμένον δὲ καὶ κεκραμένον εἰς τὸν ναὸν εἰσερρύη, καὶ ταῖς μὲν ὄψεσι τῶν ἱερέων ὡς μὴ καθορᾶν ἀλλήλους ἐπεσκότει, ταῖς δὲ διανοίαις ταῖς ἁπάντων φαντασίαν καὶ δόξαν παρεῖχεν ὡς τοῦ θεοῦ κατεληλυθότος εἰς τὸ ἱερὸν καὶ κατεσκηνωκότος ἡδέως ἐν αὐτῷ."},{"number":107,"text":"καὶ οἱ μὲν ἐπὶ ταύτης εἶχον αὑτοὺς τῆς ἐννοίας ὁ δὲ βασιλεὺς Σολόμων ἐξεγερθείς, ἔτυχε γὰρ καθεζόμενος, ἐποιήσατο λόγους πρὸς τὸν θεόν, οὓς τῇ θείᾳ φύσει πρέποντας ὑπελάμβανε καὶ καλῶς εἶχεν αὐτῷ λέγειν· σοὶ γάρ, εἶπεν, οἶκον μὲν αἰώνιον, ὦ δέσποτα, καὶ ἄξιον αὑτῷ εἰργάσω γεγονότα τὸν οὐρανὸν οἴδαμεν καὶ ἀέρα καὶ γῆν καὶ θάλασσαν, διʼ ὧν ἁπάντων οὐδὲ τούτοις ἀρκούμενος κεχώρηκας,"},{"number":108,"text":"τοῦτον δέ σοι κατεσκεύακα τὸν ναὸν ἐπώνυμον, ὡς ἂν ἀπʼ αὐτοῦ σοι τὰς εὐχὰς θύοντες καὶ καλλιεροῦντες ἀναπέμπωμεν εἰς τὸν ἀέρα καὶ πεπεισμένοι διατελοίημεν, ὅτι πάρει καὶ μακρὰν οὐκ ἀφέστηκας οὐδὲ σαυτῶ· τῷ μὲν γὰρ πάντʼ ἐφορᾶν καὶ πάντʼ ἀκούειν οὐδὲ νῦν ὅπου σοι θέμις οἰκῶν ἀπολείπεις τοῦ πᾶσιν ἔγγιστα εἶναι, μᾶλλον δʼ ἑκάστῳ καὶ βουλευομένῳ καὶ διὰ νυκτὸς καὶ ἡμέρας συμπάρει."},{"number":109,"text":"ταῦτα ἐπιθειάσας πρὸς τὸν θεὸν ἀπέστρεψεν εἰς τὸ πλῆθος τοὺς λόγους ἐμφανίζων τοῦ θεοῦ τὴν δύναμιν αὐτοῖς καὶ τὴν πρόνοιαν, ὅτι Δαυίδῃ τῷ πατρὶ περὶ τῶν μελλόντων ἅπαντα καθὼς ἀποβέβηκεν ἤδη τὰ πολλὰ καὶ γενήσεται τὰ λείποντα δηλώσειε, καὶ ὡς αὐτὸς ἐπιθείη τὸ ὄνομα μήπω γεγεννημένῳ καὶ"},{"number":110,"text":"τίς μέλλοι καλεῖσθαι προείποι καὶ ὅτι τὸν ναὸν οὗτος οἰκοδομήσει αὐτῷ βασιλεὺς μετὰ τὴν τοῦ πατρὸς τελευτὴν γενόμενος· ἃ βλέποντας κατὰ τὴν ἐκείνου προφητείαν ἐπιτελῆ τὸν θεὸν εὐλογεῖν ἠξίου καὶ περὶ μηδενὸς ἀπογινώσκειν ὧν ὑπέσχηται πρὸς εὐδαιμονίαν ὡς οὐκ ἐσομένου πιστεύοντας ἐκ τῶν ἤδη βλεπομένων."},{"number":111,"text":"Ταῦτα διαλεχθεὶς πρὸς τὸν ὄχλον ὁ βασιλεὺς ἀφορᾷ πάλιν εἰς τὸν ναὸν καὶ τὴν δεξιὰν εἰς τὸν ὄχλον ἀνασχών ἔργοις μέν, εἶπεν, οὐ δυνατὸν ἀνθρώποις ἀποδοῦναι θεῷ χάριν ὑπὲρ ὧν εὖ πεπόνθασιν· ἀπροσδεὲς γὰρ τὸ θεῖον ἁπάντων καὶ κρεῖττον τοιαύτης ἀμοιβῆς· ᾧ δὲ τῶν ἄλλων ζῴων ὑπὸ σοῦ, δέσποτα, κρείττονες γεγόναμεν, τούτῳ τὴν σὴν εὐλογεῖν μεγαλειότητα καὶ περὶ τῶν ὑπηργμένων εἰς τὸν ἡμέτερον οἶκον καὶ τὸν Ἑβραίων εὐχαριστεῖν ἀνάγκη."},{"number":112,"text":"τίνι γὰρ ἄλλῳ μᾶλλον ἱλάσασθαι μηνίοντα καὶ δυσμεναίνοντα εὐμενῆ δεξιώτερόν ἐστιν ἡμῖν ἢ φωνῇ, ἣν ἐξ ἀέρος τε ἔχομεν καὶ διʼ αὐτοῦ πάλιν ἀνιοῦσαν οἴδαμεν; χάριν οὖν ἔχειν διʼ αὐτῆς ὁμολογῶ σοι περί τε τοῦ πατρὸς πρῶτον, ὃν ἐξ ἀφανοῦς εἰς τοσαύτην ἀνήγαγες δόξαν,"},{"number":113,"text":"ἔπειθʼ ὑπὲρ ἐμαυτοῦ πάντα μέχρι τῆς παρούσης ἡμέρας ἃ προεῖπας πεποιηκότι, δέομαί τε τοῦ λοιποῦ χορηγεῖν ὅσα θεῷ δύναμις ἀνθρώποις ὑπὸ σοῦ τετιμημένοις, καὶ τὸν οἶκον τὸν ἡμέτερον αὔξειν εἰς πᾶν, ὡς καθωμολόγησας Δαυίδῃ τῷ πατρί μου καὶ ζῶντι καὶ παρὰ τὴν τελευτήν, ὅτι παρʼ ἡμῖν ἡ βασιλεία μενεῖ καὶ τὸ ἐκείνου γένος αὐτὴν διαδοχαῖς ἀμείψει μυρίαις. ταῦτʼ οὖν ἡμῖν ἐπάρκεσον καὶ παισὶ τοῖς ἐμοῖς ἀρετὴν ᾗ σὺ χαίρεις παράσχου."},{"number":114,"text":"πρὸς δὲ τούτοις ἱκετεύω καὶ μοῖράν τινα τοῦ σοῦ πνεύματος εἰς τὸν ναὸν ἀποικίσαι, ὡς ἂν καὶ ἐπὶ γῆς ἡμῖν εἶναι δοκῇς. σοὶ μὲν γὰρ μικρὸν οἰκητήριον καὶ τὸ πᾶν οὐρανοῦ καὶ τῶν κατὰ τοῦτον ὄντων κύτος, οὐχ ὅτι γε οὗτος ὁ τυχὼν ναός, ἀλλὰ φυλάσσειν τε ἀπόρθητον ἐκ πολεμίων ὡς ἴδιον εἰς ἅπαν καὶ προνοεῖν ὡς οἰκείου κτήματος παρακαλῶ."},{"number":115,"text":"κἂν ἁμαρτών ποτε ὁ λαὸς ἔπειτα πληγῇ τινι κακῷ διὰ τὴν ἁμαρτίαν ἐκ σοῦ γῆς ἀκαρπίᾳ καὶ φθορᾷ λοιμικῇ ἤ τινι τούτων τῶν παθημάτων, οἷς σὺ τοὺς παραβάντας τι τῶν ὁσίων μετέρχῃ, καὶ καταφεύγῃ πᾶς ἀθροισθεὶς ἐπὶ τὸν ναὸν ἱκετεύων σε καὶ σωθῆναι δεόμενος, ἐπήκοος αὐτοῦ γενόμενος ὡς ἔνδον ὢν ἐλεήσῃς καὶ τῶν συμφορῶν ἀπαλλάξῃς."},{"number":116,"text":"ταύτην δὲ οὐχ Ἑβραίοις μόνον δέομαι παρὰ σοῦ τὴν βοήθειαν εἶναι σφαλεῖσιν, ἀλλὰ κἂν ἀπὸ περάτων τῆς οἰκουμένης τινὲς ἀφίκωνται κἂν ὁποθενδηποτοῦν προστρεπόμενοι καὶ τυχεῖν τινος ἀγαθοῦ λιπαροῦντες, δὸς αὐτοῖς ἐπήκοος γενόμενος."},{"number":117,"text":"οὕτως γὰρ ἂν μάθοιεν πάντες, ὅτι σὺ μὲν αὐτὸς ἐβουλήθης παρʼ ἡμῖν κατασκευασθῆναί σοι τὸν οἶκον, ἡμεῖς δʼ οὐκ ἀπάνθρωποι τὴν φύσιν ἐσμὲν οὐδʼ ἀλλοτρίως πρὸς τοὺς οὐχ ὁμοφύλους ἔχομεν, ἀλλὰ πᾶσι κοινὴν τὴν ἀπὸ σοῦ βοήθειαν καὶ τὴν τῶν ἀγαθῶν ὄνησιν ὑπάρχειν ἠθελήσαμεν."},{"number":118,"text":"Εἰπὼν ταῦτα καὶ ῥίψας αὑτὸν ἐπὶ τὴν γῆν καὶ ἐπὶ πολλὴν ὥραν προσκυνήσας ἀναστὰς θυσίας τῷ θεῷ προσήνεγκε καὶ γεμίσας τῶν ὁλοκλήρων ἱερείων ἐναργέστατα τὸν θεὸν ἡδέως ἔγνω τὴν θυσίαν προσδεχόμενον· πῦρ γὰρ ἐξ ἀέρος διαδραμὸν καὶ πάντων ὁρώντων ἐπὶ τὸν βωμὸν ᾆξαν ἅπασαν τὴν θυσίαν ἀνήρπασε καὶ κατεδαίσατο."},{"number":119,"text":"ταύτης δὲ τῆς ἐπιφανείας γενομένης ὁ μὲν λαὸς δήλωσιν εἶναι τοῦτʼ εἰκάσας τῆς ἐν τῷ ναῷ τοῦ θεοῦ διατριβῆς ἐσομένης καὶ ἡσθεὶς προσεκύνει πεσὼν ἐπὶ τοὔδαφος, ὁ δὲ βασιλεὺς εὐλογεῖν τε ἤρξατο καὶ τὸ πλῆθος ταὐτὸ ποιεῖν παρώρμα δείγματα μὲν ἔχοντας ἤδη τῆς τοῦ θεοῦ πρὸς αὐτοὺς εὐμενείας,"},{"number":120,"text":"εὐχομένους δὲ τοιαῦτα ἀποβαίνειν ἀεὶ τὰ παρʼ ἐκείνου, καὶ τὴν διάνοιαν αὐτοῖς καθαρὰν ἀπὸ πάσης φυλάττεσθαι κακίας ἐν δικαιοσύνῃ καὶ θρησκείᾳ καὶ τῷ τὰς ἐντολὰς τηρεῖν ἃς διὰ Μωυσέος αὐτοῖς ἔδωκεν ὁ θεὸς διαμενούσας· ἔσεσθαι γὰρ οὕτως εὔδαιμον τὸ Ἑβραίων ἔθνος καὶ παντὸς ἀνθρώπων γένους μακαριώτερον."},{"number":121,"text":"παρεκάλει τε μνημονεύειν, ὡς οἷς ἐκτήσαντο τὰ παρόντα ἀγαθὰ τούτοις αὐτὰ καὶ βέβαια ἕξειν καὶ μείζω καὶ πλείω καταστήσειν· οὐ γὰρ λαβεῖν αὐτὰ μόνον διʼ εὐσέβειαν καὶ δικαιοσύνην, ἀλλὰ καὶ καθέξειν διὰ ταῦτα προσῆκεν ὑπολαμβάνειν· εἶναι δὲ τοῖς ἀνθρώποις οὐχ οὕτως μέγα τὸ κτήσασθαί τι τῶν οὐχ ὑπαρχόντων, ὡς τὸ σῶσαι τὰ πορισθέντα καὶ μηδὲν ἁμαρτεῖν εἰς. βλάβην αὐτῶν."},{"number":122,"text":"Ὁ μὲν οὖν βασιλεὺς διαλεχθεὶς ταῦτα πρὸς τὸ πλῆθος διαλύει τὴν ἐκκλησίαν τελέσας θυσίας ὑπέρ τε αὑτοῦ καὶ πάντων Ἑβραίων, ὡς μόσχους μὲν καταθῦσαι μυρίους καὶ δισχιλίους, προβάτων δὲ μυριάδας δώδεκα."},{"number":123,"text":"τὸν μὲν γὰρ ναὸν τότε πρῶτον ἔγευσεν ἱερουργημάτων καὶ κατευωχήθησαν ἐν αὐτῷ πάντες σὺν γυναιξὶν Ἑβραῖοι καὶ τέκνοις, ἔτι δὲ καὶ τὴν σκηνοπηγίαν καλουμένην ἑορτὴν πρὸ τοῦ ναοῦ λαμπρῶς καὶ μεγαλοπρεπῶς ἐπὶ δὶς ἑπτὰ ἡμέρας ἤγαγεν ὁ βασιλεὺς σὺν ἅπαντι τῷ λαῷ κατευωχούμενος."},{"number":124,"text":"Ἐπεὶ δʼ εἶχεν αὐτοῖς ἀποχρώντως ταῦτα καὶ μηδὲν ἐνέδει τῇ περὶ τὸν θεὸν εὐσεβείᾳ πρὸς αὑτοὺς ἕκαστος τοῦ βασιλέως ἀπολύσαντος ἀπῄεσαν εὐχαριστήσαντες τῷ βασιλεῖ τῆς τε περὶ αὐτοὺς προνοίας καὶ ὧν ἐπεδείξατο ἔργων, καὶ εὐξάμενοι τῷ θεῷ παρασχεῖν αὐτοῖς εἰς πολὺν χρόνον Σολόμωνα βασιλέα τὴν πορείαν ἐποιοῦντο μετὰ χαρᾶς καὶ παιδιᾶς ὕμνους εἰς τὸν θεὸν ᾄδοντες, ὡς ὑπὸ τῆς ἡδονῆς ἀπόνως τὴν ὁδὸν τὴν ἐπὶ τὰ οἰκεῖα πάντας ἀνύσαι."},{"number":125,"text":"καὶ οἱ μὲν τὴν κιβωτὸν εἰς τὸν ναὸν εἰσαγαγόντες καὶ τὸ μέγεθος καὶ τὸ κάλλος ἱστορήσαντες αὐτοῦ καὶ θυσιῶν ἐπʼ αὐτῷ μεγάλων καὶ ἑορτῶν μεταλαβόντες εἰς τὰς αὑτῶν ἕκαστοι πόλεις ὑπέστρεψαν. ὄναρ δʼ ἐπιφανὲν τῷ βασιλεῖ κατὰ τοὺς ὕπνους ἐσήμαινεν αὐτῷ τῆς εὐχῆς ἐπήκοον τὸν θεὸν γεγονέναι,"},{"number":126,"text":"καὶ ὅτι φυλάξει τε τὸν ναὸν καὶ διὰ παντὸς ἐν αὐτῷ μενεῖ τῶν ἐκγόνων αὐτοῦ καὶ αὐτοῦ καὶ τῆς ἁπάσης πληθύος τὰ δίκαια ποιούσης, αὐτόν τε πρῶτον ἐμμένοντα ταῖς τοῦ πατρὸς ὑποθήκαις ἔλεγεν εἰς ὕψος καὶ μέγεθος εὐδαιμονίας ἀνοίσειν ἄπειρον καὶ βασιλεύσειν ἀεὶ τῆς χώρας τοὺς ἐκ τοῦ γένους αὐτοῦ καὶ τῆς Ἰούδα φυλῆς·"},{"number":127,"text":"προδόντα μέντοι τὰ ἐπιτηδεύματα καὶ λήθην αὐτῶν ποιησάμενον καὶ ξενικοὺς θεοὺς θρησκεύειν μεταβαλόμενον πρόρριζον ἐκκόψειν καὶ μήτε τοῦ γένους τι λείψανον αὐτῶν ἐάσειν μήτε τὸν τῶν Ἰσραηλιτῶν λαὸν ἀπαθῆ παρόψεσθαι, πολέμοις δʼ αὐτοὺς καὶ κακοῖς ἐξαφανίσειν μυρίοις κἀκ τῆς γῆς, ἣν τοῖς πατράσιν αὐτῶν ἔδωκεν,"},{"number":128,"text":"ἐκβαλὼν ἐπήλυδας ἀλλοτρίας καταστήσειν, τὸν δὲ ναὸν τὸν νῦν οἰκοδομηθέντα καταπρησθησόμενον τοῖς ἐχθροῖς παραδώσειν καὶ διαρπαγησόμενον, κατασκάψειν δὲ καὶ τὴν πόλιν χερσὶ τῶν πολεμίων καὶ ποιήσειν μύθων ἄξια τὰ παρʼ αὐτοῖς κακὰ καὶ πολλῆς διʼ ὑπερβολὴν μεγέθους ἀπιστίας,"},{"number":129,"text":"ὡς τοὺς προσοίκους ἀκούοντας τὴν συμφορὰν θαυμάζειν καὶ τὴν αἰτίαν πολυπραγμονεῖν διʼ ἣν οὕτως ἐμισήθησαν Ἑβραῖοι τῷ θεῷ πρότερον εἰς δόξαν καὶ πλοῦτον ὑπʼ αὐτοῦ παραχθέντες, καὶ παρὰ τῶν ὑπολειπομένων ἀκούειν ἐξομολογουμένων τὰς ἁμαρτίας αὐτῶν καὶ τὰς τῶν πατρίων νομίμων παραβάσεις. ταῦτα μὲν αὐτῷ τὸν θεὸν εἰπεῖν κατὰ τοὺς ὕπνους ἀναγέγραπται."}],"5":[{"number":130,"text":"Μετὰ δὲ τὴν τοῦ ναοῦ κατασκευὴν ἐν ἔτεσιν ἑπτὰ καθὼς προειρήκαμεν γενομένην τὴν τῶν βασιλείων οἰκοδομὴν κατεβάλετο, ἣν ἔτεσι τρισὶ καὶ δέκα μόγις ἀπήρτισεν· οὐ γὰρ τὸν αὐτὸν ἐσπουδάζετο τρόπον ὅνπερ καὶ τὸ ἱερόν, ἀλλὰ τὸ μὲν καίπερ ὂν μέγα καὶ θαυμαστῆς ἐργασίας καὶ παραδόξου τετυχηκὸς ἔτι καὶ θεοῦ συνεργοῦντος, εἰς ὃν ἐγίνετο, τοῖς προειρημένοις ἔτεσιν ἔλαβε πέρας·"},{"number":131,"text":"τὰ δὲ βασίλεια πολὺ τῆς ἀξίας τοῦ ναοῦ καταδεέστερα τυγχάνοντα τῷ μήτε τὴν ὕλην ἐκ τοσούτου χρόνου καὶ τῆς αὐτῆς ἡτοιμάσθαι φιλοτιμίας καὶ βασιλεῦσιν οἰκητήριον ἀλλʼ οὐ θεῷ γίνεσθαι, βράδιον ἠνύσθη."},{"number":132,"text":"καὶ αὐτὰ μὲν οὖν ἄξια λόγου καὶ κατὰ τὴν εὐδαιμονίαν τῆς Ἑβραίων χώρας καὶ τοῦ βασιλέως ᾠκοδομήθη, τὴν δὲ ὅλην αὐτῶν διάταξιν καὶ τὴν διάθεσιν εἰπεῖν ἀναγκαῖον, ἵνʼ οὕτως ἐκ τούτου στοχάζεσθαι καὶ συνορᾶν ἔχωσι τὸ μέγεθος οἱ τῇ γραφῇ μέλλοντες ἐντυγχάνειν."},{"number":133,"text":"Οἶκος ἦν μέγας καὶ καλὸς πολλοῖς στύλοις ἐρηρεισμένος, ὃν εἰς τὰς κρίσεις καὶ τὴν τῶν πραγμάτων διάγνωσιν πλῆθος ὑποδέξασθαι καὶ χωρῆσαι σύνοδον ἀνθρώπων ἐπὶ δίκας συνεληλυθότων κατεσκεύασεν ἑκατὸν μὲν πηχῶν τὸ μῆκος εὖρος δὲ πεντήκοντα τὸ δʼ ὕψος τριάκοντα, κίοσι μὲν τετραγώνοις ἀνειλημμένον ἐκ κέδρου πᾶσιν, ἐστεγασμένον δὲ Κορινθίως, ἰσομέτροις δὲ φλιαῖς καὶ θυρώμασι τριγλύφοις ἀσφαλῆ τε ὁμοῦ καὶ κεκαλλωπισμένον."},{"number":134,"text":"ἕτερος δὲ οἶκος ἦν ἐν μέσῳ κατὰ ὅλου τοῦ πλάτους τεταγμένος τετράγωνος εὖρος πηχῶν τριάκοντα, ἄντικρυς ἔχων ναὸν παχέσι στύλοις ἀνατεταμένον· ἦν δὲ ἐν αὐτῷ ἐξέδρα διαπρεπής, ἐν ᾗ καθεζόμενος ὁ βασιλεὺς ἔκρινεν, ᾗ παρέζευκτο κατεσκευασμένος ἄλλος οἶκος τῇ βασιλίσσῃ καὶ τὰ λοιπὰ τὰ πρὸς τὴν δίαιταν καὶ τὰς ἀναπαύσεις οἰκήματα μετὰ τὴν τῶν πραγμάτων ἀπόλυσιν, ἐστρωμένα πάντα σανίσι τετμημέναις ἐκ κέδρου."},{"number":135,"text":"καὶ τὰ μὲν ᾠκοδομήσατο λίθοις δεκαπήχεσιν, ἑτέρῳ δὲ πριστῷ τοὺς τοίχους καὶ πολυτελεῖ κατημφίεσεν, ὃν εἰς κόσμον ἱερῶν καὶ βασιλείων οἴκων θεωρίων γῆ μεταλλεύεται τοῖς φέρουσιν αὐτὸν τόποις ἐπαινουμένη."},{"number":136,"text":"καὶ τὸ μὲν ἀπʼ αὐτοῦ κάλλος ἐπὶ τριστιχίαν ἦν ἐνυφασμένον, τετάρτη δὲ μοῖρα γλυφέων παρεῖχε θαυμάζειν ἐπιστήμην, ὑφʼ ὧν πεποίητο δένδρα καὶ φυτὰ παντοῖα σύσκια τοῖς κλάδοις καὶ τοῖς ἐκκρεμαμένοις αὐτῶν πετάλοις, ὡς ὑπονοεῖν αὐτὰ καὶ σαλεύεσθαι διʼ ὑπερβολὴν λεπτότητος καλύπτοντα τὸν ὑπʼ αὐτοῖς λίθον."},{"number":137,"text":"τὸ δὲ ἄλλο μέχρι τῆς στέγης χριστὸν ἦν καὶ καταπεποικιλμένον χρώμασι καὶ βαφαῖς. προσκατεσκεύασε δὲ τούτοις ἄλλα τε πρὸς τρυφὴν οἰκήματα καὶ δὴ καὶ στοὰς μηκίστας καὶ ἐν καλῷ τῶν βασιλείων κειμένας, ἐν αἷς λαμπρότατον οἶκον εἰς ἑστίασιν καὶ συμπόσια χρυσοῦ περίπλεων· καὶ τἆλλα δὲ ὅσα τοῦτον ἔχειν ἔδει πρὸς τὴν τῶν ἑστιωμένων ὑπηρεσίαν σκεύη πάντʼ ἐκ χρυσοῦ κατεσκεύαστο."},{"number":138,"text":"δύσκολον δʼ ἐστὶν καταριθμήσασθαι τὸ μέγεθος καὶ τὴν ποικιλίαν τῶν βασιλείων, ὅσα μὲν ἦν αὐτοῖς τὰ μέγιστα οἰκήματα, πόσα δὲ τὰ τούτων ὑποδεέστερα καὶ πόσα ὑπόγεια καὶ ἀφανῆ, τά τε τῶν ἀνειμένων εἰς ἀέρα κάλλη καὶ τὰ ἄλση πρὸς θεωρίαν ἐπιτερπεστάτην καὶ θέρους ὑποφυγὴν καὶ σκέπην εἶναι τοῖς σώμασιν."},{"number":139,"text":"ἐν κεφαλαίῳ δʼ εἰπεῖν τὴν ὅλην οἰκοδομίαν ἐκ λίθου λευκοῦ καὶ κέδρου καὶ χρυσοῦ καὶ ἀργύρου πᾶσαν ἐποιήσατο τοὺς ὀρόφους καὶ τοὺς τοίχους τοῖς ἐγκλειομένοις χρυσῷ λίθοις διανθίσας τὸν αὐτὸν τρόπον, ὡς καὶ τὸν τοῦ θεοῦ ναὸν τούτοις κατηγλάισεν."},{"number":140,"text":"εἰργάσατο δὲ καὶ ἐξ ἐλέφαντος θρόνον παμμεγεθέστατον ἐν κατασκευῇ βήματος ἔχοντα μὲν ἓξ βαθμούς, ἑκάστῳ δὲ τούτων ἐξ ἑκατέρου μέρους δύο λέοντες ἐφειστήκεσαν τοσούτων ἄνωθεν ἄλλων παρεστώτων. τὸ δʼ ἐνήλατον τοῦ θρόνου χεῖρες ἦσαν δεχόμεναι τὸν βασιλέα, ἀνακέκλιτο δʼ εἰς μόσχου προτομὴν τὰ κατόπιν αὐτοῦ βλέποντος, χρυσῷ δὲ ἅπας ἦν δεδεμένος."},{"number":141,"text":"Ταῦτα Σολόμων εἰκοσαετίᾳ κατασκευάσας, ἐπεὶ πολὺν μὲν αὐτῷ χρυσὸν πλείω δʼ ἄργυρον ὁ τῶν Τυρίων βασιλεὺς Εἴρωμος εἰς τὴν οἰκοδομίαν συνήνεγκεν ἔτι δὲ καὶ ξύλα κέδρου καὶ πίτυος, ἀντεδωρήσατο καὶ αὐτὸς μεγάλαις δωρεαῖς τὸν Εἴρωμον σῖτόν τε κατʼ ἔτος πέμπων αὐτῷ καὶ οἶνον καὶ ἔλαιον, ὧν μάλιστα διὰ τὸ νῆσον οἰκεῖν, ὡς καὶ προειρήκαμεν ἤδη, χρῄζων διετέλει."},{"number":142,"text":"πρὸς τούτοις δὲ καὶ πόλεις αὐτῷ τῆς Γαλιλαίας εἴκοσι μὲν τὸν ἀριθμὸν οὐ πόρρω δὲ τῆς Τύρου κειμένας ἐχαρίσατο, ἃς ἐπελθὼν καὶ κατανοήσας Εἴρωμος καὶ δυσαρεστήσας τῇ δωρεᾷ πέμψας πρὸς Σολόμωνα μὴ δεῖσθαι τῶν πόλεων ἔλεγε κἄκτοτε προσηγορεύθησαν Χαβαλὼν γῆ· μεθερμηνευόμενον δὲ τὸ χάβαλον κατὰ Φοινίκων γλῶτταν οὐκ ἀρέσκον σημαίνει."},{"number":143,"text":"καὶ σοφίσματα δὲ καὶ λόγους αἰνιγματώδεις διεπέμψατο πρὸς Σολόμωνα ὁ τῶν Τυρίων βασιλεὺς παρακαλῶν, ὅπως αὐτῷ σαφηνίσῃ τούτους καὶ τῆς ἀπορίας τῶν ἐν αὐτοῖς ζητουμένων ἀπαλλάξῃ. τὸν δὲ δεινὸν ὄντα καὶ συνετὸν οὐδὲν τούτων παρῆλθεν, ἀλλὰ πάντα νικήσας τῷ λογισμῷ καὶ μαθὼν αὐτῶν τὴν διάνοιαν ἐφώτισε."}],"6":[{"number":144,"text":"Μέμνηται τούτων τῶν δύο βασιλέων καὶ Μένανδρος ὁ μεταφράσας ἀπὸ τῆς Φοινίκων διαλέκτου τὰ Τυρίων ἀρχεῖα εἰς τὴν Ἑλληνικὴν φωνὴν λέγων οὕτως· τελευτήσαντος δὲ Ἀβιβάλου διεδέξατο τὴν βασιλείαν παρʼ αὐτοῦ υἱὸς Εἴρωμος, ὃς βιώσας ἔτη πεντηκοντατρία ἐβασίλευσε τριάκοντα καὶ τέσσαρα."},{"number":145,"text":"οὗτος ἔχωσε τὸ Εὐρύχωρον τόν τε χρυσοῦν κίονα τὸν ἐν τοῖς τοῦ Διὸς ἀνέθηκεν· ἔτι τε ὕλην ξύλων ἀπελθὼν ἔκοψεν ἀπὸ τοῦ ὄρους τοῦ λεγομένου Λιβάνου εἰς τὰς τῶν ἱερῶν στέγας·"},{"number":146,"text":"καθελών τε τὰ ἀρχαῖα ἱερὰ καὶ ναὸν ᾠκοδόμησε τοῦ Ἡρακλέους καὶ τῆς Ἀστάρτης, πρῶτός τε τοῦ Ἡρακλέους ἔγερσιν ἐποιήσατο ἐν τῷ Περιτίῳ μηνί· τοῖς τε Ἰτυκαίοις ἐπεστρατεύσατο μὴ ἀποδιδοῦσι τοὺς φόρους καὶ ὑποτάξας πάλιν αὑτῷ ἀνέστρεψεν. ἐπὶ τούτου ἦν Ἀβδήμονος παῖς νεώτερος, ὃς ἀεὶ ἐνίκα τὰ προβλήματα, ἃ ἐπέτασσε Σολόμων ὁ Ἱεροσολύμων βασιλεύς."},{"number":147,"text":"μνημονεύει δὲ καὶ Δῖος λέγων οὕτως· Ἀβιβάλου τελευτήσαντος ὁ υἱὸς αὐτοῦ Εἴρωμος ἐβασίλευσεν. οὗτος τὰ πρὸς ἀνατολὰς μέρη τῆς πόλεως προσέχωσε καὶ μεῖζον τὸ ἄστυ ἐποίησε καὶ τοῦ Ὀλυμπίου Διὸς τὸ ἱερὸν καθʼ ἑαυτὸ ὂν ἐγχώσας τὸν μεταξὺ τόπον συνῆψε τῇ πόλει καὶ χρυσοῖς ἀναθήμασιν ἐκόσμησεν· ἀναβὰς δὲ εἰς τὸν Λίβανον ὑλοτόμησε πρὸς τὴν τῶν ἱερῶν κατασκευήν."},{"number":148,"text":"τὸν δὲ τυραννοῦντα Ἱεροσολύμων Σολόμωνα πέμψαι φησὶ πρὸς Εἴρωμον αἰνίγματα καὶ παρʼ αὐτοῦ λαβεῖν ἀξιοῦντα, τὸν δὲ μὴ δυνηθέντα διακρῖναι τῷ λύσαντι χρήματα ἀποτίνειν."},{"number":149,"text":"ὁμολογήσαντα δὲ τὸν Εἴρωμον καὶ μὴ δυνηθέντα λῦσαι τὰ αἰνίγματα πολλὰ τῶν χρημάτων εἰς τὸ ἐπιζήμιον ἀναλῶσαι· εἶτα δὲ Ἀβδήμονά τινα Τύριον ἄνδρα τὰ προτεθέντα λῦσαι καὶ αὐτὸν ἄλλα προβαλεῖν, ἃ μὴ λύσαντα τὸν Σολόμωνα πολλὰ τῷ Εἰρώμῳ προσαποτῖσαι χρήματα. καὶ Δῖος μὲν οὕτως εἴρηκεν."},{"number":150,"text":"Ἐπεὶ δʼ ἑώρα τὰ τῶν Ἱεροσολύμων τείχη ὁ βασιλεὺς πύργων πρὸς ἀσφάλειαν δεόμενα καὶ τῆς ἄλλης ὀχυρότητος, πρὸς γὰρ τἀξίωμα τῆς πόλεως ἡγεῖτο δεῖν καὶ τοὺς περιβόλους εἶναι, ταῦτά τε προσεπεσκεύαζε καὶ πύργοις αὐτὰ μεγάλοις προσεξῇρεν."},{"number":151,"text":"ᾠκοδόμησε δὲ καὶ πόλεις ταῖς βαρυτάταις ἐναρίθμους Ἄσωρόν τε καὶ Μαγέδω, τὴν τρίτην δὲ Γάζαρα, ἣν τῆς Παλαιστίνων χώρας ὑπάρχουσαν Φαραώνης ὁ τῶν Αἰγυπτίων βασιλεὺς στρατευσάμενος καὶ πολιορκήσας αἱρεῖ κατὰ κράτος· ἀποκτείνας δὲ πάντας τοὺς ἐνοικοῦντας αὐτὴν κατέσκαψεν, εἶτα δωρεὰν ἔδωκεν τῇ θυγατρὶ Σολόμωνι γεγαμημένῃ."},{"number":152,"text":"διὸ καὶ ἀνήγειρεν αὐτὴν ὁ βασιλεὺς οὖσαν ὀχυρὰν φύσει καὶ πρὸς πολέμους καὶ τὰς τῶν καιρῶν μεταβολὰς χρησίμην εἶναι δυναμένην. οὐ πόρρω δʼ αὐτῆς ἄλλας ᾠκοδόμησε δύο πόλεις· Βητχώρα τῇ ἑτέρᾳ ὄνομα ἦν, ἡ δʼ ἑτέρα Βελὲθ ἐκαλεῖτο."},{"number":153,"text":"προσκατεσκεύασε δὲ ταύταις καὶ ἄλλας εἰς ἀπόλαυσιν καὶ τρυφὴν ἐπιτηδείως ἐχούσας τῇ τε τῶν ἀέρων εὐκρασίᾳ καὶ τοῖς ὡραίοις εὐφυεῖς καὶ νάμασιν ὑδάτων ἐνδρόσους. ἐμβαλὼν δὲ καὶ εἰς τὴν ἔρημον τῆς ἐπάνω Συρίας καὶ κατασχὼν αὐτὴν ἔκτισεν ἐκεῖ πόλιν μεγίστην δύο μὲν ἡμερῶν ὁδὸν ἀπὸ τῆς ἄνω Συρίας διεστῶσαν, ἀπὸ δʼ Εὐφράτου μιᾶς, ἀπὸ δὲ τῆς μεγάλης Βαβυλῶνος ἓξ ἡμερῶν ἦν τὸ μῆκος."},{"number":154,"text":"αἴτιον δὲ τοῦ τὴν πόλιν οὕτως ἀπὸ τῶν οἰκουμένων μερῶν τῆς Συρίας ἀπῳκίσθαι τὸ κατωτέρω μὲν μηδαμοῦ τῆς γῆς ὕδωρ εἶναι, πηγὰς δʼ ἐν ἐκείνῳ τῷ τόπῳ μόνον εὑρεθῆναι καὶ φρέατα. ταύτην οὖν τὴν πόλιν οἰκοδομήσας καὶ τείχεσιν ὀχυρωτάτοις περιβαλὼν Θαδάμοραν ὠνόμασε καὶ τοῦτʼ ἔτι νῦν καλεῖται παρὰ τοῖς Σύροις, οἱ δʼ Ἕλληνες αὐτὴν προσαγορεύουσι Πάλμυραν."},{"number":155,"text":"Σολόμων μὲν οὖν ὁ βασιλεὺς ταῦτα κατʼ ἐκεῖνον τὸν καιρὸν πράττων διετέλει. πρὸς δὲ τοὺς ἐπιζητήσαντας, ὅτι πάντες οἱ Αἰγυπτίων βασιλεῖς ἀπὸ Μιναίου τοῦ Μέμφιν οἰκοδομήσαντος, ὃς ἔτεσι πολλοῖς ἔμπροσθεν ἐγένετο τοῦ πάππου ἡμῶν Ἁβράμου, μέχρι Σολόμωνος πλειόνων ἐτῶν τριακοσίων καὶ χιλίων μεταξὺ διεληλυθότων Φαραῶθαι ἐκλήθησαν ἀπὸ τοῦ μετʼ αὐτοὺς ἐν τοῖς μεταξὺ χρόνοις ἄρξαντος βασιλέως Φαραώθου τὴν προσηγορίαν λαβόντες, ἀναγκαῖον ἡγησάμην εἰπεῖν, ἵνα τὴν ἄγνοιαν αὐτῶν ἀφέλω καὶ ποιήσω τοῦ ὀνόματος φανερὰν τὴν αἰτίαν, ὅτι Φαραὼ κατʼ Αἰγυπτίους βασιλέα σημαίνει."},{"number":156,"text":"οἶμαι δʼ αὐτοὺς ἐκπαίδων ἄλλοις χρωμένους ὀνόμασιν ἐπειδὰν βασιλεῖς γένωνται τὸ σημαῖνον αὐτῶν τὴν ἐξουσίαν κατὰ τὴν πάτριον γλῶτταν μετονομάζεσθαι· καὶ γὰρ οἱ τῆς Ἀλεξανδρείας βασιλεῖς ἄλλοις ὀνόμασι καλούμενοι πρότερον ὅτε τὴν βασιλείαν ἔλαβον Πτολεμαῖοι προσηγορεύθησαν ἀπὸ τοῦ πρώτου βασιλέως."},{"number":157,"text":"καὶ οἱ Ῥωμαίων δὲ αὐτοκράτορες ἐκ γενετῆς ἀπʼ ἄλλων χρηματίσαντες ὀνομάτων Καίσαρες καλοῦνται τῆς ἡγεμονίας καὶ τῆς τιμῆς τὴν προσηγορίαν αὐτοῖς θεμένης ἀλλʼ οὐχ οἷς ὑπὸ τῶν πατέρων ἐκλήθησαν τούτοις ἐπιμένοντες. νομίζω δὲ καὶ Ἡρόδοτον τὸν Ἁλικαρνασέα διὰ τοῦτο μετὰ Μιναίαν τὸν οἰκοδομήσαντα Μέμφιν τριάκοντα καὶ τριακοσίους βασιλεῖς Αἰγυπτίων γενέσθαι λέγοντα μὴ δηλῶσαι αὐτῶν τὰ ὀνόματα, ὅτι κοινῶς Φαραῶθʼ ἐκαλοῦντο·"},{"number":158,"text":"καὶ γὰρ μετὰ τὴν τούτων τελευτὴν γυναικὸς βασιλευσάσης λέγει τοὔνομα Νικαύλην καλῶν δηλῶν, ὡς τῶν μὲν ἀρρένων βασιλέων τὴν αὐτὴν προσηγορίαν ἔχειν δυναμένων, τῆς δὲ γυναικὸς οὐκέτι κοινωνεῖν ἐκείνης, καὶ διὰ τοῦτʼ εἶπεν αὐτῆς τὸ φύσει δεῆσαν ὄνομα."},{"number":159,"text":"ἐγὼ δὲ καὶ ἐν τοῖς ἐπιχωρίοις ἡμῶν βιβλίοις εὗρον, ὅτι μετὰ Φαραώθην τὸν Σολόμωνος πενθερὸν οὐκέτʼ οὐδεὶς τοῦτο τὸ ὄνομα βασιλεὺς Αἰγυπτίων ἐκλήθη, καὶ ὅτι ὕστερον ἧκε πρὸς Σολόμωνα ἡ προειρημένη γυνὴ βασιλεύουσα τῆς Αἰγύπτου καὶ τῆς Αἰθιοπίας. περὶ μὲν οὖν ταύτης μετʼ οὐ πολὺ δηλώσομεν· νῦν δὲ τούτων ἐπεμνήσθην, ἵνα παραστήσω τὰ ἡμέτερα βιβλία καὶ τὰ παρʼ Αἰγυπτίοις περὶ πολλῶν ὁμολογοῦντα."},{"number":160,"text":"Ὁ δὲ βασιλεὺς Σολόμων τοὺς ἔτι τῶν Χαναναίων οὐχ ὑπακούοντας, οἳ ἐν τῷ Λιβάνῳ διέτριβον ὄρει καὶ μέχρι πόλεως Ἀμάθης, ὑποχειρίους ποιησάμενος φόρον αὐτοῖς προσέταξε καὶ πρὸς τὸ θητεύειν αὐτῷ καὶ τὰς οἰκετικὰς χρείας ἐκτελεῖν καὶ πρὸς γεωργίαν κατʼ ἔτος ἐξ αὐτῶν ἐπελέγετο."},{"number":161,"text":"τῶν γὰρ Ἑβραίων οὐδεὶς ἐδούλευεν οὐδʼ ἦν εὔλογον ἔθνη πολλὰ τοῦ θεοῦ δεδωκότος αὐτοῖς ὑποχείρια, δέον ἐκ τούτων ποιεῖσθαι τὸ θητικόν, αὐτοὺς κατάγειν εἰς τοῦτο τὸ σχῆμα, ἀλλὰ πάντες ἐν ὅπλοις ἐφʼ ἁρμάτων καὶ ἵππων στρατευόμενοι μᾶλλον ἢ δουλεύοντες διῆγον."},{"number":162,"text":"τῶν δὲ Χαναναίων, οὓς εἰς τὴν οἰκετείαν ἀπήγαγεν. ἄρχοντας ἀπέδειξε πεντακοσίους καὶ πεντήκοντα τὸν ἀριθμόν, οἳ τὴν ὅλην αὐτῶν ἐπιτροπὴν εἰλήφεσαν παρὰ τοῦ βασιλέως, ὥστε διδάσκειν αὐτοὺς τὰ ἔργα καὶ τὰς πραγματείας, ἐφʼ ἃς ἂν αὐτῶν ἔχρῃζεν."},{"number":163,"text":"Ἐναυπηγήσατο δὲ ὁ βασιλεὺς ἐν τῷ Αἰγυπτιακῷ κόλπῳ σκάφη πολλὰ τῆς Ἐρυθρᾶς θαλάσσης ἔν τινι τόπῳ λεγομένῳ Γασίων Γάβελος οὐ πόρρω Ἰλάνεως πόλεως, ἣ νῦν Βερενίκη καλεῖται· αὕτη γὰρ ἡ χώρα τὸ πρὶν Ἰουδαίων ἦν. ἔτυχε δὲ καὶ τῆς ἁρμοζούσης εἰς τὰς ναῦς δωρεᾶς παρʼ Εἰρώμου τοῦ Τυρίων βασιλέως·"},{"number":164,"text":"ἄνδρας γὰρ αὐτῷ κυβερνήτας καὶ τῶν θαλασσίων ἐπιστήμονας ἔπεμψεν ἱκανούς, οἷς ἐκέλευσε πλεύσαντας μετὰ τῶν ἰδίων οἰκονόμων εἰς τὴν πάλαι μὲν Σώφειραν νῦν δὲ χρυσῆν γῆν καλουμένην, τῆς Ἰνδικῆς ἐστιν αὕτη, χρυσὸν αὐτῷ κομίσαι. καὶ συναθροίσαντες ὡς τετρακόσια τάλαντα πάλιν ἀνεχώρησαν πρὸς τὸν βασιλέα."},{"number":165,"text":"Τὴν δὲ τῆς Αἰγύπτου καὶ τῆς Αἰθιοπίας τότε βασιλεύουσαν γυναῖκα σοφίᾳ διαπεπονημένην καὶ τἆλλα θαυμαστὴν ἀκούουσαν τὴν Σολόμωνος ἀρετὴν καὶ φρόνησιν ἐπιθυμία τῆς ὄψεως αὐτοῦ ἐκ τῶν ὁσημέραι περὶ τῶν ἐκεῖ λεγομένων πρὸς αὐτὸν ἤγαγε·"},{"number":166,"text":"πεισθῆναι γὰρ ὑπὸ τῆς πείρας ἀλλʼ οὐχ ὑπὸ τῆς ἀκοῆς, ἣν εἰκός ἐστι καὶ ψευδεῖ δόξῃ συγκατατίθεσθαι καὶ μεταπεῖσαι πάλιν, ὅλη γὰρ ἐπὶ τοῖς ἀπαγγέλλουσι κεῖται, θέλουσα πρὸς αὐτὸν ἐλθεῖν διέγνω, μάλιστα καὶ τῆς σοφίας αὐτοῦ βουλομένη λαβεῖν πεῖραν αὐτὴ προτείνασα καὶ λῦσαι τὸ ἄπορον τῆς διανοίας δεηθεῖσα ἧκεν εἰς Ἱεροσόλυμα μετὰ πολλῆς δόξης καὶ πλούτου παρασκευῆς·"},{"number":167,"text":"ἐπηγάγετο γὰρ καμήλους χρυσίου μεστὰς καὶ ἀρωμάτων ποικίλων καὶ λίθων πολυτελῶν. ὡς δʼ ἀφικομένην αὐτὴν ἡδέως ὁ βασιλεὺς προσεδέξατο. τά τε ἄλλα περὶ αὐτὴν φιλότιμος ἦν καὶ τὰ προβαλλόμενα σοφίσματα ῥᾳδίως τῇ συνέσει καταλαμβανόμενος θᾶττον ἢ προσεδόκα τις ἐπελύετο."},{"number":168,"text":"ἡ δʼ ἐξεπλήσσετο μὲν καὶ τὴν σοφίαν τοῦ Σολόμωνος οὕτως ὑπερβάλλουσαν αὐτὴν καὶ τῆς ἀκουομένης τῇ πείρᾳ κρείττω καταμαθοῦσα, μάλιστα δʼ ἐθαύμαζε τὰ βασίλεια τοῦ τε κάλλους καὶ τοῦ μεγέθους οὐχ ἧττον δὲ τῆς διατάξεως τῶν οἰκοδομημάτων·"},{"number":169,"text":"καὶ γὰρ ἐν ταύτῃ πολλὴν τοῦ βασιλέως καθεώρα φρόνησιν. ὑπερεξέπληττε δʼ αὐτὴν ὅ τε οἶκος ὁ δρυμὼν ἐπικαλούμενος Λιβάνου καὶ ἡ τῶν καθʼ ἡμέραν δείπνων πολυτέλεια καὶ τὰ τῆς παρασκευῆς αὐτοῦ καὶ διακονίας ἥ τε τῶν ὑπηρετούντων ἐσθὴς καὶ τὸ μετʼ ἐπιστήμης αὐτῶν περὶ τὴν διακονίαν εὐπρεπές, οὐχ ἥκιστα δὲ καὶ αἱ καθʼ ἡμέραν ἐπιτελούμεναι τῷ θεῷ θυσίαι καὶ τὸ τῶν ἱερέων καὶ Λευιτῶν περὶ αὐτὰς ἐπιμελές."},{"number":170,"text":"ταῦθʼ ὁρῶσα καθʼ ἡμέραν ὑπερεθαύμαζε, καὶ κατασχεῖν οὐ δυνηθεῖσα τὴν ἔκπληξιν τῶν βλεπομένων φανερὰν ἐποίησεν αὑτὴν θαυμαστικῶς διακειμένην· πρὸς γὰρ τὸν βασιλέα προήχθη λόγους εἰπεῖν, ὑφʼ ὧν ἠλέγχθη σφόδρα τὴν διάνοιαν ἐπὶ τοῖς προειρημένοις ἡττημένη·"},{"number":171,"text":"πάντα μὲν γάρ, εἶπεν, ὦ βασιλεῦ, τὰ διʼ ἀκοῆς εἰς γνῶσιν ἐρχόμενα μετʼ ἀπιστίας παραγίνεται, τῶν δὲ σῶν ἀγαθῶν, ὧν αὐτός τε ἔχεις ἐν αὑτῷ, λέγω δὲ τὴν σοφίαν καὶ τὴν φρόνησιν, καὶ ὧν ἡ βασιλεία σοι δίδωσιν, οὐ ψευδὴς ἄρα ἡ φήμη πρὸς ἡμᾶς διῆλθεν, ἀλλʼ οὖσα ἀληθὴς πολὺ"},{"number":172,"text":"καταδεεστέραν τὴν εὐδαιμονίαν ἀπέφηνεν ἧς ὁρῶ νῦν παροῦσα τὰς μὲν γὰρ ἀκοὰς πείθειν ἐπεχείρει μόνον, τὸ δὲ ἀξίωμα τῶν πραγμάτων οὐχ οὕτως ἐποίει γνώριμον, ὡς ἡ ὄψις αὐτὸ καὶ τὸ παρʼ αὐτοῖς εἶναι συνίστησιν. ἐγὼ γοῦν οὐδὲ τοῖς ἀπαγγελλομένοις διὰ πλῆθος καὶ μέγεθος ὧν ἐπυνθανόμην πιστεύουσα πολλῷ πλείω τούτων ἱστόρηκα."},{"number":173,"text":"καὶ μακάριόν τε τὸν Ἑβραίων λαὸν εἶναι κρίνω δούλους τε τοὺς σοὺς καὶ φίλους, οἳ καθʼ ἡμέραν τῆς σῆς ἀπολαύουσιν ὄψεως καὶ τῆς σῆς σοφίας ἀκροώμενοι διατελοῦσιν. εὐλογήσειεν ἄν τις τὸν θεὸν ἀγαπήσαντα τήνδε τὴν χώραν καὶ τοὺς ἐν αὐτῇ κατοικοῦντας οὕτως, ὥστε σὲ ποιῆσαι βασιλέα."}],"7":[{"number":174,"text":"Παραστήσασα δὲ καὶ διὰ τῶν λόγων, πῶς αὐτὴν διέθηκεν ὁ βασιλεύς, ἔτι καὶ ταῖς δωρεαῖς τὴν διάνοιαν αὐτῆς ἐποίησε φανεράν· εἴκοσι μὲν γὰρ αὐτῷ τάλαντα ἔδωκε χρυσίου ἀρωμάτων τε πλῆθος ἀσυλλόγιστον καὶ λίθον πολυτελῆ· λέγουσι δʼ ὅτι καὶ τὴν τοῦ ὀποβαλσάμου ῥίζαν, ἣν ἔτι νῦν ἡμῶν ἡ χώρα φέρει, δούσης ταύτης τῆς γυναικὸς ἔχομεν."},{"number":175,"text":"ἀντεδωρήσατο δʼ αὐτὴν καὶ Σολόμων πολλοῖς ἀγαθοῖς καὶ μάλισθʼ ὧν κατʼ ἐπιθυμίαν ἐξελέξατο· οὐδὲν γὰρ ἦν, ὅ τι δεηθείσῃ λαβεῖν οὐ παρέσχεν, ἀλλʼ ἑτοιμότερον ὧν αὐτὸς κατὰ τὴν οἰκείαν ἐχαρίζετο προαίρεσιν ἅπερ ἐκείνη τυχεῖν ἠξίου προϊέμενος τὴν μεγαλοφροσύνην ἐπεδείκνυτο. καὶ ἡ μὲν τῶν Αἰγυπτίων καὶ τῆς Αἰθιοπίας βασίλισσα ὧν προειρήκαμεν τυχοῦσα καὶ μεταδοῦσα πάλιν τῷ βασιλεῖ τῶν παρʼ αὐτῆς εἰς τὴν οἰκείαν ὑπέστρεψε."},{"number":176,"text":"Κατὰ δὲ τὸν αὐτὸν καιρὸν κομισθέντων ἀπὸ τῆς χρυσῆς καλουμένης γῆς λίθου πολυτελοῦς τῷ βασιλεῖ καὶ ξύλων πευκίνων, τοῖς ξύλοις εἰς ὑποστήριγμα τοῦ τε ναοῦ καὶ τῶν βασιλείων κατεχρήσατο καὶ πρὸς τὴν τῶν μουσικῶν ὀργάνων κατασκευὴν κινύρας τε καὶ νάβλας, ὅπως ὑμνῶσιν οἱ Ληουῖται τὸν θεόν· πάντων δὲ τῶν ποτε κομισθέντων αὐτῷ τὰ κατʼ ἐκείνην τὴν ἡμέραν ἐνεχθέντα καὶ μεγέθει καὶ κάλλει διέφερεν."},{"number":177,"text":"ὑπολάβῃ δὲ μηδείς, ὅτι τὰ τῆς πεύκης ξύλα τοῖς νῦν εἶναι λεγομένοις καὶ ταύτην ὑπὸ τῶν πιπρασκόντων τὴν προσηγορίαν ἐπὶ καταπλήξει τῶν ὠνουμένων λαμβάνουσίν ἐστι παραπλήσια. ἐκεῖνα γὰρ τὴν μὲν ἰδέαν ἐμφερῆ τοῖς συκίνοις γίνεται, λευκότερα δέ ἐστι καὶ στίλβει πλέον."},{"number":178,"text":"τοῦτο μὲν πρὸς τὸ μηδένα τὴν διαφορὰν ἀγνοῆσαι μηδὲ τὴν φύσιν τῆς ἀληθοῦς πεύκης, ἐπεὶ διὰ τὴν τοῦ βασιλέως χρείαν ἐμνήσθημεν αὐτῆς, εὔκαιρον εἶναι καὶ φιλάνθρωπον δηλῶσαι νομίσαντες εἰρήκαμεν."},{"number":179,"text":"Ὁ δὲ τοῦ χρυσοῦ σταθμὸς τοῦ κομισθέντος αὐτῷ τάλαντα ἑξακόσια καὶ ἑξήκοντα καὶ ἕξ, μὴ συγκαταριθμουμένου καὶ τοῦ ὑπὸ τῶν ἐμπόρων ὠνηθέντος μηδʼ ὧν οἱ τῆς Ἀραβίας τοπάρχαι καὶ βασιλεῖς ἔπεμπον αὐτῷ δωρεῶν. ἐχώνευσε δὲ τὸν χρυσὸν εἰς διακοσίων κατασκευὴν θυρεῶν ἀνὰ σίκλους ἀγόντων ἑξακοσίους."},{"number":180,"text":"ἐποίησε δὲ καὶ ἀσπίδας τριακοσίας ἀγούσης ἑκάστης χρυσίου μνᾶς τρεῖς· ἀνέθηκε δὲ ταύτας φέρων εἰς τὸν οἶκον τὸν δρυμῶνα Λιβάνου καλούμενον. οὐ μὴν ἀλλὰ καὶ τὰ ἐκπώματα διὰ χρυσοῦ καὶ λίθου τὰ πρὸς τὴν ἑστίασιν ὡς ἔνι μάλιστα φιλοτεχνῶν κατεσκεύασε καὶ τὴν ἄλλην τῶν σκευῶν δαψίλειαν χρυσέαν ἅπασαν ἐμηχανήσατο·"},{"number":181,"text":"οὐδὲν γὰρ ἦν ὅ τις ἀργύρῳ ἐπίπρασκεν ἢ πάλιν ἐωνεῖτο, ἀλλὰ πολλαὶ γὰρ ἦσαν ναῦς, ἃς ὁ βασιλεὺς ἐν τῇ Ταρσικῇ λεγομένῃ θαλάττῃ καταστήσας παραγαγεῖν εἰς τὰ ἐνδοτέρω τῶν ἐθνῶν παντοίαν ἐμπορίαν προσέταξεν, ὧν ἐξεμπολουμένων ἄργυρός τε καὶ χρυσὸς ἐκομίζετο τῷ βασιλεῖ καὶ πολὺς ἐλέφας Αἰθίοπές τε καὶ πίθηκοι. τὸν δὲ πλοῦν ἀπιοῦσαί τε καὶ ἐπανερχόμεναι τρισὶν ἔτεσιν ἤνυον."},{"number":182,"text":"Φήμη δὲ λαμπρὰ πᾶσαν ἐν κύκλῳ τὴν χώραν περιήρχετο διαβοῶσα τὴν Σολόμωνος ἀρετὴν καὶ σοφίαν, ὡς τούς τε πανταχοῦ βασιλεῖς ἐπιθυμεῖν εἰς ὄψιν αὐτῷ παραγενέσθαι τοῖς λεγομένοις διʼ ὑπερβολὴν ἀπιστοῦντας, καὶ δωρεαῖς μεγάλαις προσεμφανίζειν τὴν περὶ αὐτὸν σπουδήν·"},{"number":183,"text":"ἔπεμπον γὰρ αὐτῷ σκεύη χρυσᾶ καὶ ἀργυρᾶ καὶ ἁλουργεῖς ἐσθῆτας καὶ ἀρωμάτων γένη πολλὰ καὶ ἵππους καὶ ἅρματα καὶ τῶν ἀχθοφόρων ἡμιόνων ὅσους καὶ ῥώμῃ καὶ κάλλει τὴν τοῦ βασιλέως ὄψιν εὖ διαθήσειν ἐπελέγοντο, ὥστε τοῖς οὖσιν αὐτῷ πρότερον ἅρμασι καὶ ἵπποις ἐκ τῶν πεμπομένων προσθέντα ποιῆσαι τὸν μὲν τῶν ἁρμάτων ἀριθμὸν τετρακοσίοις περισσότερον, ἦν γὰρ αὐτῷ πρότερον χίλια, τὸν δὲ τῶν ἵππων δισχιλίοις, ὑπῆρχον γὰρ αὐτῷ δισμύριοι ἵπποι."},{"number":184,"text":"ἤσκηντο δʼ οὗτοι πρὸς εὐμορφίαν καὶ τάχος, ὡς μήτʼ εὐπρεπεστέρους ἄλλους εἶναι συμβαλεῖν αὐτοῖς μήτε ὠκυτέρους, ἀλλὰ καλλίστους τε πάντων ὁρᾶσθαι καὶ ἀπαραμίλλητον αὐτῶν εἶναι τὴν ὀξύτητα."},{"number":185,"text":"ἐπεκόσμουν δὲ αὐτοὺς καὶ οἱ ἀναβαίνοντες νεότητι μὲν πρῶτον ἀνθοῦντες ἐπιτερπεστάτῃ τὸ δὲ ὕψος ὄντες περίοπτοι καὶ πολὺ τῶν ἄλλων ὑπερέχοντες, μηκίστας μὲν καθειμένοι χαίτας ἐνδεδυμένοι δὲ χιτῶνας τῆς Τυρίας πορφύρας. ψῆγμα δὲ χρυσοῦ καθʼ ἡμέραν αὐτῶν ἐπέσηθον ταῖς κόμαις, ὡς στίλβειν αὐτῶν τὰς κεφαλὰς τῆς αὐγῆς τοῦ χρυσοῦ πρὸς τὸν ἥλιον ἀντανακλωμένης."},{"number":186,"text":"τούτων περὶ αὐτὸν ὄντων ὁ βασιλεὺς καθωπλισμένων καὶ τόξα ἐξηρτημένων ἐφʼ ἅρματος αὐτὸς ὀχούμενος καὶ λευκὴν ἠμφιεσμένος ἐσθῆτα πρὸς αἰώραν ἔθος εἶχεν ἐξορμᾶν. ἦν δέ τι χωρίον ἀπὸ δύο σχοίνων Ἱεροσολύμων, ὃ καλεῖται μὲν Ἠτάν, παραδείσοις δὲ καὶ ναμάτων ἐπιρροαῖς ἐπιτερπὲς ὁμοῦ καὶ πλούσιον· εἰς τοῦτο τὰς ἐξόδους αἰωρούμενος ἐποιεῖτο."},{"number":187,"text":"Θείᾳ τε περὶ πάντα χρώμενος ἐπινοίᾳ τε καὶ σπουδῇ καὶ λίαν ὢν φιλόκαλος οὐδὲ τῶν ὁδῶν ἠμέλησεν, ἀλλὰ καὶ τούτων τὰς ἀγούσας εἰς Ἱεροσόλυμα βασίλειον οὖσαν λίθῳ κατέστρωσε μέλανι, πρός τε τὸ ῥᾳστώνην εἶναι τοῖς βαδίζουσι, καὶ πρὸς τὸ δηλοῦν τὸ ἀξίωμα τοῦ πλούτου καὶ τῆς ἡγεμονίας."},{"number":188,"text":"διαμερίσας δὲ τὰ ἅρματα καὶ διατάξας, ὥστε ἐν ἑκάστῃ πόλει τούτων ἀριθμὸν ὡρισμένον ὑπάρχειν, αὐτὸς μὲν περὶ αὑτὸν ἐτήρησεν ὀλίγα, τὰς δὲ πόλεις ταύτας ἁρμάτων προσηγόρευσε. τοῦ δʼ ἀργυρίου τοσοῦτον ἐποιήσατο πλῆθος ἐν Ἱεροσολύμοις ὁ βασιλεύς, ὅσον ἦν καὶ τῶν λίθων, καὶ τῶν κεδρίνων ξύλων οὐ πρότερον ὄντων, ὥσπερ καὶ τῶν δένδρων τῶν συκαμινίνων, ὧν πληθύει τὰ τῆς Ἰουδαίας πεδία."},{"number":189,"text":"προσέταξε δὲ καὶ τοῖς ἐμπόροις Αἰγύπτου κομίζουσιν αὐτῷ πιπράσκειν τὸ μὲν ἅρμα σὺν ἵπποις δυσὶν ἑξακοσίων δραχμῶν ἀργυρίου, αὐτὸς δὲ τοῖς τῆς Συρίας βασιλεῦσι καὶ τοῖς πέραν Εὐφράτου διέπεμπεν αὐτούς."},{"number":190,"text":"Γενόμενος δὲ πάντων βασιλέων ἐνδοξότατος καὶ θεοφιλέστατος καὶ φρονήσει καὶ πλούτῳ διενεγκὼν τῶν πρὸ αὐτοῦ τὴν Ἑβραίων ἀρχὴν ἐσχηκότων οὐκ ἐπέμεινε τούτοις ἄχρι τελευτῆς, ἀλλὰ καταλιπὼν τὴν τῶν πατρίων ἐθισμῶν φυλακὴν οὐκ εἰς ὅμοιον οἷς προειρήκαμεν αὐτοῦ τέλος κατέστρεψεν,"},{"number":191,"text":"εἰς δὲ γυναῖκας ἐκμανεὶς καὶ τὴν τῶν ἀφροδισίων ἀκρασίαν οὐ ταῖς ἐπιχωρίαις μόνον ἠρέσκετο, πολλὰς δὲ καὶ ἐκ τῶν ἀλλοτρίων ἐθνῶν γήμας Σιδωνίας καὶ Τυρίας καὶ Ἀμμανίτιδας καὶ Ἰδουμαίας παρέβη μὲν τοὺς Μωσήους νόμους, ὃς ἀπηγόρευσε συνοικεῖν ταῖς οὐχ ὁμοφύλοις,"},{"number":192,"text":"τοὺς δʼ ἐκείνων ἤρξατο θρησκεύειν θεοὺς ταῖς γυναιξὶ καὶ τῷ πρὸς αὐτὰς ἔρωτι χαριζόμενος, τοῦτʼ αὐτὸ ὑπιδομένου τοῦ νομοθέτου προειπόντος μὴ γαμεῖν τὰς ἀλλοτριοχώρους, ἵνα μὴ τοῖς ξένοις ἐπιπλακέντες ἔθεσι τῶν πατρίων ἀποστῶσι, μηδὲ τοὺς ἐκείνων σέβωνται θεοὺς παρέντες τιμᾶν τὸν ἴδιον."},{"number":193,"text":"ἀλλὰ τούτων μὲν κατημέλησεν ὑπενεχθεὶς εἰς ἡδονὴν ἀλόγιστον Σολόμων, ἀγαγόμενος δὲ γυναῖκας ἀρχόντων καὶ διασήμων θυγατέρας ἑπτακοσίας τὸν ἀριθμὸν καὶ παλλακὰς τριακοσίας, πρὸς δὲ ταύταις καὶ τὴν τοῦ βασιλέως τῶν Αἰγυπτίων θυγατέρα, εὐθὺς μὲν ἐκρατεῖτο πρὸς αὐτῶν, ὥστε μιμεῖσθαι τὰ παρʼ ἐκείναις, καὶ τῆς εὐνοίας καὶ φιλοστοργίας ἠναγκάζετο παρέχειν αὐταῖς δεῖγμα τὸ βιοῦν ὡς αὐταῖς πάτριον ἦν·"},{"number":194,"text":"προβαινούσης δὲ τῆς ἡλικίας καὶ τοῦ λογισμοῦ διὰ τὸν χρόνον ἀσθενοῦντος ἀντέχειν πρὸς τὴν μνήμην τῶν ἐπιχωρίων ἐπιτηδευμάτων ἔτι μᾶλλον τοῦ μὲν ἰδίου θεοῦ κατωλιγώρησε, τοὺς δὲ τῶν γάμων τῶν ἐπεισάκτων τιμῶν διετέλει."},{"number":195,"text":"καὶ πρὸ τούτων δὲ ἁμαρτεῖν αὐτὸν ἔτυχε καὶ σφαλῆναι περὶ τὴν φυλακὴν τῶν νομίμων, ὅτε τὰ τῶν χαλκῶν βοῶν ὁμοιώματα κατεσκεύασε τῶν ὑπὸ τῇ θαλάττῃ τῷ ἀναθήματι καὶ τῶν λεόντων τῶν περὶ τὸν θρόνον τὸν ἴδιον· οὐδὲ γὰρ ταῦτα ποιεῖν ὅσιον εἰργάσατο."},{"number":196,"text":"κάλλιστον δʼ ἔχων καὶ οἰκεῖον παράδειγμα τῆς ἀρετῆς τὸν πατέρα καὶ τὴν ἐκείνου δόξαν, ἣν αὐτῷ συνέβη καταλιπεῖν διὰ τὴν πρὸς τὸν θεὸν εὐσέβειαν, οὐ μιμησάμενος αὐτὸν καὶ ταῦτα δὶς αὐτῷ τοῦ θεοῦ κατὰ τοὺς ὕπνους φανέντος καὶ τὸν πατέρα μιμεῖσθαι παραινέσαντος ἀκλεῶς ἀπέθανεν."},{"number":197,"text":"ἧκεν οὖν εὐθὺς ὁ προφήτης ὑπὸ θεοῦ πεμφθεὶς οὔτε λανθάνειν αὐτὸν ἐπὶ τοῖς παρανομήμασι λέγων οὔτʼ ἐπὶ πολὺ χαιρήσειν τοῖς πραττομένοις ἀπειλῶν, ἀλλὰ ζῶντος μὲν οὐκ ἀφαιρεθήσεσθαι τὴν βασιλείαν ἐπεὶ τῷ πατρὶ Δαυίδῃ τὸ θεῖον ὑπέσχετο διάδοχον αὐτὸν ποιήσειν ἐκείνου,"},{"number":198,"text":"τελευτήσαντος δὲ τὸν υἱὸν αὐτοῦ ταῦτα διαθήσειν οὐχ ἅπαντα μὲν τὸν λαὸν ἀποστήσας αὐτοῦ, δέκα δὲ φυλὰς παραδοὺς αὐτοῦ τῷ δούλῳ, δύο δὲ μόνας καταλιπὼν τῷ υἱωνῷ τῷ Δαυίδου διʼ αὐτὸν ἐκεῖνον, ὅτι τὸν θεὸν ἠγάπησε, καὶ διὰ τὴν πόλιν Ἱεροσόλυμα, ἐν ᾗ ναὸν ἔχειν ἠβουλήθη."},{"number":199,"text":"Ταῦτʼ ἀκούσας Σολόμων ἤλγησε καὶ σφοδρῶς συνεχύθη πάντων αὐτῷ σχεδὸν τῶν ἀγαθῶν ἐφʼ οἷς ζηλωτὸς ἦν εἰς μεταβολὴν ἐρχομένων πονηράν. οὐ πολὺς δὲ διῆλθε χρόνος ἀφʼ οὗ κατήγγειλεν ὁ προφήτης αὐτῷ τὰ συμβησόμενα καὶ πολέμιον εὐθὺς ἐπʼ αὐτὸν ἤγειρεν ὁ θεὸς Ἄδερον μὲν ὄνομα τὴν δʼ αἰτίαν τῆς ἔχθρας λαβόντα τοιαύτην·"},{"number":200,"text":"παῖς οὗτος ἦν Ἰδουμαῖος γένος ἐκ βασιλικῶν σπερμάτων. καταστρεψαμένου δὲ τὴν Ἰδουμαίαν Ἰωάβου τοῦ Δαυίδου στρατηγοῦ καὶ πάντας τοὺς ἐν ἀκμῇ καὶ φέρειν ὅπλα δυναμένους διαφθείραντος μησὶν ἕξ, φυγὼν ἧκε πρὸς Φαραῶνα τὸν Αἰγυπτίων βασιλέα."},{"number":201,"text":"ὁ δὲ φιλοφρόνως αὐτὸν δεξάμενος οἶκόν τε αὐτῷ δίδωσι καὶ χώραν εἰς διατροφὴν καὶ γενόμενον ἐν ἡλικίᾳ λίαν ἠγάπα, ὡς καὶ τῆς αὑτοῦ γυναικὸς αὐτῷ δοῦναι πρὸς γάμον τὴν ἀδελφὴν ὄνομα Θαφίνην, ἐξ ἧς αὐτῷ υἱὸς γενόμενος τοῖς τοῦ βασιλέως παισὶ συνετράφη."},{"number":202,"text":"ἀκούσας οὖν τὸν Δαυίδου θάνατον ἐν Αἰγύπτῳ καὶ τὸν Ἰωάβου προσελθὼν ἐδεῖτο τοῦ Φαραῶνος ἐπιτρέπειν αὐτῷ βαδίζειν εἰς τὴν πατρίδα. τοῦ δὲ βασιλέως ἀνακρίναντος, τίνος ἐνδεὴς ὢν ἢ τί παθὼν ἐσπούδακε καταλιπεῖν αὐτόν, ἐνοχλῶν πολλάκις καὶ παρακαλῶν τότε μὲν οὐκ ἀφείθη·"},{"number":203,"text":"κατʼ ἐκεῖνον δὲ τὸν καιρόν, καθʼ ὃν ἤδη Σολόμωνι τὰ πράγματα κακῶς ἔχειν ἤρχετο διὰ τὰς προειρημένας παρανομίας καὶ τὴν ὀργὴν τὴν ἐπʼ αὐτοῖς τοῦ θεοῦ, συγχωρήσαντος τοῦ Φαραῶνος ὁ Ἄδερος ἧκεν εἰς τὴν Ἰδουμαίαν· καὶ μὴ δυνηθεὶς αὐτὴν ἀποστῆσαι τοῦ Σολόμωνος, κατείχετο γὰρ φρουραῖς πολλαῖς καὶ οὐκ ἦν ἐλεύθερος διʼ αὐτὰς οὐδʼ ἐπʼ ἀδείας ὁ νεωτερισμός, ἄρας ἐκεῖθεν εἰς τὴν Συρίαν ἀφίκετο."},{"number":204,"text":"συμβαλὼν δὲ ἐκεῖ τινι Ῥάζῳ μὲν τοὔνομα τὸν δὲ τῆς Σωφηνῆς ἀποδεδρακότι βασιλέα Ἀδραάζαρον δεσπότην ὄντα καὶ λῃστεύοντι τὴν χώραν εἰς φιλίαν αὐτῷ συνάψας ἔχοντι περὶ αὑτὸν στῖφος λῃστρικὸν ἀναβαίνει, καὶ κατασχὼν τὴν ἐκεῖ Συρίαν βασιλεὺς αὐτῆς ἀποδείκνυται καὶ κατατρέχων τὴν τῶν Ἰσραηλιτῶν γῆν ἐποίει κακῶς καὶ διήρπαζε Σολόμωνος ζῶντος ἔτι. καὶ ταῦτα μὲν ἐκ τοῦ Ἀδέρου συνέβαινε πάσχειν τοῖς Ἑβραίοις."},{"number":205,"text":"Ἐπιτίθεται δὲ Σολόμωνι καὶ τῶν ὁμοφύλων τις Ἱεροβόαμος υἱὸς Ναβαταίου κατὰ προφητείαν πάλαι γενομένην αὐτῷ τοῖς πράγμασιν ἐπελπίσας· παῖδα γὰρ αὐτὸν ὑπὸ τοῦ πατρὸς καταλειφθέντα καὶ ὑπὸ τῇ μητρὶ παιδευόμενον ὡς εἶδε γενναῖον καὶ τολμηρὸν Σολόμων ὄντα τὸ φρόνημα τῆς τῶν τειχῶν οἰκοδομίας ἐπιμελητὴν κατέστησεν, ὅτε τοῖς Ἱεροσολύμοις τὸν κύκλον περιέβαλεν."},{"number":206,"text":"οὕτως δὲ τῶν ἔργων προενόησεν, ὥστε ὁ βασιλεὺς αὐτὸν ἀπεδέξατο καὶ γέρας αὐτῷ στρατηγίαν ἐπὶ τῆς Ἰωσήπου φυλῆς ἔδωκεν. ἀπερχομένῳ δὲ τῷ Ἱεροβοάμῳ κατʼ ἐκεῖνον τὸν καιρὸν ἐκ τῶν Ἱεροσολύμων συνεβόλησε προφήτης ἐκ πόλεως μὲν Σιλὼ Ἀχίας δὲ ὄνομα. καὶ προσαγορεύσας αὐτὸν ἀπήγαγεν ἐκ τῆς ὁδοῦ μικρὸν ἀπονεύσας εἴς τι χωρίον, εἰς ὃ παρῆν μηδὲ εἷς ἄλλος."},{"number":207,"text":"σχίσας δὲ εἰς δώδεκα φάρση τὸ ἱμάτιον, ὅπερ ἦν αὐτὸς περιβεβλημένος, ἐκέλευσε τὸν Ἱεροβόαμον λαβεῖν τὰ δέκα προσειπών, ὅτι ταῦτα ὁ θεὸς βούλεται καὶ σχίσας τὴν Σολόμωνος ἀρχὴν τῷ παιδὶ μὲν τῷ τούτου διὰ τὴν πρὸς Δαυίδην γεγενημένην ὁμολογίαν αὐτῷ μίαν φυλὴν καὶ τὴν ἑξῆς αὐτῇ δίδωσι, σοὶ δὲ τὰς δέκα Σολόμωνος εἰς αὐτὸν ἐξαμαρτόντος καὶ ταῖς γυναιξὶ καὶ τοῖς ἐκείνων θεοῖς αὑτὸν ἐκδεδωκότος."},{"number":208,"text":"εἰδὼς οὖν τὴν αἰτίαν διʼ ἣν μετατίθησι τὴν αὑτοῦ γνώμην ἀπὸ Σολόμωνος ὁ θεὸς δίκαιος εἶναι πειρῶ καὶ φύλαττε τὰ νόμιμα, προκειμένου σοι τῆς εὐσεβείας καὶ τῆς πρὸς τὸν θεὸν τιμῆς ἄθλου μεγίστου τῶν ἁπάντων, γενήσεσθαι τηλικούτῳ ἡλίκον οἶσθα Δαυίδην γενόμενον."}],"8":[{"number":209,"text":"Ἐπαρθεὶς οὖν τοῖς τοῦ προφήτου λόγοις Ἱεροβόαμος φύσει θερμὸς ἂν νεανίας καὶ μεγάλων ἐπιθυμητὴς πραγμάτων οὐκ ἠρέμει. γενόμενος δʼ ἐν τῇ στρατηγίᾳ καὶ μεμνημένος τῶν ὑπὸ Ἀχία δεδηλωμένων εὐθὺς ἀναπείθειν ἐπεχείρει τὸν λαὸν ἀφίστασθαι Σολόμωνος καὶ κινεῖν καὶ παράγειν εἰς αὑτὸν τὴν ἡγεμονίαν."},{"number":210,"text":"μαθὼν δὲ τὴν διάνοιαν αὐτοῦ καὶ τὴν ἐπιβολὴν Σολόμων ἐζήτει συλλαβὼν αὐτὸν ἀνελεῖν. φθάσας δὲ γνῶναι τοῦτο Ἱεροβόαμος πρὸς Ἴσακον φεύγει τὸν Αἰγυπτίων βασιλέα, καὶ μέχρι τῆς Σολόμωνος τελευτῆς ἐκεῖ μείνας τό τε μηδὲν ὑπʼ αὐτοῦ παθεῖν ἐκέρδησε καὶ τὸ τῇ βασιλείᾳ φυλαχθῆναι."},{"number":211,"text":"ἀποθνήσκει δὲ Σολόμων ἤδη γηραιὸς ὢν βασιλεύσας μὲν ὀγδοήκοντα ἔτη, ζήσας δὲ ἐνενήκοντα καὶ τέσσαρα· θάπτεται δὲ ἐν Ἱεροσολύμοις ἅπαντας ὑπερβαλὼν εὐδαιμονίᾳ τε καὶ πλούτῳ καὶ φρονήσει τοὺς βασιλεύσαντας, εἰ μὴ ὅσα γε πρὸς τὸ γῆρας ὑπὸ τῶν γυναικῶν ἀπατηθεὶς παρηνόμησε· περὶ ὧν καὶ τῶν διʼ αὐτὰς κακῶν συμπεσόντων Ἑβραίοις εὐκαιρότερον ἕξομεν διασαφῆσαι."},{"number":212,"text":"Μετὰ δὲ τὴν Σολόμωνος τελευτὴν διαδεξαμένου τοῦ παιδὸς αὐτοῦ τὴν βασιλείαν Ῥοβοάμου, ὃς ἐκ γυναικὸς Ἀμμανίτιδος ὑπῆρχεν αὐτῷ γεγονὼς Νοομᾶς τοὔνομα, πέμψαντες εὐθὺς εἰς τὴν Αἴγυπτον οἱ τῶν ὄχλων ἄρχοντες ἐκάλουν τὸν Ἱεροβόαμον. ἀφικομένου δὲ πρὸς αὐτοὺς εἰς Σίκιμα πόλιν καὶ Ῥοβόαμος εἰς αὐτὴν παραγίνεται· δέδοκτο γὰρ αὐτὸν ἐκεῖσε συνελθοῦσι τοῖς Ἰσραηλίταις ἀποδεῖξαι βασιλέα."},{"number":213,"text":"προσελθόντες οὖν οἵ τε ἄρχοντες αὐτῷ τοῦ λαοῦ καὶ Ἱεροβόαμος παρεκάλουν λέγοντες ἀνεῖναί τι τῆς δουλείας αὐτοῖς καὶ γενέσθαι χρηστότερον τοῦ πατρός· βαρὺν γὰρ ὑπʼ ἐκείνῳ ζυγὸν αὐτοὺς ὑπενεγκεῖν· εὐνούστεροι δὲ ἔσεσθαι πρὸς αὐτὸν καὶ ἀγαπήσειν τὴν δουλείαν διὰ τὴν ἐπιείκειαν ἢ διὰ τὸν φόβον."},{"number":214,"text":"ὁ δὲ μετὰ τρεῖς ἡμέρας εἰπὼν αὐτοῖς ἀποκρινεῖσθαι περὶ ὧν ἀξιοῦσιν ὕποπτος μὲν εὐθὺς γίνεται μὴ παραχρῆμα ἐπινεύσας αὐτοῖς τὰ πρὸς ἡδονήν, πρόχειρον γὰρ ἠξίουν εἶναι τὸ χρηστὸν καὶ φιλάνθρωπον καὶ ταῦτʼ ἐν νέῳ, ἐδόκει δʼ ὅμως καὶ τὸ βουλεύσασθαι τοῦ μὴ παραυτίκα ἀπειπεῖν ἀγαθῆς ἐλπίδος ἔχεσθαι."},{"number":215,"text":"Συγκαλέσας δὲ τοὺς πατρῴους φίλους ἐσκοπεῖτο μετʼ αὐτῶν, ποδαπὴν δεῖ ποιήσασθαι τὴν ἀπόκρισιν πρὸς τὸ πλῆθος. οἱ δʼ ἅπερ εἰκὸς τοὺς εὔνους καὶ φύσιν ὄχλων εἰδότας παρῄνουν αὐτῷ φιλοφρόνως ὁμιλῆσαι τῷ λαῷ καὶ δημοτικώτερον ἢ κατὰ βασιλείας ὄγκον· χειρώσεσθαι γὰρ οὕτως εἰς εὔνοιαν αὐτὸν φύσει τῶν ὑπηκόων ἀγαπώντων τὸ προσηνὲς καὶ παρὰ μικρὸν ἰσότιμον τῶν βασιλέων."},{"number":216,"text":"ὁ δʼ ἀγαθὴν οὕτως καὶ συμφέρουσαν ἴσως πρὸς τὸ πᾶν, εἰ δὲ μή, πρός γε τὸν τότε καιρὸν ὅτʼ ἔδει γενέσθαι βασιλέα γνώμην ἀπεστράφη τοῦ θεοῦ ποιήσαντος οἶμαι κατακριθῆναι τὸ συμφέρον ὑπʼ αὐτοῦ· καλέσας δὲ μειράκια τὰ συντεθραμμένα καὶ τὴν τῶν πρεσβυτέρων αὐτοῖς συμβουλίαν εἰπών, τί δοκεῖ ποιεῖν αὐτοῖς ἐκέλευσε λέγειν."},{"number":217,"text":"τὰ δέ, οὔτε γὰρ ἡ νεότης οὔτε ὁ θεὸς ἠφίει νοεῖν τὰ κρείττω, παρῄνεσαν ἀποκρίνασθαι τῷ λαῷ τὸν βραχύτατον αὐτοῦ δάκτυλον τῆς τοῦ πατρὸς ὀσφύος εἶναι παχύτερον καί, εἰ σκληροῦ λίαν ἐπειράθησαν ἐκείνου, πολὺ μᾶλλον αὐτοῦ λήψεσθαι πεῖραν δυσκόλου· καὶ εἰ μάστιξιν αὐτοὺς ἐκεῖνος ἐνουθέτει, σκορπίοις τοῦτο ποιήσειν αὐτὸν προσδοκᾶν."},{"number":218,"text":"τούτοις ἡσθεὶς ὁ βασιλεὺς καὶ δόξας προσήκειν τῷ τῆς ἀρχῆς ἀξιώματι τὴν ἀπόκρισιν, ὡς συνῆλθεν ἀκουσόμενον τὸ πλῆθος τῇ τρίτῃ τῶν ἡμερῶν, μετεώρου τοῦ λαοῦ παντὸς ὄντος καὶ λέγοντος ἀκοῦσαί τι τοῦ βασιλέως ἐσπουδακότος, οἰομένου δέ τι καὶ φιλάνθρωπον, τὴν τῶν μειρακίων αὐτοῖς συμβουλίαν παρεὶς τὴν τῶν φίλων ἀπεκρίνατο. ταῦτα δʼ ἐπράττετο κατὰ τὴν τοῦ θεοῦ βούλησιν, ἵνα λάβῃ τέλος ἃ προεφήτευσεν Ἀχίας."},{"number":219,"text":"Πληγέντες δʼ ὑπὸ τῶν λόγων καὶ ἀλγήσαντες ὡς ἐπὶ πείρᾳ τοῖς εἰρημένοις ἠγανάκτησαν καὶ μέγα πάντες ἐκβοήσαντες οὐκέτι οὐδὲν αὐτοῖς οὐδὲ συγγενὲς πρὸς Δαυίδην καὶ τοὺς ἀπʼ αὐτοῦ μετʼ ἐκείνην ἔφασαν τὴν ἡμέραν· παραχωρεῖν δʼ αὐτῷ μόνον τὸν ναὸν ὃν ὁ πάππος αὐτοῦ κατεσκεύασεν εἰπόντες καταλείψειν ἠπείλησαν."},{"number":220,"text":"οὕτως δʼ ἔσχον πικρῶς καὶ τὴν ὀργὴν ἐτήρησαν, ὡς πέμψαντος αὐτοῦ τὸν ἐπὶ τῶν φόρων Ἀδώραμον, ἵνα καταπραΰνῃ καὶ συγγνόντας τοῖς εἰρημένοις, εἴ τι προπετὲς καὶ δύσκολον ἦν ἐν αὐτοῖς, ποιήσῃ μαλακωτέρους, οὐχ ὑπέμειναν, ἀλλὰ βάλλοντες αὐτὸν λίθοις ἀπέκτειναν."},{"number":221,"text":"ταῦτʼ ἰδὼν Ῥοβόαμος καὶ νομίσας αὑτὸν βεβλῆσθαι τοῖς λίθοις, οἷς τὸν ὑπηρέτην ἀπέκτεινεν αὐτοῦ τὸ πλῆθος, δείσας μὴ καὶ ἔργῳ πάθῃ τὸ δεινὸν ἐπιβὰς εὐθὺς ἐπὶ ἅρματος ἔφυγεν εἰς Ἱεροσόλυμα. καὶ ἡ μὲν Ἰούδα φυλὴ καὶ ἡ Βενιαμίδος χειροτονοῦσιν αὐτὸν βασιλέα, τὸ δὲ ἄλλο πλῆθος ἀπʼ ἐκείνης τῆς ἡμέρας τῶν Δαυίδου παίδων ἀποστὰν τὸν Ἱεροβόαμον ἀπέδειξε τῶν πραγμάτων κύριον."},{"number":222,"text":"Ῥοβόαμος δὲ ὁ Σολόμωνος παῖς ἐκκλησίαν ποιήσας τῶν δύο φυλῶν, ἃς εἶχεν ὑπηκόους, οἷός τε ἦν λαβὰν ὀκτωκαίδεκα παρʼ αὐτῶν στρατοῦ μυριάδας ἐπιλέκτους ἐξελθεῖν ἐπὶ τὸν Ἱεροβόαμον καὶ τὸν λαόν, ὅπως πολεμήσας ἀναγκάσῃ δουλεύειν αὐτῷ."},{"number":223,"text":"κωλυθεὶς δʼ ὑπὸ τοῦ θεοῦ διὰ τοῦ προφήτου ποιήσασθαι τὴν στρατείαν, οὐ γὰρ εἶναι δίκαιον τοὺς ὁμοφύλους πολεμεῖν οὗτος ἔλεγε καὶ ταῦτα κατὰ τὴν τοῦ θεοῦ προαίρεσιν τῆς τοῦ πλήθους ἀποστάσεως γεγενημένης, οὐκέτʼ ἐξῆλθε."},{"number":224,"text":"διηγήσομαι δὲ πρῶτον ὅσα Ἱεροβόαμος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς ἔπραξεν, εἶτα δὲ τούτων ἐχόμενα τὰ ὑπὸ Ῥοβοάμου τοῦ τῶν δύο φυλῶν βασιλέως γεγενημένα δηλώσομεν· φυλαχθείη γὰρ ἂν οὕτως ἄχρι παντὸς τῆς ἱστορίας τὸ εὔτακτον."},{"number":225,"text":"Ὁ τοίνυν Ἱεροβόαμος οἰκοδομήσας βασίλειον ἐν Σικίμῃ πόλει ἐν ταύτῃ τὴν δίαιταν εἶχε, κατεσκεύασε δὲ καὶ ἐν Φανουὴλ πόλει λεγομένῃ. μετʼ οὐ πολὺ δὲ τῆς σκηνοπηγίας ἑορτῆς ἐνίστασθαι μελλούσης λογισάμενος, ὡς ἐὰν ἐπιτρέψῃ τῷ πλήθει προσκυνῆσαι τὸν θεὸν εἰς Ἱεροσόλυμα πορευθέντι καὶ ἐκεῖ τὴν ἑορτὴν διαγαγεῖν, μετανοῆσαν ἴσως καὶ δελεασθὲν ὑπὸ τοῦ ναοῦ καὶ τῆς θρησκείας τῆς ἐν αὐτῷ τοῦ θεοῦ καταλείψει μὲν αὐτόν, προσχωρήσει δὲ τῷ πρώτῳ βασιλεῖ, καὶ κινδυνεύσει τούτου γενομένου τὴν ψυχὴν ἀποβαλεῖν, ἐπιτεχνᾶταί τι τοιοῦτον·"},{"number":226,"text":"δύο ποιήσας δαμάλεις χρυσᾶς καὶ οἰκοδομήσας ναΐσκους τοσούτους ἕνα μὲν ἐν Βηθήλῃ πόλει, τὸν ἕτερον δὲ ἐν Δάνῃ, ἡ δʼ ἐστὶ πρὸς ταῖς πηγαῖς τοῦ μικροῦ Ἰορδάνου, τίθησι τὰς δαμάλεις ἐν ἑκατέρῳ τῶν ἐν ταῖς προειρημέναις πόλεσι ναΐσκων, καὶ συγκαλέσας τὰς δέκα φυλὰς ὧν αὐτὸς ἦρχεν ἐδημηγόρησε τούτους ποιησάμενος τοὺς λόγους·"},{"number":227,"text":"ἄνδρες ὁμόφυλοι, γινώσκειν ὑμᾶς νομίζω τοῦτο, ὅτι πᾶς τόπος ἔχει τὸν θεὸν καὶ οὐκ ἔστιν ἓν ἀποδεδειγμένον χωρίον ἐν ᾧ πάρεστιν, ἀλλὰ πανταχοῦ τε ἀκούει καὶ τοὺς θρησκεύοντας ἐφορᾷ. ὅθεν οὔ μοι δοκεῖ νῦν ἐπείγειν ὑμᾶς εἰς Ἱεροσόλυμα πορευθέντας εἰς τὴν τῶν ἐχθρῶν πόλιν μακρὰν οὕτως ὁδὸν προσκυνεῖν·"},{"number":228,"text":"ἄνθρωπος γὰρ κατεσκεύακε τὸν ναόν, πεποίηκα δὲ κἀγὼ δύο χρυσᾶς δαμάλεις ἐπωνύμους τῷ θεῷ καὶ τὴν μὲν ἐν Βηθήλῃ πόλει καθιέρωσα τὴν δʼ ἐν Δάνῃ, ὅπως ὑμῶν οἱ τούτων ἔγγιστα τῶν πόλεων κατῳκημένοι προσκυνῶσιν εἰς αὐτὰς ἀπερχόμενοι τὸν θεόν. ἀποδείξω δέ τινας ὑμῖν καὶ ἱερεῖς ἐξ ὑμῶν αὐτῶν καὶ Ληουίτας, ἵνα μὴ χρείαν ἔχητε τῆς Ληουίτιδος φυλῆς καὶ τῶν υἱῶν Ἀαρῶνος, ἀλλʼ ὁ βουλόμενος ὑμῶν ἱερεὺς εἶναι προσενεγκάτω μόσχον τῷ θεῷ καὶ κριόν, ὃ καὶ τὸν πρῶτον ἱερέα φασὶν Ἀαρῶνα πεποιηκέναι."},{"number":229,"text":"ταῦτʼ εἰπὼν ἐξηπάτησε τὸν λαὸν καὶ τῆς πατρίου θρησκείας ἀποστάντας ἐποίησε παραβῆναι τοὺς νόμους. ἀρχὴ κακῶν ἐγένετο τοῦτο τοῖς Ἑβραίοις καὶ τοῦ πολέμῳ κρατηθέντας ὑπὸ τῶν ἀλλοφύλων αἰχμαλωσίᾳ περιπεσεῖν. ἀλλὰ ταῦτα μὲν κατὰ χώραν δηλώσομεν."}],"9":[{"number":230,"text":"Ἐνστάσης δὲ τῆς ἑορτῆς ἑβδόμῳ μηνὶ βουλόμενος καὶ αὐτὸς ἐν Βηθήλῃ ταύτην ἀγαγεῖν, ὥσπερ ἑώρταζον καὶ αἱ δύο φυλαὶ ἐν Ἱεροσολύμοις, οἰκοδομεῖ μὲν θυσιαστήριον πρὸ τῆς δαμάλεως, γενόμενος δὲ αὐτὸς ἀρχιερεὺς ἐπὶ τὸν βωμὸν ἀναβαίνει σὺν τοῖς ἰδίοις ἱερεῦσι."},{"number":231,"text":"μέλλοντος δʼ ἐπιφέρειν τὰς θυσίας καὶ τὰς ὁλοκαυτώσεις ἐν ὄψει τοῦ λαοῦ παντὸς παραγίνεται πρὸς αὐτὸν ἐξ Ἱεροσολύμων προφήτης Ἰάδων ὄνομα τοῦ θεοῦ πέμψαντος, ὃς σταθεὶς ἐν μέσῳ τῷ πλήθει τοῦ βασιλέως ἀκούοντος εἶπε τάδε πρὸς τὸ θυσιαστήριον ποιούμενος τοὺς λόγους·"},{"number":232,"text":"ὁ θεὸς ἔσεσθαί τινα προλέγει ἐκ τοῦ Δαυίδου γένους Ἰωσίαν ὄνομα, ὃς ἐπὶ σοῦ θύσει τοὺς ψευδιερεῖς τοὺς κατʼ ἐκεῖνον τὸν καιρὸν γενησομένους καὶ τὰ ὀστᾶ τῶν λαοπλάνων τούτων καὶ ἀπατεώνων καὶ ἀσεβῶν ἐπὶ σοῦ καύσει. ἵνα μέντοι γε πιστεύσωσιν οὗτοι τοῦθʼ οὕτως ἕξειν, σημεῖον αὐτοῖς προερῶ γενησόμενον· ῥαγήσεται τὸ θυσιαστήριον παραχρῆμα καὶ πᾶσα ἡ ἐπʼ αὐτοῦ πιμελὴ τῶν ἱερείων ἐπὶ γῆν χυθήσεται."},{"number":233,"text":"ταῦτʼ εἰπόντος τοῦ προφήτου παροξυνθεὶς ὁ Ἱεροβόαμος ἐξέτεινε τὴν χεῖρα κελεύων συλλαβεῖν αὐτόν. ἐκτεταμένη δʼ ἡ χεὶρ εὐθέως παρείθη καὶ οὐκέτʼ ἴσχυε ταύτην πρὸς αὑτὸν ἀναγαγεῖν, ἀλλὰ νεναρκηκυῖαν καὶ νεκρὰν εἶχεν ἀπηρτημένην. ἐρράγη δὲ καὶ τὸ θυσιαστήριον καὶ κατηνέχθη πάντα ἀπʼ αὐτοῦ, καθὼς προεῖπεν ὁ προφήτης."},{"number":234,"text":"μαθὼν δὲ ἀληθῆ τὸν ἄνθρωπον καὶ θείαν ἔχοντα πρόγνωσιν παρεκάλεσεν αὐτὸν δεηθῆναι τοῦ θεοῦ ἀναζωπυρῆσαι τὴν δεξιὰν αὐτῷ. καὶ ὁ μὲν ἱκέτευσε τὸν θεὸν τοῦτʼ αὐτῷ παρασχεῖν, ὁ δὲ τῆς χειρὸς τὸ κατὰ φύσιν ἀπολαβούσης χαίρων ἐπʼ αὐτῇ τὸν προφήτην παρεκάλει δειπνῆσαι παρʼ αὐτῷ."},{"number":235,"text":"Ἰάδων δέ φησιν οὐχ ὑπομένειν εἰσελθεῖν πρὸς αὐτὸν οὐδὲ γεύσασθαι ἄρτου καὶ ὕδατος ἐν ταύτῃ τῇ πόλει· τοῦτο γὰρ αὐτῷ τὸν θεὸν ἀπειρηκέναι καὶ τὴν ὁδὸν ἣν ἦλθεν ὅπως μὴ διʼ αὐτῆς ποιήσηται τὴν ἐπιστροφήν, ἀλλὰ διʼ ἄλλης ἔφασκεν· τοῦτον μὲν οὖν ὁ βασιλεὺς ἐθαύμαζεν τῆς ἐγκρατείας, αὐτὸς δʼ ἦν ἐν φόβῳ μεταβολὴν αὐτοῦ τῶν πραγμάτων ἐκ τῶν προειρημένων οὐκ ἀγαθὴν ὑπονοῶν."}],"10":[{"number":236,"text":"Ἦν δέ τις ἐν τῇ πόλει πρεσβύτης πονηρὸς ψευδοπροφήτης, ὃν εἶχεν ἐν τιμῇ Ἱεροβόαμος ἀπατώμενος ὑπʼ αὐτοῦ τὰ πρὸς ἡδονὴν λέγοντος. οὗτος τότε μὲν κλινήρης ἦν διὰ τὴν ἀπὸ τοῦ γήρως ἀσθένειαν, τῶν δὲ παίδων αὐτῷ δηλωσάντων τὰ περὶ τοῦ παρόντος ἐξ Ἱεροσολύμων προφήτου καὶ τῶν σημείων τῶν γενομένων,"},{"number":237,"text":"καὶ ὡς παρεθεῖσαν αὐτῷ τὴν δεξιὰν Ἱεροβόαμος εὐξαμένου πάλιν ἐκείνου ζῶσαν ἀπολάβοι, δείσας μὴ παρευδοκιμήσειεν αὐτὸν ὁ ξένος παρὰ τῷ βασιλεῖ καὶ πλείονος ἀπολαύοι τιμῆς προσέταξε τοῖς παισὶν εὐθὺς ἐπιστρώσασι τὸν ὄνον ἕτοιμον πρὸς ἔξοδον αὐτῷ παρασκευάσαι."},{"number":238,"text":"τῶν δὲ σπευσάντων ὃ προσετάγησαν ἐπιβὰς ἐδίωξε τὸν προφήτην καὶ καταλαβὼν ἀναπαυόμενον ὑπὸ δένδρῳ δασεῖ καὶ σκιὰν ἔχοντι δρυὸς εὐμεγέθους ἠσπάσατο πρῶτον, εἶτʼ ἐμέμφετο μὴ παρʼ αὐτὸν εἰσελθόντα καὶ ξενίων μεταλαβόντα."},{"number":239,"text":"τοῦ δὲ φήσαντος κεκωλῦσθαι πρὸς τοῦ θεοῦ γεύσασθαι παρά τινι τῶν ἐν ἐκείνῃ τῇ πόλει, ἀλλʼ οὐχὶ παρʼ ἐμοὶ πάντως, εἶπεν, ἀπηγόρευκέ σοι τὸ θεῖον παραθέσθαι τράπεζαν· προφήτης γάρ εἰμι κἀγὼ καὶ τῆς αὐτῆς σοι κοινωνὸς πρὸς αὐτὸν θρησκείας, καὶ πάρειμι νῦν ὑπʼ αὐτοῦ πεμφθείς. ὅπως ἀγάγω σε πρὸς ἐμαυτὸν ἑστιασόμενον."},{"number":240,"text":"ὁ δὲ ψευσαμένῳ πεισθεὶς ἀνέστρεψεν· ἀριστώντων δʼ ἔτι καὶ φιλοφρονουμένων ὁ θεὸς ἐπιφαίνεται τῷ Ἰάδωνι καὶ παραβάντα τὰς ἐντολὰς αὐτοῦ τιμωρίαν ὑφέξειν ἔλεγεν καὶ ποδαπὴν ἐδήλου· λέοντα γὰρ αὐτῷ κατὰ τὴν ὁδὸν ἀπερχομένῳ συμβαλεῖν ἔφραζεν, ὑφʼ οὗ διαφθαρήσεσθαι καὶ τῆς ἐν τοῖς πατρῴοις μνήμασι ταφῆς ἀμοιρήσειν."},{"number":241,"text":"ταῦτα δʼ ἐγένετο οἶμαι κατὰ τὴν τοῦ θεοῦ βούλησιν, ὅπως μὴ προσέχοι τοῖς τοῦ Ἰάδωνος λόγοις Ἱεροβόαμος ἐληλεγμένῳ ψευδεῖ. πορευομένῳ τοίνυν τῷ Ἰάδωνι πάλιν εἰς Ἱεροσόλυμα συμβάλλει λέων καὶ κατασπάσας αὐτὸν ἀπὸ τοῦ κτήνους ἀπέκτεινε, καὶ τὸν μὲν ὄνον οὐδὲν ὅλως ἔβλαψε, παρακαθεζόμενος δʼ ἐφύλαττε κἀκεῖνον καὶ τὸ τοῦ προφήτου σῶμα, μέχρις οὗ τινες τῶν ὁδοιπόρων ἰδόντες ἀπήγγειλαν ἐλθόντες εἰς τὴν πόλιν τῷ ψευδοπροφήτῃ."},{"number":242,"text":"ὁ δὲ τοὺς υἱοὺς πέμψας ἐκόμισε τὸ σῶμα εἰς τὴν πόλιν καὶ πολυτελοῦς κηδείας ἠξίωσεν ἐντειλάμενος τοῖς παισὶ καὶ αὐτὸν ἀποθανόντα σὺν ἐκείνῳ θάψαι, λέγων ἀληθῆ μὲν εἶναι πάνθʼ ὅσα προεφήτευσε κατὰ τῆς πόλεως ἐκείνης καὶ τοῦ θυσιαστηρίου καὶ τῶν ἱερέων καὶ τῶν ψευδοπροφητῶν, ὑβρισθήσεσθαι δʼ αὐτὸς μετὰ τὴν τελευτὴν οὐδὲν σὺν ἐκείνῳ ταφεὶς τῶν ὀστῶν οὐ γνωρισθησομένων."},{"number":243,"text":"κηδεύσας οὖν τὸν προφήτην καὶ ταῦτα τοῖς υἱοῖς ἐντειλάμενος πονηρὸς ὢν καὶ ἀσεβὴς πρόσεισι τῷ Ἱεροβοάμῳ καὶ τί δήποτʼ ἐταράχθης, εἰπών, ὑπὸ τῶν τοῦ ἀνοήτου λόγων; ὡς τὰ περὶ τὸ θυσιαστήριον αὐτῷ καὶ τὴν αὑτοῦ χεῖρα διηγήσαθʼ ὁ βασιλεὺς θεῖον ἀληθῶς καὶ προφήτην ἄριστον ἀποκαλῶν, ἤρξατο ταύτην αὐτοῦ τὴν δόξαν ἀναλύειν κακουργῶν καὶ πιθανοῖς περὶ τῶν γεγενημένων χρώμενος λόγοις βλάπτειν αὐτῶν τὴν ἀλήθειαν."},{"number":244,"text":"ἐπεχείρει γὰρ πείθειν αὐτόν, ὡς ὑπὸ κόπου μὲν ἡ χεὶρ αὐτοῦ ναρκήσειε βαστάζουσα τὰς θυσίας, εἶτʼ ἀνεθεῖσα πάλιν εἰς τὴν αὑτῆς ἐπανέλθοι φύσιν, τὸ δὲ θυσιαστήριον καινὸν ὂν καὶ δεξάμενον θυσίας πολλὰς καὶ μεγάλας ῥαγείη καὶ πέσοι διὰ βάρος τῶν ἐπενηνεγμένων. ἐδήλου δʼ αὐτῷ καὶ τὸν θάνατον τοῦ τὰ σημεῖα ταῦτα προειρηκότος ὡς ὑπὸ λέοντος ἀπώλετο· οὕτως οὐδὲ ἓν οὔτʼ εἶχεν"},{"number":245,"text":"οὔτʼ ἐφθέγξατο προφήτου. ταῦτα εἰπὼν πείθει τὸν βασιλέα καὶ τὴν διάνοιαν αὐτοῦ τελέως ἀποστρέψας ἀπὸ τοῦ θεοῦ καὶ τῶν ὁσίων ἔργων καὶ δικαίων ἐπὶ τὰς ἀσεβεῖς πράξεις παρώρμησεν. οὕτως δʼ ἐξύβρισεν εἰς τὸ θεῖον καὶ παρηνόμησεν, ὡς οὐδὲν ἄλλο καθʼ ἡμέραν ζητεῖν ἢ τί καινὸν καὶ μιαρώτερον τῶν ἤδη τετολμημένων ἐργάσηται. καὶ τὰ μὲν περὶ Ἱεροβόαμον ἐπὶ τοῦ παρόντος ἐν τούτοις ἡμῖν δεδηλώσθω."},{"number":246,"text":"Ὁ δὲ Σολόμωνος υἱὸς Ῥοβόαμος ὁ τῶν δύο φυλῶν βασιλεύς, ὡς προειρήκαμεν, ᾠκοδόμησε πόλεις ὀχυράς τε καὶ μεγάλας Βηθλεὲμ καὶ Ἠταμὲ καὶ Θεκωὲ καὶ Βηθσοὺρ καὶ Σωχὼ καὶ Ὀδολλὰμ καὶ Εἰπὰν καὶ Μάρισαν καὶ τὴν Ζιφὰ καὶ Ἀδωραὶμ καὶ Λάχεις καὶ Ἀζηκὰ καὶ Σαρὰμ καὶ Ἠλὼμ καὶ Χεβρῶνα."},{"number":247,"text":"ταύτας μὲν ἐν τῇ Ἰουδαίᾳ φυλῇ καὶ κληρουχίᾳ πρώτας ᾠκοδόμησε, κατεσκεύασε δὲ καὶ ἄλλας μεγάλας ἐν τῇ Βενιαμίδι κληρουχίᾳ, καὶ τειχίσας φρουράς τε κατέστησεν ἐν ἁπάσαις καὶ ἡγεμόνας σῖτόν τε πολὺν καὶ οἶνον καὶ ἔλαιον τά τε ἄλλα πρὸς διατροφὴν ἐν ἑκάστῃ τῶν πόλεων δαψιλῶς ἀπέθετο, πρὸς δὲ τούτοις θυρεοὺς καὶ σιρομάστας εἰς πολλὰς μυριάδας."},{"number":248,"text":"συνῆλθον δὲ οἱ παρὰ πᾶσι τοῖς Ἰσραηλίταις ἱερεῖς πρὸς αὐτὸν εἰς Ἱεροσόλυμα καὶ Ληουῖται καὶ εἴ τινες ἄλλοι τοῦ πλήθους ἦσαν ἀγαθοὶ καὶ δίκαιοι καταλιπόντες αὑτῶν τὰς πόλεις, ἵνα θρησκεύσωσιν ἐν Ἱεροσολύμοις τὸν θεόν· οὐ γὰρ ἡδέως εἶχον προσκυνεῖν ἀναγκαζόμενοι τὰς δαμάλεις, ἃς Ἱεροβόαμος κατεσκεύασε· καὶ ηὔξησαν τὴν Ῥοβοάμου βασιλείαν ἐπʼ ἔτη τρία."},{"number":249,"text":"γήμας δὲ συγγενῆ τινα καὶ τρεῖς ποιησάμενος ἐξ αὐτῆς παῖδας ἤγετο ὕστερον καὶ τὴν ἐκ τῆς Ἀψαλώμου θυγατρὸς Θαμάρης Μαχάνην ὄνομα καὶ αὐτὴν οὖσαν συγγενῆ· καὶ παῖς ἐξ αὐτῆς ἄρρην αὐτῷ γίνεται, ὃν Ἀβίαν προσηγόρευσεν. τεκνοῖ δὲ καὶ ἐξ ἄλλων γυναικῶν πλειόνων, ἁπασῶν δὲ μᾶλλον ἔστερξε τὴν Μαχάνην."},{"number":250,"text":"εἶχε δὲ τὰς μὲν νόμῳ συνοικούσας αὐτῷ γυναῖκας ὀκτωκαίδεκα παλλακὰς δὲ τριάκοντα, καὶ υἱοὶ μὲν αὐτῷ γεγόνεισαν ὀκτὼ καὶ εἴκοσι θυγατέρες δʼ ἑξήκοντα. διάδοχον δὲ ἀπέδειξε τῆς βασιλείας τὸν ἐκ τῆς Μαχάνης Ἀβίαν καὶ τοὺς θησαυροὺς αὐτῷ καὶ τὰς ὀχυρωτάτας πόλεις ἐπίστευσεν."},{"number":251,"text":"Αἴτιον δʼ οἶμαι πολλάκις γίνεται κακῶν καὶ παρανομίας τοῖς ἀνθρώποις τὸ τῶν πραγμάτων μέγεθος καὶ ἡ πρὸς τὸ βέλτιον αὐτῶν τροπή· τὴν γὰρ βασιλείαν αὐξανομένην οὕτω βλέπων Ῥοβόαμος εἰς ἀδίκους καὶ ἀσεβεῖς ἐξετράπη πράξεις καὶ τῆς τοῦ θεοῦ θρησκείας κατεφρόνησεν, ὡς καὶ τὸν ὑπʼ αὐτῷ λαὸν μιμητὴν γενέσθαι τῶν ἀνομημάτων."},{"number":252,"text":"συνδιαφθείρεται γὰρ τὰ τῶν ἀρχομένων ἤθη τοῖς τῶν ἡγουμένων τρόποις, καὶ ὡς ἔλεγχον τῆς ἐκείνων ἀσελγείας τὴν αὑτῶν σωφροσύνην παραπέμποντες ὡς ἀρετῇ ταῖς κακίαις αὐτῶν ἕπονται· οὐ γὰρ ἔνεστιν ἀποδέχεσθαι δοκεῖν τὰ τῶν βασιλέων ἔργα μὴ ταὐτὰ πράττοντας."},{"number":253,"text":"τοῦτο τοίνυν συνέβαινε καὶ τοῖς ὑπὸ Ῥοβοάμῳ τεταγμένοις ἀσεβοῦντος αὐτοῦ καὶ παρανομοῦντος σπουδάζειν, μὴ προσκρούσωσι τῷ βασιλεῖ θέλοντες εἶναι δίκαιοι. τιμωρὸν δὲ τῶν εἰς αὐτὸν ὕβρεων ὁ θεὸς ἐπιπέμπει τὸν Αἰγυπτίων βασιλέα Ἴσωκον, περὶ οὗ πλανηθεὶς Ἡρόδοτος τὰς πράξεις αὐτοῦ Σεσώστρει προσάπτει."},{"number":254,"text":"οὗτος γὰρ ὁ Ἴσωκος πέμπτῳ ἔτει τῆς Ῥοβοάμου βασιλείας ἐπιστρατεύεται μετὰ πολλῶν αὐτῷ μυριάδων· ἅρματα μὲν γὰρ αὐτῷ χίλια καὶ διακόσια τὸν ἀριθμὸν ἠκολούθει, ἱππέων δὲ μυριάδες ἕξ, πεζῶν δὲ μυριάδες τεσσαράκοντα. τούτων τοὺς πλείστους Λίβυας ἐπήγετο καὶ Αἰθίοπας."},{"number":255,"text":"ἐμβαλὼν οὖν εἰς τὴν χώραν τῶν Ἑβραίων καταλαμβάνει τε τὰς ὀχυρωτάτας τῆς Ῥοβοάμου βασιλείας πόλεις ἀμαχητὶ καὶ ταύτας ἀσφαλισάμενος ἔσχατον ἐπῆλθε τοῖς Ἱεροσολύμοις ἐγκεκλεισμένου τοῦ Ῥοβοάμου καὶ τοῦ πλήθους ἐν αὐτοῖς διὰ τὴν Ἰσώκου στρατείαν καὶ τὸν θεὸν ἱκετευόντων δοῦναι νίκην καὶ σωτηρίαν·"},{"number":256,"text":"ἀλλʼ οὐκ ἔπεισαν τὸν θεὸν ταχθῆναι μετʼ αὐτῶν· ὁ δὲ προφήτης Σαμαίας ἔφησεν αὐτοῖς τὸν θεὸν ἀπειλεῖν ἐγκαταλείψειν αὐτούς, ὡς καὶ αὐτοὶ τὴν θρησκείαν αὐτοῦ κατέλιπον. ταῦτʼ ἀκούσαντες εὐθὺς ταῖς ψυχαῖς ἀνέπεσον καὶ μηδὲν ἔτι σωτήριον ὁρῶντες ἐξομολογεῖσθαι πάντες ὥρμησαν, ὅτι δικαίως αὐτοὺς ὁ θεὸς ὑπερόψεται γενομένους περὶ αὐτὸν ἀσεβεῖς καὶ συγχέοντας τὰ νόμιμα."},{"number":257,"text":"κατιδὼν δʼ αὐτοὺς ὁ θεὸς οὕτω διακειμένους καὶ τὰς ἁμαρτίας ἀνθομολογουμένους οὐκ ἀπολέσειν αὐτοὺς εἶπε πρὸς τὸν προφήτην, ποιήσειν μέντοι γε τοῖς Αἰγυπτίοις ὑποχειρίους, ἵνα μάθωσι πότερον ἀνθρώπῳ δουλεύειν ἐστὶν ἀπονώτερον ἢ θεῷ."},{"number":258,"text":"παραλαβὼν δὲ Ἴσωκος ἀμαχητὶ τὴν πόλιν δεξαμένου Ῥοβοάμου διὰ τὸν φόβον οὐκ ἐνέμεινε ταῖς γενομέναις συνθήκαις, ἀλλʼ ἐσύλησε τὸ ἱερὸν καὶ τοὺς θησαυροὺς ἐξεκένωσε τοῦ θεοῦ καὶ τοὺς βασιλικοὺς χρυσοῦ καὶ ἀργύρου μυριάδας ἀναριθμήτους βαστάσας καὶ μηδὲν ὅλως ὑπολιπών."},{"number":259,"text":"περιεῖλε δὲ καὶ τοὺς χρυσοῦς θυρεοὺς καὶ τὰς ἀσπίδας, ἃς κατεσκεύασε Σολόμων ὁ βασιλεύς, οὐκ εἴασε δὲ οὐδὲ τὰς χρυσᾶς φαρέτρας, ἃς ἀνέθηκε Δαυίδης τῷ θεῷ λαβὼν παρὰ τοῦ τῆς Σωφηνῆς βασιλέως, καὶ τοῦτο ποιήσας ἀνέστρεψεν εἰς τὰ οἰκεῖα."},{"number":260,"text":"μέμνηται δὲ ταύτης τῆς στρατείας καὶ ὁ Ἁλικαρνασεὺς Ἡρόδοτος περὶ μόνον τὸ τοῦ βασιλέως πλανηθεὶς ὄνομα, καὶ ὅτι ἄλλοις τε πολλοῖς ἐπῆλθεν ἔθνεσι καὶ τὴν Παλαιστίνην Συρίαν ἐδουλώσατο λαβὼν ἀμαχητὶ τοὺς ἀνθρώπους τοὺς ἐν αὐτῇ."},{"number":261,"text":"φανερὸν δʼ ἐστίν, ὅτι τὸ ἡμέτερον ἔθνος βούλεται δηλοῦν κεχειρωμένον ὑπὸ τοῦ Αἰγυπτίου· ἐπάγει γάρ, ὅτι στήλας κατέλιπεν ἐν τῇ τῶν ἀμαχητὶ παραδόντων ἑαυτοὺς αἰδοῖα γυναικῶν ἐγγράψας· Ῥοβόαμος δʼ αὐτῷ παρέδωκεν ὁ ἡμέτερος βασιλεὺς ἀμαχητὶ τὴν πόλιν."},{"number":262,"text":"φησὶ δὲ καὶ Αἰθίοπας παρʼ Αἰγυπτίων μεμαθηκέναι τὴν τῶν αἰδοίων περιτομήν· Φοίνικες γὰρ καὶ Σύροι οἱ ἐν τῇ Παλαιστίνῃ ὁμολογοῦσι παρʼ Αἰγυπτίων μεμαθηκέναι. δῆλον οὖν ἐστιν, ὅτι μηδένες ἄλλοι περιτέμνονται τῶν ἐν τῇ Παλαιστίνῃ Σύρων ἢ μόνοι ἡμεῖς. ἀλλὰ περὶ μὲν τούτων ἕκαστοι λεγέτωσαν ὅ τι ἂν αὐτοῖς δοκῇ."},{"number":263,"text":"Ἀναχωρήσαντος δὲ Ἰσώκου Ῥοβόαμος ὁ βασιλεὺς ἀντὶ μὲν τῶν χρυσέων θυρεῶν καὶ τῶν ἀσπίδων χάλκεα ποιήσας τὸν αὐτὸν ἀριθμὸν παρέδωκε τοῖς τῶν βασιλείων φύλαξιν. ἀντὶ δὲ τοῦ μετὰ στρατηγίας ἐπιφανοῦς καὶ τῆς ἐν τοῖς πράγμασι λαμπρότητος διάγειν ἐβασίλευσεν ἐν ἡσυχίᾳ πολλῇ καὶ δέει πάντα τὸν χρόνον ἐχθρὸς ὢν Ἱεροβοάμῳ."},{"number":264,"text":"ἐτελεύτησε δὲ βιώσας ἔτη πεντήκοντα καὶ ἑπτὰ βασιλεύσας δʼ αὐτῶν ἑπτακαίδεκα, τὸν τρόπον ἀλαζὼν ἀνὴρ καὶ ἀνόητος καὶ διὰ τὸ μὴ προσέχειν τοῖς πατρῴοις φίλοις τὴν ἀρχὴν ἀπολέσας· ἐτάφη δʼ ἐν Ἱεροσολύμοις ἐν ταῖς θήκαις τῶν βασιλέων. διεδέξατο δʼ αὐτοῦ τὴν βασιλείαν ὁ υἱὸς Ἀβίας ὄγδοον ἤδη καὶ δέκατον ἔτος Ἱεροβοάμου τῶν δέκα φυλῶν βασιλεύοντος."},{"number":265,"text":"καὶ ταῦτα μὲν τοιοῦτον ἔσχε τὸ τέλος· τὰ δὲ περὶ Ἱεροβόαμον ἀκόλουθα τούτων ἔχομεν πῶς κατέστρεψε τὸν βίον διεξελθεῖν· οὗτος γὰρ οὐ διέλιπεν οὐδʼ ἠρέμησεν εἰς τὸν θεὸν ἐξυβρίζων, ἀλλὰ καθʼ ἑκάστην ἐπὶ τῶν ὑψηλῶν ὀρῶν βωμοὺς ἀνιστὰς καὶ ἱερεῖς ἐκ τοῦ πλήθους ἀποδεικνὺς διετέλει."}],"11":[{"number":266,"text":"Ταῦτα δʼ ἔμελλεν οὐκ εἰς μακρὰν τἀσεβήματα καὶ τὴν ὑπὲρ αὐτῶν δίκην εἰς τὴν αὐτοῦ κεφαλὴν καὶ πάσης αὐτοῦ τῆς γενεᾶς τρέψειν τὸ θεῖον. κάμνοντος δʼ αὐτῷ κατʼ ἐκεῖνον τὸν καιρὸν τοῦ παιδός, ὃν Ὀβίμην ἐκάλουν, τὴν γυναῖκα αὐτοῦ προσέταξε τὴν στολὴν ἀποθεμένην καὶ σχῆμα λαβοῦσαν ἰδιωτικὸν πορευθῆναι πρὸς Ἀχίαν τὸν προφήτην·"},{"number":267,"text":"εἶναι γὰρ θαυμαστὸν ἄνδρα περὶ τῶν μελλόντων προειπεῖν· καὶ γὰρ περὶ τῆς βασιλείας αὐτῷ τοῦτον δεδηλωκέναι· παραγενομένην δʼ ἐκέλευσε περὶ τοῦ παιδὸς ἀνακρίνειν ὡς ξένην, εἰ διαφεύξεται τὴν νόσον. ἡ δὲ μετασχηματισαμένη, καθὼς αὐτῇ προσέταξεν ὁ ἀνήρ, ἧκεν εἰς Σιλὼ πόλιν· ἐκεῖ γὰρ διέτριβεν ὁ Ἀχίας."},{"number":268,"text":"καὶ μελλούσης εἰς τὴν οἰκίαν αὐτοῦ εἰσιέναι τὰς ὄψεις ἠμαυρωμένου διὰ τὸ γῆρας ἐπιφανεὶς ὁ θεὸς ἀμφότερα αὐτῷ μηνύει τήν τε Ἱεροβοάμου γυναῖκα πρὸς αὐτὸν ἀφιγμένην καὶ τί δεῖ περὶ ὧν πάρεστιν ἀποκρίνασθαι."},{"number":269,"text":"παριούσης δὲ τῆς γυναικὸς εἰς τὴν οἰκίαν ὡς ἰδιώτιδος καὶ ξένης ἀνεβόησεν εἴσελθε, ὦ γύναι Ἱεροβοάμου· τί κρύπτεις σαυτήν; τὸν γὰρ θεὸν οὐ λανθάνεις, ὃς ἀφιξομένην τέ μοι ἐδήλωσε καὶ προσέταξε τίνας ποιήσομαι τοὺς λόγους. ἀπελθοῦσα οὖν πρὸς τὸν ἄνδρα φράζε αὐτῷ ταῦτα λέγειν·"},{"number":270,"text":"ἐπεί σε μέγαν ἐκ μικροῦ καὶ μηδενὸς ὄντος ἐποίησα καὶ ἀποσχίσας τὴν βασιλείαν ἀπὸ τοῦ Δαυίδου γένους σοὶ ταύτην ἔδωκα, σὺ δὲ τούτων ἠμνημόνησας καὶ τὴν ἐμὴν θρησκείαν καταλιπὼν χωνευτοὺς θεοὺς κατασκευάσας ἐκείνους τιμᾷς, οὕτω σε πάλιν καθαιρήσω καὶ πᾶν ἐξολέσω σου τὸ γένος καὶ κυσὶ καὶ ὄρνισι βορὰν ποιήσω γενέσθαι."},{"number":271,"text":"βασιλεὺς γὰρ ἐξεγείρεθʼ ὑπʼ ἐμοῦ τοῦ λαοῦ παντός, ὃς οὐδένα ὑπολείψει τοῦ Ἱεροβοάμου γένους· μεθέξει δὲ τῆς τιμωρίας καὶ τὸ πλῆθος ἐκπεσὸν τῆς ἀγαθῆς γῆς καὶ διασπαρὲν εἰς τοὺς πέραν Εὐφράτου τόπους, ὅτι τοῖς τοῦ βασιλέως ἀσεβήμασι κατηκολούθησε καὶ τοὺς ὑπʼ αὐτοῦ γενομένους προσκυνεῖ θεοὺς τὴν ἐμὴν θυσίαν ἐγκαταλιπόν."},{"number":272,"text":"σὺ δέ, ὦ γύναι, ταῦτα ἀπαγγέλλουσα σπεῦδε πρὸς τὸν ἄνδρα. τὸν δὲ υἱὸν καταλήψῃ τεθνηκότα· σοῦ γὰρ εἰσιούσης εἰς τὴν πόλιν ἀπολείψει τὸ ζῆν αὐτόν. ταφήσεται δὲ κλαυθεὶς ὑπὸ τοῦ πλήθους παντὸς κοινῷ τιμηθεὶς πένθει· καὶ γὰρ μόνος τῶν ἐκ τοῦ Ἱεροβοάμου γένους ἀγαθὸς οὗτος ἦν."},{"number":273,"text":"ταῦτʼ αὐτοῦ προφητεύσαντος ἐκπηδήσασα ἡ γυνὴ τεταραγμένη καὶ τῷ τοῦ προειρημένου παιδὸς θανάτῳ περιαλγής, θρηνοῦσα διὰ τῆς ὁδοῦ καὶ τὴν μέλλουσαν τοῦ τέκνου κοπτομένη τελευτὴν ἀθλία τοῦ πάθους ἠπείγετο κακοῖς ἀμηχάνοις καὶ σπουδῇ μὲν ἀτυχεῖ χρωμένη διὰ τὸν υἱὸν αὐτῆς, ἔμελλε γὰρ αὐτὸν ἐπειχθεῖσα θᾶττον ὄψεσθαι νεκρόν, ἀναγκαίᾳ δὲ διὰ τὸν ἄνδρα. καὶ παραγενομένη τὸν μὲν ἐκπεπνευκότα καθὼς εἶπεν ὁ προφήτης εὗρε, τῷ δὲ βασιλεῖ πάντα ἀπήγγειλεν."},{"number":274,"text":"Ἱεροβόαμος δʼ οὐδενὸς τούτων φροντίσας πολλὴν ἀθροίσας στρατιὰν ἐπὶ τὸν Ῥοβοάμου παῖδα τῶν δύο φυλῶν τὴν βασιλείαν τοῦ πατρὸς διαδεξάμενον Ἀβίαν ἐξεστράτευσε πολεμήσων· κατεφρόνει γὰρ αὐτοῦ διὰ τὴν ἡλικίαν. ὁ δὲ ἀκούσας τὴν ἔφοδον τὴν Ἱεροβοάμου πρὸς αὐτὴν οὐ κατεπλάγη, γενόμενος δʼ ἐπάνω καὶ τῆς νεότητος τῷ φρονήματι καὶ τῆς ἐλπίδος τοῦ πολεμίου στρατιὰν ἐπιλέξας ἐκ τῶν δύο φυλῶν ἀπήντησε τῷ Ἱεροβοάμῳ εἰς τόπον τινὰ καλούμενον ὄρος Σαμαρῶν καὶ στρατοπεδευσάμενος ἐγγὺς αὐτοῦ τὰ πρὸς τὴν μάχην εὐτρέπιζεν."},{"number":275,"text":"ἦν δʼ ἡ δύναμις αὐτοῦ μυριάδες τεσσαράκοντα, ἡ δὲ τοῦ Ἱεροβοάμου στρατιὰ διπλασίων ἐκείνης. ὡς δὲ τὰ στρατεύματα πρὸς τὰ ἔργα καὶ τοὺς κινδύνους ἀντιπαρετάσσετο καὶ συμβαλεῖν ἔμελλε, στὰς ἐφʼ ὑψηλοῦ τινος Ἀβίας τόπου καὶ τῇ χειρὶ κατασείσας τὸ πλῆθος καὶ τὸν Ἱεροβόαμον ἀκοῦσαι πρῶτον αὐτοῦ μεθʼ ἡσυχίας ἠξίωσε."},{"number":276,"text":"γενομένης δὲ σιωπῆς ἤρξατο λέγειν· ὅτι μὲν τὴν ἡγεμονίαν ὁ θεὸς Δαυίδῃ καὶ τοῖς ἐκγόνοις αὐτοῦ κατένευσεν εἰς ἅπαντα χρόνον, οὐδʼ ὑμεῖς ἀγνοεῖτε, θαυμάζω δέ, πῶς ἀποστάντες τοὐμοῦ πατρὸς τῷ δούλῳ Ἱεροβοάμῳ προσέθεσθε καὶ μετʼ ἐκείνου πάρεστε νῦν ἐπὶ τοὺς ὑπὸ τοῦ θεοῦ βασιλεύειν κεκριμένους πολεμήσοντες καὶ τὴν ἀρχὴν ἀφαιρησόμενοι τὴν ὑπάρχουσαν· τὴν μὲν γὰρ πλείω μέχρι νῦν Ἱεροβόαμος ἀδίκως ἔχει."},{"number":277,"text":"ἀλλʼ οὐκ οἶμαι καὶ ταύτης αὐτὸν ἀπολαύσειν ἐπὶ πλείονα χρόνον, ἀλλὰ δοὺς καὶ τοῦ παρεληλυθότος δίκην τῷ θεῷ παύσεται τῆς παρανομίας καὶ τῶν ὕβρεων, ἃς οὐ διαλέλοιπεν εἰς αὐτὸν ὑβρίζων καὶ ταὐτὰ ποιεῖν ὑμᾶς ἀναπεπεικώς, οἳ μηδὲν ἀδικηθέντες ὑπὸ τοῦ πατρός, ἀλλʼ ὅτι μὴ πρὸς ἡδονὴν ἐκκλησιάζων ὡμίλησεν ἀνθρώπων πονηρῶν συμβουλίᾳ πεισθείς, ἐγκατελίπετε τῷ δοκεῖν ὑπʼ ὀργῆς ἐκεῖνον, ταῖς δʼ ἀληθείαις αὑτοὺς ἀπὸ τοῦ θεοῦ καὶ τῶν ἐκείνου νόμων ἀπεσπάσατε."},{"number":278,"text":"καίτοι συνεγνωκέναι καλῶς εἶχεν ὑμᾶς οὐ λόγων μόνον δυσκόλων ἀνδρὶ νέῳ καὶ δημαγωγίας ἀπείρῳ, ἀλλʼ εἰ καὶ πρός τι δυσχερὲς ἡ νεότης αὐτὸν καὶ ἡ ἀμαθία τῶν πραττομένων ἐξῆγεν ἔργον, διά τε Σολόμωνα τὸν πατέρα καὶ τὰς εὐεργεσίας τὰς ἐκείνου· παραίτησιν γὰρ εἶναι δεῖ τῆς τῶν ἐγγόνων ἁμαρτίας τὰς τῶν πατέρων εὐποιίας."},{"number":279,"text":"ὑμεῖς δʼ οὐδὲν τούτων ἐλογίσασθε οὔτε τότʼ οὔτε νῦν, ἀλλʼ ἧκε στρατὸς ἐφʼ ἡμᾶς τοσοῦτος· τίνι καὶ πεπιστευκὼς περὶ τῆς νίκης; ἦ ταῖς χρυσαῖς δαμάλεσι καὶ τοῖς ἐπὶ τῶν ὀρῶν βωμοῖς, ἃ δείγματα τῆς ἀσεβείας ἐστὶν ὑμῶν ἀλλʼ οὐχὶ τῆς θρησκείας; ἢ τὸ πλῆθος ὑμᾶς εὐέλπιδας ἀπεργάζεται τὴν ἡμετέραν στρατιὰν ὑπερβάλλον;"},{"number":280,"text":"ἀλλʼ οὐδʼ ἥτις ἰσχὺς μυριάδων στρατοῦ μετʼ ἀδικημάτων πολεμοῦντος· ἐν γὰρ μόνῳ τῷ δικαίῳ καὶ πρὸς τὸ θεῖον εὐσεβεῖ τὴν βεβαιοτάτην ἐλπίδα τοῦ κρατεῖν τῶν ἐναντίων ἀποκεῖσθαι συμβέβηκεν, ἥτις ἐστὶ παρʼ ἡμῖν τετηρηκόσιν ἀπʼ ἀρχῆς τὰ νόμιμα καὶ τὸν ἴδιον θεὸν σεβομένοις, ὃν οὐ χεῖρες ἐποίησαν ἐξ ὕλης φθαρτῆς οὐδʼ ἐπίνοια πονηροῦ βασιλέως ἐπὶ τῇ τῶν ὄχλων ἀπάτῃ κατεσκεύασεν, ἀλλʼ ὃς ἔργον ἐστὶν αὑτοῦ καὶ ἀρχὴ καὶ τέλος τῶν ἁπάντων."},{"number":281,"text":"συμβουλεύω τοιγαροῦν ὑμῖν ἔτι καὶ νῦν μεταγνῶναι καὶ λαβόντας ἀμείνω λογισμὸν παύσασθαι τοῦ πολεμεῖν καὶ τὰ πάτρια καὶ τὸ προαγαγὸν ὑμᾶς ἐπὶ τοσοῦτον μέγεθος εὐδαιμονίας γνωρίσαι."},{"number":282,"text":"Ταῦτα μὲν Ἀβίας διελέχθη πρὸς τὸ πλῆθος· ἔτι δὲ αὐτοῦ λέγοντος λάθρα τινὰς τῶν στρατιωτῶν Ἱεροβόαμος ἔπεμψε περικυκλωσομένους τὸν Ἀβίαν ἔκ τινων οὐ φανερῶν τοῦ στρατοπέδου μερῶν. μέσου δʼ αὐτοῦ περιληφθέντος τῶν πολεμίων ἡ μὲν στρατιὰ κατέδεισε καὶ ταῖς ψυχαῖς ἀνέπεσεν, ὁ δʼ Ἀβίας παρεθάρρυνε καὶ τὰς ἐλπίδας ἔχειν ἐν τῷ θεῷ παρεκάλει· τοῦτον γὰρ οὐ κεκυκλῶσθαι πρὸς τῶν πολεμίων."},{"number":283,"text":"οἱ δὲ ὁμοῦ πάντες ἐπικαλεσάμενοι τὴν παρὰ τοῦ θεοῦ συμμαχίαν τῶν ἱερέων τῇ σάλπιγγι σημανάντων ἀλαλάξαντες ἐχώρησαν ἐπὶ τοὺς πολεμίους· καὶ τῶν μὲν ἔθραυσε τὰ φρονήματα καὶ τὰς ἀκμὰς αὐτῶν ἐξέλυσεν ὁ θεός, τὴν δὲ Ἀβία στρατιὰν ὑπερτέραν ἐποίησεν·"},{"number":284,"text":"ὅσος γὰρ οὐδέποτʼ ἐμνημονεύθη φόνος ἐν πολέμῳ γεγονέναι οὔθʼ Ἑλλήνων οὔτε βαρβάρων, τοσούτους ἀποκτείναντες τῆς Ἱεροβοάμου δυνάμεως θαυμαστὴν καὶ διαβόητον νίκην παρὰ τοῦ θεοῦ λαβεῖν ἠξιώθησαν· πεντήκοντα γὰρ μυριάδας τῶν ἐχθρῶν κατέβαλον καὶ τὰς πόλεις αὐτῶν διήρπασαν τὰς ὀχυρωτάτας ἑλόντες κατὰ κράτος, τήν τε Βηθήλην καὶ τὴν τοπαρχίαν αὐτῆς καὶ τὴν Ἰσανὰν καὶ τὴν τοπαρχίαν αὐτῆς."},{"number":285,"text":"καὶ Ἱεροβόαμος μὲν οὐκέτι μετὰ ταύτην τὴν ἧτταν ἴσχυσεν ἐφʼ ὅσον Ἀβίας περιῆν χρόνον. τελευτᾷ δʼ οὗτος ὀλίγον τῇ νίκῃ χρόνον ἐπιζήσας ἔτη βασιλεύσας τρία, καὶ θάπτεται μὲν ἐν Ἱεροσολύμοις ἐν ταῖς προγονικαῖς θήκαις, ἀπολείπει δὲ υἱοὺς μὲν δύο καὶ εἴκοσι θυγατέρας δὲ ἓξ καὶ δέκα. πάντας τούτους ἐκ γυναικῶν δεκατεσσάρων ἐτεκνώσατο."},{"number":286,"text":"διεδέξατο δʼ αὐτοῦ τὴν βασιλείαν ὁ υἱὸς αὐτοῦ Ἄσανος· καὶ ἡ μήτηρ τοῦ νεανίσκου Μαχαία τοὔνομα. τούτου κρατοῦντος εἰρήνης ἀπέλαυεν ἡ χώρα τῶν Ἰσραηλιτῶν ἐπὶ ἔτη δέκα."},{"number":287,"text":"Καὶ τὰ μὲν περὶ Ἀβίαν τὸν Ῥοβοάμου τοῦ Σολόμωνος οὕτως παρειλήφαμεν. ἐτελεύτησε δὲ καὶ Ἱεροβόαμος ὁ τῶν δέκα φυλῶν βασιλεὺς ἄρξας ἔτη δύο καὶ εἴκοσι. διαδέχεται δʼ αὐτὸν ὁ παῖς Νάβαδος δευτέρου ἔτους ἤδη τῆς βασιλείας Ἀσάνου διεληλυθότος. ἦρξε δὲ ὁ τοῦ Ἱεροβοάμου παῖς ἔτη δύο τῷ πατρὶ τὴν ἀσέβειαν καὶ τὴν πονηρίαν ἐμφερὴς ὤν."},{"number":288,"text":"ἐν δὲ τούτοις τοῖς δυσὶν ἔτεσι στρατευσάμενος ἐπὶ Γαβαθῶνα πόλιν Παλαιστίνων οὖσαν πολιορκίᾳ λαβεῖν αὐτὴν προσέμενεν· ἐπιβουλευθεὶς δʼ ἐκεῖ ὑπὸ φίλου τινὸς Βασάνου ὄνομα Σειδοῦ δὲ παιδὸς ἀποθνήσκει, ὃς μετὰ τὴν τελευτὴν αὐτοῦ τὴν βασιλείαν παραλαβὼν ἅπαν τὸ Ἱεροβοάμου γένος διέφθειρε."},{"number":289,"text":"καὶ συνέβη κατὰ τὴν τοῦ θεοῦ προφητείαν τοὺς μὲν ἐν τῇ πόλει τῶν Ἱεροβοάμου συγγενῶν ἀποθανόντας ὑπὸ κυνῶν σπαραχθῆναι καὶ δαπανηθῆναι, τοὺς δʼ ἐν τοῖς ἀγροῖς ὑπʼ ὀρνίθων. ὁ μὲν οὖν Ἱεροβοάμου οἶκος τῆς ἀσεβείας αὐτοῦ καὶ τῶν ἀνομημάτων ἀξίαν ὑπέσχε δίκην."}],"12":[{"number":290,"text":"Ὁ δὲ τῶν Ἱεροσολύμων βασιλεὺς Ἄσανος ἦν τὸν τρόπον ἄριστος καὶ πρὸς τὸ θεῖον ἀφορῶν καὶ μηδὲν μήτε πράττων μήτʼ ἐννοούμενος, ὃ μὴ πρὸς τὴν εὐσέβειαν εἶχε καὶ τὴν τῶν νομίμων φυλακὴν τὴν ἀναφοράν. κατώρθωσε δὲ τὴν αὑτοῦ βασιλείαν ἐκκόψας εἴ τι πονηρὸν ἦν ἐν αὐτῇ καὶ καθαρεύσας ἁπάσης κηλῖδος."},{"number":291,"text":"στρατοῦ δʼ εἶχεν ἐπιλέκτων ἀνδρῶν ὡπλισμένων θυρεὸν καὶ σιρομάστην ἐκ μὲν τῆς Ἰούδα φυλῆς μυριάδας τριάκοντα, ἐκ δὲ τῆς Βενιαμίτιδος ἀσπίδας φορούντων καὶ τοξοτῶν μυριάδας πέντε καὶ εἴκοσι."},{"number":292,"text":"ἤδη δὲ αὐτοῦ δέκα ἔτη βασιλεύοντος στρατεύει μεγάλῃ δυνάμει Ζαραῖος ἐπʼ αὐτὸν ὁ τῆς Αἰθιοπίας βασιλεὺς ἐνενήκοντα μὲν πεζῶν μυριάσιν ἱππέων δὲ δέκα τριακοσίοις δʼ ἅρμασι. καὶ μέχρι πόλεως Μαρήσας, ἔστι δʼ αὕτη τῆς Ἰούδα φυλῆς, ἐλάσαντος αὐτοῦ μετὰ τῆς οἰκείας δυνάμεως ἀπήντησεν Ἄσανος,"},{"number":293,"text":"καὶ ἀντιπαρατάξας αὐτῷ τὴν στρατιὰν ἔν τινι φάραγγι Σαβαθὰ λεγομένῃ τῆς πόλεως οὐκ ἄπωθεν, ὡς κατεῖδε τὸ τῶν Αἰθιόπων πλῆθος ἀναβοήσας νίκην ᾔτει παρὰ τοῦ θεοῦ καὶ τὰς πολλὰς ἑλεῖν μυριάδας τῶν πολεμίων· οὐδὲ γὰρ ἄλλῳ τινὶ θαρσήσας ἔλεγεν ἢ τῇ παρʼ αὐτοῦ βοηθείᾳ δυναμένῃ καὶ τοὺς ὀλίγους ἀπεργάσασθαι κρείττους τῶν πλειόνων καὶ τοὺς ἀσθενεῖς τῶν ὑπερεχόντων ἀπαντῆσαι πρὸς μάχην τῷ Ζαραίῳ."},{"number":294,"text":"Ταῦτα λέγοντος Ἀσάνου νίκην ἐσήμαινεν ὁ θεός, καὶ συμβαλὼν μετὰ χαρᾶς τῶν προδεδηλωμένων ὑπὸ τοῦ θεοῦ πολλοὺς ἀποκτείνει τῶν Αἰθιόπων καὶ τραπέντας εἰς φυγὴν ἐδίωξεν ἄχρι τῆς Γεραρίτιδος χώρας. ἀφέμενοι δὲ τῆς ἀναιρέσεως ἐπὶ τὴν διαρπαγὴν τῶν πόλεων, ἥλω γὰρ ἡ Γεράρων, ἐχώρησαν καὶ τῆς παρεμβολῆς αὐτῶν, ὡς πολὺν μὲν ἐκφορῆσαι χρυσὸν πολὺν δὲ ἄργυρον λείαν τε ἀπαγαγεῖν καμήλους τε καὶ ὑποζύγια καὶ βοσκημάτων ἀγέλας."},{"number":295,"text":"Ἄσανος μὲν οὖν καὶ ἡ παρʼ αὐτῷ στρατιὰ τοιαύτην παρὰ τοῦ θεοῦ νίκην λαβόντες καὶ ὠφέλειαν ἀνέστρεφον εἰς Ἱεροσόλυμα, παραγενομένοις δὲ αὐτοῖς ἀπήντησε κατὰ τὴν ὁδὸν προφήτης Ἀζαρίας ὄνομα. οὗτος ἐπισχεῖν κελεύσας τῆς ὁδοιπορίας ἤρξατο λέγειν πρὸς αὐτούς, ὅτι ταύτης εἶεν τῆς νίκης παρὰ τοῦ θεοῦ τετυχηκότες, ὅτι δικαίους καὶ ὁσίους ἑαυτοὺς παρέσχον καὶ πάντα κατὰ βούλησιν θεοῦ πεποιηκότας."},{"number":296,"text":"ἐπιμένουσι μὲν οὖν ἔφασκεν ἀεὶ κρατεῖν αὐτοὺς τῶν ἐχθρῶν καὶ τὸ ζῆν μετʼ εὐδαιμονίας παρέξειν τὸν θεόν, ἀπολιποῦσι δὲ τὴν θρησκείαν ἅπαντα τούτων ἐναντία συμβήσεσθαι καὶ γενήσεσθαι χρόνον ἐκεῖνον, ἐν ᾧ μηδεὶς ἀληθὴς εὑρεθήσεται προφήτης ἐν τῷ ὑμετέρῳ ὄχλῳ οὐδὲ ἱερεὺς τὰ δίκαια χρηματίζων,"},{"number":297,"text":"ἀλλὰ καὶ αἱ πόλεις ἀνάστατοι γενήσονται καὶ τὸ ἔθνος κατὰ πάσης σπαρήσεται γῆς ἔπηλυν βίον καὶ ἀλήτην βιωσόμενον. καιρὸν δʼ αὐτοῖς ἔχουσι συνεβούλευεν ἀγαθοῖς γίνεσθαι καὶ μὴ φθονῆσαι τῆς εὐμενείας αὑτοῖς τοῦ θεοῦ. ταῦτʼ ἀκούσας ὁ βασιλεὺς καὶ ὁ λαὸς ἐχάρησαν καὶ πολλὴν πρόνοιαν ἐποιοῦντο κοινῇ τε πάντες καὶ κατʼ ἰδίαν τοῦ δικαίου· διέπεμψε δʼ ὁ βασιλεὺς καὶ τοὺς ἐν τῇ χώρᾳ τῶν νομίμων ἐπιμελησομένους."},{"number":298,"text":"Καὶ τὰ μὲν Ἀσάνου τοῦ βασιλέως τῶν δύο φυλῶν ἐν τούτοις ὑπῆρχεν. ἐπάνειμι δʼ ἐπὶ τὸ πλῆθος τῶν Ἰσραηλιτῶν καὶ τὸν βασιλέα αὐτῶν Βασάνην τὸν ἀποκτείναντα τὸν Ἱεροβοάμου υἱὸν Νάβαδον καὶ κατασχόντα τὴν ἀρχήν."},{"number":299,"text":"οὗτος γὰρ ἐν Θαρσάλῃ πόλει διατρίβων καὶ ταύτην οἰκητήριον πεποιηκὼς εἴκοσι μὲν ἐβασίλευσεν ἔτη καὶ τέσσαρα, πονηρὸς δὲ καὶ ἀσεβὴς ὑπὲρ Ἱεροβόαμον καὶ τὸν υἱὸν αὐτοῦ γενόμενος πολλὰ καὶ τὸ πλῆθος κακὰ διέθηκε καὶ τὸν θεὸν ἐξύβρισεν· ὃς αὐτῷ πέμψας Ἰηοῦν τὸν προφήτην προεῖπε διαφθερεῖν αὐτοῦ πᾶν τὸ γένος καὶ τοῖς αὐτοῖς οἷς καὶ τὸν Ἱεροβοάμου κακοῖς περιέβαλεν οἶκον ἐξολέσειν,"},{"number":300,"text":"ὅτι βασιλεὺς ὑπʼ αὐτοῦ γενόμενος οὐκ ἠμείψατο τὴν εὐεργεσίαν τῷ δικαίως προστῆναι τοῦ πλήθους καὶ εὐσεβῶς, ἅπερ αὐτοῖς πρῶτον τοῖς οὖσι τοιούτοις ἀγαθὰ ἔπειτα τῷ θεῷ φίλα, τὸν δὲ κάκιστον Ἱεροβόαμον ἐμιμήσατο καὶ τῆς ψυχῆς ἀπολομένης τῆς ἐκείνου ζῶσαν αὐτοῦ τὴν πονηρίαν ἐνεδείξατο· πεῖραν οὖν ἕξειν εἰκότως τῆς ὁμοίας συμφορᾶς αὐτὸν ἔλεγεν ὅμοιον αὐτῷ γενόμενον."},{"number":301,"text":"Βασάνης δὲ προακηκοὼς τὰ μέλλοντα αὐτῷ συμβήσεσθαι κακὰ μεθʼ ὅλης τῆς γενεᾶς ἐπὶ τοῖς τετολμημένοις οὐ πρὸς τὸ λοιπὸν ἡσύχασεν, ἵνα μὴ μᾶλλον πονηρὸς δόξας ἀποθάνῃ καὶ περὶ τῶν παρῳχημένων ἔκτοτε γοῦν μετανοήσας συγγνώμης τύχῃ,"},{"number":302,"text":"ἀλλʼ ὥσπερ οἱ προκειμένων αὐτοῖς ἄθλων ἐπὰν περί τι σπουδάσωσιν οὐ διαλείπουσι περὶ τοῦτο ἐνεργοῦντες, οὕτω καὶ Βασάνης προειρηκότος αὐτῷ τοῦ προφήτου τὰ μέλλοντα ὡς ἐπʼ ἀγαθοῖς τοῖς μεγίστοις κακοῖς ὀλέθρῳ γένους καὶ οἰκίας ἀπωλείᾳ χείρων ἐγένετο, καὶ καθʼ ἑκάστην ἡμέραν ὥσπερ ἀθλητὴς κακίας τοῖς περὶ ταύτην πόνοις προσετίθει."},{"number":303,"text":"καὶ τελευταῖον τὴν στρατιὰν παραλαβὼν πάλιν ἐπῆλθε πόλει τινὶ τῶν οὐκ ἀφανῶν Ἀρμαθῶνι τοὔνομα σταδίους ἀπεχούσῃ Ἱεροσολύμων τεσσαράκοντα, καὶ καταλαβόμενος αὐτὴν ὠχύρου προδιεγνωκὼς καταλιπεῖν ἐν αὐτῇ δύναμιν, ἵνʼ ἐκεῖθεν ὡρμημένοι τὴν Ἀσάνου βασιλείαν κακώσωσι."},{"number":304,"text":"Φοβηθεὶς δὲ Ἄσανος τὴν ἐπιχείρησιν τοῦ πολεμίου καὶ λογισάμενος, ὡς πολλὰ διαθήσει κακὰ τὴν ὑπʼ αὐτῷ βασιλευομένην ἅπασαν ὁ καταλειφθεὶς ἐν Ἀρμαθῶνι στρατός, ἔπεμψε πρὸς τὸν Δαμασκηνῶν βασιλέα πρέσβεις καὶ χρυσὸν καὶ ἄργυρον παρακαλῶν συμμαχίαν καὶ ὑπομιμνήσκων, ὅτι καὶ πατρῴα φιλία πρὸς ἀλλήλους ἐστὶν αὐτοῖς."},{"number":305,"text":"ὁ δὲ τῶν χρημάτων τὸ πλῆθος ἀσμένως ἐδέξατο καὶ συμμαχίαν ἐποιήσατο πρὸς αὐτὸν διαλύσας τὴν πρὸς τὸν Βασάνην φιλίαν, καὶ πέμψας εἰς τὰς ὑπʼ αὐτοῦ βασιλευομένας πόλεις τοὺς ἡγεμόνας τῆς ἰδίας δυνάμεως ἐκέλευσε κακοῦν αὐτάς. οἱ δὲ τὰς μὲν ἐνεπίμπρασαν τὰς δὲ διήρπασαν πορευθέντες, τήν τε Ἰωάνου λεγομένην καὶ Δάνα καὶ Ἀβελάνην καὶ ἄλλας πολλάς."},{"number":306,"text":"ταῦτʼ ἀκούσας ὁ τῶν Ἰσραηλιτῶν βασιλεὺς τοῦ μὲν οἰκοδομεῖν καὶ ὀχυροῦν τὸν Ἀραμαθῶνα ἐπαύσατο καὶ μετὰ σπουδῆς ὡς βοηθήσων τοῖς οἰκείοις κακουμένοις ἀνέστρεψεν, ὁ δʼ Ἄσανος ἐκ τῆς παρεσκευασμένης ὑπʼ αὐτοῦ πρὸς οἰκοδομίαν ὕλης πόλεις ἀνήγειρεν ἐν αὐτῷ τῷ τόπῳ δύο καρτεράς, ἡ μὲν Γαβαὰ ἐκαλεῖτο, ἡ δὲ Μασταφάς."},{"number":307,"text":"καὶ μετὰ ταῦτα καιρὸν οὐκ ἔσχεν ὁ Βασάνης τῆς ἐπὶ τὸν Ἄσανον στρατείας· ἐφθάσθη γὰρ ὑπὸ τοῦ χρεὼν καὶ θάπτεται μὲν ἐν Θαρσῇ πόλει, παραλαμβάνει δʼ αὐτοῦ τὴν ἀρχὴν παῖς Ἤλανος. οὗτος ἄρξας ἐπʼ ἔτη δύο τελευτᾷ φονεύσαντος αὐτὸν ἐξ ἐπιβουλῆς Ζαμβρίου τοῦ ἱππάρχου τῆς ἡμισείας τάξεως·"},{"number":308,"text":"κατευωχηθέντα γὰρ αὐτὸν παρὰ τῷ οἰκονόμῳ αὐτοῦ Ὠσᾶ τοὔνομα πείσας ἐπιδραμεῖν τῶν ὑφʼ αὑτὸν ἱππέων τινὰς ἀπέκτεινε διʼ αὐτῶν μεμονωμένον τῶν περὶ αὐτὸν ὁπλιτῶν καὶ ἡγεμόνων· οὗτοι γὰρ ἅπαντες περὶ τὴν πολιορκίαν τῆς Γαβαθώνης ἐγίνοντο τῆς Παλαιστίνων."},{"number":309,"text":"Φονεύσας δὲ τὸν Ἤλανον ὁ ἵππαρχος Ζαμβρίας αὐτὸς βασιλεύει καὶ πᾶσαν τὴν Βασάνου γενεὰν κατὰ τὴν Ἰηοῦς προφητείαν διαφθείρει· τῷ γὰρ αὐτῷ τρόπῳ συνέβη τὸν οἶκον αὐτοῦ πρόρριζον ἀπολέσθαι διὰ τὴν ἀσέβειαν, ὡς καὶ τὸν Ἱεροβοάμου διαφθαρέντα γεγράφαμεν."},{"number":310,"text":"ἡ δὲ πολιορκοῦσα τὴν Γαβαθώνην στρατιὰ πυθομένη τὰ περὶ τὸν βασιλέα καὶ ὅτι Ζαμβρίας ἀποκτείνας αὐτὸν ἔχει τὴν βασιλείαν καὶ αὐτὴ τὸν ἡγούμενον αὐτῆς Ἀμαρῖνον ἀπέδειξε βασιλέα, ὃς ἀπὸ τῆς Γαβαθώνης ἀναστήσας τὸν στρατὸν εἰς Θαρσὴν παραγίνεται τὸ βασίλειον καὶ προσβαλὼν τῇ πόλει κατὰ κράτος αἱρεῖ."},{"number":311,"text":"Ζαμβρίας δὲ τὴν πόλιν ἰδὼν ἠρημωμένην συνέφυγεν εἰς τὸ μυχαίτατον τῶν βασιλείων καὶ ὑποπρήσας αὐτὸ συγκατέκαυσεν ἑαυτὸν βασιλεύσας ἡμέρας ἑπτά. διέστη δʼ εὐθὺς ὁ τῶν Ἰσραηλιτῶν λαὸς καὶ οἱ μὲν αὐτῶν Θαμαναῖον βασιλεύειν ἤθελον, οἱ δὲ τὸν Ἀμαρῖνον. νικήσαντες δʼ οἱ τοῦτον ἄρχειν ἀξιοῦντες ἀποκτείνουσι τὸν Θαμαναῖον, καὶ παντὸς βασιλεύει ὁ Ἀμαρῖνος τοῦ ὄχλου."},{"number":312,"text":"τριακοστῷ δὲ ἔτει τῆς Ἀσάνου βασιλείας ἦρξεν ὁ Ἀμαρῖνος ἔτη δώδεκα· τούτων τὰ μὲν ἓξ ἐν Θάρσῳ πόλει, τὰ δὲ λοιπὰ ἐν Σωμαρεῶνι λεγομένῃ πόλει ὑπὸ δὲ Ἑλλήνων Σαμαρείᾳ καλουμένῃ. προσηγόρευσε δʼ αὐτὴν αὐτὸς Σωμαραῖος ἀπὸ τοῦ τὸ ὄρος ἀποδομένου αὐτῷ ἐφʼ ᾧ κατεσκεύασε τὴν πόλιν Σωμάρου."},{"number":313,"text":"διέφερε δʼ οὐδὲν τῶν πρὸ αὐτοῦ βασιλευσάντων ἢ τῷ χείρων αὐτῶν εἶναι· ἅπαντες γὰρ ἐζήτουν πῶς ἀποστήσουσιν ἀπὸ τοῦ θεοῦ τὸν λαὸν τοῖς καθʼ ἡμέραν ἀσεβήμασι καὶ διὰ τοῦτο διʼ ἀλλήλων αὐτοὺς ὁ θεὸς ἐποίησεν ἐλθεῖν καὶ μηδένα τοῦ γένους ὑπολιπεῖν. ἐτελεύτησε δὲ καὶ οὗτος ἐν Σαμαρείᾳ, διαδέχεται δʼ αὐτὸν ὁ παῖς Ἄχαβος."},{"number":314,"text":"Μαθεῖν δʼ ἔστιν ἐκ τούτων, ὅσην τὸ θεῖον ἐπιστροφὴν ἔχει τῶν ἀνθρωπίνων πραγμάτων, καὶ πῶς μὲν ἀγαπᾷ τοὺς ἀγαθούς, μισεῖ δὲ τοὺς πονηροὺς καὶ προρρίζους ἀπόλλυσιν· οἱ μὲν γὰρ τῶν Ἰσραηλιτῶν βασιλεῖς ἄλλος ἐπʼ ἄλλῳ διὰ τὴν παρανομίαν καὶ τὰς ἀδικίας ἐν ὀλίγῳ χρόνῳ πολλοὶ κακῶς διαφθαρέντες ἐγνώσθησαν καὶ τὸ γένος αὐτῶν, ὁ δὲ τῶν Ἱεροσολύμων καὶ τῶν δύο φυλῶν βασιλεὺς Ἄσανος διʼ εὐσέβειαν καὶ δικαιοσύνην εἰς μακρὸν καὶ εὔδαιμον ὑπὸ τοῦ θεοῦ προήχθη γῆρας καὶ τεσσαράκοντα καὶ ἓν ἄρξας ἔτος εὐμοίρως ἀπέθανε."},{"number":315,"text":"τελευτήσαντος δʼ αὐτοῦ διεδέξατο τὴν ἡγεμονίαν ὁ υἱὸς Ἰωσαφάτης ἐκ γυναικὸς Ἀβιδᾶς τοὔνομα γεγενημένος. τοῦτον μιμητὴν Δαυίδου τοῦ προπάππου κατά τε ἀνδρείαν καὶ εὐσέβειαν ἅπαντες ἐν τοῖς ἔργοις ὑπέλαβον. ἀλλὰ περὶ μὲν τούτου τοῦ βασιλέως οὐ κατεπείγει νῦν λέγειν."}],"13":[{"number":316,"text":"Ὁ δὲ Ἄχαβος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς κατῴκει μὲν ἐν Σαμαρείᾳ, τὴν δʼ ἀρχὴν κατέσχεν ἕως ἐτῶν εἴκοσι καὶ δύο μηδὲν καινίσας τῶν πρὸ αὐτοῦ βασιλέων, εἰ μὴ ὅσα γε πρὸς τὸ χεῖρον καθʼ ὑπερβολὴν πονηρίας ἐπενόησεν, ἅπαντα δʼ αὐτῶν τὰ κακουργήματα καὶ τὴν πρὸς τὸ θεῖον ὕβριν ἐκμιμησάμενος καὶ μάλιστα τὴν Ἱεροβοάμου ζηλώσας παρανομίαν·"},{"number":317,"text":"καὶ γὰρ οὗτος δαμάλεις τὰς ὑπʼ ἐκείνου κατασκευασθείσας προσεκύνησε καὶ τούτοις ἄλλα παράδοξα προσεμηχανήσατο. ἔγημε δὲ γυναῖκα θυγατέρα μὲν Εἰθωβάλου τοῦ Τυρίων καὶ Σιδωνίων βασιλέως Ἰεζαβέλην δὲ ὄνομα, ἀφʼ ἧς τοὺς ἰδίους αὐτῆς θεοὺς προσκυνεῖν ἔμαθεν."},{"number":318,"text":"ἦν δὲ τὸ γύναιον δραστήριόν τε καὶ τολμηρόν, εἰς τοσαύτην δὲ ἀσέλγειαν καὶ μανίαν προύπεσεν, ὥστε καὶ ναὸν τῷ Τυρίων θεῷ ὃν Βελίαν προσαγορεύουσιν ᾠκοδόμησε καὶ ἄλσος παντοίων δένδρων κατεφύτευσε· κατέστησε δὲ καὶ ἱερεῖς καὶ ψευδοπροφήτας τούτῳ τῷ θεῷ· καὶ αὐτὸς δʼ ὁ βασιλεὺς πολλοὺς τοιούτους περὶ αὑτὸν εἶχεν ἀνοίᾳ καὶ πονηρίᾳ πάντας ὑπερβεβληκὼς τοὺς πρὸ αὐτοῦ."},{"number":319,"text":"Προφήτης δέ τις τοῦ μεγάλου θεοῦ ἐκ πόλεως Θεσσεβώνης τῆς Γαλααδίτιδος χώρας προσελθὼν Ἀχάβῳ προλέγειν αὐτῷ τὸν θεὸν ἔφασκε μήθʼ ὕσειν αὐτὸν ἐν ἐκείνοις τοῖς ἔτεσι μήτε δρόσον καταπέμψειν εἰς τὴν χώραν, εἰ μὴ φανέντος αὐτοῦ. καὶ τούτοις ἐπομόσας ἀνεχώρησεν εἰς τὰ πρὸς νότον μέρη ποιούμενος παρὰ χειμάρρῳ τινὶ τὴν διατριβήν, ἐξ οὗ καὶ τὸ ποτὸν εἶχε· τὴν γὰρ τροφὴν αὐτῷ καθʼ ἡμέραν κόρακες προσέφερον."},{"number":320,"text":"ἀναξηρανθέντος δὲ τοῦ ποταμοῦ διʼ ἀνομβρίαν εἰς Σαριφθὰν πόλιν οὐκ ἄπωθεν τῆς Σιδῶνος καὶ Τύρου, μεταξὺ γὰρ κεῖται, παραγίνεται τοῦ θεοῦ κελεύσαντος· εὑρήσειν γὰρ ἐκεῖ γυναῖκα χήραν, ἥτις αὐτῷ παρέξει τροφάς."},{"number":321,"text":"ὢν δʼ οὐ πόρρω τῆς πύλης ὁρᾷ γυναῖκα χερνῆτιν ξυλιζομένην· τοῦ δὲ θεοῦ δηλώσαντος ταύτην εἶναι τὴν μέλλουσαν αὐτὸν διατρέφειν προσελθὼν ἠσπάσατο καὶ κομίσαι ὕδωρ παρεκάλεσεν, ὅπως πίῃ, καὶ πορευομένης μετακαλεσάμενος καὶ ἄρτον ἐνεγκεῖν ἐκέλευσε."},{"number":322,"text":"τῆς δʼ ὀμοσάσης μηδὲν ἔχειν ἢ μίαν ἀλεύρου δράκα καὶ ὀλίγον ἐλαίου, πορεύεσθαι δὲ συνειλεχυῖαν τὰ ξύλα, ἵνα φυράσασα ποιήσῃ αὑτῇ καὶ τῷ τέκνῳ ἄρτον, μεθʼ ὃν ἀπολεῖσθαι λιμῷ δαπανηθέντα μηκέτι μηδενὸς ὄντος ἔλεγεν, ἀλλὰ θαρσοῦσα, εἶπεν, ἄπιθι καὶ τὰ κρείττω προσδοκῶσα, καὶ ποιήσασα πρῶτον ἐμοὶ βραχὺ κόμισον· προλέγω γάρ σοι μηδέποτʼ ἐπιλείψειν ἀλεύρων ἐκεῖνο τὸ ἄγγος μηδʼ ἐλαίου τὸ κεράμιον, μέχρις οὗ ἂν ὕσῃ ὁ θεός."},{"number":323,"text":"ταῦτʼ εἰπόντος τοῦ προφήτου παραγενομένη πρὸς αὑτὴν ἐποίησε τὰ εἰρημένα καὶ αὐτή τε ἔσχε καὶ τῷ τέκνῳ χορηγεῖ τὴν διατροφὴν καὶ τῷ προφήτῃ, ἐπέλιπε δʼ οὐδὲν αὐτοὺς τούτων, ἄχρις οὗ καὶ ὁ αὐχμὸς ἐπαύσατο."},{"number":324,"text":"μέμνηται δὲ τῆς ἀνομβρίας ταύτης καὶ Μένανδρος ἐν ταῖς Ἰθωβάλου τοῦ Τυρίων βασιλέως πράξεσι λέγων οὕτως· ἀβροχία τʼ ἐπʼ αὐτοῦ ἐγένετο ἀπὸ τοῦ Ὑπερβερεταίου μηνὸς ἕως τοῦ ἐχομένου ἔτους Ὑπερβερεταίου, ἱκετείαν δʼ αὐτοῦ ποιησαμένου κεραυνοὺς ἱκανοὺς βεβληκέναι. οὗτος πόλιν Βότρυν ἔκτισε τὴν ἐπὶ Φοινίκῃ καὶ Αὖζαν τὴν ἐν Λιβύῃ. καὶ ταῦτα μὲν δηλῶν τὴν ἐπʼ Ἀχάβου γενομένην ἀνομβρίαν, κατὰ γὰρ τοῦτον καὶ Ἰθώβαλος ἐβασίλευε Τυρίων, ὁ Μένανδρος ἀναγέγραφεν."},{"number":325,"text":"Ἡ δὲ γυνὴ περὶ ἧς πρὸ τούτων εἴπομεν, ἡ τὸν προφήτην διατρέφουσα, τοῦ παιδὸς αὐτῇ καταπεσόντος εἰς νόσον, ὡς καὶ τὴν ψυχὴν ἀφεῖναι καὶ δόξαι νεκρόν, ἀνακλαιομένη καὶ ταῖς τε χερσὶν αὑτὴν αἰκιζομένη καὶ φωνὰς οἵας ὑπηγόρευε τὸ πάθος ἀφιεῖσα κατῃτιᾶτο τῆς παρʼ αὐτῇ παρουσίας τὸν προφήτην ὡς ἐλέγξαντα τὰς ἁμαρτίας αὐτῆς καὶ διὰ τοῦτο τοῦ παιδὸς τετελευτηκότος."},{"number":326,"text":"ὁ δὲ παρεκελεύετο θαρρεῖν καὶ παραδοῦναι τὸν υἱὸν αὐτῷ· ζῶντα γὰρ αὐτὸν ἀποδώσειν. παραδούσης οὖν βαστάσας εἰς τὸ δωμάτιον, ἐν ᾧ διέτριβεν αὐτός, καὶ καταθεὶς ἐπὶ τῆς κλίνης ἀνεβόησε πρὸς τὸν θεὸν οὐ καλῶς ἀμείψασθαι τὴν ὑποδεξαμένην καὶ θρέψασαν τὸν υἱὸν αὐτῆς ἀφαιρησόμενον, ἐδεῖτό τε τὴν ψυχὴν εἰσπέμψαι πάλιν τῷ παιδὶ καὶ παρασχεῖν αὐτῷ τὸν βίον."},{"number":327,"text":"τοῦ δὲ θεοῦ κατοικτείραντος μὲν τὴν μητέρα, βουληθέντος δὲ καὶ τῷ προφήτῃ χαρίσασθαι τὸ μὴ δόξαι πρὸς αὐτὴν ἐπὶ κακῷ παρεῖναι, παρὰ πᾶσαν τὴν προσδοκίαν ἀνεβίωσεν. ἡ δʼ εὐχαρίστει τῷ προφήτῃ καὶ τότε σαφῶς ἔλεγε μεμαθηκέναι, ὅτι τὸ θεῖον αὐτῷ διαλέγεται."},{"number":328,"text":"Χρόνου δʼ ὀλίγου διελθόντος παραγίνεται πρὸς Ἄχαβον τὸν βασιλέα κατὰ βούλησιν τοῦ θεοῦ δηλώσων αὐτῷ τὸν γενησόμενον ὑετόν. λιμὸς δὲ τότε κατεῖχε τὴν χώραν ἅπασαν καὶ πολλὴ τῶν ἀναγκαίων ἀπορία, ὡς μὴ μόνον ἀνθρώπους αὐτῶν σπανίζειν, ἀλλὰ καὶ τὴν γῆν μηδʼ ὅσα τοῖς ἵπποις καὶ τοῖς ἄλλοις κτήνεσι πρὸς νομήν ἐστι χρήσιμα διὰ τὴν ἀνομβρίαν ἀναδιδόναι."},{"number":329,"text":"τὸν οὖν ἐπιμελόμενον αὐτοῦ τῶν κτημάτων ὁ βασιλεὺς καλέσας Ὠβεδίαν ἀπιέναι βούλεσθαι πρὸς αὐτὸν εἶπεν ἐπὶ τὰς πηγὰς τῶν ὑδάτων καὶ τοὺς χειμάρρους, ἵνʼ εἴ που παρʼ αὐτοῖς εὑρεθείη πόα ταύτην εἰς τροφὴν ἀμησάμενοι τοῖς κτήνεσιν ἔχωσι. καὶ περιπέμψαντα κατὰ πᾶσαν τὴν οἰκουμένην τοὺς ζητήσοντας τὸν προφήτην Ἠλίαν οὐχ εὑρηκέναι· συνέπεσθαι δʼ ἐκέλευσε κἀκεῖνον αὐτῷ."},{"number":330,"text":"δόξαν οὖν ἐξορμᾶν αὐτοῖς μερισάμενοι τὰς ὁδοὺς ὅ τε Ὠβεδίας καὶ ὁ βασιλεὺς ἀπῄεσαν ἕτερος ἑτέραν τῶν ὁδῶν. συνεβεβήκει δὲ καθʼ ὃν Ἰεζαβέλη ἡ βασίλισσα καιρὸν τοὺς προφήτας ἀπέκτεινε τοῦτον ἑκατὸν ἐν τοῖς ὑπὸ Γάρις σπηλαίοις κρύψαι προφήτας καὶ τρέφειν αὐτοὺς ἄρτον χορηγοῦντα μόνον καὶ ὕδωρ."},{"number":331,"text":"μονωθέντι δʼ ἀπὸ τοῦ βασιλέως Ὠβεδίᾳ συνήντησεν ὁ προφήτης Ἠλίας· καὶ πυθόμενος παρʼ αὐτοῦ τίς εἴη καὶ μαθὼν προσεκύνησεν αὐτόν· ὁ δὲ πρὸς τὸν βασιλέα βαδίζειν ἐκέλευσε καὶ λέγειν, ὅτι παρείη πρὸς αὐτόν."},{"number":332,"text":"ὁ δὲ τί κακὸν ὑπʼ αὐτοῦ πεπονθότα πρὸς τὸν ἀποκτεῖναι ζητοῦντα καὶ πᾶσαν ἐρευνήσαντα γῆν πέμπειν αὐτὸν ἔλεγεν· ἢ τοῦτʼ ἀγνοεῖν αὐτόν, ὅτι μηδένα τόπον κατέλιπεν, εἰς ὃν οὐκ ἀπέστειλε τοὺς ἀνάξοντας εἰ λάβοιεν ἐπὶ θανάτῳ;"},{"number":333,"text":"καὶ γὰρ εὐλαβεῖσθαι πρὸς αὐτὸν ἔφασκε, μὴ τοῦ θεοῦ φανέντος αὐτῷ πάλιν εἰς ἄλλον ἀπέλθῃ τόπον, εἶτα διαμαρτὼν αὐτοῦ πέμψαντος τοῦ βασιλέως μὴ δυνάμενος εὑρεῖν ὅπου ποτʼ εἴη γῆς ἀποθάνῃ."},{"number":334,"text":"προνοεῖν οὖν αὐτοῦ τῆς σωτηρίας παρακαλεῖ τὴν περὶ τοὺς ὁμοτέχνους αὐτοῦ σπουδὴν λέγων, ὅτι σώσειεν ἑκατὸν προφήτας Ἱεζαβέλης πάντας τοὺς ἄλλους ἀνῃρηκυίας καὶ ἔχοι κεκρυμμένους αὐτοὺς καὶ τρεφομένους ὑπʼ αὐτοῦ. ὁ δὲ μηδὲν δεδιότα βαδίζειν ἐκέλευε πρὸς τὸν βασιλέα δοὺς αὐτῷ πίστεις ἐνόρκους, ὅτι πάντως κατʼ ἐκείνην Ἀχάβῳ φανήσεται τὴν ἡμέραν."},{"number":335,"text":"Μηνύσαντος δὲ τῷ βασιλεῖ Ὠβεδίου τὸν Ἠλίαν ὑπήντησεν ὁ Ἄχαβος καὶ ἤρετο μετʼ ὀργῆς, εἰ αὐτὸς εἴη ὁ τὸν Ἑβραίων λαὸν κακώσας καὶ τῆς ἀκαρπίας αἴτιος γεγενημένος. ὁ δʼ οὐδὲν ὑποθωπεύσας αὐτὸν εἶπεν ἅπαντα τὰ δεινὰ πεποιηκέναι καὶ τὸ γένος αὐτοῦ ξενικοὺς ἐπεισενηνοχότας τῇ χώρᾳ θεοὺς καὶ τούτους σέβοντας, τὸν δʼ ἴδιον αὐτῶν, ὃς μόνος ἐστὶ θεός, ἀπολελοιπότας καὶ μηδεμίαν ἔτι πρόνοιαν αὐτοῦ ποιουμένους."},{"number":336,"text":"νῦν μέντοι γε ἀνελθόντα ἐκέλευε πάντα τὸν λαὸν εἰς τὸ Καρμήλιον ὄρος ἀθροῖσαι πρὸς αὐτὸν καὶ τοὺς προφήτας αὐτοῦ καὶ τῆς γυναικός, εἰπὼν ὅσοι τὸν ἀριθμὸν εἴησαν, καὶ τοὺς τῶν ἀλσῶν προφήτας ὡς τετρακοσίους τὸ πλῆθος ὄντας."},{"number":337,"text":"ὡς δὲ συνέδραμον πάντες εἰς τὸ προειρημένον ὄρος Ἀχάβου διαπέμψαντος, σταθεὶς αὐτῶν ὁ προφήτης Ἠλίας μεταξύ, μέχρι πότε διῃρημένους αὐτοὺς τῇ διανοίᾳ καὶ ταῖς δόξαις οὕτως βιώσειν ἔφασκε· νομίσαντας μὲν γὰρ τὸν ἐγχώριον θεὸν ἀληθῆ καὶ μόνον ἕπεσθαι τούτῳ καὶ ταῖς ἐντολαῖς αὐτοῦ παρῄνει, μηδὲν δὲ τοῦτον ἡγουμένους ἀλλὰ περὶ τῶν ξενικῶν ὑπειληφότας ὡς ἐκείνους δεῖ θρησκεύειν αὐτοῖς συνεβούλευε κατακολουθεῖν."},{"number":338,"text":"τοῦ δὲ πλήθους μηδὲν πρὸς ταῦτʼ ἀποκριναμένου ἠξίωσεν Ἠλίας πρὸς διάπειραν τῆς τε τῶν ξενικῶν θεῶν ἰσχύος καὶ τῆς τοῦ ἰδίου, μόνος ὢν αὐτοῦ προφήτης ἐκείνων δὲ τετρακοσίους ἐχόντων, λαβεῖν αὐτός τε βοῦν καὶ ταύτην θύσας ἐπιθεῖναι ξύλοις πυρὸς οὐχ ὑπαφθέντος, κἀκείνους ταὐτὸ ποιήσαντας ἐπικαλέσασθαι τοὺς ἰδίους θεοὺς ἀνακαῦσαι τὰ ξύλα· γενομένου γὰρ τούτου μαθήσεσθαι αὐτοὺς τὴν ἀληθῆ φύσιν τοῦ θεοῦ."},{"number":339,"text":"ἀρεσάσης δὲ τῆς γνώμης ἐκέλευσεν Ἠλίας τοὺς προφήτας ἐκλεξαμένους βοῦν πρώτους θῦσαι καὶ τοὺς αὑτῶν ἐπικαλέσασθαι θεούς. ἐπεὶ δʼ οὐδὲν ἀπήντα παρὰ τῆς εὐχῆς καὶ τῆς ἐπικλήσεως θύσασι τοῖς προφήταις, σκώπτων ὁ Ἠλίας μεγάλῃ βοῇ καλεῖν αὐτοὺς ἐκέλευε τοὺς θεούς· ἢ γὰρ ἀποδημεῖν αὐτοὺς ἢ καθεύδειν."},{"number":340,"text":"τῶν δʼ ἀπʼ ὄρθρου τοῦτο ποιούντων μέχρι μέσης ἡμέρας καὶ τεμνόντων αὑτοὺς μαχαίραις καὶ σιρομάσταις κατὰ τὸ πάτριον ἔθος, μέλλων αὐτὸς ἐπιτελεῖν ἐκέλευσε τοὺς μὲν ἀναχωρῆσαι, τοὺς δʼ ἐγγὺς προσελθόντας τηρεῖν αὐτόν, μὴ πῦρ λάθρα τοῖς ξύλοις ἐμβάλῃ."},{"number":341,"text":"τοῦ δὲ ὄχλου προσελθόντος λαβὼν δώδεκα λίθους κατὰ φυλὴν τοῦ λαοῦ τῶν Ἑβραίων ἀνέστησεν ἐξ αὐτῶν θυσιαστήριον καὶ περὶ αὐτὸ δεξαμενὴν ὤρυξε βαθυτάτην, καὶ συνθεὶς τὰς σχίζας ἐπὶ τοῦ βωμοῦ καὶ κατʼ αὐτῶν ἐπιθεὶς τὰ ἱερεῖα τέσσαρας ἀπὸ τῆς κρήνης ἐκέλευσεν ὑδρίας ὕδατος κατασκεδάσαι τοῦ θυσιαστηρίου, ὡς ὑπερβαλεῖν αὐτὸ καὶ τὴν δεξαμενὴν ἅπασαν γεμισθῆναι ὕδατος πηγῆς ἀναδοθείσης."},{"number":342,"text":"ταῦτα δὲ ποιήσας ἤρξατο εὔχεσθαι τῷ θεῷ καὶ καλεῖν αὐτὸν καὶ ποιεῖν τῷ πεπλανημένῳ πολὺν ἤδη χρόνον λαῷ φανερὰν τὴν αὑτοῦ δύναμιν. καὶ ταῦτα λέγοντος ἄφνω πῦρ ἐξ οὐρανοῦ τοῦ πλήθους ὁρῶντος ἐπὶ τὸν βωμὸν ἔπεσε καὶ τὴν θυσίαν ἐδαπάνησεν, ὡς ἀνακαῆναι καὶ τὸ ὕδωρ καὶ ψαφαρὸν γενέσθαι τὸν τόπον."},{"number":343,"text":"Οἱ δʼ Ἰσραηλῖται τοῦτʼ ἰδόντες ἔπεσον ἐπὶ τῆς γῆς καὶ προσεκύνουν ἕνα θεὸν καὶ μέγιστον καὶ ἀληθῆ μόνον ἀποκαλοῦντες, τοὺς δʼ ἄλλους ὀνόματι ὑπὸ φαύλης καὶ ἀνοήτου δόξης πεποιημένους· συλλαβόντες δʼ αὐτῶν καὶ τοὺς προφήτας ἀπέκτειναν Ἠλία παραινέσαντος. ἔφη δὲ καὶ τῷ βασιλεῖ πορεύεσθαι πρὸς ἄριστον μηδὲν ἔτι φροντίσαντα· μετʼ ὀλίγον γὰρ ὄψεσθαι τὸν θεὸν ὕοντα."},{"number":344,"text":"καὶ ὁ μὲν Ἄχαβος ἀπηλλάγη, Ἠλίας δʼ ἐπὶ τὸ ἀκρωτήριον τοῦ Καρμηλίου ἀναβὰς ὄρους καὶ καθίσας ἐπὶ τῆς γῆς προσηρείσατο τοῖς γόνασι τὴν κεφαλήν, τὸν δὲ θεράποντα ἐκέλευσεν ἀνελθόντα ἐπί τινα σκοπὴν εἰς τὴν θάλασσαν ἀποβλέπειν, κἂν ἴδῃ νεφέλην ἐγειρομένην ποθέν, φράζειν αὐτῷ· μέχρι γὰρ τότε καθαρῷ συνέβαινε τῷ ἀέρι εἶναι."},{"number":345,"text":"τοῦ δὲ ἀναβάντος καὶ μηδὲν πολλάκις ὁρᾶν φήσαντος, ἕβδομον ἤδη βαδίσας ἑωρακέναι μελαινόμενον εἶπέ τι τοῦ ἀέρος οὐ πλέον ἴχνους ἀνθρωπίνου. ὁ δὲ Ἠλίας ταῦτʼ ἀκούσας πέμπει πρὸς τὸν Ἄχαβον κελεύων αὐτὸν εἰς τὴν πόλιν ἀπέρχεσθαι πρὶν ἢ καταρραγῆναι τὸν ὄμβρον."},{"number":346,"text":"καὶ ὁ μὲν εἰς Ἱερέζηλα πόλιν παραγίνεται· μετʼ οὐ πολὺ δὲ τοῦ ἀέρος ἀχλύσαντος καὶ νέφεσι καλυφθέντος πνεῦμά τε λάβρον ἐπιγίνεται καὶ πολὺς ὄμβρος. ὁ δὲ προφήτης ἔνθεος γενόμενος τῷ τοῦ βασιλέως ἅρματι μέχρι τῆς Ἱερέζηλας πόλεως συνέδραμε."},{"number":347,"text":"Μαθοῦσα δὲ ἡ τοῦ Ἀχάβου γυνὴ Ἰεζάβηλα τά τε σημεῖα τὰ ὑπὸ Ἠλία γενόμενα καὶ ὅτι τοὺς προφήτας αὐτῶν ἀπέκτεινεν, ὀργισθεῖσα πέμπει πρὸς αὐτὸν ἀγγέλους ἀπειλοῦσα διʼ αὐτῶν ἀποκτείνειν αὐτόν, ὡς κἀκεῖνος τοὺς προφήτας αὐτῆς ἀπολέσειε."},{"number":348,"text":"φοβηθεὶς δʼ ὁ Ἠλίας φεύγει εἰς πόλιν Βερσουβεὲ λεγομένην, ἐπʼ ἐσχάτης δʼ ἔστιν αὕτη τῆς χώρας τῶν τῆς Ἰούδα φυλῆς ἐχόντων κατὰ τὴν Ἰδουμαίων γῆν, καταλιπὼν δʼ ἐκεῖ τὸν θεράποντα εἰς τὴν ἔρημον ἀνεχώρησεν εὐξάμενος ἀποθανεῖν· οὐ γὰρ δὴ κρείττων εἶναι τῶν πατέρων, ἵνα ἐκείνων ἀπολωλότων αὐτὸς ζῆν γλίχηται·"},{"number":349,"text":"κατακοιμηθεὶς δὲ πρός τινι δένδρῳ διεγείραντος αὐτόν τινος ἀναστὰς εὑρίσκει παρακειμένην αὑτῷ τροφὴν καὶ ὕδωρ· φαγὼν δὲ καὶ συλλεξάμενος ἐκ τῆς τροφῆς ἐκείνης τὴν δύναμιν εἰς τὸ Σιναῖον καλούμενον ὄρος παραγίνεται, οὗ Μωυσῆς τοὺς νόμους παρὰ τοῦ θεοῦ λέγεται λαβεῖν."},{"number":350,"text":"εὑρὼν δʼ ἐν αὐτῷ σπήλαιόν τι κοῖλον εἴσεισι καὶ διετέλει ποιούμενος ἐν αὐτῷ τὴν μονήν. ἐρομένης δέ τινος αὐτὸν φωνῆς ἐξ ἀδήλου, τί παρείη καταλελοιπὼς τὴν πόλιν ἐκεῖσε, διὰ τὸ κτεῖναι μὲν τοὺς προφήτας τῶν ξενικῶν θεῶν, πεῖσαι δὲ τὸν λαὸν ὅτι μόνος εἴη θεὸς ὁ ὤν, ὃν ἀπʼ ἀρχῆς ἐθρήσκευσαν, ἔφησε· ζητεῖσθαι γὰρ ἐπὶ τούτῳ πρὸς τιμωρίαν ὑπὸ τῆς γυναικὸς τοῦ βασιλέως."},{"number":351,"text":"πάλιν δὲ ἀκούσας προελθεῖν εἰς τὸ ὕπαιθρον τῇ ἐπιούσῃ, γνώσεσθαι γὰρ οὕτως τί δεῖ ποιεῖν, προῆλθεν ἐκ τοῦ σπηλαίου μεθʼ ἡμέραν καὶ σεισμοῦ τε ἐπακούει καὶ λαμπρὰν πυρὸς αὐγὴν ὁρᾷ."},{"number":352,"text":"καὶ γενομένης ἡσυχίας φωνὴ θεία μὴ ταράττεσθαι τοῖς γινομένοις αὐτὸν παρακελεύεται, κρατήσειν γὰρ οὐδένα τῶν ἐχθρῶν αὐτοῦ, προσέταξέ τε ὑποστρέψαντα εἰς τὴν οἰκείαν ἀποδεῖξαι τοῦ πλήθους βασιλέα Ἰηοῦν τὸν Νεμεσαίου παῖδα, ἐκ Δαμασκοῦ δὲ τῶν Σύρων Ἀζάηλον· ἀντʼ αὐτοῦ δὲ προφήτην Ἐλισσαῖον ὑπʼ αὐτοῦ γενήσεσθαι ἐκ πόλεως Ἀβέλας·"},{"number":353,"text":"διαφθερεῖ δὲ τοῦ ἀσεβοῦς ὄχλου τοὺς μὲν Ἀζάηλος τοὺς δὲ Ἰηοῦς. ὁ δʼ Ἠλίας ὑποστρέφει ταῦτʼ ἀκούσας εἰς τὴν Ἑβραίων χώραν καὶ τὸν Σαφάτου παῖδα Ἐλισσαῖον καταλαβὼν ἀροῦντα καὶ μετʼ αὐτοῦ τινας ἄλλους ἐλαύνοντας ζεύγη δώδεκα προσελθὼν ἐπέρριψεν αὐτῷ τὸ ἴδιον ἱμάτιον."},{"number":354,"text":"ὁ δʼ Ἐλισσαῖος εὐθέως προφητεύειν ἤρξατο καὶ καταλιπὼν τοὺς βόας ἠκολούθησεν Ἠλίᾳ. δεηθεὶς δὲ συγχωρῆσαι αὐτῷ τοὺς γονεῖς ἀσπάσασθαι κελεύοντος τοῦτο ποιεῖν ἀποταξάμενος αὐτοῖς εἵπετο καὶ ἦν Ἠλίου τὸν ἅπαντα χρόνον τοῦ ζῆν καὶ μαθητὴς καὶ διάκονος. καὶ τὰ μὲν περὶ τοῦ προφήτου τούτου τοιαῦτα ἦν."},{"number":355,"text":"Ναβώθης δέ τις ἐξ Ἱεζαρήλου πόλεως ἀγρογείτων ὢν τοῦ βασιλέως παρακαλοῦντος αὐτὸν ἀποδόσθαι τιμῆς ὅσης βούλεται τὸν πλησίον αὐτοῦ τῶν ἰδίων ἀγρόν, ἵνα συνάψας ἓν αὐτὸ ποιήσῃ κτῆμα, εἰ δὲ μὴ βούλοιτο χρήματα λαβεῖν ἐπιτρέποντος ἐκλέξασθαι τῶν ἀγρῶν τινα τῶν ἐκείνου, τοῦτο μὲν οὔ φησι ποιήσειν, αὐτὸς δὲ τὴν ἰδίαν καρπώσεσθαι γῆν, ἣν ἐκληρονόμησε τοῦ πατρός."},{"number":356,"text":"λυπηθεὶς δʼ ὡς ἐφʼ ὕβρει τῷ μὴ τἀλλότρια λαβεῖν ὁ βασιλεὺς οὔτε λουτρὸν προσηνέγκατο οὔτε τροφήν, τῆς δʼ Ἰεζαβέλης τῆς γυναικὸς αὐτοῦ πυνθανομένης, ὅ τι λυπεῖται καὶ μήτε λούεται μήτε ἄριστον αὑτῷ παρατίθεται μήτε δεῖπνον, διηγήσατο αὐτῇ τὴν Ναβώθου σκαιότητα καὶ ὡς χρησάμενος ἐπιεικέσι πρὸς αὐτὸν λόγοις καὶ βασιλικῆς ἐξουσίας ὑποδεεστέροις ὑβρισθείη μὴ τυχὼν ὧν ἠξίου."},{"number":357,"text":"ἡ δὲ μὴ μικροψυχεῖν ἐπὶ τούτοις παρεκάλει, παυσάμενον δὲ τῆς λύπης ἐπὶ τὴν συνήθη τρέπεσθαι τοῦ σώματος πρόνοιαν· μελήσειν γὰρ αὐτῇ περὶ τῆς Ναβώθου τιμωρίας."},{"number":358,"text":"καὶ παραχρῆμα πέμπει γράμματα πρὸς τοὺς ὑπερέχοντας τῶν Ἰσραηλιτῶν ἐκ τοῦ Ἀχάβου ὀνόματος νηστεῦσαί τε κελεύουσα καὶ ποιησαμένους ἐκκλησίαν προκαθίσαι μὲν αὐτῶν Νάβωθον, εἶναι γὰρ αὐτὸν γένους ἐπιφανοῦς, παρασκευασαμένους δὲ τρεῖς τολμηρούς τινας τοὺς καταμαρτυρήσοντας αὐτοῦ, ὡς τὸν θεόν τε εἴη βλασφημήσας καὶ τὸν βασιλέα, καταλεῦσαι καὶ τούτῳ διαχρήσασθαι τῷ τρόπῳ."},{"number":359,"text":"καὶ Νάβωθος μέν, ὡς ἔγραψεν ἡ βασίλισσα, οὕτως καταμαρτυρηθεὶς βλασφημῆσαι τὸν θεόν τε καὶ Ἄχαβον βαλλόμενος ὑπὸ τοῦ πλήθους ἀπέθανεν, ἀκούσασα δὲ ταῦτα Ἰεζάβηλα εἴσεισι πρὸς τὸν βασιλέα καὶ κληρονομεῖν τὸν Ναβώθου ἀμπελῶνα προῖκα ἐκέλευσεν."},{"number":360,"text":"ὁ δὲ Ἄχαβος ἥσθη τοῖς γεγενημένοις καὶ ἀναπηδήσας ἀπὸ τῆς κλίνης ὀψόμενος ἧκε τὸν ἀμπελῶνα τὸν Ναβώθου. ἀγανακτήσας δʼ ὁ θεὸς πέμπει τὸν προφήτην Ἠλίαν εἰς τὸ Ναβώθου χωρίον Ἀχάβῳ συμβαλοῦντα καὶ περὶ τῶν πεπραγμένων ἐρησόμενον, ὅτι κτείνας τὸν ἀληθῆ δεσπότην τοῦ χωρίου κληρονομήσειεν αὐτὸς ἀδίκως."},{"number":361,"text":"ὡς δʼ ἧκε πρὸς αὐτὸν εἰπόντος τοῦ βασιλέως, ὅ τι βούλεται χρήσασθαι αὐτῷ, αἰσχρὸν γὰρ ὄντα ἐπὶ ἁμαρτήματι ληφθῆναι ὑπʼ αὐτοῦ, κατʼ ἐκεῖνον ἔφη τὸν τόπον, ἐν ᾧ τὸν Ναβώθου νεκρὸν ὑπὸ κυνῶν δαπανηθῆναι συνέβη, τό τε αὐτοῦ καὶ τὸ τῆς γυναικὸς χυθήσεσθαι αἷμα καὶ πᾶν αὐτοῦ τὸ γένος ἀπολεῖσθαι τοιαῦτα ἀσεβῆσαι τετολμηκότος καὶ παρὰ τοὺς πατρίους νόμους πολίτην ἀδίκως ἀνῃρηκότος."},{"number":362,"text":"Ἀχάβῳ δὲ λύπη τῶν πεπραγμένων εἰσῆλθε καὶ μετάμελος, καὶ σακκίον ἐνδυσάμενος γυμνοῖς τοῖς ποσὶ διῆγεν οὐχ ἁπτόμενος τροφῆς ἀνθομολογούμενός τε τὰ ἡμαρτημένα καὶ τὸν θεὸν οὕτως ἐξευμενίζων. ὁ δὲ ζῶντος μὲν αὐτοῦ πρὸς τὸν προφήτην ὑπερβαλεῖσθαι τὴν τοῦ γένους τιμωρίαν εἶπεν ἐφʼ οἷς ἐπὶ τοῖς τετολμημένοις μετανοεῖ, τελέσειν δὲ τὴν ἀπειλὴν ἐπὶ τῷ υἱῷ Ἀχάβου. καὶ ὁ μὲν προφήτης ταῦτʼ ἐδήλωσε τῷ βασιλεῖ."}],"14":[{"number":363,"text":"Τῶν δὲ περὶ τὸν Ἄχαβον ὄντων τοιούτων κατὰ τὸν αὐτὸν καιρὸν ὁ τοῦ Ἀδάδου βασιλεύων τῶν Σύρων καὶ Δαμασκοῦ δύναμιν ἐξ ἁπάσης τῆς χώρας συναγαγὼν καὶ συμμάχους τοὺς πέραν Εὐφράτου βασιλέας ποιησάμενος τριάκοντα καὶ δύο ἐστράτευσεν ἐπὶ τὸν Ἄχαβον."},{"number":364,"text":"ὁ δʼ οὐκ ὢν ὅμοιος αὐτῷ τῇ στρατιᾷ πρὸς μάχην μὲν οὐ παρετάξατο, πάντα δʼ εἰς τὰς ὀχυρωτάτας πόλεις ἐγκλείσας τὰ ἐν τῇ χώρᾳ αὐτὸς μὲν ἔμεινεν ἐν Σαμαρείᾳ· τείχη γὰρ αὕτη λίαν ἰσχυρὰ περιεβέβλητο καὶ τὰ ἄλλα δυσάλωτος ἐδόκει· ὁ δὲ Σύρος ἀναλαβὼν τὴν δύναμιν ἧκεν ἐπὶ τὴν Σαμάρειαν καὶ περικαθίσας αὐτῇ τὸν στρατὸν ἐπολιόρκει."},{"number":365,"text":"πέμψας δὲ κήρυκα πρὸς Ἄχαβον ἠξίου πρεσβευτὰς δέξασθαι παρʼ αὐτοῦ, διʼ ὧν αὐτῷ δηλώσει τί βούλεται. τοῦ δὲ τῶν Ἰσραηλιτῶν βασιλέως πέμπειν ἐπιτρέψαντος ἐλθόντες οἱ πρέσβεις ἔλεγον κατʼ ἐντολὴν τοῦ βασιλέως τὸν Ἀχάβου πλοῦτον καὶ τὰ τέκνα αὐτοῦ καὶ τὰς γυναῖκας Ἀδάδου τυγχάνειν· ἂν δʼ ὁμολογήσῃ καὶ λαβεῖν αὐτὸν τούτων ὅσα βούλεται συγχωρήσῃ, τὴν στρατιὰν ἀπάξει καὶ παύσεται πολιορκῶν αὐτόν."},{"number":366,"text":"ὁ δʼ Ἄχαβος τοῖς πρέσβεσιν ἐκέλευσε πορευθεῖσι λέγειν τῷ βασιλεῖ αὐτῶν, ὅτι καὶ αὐτὸς καὶ οἱ ἑκείνου πάντες κτήματά εἰσιν αὐτοῦ."},{"number":367,"text":"ταῦτα δʼ ἀπαγγειλάντων πέμπει πάλιν πρὸς αὐτὸν ἀξιῶν ἀνωμολογηκότα πάντα εἶναι ἐκείνου δέξασθαι τοὺς πεμφθησομένους εἰς τὴν ἐπιοῦσαν ὑπʼ αὐτοῦ δούλους, οἷς ἐρευνήσασι τά τε βασίλεια καὶ τοὺς τῶν φίλων καὶ συγγενῶν οἴκους ἐκέλευε διδόναι πᾶν ὅ τι ἂν ἐν αὐτοῖς εὕρωσι κάλλιστον,"},{"number":368,"text":"τὰ δʼ ἀπαρέσαντα σοὶ καταλείψουσιν. Ἄχαβος δʼ ἀγασθεὶς ἐπὶ τῇ δευτέρᾳ πρεσβείᾳ τοῦ τῶν Σύρων βασιλέως συναγαγὼν εἰς ἐκκλησίαν τὸ πλῆθος ἔλεγεν, ὡς αὐτὸς μὲν ἑτοίμως εἶχεν ὑπὲρ σωτηρίας αὐτοῦ καὶ εἰρήνης καὶ γυναῖκας τὰς ἰδίας προέσθαι τῷ πολεμίῳ καὶ τὰ τέκνα καὶ πάσης παραχωρῆσαι κτήσεως· ταῦτα γὰρ ἐπιζητῶν ἐπρεσβεύσατο πρῶτον ὁ Σύρος."},{"number":369,"text":"νῦν δʼ ἠξίωκε δούλους πέμψαι τάς τε πάντων οἰκίας ἐρευνῆσαι καὶ μηδὲν ἐν αὐταῖς καταλιπεῖν τῶν καλλίστων κτημάτων πρόφασιν βουλόμενος πολέμου λαβεῖν, εἰδὼς ὅτι τῶν μὲν ἐμαυτοῦ διʼ ὑμᾶς οὐκ ἂν φεισαίμην, ἀφορμὴν δʼ ἐκ τοῦ περὶ τῶν ὑμετέρων ἀηδοῦς πραγματευόμενος εἰς τὸ πολεμεῖν· ποιήσω γε μὴν τὰ ὑμῖν δοκοῦντα."},{"number":370,"text":"τὸ δὲ πλῆθος μὴ δεῖν ἀκούειν τῶν κατʼ αὐτὸν ἔλεγεν, ἀλλὰ καταφρονεῖν καὶ πρὸς τὸ πολεμεῖν ἑτοίμως ἔχειν. τοῖς οὖν πρεσβευταῖς ἀποκρινάμενος λέγειν ἀπελθοῦσιν, ὅτι τοῖς τὸ πρῶτον ἀξιωθεῖσιν ὑπʼ αὐτοῦ καὶ νῦν ἐμμένει τῆς τῶν πολιτῶν ἀσφαλείας ἕνεκα πρὸς δὲ τὴν δευτέραν ἀξίωσιν οὐχ ὑπακούει, ἀπέλυσεν αὐτούς."},{"number":371,"text":"Ὁ δʼ Ἄδαδος ἀκούσας ταῦτα καὶ δυσχεράνας τρίτον ἔπεμψε πρὸς Ἄχαβον τοὺς πρέσβεις ἀπειλῶν ὑψηλότερον τῶν τειχῶν οἷς καταφρονεῖ χῶμα τούτοις ἐπεγείρειν αὐτοῦ τὴν στρατιὰν κατὰ δράκα λαμβάνουσαν, ἐμφανίζων αὐτῷ τῆς δυνάμεως τὸ πλῆθος καὶ καταπληττόμενος."},{"number":372,"text":"τοῦ δʼ Ἀχάβου μὴ καυχᾶσθαι δεῖν ἀποκριναμένου καθωπλισμένον ἀλλὰ τῇ μάχῃ κρείττω γενόμενον, ἐλθόντες οἱ πρέσβεις καὶ δειπνοῦντα καταλαβόντες τὸν βασιλέα μετὰ τριάκοντα καὶ δύο βασιλέων συμμάχων ἐδήλωσαν αὐτῷ τὴν ἀπόκρισιν· ὁ δʼ εὐθέως τοῦτο προσέταξε καὶ περιχαρακοῦν τὴν πόλιν καὶ χώματα βάλλεσθαι καὶ μηδένα τρόπον ἀπολιπεῖν πολιορκίας."},{"number":373,"text":"ἦν δʼ Ἄχαβος τούτων πραττομένων ἐν ἀγωνίᾳ δεινῇ σὺν παντὶ τῷ λαῷ· θαρρεῖ δὲ καὶ τῶν φόβων ἀπολύεται προφήτου τινὸς αὐτῷ προσελθόντος καὶ φήσαντος αὐτῷ τὸν θεὸν ὑπισχνεῖσθαι ποιήσειν τὰς τοσαύτας τῶν πολεμίων μυριάδας ὑποχειρίους."},{"number":374,"text":"πυθομένῳ δέ, διὰ τίνων ἂν ἡ νίκη γένοιτο, διὰ τῶν παίδων, εἶπε, τῶν ἡγεμόνων ἡγουμένου σοῦ διὰ τὴν ἀπειρίαν ἐκείνων. καλέσαντος δὲ τοὺς τῶν ἡγεμόνων υἱούς, εὑρέθησαν δʼ ὡς διακόσιοι καὶ τριακονταδύο, μαθὼν τὸν Σύρον πρὸς εὐωχίαν καὶ ἄνεσιν τετραμμένον ἀνοίξας τὰς πύλας ἐξέπεμψε τοὺς παῖδας."},{"number":375,"text":"τῶν δὲ σκοπῶν δηλωσάντων τοῦτο τῷ Ἀδάδῳ πέμπει τινὰς ὑπαντησομένους ἐντειλάμενος, ἂν μὲν εἰς μάχην ὦσι προεληλυθότες, ἵνα δήσαντες ἀγάγωσι πρὸς αὐτόν, ἂν δʼ εἰρηνικῶς, ὅπως ταὐτὸ ποιῶσιν."},{"number":376,"text":"εἶχε δʼ ἑτοίμην Ἄχαβος καὶ τὴν ἄλλην στρατιὰν ἐντὸς τῶν τειχῶν. οἱ δὲ τῶν ἀρχόντων παῖδες συμβαλόντες τοῖς φύλαξι πολλοὺς αὐτῶν ἀποκτείνουσι καὶ τοὺς ἄλλους ἄχρι τοῦ στρατοπέδου διώκουσιν. ἰδὼν δὲ τούτους νικῶντας ὁ βασιλεὺς ἐξαφίησι καὶ τὴν ἄλλην στρατιὰν ἅπασαν."},{"number":377,"text":"ἡ δʼ αἰφνιδίως ἐπιπεσοῦσα τοῖς Σύροις ἐκράτησεν αὐτῶν, οὐ γὰρ προσεδόκων αὐτοὺς ἐπεξελεύσεσθαι, καὶ διὰ τοῦτο γυμνοῖς καὶ μεθύουσι προσέβαλλον, ὥστε τὰς πανοπλίας ἐκ τῶν στρατοπέδων φεύγοντας καταλιπεῖν καὶ τὸν βασιλέα σωθῆναι μόλις ἐφʼ ἵππου ποιησάμενον τὴν φυγήν."},{"number":378,"text":"Ἄχαβος δὲ πολλὴν ὁδὸν διώκων τοὺς Σύρους ἤνυσεν ἀναιρῶν αὐτούς, διαρπάσας δὲ τὰ ἐν τῇ παρεμβολῇ, πλοῦτος δʼ ἦν οὐκ ὀλίγος, ἀλλὰ καὶ χρυσοῦ πλῆθος καὶ ἀργύρου τά τε ἅρματα τοῦ Ἀδάδου καὶ τοὺς ἵππους λαβὼν ἀνέστρεψεν εἰς τὴν πόλιν. τοῦ δὲ προφήτου παρασκευάζεσθαι φήσαντος καὶ τὴν δύναμιν ἑτοίμην ἔχειν, ὡς τῷ ἐπιόντι πάλιν ἔτει στρατεύσοντος ἐπʼ αὐτὸν τοῦ Σύρου, ὁ μὲν Ἄχαβος πρὸς τούτοις ἦν."},{"number":379,"text":"Ὁ δὲ Ἄδαδος διασωθεὶς ἐκ τῆς μάχης μεθʼ ὅσης ἠδυνήθη στρατιᾶς συνεβουλεύσατο τοῖς αὑτοῦ φίλοις, πῶς ἂν ἐπιστρατεύσηται τοῖς Ἰσραηλίταις. οἱ δὲ ἐν μὲν τοῖς ὄρεσιν οὐκ ἐδίδοσαν γνώμην συμβαλεῖν αὐτοῖς· τὸν γὰρ θεὸν αὐτῶν ἐν τοῖς τοιούτοις δύνασθαι τόποις καὶ διὰ τοῦτο νῦν ὑπʼ αὐτῶν νενικῆσθαι· κρατήσειν δὲ ἔλεγον ἐν πεδίῳ ποιησαμένους τὴν μάχην."},{"number":380,"text":"συνεβούλευον δὲ πρὸς τούτῳ τοὺς μὲν βασιλέας οὓς ἐπηγάγετο συμμάχους ἀπολῦσαι πρὸς τὰ οἰκεῖα, τὴν δὲ στρατιὰν αὐτῶν κατασχεῖν ἀντʼ ἐκείνων σατράπας καταστήσαντα· εἰς δὲ τὴν τῶν ἀπολωλότων τάξιν στρατολογῆσαι δύναμιν ἐκ τῆς χώρας τῆς αὐτῶν καὶ ἵππους καὶ ἅρματα. δοκιμάσας οὖν ταῦτα εἰρῆσθαι καλῶς οὕτως διεκόσμησε τὴν δύναμιν."},{"number":381,"text":"Ἀρξαμένου δὲ ἔαρος ἀναλαβὼν τὴν στρατιὰν ἦγεν ἐπὶ τοὺς Ἑβραίους, καὶ γενόμενος πρὸς πόλει τινί, Ἀφεκὰ δʼ αὐτὴν καλοῦσιν, ἐν μεγάλῳ στρατοπεδεύεται πεδίῳ. Ἄχαβος δʼ ἀπαντήσας αὐτῷ μετὰ τῆς δυνάμεως ἀντεστρατοπεδεύσατο· σφόδρα δʼ ἦν ὀλίγον αὐτοῦ τὸ στράτευμα πρὸς τοὺς πολεμίους ἀντιπαραβαλλόμενον."},{"number":382,"text":"τοῦ δὲ προφήτου προσελθόντος αὐτῷ πάλιν καὶ νίκην τὸν θεὸν αὐτῷ διδόναι φήσαντος, ἵνα τὴν ἰδίαν ἰσχὺν ἐπιδείξηται μὴ μόνον ἐν τοῖς ὄρεσιν ἀλλὰ κἀν τοῖς πεδίοις ὑπάρχουσαν, ὅπερ οὐκ εἶναι δοκεῖ τοῖς Σύροις, ἑπτὰ μὲν ἡμέρας ἀντεστρατοπεδευκότες ἡσύχαζον, τῇ δὲ ὑστάτῃ τούτων ὑπὸ τὸν ὄρθρον προελθόντων ἐκ τοῦ στρατοπέδου τῶν πολεμίων καὶ παραταξαμένων εἰς μάχην ἀντεπεξῆγε καὶ Ἄχαβος τὴν οἰκείαν δύναμιν."},{"number":383,"text":"καὶ συμβαλὼν καρτερᾶς τῆς μάχης γενομένης τρέπεται τοὺς πολεμίους εἰς φυγὴν καὶ διώκων ἐπέκειτο. οἱ δὲ καὶ ὑπὸ τῶν ἁρμάτων καὶ ὑπʼ ἀλλήλων ἀπώλοντο, ἴσχυσαν δʼ ὀλίγοι διαφυγεῖν εἰς τὴν Ἀφεκὰ πόλιν αὐτῶν."},{"number":384,"text":"ἀπέθανον δὲ καὶ αὐτοὶ τῶν τειχῶν αὐτοῖς ἐπιπεσόντων ὄντες δισμύριοι ἑπτακισχίλιοι. διεφθάρησαν δʼ ἐν ἐκείνῃ τῇ μάχῃ ἄλλαι μυριάδες δέκα. ὁ δὲ βασιλεὺς τῶν Σύρων Ἄδαδος φεύγων μετά τινων πιστοτάτων οἰκετῶν εἰς ὑπόγειον οἶκον ἐκρύβη."},{"number":385,"text":"τούτων φιλανθρώπους καὶ ἐλεήμονας εἶναι φησάντων τοὺς τῶν Ἰσραηλιτῶν βασιλέας καὶ δυνήσεσθαι τῷ συνήθει τρόπῳ τῆς ἱκετείας χρησαμένους τὴν σωτηρίαν αὐτῷ παρʼ Ἀχάβου λαβεῖν, εἰ συγχωρήσειεν αὐτοῖς πρὸς αὐτὸν ἀπελθεῖν, ἀφῆκεν· οἱ δὲ σάκκους ἐνδυσάμενοι καὶ σχοινία ταῖς κεφαλαῖς περιθέμενοι, οὕτως γὰρ τὸ παλαιὸν ἱκέτευον οἱ Σύροι, πρὸς Ἄχαβον παρεγένοντο καὶ δεῖσθαι τὸν Ἄδαδον σώζειν αὐτὸν ἔλεγον εἰς ἀεὶ δοῦλον αὐτοῦ τῆς χάριτος γενησόμενον."},{"number":386,"text":"ὁ δὲ συνήδεσθαι φήσας αὐτῷ περιόντι καὶ μηδὲν ἐν τῇ μάχῃ πεπονθότι τιμὴν καὶ εὔνοιαν, ἣν ἄν τις ἀδελφῷ παράσχοι, κατεπηγγείλατο. λαβόντες δὲ ὅρκους παρʼ αὐτοῦ μηδὲν ἀδικήσειν φανέντα προάγουσι πορευθέντες ἐκ τοῦ οἴκου ἐν ᾧ κέκρυπτο καὶ προσάγουσι τῷ Ἀχάβῳ ἐφʼ ἅρματος καθεζομένῳ· ὁ δὲ προσεκύνησεν αὐτόν."},{"number":387,"text":"Ἄχαβος δʼ ἐπιδοὺς αὐτῷ τὴν δεξιὰν ἀναβιβάζει ἐπὶ τὸ ἅρμα καὶ καταφιλήσας θαρρεῖν ἐκέλευε καὶ μηδὲν τῶν ἀτόπων προσδοκᾶν, Ἄδαδος δʼ εὐχαρίστει καὶ παρʼ ὅλον τὸν τοῦ ζῆν χρόνον ἀπομνημονεύσειν τῆς εὐεργεσίας ὡμολόγει καὶ τὰς πόλεις τῶν Ἰσραηλιτῶν, ἃς ἀπήνεγκαν οἱ πρὸ αὐτοῦ βασιλεῖς, ἀποδώσειν ἐπηγγείλατο καὶ Δαμασκὸν ὥστε ἐξελαύνειν εἰς αὐτήν, καθὼς καὶ οἱ πατέρες αὐτοῦ εἰς Σαμάρειαν εἶχον τοῦτο ποιεῖν, ἀνήσειν."},{"number":388,"text":"γενομένων δʼ αὐτοῖς ὅρκων καὶ συνθηκῶν πολλὰ δωρησάμενος αὐτῷ Ἄχαβος ἀπέπεμψεν εἰς τὴν ἰδίαν βασιλείαν. καὶ τὰ μὲν περὶ τῆς Ἀδάδου τοῦ Σύρων βασιλέως στρατείας ἐπὶ Ἄχαβον καὶ τοὺς Ἰσραηλίτας τοιοῦτον ἔσχε τὸ τέλος."},{"number":389,"text":"Προφήτης δέ τις τοὔνομα Μιχαίας προσελθών τινι τῶν Ἰσραηλιτῶν ἐκέλευεν αὐτὸν εἰς τὴν κεφαλὴν πλῆξαι· τοῦτο γὰρ ποιήσειν κατὰ βούλησιν τοῦ θεοῦ. τοῦ δὲ μὴ πεισθέντος προεῖπε παρακούσαντα τῶν τοῦ θεοῦ προσταγμάτων λέοντι περιτυχόντα διαφθαρήσεσθαι. συμβάντος τούτου τἀνθρώπῳ πρόσεισιν ἑτέρῳ πάλιν ὁ προφήτης ταὐτὸ προστάσσων."},{"number":390,"text":"πλήξαντος δʼ ἐκείνου καὶ θραύσαντος αὐτοῦ τὸ κρανίον καταδησάμενος τὴν κεφαλὴν προσῆλθε τῷ βασιλεῖ λέγων αὐτῷ συνεστρατεῦσθαι καὶ παραλαβεῖν ἐπὶ φυλακῇ τινα τῶν αἰχμαλώτων παρὰ τοῦ ταξιάρχου, φυγόντος δʼ αὐτοῦ κινδυνεύειν ὑπὸ τοῦ παραδεδωκότος ἀποθανεῖν· ἀπειλῆσαι γὰρ αὐτὸν εἰ διαφύγοι ὁ αἰχμάλωτος ἀποκτείνειν."},{"number":391,"text":"δίκαιον δὲ φήσαντος Ἀχάβου τὸν θάνατον εἶναι λύσας τὴν κεφαλὴν ἐπιγινώσκεται ὑπʼ αὐτοῦ Μιχαίας ὁ προφήτης ὤν. ἐκέχρητο δὲ σοφίσματι πρὸς αὐτὸν τῷ γενομένῳ πρὸς τοὺς μέλλοντας λόγους·"},{"number":392,"text":"εἶπε γάρ, ὡς ὁ θεὸς ἀφέντʼ αὐτὸν διαδράναι τὴν τιμωρίαν Ἄδαδον τὸν βλασφημήσαντα εἰς αὐτὸν μετελεύσεται καὶ ποιήσει σεαυτὸν μὲν ἀποθανεῖν ὑπʼ ἐκείνου, τὸν δὲ λαὸν ὑπὸ τῆς στρατιᾶς αὐτοῦ. παροξυνθεὶς δʼ Ἄχαβος πρὸς τὸν προφήτην τὸν μὲν ἐγκλεισθέντα φυλάττεσθαι ἐκέλευσε, συγκεχυμένος δʼ αὐτὸς ἐπὶ τοῖς Μιχαίου λόγοις ἀνεχώρησεν εἰς τὴν οἰκείαν."}],"15":[{"number":393,"text":"Καὶ Ἄχαβος μὲν ἐν τούτοις ἦν· ἐπάνειμι δὲ ἐπὶ τὸν Ἱεροσολύμων βασιλέα Ἰωσάφατον, ὃς αὐξήσας τὴν βασιλείαν καὶ δυνάμεις ἐν ταῖς πόλεσι ταῖς ἐν τῇ τῶν ὑπηκόων χώρᾳ καταστήσας οὐδὲν ἧττον Ἀβία τοῦ πάππου καταληφθείσης τῆς Ἐφράμου κληρουχίας Ἱεροβάμου βασιλεύοντος τῶν δέκα φυλῶν φρουρὰς ἐγκαθίδρυσεν."},{"number":394,"text":"ἀλλʼ εἶχεν εὐμενές τε καὶ συνεργὸν τὸ θεῖον δίκαιος ὢν καὶ εὐσεβὴς καὶ τί καθʼ ἑκάστην ἡμέραν ἡδὺ ποιήσει καὶ προσηνὲς τῷ θεῷ ζητῶν. ἐτίμων δʼ αὐτὸν οἱ πέριξ βασιλικαῖς δωρεαῖς, ὡς πλοῦτόν τε ποιῆσαι βαθύτατον καὶ δόξαν ἄρασθαι μεγίστην."},{"number":395,"text":"Τρίτῳ δʼ ἔτει τῆς βασιλείας συγκαλέσας τοὺς ἡγεμόνας τῆς χώρας καὶ τοὺς ἱερεῖς ἐκέλευε τὴν γῆν περιελθόντας ἅπαντα τὸν λαὸν τὸν ἐπʼ αὐτῇ διδάξαι κατὰ πόλιν τοὺς Μωσείους νόμους καὶ φυλάσσειν τούτους καὶ σπουδάζειν περὶ τὴν θρησκείαν τοῦ θεοῦ. καὶ ἥσθη πᾶν τὸ πλῆθος οὕτως, ὡς μηδὲν ἄλλο φιλοτιμεῖσθαι μηδὲ ἀγαπᾶν ὡς τὸ τηρεῖν τὰ νόμιμα."},{"number":396,"text":"οἵ τε προσχώριοι διετέλουν στέργοντες τὸν Ἰωσάφατον καὶ πρὸς αὐτὸν εἰρήνην ἄγοντες· οἱ δὲ Παλαιστῖνοι τακτοὺς ἐτέλουν αὐτῷ φόρους καὶ Ἄραβες ἐχορήγουν κατʼ ἔτος ἄρνας ἑξήκοντα καὶ τριακοσίους καὶ ἐρίφους τοσούτους. πόλεις τε μεγάλας ὠχύρωσεν ἄλλας τε καὶ βαρεῖς, καὶ δύναμιν στρατιωτικὴν πρὸς πολέμους ηὐτρέπιστο."},{"number":397,"text":"ἦν δὲ ἐκ μὲν τῆς Ἰούδα φυλῆς στρατὸς ὁπλιτῶν μυριάδες τριάκοντα, ὧν Ἐδναῖος τὴν ἡγεμονίαν εἶχεν, Ἰωάννης δὲ μυριάδων εἴκοσι. ὁ δʼ αὐτὸς οὗτος ἡγεμὼν κἀκ τῆς Βενιαμίτιδος φυλῆς εἶχε τοξοτῶν πεζῶν μυριάδας εἴκοσι, ἄλλος δʼ ἡγεμὼν ᾧ Χάβαθος ὄνομα μυριάδας ὁπλιτῶν ὀκτωκαίδεκα τὸ πλῆθος τῷ βασιλεῖ προσένειμε, πάρεξ ὧν εἰς τὰς ὀχυρωτάτας διέπεμψε πόλεις."},{"number":398,"text":"Ἠγάγετο δὲ τῷ παιδὶ Ἰωράμῳ τὴν Ἀχάβου θυγατέρα τοῦ τῶν δέκα φυλῶν βασιλέως Ὀθλίαν ὄνομα. πορευθέντα δʼ αὐτὸν μετὰ χρόνον τινὰ εἰς Σαμάρειαν φιλοφρόνως Ἄχαβος ὑπεδέξατο καὶ τὸν ἀκολουθήσαντα στρατὸν ἐξένισε λαμπρῶς σίτου τε καὶ οἴνου καὶ θυμάτων ἀφθονίᾳ, παρεκάλεσέ τε συμμαχῆσαι κατὰ τοῦ Σύρων βασιλέως, ἵνα τὴν ἐν τῇ Γαλαδηνῇ πόλιν Ἀραμαθὰν ἀφέληται·"},{"number":399,"text":"τοῦ γὰρ πατρὸς αὐτὴν τοῦ αὐτοῦ πρῶτον τυγχάνουσαν ἀφῃρῆσθαι τὸν ἐκείνου πατέρα. τοῦ δὲ Ἰωσαφάτου τὴν βοήθειαν ἐπαγγειλαμένου, καὶ γὰρ εἶναι δύναμιν αὐτῷ μὴ ἐλάττω τῆς ἐκείνου, καὶ μεταπεμψαμένου τὴν δύναμιν ἐξ Ἱεροσολύμων εἰς Σαμάρειαν, προεξελθόντες ἔξω τῆς πόλεως οἱ δύο βασιλεῖς καθίσαντες ἐπὶ τοῦ ἰδίου θρόνου ἑκάτερος τοῖς οἰκείοις στρατιώταις τὸ στρατιωτικὸν διένεμον."},{"number":400,"text":"Ἰωσαφάτης δʼ ἐκέλευσεν εἴ τινές εἰσι προφῆται καλέσαντʼ αὐτοὺς ἀνακρῖναι περὶ τῆς ἐπὶ τὸν Σύρον ἐξόδου, εἰ συμβουλεύουσι κατʼ ἐκεῖνον τὸν καιρὸν αὐτῷ ποιήσασθαι τὴν στρατείαν· καὶ γὰρ εἰρήνη τε καὶ φιλία τότε τῷ Ἀχάβῳ πρὸς τὸν Σύρον ὑπῆρχεν ἐπὶ τρία ἔτη διαμείνασα, ἀφʼ οὗ λαβὼν αὐτὸν αἰχμάλωτον ἀπέλυσεν ἄχρις ἐκείνης τῆς ἡμέρας."},{"number":401,"text":"Καλέσας δὲ Ἄχαβος τοὺς αὑτοῦ προφήτας ὡσεὶ τετρακοσίους τὸν ἀριθμὸν ὄντας ἐκέλευσεν ἔρεσθαι τοῦ θεοῦ, εἰ δίδωσιν αὐτῷ στρατευσαμένῳ ἐπὶ Ἄδερα νίκην καὶ καθαίρεσιν τῆς πόλεως, διʼ ἣν ἐκφέρειν μέλλει τὸν πόλεμον."},{"number":402,"text":"τῶν δὲ προφητῶν συμβουλευσάντων ἐκστρατεῦσαι, κρατήσειν γὰρ τοῦ Σύρου καὶ λήψεσθαι ὑποχείριον αὐτὸν ὡς καὶ τὸ πρῶτον, συνεὶς ἐκ τῶν λόγων Ἰωσάφατος, ὅτι ψευδοπροφῆται τυγχάνουσιν, ἐπύθετο τοῦ Ἀχάβου εἰ καὶ ἕτερός τίς ἐστι προφήτης τοῦ θεοῦ, ἵνα ἀκριβέστερον μάθωμεν περὶ τῶν μελλόντων. ὁ δʼ Ἄχαβος εἶναι μὲν ἔφη,"},{"number":403,"text":"μισεῖν δʼ αὐτὸν κακὰ προφητεύσαντα καὶ προειπόντα ὅτι τεθνήξεται νικηθεὶς ὑπὸ τοῦ Σύρου, ἐν φρουρᾷ δὲ νῦν αὐτὸν ἔχειν· καλεῖσθαι δὲ Μιχαίαν, υἱὸν δʼ εἶναι Ὀμβλαίου· τοῦ δʼ Ἰωσαφάτου κελεύσαντος αὐτὸν προαχθῆναι πέμψας εὐνοῦχον ἄγει τὸν Μιχαίαν."},{"number":404,"text":"κατὰ δὲ τὴν ὁδὸν ἐδήλωσεν αὐτῷ ὁ εὐνοῦχος πάντας τοὺς ἄλλους προφήτας νίκην τῷ βασιλεῖ προειρηκέναι. ὁ δὲ οὐκ ἐξὸν αὐτῷ καταψεύσασθαι τοῦ θεοῖ φήσας, ἀλλʼ ἐρεῖν ὅτι ἂν αὐτῷ περὶ τοῦ βασιλέως αὐτὸς εἴπῃ, ὡς ἧκε πρὸς τὸν Ἄχαβον καὶ λέγειν αὐτῷ τἀληθὲς οὗτος ἐνωρκίσατο, δεῖξαι τὸν θεὸν αὐτῷ φεύγοντας τοὺς Ἰσραηλίτας ἔφη καὶ διωκομένους ὑπὸ τῶν Σύρων καὶ διασκορπιζομένους ὑπʼ αὐτῶν εἰς τὰ ὄρη, καθάπερ ποιμένων ἠρημωμένα ποίμνια."},{"number":405,"text":"ἔλεγε δὲ σημαίνειν τοὺς μὲν μετʼ εἰρήνης ἀναστρέψειν εἰς τὰ ἴδια, πεσεῖσθαι δʼ αὐτὸν μόνον ἐν τῇ μάχῃ. ταῦτα φήσαντος τοῦ Μιχαία πρὸς Ἰωσάφατον ὁ Ἄχαβος ἀλλʼ ἔγωγε μικρὸν ἔμπροσθεν ἐδήλωσά σοι τὴν τἀνθρώπου πρός με διάθεσιν, καὶ ὅτι μοι τὰ χείρω προεφήτευσε. τοῦ δὲ Μιχαία εἰπόντος,"},{"number":406,"text":"ὡς προσῆκεν αὐτῷ πάντων ἀκροᾶσθαι τῶν ὑπὸ τοῦ θεοῦ προλεγομένων, καὶ ὡς παρορμῶσιν αὐτὸν οἱ ψευδοπροφῆται ποιήσασθαι τὸν πόλεμον ἐλπίδι νίκης, καὶ ὅτι δεῖ πεσεῖν αὐτὸν μαχόμενον, αὐτὸς μὲν ἦν ἐπʼ ἐννοίᾳ, Σεδεκίας δέ τις τῶν ψευδοπροφητῶν προσελθὼν Μιχαίᾳ μὲν μὴ προσέχειν παρῄνει·"},{"number":407,"text":"λέγειν γὰρ αὐτὸν οὐδὲν ἀληθές· τεκμηρίῳ δὲ ἐχρήσατο οἷς Ἠλίας προεφήτευσεν ὁ τούτου κρείττων τὰ μέλλοντα συνιδεῖν· καὶ γὰρ τοῦτον ἔλεγε προφητεύσαντα ἐν Ἱεζερήλα πόλει ἐν τῷ Ναβώθου ἀγρῷ τὸ αἷμα αὐτοῦ κύνας ἀναλιχμήσεσθαι προειπεῖν, καθὼς καὶ Ναβώθου τοῦ διʼ αὐτὸν καταλευσθέντος ὑπὸ τοῦ ὄχλου."},{"number":408,"text":"δῆλον οὖν, ὅτι οὗτος ψεύδεται τῷ κρείττονι προφήτῃ τἀναντία λέγων ἀπὸ ἡμερῶν τριῶν φάσκων τεθνήξεσθαι. γνώσεσθε δʼ εἴπερ ἐστὶν ἀληθὴς καὶ τοῦ θείου πνεύματος ἔχει τὴν δύναμιν· εὐθὺς γὰρ ῥαπισθεὶς ὑπʼ ἐμοῦ βλαψάτω μου τὴν χεῖρα, ὥσπερ Ἰάδαος τὴν Ἱεροβοάμου τοῦ βασιλέως συλλαβεῖν θελήσαντος ἀπεξήρανε δεξιάν·"},{"number":409,"text":"ἀκήκοας γὰρ οἶμαι τοῦτο πάντως γενόμενον. ὡς οὖν πλήξαντος αὐτοῦ τὸν Μιχαίαν μηδὲν συνέβη παθεῖν, Ἄχαβος θαρρήσας ἄγειν τὴν στρατιὰν πρόθυμος ἦν ἐπὶ τὸν Σύρον· ἐνίκα γὰρ οἶμαι τὸ χρεὼν καὶ πιθανωτέρους ἐποίει τοῦ ἀληθοῦς τοὺς ψευδοπροφήτας, ἵνα λάβῃ τὴν ἀφορμὴν τοῦ τέλους. Σεδεκίας σιδήρεα ποιήσας κέρατα λέγει πρὸς Ἄχαβον, ὡς θεὸν αὐτῷ σημαίνειν τούτοις ἅπασαν καταστρέψεσθαι τὴν Συρίαν."},{"number":410,"text":"Μιχαίαν δὲ μετʼ οὐ πολλὰς ἡμέρας εἰπόντα τὸν Σεδεκίαν ταμιεῖον ἐκ ταμιείου κρυβόμενον ἀμείψειν ζητοῦντα φυγεῖν τῆς ψευδολογίας τὴν δίκην, ἐκέλευσεν ὁ βασιλεὺς ἀπαχθέντα φυλάττεσθαι πρὸς Ἀχάμωνα τὸν τῆς πόλεως ἄρχοντα καὶ χορηγεῖσθαι μηδὲν ἄρτου καὶ ὕδατος αὐτῷ περισσότερον."},{"number":411,"text":"Καὶ Ἄχαβος μὲν καὶ Ἰωσάφατος ὁ τῶν Ἱεροσολύμων βασιλεὺς ἀναλαβόντες τὰς δυνάμεις ἤλασαν εἰς Ῥαμάθην πόλιν τῆς Γαλαδίτιδος. ὁ δὲ τῶν Σύρων βασιλεὺς ἀκούσας αὐτῶν τὴν στρατείαν ἀντεπήγαγεν αὐτοῖς τὴν αὑτοῦ στρατιὰν καὶ οὐκ ἄπωθεν τῆς Ἀραμάθης στρατοπεδεύεται."},{"number":412,"text":"συνέθεντο δὲ ὅ τε Ἄχαβος καὶ Ἰωσάφατος ἀποθέσθαι μὲν τὸν Ἄχαβον τὸ βασιλικὸν σχῆμα, τὸν δὲ τῶν Ἱεροσολύμων βασιλέα τὴν αὐτοῦ στολὴν ἔχοντα στῆναι ἐν τῇ παρατάξει, κατασοφιζόμενοι τὰ ὑπὸ τοῦ Μιχαία προειρημένα. εὗρε δʼ αὐτὸν τὸ χρεὼν καὶ δίχα τοῦ σχήματος·"},{"number":413,"text":"ὁ μὲν γὰρ Ἄδαδος ὁ τῶν Σύρων βασιλεὺς παρήγγειλε τῇ στρατιᾷ διὰ τῶν ἡγεμόνων μηδένα τῶν ἄλλων ἀναιρεῖν, μόνον δὲ τὸν βασιλέα τῶν Ἰσραηλιτῶν. οἱ δὲ Σύροι τῆς συμβολῆς γενομένης ἰδόντες τὸν Ἰωσάφατον ἑστῶτα πρὸ τῆς τάξεως καὶ τοῦτον εἰκάσαντες εἶναι τὸν Ἄχαβον ὥρμησαν ἐπʼ αὐτὸν καὶ περικυκλωσάμενοι,"},{"number":414,"text":"ὡς ἐγγὺς ὄντες ἔγνωσαν οὐκ ὄντα τοῦτον, ἀνεχώρησαν ὀπίσω, ἀπό τε ἀρχομένης ἠοῦς ἄχρι δείλης μαχόμενοι καὶ νικῶντες ἀπέκτειναν οὐδένα κατὰ τὴν τοῦ βασιλέως ἐντολὴν ζητοῦντες τὸν Ἄχαβον ἀνελεῖν μόνον καὶ εὑρεῖν οὐ δυνάμενοι. παῖς δέ τις βασιλικὸς τοῦ Ἀδάδου Ἀμανὸς ὄνομα τοξεύσας εἰς τοὺς πολεμίους τιτρώσκει τὸν βασιλέα διὰ τοῦ θώρακος κατὰ τοῦ πνεύμονος."},{"number":415,"text":"Ἄχαβος δὲ τὸ μὲν συμβεβηκὸς οὐκ ἔγνω ποιῆσαι τῷ στρατεύματι φανερὸν μὴ τραπείησαν, τὸν δʼ ἡνίοχον ἐκέλευσεν ἐκτρέψαντα τὸ ἅρμα ἐξάγειν τῆς μάχης· χαλεπῶς γὰρ βεβλῆσθαι καὶ καιρίως. ὀδυνώμενος δὲ ἔστη ἐπὶ τοῦ ἅρματος ἄχρι δύνοντος ἡλίου καὶ λιφαιμήσας ἀπέθανε."},{"number":416,"text":"Καὶ τὸ μὲν τῶν Σύρων στράτευμα νυκτὸς ἤδη γενομένης ἀνεχώρησεν εἰς τὴν παρεμβολήν, καὶ δηλώσαντος τοῦ στρατοκήρυκος ὅτι τέθνηκεν Ἄχαβος ἀνέζευξαν εἰς τὰ ἴδια, κομίσαντες δὲ τὸν Ἀχάβου νεκρὸν εἰς Σαμάρειαν ἐκεῖ θάπτουσι."},{"number":417,"text":"καὶ τὸ ἅρμα ἀποπλύναντες ἐν τῇ Ἱεζερήλα κρήνῃ καθῃμαγμένον τῷ τοῦ βασιλέως φόνῳ ἀληθῆ τὴν Ἠλία προφητείαν ἐπέγνωσαν· οἱ μὲν γὰρ κύνες ἀνελιχμήσαντο τὸ αἷμα, αἱ δὲ ἑταιριζόμεναι ἐν τῇ κρήνῃ τὸ λοιπὸν λουόμεναι τούτῳ διετέλουν. ἀπέθανε δʼ ἐν Ἀραμάθῃ, Μιχαία τοῦτο προειπόντος."},{"number":418,"text":"συμβάντων οὖν Ἀχάβῳ τῶν ὑπὸ τῶν δύο προφητῶν εἰρημένων μέγα τὸ θεῖον ἡγεῖσθαι καὶ σέβειν καὶ τιμᾶν αὐτὸ πανταχοῦ, καὶ τῆς ἀληθείας μὴ τὰ πρὸς ἡδονὴν καὶ βούλησιν πιθανώτερα δοκεῖν, ὑπολαμβάνειν δʼ ὅτι προφητείας καὶ τῆς διὰ τῶν τοιούτων προγνώσεως οὐδέν ἐστι συμφορώτερον παρέχοντος οὕτω τοῦ θεοῦ τί δεῖ φυλάξασθαι,"},{"number":419,"text":"λογίζεσθαί τε πάλιν ἐκ τῶν περὶ τὸν βασιλέα γεγενημένων στοχαζομένους προσῆκε τὴν τοῦ χρεὼν ἰσχύν, ὅτι μηδὲ προγινωσκόμενον αὐτὸ διαφυγεῖν ἔστιν, ἀλλʼ ὑπέρχεται τὰς ἀνθρωπίνας ψυχὰς ἐλπίσι κολακεῦον χρησταῖς, αἷς εἰς τὸ πόθεν αὐτῶν κρατήσει περιάγει."},{"number":420,"text":"φαίνεται οὖν καὶ Ἄχαβος ὑπὸ τούτου τὴν διάνοιαν ἀπατηθείς, ὥστε ἀπιστῆσαι μὲν τοῖς προλέγουσι τὴν ἧτταν, τοῖς δὲ πρὸς χάριν προφητεύσασι πεισθεὶς ἀποθανεῖν. τοῦτον μὲν οὖν ὁ παῖς Ὀχοζίας διεδέξατο."}]},"count":420};})();
